window.CM=window.CM||{};CM.parts={"1": "General & Behavioral", "2": "Biostatistics & Research", "3": "Communication & Health Education", "4": "Environmental Health", "5": "School & Occupational Health", "6": "National & International Health", "7": "Arthropods, Disinfection & Immunity", "8": "Demography, MCH & Family Planning", "9": "Food & Nutrition", "10": "Accidents, Disasters & Epidemiology", "11": "Communicable Diseases, NCDs & Health Administration"};
CM.du=[{"id":"DU.1","n":1,"part":1,"topic":"Introduction to Community Medicine","stars":3,"years":["13Ju","05S"],"colleges":"MMC (1st Supp A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define community medicine.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Community medicine</strong> is the branch of medicine that studies health and disease in the population of a defined community or group. Its goal is to find the health problems and needs of that population (<strong>community diagnosis</strong>) and to plan, carry out and evaluate health measures that meet those needs (<strong>community treatment</strong>) (Faculty of Community Medicine, Royal Colleges of Physicians, UK, 1972).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.2","n":2,"part":1,"topic":"Introduction to Community Medicine","stars":3,"years":["22Nov","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist the aims / mention three objectives of community medicine.</p>","a":"<p><strong>Aim</strong></p>\n<p>Highest attainable level of health for the whole community (<strong>Health for All</strong>), with equity, through promotive, preventive, curative and rehabilitative services.</p>\n<p><strong>Objectives</strong></p>\n<ol>\n<li><strong>Health promotion</strong>: health education, nutrition, healthy lifestyle, sanitation.</li>\n<li><strong>Prevention of disease</strong>: specific protection (immunisation, chemoprophylaxis); primordial to tertiary levels.</li>\n<li><strong>Early diagnosis and treatment</strong>: screening, case finding, surveillance.</li>\n<li><strong>Disability limitation and rehabilitation</strong>.</li>\n<li><strong>Community diagnosis</strong>: size, distribution and determinants of health problems (epidemiology, biostatistics).</li>\n<li><strong>Community treatment</strong>: plan, implement and evaluate health services and national programmes.</li>\n<li><strong>Care of vulnerable groups</strong>: mothers, under-fives, school children, adolescents, workers, elderly, disabled.</li>\n<li><strong>Control of communicable and non-communicable diseases</strong>; epidemic and disaster management.</li>\n<li><strong>Healthy environment</strong>: safe water, sanitation, housing, safe workplaces.</li>\n<li><strong>Health management</strong>: efficient use of resources, intersectoral coordination, community participation.</li>\n<li><strong>Research</strong>: causes, risk factors, effective and affordable interventions.</li>\n<li><strong>Training</strong> of a community-oriented health team.</li>\n</ol>\n<p><strong>Educational objective (MBBS)</strong></p>\n<p>Produce a <strong>community-oriented doctor</strong> who can diagnose community problems, run national programmes and lead the health team at primary level (Upazila and below).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.3","n":3,"part":1,"topic":"Introduction to Community Medicine","stars":3,"years":["24Nov","16Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the differences between community medicine and clinical medicine?</p>","a":"<p><strong>Differences between community medicine and clinical medicine</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Community medicine</th>\n<th>Clinical medicine</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Unit of concern</td>\n<td>Community / population group</td>\n<td>Individual patient</td>\n</tr>\n<tr>\n<td>Main focus</td>\n<td>Health promotion and disease prevention</td>\n<td>Diagnosis and cure of disease</td>\n</tr>\n<tr>\n<td>Approach</td>\n<td>Active: seeks out healthy and sick</td>\n<td>Passive: waits for the patient</td>\n</tr>\n<tr>\n<td>Diagnosis</td>\n<td><strong>Community diagnosis</strong></td>\n<td><strong>Clinical diagnosis</strong></td>\n</tr>\n<tr>\n<td>Basis of diagnosis</td>\n<td>Rates, ratios, surveys, surveillance data</td>\n<td>History, examination, laboratory tests</td>\n</tr>\n<tr>\n<td>Tools</td>\n<td>Epidemiology, biostatistics, social sciences</td>\n<td>Clinical methods, diagnostic tests</td>\n</tr>\n<tr>\n<td>Treatment</td>\n<td><strong>Community treatment</strong>: health programmes, health education, environmental measures</td>\n<td>Drugs, surgery, nursing care</td>\n</tr>\n<tr>\n<td>Evaluation</td>\n<td>Change in health indicators (incidence, IMR, coverage)</td>\n<td>Cure, recovery, relief of symptoms</td>\n</tr>\n<tr>\n<td>Concept of health</td>\n<td>Holistic, ecological</td>\n<td>Mainly biomedical</td>\n</tr>\n<tr>\n<td>Setting</td>\n<td>Home, school, workplace, field, health centres</td>\n<td>Hospital, clinic</td>\n</tr>\n<tr>\n<td>Personnel</td>\n<td>Health team, community, other sectors</td>\n<td>Doctor, nurse, specialists</td>\n</tr>\n<tr>\n<td>Responsibility</td>\n<td>Whole population, including the unaffected</td>\n<td>Patients under care</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Measles vaccination campaign lowers incidence</td>\n<td>Treatment of measles pneumonia in hospital</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.4","n":4,"part":1,"topic":"Introduction to Community Medicine","stars":0,"years":[],"colleges":"MMC (2nd Term A5)","asked":"","note":"","kind":"","sub":"","q":"<p>State the role of doctors in society.</p>","a":"<p><strong>A. WHO &quot;Five-star doctor&quot; (C. Boelen, WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Role</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Care provider</td>\n<td>High-quality, continuous, comprehensive care of the patient as a whole person in family and community</td>\n</tr>\n<tr>\n<td>2. Decision-maker</td>\n<td>Chooses evidence-based, cost-effective technologies and treatments</td>\n</tr>\n<tr>\n<td>3. Communicator</td>\n<td>Promotes healthy lifestyles by explanation and advice; empowers people</td>\n</tr>\n<tr>\n<td>4. Community leader</td>\n<td>Wins community trust; balances individual and community needs; starts action</td>\n</tr>\n<tr>\n<td>5. Manager</td>\n<td>Works with the health team and other sectors; uses health data for decisions</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Other roles</strong></p>\n<ol>\n<li><strong>Health educator and promoter</strong>: counselling on diet, tobacco, family planning, hygiene.</li>\n<li><strong>Preventive role</strong>: immunisation, ANC, screening, early detection.</li>\n<li><strong>Public health role</strong>: surveillance, <strong>notification</strong> of diseases, outbreak investigation, disaster response.</li>\n<li><strong>Programme implementer</strong>: EPI, TB, malaria, family planning, NCD control.</li>\n<li><strong>Team leader and trainer</strong>: supervises nurses, health assistants, CHCPs.</li>\n<li><strong>Researcher</strong>: collects data, evaluates services, practises evidence-based medicine.</li>\n<li><strong>Medicolegal role</strong>: birth, death and fitness certificates; injury reports; court evidence.</li>\n<li><strong>Advocate</strong>: for the poor and vulnerable and for healthy public policy.</li>\n<li><strong>Ethical role</strong>: confidentiality, informed consent, equity, rational prescribing.</li>\n<li><strong>Social role</strong>: counsellor, role model, link between people and the health system; intersectoral coordination.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine); WHO, The five-star doctor (Boelen C).</p>"},{"id":"DU.5","n":5,"part":1,"topic":"Introduction to Community Medicine","stars":2,"years":[],"colleges":"MMC (2nd Term A5); MuMC (2nd Final B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Write the qualities of a good doctor. / Describe the deeper insight into the qualities of a good doctor.</p>","a":"<p><strong>A. Professional qualities</strong></p>\n<ol>\n<li>Sound, up-to-date <strong>knowledge</strong>; lifelong learning (CME/CPD).</li>\n<li>Clinical <strong>competence</strong>: history, examination, diagnosis, procedures.</li>\n<li>Sound <strong>judgement</strong>; evidence-based, rational decisions.</li>\n<li>Good <strong>communication</strong>: listens, explains in the patient's language, breaks bad news gently.</li>\n<li>Record keeping, time management, teamwork, leadership.</li>\n</ol>\n<p><strong>B. Personal qualities</strong></p>\n<ol>\n<li><strong>Compassion and empathy</strong>; kindness, patience, courtesy.</li>\n<li><strong>Integrity and honesty</strong>; humility; knows own limits and refers.</li>\n<li>Punctuality, discipline, neat appearance, emotional stability.</li>\n<li>Physical and mental fitness; self-care.</li>\n</ol>\n<p><strong>C. Ethical qualities (four principles)</strong></p>\n<ol>\n<li><strong>Autonomy</strong>: informed consent; respect for choices.</li>\n<li><strong>Beneficence</strong>: acts in the patient's best interest.</li>\n<li><strong>Non-maleficence</strong>: first, do no harm.</li>\n<li><strong>Justice</strong>: equal care regardless of wealth, religion, sex or politics.<br />\nPlus <strong>confidentiality</strong>, truthfulness, no exploitation, no conflict of interest.</li>\n</ol>\n<p><strong>D. Social / community qualities</strong></p>\n<ol>\n<li>Preventive outlook; health educator.</li>\n<li><strong>Social accountability</strong>; serves the poor and rural people.</li>\n<li>Respect for local culture and beliefs.</li>\n</ol>\n<p><strong>Deeper insight</strong></p>\n<ul>\n<li>Treats the <strong>person, not just the disease</strong> (holistic, psychosocial).</li>\n<li>Combines science (competence), art (empathy) and ethics (conscience).</li>\n<li>Is a <strong>five-star doctor</strong> (WHO): care provider, decision-maker, communicator, community leader, manager.</li>\n<li>Follows professional codes: Hippocratic Oath, WMA Declaration of Geneva (Physician's Pledge, 2017), BMDC Code of Professional Conduct, Etiquette and Ethics.</li>\n<li>Earns and keeps <strong>public trust</strong>, the basis of the doctor–patient relationship.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine); WMA Declaration of Geneva, 2017.</p>"},{"id":"DU.6","n":6,"part":1,"topic":"Introduction to Community Medicine","stars":0,"years":["25Nov"],"colleges":"MMC (2nd Term A5)","asked":"","note":"","kind":"","sub":"","q":"<p>Define integrity and accountability in medical practice.</p>","a":"<p><strong>Integrity</strong></p>\n<ul>\n<li><strong>Definition</strong>: steady adherence to moral and professional principles: honest, truthful and fair in every act, whether observed or not.</li>\n<li>In medical practice:\n<ol>\n<li>Honest history, notes, reports and certificates; no false certificates.</li>\n<li>Truthful disclosure of diagnosis, prognosis and <strong>errors</strong>.</li>\n<li>No fee-splitting, kickbacks or gifts from drug companies; declare <strong>conflicts of interest</strong>.</li>\n<li>Rational prescribing and investigations; no unnecessary procedures.</li>\n<li>Research integrity: no fabrication, falsification or plagiarism.</li>\n<li>Respect for confidentiality and consent.</li>\n<li>Work within competence; refer when needed.</li>\n</ol>\n</li>\n</ul>\n<p><strong>Accountability</strong></p>\n<ul>\n<li><strong>Definition</strong>: the duty of a doctor to answer for professional decisions and actions, accept responsibility for their outcome, and be open to review and sanction.</li>\n<li>Accountable to:</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th>To whom</th>\n<th>Mechanism</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Patient and family</td>\n<td>Informed consent, explanation, complaint handling</td>\n</tr>\n<tr>\n<td>Profession</td>\n<td>BMDC registration, code of conduct, disciplinary action, peer review</td>\n</tr>\n<tr>\n<td>Employer / institution</td>\n<td>Medical audit, clinical governance, service rules</td>\n</tr>\n<tr>\n<td>Society and law</td>\n<td>Courts, consumer protection, medicolegal duties, notification</td>\n</tr>\n<tr>\n<td>Self</td>\n<td>Conscience, reflection, continuing professional development</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine); BMDC Code of Professional Conduct, Etiquette and Ethics.</p>"},{"id":"DU.7","n":7,"part":1,"topic":"Public Health","stars":3,"years":["22Nov","21M"],"colleges":"MMC (1st Supp A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define public health.</p>","a":"<p><strong>Definitions</strong></p>\n<ol>\n<li><strong>Winslow (1920)</strong>: the science and art of preventing disease, prolonging life and promoting physical health and efficiency through organised community efforts for:\n<ul>\n<li>sanitation of the environment</li>\n<li>control of community infections</li>\n<li>education of the individual in personal hygiene</li>\n<li>organisation of medical and nursing services for early diagnosis and preventive treatment of disease</li>\n<li>development of social machinery that ensures every individual a standard of living adequate for health,<br />\nso that every citizen can realise his birthright of health and longevity.</li>\n</ul>\n</li>\n<li><strong>Acheson (UK, 1988; used by WHO)</strong>: &quot;the science and art of preventing disease, prolonging life and promoting health through the organized efforts of society.&quot;</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.8","n":8,"part":1,"topic":"Public Health","stars":3,"years":["22Nov","19M","16Ju"],"colleges":"MuMC (1st Final A5, 1st Supp A4)","asked":"","note":"","kind":"","sub":"","q":"<p>Briefly narrate the changing concepts of public health (including: narrate the 4th phase).</p>","a":"<p><strong>Phases (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Phase</th>\n<th>Period</th>\n<th>Main features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Disease control phase</td>\n<td>1880–1920</td>\n<td>Sanitary legislation; control of environment: water supply, sewage and refuse disposal, drainage, housing; quarantine; germ theory gave scientific basis</td>\n</tr>\n<tr>\n<td>2. Health promotional phase</td>\n<td>1920–1960</td>\n<td>Shift from environment to the <strong>individual</strong>; personal health services: MCH, school health, industrial health, mental health, health education; health centres, basic health services</td>\n</tr>\n<tr>\n<td>3. Social engineering phase</td>\n<td>1960–1980</td>\n<td>Rise of chronic diseases, accidents, drug and alcohol problems; <strong>social and behavioural</strong> causes recognised; social medicine, social welfare, care of &quot;at-risk&quot; groups</td>\n</tr>\n<tr>\n<td>4. Health for All phase</td>\n<td>1981–2000 AD</td>\n<td>Goal of <strong>HFA by 2000</strong>; <strong>PHC</strong> as key strategy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>4th phase: Health for All (details)</strong></p>\n<ol>\n<li>Recognition of a <strong>health gap</strong>: services concentrated in cities, hospitals and the well-off; rural poor uncovered.</li>\n<li><strong>WHA30.43 (1977)</strong>: main social target = a level of health permitting a socially and economically productive life by 2000.</li>\n<li><strong>Alma-Ata Declaration (1978)</strong>: <strong>primary health care</strong> as the key to HFA.</li>\n<li>Principles: <strong>equitable distribution, community participation, intersectoral coordination, appropriate technology</strong>.</li>\n<li>Shifts: curative → preventive/promotive; urban → rural; hospital → community; doctor-centred → team- and people-centred.</li>\n<li>Health as a <strong>fundamental human right</strong> and part of socio-economic development.</li>\n<li>Bangladesh: Upazila Health Complexes, union-level facilities, EPI (1979), ORS.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.9","n":9,"part":1,"topic":"Public Health","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss briefly the &quot;Disease Control Phase&quot; of public health.</p>","a":"<p><strong>Period</strong></p>\n<p>1880–1920; first phase of the changing concept of public health.</p>\n<p><strong>Background</strong></p>\n<ul>\n<li>Industrial Revolution (Europe) → rapid urbanisation, overcrowded slums, filth, polluted water.</li>\n<li>Repeated epidemics: cholera, typhoid, typhus, plague, smallpox; high death rates.</li>\n<li><strong>Sanitary awakening</strong>: Chadwick's report on the labouring population (1842) → <strong>Public Health Act 1848</strong> (England); John Snow's cholera study (1854).</li>\n<li><strong>Germ theory</strong> (Pasteur, Koch) gave a scientific basis to control.</li>\n</ul>\n<p><strong>Main features</strong></p>\n<ol>\n<li>Public health = <strong>sanitary legislation</strong> + <strong>environmental control</strong>.</li>\n<li>Measures:\n<ul>\n<li>Safe water supply</li>\n<li>Sewage, excreta and refuse disposal; drainage</li>\n<li>Housing and slum regulation; removal of nuisances</li>\n<li>Food hygiene and anti-adulteration laws</li>\n<li>Quarantine, isolation, disinfection, notification</li>\n<li>Vector control (malaria, yellow fever, plague)</li>\n<li>Smallpox vaccination</li>\n</ul>\n</li>\n<li>Run by local sanitary authorities and Medical Officers of Health; international sanitary conferences for quarantine.</li>\n</ol>\n<p><strong>Achievements</strong></p>\n<ol>\n<li>Cholera, typhoid and plague largely controlled in Europe and North America <strong>before</strong> antibiotics and most vaccines.</li>\n<li>Fall in death rates; rise in life expectancy.</li>\n<li>Legal and administrative foundation of modern public health.</li>\n</ol>\n<p><strong>Limitations</strong></p>\n<ol>\n<li>Focus on environment, not on <strong>man</strong> himself.</li>\n<li>No personal health services (MCH, school health).</li>\n<li>Health education neglected.</li>\n<li>Preventive and curative services separate.</li>\n<li>Social and non-communicable problems ignored.</li>\n</ol>\n<p>Disease control phase → <strong>Health promotional phase</strong> (1920–1960).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.10","n":10,"part":1,"topic":"Public Health","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the concept of health promotion in context of public health.</p>","a":"<p><strong>Definition</strong></p>\n<ul>\n<li><strong>Ottawa Charter (WHO, 1986)</strong>: &quot;Health promotion is the process of enabling people to increase control over, and to improve, their health.&quot;</li>\n<li>Park: first level of <strong>primary prevention</strong> (Leavell and Clark); not aimed at any one disease; strengthens the host by general measures.</li>\n</ul>\n<p><strong>Place in public health</strong></p>\n<p><strong>Health promotional phase (1920–1960)</strong>: focus moved from environment to the <strong>individual</strong>; personal health services (MCH, school, industrial and mental health), health education, health centres.</p>\n<p><strong>Approaches (Park)</strong></p>\n<ol>\n<li><strong>Health education</strong>: most cost-effective.</li>\n<li><strong>Environmental modifications</strong>: safe water, sanitation, housing, pollution control.</li>\n<li><strong>Nutritional interventions</strong>: fortification, supplementation, nutrition education.</li>\n<li><strong>Lifestyle and behavioural change</strong>: tobacco, alcohol, diet, exercise.</li>\n</ol>\n<p><strong>Ottawa Charter: five action areas</strong></p>\n<ol>\n<li>Build healthy public policy</li>\n<li>Create supportive environments</li>\n<li>Strengthen community action</li>\n<li>Develop personal skills</li>\n<li>Reorient health services</li>\n</ol>\n<p><strong>Basic strategies</strong>: Advocate, Enable, Mediate.<br />\n<strong>Prerequisites for health</strong>: peace, shelter, education, food, income, stable ecosystem, sustainable resources, social justice and equity.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine; Concept of Health and Disease); WHO, Ottawa Charter for Health Promotion, 1986.</p>"},{"id":"DU.11","n":11,"part":1,"topic":"Public Health","stars":0,"years":[],"colleges":"ShSMC (2nd Term A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the importance of the social uplift phase of public health.</p>","a":"<p><strong>Period</strong></p>\n<p>1960–1980; third phase (Park: <strong>social engineering phase</strong>).</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li>Broadened health beyond the biomedical → <strong>psychosocial and holistic</strong> concepts.</li>\n<li>Recognised poverty, illiteracy, unemployment and bad housing as <strong>causes of ill health</strong> → social determinants approach.</li>\n<li>Base for <strong>chronic disease epidemiology</strong> and lifestyle modification.</li>\n<li>Introduced <strong>social security and health insurance</strong> for workers, elderly and disabled.</li>\n<li>Emphasised <strong>equity</strong> and care of the vulnerable.</li>\n<li>Promoted <strong>community participation</strong> and <strong>intersectoral action</strong> (education, agriculture, housing).</li>\n<li>Linked health with socio-economic <strong>development</strong>.</li>\n<li>Led directly to the <strong>Health for All</strong> phase and <strong>PHC</strong> (Alma-Ata, 1978).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.12","n":12,"part":1,"topic":"Public Health","stars":0,"years":[],"colleges":"MuMC (1st Final A5, 1st Supp A4)","asked":"","note":"","kind":"","sub":"","q":"<p>What is the latest level (phase) of the changing concept of public health to achieve HFA with its health-related goal?</p>","a":"<p><strong>Latest phase (Park)</strong></p>\n<p><strong>Health for All phase (1981–2000 AD)</strong>: fourth phase of the changing concept of public health.</p>\n<p><strong>Background</strong></p>\n<ul>\n<li>Services reached mainly urban, rich and hospital users; rural poor left out (<strong>health gap</strong>).</li>\n<li>Health accepted as a human right and part of development.</li>\n</ul>\n<p><strong>Goal: Health for All by 2000 AD</strong></p>\n<ul>\n<li><strong>WHA30.43 (1977)</strong>: main social target of governments and WHO = attainment by all citizens of the world by 2000 of a level of health that permits a socially and economically productive life.</li>\n<li><strong>Alma-Ata Declaration (1978)</strong>: <strong>primary health care</strong> = key to HFA.</li>\n</ul>\n<p><strong>Features</strong></p>\n<ol>\n<li>Health as a <strong>fundamental human right</strong>.</li>\n<li>Shift: curative → preventive/promotive; hospital → community; urban → rural.</li>\n<li>PHC principles: <strong>equitable distribution, community participation, intersectoral coordination, appropriate technology</strong>.</li>\n<li>Eight essential elements of PHC (education, food and nutrition, water and sanitation, MCH and FP, immunisation, local endemic disease control, treatment of common diseases, essential drugs).</li>\n<li>Global indicators to monitor progress (e.g., IMR &lt;50/1000 LB, life expectancy &gt;60 years, adult literacy &gt;70%).</li>\n</ol>\n<p><strong>Health-related goals after 2000 (updated: UN/WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Framework</th>\n<th>Period</th>\n<th>Health-related goal</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>HFA policy for 21st century (WHA51.7)</td>\n<td>1998</td>\n<td>Renewed HFA</td>\n</tr>\n<tr>\n<td>MDGs</td>\n<td>2000–2015</td>\n<td>Goals 4, 5, 6 (+ targets 1C, 7C, 8E)</td>\n</tr>\n<tr>\n<td>SDGs</td>\n<td>2016–2030</td>\n<td><strong>SDG 3</strong>: healthy lives and well-being for all at all ages; target 3.8 <strong>UHC</strong></td>\n</tr>\n<tr>\n<td>Astana Declaration</td>\n<td>2018</td>\n<td>Renewed PHC as the route to UHC and the health SDGs</td>\n</tr>\n</tbody>\n</table>\n<p>Current form of HFA = <strong>UHC through PHC</strong> under <strong>SDG 3</strong> by 2030.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine; Health Care of the Community).</p>"},{"id":"DU.13","n":13,"part":1,"topic":"Concept of Health","stars":3,"years":["24Nov","23Nov","20Nov","16Nov","14Ja"],"colleges":"SSMC (1st Supp A1); ShSMC (1st Term A1); MMC (1st Supp A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define health.</p>","a":"<p><strong>Definitions</strong></p>\n<ol>\n<li><strong>WHO (Constitution, 1948)</strong>: &quot;Health is a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity.&quot;</li>\n<li><strong>Amplified (Alma-Ata, 1978)</strong>: health includes the ability to lead a <strong>socially and economically productive life</strong>.</li>\n<li><strong>Operational definition (WHO study group)</strong>:\n<ul>\n<li>Broad sense: a condition or quality of the organism showing <strong>adequate functioning</strong> under given genetic and environmental conditions.</li>\n<li>Narrow sense (for measurement): no obvious disease; body functions within normal limits for age, sex, community and region; organs in balance (<strong>homeostasis</strong>).</li>\n</ul>\n</li>\n<li><strong>Ottawa Charter (1986)</strong>: health is a <strong>resource for everyday life</strong>, not the objective of living.</li>\n<li><strong>Huber et al. (BMJ, 2011)</strong>: health as the ability to <strong>adapt and self-manage</strong> in face of social, physical and emotional challenges.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); WHO Constitution, 1948.</p>"},{"id":"DU.14","n":14,"part":1,"topic":"Concept of Health","stars":3,"years":["26M","25M","24Nov","24M","22M","18Nov","17Nov","16Nov","13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the changing concepts of health.</p>","a":"<p><strong>Changing concepts of health (Park)</strong></p>\n<p>Biomedical → Ecological → Psychosocial → Holistic</p>\n<table>\n<thead>\n<tr>\n<th>Concept</th>\n<th>Health seen as</th>\n<th>Key points</th>\n<th>Limitation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Biomedical</strong></td>\n<td>Absence of disease</td>\n<td>Based on germ theory; body as a machine, disease as breakdown, doctor as repairer; dominant till mid-20th century</td>\n<td>Ignores environmental, social, psychological and cultural factors; failed against malnutrition, chronic disease, mental illness, pollution, population growth</td>\n</tr>\n<tr>\n<td>2. <strong>Ecological</strong></td>\n<td>Dynamic equilibrium between man and environment</td>\n<td>Disease = maladjustment of man to environment; imperfect man in an imperfect environment (Dubos); health = relative absence of pain and discomfort with continuous adaptation</td>\n<td>Incomplete without social and psychological aspects</td>\n</tr>\n<tr>\n<td>3. <strong>Psychosocial</strong></td>\n<td>Biological and social phenomenon</td>\n<td>Health shaped by social, psychological, cultural, economic and political factors</td>\n<td>Needs to be joined with biological and environmental views</td>\n</tr>\n<tr>\n<td>4. <strong>Holistic</strong></td>\n<td>Multidimensional well-being of the whole person in his environment</td>\n<td>Synthesis of all earlier concepts; social, economic, political and environmental influences; many sectors (agriculture, education, industry, housing, communication) affect health; stress on promotion and protection</td>\n<td>Demands intersectoral effort; hard to measure</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Significance</strong></p>\n<ol>\n<li>Moved focus from <strong>disease to health</strong>, from <strong>cure to prevention and promotion</strong>.</li>\n<li>From <strong>individual to community</strong>; from doctor alone to <strong>team and other sectors</strong>.</li>\n<li>The WHO definition (1948) and PHC (Alma-Ata, 1978) reflect the <strong>holistic</strong> concept.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.15","n":15,"part":1,"topic":"Concept of Health","stars":0,"years":["10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What does holistic approach imply?</p>","a":"<p><strong>Meaning</strong></p>\n<p><strong>Holistic concept</strong> = synthesis of biomedical, ecological and psychosocial concepts. Health is a <strong>multidimensional</strong> process involving the well-being of the <strong>whole person</strong> (body, mind, social life, spirit) in the context of his <strong>environment</strong>.</p>\n<p><strong>What it implies</strong></p>\n<ol>\n<li>Treat the <strong>person, not only the disease</strong>: physical, mental, social and spiritual needs.</li>\n<li>Many <strong>determinants</strong>: biology, behaviour, environment, socio-economic status, health services.</li>\n<li><strong>Intersectoral approach</strong>: agriculture, food, education, water, housing, industry, communication and social welfare all affect health.</li>\n<li><strong>All levels of prevention</strong>: promotion, specific protection, early treatment, disability limitation, rehabilitation.</li>\n<li><strong>Comprehensive, continuous, family-centred</strong> care.</li>\n<li><strong>Community participation</strong> and self-care.</li>\n<li><strong>Team approach</strong>: doctor, nurse, health worker, social worker, nutritionist.</li>\n<li><strong>Integrated programmes</strong>: PHC, IMCI, essential service package; <strong>One Health</strong> (human–animal–environment).</li>\n<li>Priority to <strong>promotion and protection</strong> of health.</li>\n</ol>\n<p><strong>Biomedical vs holistic approach</strong></p>\n<table>\n<thead>\n<tr>\n<th>Biomedical</th>\n<th>Holistic</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Disease-centred</td>\n<td>Person-centred</td>\n</tr>\n<tr>\n<td>Single cause</td>\n<td>Multiple causes</td>\n</tr>\n<tr>\n<td>Cure</td>\n<td>Promotion, prevention, cure, rehabilitation</td>\n</tr>\n<tr>\n<td>Doctor alone</td>\n<td>Team, community and other sectors</td>\n</tr>\n<tr>\n<td>Hospital-based</td>\n<td>Home, community and facility</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.16","n":16,"part":1,"topic":"Concept of Health","stars":3,"years":["25Nov","21M","09Ju"],"colleges":"MMC (1st Supp A2)","asked":"","note":"","kind":"","sub":"","q":"<p>List the five major dimensions of health. / Health is a multidimensional theme on most culture – justify.</p>","a":"<p><strong>Five major dimensions</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Meaning / signs</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Physical</strong></td>\n<td>Perfect functioning of the body: good complexion, clean skin, bright eyes, good appetite, sound sleep, normal pulse and BP for age and sex</td>\n</tr>\n<tr>\n<td>2. <strong>Mental</strong></td>\n<td>Balance between self and surroundings: free of inner conflict, well adjusted, good self-esteem and self-control, solves problems</td>\n</tr>\n<tr>\n<td>3. <strong>Social</strong></td>\n<td>Quantity and quality of ties with family and community; social skills and roles</td>\n</tr>\n<tr>\n<td>4. <strong>Spiritual</strong></td>\n<td>Meaning and purpose in life; principles, ethics, faith</td>\n</tr>\n<tr>\n<td>5. <strong>Emotional</strong></td>\n<td>&quot;Feeling&quot;: freedom from anxiety and depression; handling emotions (mental = &quot;knowing&quot;)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other dimensions</strong></p>\n<p>Vocational (work satisfaction); philosophical, cultural, socio-economic, environmental, educational, nutritional, curative, preventive.</p>\n<p><strong>Health is multidimensional: justification</strong></p>\n<ol>\n<li>The WHO definition itself names <strong>physical, mental and social</strong> well-being.</li>\n<li>Dimensions <strong>interact</strong>: chronic illness → depression → job loss → poverty → poor nutrition → more illness.</li>\n<li>Across cultures health has always meant more than a sound body:\n<ul>\n<li><strong>Ayurveda</strong>: balance of body humours, senses, mind and soul.</li>\n<li><strong>Unani</strong> (Greek–Arab): balance of four humours and temperament.</li>\n<li><strong>Islamic tradition</strong>: well-being of body, mind and soul.</li>\n<li><strong>Chinese medicine</strong>: harmony of yin and yang with nature.</li>\n<li>Folk and tribal systems: harmony with family, ancestors and community.</li>\n</ul>\n</li>\n<li>Lay people judge health by ability to <strong>work, perform social roles and feel well</strong>, not only by absence of disease.</li>\n<li>So health is <strong>measured</strong> by many indicators (mortality, morbidity, disability, quality of life) and <strong>promoted</strong> by holistic, intersectoral action.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.17","n":17,"part":1,"topic":"Concept of Health","stars":3,"years":["23Nov","14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Explain mental dimension of health.</p>","a":"<p><strong>Definition</strong></p>\n<ul>\n<li>Mental health is more than the absence of mental illness.</li>\n<li><strong>WHO (2022)</strong>: &quot;a state of mental well-being that enables people to cope with the stresses of life, realize their abilities, learn well and work well, and contribute to their community.&quot;</li>\n<li>Park: a state of <strong>balance</strong> between the individual and the world around him; harmony with self, others and environment.</li>\n</ul>\n<p><strong>Characteristics of a mentally healthy person (Park)</strong></p>\n<ol>\n<li>Free from internal <strong>conflicts</strong>.</li>\n<li><strong>Well adjusted</strong>; gets along with others; accepts criticism.</li>\n<li>Searches for <strong>identity</strong>.</li>\n<li>Strong sense of <strong>self-esteem</strong>.</li>\n<li>Knows himself, his needs, problems and goals (<strong>self-actualisation</strong>).</li>\n<li>Good <strong>self-control</strong>; balances reason and emotion.</li>\n<li>Faces problems and solves them <strong>intelligently</strong>; copes with stress.</li>\n</ol>\n<p><strong>Determinants</strong></p>\n<ul>\n<li>Biological: genetics, brain disease, substance use.</li>\n<li>Psychological: personality, coping skills, childhood experiences.</li>\n<li>Social: poverty, unemployment, violence, discrimination, family conflict, migration, disasters.</li>\n</ul>\n<p><strong>Assessment</strong></p>\n<p>Clinical interview; mental status examination; psychological tests (intelligence, personality); screening scales (GHQ-12, PHQ-9, GAD-7, WHO-5).</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li>&quot;No health without mental health&quot;: mind and body interact (psychosomatic disorders: peptic ulcer, hypertension, asthma).</li>\n<li>Mental disorders cause major disability and loss of productivity.</li>\n<li>Depression worsens outcome of diabetes, CVD, TB, HIV.</li>\n<li>Promotion: life skills, school mental health, stress management, social support.</li>\n<li>Bangladesh: <strong>Mental Health Act 2018</strong>; mental health integrated into PHC.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Mental Health); WHO, Mental health: strengthening our response, 2022.</p>"},{"id":"DU.18","n":18,"part":1,"topic":"Concept of Health","stars":3,"years":["24M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the tools and techniques for evaluation of health.</p>","a":"<p><strong>A. Individual level</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Tools and techniques</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Physical</td>\n<td>Self-assessment of overall health; inquiry into symptoms, risk factors, medicines, physical activity, use of services; standardised questionnaires (e.g., cardiovascular); standardised physical examination; physiological tests (BP, ECG, spirometry, exercise tolerance); anthropometry and nutritional assessment; biochemical and laboratory tests</td>\n</tr>\n<tr>\n<td>Mental</td>\n<td>Clinical interview; mental status examination; psychological tests (intelligence, personality); rating scales (GHQ-12, PHQ-9)</td>\n</tr>\n<tr>\n<td>Social</td>\n<td>Social support and social adjustment scales; family function (Family APGAR); occupational functioning</td>\n</tr>\n<tr>\n<td>Overall well-being</td>\n<td>Quality-of-life tools (WHOQOL-BREF, SF-36); WHO-5 Well-Being Index</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Community level: health indicators</strong></p>\n<ol>\n<li><strong>Mortality</strong>: CDR, IMR, U5MR, MMR, life expectancy.</li>\n<li><strong>Morbidity</strong>: incidence, prevalence, notification rates.</li>\n<li><strong>Disability</strong>: Sullivan's index, HALE, DALY.</li>\n<li><strong>Nutritional status</strong>: stunting, wasting, underweight, LBW.</li>\n<li><strong>Health care delivery and utilisation</strong>: immunisation coverage, ANC, bed occupancy.</li>\n<li><strong>Composite</strong>: PQLI, HDI.</li>\n</ol>\n<p><strong>C. Techniques (sources of data)</strong></p>\n<ol>\n<li>Census and vital registration (Bangladesh: SVRS by BBS).</li>\n<li>Sample surveys (BDHS, MICS, STEPS NCD risk factor survey).</li>\n<li>Surveillance and notification (IEDCR).</li>\n<li>Hospital and service records (DHIS2-based HMIS).</li>\n<li>Screening programmes.</li>\n<li>Epidemiological studies (cross-sectional, cohort).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.19","n":19,"part":1,"topic":"Concept of Health","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you evaluate physical health?</p>","a":"<p><strong>Concept</strong></p>\n<p>Physical health = &quot;perfect functioning&quot; of the body; every cell and organ works at optimum capacity in harmony with the rest.</p>\n<p><strong>Signs of physical health</strong></p>\n<p>Good complexion; clean skin; bright eyes; lustrous hair; firm flesh, not too fat; sweet breath; good appetite; sound sleep; regular bowel and bladder; smooth, easy, coordinated movements; organs of normal size and function; intact special senses; resting pulse, BP and exercise tolerance in normal range for age and sex.</p>\n<p><strong>Evaluation at individual level</strong></p>\n<ol>\n<li>Self-assessment of overall health.</li>\n<li>Inquiry into symptoms of ill health and risk factors (tobacco, alcohol, diet).</li>\n<li>Inquiry into medications.</li>\n<li>Inquiry into level of physical activity.</li>\n<li>Inquiry into use of medical services.</li>\n<li>Standardised questionnaires (e.g., for cardiovascular disease).</li>\n<li>Standardised physical examination.</li>\n<li>Physiological tests: pulse, BP, ECG, lung function, exercise tolerance.</li>\n<li>Nutritional assessment: anthropometry (height, weight, BMI, MUAC, waist), diet survey, clinical signs.</li>\n<li>Biochemical and laboratory tests: haemoglobin, blood glucose, lipids, urine, stool.</li>\n</ol>\n<p><strong>Evaluation at community level</strong></p>\n<p>Health status indicators: CDR, IMR, U5MR, life expectancy, morbidity (incidence, prevalence), disability rates, nutritional status.</p>\n<table>\n<thead>\n<tr>\n<th>Indicator (Bangladesh)</th>\n<th>Value</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Life expectancy at birth</td>\n<td>72.3 years (SVRS 2023)</td>\n</tr>\n<tr>\n<td>Infant mortality rate</td>\n<td>27 per 1000 live births (SVRS 2023)</td>\n</tr>\n<tr>\n<td>Under-5 mortality rate</td>\n<td>33 per 1000 live births (SVRS 2023)</td>\n</tr>\n<tr>\n<td>Crude death rate</td>\n<td>6.1 per 1000 population (SVRS 2023)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); BBS, Bangladesh Sample Vital Statistics 2023 (The Financial Express, 2024), https://today.thefinancialexpress.com.bd/print/life-expectancy-falls-in-bd-bbs-1724781053</p>"},{"id":"DU.20","n":20,"part":1,"topic":"Concept of Health","stars":1,"years":["07Ja","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is positive health?</p>","a":"<p><strong>Concept</strong></p>\n<p>Positive health = perfect functioning of body and mind, beyond mere freedom from disease:</p>\n<ul>\n<li><strong>Biologically</strong>: every cell and organ works at optimum capacity, in perfect harmony with the rest.</li>\n<li><strong>Psychologically</strong>: the person feels perfect well-being and mastery over his environment.</li>\n<li><strong>Socially</strong>: optimum capacity to take part in the social system.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.21","n":21,"part":1,"topic":"Concept of Health","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by well-being?</p>","a":"<p><strong>Meaning</strong></p>\n<p>Well-being = overall welfare of a person or community; complex, partly subjective. Two components (Park):</p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Expressed as</th>\n<th>Nature</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Objective</strong></td>\n<td><strong>Standard of living / level of living</strong></td>\n<td>Measurable material conditions</td>\n</tr>\n<tr>\n<td><strong>Subjective</strong></td>\n<td><strong>Quality of life</strong></td>\n<td>What each person perceives and feels</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); UNDP HDR 2025 (TBS News, 2025), https://www.tbsnews.net/node/1135586</p>"},{"id":"DU.22","n":22,"part":1,"topic":"Concept of Health","stars":1,"years":["10Ju","04M"],"colleges":"MuMC (1st Final B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Illustrate subjective components of well-being.</p>","a":"<p><strong>Concept</strong></p>\n<p>Well-being = objective component (standard / level of living) + <strong>subjective component</strong> (what the person perceives) = <strong>quality of life</strong>.</p>\n<p><strong>Quality of life (WHO, 1995)</strong>: &quot;individuals' perception of their position in life in the context of the culture and value systems in which they live and in relation to their goals, expectations, standards and concerns.&quot;</p>\n<p><strong>Subjective components</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Illustration</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Happiness / positive feelings</td>\n<td>Joy, contentment, enthusiasm</td>\n</tr>\n<tr>\n<td>Absence of negative feelings</td>\n<td>Little anxiety, sadness, anger</td>\n</tr>\n<tr>\n<td>Life satisfaction</td>\n<td>Judging that life is going well overall</td>\n</tr>\n<tr>\n<td>Meaning and purpose</td>\n<td>Goals, values, faith (spiritual)</td>\n</tr>\n<tr>\n<td>Self-esteem and self-acceptance</td>\n<td>Positive view of oneself</td>\n</tr>\n<tr>\n<td>Sense of control (autonomy)</td>\n<td>Feeling able to shape one's own life</td>\n</tr>\n<tr>\n<td>Social connectedness</td>\n<td>Satisfying relations with family, friends, community</td>\n</tr>\n<tr>\n<td>Perceived health</td>\n<td>Self-rated physical and mental health</td>\n</tr>\n<tr>\n<td>Satisfaction with environment</td>\n<td>Safety, housing, services, freedom</td>\n</tr>\n</tbody>\n</table>\n<p><strong>WHOQOL domains</strong></p>\n<ul>\n<li>WHOQOL-100 (six): physical health; psychological; level of independence; social relationships; environment; spirituality / religion / personal beliefs.</li>\n<li>WHOQOL-BREF (four): physical, psychological, social relationships, environment.</li>\n</ul>\n<p><strong>Measurement</strong></p>\n<p>WHOQOL-BREF; WHO-5 Well-Being Index; Satisfaction With Life Scale; self-rated health (excellent → poor); Cantril ladder (World Happiness Report).</p>\n<p><strong>Flow</strong></p>\n<p>Objective conditions (income, housing, services) → personal perception (values, expectations, culture) → subjective well-being / quality of life</p>\n<p>Two people with the same standard of living may report very different quality of life; both components are needed.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); WHO, WHOQOL, 1995.</p>"},{"id":"DU.23","n":23,"part":1,"topic":"Concept of Health","stars":3,"years":["16M","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down / explain the biomedical concept of health.</p>","a":"<p><strong>Concept</strong></p>\n<ul>\n<li>Health = <strong>absence of disease</strong>; a person without disease is healthy.</li>\n<li>Rooted in the <strong>germ theory</strong> (Pasteur, Koch, late 19th century); dominated medicine until mid-20th century.</li>\n<li>Body seen as a <strong>machine</strong>; disease = breakdown of the machine; doctor = repairer.</li>\n<li>Disease explained by biological agents and abnormalities (pathology, physiology, biochemistry).</li>\n</ul>\n<p><strong>Features</strong></p>\n<ol>\n<li>Single-cause (agent) model of disease.</li>\n<li>Hospital- and doctor-centred; curative.</li>\n<li>Reliance on medical technology, drugs and surgery.</li>\n<li>Health judged by clinical and laboratory findings.</li>\n<li>Mind and body treated separately.</li>\n</ol>\n<p><strong>Contributions</strong></p>\n<ol>\n<li>Discovery of microbes, vaccines and antibiotics; control of many infections.</li>\n<li>Scientific diagnosis and treatment; growth of specialties.</li>\n</ol>\n<p><strong>Limitations</strong></p>\n<ol>\n<li>Ignores <strong>environmental, social, psychological and cultural</strong> determinants.</li>\n<li>Health is more than absence of disease; a person may have no disease yet feel unwell or be socially unfit.</li>\n<li>Cannot solve malnutrition, chronic disease, mental illness, accidents, drug abuse, pollution, population explosion.</li>\n<li>Costly; widens inequity; neglects prevention and promotion.</li>\n<li>Neglects the patient's experience and quality of life.</li>\n</ol>\n<p><strong>Outcome</strong></p>\n<p>Its limitations led to newer concepts:<br />\nBiomedical → Ecological → Psychosocial → Holistic</p>\n<p><strong>Example</strong></p>\n<p>Treating a malnourished child's diarrhoea with ORS and drugs alone, without addressing water, sanitation, feeding and poverty → repeated illness.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.24","n":24,"part":1,"topic":"Determinants of Health","stars":3,"years":["22M","18Nov","17Nov","08Ju","07Ju"],"colleges":"ShSMC (1st Term C1)","asked":"biological and social determinants of health","note":"","kind":"","sub":"","q":"<p>Enlist / discuss in brief the determinants of health.</p>","a":"<p><strong>Definition</strong></p>\n<p>Determinants of health = factors inside and outside the body whose interaction decides the health of individuals and communities.</p>\n<p><strong>Determinants (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Determinant</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Biological</strong></td>\n<td>Genetic make-up; chromosomal anomalies (Down syndrome); inborn errors (thalassaemia); predisposition (diabetes, hypertension); age, sex</td>\n</tr>\n<tr>\n<td>2. <strong>Behavioural and socio-cultural</strong></td>\n<td>Lifestyle: smoking, diet, physical activity, alcohol, sexual behaviour; customs, beliefs</td>\n</tr>\n<tr>\n<td>3. <strong>Environment</strong></td>\n<td>Internal milieu; external: physical (water, air, housing, arsenic), biological (vectors, microbes), psychosocial (stress, support)</td>\n</tr>\n<tr>\n<td>4. <strong>Socio-economic</strong></td>\n<td>Economic status, education (esp. female), occupation, political system</td>\n</tr>\n<tr>\n<td>5. <strong>Health services</strong></td>\n<td>Coverage, access and quality: immunisation, ANC, safe delivery, essential drugs</td>\n</tr>\n<tr>\n<td>6. <strong>Ageing of population</strong></td>\n<td>More NCDs, disability, care needs</td>\n</tr>\n<tr>\n<td>7. <strong>Gender</strong></td>\n<td>Unequal access to food, education, care; gender-based violence</td>\n</tr>\n<tr>\n<td>8. <strong>Other factors</strong></td>\n<td>Food and agriculture, education, industry, social welfare, rural development; information and communication technology</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Biological vs social determinants</strong></p>\n<ul>\n<li><strong>Biological</strong>: largely non-modifiable (genes, age, sex); some managed by genetic counselling and screening.</li>\n<li><strong>Social determinants (WHO)</strong>: non-medical conditions in which people are born, grow, work, live and age, and the wider forces (economics, policies, social norms, politics) shaping them; <strong>modifiable</strong>; root of health inequities.</li>\n</ul>\n<p><strong>WHO framework (CSDH, 2008)</strong></p>\n<p>Structural determinants (socio-political context; income, education, occupation, gender, ethnicity) → Intermediary determinants (living and working conditions, behaviours, psychosocial factors, health system) → Health and equity</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); WHO, Closing the gap in a generation (CSDH), 2008.</p>"},{"id":"DU.25","n":25,"part":1,"topic":"Determinants of Health","stars":3,"years":["26M"],"colleges":"ShSMC (1st Term C1)","asked":"criteria of an ideal health indicator","note":"","kind":"","sub":"","q":"<p>List the ideal characteristics of health indicators / five characteristics of a good indicator.</p>","a":"<p><strong>Health indicator</strong></p>\n<p>A variable that helps measure changes in health status, directly or indirectly.</p>\n<p><strong>Ideal characteristics (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Characteristic</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Valid</strong></td>\n<td>Measures what it is meant to measure</td>\n<td>IMR reflects child health and MCH care</td>\n</tr>\n<tr>\n<td>2. <strong>Reliable and objective</strong></td>\n<td>Same result when measured by different people at different times under similar conditions</td>\n<td>Birth weight on a calibrated scale</td>\n</tr>\n<tr>\n<td>3. <strong>Sensitive</strong></td>\n<td>Responds to changes in the situation</td>\n<td>IMR falls quickly as MCH services improve</td>\n</tr>\n<tr>\n<td>4. <strong>Specific</strong></td>\n<td>Reflects changes only in the situation concerned</td>\n<td>Neonatal tetanus rate reflects TT coverage and clean delivery</td>\n</tr>\n<tr>\n<td>5. <strong>Feasible</strong></td>\n<td>Data obtainable easily at acceptable cost</td>\n<td>Measles vaccine coverage from EPI records</td>\n</tr>\n<tr>\n<td>6. <strong>Relevant</strong></td>\n<td>Adds to understanding of the problem of interest</td>\n<td>MMR for a maternal health programme</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.26","n":26,"part":1,"topic":"Determinants of Health","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Explain the role of socio-economic &amp; cultural conditions on health.</p>","a":"<p><strong>A. Socio-economic conditions</strong></p>\n<ol>\n<li><strong>Economic status</strong>\n<ul>\n<li>Per capita income decides purchasing power, standard of living, family size and disease pattern.</li>\n<li>Poverty → malnutrition, overcrowding, unsafe water, infections (TB, diarrhoea), low use of services, high IMR.</li>\n<li>Affluence → obesity, diabetes, coronary heart disease.</li>\n</ul>\n</li>\n<li><strong>Education</strong>\n<ul>\n<li><strong>Female literacy</strong> → lower IMR and fertility; better hygiene, feeding, immunisation, care-seeking.</li>\n<li>Educated people understand and act on health messages.</li>\n</ul>\n</li>\n<li><strong>Occupation</strong>\n<ul>\n<li>Work gives income, status, self-esteem; unemployment → poverty, mental illness, substance use, suicide.</li>\n<li>Occupational hazards: silicosis, pesticide poisoning, injuries (garment, brick-kiln, ship-breaking workers).</li>\n</ul>\n</li>\n<li><strong>Political system</strong>\n<ul>\n<li>Decides health budget, policy, resource distribution, land reform, social safety nets, commitment to PHC and UHC.</li>\n</ul>\n</li>\n</ol>\n<p><strong>B. Cultural conditions (customs, beliefs, traditions, values)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Harmful to health</th>\n<th>Helpful to health</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Child marriage → teenage pregnancy, maternal and neonatal deaths</td>\n<td>Tradition of breastfeeding</td>\n</tr>\n<tr>\n<td>Food taboos in pregnancy; prelacteal feeds; discarding colostrum</td>\n<td>Religious cleanliness (ablution, hand-washing)</td>\n</tr>\n<tr>\n<td>Consanguineous marriage → thalassaemia, other genetic disorders</td>\n<td>Joint family care of elderly and sick</td>\n</tr>\n<tr>\n<td>Home delivery by untrained attendants; restricted mobility of women</td>\n<td>Abstinence from alcohol in many communities</td>\n</tr>\n<tr>\n<td>Belief in supernatural causes; quacks; delayed treatment</td>\n<td>Community solidarity in crises</td>\n</tr>\n<tr>\n<td>Son preference; discrimination against girls in food and care</td>\n<td></td>\n</tr>\n<tr>\n<td>Betel-quid and smokeless tobacco → oral cancer</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Interaction</strong></p>\n<p>Poverty → illiteracy → harmful practices → ill health → loss of work → deeper poverty (vicious cycle)</p>\n<p><strong>Implications</strong></p>\n<p>Health education, female education, poverty alleviation, social safety nets, culturally acceptable services, community participation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Medicine and Social Sciences).</p>"},{"id":"DU.27","n":27,"part":1,"topic":"Determinants of Health","stars":3,"years":["14Ju","12Ju","11Ja","09Ja"],"colleges":"SSMC (1st Supp A2)","asked":"","note":"","kind":"","sub":"","q":"<p>Explain community participation as principle of PHC / discuss the role of community participation for achieving the goal of HFA / discuss community participation / how community can participate in health development.</p>","a":"<p><strong>Definition</strong></p>\n<ul>\n<li><strong>Community participation</strong>: process by which individuals and families take responsibility for their own health and that of their community, and build the capacity to contribute to its development (Alma-Ata, 1978).</li>\n<li>Park: involvement of the community in <strong>planning, implementation and maintenance</strong> of health services, with maximum use of <strong>local resources</strong> (manpower, money, materials).</li>\n</ul>\n<p><strong>Place in PHC</strong></p>\n<p>Principles of PHC: equitable distribution; <strong>community participation</strong>; intersectoral coordination; appropriate technology.</p>\n<p><strong>Role in achieving HFA</strong></p>\n<ol>\n<li>Health cannot simply be &quot;delivered&quot;; people must take responsibility (<strong>self-reliance</strong>).</li>\n<li>Services become relevant, acceptable and culturally appropriate.</li>\n<li>Local resources lower cost and make services <strong>sustainable</strong>.</li>\n<li>Better coverage and use: immunisation, ANC, family planning, sanitation.</li>\n<li>Makes providers <strong>accountable</strong> to the people.</li>\n<li><strong>Empowers</strong> people; promotes equity.</li>\n</ol>\n<p><strong>How the community can participate</strong></p>\n<ol>\n<li>Identify needs and priorities (community diagnosis).</li>\n<li>Plan and manage services through health committees.</li>\n<li>Contribute land, labour, money and materials.</li>\n<li>Serve as volunteers and community health workers.</li>\n<li>Practise and spread healthy behaviour in families.</li>\n<li>Support campaigns: NIDs, vitamin A, sanitation, mosquito control.</li>\n<li>Monitor quality and give feedback.</li>\n</ol>\n<p><strong>Bangladesh example: Community Clinic</strong></p>\n<ul>\n<li>Built on <strong>land donated by the community</strong>; government provides building, staff (CHCP), drugs and logistics.</li>\n<li>Managed by a <strong>Community Group (CG)</strong>, helped by three <strong>Community Support Groups (CSGs)</strong> for awareness, referral and local funds.</li>\n<li>Planned as one clinic per ~6,000 people within 30 minutes' walk (CCHST, 2025).</li>\n<li>Others: NGO volunteers (e.g., BRAC <em>shasthya shebika</em>), union parishad health committees.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); Daily Observer (bdnews24), 2025, https://www.observerbd.com/news/540274</p>"},{"id":"DU.28","n":28,"part":1,"topic":"Health Indicators & MDGs","stars":3,"years":["21M","19Nov","07Ja"],"colleges":"SSMC (1st Supp A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the indicators of health with examples. / Illustrate the health status indicators.</p>","a":"<p><strong>Definition</strong></p>\n<p>Health indicators: variables that help measure changes in the health situation, directly or indirectly.</p>\n<p><strong>Classification (Park) with examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Indicator</th>\n<th>Examples (Bangladesh figures where available)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Mortality</strong></td>\n<td>CDR 6.1/1000; IMR 27 and U5MR 33/1000 LB; life expectancy 72.3 years (SVRS 2023); MMR 123/100,000 LB (UN estimate, 2020); disease-specific and proportional mortality</td>\n</tr>\n<tr>\n<td>2. <strong>Morbidity</strong></td>\n<td>Incidence, prevalence; notification rates; OPD attendance; admissions; length of stay; sickness absence</td>\n</tr>\n<tr>\n<td>3. <strong>Disability</strong></td>\n<td>Event-type (restricted-activity, bed-disability, work-loss days); person-type (limitation of mobility or activity); Sullivan's index; HALE; DALY</td>\n</tr>\n<tr>\n<td>4. <strong>Nutritional status</strong></td>\n<td>Under-5 stunting 23.6% (2022), wasting, underweight; heights/weights at school entry; LBW</td>\n</tr>\n<tr>\n<td>5. <strong>Health care delivery</strong></td>\n<td>Doctor–population, doctor–nurse, population–bed ratios; population per health centre</td>\n</tr>\n<tr>\n<td>6. <strong>Utilisation rates</strong></td>\n<td>Fully immunised children; ANC coverage; contraceptive prevalence; bed occupancy, average length of stay, bed turnover</td>\n</tr>\n<tr>\n<td>7. <strong>Social and mental health</strong></td>\n<td>Suicide, homicide, violence, road traffic accidents, drug and alcohol abuse</td>\n</tr>\n<tr>\n<td>8. <strong>Environmental</strong></td>\n<td>Access to safe water and sanitation; air pollution; arsenic exposure</td>\n</tr>\n<tr>\n<td>9. <strong>Socio-economic</strong></td>\n<td>Population growth rate; per capita GNP; dependency ratio; unemployment; literacy (esp. female); persons per room; per capita calorie availability</td>\n</tr>\n<tr>\n<td>10. <strong>Health policy</strong></td>\n<td>% of GNP spent on health; % spent on PHC</td>\n</tr>\n<tr>\n<td>11. <strong>Quality of life</strong></td>\n<td>PQLI; HDI (Bangladesh 0.685, UNDP HDR 2025)</td>\n</tr>\n<tr>\n<td>12. <strong>Other</strong></td>\n<td>Social indicators; basic needs indicators; HFA indicators; SDG 3 indicators (e.g., UHC service coverage index)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Health status indicators (narrow sense)</strong></p>\n<p>Mortality, morbidity, disability, nutritional status: they describe the health of people directly; the rest describe determinants and services.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); BBS SVRS 2023 (The Financial Express, 2024), https://today.thefinancialexpress.com.bd/print/life-expectancy-falls-in-bd-bbs-1724781053; Our World in Data, Bangladesh health profile, https://ourworldindata.org/profile/health/bangladesh</p>"},{"id":"DU.29","n":29,"part":1,"topic":"Health Indicators & MDGs","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Justify mortality indicators that are fair and good indicators of health.</p>","a":"<p><strong>Why mortality indicators are good indicators</strong></p>\n<ol>\n<li>Death is a definite event → <strong>objective and reliable</strong>.</li>\n<li>Data easily available (vital registration, SVRS, surveys, census) → <strong>feasible</strong>.</li>\n<li>Recorded everywhere → <strong>comparable</strong> across countries and over time.</li>\n<li>Reflect the end result of all determinants (socio-economic, environmental, nutritional, health services) → <strong>valid</strong> summary of health.</li>\n<li>Oldest and still most widely used indicators.</li>\n</ol>\n<p><strong>Justification of each indicator</strong></p>\n<table>\n<thead>\n<tr>\n<th>Indicator</th>\n<th>Why it is a fair and good indicator</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Crude death rate</td>\n<td>Simple overall measure; but affected by age structure, so poor for comparison unless standardised</td>\n</tr>\n<tr>\n<td><strong>Infant mortality rate</strong></td>\n<td>Most sensitive index of health status and level of living; reflects MCH care, nutrition, sanitation, female education; responds quickly to change</td>\n</tr>\n<tr>\n<td>Under-5 mortality rate</td>\n<td>Reflects child survival, nutrition, immunisation; MDG/SDG indicator</td>\n</tr>\n<tr>\n<td>Child mortality rate (1–4 y)</td>\n<td>Reflects environment, nutrition, infections</td>\n</tr>\n<tr>\n<td><strong>Maternal mortality ratio</strong></td>\n<td>Reflects quality of obstetric care, access to services, status of women</td>\n</tr>\n<tr>\n<td><strong>Life expectancy</strong></td>\n<td>Best single summary of mortality at all ages; free of age-structure effect; good index of socio-economic development</td>\n</tr>\n<tr>\n<td>Disease-specific mortality</td>\n<td>Burden of a disease; evaluates control programmes</td>\n</tr>\n<tr>\n<td>Proportional mortality rate</td>\n<td>Simple; e.g., share of deaths from communicable diseases, share of deaths at age ≥50 years</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Limitations</strong></p>\n<ol>\n<li>Show only death, not illness, disability or quality of life (tip of the iceberg).</li>\n<li>As mortality falls they become <strong>less sensitive</strong>; NCDs and mental illness poorly reflected.</li>\n<li>Under-registration and wrong cause-of-death coding in developing countries.</li>\n<li>National averages hide inequalities unless disaggregated.</li>\n</ol>\n<p>So they are combined with morbidity, disability (DALY, HALE) and quality-of-life indicators.<br />\nExample: Bangladesh IMR 27 per 1000 live births (SVRS 2023).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); BBS SVRS 2023 (The Financial Express, 2024), https://today.thefinancialexpress.com.bd/print/life-expectancy-falls-in-bd-bbs-1724781053</p>"},{"id":"DU.30","n":30,"part":1,"topic":"Health Indicators & MDGs","stars":0,"years":["19Nov","16Nov","09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is Health For All (HFA)?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Health for All (HFA)</strong>: attainment by all citizens of the world by the year 2000 of a level of health that will permit them to lead a <strong>socially and economically productive life</strong> (World Health Assembly, WHA30.43, 1977).</p>\n<p><strong>What HFA means</strong></p>\n<ol>\n<li>Health begins at home, school and workplace.</li>\n<li>People use better ways to prevent illness and relieve unavoidable disease and disability; grow up, grow old and die gracefully.</li>\n<li>Health resources are evenly distributed.</li>\n<li>Essential health care is accessible to all individuals and families, in an acceptable and affordable way, with their full involvement.</li>\n<li>People realise disease is not inevitable and that they can shape their own lives.</li>\n</ol>\n<p><strong>What HFA does NOT mean</strong></p>\n<ul>\n<li>That doctors and nurses will treat everyone for every illness by 2000.</li>\n<li>That nobody will be sick or disabled by 2000.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine; Health Care of the Community).</p>"},{"id":"DU.31","n":31,"part":1,"topic":"Health Indicators & MDGs","stars":0,"years":["05M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the global indicators for HFA 2000 AD.</p>","a":"<p><strong>Global indicators for HFA by 2000 (WHO, Global Strategy, 1981)</strong></p>\n<ol>\n<li>HFA endorsed as policy at the <strong>highest official level</strong>.</li>\n<li>Mechanisms for <strong>involving people</strong> in implementing strategies formed or strengthened, and functioning.</li>\n<li>At least <strong>5% of GNP</strong> spent on health.</li>\n<li>A reasonable share of national health expenditure on <strong>local health care</strong> (first-level care).</li>\n<li>Resources <strong>equitably distributed</strong>.</li>\n<li>Number of developing countries with well-defined HFA strategies and explicit resource allocation, whose external resource needs receive sustained support from richer countries.</li>\n<li><strong>PHC available to the whole population</strong>, with at least:\n<ul>\n<li>safe water in the home or within 15 minutes' walk; adequate sanitary facilities in the home or nearby</li>\n<li>immunisation against diphtheria, tetanus, whooping cough, measles, poliomyelitis and tuberculosis</li>\n<li>local health care with at least <strong>20 essential drugs</strong> within one hour's walk or travel</li>\n<li>trained personnel for pregnancy and childbirth, and care of children up to at least 1 year</li>\n</ul>\n</li>\n<li><strong>Nutritional status</strong>: at least 90% of newborns weigh <strong>≥2500 g</strong>; at least 90% of children have weight-for-age matching reference values.</li>\n<li><strong>IMR &lt;50</strong> per 1000 live births in all identifiable subgroups.</li>\n<li><strong>Life expectancy at birth &gt;60 years</strong>.</li>\n<li><strong>Adult literacy &gt;70%</strong> for both men and women.</li>\n<li><strong>GNP per head &gt;US$ 500</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.32","n":32,"part":1,"topic":"Health Indicators & MDGs","stars":3,"years":["16M","13Ju","10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Illustrate the health related MDGs / mention health related goals of MDG / state health related Millennium components of MDGs.</p>","a":"<p><strong>Health-related MDGs (2000–2015; baseline 1990)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Goal</th>\n<th>Health-related target</th>\n<th>Key indicators</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Eradicate extreme poverty and hunger</td>\n<td><strong>1C</strong>: halve the proportion of people suffering from hunger</td>\n<td>Underweight under-5s; population below minimum dietary energy</td>\n</tr>\n<tr>\n<td>4. <strong>Reduce child mortality</strong></td>\n<td><strong>4A</strong>: cut U5MR by <strong>two-thirds</strong></td>\n<td>U5MR; IMR; % of 1-year-olds immunised against measles</td>\n</tr>\n<tr>\n<td>5. <strong>Improve maternal health</strong></td>\n<td><strong>5A</strong>: cut MMR by <strong>three-quarters</strong>; <strong>5B</strong>: universal access to reproductive health by 2015</td>\n<td>MMR; skilled birth attendance; CPR; adolescent birth rate; ANC; unmet need for FP</td>\n</tr>\n<tr>\n<td>6. <strong>Combat HIV/AIDS, malaria and other diseases</strong></td>\n<td><strong>6A</strong>: halt and reverse HIV by 2015; <strong>6B</strong>: universal access to HIV treatment by 2010; <strong>6C</strong>: halt and reverse malaria and other major diseases (TB)</td>\n<td>HIV prevalence (15–24 y); condom use; ART coverage; malaria and TB incidence and deaths; ITN use; TB detection and cure (DOTS)</td>\n</tr>\n<tr>\n<td>7. Environmental sustainability</td>\n<td><strong>7C</strong>: halve proportion without safe drinking water and basic sanitation; <strong>7D</strong>: improve lives of slum dwellers</td>\n<td>Use of improved water source and sanitation</td>\n</tr>\n<tr>\n<td>8. Global partnership</td>\n<td><strong>8E</strong>: access to affordable essential drugs</td>\n<td>Population with access to affordable essential drugs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Core health MDGs</strong>: Goals 4, 5 and 6.</p>\n<p><strong>Bangladesh progress (MDG Progress Report 2015, GED)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Indicator</th>\n<th>1990</th>\n<th>Achieved</th>\n<th>2015 target</th>\n<th>Status</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>U5MR /1000 LB</td>\n<td>146</td>\n<td>46 (BDHS 2014)</td>\n<td>48</td>\n<td>Met</td>\n</tr>\n<tr>\n<td>IMR /1000 LB</td>\n<td>92</td>\n<td>32 (SVRS 2013)</td>\n<td>31</td>\n<td>On track</td>\n</tr>\n</tbody>\n</table>\n<p>MMR baseline 574 per 100,000 LB (1990); 2015 target 143.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); GED/UNSD, From MDG to SDG monitoring: Bangladesh, 2015, https://unstats.un.org/sdgs/files/meetings/sdg-seminar-xian-2015/Presentation--1.2-From-MDG-to-SDG-Monitoring--Bangladesh.pdf</p>"},{"id":"DU.33","n":33,"part":1,"topic":"Health Indicators & MDGs","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Briefly discuss the concept of MDGs.</p>","a":"<p><strong>Concept</strong></p>\n<ul>\n<li><strong>MDGs</strong>: eight time-bound, measurable development goals from the <strong>UN Millennium Declaration</strong>, signed by 189 member states at the Millennium Summit (September 2000).</li>\n<li>Aim: halve extreme poverty and improve human development by <strong>2015</strong>, from a <strong>1990 baseline</strong>.</li>\n<li>Framework: <strong>8 goals, 21 targets, 60 indicators</strong> (revised 2007; originally 18 targets, 48 indicators).</li>\n<li>Shared responsibility: developing countries (policy, governance) + developed countries (aid, trade, debt relief; Goal 8).</li>\n</ul>\n<p><strong>The eight goals</strong></p>\n<ol>\n<li>Eradicate extreme poverty and hunger</li>\n<li>Achieve universal primary education</li>\n<li>Promote gender equality and empower women</li>\n<li>Reduce child mortality</li>\n<li>Improve maternal health</li>\n<li>Combat HIV/AIDS, malaria and other diseases</li>\n<li>Ensure environmental sustainability</li>\n<li>Develop a global partnership for development</li>\n</ol>\n<p><strong>Health in MDGs</strong></p>\n<p>3 goals directly on health (4, 5, 6); health targets also in Goals 1 (hunger), 7 (water, sanitation) and 8 (essential drugs).</p>\n<p><strong>Features</strong></p>\n<ol>\n<li>Simple, clear, quantified, time-bound; easy to monitor.</li>\n<li>Mobilised political will and funds (GAVI 2000, Global Fund 2002).</li>\n<li>Focus on developing countries.</li>\n</ol>\n<p><strong>Limitations</strong></p>\n<ol>\n<li>Narrow: NCDs, mental health, injuries, health systems left out.</li>\n<li>Donor-driven; national averages hid inequalities.</li>\n</ol>\n<p><strong>Outcome</strong></p>\n<ul>\n<li>World missed the U5MR target; 24 low- and lower-middle-income countries met it, including <strong>Bangladesh</strong> (UNICEF, 2015).</li>\n<li>Bangladesh U5MR 46 vs target 48 (BDHS 2014).</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); UNICEF, A Promise Renewed 2015 progress report, https://www.unicef.cn/en/press-releases/nearly-50-million-lives-saved-2000-millions-more-can-be-saved-2030-unicef-report</p>"},{"id":"DU.34","n":34,"part":1,"topic":"Health Indicators & MDGs","stars":0,"years":[],"colleges":"DMC (1st Assess A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Write down four important aspects of health indicators.</p>","a":"<p><strong>Health indicator</strong></p>\n<p>A variable that measures changes in health status, directly or indirectly, and shows how far objectives and targets are being reached.</p>\n<p><strong>Four important aspects (uses)</strong></p>\n<ol>\n<li><strong>Measure the health status</strong> of a community\n<ul>\n<li>Community diagnosis; e.g., IMR, life expectancy, stunting.</li>\n</ul>\n</li>\n<li><strong>Compare</strong> health status\n<ul>\n<li>Between countries, regions, groups (urban–rural, rich–poor) and over time.</li>\n</ul>\n</li>\n<li><strong>Assess health care needs and allocate resources</strong>\n<ul>\n<li>Identify priority problems and underserved groups; guide planning and allocation of scarce resources.</li>\n</ul>\n</li>\n<li><strong>Monitor and evaluate</strong> health services and programmes\n<ul>\n<li>e.g., immunisation coverage for EPI; ANC and skilled birth attendance for maternal health; progress towards SDG 3.</li>\n</ul>\n</li>\n</ol>\n<p><strong>Other aspects</strong></p>\n<ul>\n<li>Indicators are usually expressed as <strong>rates, ratios or proportions</strong>.</li>\n<li>A <strong>set</strong> of indicators is needed; no single indicator captures health.</li>\n<li>Support <strong>advocacy and accountability</strong> of governments and programmes.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.35","n":35,"part":1,"topic":"Health Care of the Community","stars":0,"years":["06M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define health care.</p>","a":"<p><strong>Definition</strong></p>\n<ul>\n<li><strong>Health care</strong>: the many services given to individuals, families or communities by health services or professions to <strong>promote, maintain, monitor or restore health</strong>.</li>\n<li>Broader than medical care: includes promotive, preventive, curative, rehabilitative and palliative services.</li>\n<li><strong>Health system (WHO, 2000)</strong>: all organisations, people and actions whose primary intent is to promote, restore or maintain health.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Health Care of the Community); WHO, World Health Report 2000.</p>"},{"id":"DU.36","n":36,"part":1,"topic":"Health Care of the Community","stars":3,"years":["20Nov","12Ju","06M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist the criteria of ideal health care.</p>","a":"<p><strong>Criteria of ideal health care (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Criterion</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Appropriate</strong></td>\n<td>Relevant to the real needs of the community</td>\n<td>Priority to diarrhoea, pneumonia, maternal care over costly transplants</td>\n</tr>\n<tr>\n<td>2. <strong>Comprehensive</strong></td>\n<td>Optimal mix of promotive, preventive, curative and rehabilitative services</td>\n<td>UHC offering EPI, ANC, OPD, physiotherapy</td>\n</tr>\n<tr>\n<td>3. <strong>Adequate</strong></td>\n<td>In proportion to requirement (staff, drugs, beds)</td>\n<td>Doctor–population and bed–population ratios</td>\n</tr>\n<tr>\n<td>4. <strong>Available</strong></td>\n<td>Round the clock, all year</td>\n<td>24-hour emergency and delivery services</td>\n</tr>\n<tr>\n<td>5. <strong>Accessible</strong></td>\n<td>Within easy reach: geographic, economic, social</td>\n<td>Community clinic within 30 minutes' walk</td>\n</tr>\n<tr>\n<td>6. <strong>Affordable</strong></td>\n<td>Cost within means of individuals and the country</td>\n<td>Free essential drugs at community clinics</td>\n</tr>\n<tr>\n<td>7. <strong>Feasible</strong></td>\n<td>Operationally possible with existing resources</td>\n<td>ORS and CHCPs rather than high-tech units</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Additional criteria: quality of care (WHO, OECD, World Bank, 2018)</strong></p>\n<ol>\n<li>Effective</li>\n<li>Safe</li>\n<li>People-centred</li>\n<li>Timely</li>\n<li>Equitable</li>\n<li>Integrated</li>\n<li>Efficient</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); WHO, Delivering quality health services, 2018.</p>"},{"id":"DU.37","n":37,"part":1,"topic":"Health Care of the Community","stars":3,"years":["22Nov","17Ja","16M","14Ju","06Ja"],"colleges":"ShSMC (2nd Term A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Produce your concept about / what do you mean by comprehensive health care?</p>","a":"<p><strong>Concept</strong></p>\n<ul>\n<li><strong>Comprehensive health care</strong>: integrated provision of <strong>promotive, preventive, curative and rehabilitative</strong> (and palliative) services to the individual, family and community through one system, at all levels.</li>\n<li>Origin: <strong>Bhore Committee (India, 1946)</strong>: integration of curative and preventive medicine at all levels; later the basis of PHC.</li>\n<li>Treats the whole person (holistic), with continuity from birth to death.</li>\n</ul>\n<p><strong>Features</strong></p>\n<ol>\n<li><strong>Integration</strong> of preventive and curative services (not separate vertical units).</li>\n<li><strong>Continuity</strong> of care, &quot;womb to tomb&quot;, across levels through <strong>referral</strong>.</li>\n<li><strong>Whole population</strong> covered, priority to vulnerable groups.</li>\n<li><strong>Team approach</strong>: doctors, nurses, health assistants, CHCPs, social workers.</li>\n<li><strong>Community participation</strong> and <strong>intersectoral</strong> links (water, education, agriculture).</li>\n<li>Covers physical, mental and social health.</li>\n<li>First contact close to people, at primary level.</li>\n<li>Rational, cost-effective use of resources.</li>\n</ol>\n<p><strong>Components</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Promotive</td>\n<td>Health education, nutrition, sanitation</td>\n</tr>\n<tr>\n<td>Preventive</td>\n<td>EPI, ANC, vitamin A, screening</td>\n</tr>\n<tr>\n<td>Curative</td>\n<td>Treatment of pneumonia, TB, hypertension</td>\n</tr>\n<tr>\n<td>Rehabilitative</td>\n<td>Physiotherapy, artificial limbs, vocational training</td>\n</tr>\n<tr>\n<td>Palliative</td>\n<td>Pain relief in cancer</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Health Care of the Community).</p>"},{"id":"DU.38","n":38,"part":1,"topic":"Health Care of the Community","stars":3,"years":["25Nov","20Nov"],"colleges":"MMC (1st Supp A2)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the components of comprehensive health care with example.</p>","a":"<p><strong>Components of comprehensive health care</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Aim</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Health promotion</strong></td>\n<td>Improve general health and well-being</td>\n<td>Health education, nutrition, healthy lifestyle, sanitation, housing</td>\n</tr>\n<tr>\n<td>2. <strong>Specific protection</strong></td>\n<td>Protect against particular diseases</td>\n<td>Immunisation (EPI), chemoprophylaxis, iodised salt, vitamin A, helmets and seat belts, protective gear at work</td>\n</tr>\n<tr>\n<td>3. <strong>Early diagnosis and treatment</strong></td>\n<td>Detect and treat early; stop spread and complications</td>\n<td>Screening (BP, diabetes, VIA for cervical cancer), TB case finding, malaria treatment, IMCI</td>\n</tr>\n<tr>\n<td>4. <strong>Disability limitation</strong></td>\n<td>Prevent progression to disability or death</td>\n<td>Good diabetes control to avoid amputation; stroke care; care of leprosy reactions</td>\n</tr>\n<tr>\n<td>5. <strong>Rehabilitation</strong></td>\n<td>Restore highest possible function</td>\n<td>Physiotherapy, artificial limbs, hearing aids, vocational training, social support</td>\n</tr>\n<tr>\n<td>6. <strong>Palliative care</strong></td>\n<td>Relieve suffering in incurable illness</td>\n<td>Oral morphine for cancer pain, home-based care</td>\n</tr>\n</tbody>\n</table>\n<p>Components 1–5 = Leavell and Clark's five modes of intervention; WHO adds palliative care to the UHC continuum.</p>\n<p><strong>Example: tuberculosis</strong></p>\n<ol>\n<li>Promotion: health education, nutrition, ventilation.</li>\n<li>Protection: BCG; TB preventive therapy for contacts.</li>\n<li>Early diagnosis and treatment: sputum microscopy / GeneXpert; DOTS.</li>\n<li>Disability limitation: management of complications and drug-resistant TB.</li>\n<li>Rehabilitation: vocational and social support.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.39","n":39,"part":1,"topic":"Health Care of the Community","stars":2,"years":["18M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between medical care and health care.</p>","a":"<p><strong>Medical care vs health care</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Medical care</th>\n<th>Health care</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Definition</td>\n<td>Services by doctors and allied staff to diagnose and treat illness</td>\n<td>All services by health professions and agencies to promote, maintain, monitor or restore health</td>\n</tr>\n<tr>\n<td>Scope</td>\n<td>Narrow; a part of health care</td>\n<td>Broad; medical care + public health + related services</td>\n</tr>\n<tr>\n<td>Target</td>\n<td>Sick individual</td>\n<td>Individual, family and community, sick and healthy</td>\n</tr>\n<tr>\n<td>Orientation</td>\n<td>Curative</td>\n<td>Promotive, preventive, curative, rehabilitative, palliative</td>\n</tr>\n<tr>\n<td>Concept of health</td>\n<td>Biomedical</td>\n<td>Holistic</td>\n</tr>\n<tr>\n<td>Approach</td>\n<td>Passive: patient comes to doctor</td>\n<td>Active: reaches people</td>\n</tr>\n<tr>\n<td>Provider</td>\n<td>Doctor-centred</td>\n<td>Health team, community and other sectors</td>\n</tr>\n<tr>\n<td>Place</td>\n<td>Hospitals, clinics</td>\n<td>Homes, schools, workplaces, community, facilities</td>\n</tr>\n<tr>\n<td>Activities</td>\n<td>Diagnosis, drugs, surgery, nursing</td>\n<td>Plus health education, immunisation, nutrition, sanitation, MCH, FP, surveillance</td>\n</tr>\n<tr>\n<td>Evaluation</td>\n<td>Cure of the patient</td>\n<td>Health indicators of the population</td>\n</tr>\n<tr>\n<td>Cost</td>\n<td>Costly, technology-heavy</td>\n<td>More cost-effective (prevention)</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Treating a child's measles pneumonia</td>\n<td>Measles vaccination, vitamin A, nutrition, plus treatment</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.40","n":40,"part":1,"topic":"Health Care of the Community","stars":0,"years":[],"colleges":"SSMC (1st Supp A5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A patient with severe asthma first visits a community clinic, then is referred to Upazila Health Complex, and finally to a Medical College Hospital. What is the type of referral system here? Describe types of referral systems in Bangladesh. State importance of referral system. [1+3+3]</p>","a":"<p><strong>a) Type of referral (1)</strong></p>\n<p><strong>Vertical (upward) referral</strong>: stepwise from primary (community clinic) → first-referral level (Upazila Health Complex) → tertiary (medical college hospital); a <strong>three-tier</strong> referral.</p>\n<p><strong>b) Types of referral in Bangladesh (3)</strong></p>\n<p>Service tiers:<br />\nCommunity clinic (ward; ~6,000 people) → Union Health and Family Welfare Centre / Union Sub-centre → Upazila Health Complex → District hospital → Medical college hospital / specialised institute (e.g., National Institute of Diseases of the Chest and Hospital)</p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Description</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Vertical: upward</strong></td>\n<td>Lower to higher level for more skilled care</td>\n<td>Severe asthma: CC → UHC → medical college hospital</td>\n</tr>\n<tr>\n<td>2. <strong>Vertical: downward (back / reverse referral)</strong></td>\n<td>Higher to lower level for follow-up after stabilisation</td>\n<td>Stable asthmatic sent back to UHC or CC for inhaler follow-up</td>\n</tr>\n<tr>\n<td>3. <strong>Horizontal (lateral)</strong></td>\n<td>Between facilities or departments at the same level</td>\n<td>Medicine to surgery within a district hospital; one UHC to another with a specialist</td>\n</tr>\n<tr>\n<td>4. <strong>Diagonal</strong></td>\n<td>To a different level and a different specialty</td>\n<td>UHC medicine OPD → district hospital eye department</td>\n</tr>\n<tr>\n<td>5. <strong>Self-referral (bypass)</strong></td>\n<td>Patient goes straight to a higher level without referral</td>\n<td>Common in Bangladesh; overcrowds tertiary hospitals</td>\n</tr>\n</tbody>\n</table>\n<p>Also by urgency: <strong>emergency</strong> vs <strong>routine (elective)</strong> referral. A proper referral needs a <strong>referral slip</strong> and <strong>counter-referral (feedback)</strong>.</p>\n<p><strong>c) Importance of referral system (3)</strong></p>\n<ol>\n<li><strong>Right care at the right level</strong>; continuity of care.</li>\n<li><strong>Gatekeeping</strong>: keeps minor cases away from tertiary hospitals.</li>\n<li><strong>Efficient use of resources</strong>: specialists, beds and equipment for those who need them.</li>\n<li>Lowers <strong>cost</strong> and travel for patients; most problems solved locally.</li>\n<li><strong>Saves lives</strong>: timely transfer of emergencies (obstetric, severe asthma, trauma).</li>\n<li><strong>Strengthens PHC</strong> and community trust in lower facilities.</li>\n<li><strong>Two-way communication</strong>: feedback improves skills of primary-level staff.</li>\n<li>Better records, monitoring and quality of care.</li>\n<li>Supports an integrated health system and <strong>UHC</strong>.</li>\n</ol>\n<p><strong>Problems in Bangladesh</strong></p>\n<p>Weak enforcement, frequent self-referral, poor transport and ambulance services, little feedback, staff and drug shortages at lower levels.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); Daily Observer (bdnews24), 2025, https://www.observerbd.com/news/540274</p>"},{"id":"DU.41","n":41,"part":1,"topic":"PHC","stars":3,"years":["23Nov","17Ja","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define primary health care (PHC).</p>","a":"<p><strong>Definition (Alma-Ata Declaration, 1978)</strong></p>\n<p>&quot;Primary health care is essential health care based on practical, scientifically sound and socially acceptable methods and technology made universally accessible to individuals and families in the community through their full participation and at a cost that the community and country can afford to maintain at every stage of their development in the spirit of self-reliance and self-determination.&quot;</p>\n<p>It is part of both the national health system (its central function and main focus) and overall socio-economic development; the <strong>first level of contact</strong> of people with the health system, bringing care as close as possible to where they live and work; the first element of a <strong>continuing health care process</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); WHO/UNICEF, Declaration of Astana, 2018.</p>"},{"id":"DU.42","n":42,"part":1,"topic":"PHC","stars":3,"years":["24M","22M","21M","20Nov","19M","17M","16Ju","16M","14Ja","11Ja","10Ja"],"colleges":"DMC (1st Assess D4); ShSMC (1st Term A2)","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the elements of PHC / mention 5 strategies of PHC (also: in Bangladesh).</p>","a":"<p><strong>Elements of PHC (Alma-Ata, 1978)</strong></p>\n<table>\n<thead>\n<tr>\n<th>No.</th>\n<th>Element</th>\n<th>Examples (Bangladesh)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Education</strong> concerning prevailing health problems and methods of preventing and controlling them</td>\n<td>Hand-washing, ORS use, breastfeeding messages</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Promotion of <strong>food supply and proper nutrition</strong></td>\n<td>Vitamin A, iron-folic acid, growth monitoring, IYCF counselling</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Adequate supply of <strong>safe water and basic sanitation</strong></td>\n<td>Tube wells, arsenic testing, sanitary latrines</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Maternal and child health</strong>, including <strong>family planning</strong></td>\n<td>ANC, safe delivery, PNC, contraceptives</td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>Immunisation</strong> against major infectious diseases</td>\n<td>EPI</td>\n</tr>\n<tr>\n<td>6</td>\n<td>Prevention and control of <strong>locally endemic diseases</strong></td>\n<td>Malaria, kala-azar, filariasis, dengue control</td>\n</tr>\n<tr>\n<td>7</td>\n<td>Appropriate <strong>treatment of common diseases and injuries</strong></td>\n<td>IMCI, first aid at community clinics</td>\n</tr>\n<tr>\n<td>8</td>\n<td>Provision of <strong>essential drugs</strong></td>\n<td>Free essential drugs at CC and UHC</td>\n</tr>\n</tbody>\n</table>\n<p>Mnemonic: <strong>ELEMENTS</strong> (Education, Locally endemic diseases, EPI, MCH-FP, Essential drugs, Nutrition, Treatment, Safe water).<br />\nLater additions (India/Bangladesh practice): mental health, dental health, NCD screening, referral services.</p>\n<p><strong>Strategies of PHC (and in Bangladesh)</strong></p>\n<ol>\n<li><strong>Community participation</strong>: community clinics on donated land; community groups.</li>\n<li><strong>Intersectoral coordination</strong>: health with education, agriculture, local government (water, sanitation).</li>\n<li><strong>Appropriate technology</strong>: ORS, MUAC tape, chlorhexidine, misoprostol.</li>\n<li><strong>Equitable distribution</strong>: one community clinic per ~6,000 people; free services.</li>\n<li><strong>Decentralisation and referral</strong>: CC → union → UHC → district → tertiary.</li>\n<li><strong>Human resources</strong>: CHCPs, health assistants, FWAs, NGO volunteers.</li>\n<li><strong>Integration of services</strong>: Essential Service Package (health, nutrition, FP).</li>\n<li><strong>Public–private–NGO partnership</strong>: BRAC, icddr,b, urban PHC projects.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.43","n":43,"part":1,"topic":"PHC","stars":3,"years":["14Ja","10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention which element of PHC is best for immediate improvement of health services in Bangladesh and why.</p>","a":"<p><strong>Best element for immediate improvement: &quot;Education concerning prevailing health problems and the methods of preventing and controlling them&quot; (health education)</strong></p>\n<p><strong>Why</strong></p>\n<ol>\n<li><strong>Key to all other elements</strong>: people use immunisation, ANC, family planning, sanitation and ORS only when they understand them.</li>\n<li><strong>Quick results</strong>: messages spread fast through mass media, mobile phones, community clinics, schools, mosques, NGO workers.</li>\n<li><strong>Cheapest and most cost-effective</strong> intervention; needs few resources.</li>\n<li><strong>Fits Bangladesh's problems</strong>, which are largely behaviour-related: hand-washing, safe water, breastfeeding, child marriage, early ANC, tobacco, salt intake, dengue source reduction.</li>\n<li><strong>Creates demand</strong> for services and reduces delay in seeking care (e.g., danger signs in pregnancy and childhood pneumonia).</li>\n<li><strong>Empowers communities</strong>: promotes self-care, community participation and accountability.</li>\n<li><strong>Proven success</strong>: home-made ORS (lobon-gur), family planning and EPI campaigns spread through health education.</li>\n<li>Addresses the <strong>rising NCD burden</strong>: diet, exercise, tobacco, BP and diabetes screening.</li>\n</ol>\n<p><strong>Conclusion line</strong></p>\n<p>Health education multiplies the effect of every other element at the lowest cost.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community; Communication for Health Education).</p>"},{"id":"DU.44","n":44,"part":1,"topic":"PHC","stars":3,"years":["25M","20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Primary health care is essential health care – justify.</p>","a":"<p><strong>PHC = essential health care: justification</strong></p>\n<ol>\n<li><strong>By definition (Alma-Ata, 1978)</strong>: PHC is &quot;essential health care&quot; based on practical, scientifically sound and socially acceptable methods.</li>\n<li><strong>Meets basic health needs</strong>: its 8 elements tackle the main causes of illness and death (infections, malnutrition, maternal and child problems, unsafe water).</li>\n<li><strong>First contact</strong>: most health problems (common illnesses, ANC, immunisation, FP) can be managed at this level.</li>\n<li><strong>Universal accessibility</strong>: brings care close to home, work and school.</li>\n<li><strong>Affordable</strong>: low cost for people and the country; uses local resources.</li>\n<li><strong>Acceptable</strong>: socially and culturally appropriate methods.</li>\n<li><strong>Equity</strong>: priority to the poor, rural and vulnerable.</li>\n<li><strong>Comprehensive</strong>: promotive, preventive, curative and rehabilitative.</li>\n<li><strong>Community participation and self-reliance</strong>: makes care sustainable.</li>\n<li><strong>Cost-effective</strong>: prevention is cheaper than hospital care.</li>\n<li><strong>Foundation of the health system</strong>: links people to secondary and tertiary care through referral.</li>\n<li><strong>Route to UHC and SDG 3</strong> (Astana Declaration, 2018).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.45","n":45,"part":1,"topic":"PHC","stars":2,"years":["22Nov","16Nov","09Ju"],"colleges":"MMC (1st Supp A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention / briefly narrate the principles of PHC with examples (also: strategies and principles).</p>","a":"<p><strong>Principles of PHC (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Principle</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Equitable distribution</strong></td>\n<td>Health services shared by all, irrespective of ability to pay; rich or poor, urban or rural</td>\n<td>One community clinic per ~6,000 rural people; free EPI</td>\n</tr>\n<tr>\n<td>2. <strong>Community participation</strong></td>\n<td>People involved in planning, implementing and maintaining services; use of local resources</td>\n<td>Land donated for community clinics; community groups</td>\n</tr>\n<tr>\n<td>3. <strong>Intersectoral coordination</strong></td>\n<td>Health linked with agriculture, food, education, water, housing, communication, local government</td>\n<td>Arsenic-safe water with DPHE; school health with education ministry</td>\n</tr>\n<tr>\n<td>4. <strong>Appropriate technology</strong></td>\n<td>Scientifically sound, locally adaptable, acceptable, affordable, maintainable by people</td>\n<td>Home-made ORS, MUAC tape, chlorhexidine for cord care</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other principles / strategies often added</strong></p>\n<table>\n<thead>\n<tr>\n<th>Principle</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Focus on prevention and promotion</td>\n<td>Health education, immunisation</td>\n</tr>\n<tr>\n<td>Decentralisation</td>\n<td>Upazila and union-level planning</td>\n</tr>\n<tr>\n<td>Use of health manpower (CHWs)</td>\n<td>CHCPs, health assistants, FWAs</td>\n</tr>\n<tr>\n<td>Integration of services</td>\n<td>Essential Service Package</td>\n</tr>\n<tr>\n<td>Referral system</td>\n<td>CC → UHC → district hospital</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Importance</strong></p>\n<p>These principles make care <strong>essential, accessible, acceptable and affordable</strong>, the basis for Health for All and UHC.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.46","n":46,"part":1,"topic":"PHC","stars":3,"years":["16Ju","16M","13Ju","10Ju","10Ja"],"colleges":"ShSMC (1st Term A2)","asked":"explain equitable distribution of PHC","note":"","kind":"","sub":"","q":"<p>Why equitable distribution is an essential part of PHC? / explain social equity as a principle of PHC / describe equitable distribution of health services / highlight implementation of equitable distribution in Bangladesh.</p>","a":"<p><strong>Equitable distribution: meaning</strong></p>\n<ul>\n<li>First principle of PHC: health services must be shared equally by all people irrespective of their ability to pay; all (rich or poor, urban or rural) must have access.</li>\n<li><strong>Social equity</strong>: equal access for equal need; more resources to those in greater need.</li>\n</ul>\n<p><strong>Why it is essential</strong></p>\n<ol>\n<li>Health services were concentrated in cities and hospitals, where a minority lives → <strong>social injustice</strong>.</li>\n<li><strong>Inverse care law</strong> (Tudor Hart, 1971): availability of good care varies inversely with need.</li>\n<li>The poor and rural carry the <strong>highest burden</strong> of disease and death.</li>\n<li>Health is a <strong>human right</strong>; HFA and UHC are impossible without equity.</li>\n<li>Inequity wastes resources: costly tertiary care for few, no basic care for many.</li>\n<li>Equity improves national indicators fastest (IMR, MMR).</li>\n</ol>\n<p><strong>Implementation in Bangladesh</strong></p>\n<ol>\n<li><strong>Community clinics</strong>: one per ~6,000 rural people, within 30 minutes' walk.</li>\n<li><strong>Union-level facilities</strong> and <strong>Upazila Health Complexes</strong> in every upazila.</li>\n<li><strong>Free or low-cost services</strong>: EPI, essential drugs, FP methods, TB and malaria treatment.</li>\n<li><strong>Outreach</strong>: EPI outreach sites, satellite clinics, domiciliary visits by HA and FWA.</li>\n<li><strong>Pro-poor schemes</strong>: maternal health voucher scheme; Shasthyo Surokhsha Karmasuchi (health card for the poor).</li>\n<li><strong>Urban PHC</strong> for slum dwellers through city corporations and NGOs.</li>\n<li><strong>Special areas</strong>: hill tracts, haor, char and coastal areas.</li>\n<li><strong>Gender equity</strong>: women-friendly services, female health workers.</li>\n</ol>\n<p><strong>Problems</strong></p>\n<p>Vacant posts in rural facilities, high out-of-pocket spending, urban–rural gap.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.47","n":47,"part":1,"topic":"PHC","stars":2,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Distinguish equal and equitable distribution with illustrations.</p>","a":"<p><strong>Equal vs equitable distribution</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Equal distribution</th>\n<th>Equitable distribution</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Meaning</td>\n<td>Same amount of resources to everyone</td>\n<td>Resources according to <strong>need</strong></td>\n</tr>\n<tr>\n<td>Basis</td>\n<td>Sameness</td>\n<td>Fairness / justice</td>\n</tr>\n<tr>\n<td>Assumption</td>\n<td>Everyone starts with the same needs</td>\n<td>Needs differ between people and areas</td>\n</tr>\n<tr>\n<td>Effect on gaps</td>\n<td>Gaps persist or widen</td>\n<td>Gaps narrow</td>\n</tr>\n<tr>\n<td>Concept</td>\n<td>Equality</td>\n<td>Equity</td>\n</tr>\n<tr>\n<td>PHC principle</td>\n<td>Not sufficient</td>\n<td><strong>First principle of PHC</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Illustrations</strong></p>\n<ol>\n<li><strong>Doctors per upazila</strong>: equal = same number for every upazila; equitable = more staff for remote haor, char and hill upazilas with worse indicators.</li>\n<li><strong>Iron-folic acid</strong>: equal = same tablets for all women; equitable = extra supply to pregnant and anaemic women.</li>\n<li><strong>Food support</strong>: equal = same ration to every child; equitable = therapeutic food to severely malnourished children.</li>\n<li><strong>Health budget</strong>: equal per head ignores need; equitable gives more to districts with high IMR and MMR.</li>\n<li><strong>Hospital beds</strong>: equal per city and village is unrealistic; equitable ensures every person can reach basic care (community clinic within 30 minutes' walk).</li>\n</ol>\n<p><strong>Key point</strong></p>\n<p>Equity = equal access for equal need + more for greater need → fair health outcomes.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.48","n":48,"part":1,"topic":"PHC","stars":2,"years":["23Nov","22M","16Ja","12Ja"],"colleges":"MuMC (1st Final A1, 1st Supp A1)","asked":"why home-made ORS is a classic example of appropriate technology in PHC","note":"","kind":"","sub":"","q":"<p>Discuss appropriate technology.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Appropriate technology</strong>: technology that is scientifically sound, adaptable to local needs, and acceptable to those who apply it and to those for whom it is used, and that can be maintained by the people themselves, using resources the community and country can afford (Park).</p>\n<p><strong>Criteria</strong></p>\n<ol>\n<li>Scientifically sound and effective</li>\n<li>Simple; usable by community health workers or families</li>\n<li>Low cost, affordable</li>\n<li>Acceptable (social, cultural)</li>\n<li>Uses local resources; maintainable by people</li>\n<li>Safe</li>\n</ol>\n<p><strong>Examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Appropriate technology</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Diarrhoea</td>\n<td>ORS, home-made salt–sugar (lobon-gur) solution, zinc</td>\n</tr>\n<tr>\n<td>Nutrition</td>\n<td>Growth chart, MUAC tape, iodised salt</td>\n</tr>\n<tr>\n<td>Maternal health</td>\n<td>Clean delivery kit, misoprostol for PPH, partograph</td>\n</tr>\n<tr>\n<td>Newborn care</td>\n<td>Kangaroo mother care, chlorhexidine for cord care</td>\n</tr>\n<tr>\n<td>Water and sanitation</td>\n<td>Tube well, chlorination, sanitary pit latrine</td>\n</tr>\n<tr>\n<td>Immunisation</td>\n<td>Cold chain (ice-lined refrigerators, vaccine carriers), VVM</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Home-made ORS: a classic example</strong></p>\n<ol>\n<li><strong>Scientifically sound</strong>: glucose-coupled sodium absorption replaces water and salt lost in diarrhoea.</li>\n<li><strong>Simple</strong>: a pinch of salt, a fistful of gur or sugar, in about half a litre of clean water; any mother can make it.</li>\n<li><strong>Low cost</strong>: uses salt, gur and water found in every home.</li>\n<li><strong>Acceptable</strong>: familiar ingredients; given by the mother at home.</li>\n<li><strong>Available immediately</strong>: no need to wait for packets or a health facility.</li>\n<li><strong>Effective</strong>: prevents dehydration deaths; Bangladesh scaled it up nationally through mass teaching of mothers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.49","n":49,"part":1,"topic":"PHC","stars":3,"years":["21M","19Nov","13Ju","11Ju"],"colleges":"MMC (2nd Term B5)","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the health care delivery system in Bangladesh / at primary level in Bangladesh / health care set up from upazilla to grass-root level.</p>","a":"<p><strong>Organisation</strong></p>\n<p>Ministry of Health and Family Welfare (MOHFW): two divisions since 2017, Health Services Division; Medical Education and Family Welfare Division.<br />\nDirectorates: <strong>DGHS</strong> (health services), <strong>DGFP</strong> (family planning), DGME (medical education), DGNM (nursing and midwifery), DGDA (drugs).</p>\n<p><strong>Levels of public health care</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Facility</th>\n<th>Main services</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>National / tertiary</td>\n<td>Medical college hospitals, specialised institutes</td>\n<td>Specialist and super-specialist care, teaching, research</td>\n</tr>\n<tr>\n<td>District / secondary</td>\n<td>District hospital, MCWC</td>\n<td>Specialist care, referral</td>\n</tr>\n<tr>\n<td>Upazila / primary (first referral)</td>\n<td><strong>Upazila Health Complex</strong> (31/50 beds)</td>\n<td>Indoor and outdoor care, emergency, EPI, MCH-FP, TB/leprosy, lab, supervision of field staff</td>\n</tr>\n<tr>\n<td>Union</td>\n<td>Union Health and Family Welfare Centre (DGFP), Union Sub-centre / Rural Dispensary (DGHS)</td>\n<td>Outpatient care, MCH-FP, normal delivery, immunisation</td>\n</tr>\n<tr>\n<td>Ward / grass root</td>\n<td><strong>Community clinic</strong> (one per ~6,000 people)</td>\n<td>One-stop health, FP, nutrition services; referral</td>\n</tr>\n<tr>\n<td>Household</td>\n<td>HA, FWA (domiciliary)</td>\n<td>EPI, FP, health education, surveillance</td>\n</tr>\n</tbody>\n</table>\n<p>Facility count (Bangladesh Health Facility Survey 2017): 420 Upazila Health Complexes; 1,275 union sub-centres; 3,924 UH&amp;FWCs (DGFP); 13,442 community clinics.</p>\n<p><strong>Primary-level flow (upazila to grass root)</strong></p>\n<p>Upazila Health Complex → Union facilities → Community clinic → Household (HA, FWA, CHCP)</p>\n<p><strong>Urban PHC</strong>: Local Government Division (city corporations, municipalities) with NGOs.</p>\n<p><strong>Other sectors</strong>: private hospitals and clinics, NGOs (BRAC, icddr,b), informal providers (village doctors, drug sellers).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); Bangladesh Health Facility Survey 2017 (PMC), https://pmc.ncbi.nlm.nih.gov/articles/PMC8424828/table/T2</p>"},{"id":"DU.50","n":50,"part":1,"topic":"PHC","stars":0,"years":["06Ju"],"colleges":"MuMC (1st Final C1, 1st Supp C1)","asked":"what types of health care are given in Mugda Medical College?","note":"","kind":"","sub":"","q":"<p>What are different types of health care services?</p>","a":"<p><strong>Types of health care services</strong></p>\n<p><strong>A. By level</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Description</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Primary</td>\n<td>First contact; essential care near home</td>\n<td>Community clinic, union centres, UHC outpatient</td>\n</tr>\n<tr>\n<td>Secondary</td>\n<td>Referral care; basic specialists</td>\n<td>District hospital</td>\n</tr>\n<tr>\n<td>Tertiary</td>\n<td>Specialised care, teaching, research</td>\n<td>Medical college hospitals (e.g., Mugda Medical College Hospital), specialised institutes</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. By nature of care</strong></p>\n<ol>\n<li><strong>Promotive</strong>: health education, nutrition counselling.</li>\n<li><strong>Preventive</strong>: immunisation, ANC, screening.</li>\n<li><strong>Curative</strong>: outpatient, inpatient, emergency, surgery.</li>\n<li><strong>Rehabilitative</strong>: physiotherapy, prosthesis, counselling.</li>\n<li><strong>Palliative</strong>: pain relief, end-of-life care.</li>\n</ol>\n<p><strong>C. By setting</strong></p>\n<p>Hospital-based (OPD, IPD, emergency, ICU); community-based (outreach, satellite clinics, domiciliary visits); school, workplace and mobile services; telemedicine.</p>\n<p><strong>D. By provider</strong></p>\n<p>Public (MOHFW); private; NGO; informal (village doctors, drug sellers); traditional (Ayurvedic, Unani, homoeopathic).</p>\n<p><strong>E. Special services</strong></p>\n<p>MCH and family planning; school health; occupational health; geriatric care; mental health; diagnostic (lab, imaging); blood transfusion; ambulance and referral.</p>\n<p><strong>Mugda Medical College Hospital (tertiary)</strong>: outpatient, inpatient and emergency care in major specialties, ICU, diagnostic and imaging services, EPI and MCH corner, referral care, teaching and training.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.51","n":51,"part":1,"topic":"PHC","stars":0,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the achievements and constraints of PHC implementation in Bangladesh since 1978.</p>","a":"<p><strong>Achievements (since Alma-Ata, 1978)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Achievement</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Child survival</td>\n<td>U5MR 146 (1990) → 46 (2014); MDG 4 met; U5MR 33 and IMR 27 per 1000 LB (SVRS 2023)</td>\n</tr>\n<tr>\n<td>Life expectancy</td>\n<td>72.3 years (SVRS 2023)</td>\n</tr>\n<tr>\n<td>Fertility</td>\n<td>Fall to TFR 2.17 (SVRS 2023) through family planning</td>\n</tr>\n<tr>\n<td>Immunisation</td>\n<td>EPI since 1979; smallpox gone (last case 1975); polio-free (SEAR certified 2014)</td>\n</tr>\n<tr>\n<td>Disease elimination</td>\n<td>Lymphatic filariasis (May 2023) and kala-azar (Oct 2023; first country) eliminated as public health problems (WHO)</td>\n</tr>\n<tr>\n<td>Diarrhoea</td>\n<td>ORS and home-made ORS; zinc scale-up</td>\n</tr>\n<tr>\n<td>Infrastructure</td>\n<td>Community clinics, union centres and UHCs nationwide</td>\n</tr>\n<tr>\n<td>Workforce</td>\n<td>CHCPs, HAs, FWAs, NGO volunteers</td>\n</tr>\n<tr>\n<td>Partnership</td>\n<td>Strong NGO sector (BRAC, icddr,b)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Constraints</strong></p>\n<ol>\n<li><strong>Human resources</strong>: vacant posts, absenteeism, few specialists at upazila level.</li>\n<li><strong>Maldistribution</strong>: urban concentration of doctors and facilities.</li>\n<li><strong>Financing</strong>: low public spending; high <strong>out-of-pocket</strong> payment.</li>\n<li><strong>Weak referral</strong> and frequent self-referral.</li>\n<li><strong>Quality gaps</strong>: drugs, equipment, laboratory support.</li>\n<li><strong>Urban PHC</strong> weak, especially for slum dwellers.</li>\n<li><strong>Double burden</strong>: rising NCDs with remaining infections and malnutrition.</li>\n<li><strong>Coverage gaps</strong>: measles-rubella first dose fell to 86% (CES 2023) → large measles outbreak in 2026.</li>\n<li>Weak intersectoral coordination and community participation in some areas.</li>\n<li>Unregulated private sector and informal providers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); BBS SVRS 2023 (The Financial Express, 2024), https://today.thefinancialexpress.com.bd/print/life-expectancy-falls-in-bd-bbs-1724781053; WHO, 2023, https://www.who.int/news/item/31-10-2023-bangladesh-achieves-historic-milestone-by-eliminating-kala-azar-as-a-public-health-problem</p>"},{"id":"DU.52","n":52,"part":1,"topic":"PHC","stars":3,"years":["24M","23Nov","20Nov","17M","16Ju","13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist health care / state the services provided at community clinic / role of community clinic at grass-root level of Bangladesh.</p>","a":"<p><strong>Community clinic (CC)</strong></p>\n<ul>\n<li>Ward-level, first-contact government facility; one per ~6,000 rural people within 30 minutes' walk.</li>\n<li><strong>One-stop</strong> outlet for health, family planning and nutrition.</li>\n<li>Run by a <strong>Community Health Care Provider (CHCP)</strong>, supported by the Health Assistant and Family Welfare Assistant; managed with the community (Community Group).</li>\n</ul>\n<p><strong>Services</strong></p>\n<ol>\n<li><strong>Maternal care</strong>: ANC, PNC, danger-sign identification, iron-folic acid; normal delivery in selected CCs.</li>\n<li><strong>Family planning</strong>: pills, condoms, injectables; counselling.</li>\n<li><strong>Child health</strong>: IMCI, growth monitoring, IYCF counselling.</li>\n<li><strong>Immunisation</strong>: EPI outreach site; vitamin A campaigns.</li>\n<li><strong>Nutrition</strong>: counselling, MUAC screening, micronutrient supplements.</li>\n<li><strong>Treatment</strong> of minor ailments and first aid; free essential drugs.</li>\n<li><strong>NCD screening</strong>: blood pressure, diabetes.</li>\n<li><strong>Health education</strong>: hygiene, sanitation, safe water, adolescent health.</li>\n<li><strong>Surveillance</strong>: reporting of births, deaths, notifiable diseases.</li>\n<li><strong>Referral</strong> of complicated cases to union, UHC and district hospital.</li>\n<li><strong>Record keeping</strong> and online reporting.</li>\n</ol>\n<p><strong>Role at grass-root level</strong></p>\n<ol>\n<li>Brings PHC to the <strong>doorstep</strong> of rural people.</li>\n<li>Reduces distance, cost and delay.</li>\n<li>Serves mainly <strong>women and children</strong>.</li>\n<li>Model of <strong>community participation</strong> (donated land, community groups).</li>\n<li>Strengthens <strong>referral</strong> and continuity of care.</li>\n<li>Supports national programmes (EPI, FP, nutrition, TB) and progress toward UHC.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); Daily Observer (bdnews24), 2025, https://www.observerbd.com/news/540274</p>"},{"id":"DU.53","n":53,"part":1,"topic":"PHC","stars":3,"years":["22M","16Nov"],"colleges":"DMC (1st Assess D4, 2nd Assess D4); MuMC (2nd Final B2)","asked":"functions / primary responsibilities / 5 duties of UH&FPO","note":"","kind":"","sub":"","q":"<p>Mention the duties of a community physician at Upazila level.</p>","a":"<p><strong>Upazila Health and Family Planning Officer (UH&amp;FPO): community physician at upazila level</strong></p>\n<p><strong>A. Administrative</strong></p>\n<ol>\n<li>Head of the <strong>Upazila Health Complex</strong> and all upazila health services.</li>\n<li>Supervises doctors, nurses, SACMOs, HIs, AHIs, HAs, CHCPs and community clinics.</li>\n<li>Planning, budgeting, logistics, drugs and equipment management.</li>\n<li>Coordination with upazila parishad, UNO, Upazila Family Planning Officer, education, DPHE and NGOs (<strong>intersectoral</strong>).</li>\n<li>Chairs or joins upazila health committees.</li>\n</ol>\n<p><strong>B. Public health / preventive</strong></p>\n<ol>\n<li>Implements national programmes: EPI, TB, leprosy, malaria, dengue, nutrition, NCD, MNCH, school health.</li>\n<li><strong>Disease surveillance</strong> and notification; outbreak investigation and control.</li>\n<li>Health education and community mobilisation.</li>\n<li>Environmental sanitation and safe water promotion (with DPHE).</li>\n<li>Disaster preparedness and emergency response.</li>\n</ol>\n<p><strong>C. Clinical</strong></p>\n<ol>\n<li>Ensures outpatient, inpatient, emergency and referral services.</li>\n<li>Quality of care, infection prevention, rational drug use.</li>\n</ol>\n<p><strong>D. Information and evaluation</strong></p>\n<ol>\n<li>Collection and reporting of health data (HMIS/DHIS2); monthly reports to the civil surgeon.</li>\n<li>Monitoring, supervision and evaluation of services.</li>\n</ol>\n<p><strong>E. Training and research</strong></p>\n<p>Training of staff; supervision of interns; operational research.</p>\n<p><strong>F. Legal</strong></p>\n<p>Medicolegal duties (injury and post-mortem reports where applicable), birth and death certificates, enforcement of public health laws.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community; Health Planning and Management).</p>"},{"id":"DU.54","n":54,"part":1,"topic":"PHC","stars":3,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the role of PHC in prevention, control &amp; treatment of diarrhoeal diseases in Bangladesh.</p>","a":"<p><strong>PHC elements in diarrhoeal disease control</strong></p>\n<table>\n<thead>\n<tr>\n<th>PHC element</th>\n<th>Role in diarrhoea</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Health education</td>\n<td>Hand-washing with soap, food hygiene, safe disposal of child faeces, home-made ORS, danger signs</td>\n</tr>\n<tr>\n<td>Food and nutrition</td>\n<td>Exclusive breastfeeding to 6 months, complementary feeding, continued feeding during diarrhoea, vitamin A</td>\n</tr>\n<tr>\n<td>Safe water and sanitation</td>\n<td>Tube wells, water treatment, sanitary latrines, ending open defecation</td>\n</tr>\n<tr>\n<td>MCH</td>\n<td>IMCI; care of young children; growth monitoring</td>\n</tr>\n<tr>\n<td>Immunisation</td>\n<td>Measles vaccine (reduces post-measles diarrhoea); oral cholera vaccine in outbreaks and camps</td>\n</tr>\n<tr>\n<td>Local endemic disease control</td>\n<td>Cholera surveillance, outbreak response</td>\n</tr>\n<tr>\n<td>Treatment of common diseases</td>\n<td><strong>ORS + zinc</strong> + continued feeding; antibiotics only for dysentery and cholera; IV fluids for severe dehydration</td>\n</tr>\n<tr>\n<td>Essential drugs</td>\n<td>ORS packets, zinc tablets at community clinics and UHCs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Prevention, control and treatment</strong></p>\n<ol>\n<li><strong>Prevention</strong>: water, sanitation, hygiene (WASH), breastfeeding, nutrition, immunisation.</li>\n<li><strong>Control</strong>: surveillance, early detection of outbreaks, chlorination, health education.</li>\n<li><strong>Treatment</strong>: case management at home (ORS), community clinics (IMCI), UHC and hospitals (severe cases).</li>\n</ol>\n<p><strong>Principles applied</strong></p>\n<p>Community participation (mothers making ORS); appropriate technology (ORS, zinc); intersectoral coordination (DPHE, local government); equitable distribution (free ORS).</p>\n<p><strong>Bangladesh</strong></p>\n<p>ORS pioneered by icddr,b; by 2014 about 80% of children with diarrhoea received ORS and 34% ORS + zinc.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases; Health Care of the Community); J Glob Health, 2019, https://jogha.org/documents/issue201901/jogh-09-010503.htm</p>"},{"id":"DU.55","n":55,"part":1,"topic":"PHC","stars":0,"years":[],"colleges":"SSMC (1st Supp A2)","asked":"","note":"","kind":"","sub":"","q":"<p>Community clinic is an excellent example of community participation – explain.</p>","a":"<p><strong>Community clinic: excellent example of community participation</strong></p>\n<p><strong>1. Planning and establishment</strong></p>\n<ul>\n<li>Built on <strong>land donated</strong> by the local community.</li>\n<li>Site chosen with local people for easy access.</li>\n</ul>\n<p><strong>2. Management</strong></p>\n<ul>\n<li><strong>Community Group (CG)</strong>: local representatives (union parishad member, teachers, women, donors) manage the clinic, monitor attendance, solve problems.</li>\n<li>Three <strong>Community Support Groups (CSGs)</strong>: create awareness, mobilise people, help referral, raise local funds.</li>\n</ul>\n<p><strong>3. Resource contribution</strong></p>\n<ul>\n<li>Local donations (money, materials, labour) for repairs, furniture, water, electricity.</li>\n<li>Volunteers support campaigns.</li>\n</ul>\n<p><strong>4. Use and demand</strong></p>\n<ul>\n<li>Community mobilises women, children and the poor to use services.</li>\n<li>Feedback improves service quality and timing.</li>\n</ul>\n<p><strong>5. Accountability</strong></p>\n<ul>\n<li>Community monitors staff presence and drug supply.</li>\n</ul>\n<p><strong>6. Partnership model</strong></p>\n<ul>\n<li>Government provides building, staff (CHCP), drugs, logistics; community provides land and management support → <strong>public–community partnership</strong>.</li>\n</ul>\n<p><strong>Why it fits the PHC principle</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature of community participation</th>\n<th>Community clinic</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Involvement in planning</td>\n<td>Site selection, land donation</td>\n</tr>\n<tr>\n<td>Involvement in implementation</td>\n<td>CG and CSGs</td>\n</tr>\n<tr>\n<td>Involvement in maintenance</td>\n<td>Local funds and repairs</td>\n</tr>\n<tr>\n<td>Use of local resources</td>\n<td>Land, money, volunteers</td>\n</tr>\n<tr>\n<td>Self-reliance</td>\n<td>Community &quot;owns&quot; the clinic</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.56","n":56,"part":1,"topic":"PHC","stars":0,"years":[],"colleges":"MuMC (1st Final A1, 1st Supp A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the importance of the health team.</p>","a":"<p><strong>Health team</strong></p>\n<p>A group of persons with different skills who share a common health goal, each contributing according to competence, working in coordination (doctor, nurse, health assistant, FWA, CHCP, SACMO, health inspector, lab technician, pharmacist, community volunteers).</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li><strong>Comprehensive care</strong>: no single person has all skills for promotive, preventive, curative and rehabilitative care.</li>\n<li><strong>Coverage</strong>: reaches large populations, homes and remote areas.</li>\n<li><strong>Efficient use of manpower</strong>: tasks delegated to the right level (task-sharing); doctor's time saved for complex cases.</li>\n<li><strong>Cost-effective</strong>: lower-cost workers deliver routine services.</li>\n<li><strong>Continuity of care</strong>: from home to community clinic to hospital, through referral.</li>\n<li><strong>Implements national programmes</strong>: EPI, FP, TB, malaria, nutrition, NCDs.</li>\n<li><strong>Community participation</strong>: field workers link people with health services.</li>\n<li><strong>Better quality and safety</strong>: mutual support, supervision, shared decisions.</li>\n<li><strong>Intersectoral action</strong>: includes teachers, sanitary workers, social workers.</li>\n<li><strong>Training and supervision</strong>: senior members guide juniors.</li>\n<li><strong>Data and surveillance</strong>: field staff collect information for planning.</li>\n</ol>\n<p><strong>Requirements for an effective team</strong></p>\n<p>Common goal; clear roles; good leadership; communication; mutual respect; supervision; training; adequate resources.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.57","n":57,"part":1,"topic":"PHC","stars":0,"years":[],"colleges":"MuMC (2nd Final D1)","asked":"","note":"","kind":"","sub":"","q":"<p>“Community health workers are at the heart of a stronger health system” – justify.</p>","a":"<p><strong>Community health workers (CHWs)</strong></p>\n<p>Health workers chosen from and working in their own communities, with short training, providing promotive, preventive and basic curative care and linking people with the health system.<br />\nBangladesh: Health Assistants, Family Welfare Assistants, CHCPs, NGO volunteers (e.g., BRAC <em>shasthya shebika</em>).</p>\n<p><strong>Justification</strong></p>\n<ol>\n<li><strong>Reach</strong>: deliver care to homes in remote, poor and hard-to-reach areas → <strong>equity</strong>.</li>\n<li><strong>First contact</strong>: implement PHC at the grass root.</li>\n<li><strong>Trust and acceptability</strong>: same language, culture and community.</li>\n<li><strong>Cost-effective</strong>: low cost, high coverage; free scarce doctors for complex care.</li>\n<li><strong>Proven impact</strong>: ORS, family planning, EPI, vitamin A, TB DOTS, malaria and kala-azar control.</li>\n<li><strong>Health education and behaviour change</strong> in families.</li>\n<li><strong>Surveillance</strong>: early reporting of outbreaks, births, deaths.</li>\n<li><strong>Community participation</strong>: mobilise people and resources.</li>\n<li><strong>Referral</strong>: identify danger signs and refer early.</li>\n<li><strong>Resilience</strong>: maintain services during disasters and epidemics.</li>\n<li><strong>UHC</strong>: essential for reaching everyone with essential services (WHO guideline on CHW programmes, 2018).</li>\n</ol>\n<p><strong>Conditions for success</strong></p>\n<p>Proper selection, training, supervision, supplies, fair pay, career path, integration into the health system.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); WHO guideline on health policy and system support to optimize CHW programmes, 2018.</p>"},{"id":"DU.58","n":58,"part":1,"topic":"PHC","stars":0,"years":[],"colleges":"MuMC (2nd Final B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Why is the Upazila Health Complex called a “complex”?</p>","a":"<p><strong>Why &quot;complex&quot;</strong></p>\n<p>The Upazila Health Complex is not just a hospital; it is a <strong>combination (complex) of many health facilities, services and offices in one campus</strong> serving the whole upazila.</p>\n<p><strong>Components</strong></p>\n<ol>\n<li><strong>Hospital</strong>: indoor (31/50 beds), outpatient, emergency, operation theatre, labour room.</li>\n<li><strong>Diagnostic services</strong>: laboratory, X-ray, ECG.</li>\n<li><strong>Preventive and public health units</strong>: EPI, TB and leprosy, malaria, nutrition, surveillance.</li>\n<li><strong>MCH and family planning</strong> services (with the Upazila Family Planning Office).</li>\n<li><strong>Dental, eye and other units</strong> where staffed.</li>\n<li><strong>Administrative office</strong> of the UH&amp;FPO; stores; records and HMIS.</li>\n<li><strong>Training</strong> facilities for staff and community workers.</li>\n<li><strong>Residential quarters</strong> for doctors, nurses and staff.</li>\n<li><strong>Supervisory base</strong> for field staff (HI, AHI, HA) and community clinics.</li>\n<li><strong>Ambulance and referral</strong> services.</li>\n</ol>\n<p><strong>Functions combined</strong></p>\n<p>Curative + preventive + promotive + rehabilitative + administrative + training + supervision → <strong>integrated, comprehensive care</strong>.</p>\n<p>Hence it is a &quot;complex&quot; rather than a single hospital.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.59","n":59,"part":1,"topic":"PHC","stars":0,"years":[],"colleges":"DMC (2nd Assess D4)","asked":"","note":"","kind":"","sub":"","q":"<p>What is the role of a Health Assistant as domiciliary worker in the community?</p>","a":"<p><strong>Health Assistant (HA)</strong></p>\n<p>Male or female domiciliary field worker of DGHS at <strong>ward level</strong>; supervised by the Assistant Health Inspector → Health Inspector → UH&amp;FPO.</p>\n<p><strong>Roles in the community</strong></p>\n<ol>\n<li><strong>Immunisation (EPI)</strong>: registers eligible children and women; vaccinates at outreach sites; tracks defaulters.</li>\n<li><strong>Surveillance</strong>: reports AFP, measles, neonatal tetanus, diarrhoea outbreaks and other notifiable diseases.</li>\n<li><strong>Health education</strong>: hygiene, safe water, sanitation, breastfeeding, nutrition, danger signs.</li>\n<li><strong>Communicable disease control</strong>: TB and leprosy case finding and treatment follow-up; malaria and kala-azar activities in endemic areas; dengue source reduction.</li>\n<li><strong>Vitamin A, deworming</strong> and other campaigns.</li>\n<li><strong>MCH</strong>: identifies pregnant women, encourages ANC and facility delivery.</li>\n<li><strong>School health</strong>: health education and screening in schools.</li>\n<li><strong>Registration</strong>: births, deaths, pregnancies; household records.</li>\n<li><strong>Community clinic support</strong>: works at the CC on scheduled days.</li>\n<li><strong>Referral</strong> of sick persons to CC, union centre or UHC.</li>\n<li><strong>Disaster and epidemic response</strong>: chlorination, ORS distribution.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.60","n":60,"part":1,"topic":"PHC","stars":0,"years":[],"colleges":"MMC (2nd Term B5)","asked":"","note":"","kind":"","sub":"","q":"<p>Which one is the grass-root level hospital of Bangladesh?</p>","a":"<p><strong>Answer</strong></p>\n<p><strong>Upazila Health Complex (UHC)</strong> is the grass-root level (first-level) <strong>hospital</strong> of Bangladesh.</p>\n<p><strong>Reasons</strong></p>\n<ol>\n<li>Lowest level with <strong>indoor (inpatient) beds</strong> (31/50 beds) in every upazila.</li>\n<li><strong>First referral</strong> level for community clinics and union facilities.</li>\n<li>Provides emergency care, normal and assisted delivery, minor surgery, laboratory and X-ray.</li>\n<li>Integrates curative, preventive and family planning services.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.61","n":61,"part":1,"topic":"Bhore Committee","stars":0,"years":["06M","05M","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is Bhore committee? / Discuss the concept, objectives and recommendations of Bhore committee.</p>","a":"<p><strong>What it is</strong></p>\n<p><strong>Health Survey and Development Committee</strong> (India), 1943–1946, chaired by <strong>Sir Joseph Bhore</strong>; reviewed health conditions of undivided British India (including present Bangladesh) and planned future health services. Report: 1946.</p>\n<p><strong>Concept</strong></p>\n<p>Health services should be <strong>comprehensive</strong>, <strong>integrated</strong> (preventive + curative) and reach the <strong>rural</strong> population through health centres; doctors should be <strong>social physicians</strong>.</p>\n<p><strong>Objectives</strong></p>\n<ol>\n<li>Survey the existing health situation and organisation.</li>\n<li>Recommend future development of health services.</li>\n</ol>\n<p><strong>Recommendations</strong></p>\n<ol>\n<li><strong>Integration of preventive and curative services</strong> at all administrative levels.</li>\n<li><strong>Primary health centres</strong> in two stages:\n<ul>\n<li><strong>Short-term</strong>: one PHC per 40,000 population, with 2 doctors, 1 nurse, 4 public health nurses, 4 midwives, 4 trained dais, 2 sanitary inspectors, 2 health assistants, 1 pharmacist and 15 class IV staff; secondary health centres to support and supervise PHCs.</li>\n<li><strong>Long-term (&quot;3 million plan&quot;)</strong>: primary health units with 75-bed hospitals for 10,000–20,000 people; secondary units with 650-bed hospitals; district hospitals with 2,500 beds.</li>\n</ul>\n</li>\n<li><strong>Medical education</strong>: 3 months' training in preventive and social medicine to prepare &quot;<strong>social physicians</strong>&quot;.</li>\n</ol>\n<p><strong>Significance</strong></p>\n<p>Basis of rural health centres and PHC in the subcontinent; precursor of thana (upazila) health complexes; introduced the idea of comprehensive health care.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.62","n":62,"part":1,"topic":"Concept of Disease","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Identify diseases of social origin.</p>","a":"<p><strong>Diseases of social origin</strong></p>\n<p>Diseases whose main causes are social conditions (poverty, illiteracy, overcrowding, unemployment, customs, lifestyle) rather than biology alone.</p>\n<table>\n<thead>\n<tr>\n<th>Social factor</th>\n<th>Diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Poverty, overcrowding, malnutrition</td>\n<td>Tuberculosis, leprosy, protein-energy malnutrition, anaemia</td>\n</tr>\n<tr>\n<td>Poor sanitation and unsafe water</td>\n<td>Cholera, typhoid, diarrhoea, hepatitis A and E, worm infestations</td>\n</tr>\n<tr>\n<td>Sexual behaviour, migration</td>\n<td>STIs, HIV/AIDS</td>\n</tr>\n<tr>\n<td>Substance use</td>\n<td>Alcoholism, drug addiction, tobacco-related cancers and COPD</td>\n</tr>\n<tr>\n<td>Urban lifestyle, affluence</td>\n<td>Obesity, diabetes, hypertension, coronary heart disease</td>\n</tr>\n<tr>\n<td>Social stress, family breakdown</td>\n<td>Depression, anxiety, suicide, juvenile delinquency</td>\n</tr>\n<tr>\n<td>Industrialisation, traffic</td>\n<td>Occupational diseases, road traffic accidents</td>\n</tr>\n<tr>\n<td>Customs and gender inequality</td>\n<td>Child marriage → maternal deaths; female malnutrition; domestic violence</td>\n</tr>\n<tr>\n<td>Neglect and violence</td>\n<td>Child abuse, battered baby syndrome</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine; Medicine and Social Sciences).</p>"},{"id":"DU.63","n":63,"part":1,"topic":"Concept of Disease","stars":3,"years":["16Ju","14Ju","13Ju","11Ja","10Ja"],"colleges":"SSMC (1st Supp D4); ShSMC (1st Term A1); MMC (1st Supp A4)","asked":"","note":"","kind":"","sub":"","q":"<p>What does natural history of disease imply? / Describe the natural history of disease.</p>","a":"<p><strong>Meaning</strong></p>\n<p><strong>Natural history of disease</strong>: the way a disease evolves over time in a person, from the earliest stage of its pre-pathogenesis to its termination as recovery, disability or death, <strong>without any treatment or intervention</strong>.</p>\n<p><strong>Phases</strong></p>\n<table>\n<thead>\n<tr>\n<th>Phase</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Pre-pathogenesis</strong></td>\n<td>Before man is involved; disease agent present in the environment; interaction of <strong>agent, host and environment</strong> creates the stimulus; person is &quot;at risk&quot;</td>\n</tr>\n<tr>\n<td><strong>2. Pathogenesis</strong></td>\n<td>Begins with entry of the agent into the host; agent multiplies, tissue changes occur</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Stages of pathogenesis</strong></p>\n<p>Stimulus → Early pathogenesis (incubation / pre-symptomatic) → Early discernible lesions → Advanced disease → Convalescence → Outcome (recovery, disability, defect, chronic state, death)</p>\n<ul>\n<li><strong>Clinical horizon</strong>: line separating subclinical from clinical disease.</li>\n<li>Infectious diseases: incubation period; chronic diseases: latent period.</li>\n</ul>\n<p><strong>Levels of prevention along natural history (Leavell and Clark)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Level</th>\n<th>Mode of intervention</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Pre-pathogenesis</td>\n<td>Primary prevention</td>\n<td>Health promotion; specific protection</td>\n</tr>\n<tr>\n<td>Early pathogenesis</td>\n<td>Secondary prevention</td>\n<td>Early diagnosis and treatment</td>\n</tr>\n<tr>\n<td>Late pathogenesis</td>\n<td>Tertiary prevention</td>\n<td>Disability limitation; rehabilitation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Implications / uses</strong></p>\n<ol>\n<li>Basis of the <strong>levels of prevention</strong>.</li>\n<li>Helps plan <strong>screening</strong> (detect early, pre-symptomatic disease).</li>\n<li>Shows where the <strong>iceberg</strong> (hidden disease) lies.</li>\n<li>Natural history of chronic diseases is best studied by <strong>cohort studies</strong>.</li>\n<li>Helps predict prognosis and evaluate interventions.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.64","n":64,"part":1,"topic":"Concept of Disease","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define miasmatic theory of disease.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Miasmatic theory</strong>: the belief that disease is caused by <strong>&quot;miasma&quot;</strong> (bad air), foul-smelling, poisonous vapours rising from decaying organic matter, filth, sewage, marshes and swamps.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.65","n":65,"part":1,"topic":"Concept of Disease","stars":3,"years":["13Ju"],"colleges":"MuMC (1st Final D2)","asked":"modern concept of disease causation with suitable examples","note":"","kind":"","sub":"","q":"<p>State multifactorial causation of disease. What is self care?</p>","a":"<p><strong>Multifactorial causation</strong></p>\n<ul>\n<li>Disease results from the <strong>interaction of many factors</strong> (agent, host, environment, lifestyle), not a single cause.</li>\n<li>Early proponent: <strong>Pettenkofer</strong> of Munich (19th century).</li>\n<li><strong>Web of causation</strong> (MacMahon and Pugh): a chain of interlinked factors; removing some links can prevent disease.</li>\n<li>Especially relevant to <strong>non-communicable diseases</strong>; also explains infections (agent is necessary but not sufficient).</li>\n</ul>\n<p><strong>Self-care</strong></p>\n<ul>\n<li><strong>Definition (WHO, 2019)</strong>: the ability of individuals, families and communities to promote health, prevent disease, maintain health, and cope with illness and disability with or without the support of a health worker.</li>\n<li>Park: activities people undertake to promote their own health, prevent disease, limit illness and restore health, using their own knowledge and skills.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.66","n":66,"part":1,"topic":"Concept of Disease","stars":3,"years":["24Nov","16Nov","13Ja","07Ja","06Ja"],"colleges":"SSMC (1st Supp A4)","asked":"","note":"","kind":"","sub":"","q":"<p>What is epidemiological / ecological triad? Briefly describe it in disease causation (also: discuss mode of transmission of disease).</p>","a":"<p><strong>Epidemiological (ecological) triad</strong></p>\n<p>Disease results from interaction of three components:</p>\n<p>Agent ↔ Host ↔ Environment</p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Meaning</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Agent</strong></td>\n<td>Factor whose presence (or absence) is needed for disease</td>\n<td>Biological (bacteria, viruses), nutrient, physical, chemical, mechanical, social agents</td>\n</tr>\n<tr>\n<td><strong>Host</strong></td>\n<td>Human (or animal) who harbours the disease</td>\n<td>Age, sex, genetics, immunity, nutrition, behaviour, occupation</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>All external conditions influencing agent and host</td>\n<td>Physical (climate, water), biological (vectors, animals), psychosocial (poverty, customs)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Role in disease causation</strong></p>\n<ol>\n<li>Health = <strong>equilibrium</strong> among agent, host and environment.</li>\n<li>Disease = <strong>imbalance</strong>: more virulent agent, more susceptible host, or environment favouring agent.</li>\n<li>Environment links agent and host (e.g., stagnant water → mosquitoes → malaria).</li>\n<li>Model suits <strong>communicable diseases</strong>; for NCDs the <strong>web of causation</strong> is preferred.</li>\n<li>Prevention can act on any arm: kill agent, protect host, modify environment.</li>\n</ol>\n<p><strong>Example: cholera</strong></p>\n<p>Agent: <em>Vibrio cholerae</em> | Host: low gastric acidity, malnutrition, blood group O | Environment: contaminated water, poor sanitation, floods.</p>\n<p><strong>Modes of transmission</strong></p>\n<table>\n<thead>\n<tr>\n<th>Direct</th>\n<th>Indirect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Direct contact (STIs, skin infections)</td>\n<td>Vehicle-borne (water, food, blood)</td>\n</tr>\n<tr>\n<td>Droplet infection (measles, influenza)</td>\n<td>Vector-borne: mechanical, biological (propagative, cyclo-propagative, cyclo-developmental)</td>\n</tr>\n<tr>\n<td>Contact with soil (tetanus, hookworm)</td>\n<td>Airborne (droplet nuclei, dust)</td>\n</tr>\n<tr>\n<td>Inoculation into skin or mucosa (rabies)</td>\n<td>Fomite-borne (towels, utensils)</td>\n</tr>\n<tr>\n<td>Transplacental (rubella, HIV, syphilis)</td>\n<td>Unclean hands and fingers</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Principles of Epidemiology).</p>"},{"id":"DU.67","n":67,"part":1,"topic":"Concept of Disease","stars":3,"years":["22Nov","21M","19Nov","19M","16Ja","15Ja","05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define / classify / describe disease agents with examples; name the agents responsible for disease causation (also: how clinical medicine differs from community medicine).</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Disease agent</strong>: a substance, living or non-living, or a force, tangible or intangible, whose excessive presence or relative lack may initiate or perpetuate a disease process.</p>\n<p><strong>Classification of agents (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Agent</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Biological</strong></td>\n<td>Viruses (measles), rickettsiae (typhus), bacteria (TB), fungi (candida), protozoa (malaria), metazoa (hookworm)</td>\n</tr>\n<tr>\n<td>2. <strong>Nutrient</strong></td>\n<td>Deficiency or excess of protein, fat, carbohydrate, vitamins, minerals, water (kwashiorkor, rickets, obesity)</td>\n</tr>\n<tr>\n<td>3. <strong>Physical</strong></td>\n<td>Heat, cold, humidity, pressure, radiation, electricity, sound (heat stroke, deafness)</td>\n</tr>\n<tr>\n<td>4. <strong>Chemical: endogenous</strong></td>\n<td>Accumulated urea (uraemia), bilirubin (jaundice), ketones, uric acid (gout), calcium carbonate (stones)</td>\n</tr>\n<tr>\n<td>4. <strong>Chemical: exogenous</strong></td>\n<td>Allergens, metals (arsenic, lead), fumes, dust, gases, pesticides</td>\n</tr>\n<tr>\n<td>5. <strong>Mechanical</strong></td>\n<td>Chronic friction, injuries, fractures, sprains, accidents</td>\n</tr>\n<tr>\n<td>6. <strong>Absence or insufficiency or excess of a factor necessary to health</strong></td>\n<td>Hormones (insulin → diabetes), enzymes, chromosomal factors (Down syndrome), immunological factors (agammaglobulinaemia), structure (congenital heart defect)</td>\n</tr>\n<tr>\n<td>7. <strong>Social</strong></td>\n<td>Poverty, smoking, alcohol and drug abuse, unhealthy lifestyle, social isolation, maternal deprivation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Responsible agent vs sufficient cause</strong></p>\n<p>An agent is usually <strong>necessary but not sufficient</strong>; host and environment decide whether disease develops.</p>\n<p><strong>Clinical vs community medicine (brief)</strong></p>\n<p>Clinical medicine finds the agent in a patient and treats it; community medicine studies agents, host and environment in populations and controls their spread.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.68","n":68,"part":1,"topic":"Concept of Disease","stars":1,"years":["07Ju","05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is meant by risk factor?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Risk factor</strong>: an attribute or exposure that is significantly associated with the development of a disease (Park). Its presence increases the probability of disease; its removal reduces it.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.69","n":69,"part":1,"topic":"Concept of Disease","stars":3,"years":["26M","24Nov","22M","20Nov","17Nov","16Nov","16Ja"],"colleges":"SSMC (1st Supp A4); MuMC (1st Final D1, 1st Supp D1)","asked":"","note":"","kind":"","sub":"","q":"<p>Describe the concept of the disease cycle / mention six stages / briefly discuss the stages / draw and label the disease cycle and explain its uses.</p>","a":"<p><strong>Concept</strong></p>\n<p>The <strong>disease cycle (chain of infection)</strong>: the sequence of links by which an infectious agent leaves one host and infects another. Infection continues only if every link is present; <strong>breaking any link stops transmission</strong>.</p>\n<p><strong>Six stages (links)</strong></p>\n<p>Infectious agent → Reservoir / source → Portal of exit → Mode of transmission → Portal of entry → Susceptible host → (back to agent/reservoir)</p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Meaning</th>\n<th>Example (TB)</th>\n<th>Control measure</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Infectious agent</td>\n<td>Organism causing disease</td>\n<td><em>M. tuberculosis</em></td>\n<td>Early diagnosis, treatment (DOTS)</td>\n</tr>\n<tr>\n<td>2. Reservoir / source</td>\n<td>Where the agent lives and multiplies</td>\n<td>Sputum-positive patient</td>\n<td>Case finding, isolation, treatment</td>\n</tr>\n<tr>\n<td>3. Portal of exit</td>\n<td>Route by which agent leaves</td>\n<td>Respiratory tract (cough)</td>\n<td>Cough etiquette, masks</td>\n</tr>\n<tr>\n<td>4. Mode of transmission</td>\n<td>How agent reaches new host</td>\n<td>Droplet nuclei (airborne)</td>\n<td>Ventilation, sunlight, UV</td>\n</tr>\n<tr>\n<td>5. Portal of entry</td>\n<td>Route into new host</td>\n<td>Respiratory tract</td>\n<td>Masks (N95) for health workers</td>\n</tr>\n<tr>\n<td>6. Susceptible host</td>\n<td>Person who can be infected</td>\n<td>Malnourished, HIV-positive</td>\n<td>BCG, nutrition, TB preventive therapy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Uses</strong></p>\n<ol>\n<li>Explains how infection spreads.</li>\n<li>Identifies the <strong>weakest link</strong> to target control.</li>\n<li>Guides <strong>infection prevention</strong> in hospitals (hand hygiene, sterilisation, isolation).</li>\n<li>Basis of the three control approaches: <strong>control of reservoir, interruption of transmission, protection of susceptible</strong>.</li>\n<li>Helps outbreak investigation and health education.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology; Concept of Health and Disease).</p>"},{"id":"DU.70","n":70,"part":1,"topic":"Concept of Disease","stars":3,"years":["24Nov","12Ju"],"colleges":"SSMC (1st Supp D4); ShSMC (1st Term A1); MuMC (1st Final B2)","asked":"epidemiological importance of understanding the iceberg of disease","note":"","kind":"","sub":"","q":"<p>What do you mean by iceberg of disease? / Briefly describe the iceberg phenomenon / explain its importance.</p>","a":"<p><strong>Iceberg of disease</strong></p>\n<p>A concept comparing disease in a community to an iceberg:</p>\n<table>\n<thead>\n<tr>\n<th>Part</th>\n<th>Represents</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Floating tip</strong> (visible)</td>\n<td>Clinical cases seen by doctors</td>\n</tr>\n<tr>\n<td><strong>Waterline</strong></td>\n<td>Line between apparent and inapparent disease</td>\n</tr>\n<tr>\n<td><strong>Submerged mass</strong> (hidden, larger)</td>\n<td>Undiagnosed cases, subclinical (inapparent) infections, carriers, latent and pre-symptomatic disease</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Examples</strong></p>\n<p>Hypertension, diabetes, anaemia, malnutrition, mental illness, TB, polio, hepatitis B; hidden cases far outnumber diagnosed ones.<br />\nIceberg is absent or small in rabies, measles and tetanus (almost all infections are clinical).</p>\n<p><strong>Epidemiological importance</strong></p>\n<ol>\n<li>Clinicians see only the tip; the true <strong>burden</strong> is much larger.</li>\n<li>The hidden part is a major <strong>source of infection</strong> (carriers, subclinical cases) → spread continues unnoticed.</li>\n<li>Justifies <strong>screening</strong> and <strong>active case finding</strong> to detect hidden cases early (secondary prevention).</li>\n<li>Hospital data alone <strong>underestimate</strong> disease; community surveys are needed (<strong>community diagnosis</strong>).</li>\n<li>Guides <strong>planning and resource allocation</strong>.</li>\n<li>Explains why disease <strong>control is difficult</strong> for diseases with large submerged parts.</li>\n<li>Underlines community medicine's focus on the <strong>whole population</strong>, not only patients.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.71","n":71,"part":1,"topic":"Concept of Disease","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is opportunistic infection?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Opportunistic infection</strong>: infection by an organism that usually does not cause disease (or causes only mild disease) in a healthy person, but causes disease when the host's defences are weakened, i.e., it takes the &quot;opportunity&quot; of lowered immunity.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.72","n":72,"part":1,"topic":"Concept of Disease","stars":3,"years":["25M","24M","18M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify host factors with examples.</p>","a":"<p><strong>Host factors (intrinsic factors)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Factors</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Demographic</strong></td>\n<td>Age, sex, ethnicity</td>\n<td>Measles in children; breast cancer in women; thalassaemia in certain groups</td>\n</tr>\n<tr>\n<td>2. <strong>Biological</strong></td>\n<td>Genetic factors; biochemical levels (cholesterol); blood groups; physiological state (pregnancy, puberty, stress, fatigue); immunity and previous disease; nutrition</td>\n<td>Sickle-cell trait protects against malaria; blood group O and cholera; pregnancy and anaemia</td>\n</tr>\n<tr>\n<td>3. <strong>Social and economic</strong></td>\n<td>Socio-economic status, education, occupation, stress, marital status, housing</td>\n<td>Silicosis in stone crushers; TB with poverty and overcrowding</td>\n</tr>\n<tr>\n<td>4. <strong>Lifestyle</strong></td>\n<td>Personality traits, living habits, nutrition, physical exercise, use of alcohol, drugs, smoking, behaviour</td>\n<td>CHD with smoking and inactivity; HIV with risky sexual behaviour</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other host factors</strong></p>\n<ul>\n<li><strong>Immune status</strong>: vaccination, natural immunity.</li>\n<li><strong>Personal hygiene</strong>: scabies, worm infestation.</li>\n<li><strong>Psychological factors</strong>: personality type A and CHD.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.73","n":73,"part":1,"topic":"Concept of Disease","stars":0,"years":[],"colleges":"MMC (1st Supp A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define disease.</p>","a":"<p><strong>Definitions</strong></p>\n<ol>\n<li><strong>Webster</strong>: a condition in which body health is impaired; a departure from a state of health; an alteration of the body that interrupts performance of vital functions.</li>\n<li><strong>Oxford English Dictionary</strong>: a condition of the body, or of some part or organ, in which its functions are disturbed or deranged.</li>\n<li><strong>Ecological view</strong>: maladjustment of the human organism to its environment.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.74","n":74,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":3,"years":["12Ja"],"colleges":"DMC (1st Assess A2)","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by disease control?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Disease control</strong>: ongoing operations aimed at reducing:</p>\n<ol>\n<li>the <strong>incidence</strong> of disease,</li>\n<li>the <strong>duration</strong> of disease and so the risk of transmission,</li>\n<li>the <strong>effects</strong> of infection, including physical and psychosocial complications,</li>\n<li>the <strong>financial burden</strong> to the community.</li>\n</ol>\n<p>The aim is to reduce the disease to a level where it is <strong>no longer a public health problem</strong>; the agent continues to exist in the community.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.75","n":75,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":3,"years":["26M","25M","22Nov","17M","16Ju","12Ja","11Ju"],"colleges":"MMC (1st Supp A5); MuMC (1st Final C1, 1st Supp C1)","asked":"levels of prevention with mode of intervention / describe levels of prevention and related interventions","note":"","kind":"","sub":"","q":"<p>List the modes of intervention with examples / mention (write down, state) the different levels of disease prevention with examples / how will you prevent disease at different levels?</p>","a":"<p><strong>Levels of prevention and modes of intervention</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Phase of natural history</th>\n<th>Mode of intervention</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primordial</strong></td>\n<td>Before risk factors appear</td>\n<td>Prevent emergence of risk factors (individual and mass education, policy)</td>\n<td>Discourage children from smoking; promote healthy diet and play; tobacco laws</td>\n</tr>\n<tr>\n<td><strong>Primary</strong></td>\n<td>Pre-pathogenesis</td>\n<td>1. <strong>Health promotion</strong></td>\n<td>Health education, nutrition, sanitation, housing, lifestyle change</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td>2. <strong>Specific protection</strong></td>\n<td>Immunisation, chemoprophylaxis, iodised salt, vitamin A, helmets, protective gear, condom use</td>\n</tr>\n<tr>\n<td><strong>Secondary</strong></td>\n<td>Early pathogenesis</td>\n<td>3. <strong>Early diagnosis and treatment</strong></td>\n<td>Screening (BP, diabetes, VIA), case finding (TB), treatment of malaria, IMCI</td>\n</tr>\n<tr>\n<td><strong>Tertiary</strong></td>\n<td>Late pathogenesis</td>\n<td>4. <strong>Disability limitation</strong></td>\n<td>Good diabetes control to prevent amputation; treatment of stroke; leprosy MDT and care</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td>5. <strong>Rehabilitation</strong></td>\n<td>Medical, vocational, social, psychological: physiotherapy, artificial limb, job training</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Key points</strong></p>\n<ol>\n<li>Levels follow the <strong>natural history of disease</strong> (Leavell and Clark).</li>\n<li>Five modes of intervention: health promotion, specific protection, early diagnosis and treatment, disability limitation, rehabilitation.</li>\n<li>Earlier prevention is cheaper and more effective.</li>\n<li>Secondary prevention is often the main option for diseases without primary prevention.</li>\n</ol>\n<p><strong>Example: diabetes at all levels</strong></p>\n<p>Primordial: healthy school food | Primary: weight control, exercise | Secondary: blood glucose screening | Tertiary: foot care, eye laser, rehabilitation after amputation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.76","n":76,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":3,"years":["17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Explain primordial prevention.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Primordial prevention</strong>: prevention of the emergence or development of <strong>risk factors</strong> in countries or population groups in which they have not yet appeared.</p>\n<p><strong>Features</strong></p>\n<ol>\n<li>Newest level; acts <strong>before</strong> risk factors appear.</li>\n<li>Especially for <strong>chronic NCDs</strong> (CHD, hypertension, diabetes, cancers).</li>\n<li>Targets <strong>children and young people</strong>, before harmful habits form.</li>\n<li>Works mainly through <strong>individual and mass education</strong> and healthy public policy.</li>\n<li>Population-wide; not disease-specific.</li>\n</ol>\n<p><strong>Examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Risk factor prevented</th>\n<th>Measure</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Smoking</td>\n<td>Tobacco control law, school education, ban on advertising, taxes</td>\n</tr>\n<tr>\n<td>Unhealthy diet</td>\n<td>School nutrition, limits on trans fat, salt and sugar; healthy food labelling</td>\n</tr>\n<tr>\n<td>Physical inactivity</td>\n<td>Playgrounds, parks, safe walking and cycling paths</td>\n</tr>\n<tr>\n<td>Obesity</td>\n<td>Breastfeeding promotion, healthy lifestyle education</td>\n</tr>\n<tr>\n<td>Alcohol and drugs</td>\n<td>Laws, awareness, family support</td>\n</tr>\n<tr>\n<td>Air pollution</td>\n<td>Clean fuel, emission control</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Primordial vs primary prevention</strong></p>\n<table>\n<thead>\n<tr>\n<th>Primordial</th>\n<th>Primary</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Prevents risk factors</td>\n<td>Prevents disease in those with/without risk factors</td>\n</tr>\n<tr>\n<td>Before risk factors appear</td>\n<td>Pre-pathogenesis phase</td>\n</tr>\n<tr>\n<td>Mainly policy and education</td>\n<td>Health promotion + specific protection</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.77","n":77,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":3,"years":["22M","09Ja","05S"],"colleges":"DMC (1st Assess A1)","asked":"mode of intervention of primary prevention","note":"","kind":"","sub":"","q":"<p>What is primary prevention? / Describe primary prevention with examples.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Primary prevention</strong>: action taken <strong>before the onset of disease</strong> that removes the possibility that the disease will ever occur; intervention in the <strong>pre-pathogenesis</strong> phase.</p>\n<p><strong>Modes of intervention</strong></p>\n<p><strong>1. Health promotion</strong> (not disease-specific)</p>\n<ul>\n<li>Health education</li>\n<li>Environmental modifications (safe water, sanitation, housing)</li>\n<li>Nutritional interventions (food fortification, supplementation)</li>\n<li>Lifestyle and behavioural changes</li>\n</ul>\n<p><strong>2. Specific protection</strong> (disease-specific)</p>\n<ul>\n<li>Immunisation (EPI: BCG, pentavalent, MR, PCV)</li>\n<li>Use of specific nutrients (iodised salt, vitamin A, iron-folic acid)</li>\n<li>Chemoprophylaxis (antimalarials for travellers, cotrimoxazole in HIV)</li>\n<li>Protection against occupational hazards (masks, earplugs)</li>\n<li>Protection against accidents (helmets, seat belts)</li>\n<li>Protection from carcinogens (HPV vaccine, no tobacco)</li>\n<li>Avoidance of allergens</li>\n<li>Control of specific environmental hazards (air pollution)</li>\n<li>Quality control of food, drugs and cosmetics</li>\n</ul>\n<p><strong>Approaches</strong></p>\n<table>\n<thead>\n<tr>\n<th>Approach</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Population (mass) strategy</strong></td>\n<td>Lower the risk factor level in the whole population</td>\n<td>Salt reduction for all</td>\n</tr>\n<tr>\n<td><strong>High-risk strategy</strong></td>\n<td>Target persons at special risk</td>\n<td>Statins and counselling for high-risk adults</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Importance</strong></p>\n<p>Most effective and cheapest level; &quot;prevention is better than cure&quot;; WHO and Alma-Ata stress it.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.78","n":78,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":3,"years":["24Nov"],"colleges":"DMC (1st Assess A2)","asked":"","note":"","kind":"","sub":"","q":"<p>What is disease elimination and disease eradication?</p>","a":"<p><strong>Definitions</strong></p>\n<table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Meaning</th>\n<th>Measures needed after achievement</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Control</strong></td>\n<td>Reduction of incidence, prevalence, morbidity or mortality to an acceptable level</td>\n<td>Continued</td>\n<td>TB, malaria</td>\n</tr>\n<tr>\n<td><strong>Elimination as a public health problem</strong> (WHO)</td>\n<td>Achievement of defined measurable targets (e.g., below a threshold rate) in an area</td>\n<td>Continued</td>\n<td>Kala-azar: &lt;1 case/10,000 at upazila level</td>\n</tr>\n<tr>\n<td><strong>Elimination of disease</strong></td>\n<td>Reduction to <strong>zero incidence</strong> of disease in a defined geographical area</td>\n<td>Continued</td>\n<td>Neonatal tetanus in a country</td>\n</tr>\n<tr>\n<td><strong>Elimination of infection</strong></td>\n<td>Reduction to <strong>zero incidence of infection</strong> in a defined area</td>\n<td>Continued</td>\n<td>Polio in a region</td>\n</tr>\n<tr>\n<td><strong>Eradication</strong></td>\n<td>Permanent reduction to <strong>zero worldwide incidence of infection</strong>; termination of all transmission by extermination of the agent</td>\n<td><strong>Not needed</strong></td>\n<td>Smallpox</td>\n</tr>\n<tr>\n<td><strong>Extinction</strong></td>\n<td>Agent no longer exists in nature or laboratory</td>\n<td>None</td>\n<td>None yet</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Eradication: smallpox</strong></p>\n<ul>\n<li>Last natural case worldwide: Somalia, 1977; Bangladesh's last case: 1975.</li>\n<li>WHO declared global eradication in <strong>1980</strong>.</li>\n<li>Candidates: poliomyelitis, dracunculiasis (guinea worm), yaws.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease); WHO, 2023, https://www.who.int/news/item/31-10-2023-bangladesh-achieves-historic-milestone-by-eliminating-kala-azar-as-a-public-health-problem</p>"},{"id":"DU.79","n":79,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":0,"years":["06S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define surveillance.</p>","a":"<p><strong>Definitions</strong></p>\n<ol>\n<li><strong>Park</strong>: the continuous scrutiny of the factors that determine the occurrence and distribution of disease and other conditions of ill health.</li>\n<li><strong>CDC / WHO (public health surveillance)</strong>: the ongoing, systematic collection, analysis and interpretation of health-related data essential to planning, implementation and evaluation of public health practice, with timely dissemination to those who need to know, linked to action.</li>\n</ol>\n<p>Short form: <strong>&quot;information for action&quot;</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.80","n":80,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":0,"years":[],"colleges":"MMC (1st Supp A5)","asked":"","note":"","kind":"","sub":"","q":"<p>Define prevention.</p>","a":"<p><strong>Definitions</strong></p>\n<ol>\n<li>The goals of medicine: to <strong>promote</strong> health, <strong>preserve</strong> health, <strong>restore</strong> health when impaired, and <strong>minimise suffering</strong>; these goals are summed up in the word <strong>prevention</strong>.</li>\n<li><strong>Prevention</strong>: actions aimed at eradicating, eliminating or minimising the impact of disease and disability, or, if none is feasible, slowing their progress (Last, Dictionary of Epidemiology).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.81","n":81,"part":1,"topic":"Community Diagnosis and Treatment","stars":3,"years":["25M","20Nov","18M","17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is community diagnosis? Write down three importance of community diagnosis in prevention of disease. (also: explain community diagnosis with examples.)</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Community diagnosis</strong>: identification and quantification of the health problems of a community in terms of mortality and morbidity rates and ratios, and identification of their correlates (determinants), in order to define those at risk or in need of health care.</p>\n<p>It is to the community what clinical diagnosis is to the patient.</p>\n<p><strong>Steps</strong></p>\n<p>Collect data (census, records, surveys) → Calculate rates and ratios → Identify main problems and at-risk groups → Find causes / correlates → Set priorities → Plan action (community treatment)</p>\n<p><strong>Data used</strong></p>\n<p>Demographic (age-sex structure), vital statistics (births, deaths), morbidity, nutritional status, environment (water, sanitation), socio-economic status, health services and their use.</p>\n<p><strong>Example</strong></p>\n<p>A village survey shows high diarrhoea and stunting among under-fives, linked with unsafe water, open defecation and poor feeding → diagnosis: &quot;diarrhoea and undernutrition due to poor WASH and feeding practices&quot;.</p>\n<p><strong>Importance in prevention of disease</strong></p>\n<ol>\n<li><strong>Identifies priority problems and their causes</strong> → targets prevention where it is needed most.</li>\n<li><strong>Defines high-risk groups</strong> (mothers, under-fives, elderly, workers) → selective protection and screening.</li>\n<li><strong>Basis for planning and resource allocation</strong> of preventive programmes (immunisation, WASH, nutrition).</li>\n<li><strong>Baseline for evaluation</strong>: later surveys show whether prevention worked.</li>\n<li>Detects the <strong>hidden iceberg</strong> of disease missed by hospital data.</li>\n<li>Promotes <strong>community participation</strong> in solving local problems.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine; Principles of Epidemiology).</p>"},{"id":"DU.82","n":82,"part":1,"topic":"Community Diagnosis and Treatment","stars":3,"years":["24Nov","18M","17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Explain community treatment / relate the role of community treatment in controlling disease (asked together with community diagnosis).</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Community treatment</strong>: organised, collective health action taken by the health system and the community to deal with the health problems identified by <strong>community diagnosis</strong>; it includes promotive, preventive, curative and rehabilitative measures applied to the whole population or groups.</p>\n<p>Community diagnosis → Community treatment → Evaluation</p>\n<p><strong>Methods</strong></p>\n<ol>\n<li>Health education and behaviour change.</li>\n<li>Environmental measures: safe water, sanitation, vector control.</li>\n<li>Mass immunisation campaigns.</li>\n<li><strong>Mass drug administration</strong> and chemoprophylaxis.</li>\n<li>Nutrition programmes: supplementation, fortification.</li>\n<li>Screening and case finding.</li>\n<li>Legislation: food safety, tobacco control.</li>\n<li>Organisation of health services and referral.</li>\n</ol>\n<p><strong>Role in controlling disease</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disease</th>\n<th>Community treatment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Lymphatic filariasis</td>\n<td>Annual MDA with DEC + albendazole → eliminated in Bangladesh (2023)</td>\n</tr>\n<tr>\n<td>Polio</td>\n<td>National Immunisation Days</td>\n</tr>\n<tr>\n<td>Cholera</td>\n<td>Chlorination, ORS, oral cholera vaccine campaigns</td>\n</tr>\n<tr>\n<td>Worm infestation</td>\n<td>Mass deworming of school children</td>\n</tr>\n<tr>\n<td>Vitamin A deficiency</td>\n<td>Biannual vitamin A campaigns</td>\n</tr>\n<tr>\n<td>Dengue</td>\n<td>Community source reduction</td>\n</tr>\n<tr>\n<td>Iodine deficiency</td>\n<td>Universal salt iodisation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Clinical vs community treatment</strong></p>\n<table>\n<thead>\n<tr>\n<th>Clinical</th>\n<th>Community</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Individual patient</td>\n<td>Whole population</td>\n</tr>\n<tr>\n<td>Drugs, surgery</td>\n<td>Programmes, policy, environment</td>\n</tr>\n<tr>\n<td>Cure</td>\n<td>Prevention and control</td>\n</tr>\n<tr>\n<td>Evaluated by recovery</td>\n<td>Evaluated by fall in incidence</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.83","n":83,"part":1,"topic":"Community Diagnosis and Treatment","stars":0,"years":[],"colleges":"SSMC (1st Supp B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Define and classify screening tests.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Screening</strong>: the search for unrecognised disease or defect by means of rapidly applied tests, examinations or other procedures in apparently healthy individuals. It sorts out those who <strong>probably have</strong> the disease from those who probably do not; it is <strong>not diagnostic</strong> (positives need diagnostic confirmation) (US Commission on Chronic Illness).</p>\n<p><strong>Classification (types of screening)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Mass screening</strong></td>\n<td>Whole population or large group, regardless of risk</td>\n<td>Hypertension screening of all adults in a community</td>\n</tr>\n<tr>\n<td><strong>High-risk / selective screening</strong></td>\n<td>Only groups at higher risk</td>\n<td>Diabetes in obese adults; cervical cancer screening in women 30–60 years</td>\n</tr>\n<tr>\n<td><strong>Multiphasic screening</strong></td>\n<td>Several tests at one time</td>\n<td>Health check-up: BP, glucose, lipids, Hb, urine</td>\n</tr>\n<tr>\n<td><strong>Opportunistic (case finding)</strong></td>\n<td>Testing patients who come for other reasons</td>\n<td>Checking BP of every OPD patient</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Criteria of a good screening test</strong></p>\n<p>Acceptability; repeatability (reliability); validity (sensitivity, specificity); yield; simplicity; safety; rapidity; ease of administration; low cost.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Screening for Disease).</p>"},{"id":"DU.84","n":84,"part":1,"topic":"Community Diagnosis and Treatment","stars":0,"years":[],"colleges":"SSMC (1st Supp B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between the sensitivity and specificity of a screening test.</p>","a":"<p><strong>2 × 2 table</strong></p>\n<table>\n<thead>\n<tr>\n<th>Screening test</th>\n<th>Disease present</th>\n<th>Disease absent</th>\n<th>Total</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Positive</td>\n<td>a (true positive)</td>\n<td>b (false positive)</td>\n<td>a + b</td>\n</tr>\n<tr>\n<td>Negative</td>\n<td>c (false negative)</td>\n<td>d (true negative)</td>\n<td>c + d</td>\n</tr>\n<tr>\n<td>Total</td>\n<td>a + c</td>\n<td>b + d</td>\n<td>N</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Sensitivity vs specificity</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Sensitivity</th>\n<th>Specificity</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Definition</td>\n<td>Ability of a test to identify correctly those <strong>who have</strong> the disease</td>\n<td>Ability of a test to identify correctly those <strong>who do not have</strong> the disease</td>\n</tr>\n<tr>\n<td>Formula</td>\n<td>a / (a + c) × 100</td>\n<td>d / (b + d) × 100</td>\n</tr>\n<tr>\n<td>Also called</td>\n<td>True positive rate</td>\n<td>True negative rate</td>\n</tr>\n<tr>\n<td>Linked error</td>\n<td>Low sensitivity → more <strong>false negatives</strong></td>\n<td>Low specificity → more <strong>false positives</strong></td>\n</tr>\n<tr>\n<td>Effect of error</td>\n<td>Cases missed; false reassurance; disease spreads</td>\n<td>Healthy people investigated, anxious, extra cost</td>\n</tr>\n<tr>\n<td>Preferred when</td>\n<td>Disease serious, treatable, missing it is costly (e.g., blood donor HIV, PKU)</td>\n<td>False positives are harmful or costly (e.g., before surgery or toxic treatment); disease rare</td>\n</tr>\n<tr>\n<td>Effect of moving cut-off (e.g., lowering glucose cut-off)</td>\n<td>Increases</td>\n<td>Decreases</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Screening for Disease).</p>"},{"id":"DU.85","n":85,"part":1,"topic":"Behavioral Science","stars":0,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by medical sociology?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Medical sociology</strong>: the branch of sociology that studies the <strong>social aspects of health, illness and medical care</strong>: social causes and consequences of disease, health and illness behaviour, doctor–patient relationship, medical profession, hospitals and health care systems.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.86","n":86,"part":1,"topic":"Behavioral Science","stars":0,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention components of medical sociology.</p>","a":"<p><strong>Components of medical sociology</strong></p>\n<ol>\n<li><strong>Social aetiology of disease</strong>: poverty, overcrowding, illiteracy, occupation, urbanisation, stress.</li>\n<li><strong>Social epidemiology</strong>: distribution of disease by class, gender, ethnicity, residence.</li>\n<li><strong>Health behaviour, illness behaviour and sick role</strong> (Parsons): rights and duties of the sick.</li>\n<li><strong>Doctor–patient relationship</strong>: communication, trust, compliance.</li>\n<li><strong>Hospital sociology</strong>: hospital as a social system; roles of staff and patients.</li>\n<li><strong>Medical profession</strong>: professional values, ethics, power, socialisation of doctors.</li>\n<li><strong>Health care organisation and policy</strong>: access, equity, financing.</li>\n<li><strong>Culture and health</strong>: beliefs, customs, taboos, traditional healers.</li>\n<li><strong>Family and health</strong>: family's role in causation, care, rehabilitation.</li>\n<li><strong>Stigma and deviance</strong>: leprosy, HIV, mental illness.</li>\n<li><strong>Stress and social support</strong>.</li>\n<li><strong>Social problems</strong>: alcoholism, drug addiction, suicide, delinquency, domestic violence.</li>\n<li><strong>Social change</strong>: industrialisation, migration, ageing.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.87","n":87,"part":1,"topic":"Behavioral Science","stars":3,"years":["15Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention factors influencing doctor-patient relationship.</p>","a":"<p><strong>Factors influencing doctor–patient relationship</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Factors</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Doctor</strong></td>\n<td>Knowledge and competence; communication skills; empathy, courtesy; attitude (respect vs arrogance); time given; honesty; fees; gender; language; professional ethics</td>\n</tr>\n<tr>\n<td><strong>Patient</strong></td>\n<td>Education, culture, beliefs; expectations; socio-economic status; anxiety, fear; previous experience; compliance; gender, age</td>\n</tr>\n<tr>\n<td><strong>Illness</strong></td>\n<td>Severity, urgency, chronicity; stigma (HIV, mental illness, leprosy); prognosis</td>\n</tr>\n<tr>\n<td><strong>Communication</strong></td>\n<td>Language barrier; medical jargon; non-verbal cues; listening; explanation</td>\n</tr>\n<tr>\n<td><strong>Setting / system</strong></td>\n<td>Overcrowded OPD, short consultation time, lack of privacy, long waiting; cost of care; public vs private; referral problems</td>\n</tr>\n<tr>\n<td><strong>Social</strong></td>\n<td>Media reports, mistrust, commercialisation, violence against doctors, litigation</td>\n</tr>\n<tr>\n<td><strong>Third parties</strong></td>\n<td>Family members, attendants, brokers, drug companies</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Models (Szasz and Hollender)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Model</th>\n<th>Doctor</th>\n<th>Patient</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Activity–passivity</td>\n<td>Active</td>\n<td>Passive</td>\n<td>Unconscious patient, emergency</td>\n</tr>\n<tr>\n<td>Guidance–cooperation</td>\n<td>Guides</td>\n<td>Cooperates</td>\n<td>Acute infection</td>\n</tr>\n<tr>\n<td>Mutual participation</td>\n<td>Helps patient help himself</td>\n<td>Partner</td>\n<td>Chronic disease (diabetes)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.88","n":88,"part":1,"topic":"Behavioral Science","stars":3,"years":["24M","22M","13Ju"],"colleges":"DMC (1st Assess D1); ShSMC (1st Term D5); MMC (1st Supp B2)","asked":"how to improve doctor-patient relationship (part c of the language-barrier case)","note":"","kind":"","sub":"","q":"<p>Explore strategies for enhancing / how can doctor-patient relationship be promoted (in Bangladesh)?</p>","a":"<p><strong>Strategies to enhance doctor–patient relationship (Bangladesh)</strong></p>\n<p><strong>A. Doctor-level</strong></p>\n<ol>\n<li><strong>Communication skills</strong> training (undergraduate and in-service): listening, explaining, breaking bad news.</li>\n<li>Speak <strong>Bangla / local language</strong>; avoid jargon; use <strong>interpreters</strong> for indigenous, Rohingya or foreign patients.</li>\n<li><strong>Empathy</strong>, courtesy, respect for dignity, culture and religion.</li>\n<li><strong>Informed consent</strong> and shared decision-making.</li>\n<li><strong>Privacy and confidentiality</strong>: screened examination, female chaperone.</li>\n<li>Honest, transparent information on diagnosis, cost, prognosis.</li>\n<li>Rational prescribing; avoid unnecessary tests; declare conflicts of interest.</li>\n<li>Follow BMDC code of ethics.</li>\n</ol>\n<p><strong>B. System-level</strong></p>\n<ol>\n<li>Reduce <strong>OPD overcrowding</strong>: more doctors, appointment and token systems, strong referral.</li>\n<li>Adequate <strong>consultation time</strong>.</li>\n<li>Clear, fixed <strong>fees</strong> in private sector; regulation of private clinics.</li>\n<li>Patient <strong>help desks</strong>, information boards, complaint and feedback systems.</li>\n<li><strong>Security</strong> of doctors and staff; legal protection against violence.</li>\n<li>Continuity of care: <strong>family physicians</strong>, community clinics.</li>\n<li>Female doctors and women-friendly services.</li>\n<li>Telemedicine and follow-up by phone.</li>\n</ol>\n<p><strong>C. Community-level</strong></p>\n<ol>\n<li>Health education to set realistic expectations.</li>\n<li>Responsible media reporting.</li>\n<li>Community participation in hospital management committees.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.89","n":89,"part":1,"topic":"Behavioral Science","stars":3,"years":["19Nov","16M","15Ja"],"colleges":"MMC (1st Supp B4)","asked":"define behavior","note":"","kind":"","sub":"","q":"<p>Enumerate / enlist / define and classify the types of behaviour with examples.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Behaviour</strong>: everything a person does (physical, mental or verbal) in response to internal or external stimuli; observable actions plus internal processes (thinking, feeling).</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Observability</td>\n<td><strong>Overt</strong> (observable) / <strong>Covert</strong> (internal)</td>\n<td>Walking, speaking / thinking, feeling</td>\n</tr>\n<tr>\n<td>Control</td>\n<td><strong>Voluntary</strong> / <strong>Involuntary</strong> (reflex)</td>\n<td>Eating / knee jerk, blinking</td>\n</tr>\n<tr>\n<td>Awareness</td>\n<td><strong>Conscious</strong> / <strong>Unconscious</strong></td>\n<td>Planned decision / slips of tongue, habits</td>\n</tr>\n<tr>\n<td>Origin</td>\n<td><strong>Innate</strong> (instinctive) / <strong>Learned</strong> (acquired)</td>\n<td>Sucking reflex / hand-washing, smoking</td>\n</tr>\n<tr>\n<td>Normality</td>\n<td><strong>Normal</strong> / <strong>Abnormal</strong></td>\n<td>Social interaction / hallucinatory behaviour</td>\n</tr>\n<tr>\n<td>Numbers</td>\n<td><strong>Individual</strong> / <strong>Group (collective)</strong></td>\n<td>Personal diet / crowd panic, mob behaviour</td>\n</tr>\n<tr>\n<td>Effect</td>\n<td><strong>Adaptive</strong> / <strong>Maladaptive</strong></td>\n<td>Seeking help when ill / drug abuse</td>\n</tr>\n<tr>\n<td>Health-related (Kasl and Cobb)</td>\n<td><strong>Health behaviour</strong>, <strong>illness behaviour</strong>, <strong>sick-role behaviour</strong></td>\n<td>Vaccination; consulting a doctor; taking prescribed medicine</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Determinants</strong></p>\n<p>Heredity, learning, motivation, perception, attitudes, beliefs, personality, culture, family, peers, environment.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.90","n":90,"part":1,"topic":"Behavioral Science","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate types of health behavior with examples.</p>","a":"<p><strong>Types of health-related behaviour (Kasl and Cobb, 1966)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Health behaviour</th>\n<th>Illness behaviour</th>\n<th>Sick-role behaviour</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Person's state</td>\n<td>Believes himself <strong>healthy</strong></td>\n<td><strong>Feels ill</strong>; not yet diagnosed</td>\n<td><strong>Considers himself ill</strong> (diagnosed)</td>\n</tr>\n<tr>\n<td>Purpose</td>\n<td>Prevent disease or detect it in asymptomatic stage</td>\n<td>Define the illness and find a remedy</td>\n<td>Get well</td>\n</tr>\n<tr>\n<td>Activities</td>\n<td>Immunisation, exercise, balanced diet, hand-washing, check-ups, screening</td>\n<td>Noticing symptoms, consulting family, self-medication, visiting a doctor</td>\n<td>Taking prescribed drugs, rest, follow-up, exemption from duties</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Woman getting VIA screening</td>\n<td>Man with cough visiting the community clinic</td>\n<td>TB patient completing DOTS</td>\n</tr>\n<tr>\n<td>Level of prevention</td>\n<td>Primary</td>\n<td>Secondary</td>\n<td>Secondary / tertiary</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.91","n":91,"part":1,"topic":"Behavioral Science","stars":2,"years":["07Ja","06M","05S"],"colleges":"ShSMC (1st Term A4)","asked":"illustrate Maslow’s hierarchy of needs","note":"","kind":"","sub":"","q":"<p>What are the human needs?</p>","a":"<p><strong>Human needs</strong></p>\n<p>Needs are states of deprivation that motivate behaviour.</p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primary (biological)</strong></td>\n<td>Food, water, air, sleep, shelter, sex, avoidance of pain</td>\n</tr>\n<tr>\n<td><strong>Secondary (psychosocial, learned)</strong></td>\n<td>Love, security, belonging, recognition, achievement, power</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Maslow's hierarchy of needs (1943)</strong></p>\n<p>Needs are arranged in a pyramid; lower needs must be met before higher ones motivate.</p>\n<table>\n<thead>\n<tr>\n<th>Level (bottom → top)</th>\n<th>Need</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Physiological</strong></td>\n<td>Food, water, sleep, shelter</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>Safety / security</strong></td>\n<td>Physical safety, job security, health, money</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Love and belonging (social)</strong></td>\n<td>Family, friends, acceptance in a group</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Esteem</strong></td>\n<td>Self-respect, recognition, status, achievement</td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>Self-actualisation</strong></td>\n<td>Realising one's full potential, creativity</td>\n</tr>\n</tbody>\n</table>\n<p>Physiological → Safety → Belonging → Esteem → Self-actualisation</p>\n<ul>\n<li>Levels 1–4: <strong>deficiency needs</strong>; level 5: <strong>growth need</strong>.</li>\n</ul>\n<p><strong>Relevance to health</strong></p>\n<ol>\n<li>Poor people focused on survival needs may ignore preventive services → link health with basic needs.</li>\n<li>Motivating health workers: pay meets lower needs; recognition and growth meet higher needs.</li>\n<li>Patient care: safety, belonging and dignity matter, not only treatment.</li>\n<li>Health education must appeal to the need active in the audience.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Communication for Health Education).</p>"},{"id":"DU.92","n":92,"part":1,"topic":"Behavioral Science","stars":0,"years":[],"colleges":"MMC (1st Supp B4)","asked":"","note":"","kind":"","sub":"","q":"<p>How does behavior influence human health?</p>","a":"<p><strong>How behaviour influences health</strong></p>\n<p>Health depends largely on what people do; many leading causes of death are <strong>behaviour-related</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>Behaviour</th>\n<th>Effect on health</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Tobacco smoking and chewing</td>\n<td>Lung and oral cancers, CHD, stroke, COPD, TB</td>\n</tr>\n<tr>\n<td>Unhealthy diet (salt, sugar, fat)</td>\n<td>Hypertension, diabetes, obesity, CHD</td>\n</tr>\n<tr>\n<td>Physical inactivity</td>\n<td>Obesity, diabetes, CHD, osteoporosis, depression</td>\n</tr>\n<tr>\n<td>Alcohol and drug use</td>\n<td>Liver disease, accidents, violence, HIV (injecting)</td>\n</tr>\n<tr>\n<td>Unsafe sex</td>\n<td>STIs, HIV, unwanted pregnancy</td>\n</tr>\n<tr>\n<td>Poor hygiene, open defecation</td>\n<td>Diarrhoea, typhoid, hepatitis, worms</td>\n</tr>\n<tr>\n<td>Delayed care-seeking</td>\n<td>Complications, maternal and child deaths</td>\n</tr>\n<tr>\n<td>Non-adherence to treatment</td>\n<td>Treatment failure, drug resistance (MDR-TB)</td>\n</tr>\n<tr>\n<td>Reckless driving, no helmet</td>\n<td>Road traffic injuries</td>\n</tr>\n<tr>\n<td>Breastfeeding, immunisation, ANC</td>\n<td>Protection of mother and child</td>\n</tr>\n<tr>\n<td>Regular exercise, balanced diet, sleep</td>\n<td>Physical and mental well-being</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Pathways</strong></p>\n<ol>\n<li><strong>Direct</strong>: exposure to or protection from risk (smoking → cancer).</li>\n<li><strong>Through use of services</strong>: screening, vaccination, early treatment.</li>\n<li><strong>Through others</strong>: second-hand smoke; spread of infection; children copying parents.</li>\n<li><strong>Psychological</strong>: stress-coping behaviour affects mental and physical health.</li>\n</ol>\n<p><strong>Implications</strong></p>\n<p>Behaviour change communication; health belief model; laws and policy; community participation; positive role models.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Communication for Health Education).</p>"},{"id":"DU.93","n":93,"part":1,"topic":"Behavioral Science","stars":0,"years":[],"colleges":"MuMC (1st Final C2)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A newly appointed intern doctor in a hospital receives adequate salary but still feels dissatisfied and unmotivated at work. Analyze the situation according to Abraham Maslow’s Hierarchy of Needs theory. Which level of need may remain unmet and how can it affect professional performance? [1.5+2]</p>","a":"<p><strong>a) Analysis using Maslow's hierarchy (1.5)</strong></p>\n<ul>\n<li>Adequate salary satisfies <strong>physiological</strong> and <strong>safety</strong> needs (food, shelter, security).</li>\n<li>He is still dissatisfied → the unmet needs are higher:\n<ol>\n<li><strong>Esteem needs</strong> (most likely): lack of recognition, respect, appreciation, status, sense of achievement; interns often feel undervalued.</li>\n<li><strong>Love and belonging (social)</strong>: may not feel accepted by the team; isolation, poor relations with seniors.</li>\n<li><strong>Self-actualisation</strong>: little chance to learn, grow and use skills; routine clerical work.</li>\n</ol>\n</li>\n<li>Herzberg's two-factor view agrees: salary is a <strong>hygiene factor</strong> (prevents dissatisfaction) but does not motivate; <strong>motivators</strong> are recognition, responsibility, achievement and growth.</li>\n</ul>\n<p><strong>b) Effect on professional performance (2)</strong></p>\n<ol>\n<li><strong>Low motivation</strong> and job satisfaction; minimal effort.</li>\n<li><strong>Poor quality of care</strong>: hurried history, errors, poor record keeping.</li>\n<li><strong>Poor communication</strong> and empathy with patients → weak doctor–patient relationship.</li>\n<li><strong>Absenteeism</strong>, late arrival, early leaving.</li>\n<li><strong>Burnout</strong>, stress, frustration, depression.</li>\n<li>Poor <strong>teamwork</strong> and conflicts with staff.</li>\n<li>Little interest in learning → slow skill development.</li>\n<li>Wish to leave the job or profession (turnover, brain drain).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Health Planning and Management).</p>"},{"id":"DU.94","n":94,"part":1,"topic":"Learning and Personality","stars":3,"years":["22Nov"],"colleges":"DMC (1st Assess B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Define learning.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Learning</strong>: a relatively permanent change in behaviour (knowledge, attitude or skill) that results from <strong>experience or practice</strong>.</p>\n<p>Changes due to maturation, fatigue, illness or drugs are <strong>not</strong> learning.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Communication for Health Education).</p>"},{"id":"DU.95","n":95,"part":1,"topic":"Learning and Personality","stars":0,"years":["11Ju","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the types of learning? / Classify learning.</p>","a":"<p><strong>Types of learning</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Proponent</th>\n<th>Mechanism</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Classical conditioning</strong></td>\n<td>Pavlov</td>\n<td>Neutral stimulus paired with natural stimulus produces a conditioned response</td>\n<td>Child cries at the sight of a white coat after injections</td>\n</tr>\n<tr>\n<td><strong>Operant (instrumental) conditioning</strong></td>\n<td>Skinner</td>\n<td>Behaviour shaped by its consequences (reward or punishment)</td>\n<td>Praise for completed vaccination card encourages return visits</td>\n</tr>\n<tr>\n<td><strong>Trial and error</strong></td>\n<td>Thorndike</td>\n<td>Repeated attempts; successful responses retained</td>\n<td>Learning to use an inhaler correctly</td>\n</tr>\n<tr>\n<td><strong>Insight (cognitive) learning</strong></td>\n<td>Köhler (Gestalt)</td>\n<td>Sudden understanding of relationships</td>\n<td>Grasping why ORS works</td>\n</tr>\n<tr>\n<td><strong>Observational / social learning</strong></td>\n<td>Bandura</td>\n<td>Imitation of a model</td>\n<td>Adolescents copying smoking parents; peer educators</td>\n</tr>\n<tr>\n<td><strong>Rote learning</strong></td>\n<td>—</td>\n<td>Memorising by repetition</td>\n<td>Drug doses</td>\n</tr>\n<tr>\n<td><strong>Meaningful learning</strong></td>\n<td>Ausubel</td>\n<td>Linking new to existing knowledge</td>\n<td>Understanding pathophysiology</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other classifications</strong></p>\n<ul>\n<li>By domain (Bloom): cognitive, affective, psychomotor.</li>\n<li>By setting: formal (school), non-formal (training), informal (daily life).</li>\n<li>By participation: active (learning by doing) vs passive (listening).</li>\n<li>By group: individual vs group learning.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Communication for Health Education).</p>"},{"id":"DU.96","n":96,"part":1,"topic":"Learning and Personality","stars":2,"years":["22Nov","20Nov","13Ju","11Ju","09Ju"],"colleges":"DMC (1st Assess B4); SSMC (1st Supp C3)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the factors / conditions affecting the process of learning? (also: state defense mechanism).</p>","a":"<p><strong>Factors affecting learning</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Factors</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Learner</strong></td>\n<td>Motivation and interest; intelligence; age; physical and mental health; attention; readiness; previous knowledge; emotional state (anxiety); fatigue; sensory defects</td>\n</tr>\n<tr>\n<td><strong>Teacher</strong></td>\n<td>Knowledge; teaching method; communication; attitude; use of examples and aids</td>\n</tr>\n<tr>\n<td><strong>Material</strong></td>\n<td>Meaningfulness; difficulty; length; organisation (simple → complex)</td>\n</tr>\n<tr>\n<td><strong>Method</strong></td>\n<td>Practice and repetition; spaced vs massed practice; active participation (learning by doing); feedback; reinforcement (reward); audio-visual aids</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>Physical (light, ventilation, noise, seating); social (group size, peer influence); culture</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Defence mechanisms</strong></p>\n<p>Unconscious mental processes that protect the self from anxiety (Freud).</p>\n<table>\n<thead>\n<tr>\n<th>Mechanism</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Repression</td>\n<td>Forgetting a painful event</td>\n</tr>\n<tr>\n<td>Denial</td>\n<td>Refusing to accept a cancer diagnosis</td>\n</tr>\n<tr>\n<td>Projection</td>\n<td>Blaming the doctor for one's own failure</td>\n</tr>\n<tr>\n<td>Rationalisation</td>\n<td>&quot;Smoking relieves my stress&quot;</td>\n</tr>\n<tr>\n<td>Displacement</td>\n<td>Anger at boss shown to family</td>\n</tr>\n<tr>\n<td>Regression</td>\n<td>Adult behaving childishly in hospital</td>\n</tr>\n<tr>\n<td>Reaction formation</td>\n<td>Excess kindness to a disliked person</td>\n</tr>\n<tr>\n<td>Sublimation</td>\n<td>Aggression channelled into sport</td>\n</tr>\n<tr>\n<td>Identification</td>\n<td>Student copying a respected teacher</td>\n</tr>\n<tr>\n<td>Intellectualisation</td>\n<td>Discussing one's illness only in technical terms</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Communication for Health Education).</p>"},{"id":"DU.97","n":97,"part":1,"topic":"Learning and Personality","stars":3,"years":["14Ju","13Ja"],"colleges":"ShSMC (1st Term D2)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention Benjamin Bloom's domains of learning.</p>","a":"<p><strong>Bloom's domains of learning (Bloom, 1956)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Domain</th>\n<th>Concerns</th>\n<th>Levels (lowest → highest)</th>\n<th>Medical example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Cognitive</strong></td>\n<td>Knowledge, thinking (&quot;head&quot;)</td>\n<td>Remember → Understand → Apply → Analyse → Evaluate → Create (revised 2001; original: knowledge, comprehension, application, analysis, synthesis, evaluation)</td>\n<td>Knowing EPI schedule; interpreting a growth chart</td>\n</tr>\n<tr>\n<td><strong>Affective</strong></td>\n<td>Attitudes, feelings, values (&quot;heart&quot;)</td>\n<td>Receiving → Responding → Valuing → Organisation → Characterisation (Krathwohl)</td>\n<td>Showing empathy; valuing confidentiality</td>\n</tr>\n<tr>\n<td><strong>Psychomotor</strong></td>\n<td>Manual and physical skills (&quot;hands&quot;)</td>\n<td>Imitation → Manipulation → Precision → Articulation → Naturalisation (Dave)</td>\n<td>Giving an injection; taking BP; CPR</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.98","n":98,"part":1,"topic":"Learning and Personality","stars":3,"years":["26M","22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Summarize the key principles of learning.</p>","a":"<p><strong>Key principles of learning</strong></p>\n<ol>\n<li><strong>Motivation</strong>: learning is fastest when the learner wants to learn (felt need).</li>\n<li><strong>Readiness</strong> (Thorndike's law of readiness): learner must be physically and mentally ready.</li>\n<li><strong>Exercise / practice</strong>: repetition strengthens learning (&quot;practice makes perfect&quot;).</li>\n<li><strong>Effect / reinforcement</strong>: rewarded responses are repeated; punished ones fade.</li>\n<li><strong>Active participation</strong>: &quot;learning by doing&quot; is better than passive listening.</li>\n<li><strong>Known to unknown; simple to complex; concrete to abstract</strong>.</li>\n<li><strong>Interest and relevance</strong>: link content to learner's problems and life.</li>\n<li><strong>Comprehension</strong>: use the learner's language and level.</li>\n<li><strong>Feedback</strong>: tells the learner what is right and what to correct.</li>\n<li><strong>Primacy and recency</strong>: first and last items are remembered best.</li>\n<li><strong>Intensity</strong>: vivid, dramatic experiences (demonstration, real cases) are remembered longer.</li>\n<li><strong>Spaced learning</strong> is better than massed (cramming).</li>\n<li><strong>Multisensory</strong>: using several senses (audio-visual aids) improves retention.</li>\n<li><strong>Individual differences</strong>: pace and method suited to the learner.</li>\n<li><strong>Good human relations</strong> between teacher and learner.</li>\n</ol>\n<p><strong>Application</strong></p>\n<p>Health education, patient counselling, training of CHWs and students.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.99","n":99,"part":1,"topic":"Learning and Personality","stars":3,"years":["12Ja","07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define and classify personality with appropriate examples / mention different types of personality.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Personality</strong>: the dynamic organisation within the individual of those psychophysical systems that determine his unique adjustment to his environment (after Allport); the sum of a person's characteristic patterns of thinking, feeling and behaving.</p>\n<p><strong>Classification</strong></p>\n<p><strong>A. Type theories</strong></p>\n<table>\n<thead>\n<tr>\n<th>Theory</th>\n<th>Types</th>\n<th>Example features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Hippocrates (humours)</td>\n<td>Sanguine, choleric, melancholic, phlegmatic</td>\n<td>Cheerful; irritable; sad; calm</td>\n</tr>\n<tr>\n<td>Kretschmer (body build)</td>\n<td>Pyknic, asthenic, athletic</td>\n<td>Stout, sociable; thin, withdrawn; muscular, energetic</td>\n</tr>\n<tr>\n<td>Sheldon (somatotype)</td>\n<td>Endomorph, mesomorph, ectomorph</td>\n<td>Relaxed, comfort-loving; assertive; shy, restrained</td>\n</tr>\n<tr>\n<td>Jung</td>\n<td>Introvert, extrovert, ambivert</td>\n<td>Reserved; outgoing; mixed</td>\n</tr>\n<tr>\n<td>Friedman and Rosenman</td>\n<td>Type A, Type B</td>\n<td>Hurried, competitive (CHD risk); relaxed</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Trait theories</strong></p>\n<ul>\n<li><strong>Allport</strong>: cardinal, central and secondary traits.</li>\n<li><strong>Cattell</strong>: 16 personality factors.</li>\n<li><strong>Eysenck</strong>: extraversion, neuroticism, psychoticism.</li>\n<li><strong>Big Five (OCEAN)</strong>: openness, conscientiousness, extraversion, agreeableness, neuroticism.</li>\n</ul>\n<p><strong>C. Psychoanalytic (Freud)</strong></p>\n<p>Id, ego, superego.</p>\n<p><strong>Determinants</strong></p>\n<p>Heredity, physique, endocrine glands, family, culture, school, peers, life experiences.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.100","n":100,"part":1,"topic":"Learning and Personality","stars":3,"years":["22M","19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Compare personality type A with type B / what are the features of type A and type B personality?</p>","a":"<p><strong>Type A vs Type B personality (Friedman and Rosenman)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th>Type A</th>\n<th>Type B</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Time</td>\n<td>Sense of <strong>time urgency</strong>; always hurried</td>\n<td>Relaxed; no hurry</td>\n</tr>\n<tr>\n<td>Drive</td>\n<td>Highly <strong>competitive</strong>, ambitious, achievement-oriented</td>\n<td>Less competitive; easy-going</td>\n</tr>\n<tr>\n<td>Emotions</td>\n<td>Impatient, <strong>hostile</strong>, easily angered</td>\n<td>Patient, calm, tolerant</td>\n</tr>\n<tr>\n<td>Work</td>\n<td>Workaholic; many tasks at once</td>\n<td>Balanced work and leisure</td>\n</tr>\n<tr>\n<td>Speech and manner</td>\n<td>Fast talking, interrupts, restless</td>\n<td>Slow, unhurried speech</td>\n</tr>\n<tr>\n<td>Leisure</td>\n<td>Feels guilty when relaxing</td>\n<td>Enjoys leisure without guilt</td>\n</tr>\n<tr>\n<td>Stress response</td>\n<td>High stress, high sympathetic arousal</td>\n<td>Low stress</td>\n</tr>\n<tr>\n<td>Health risk</td>\n<td>Higher risk of <strong>coronary heart disease</strong>, hypertension, peptic ulcer</td>\n<td>Lower risk</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Relevance</strong></p>\n<p>Stress management, relaxation, lifestyle counselling for Type A persons as part of CHD prevention.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.101","n":101,"part":1,"topic":"Learning and Personality","stars":3,"years":["23Nov","10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Arrange developmental stages of personality / how personality of an individual is developed?</p>","a":"<p><strong>Development of personality</strong></p>\n<p>Personality develops through the interaction of <strong>heredity</strong> (genes, physique, temperament, endocrine) and <strong>environment</strong> (family, school, peers, culture, religion, life events), across stages of life.</p>\n<p><strong>A. Freud's psychosexual stages</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Age</th>\n<th>Focus</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Oral</td>\n<td>0–1 year</td>\n<td>Mouth (sucking, feeding)</td>\n</tr>\n<tr>\n<td>Anal</td>\n<td>1–3 years</td>\n<td>Toilet training, control</td>\n</tr>\n<tr>\n<td>Phallic</td>\n<td>3–6 years</td>\n<td>Genitals; Oedipus/Electra complex</td>\n</tr>\n<tr>\n<td>Latency</td>\n<td>6 years–puberty</td>\n<td>Sexual drive dormant; school, skills</td>\n</tr>\n<tr>\n<td>Genital</td>\n<td>Puberty onward</td>\n<td>Mature sexual relationships</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Erikson's psychosocial stages</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Age</th>\n<th>Conflict</th>\n<th>Virtue</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>Infancy (0–1)</td>\n<td>Trust vs mistrust</td>\n<td>Hope</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Early childhood (1–3)</td>\n<td>Autonomy vs shame and doubt</td>\n<td>Will</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Preschool (3–6)</td>\n<td>Initiative vs guilt</td>\n<td>Purpose</td>\n</tr>\n<tr>\n<td>4</td>\n<td>School age (6–12)</td>\n<td>Industry vs inferiority</td>\n<td>Competence</td>\n</tr>\n<tr>\n<td>5</td>\n<td>Adolescence (12–18)</td>\n<td>Identity vs role confusion</td>\n<td>Fidelity</td>\n</tr>\n<tr>\n<td>6</td>\n<td>Young adult</td>\n<td>Intimacy vs isolation</td>\n<td>Love</td>\n</tr>\n<tr>\n<td>7</td>\n<td>Middle adult</td>\n<td>Generativity vs stagnation</td>\n<td>Care</td>\n</tr>\n<tr>\n<td>8</td>\n<td>Old age</td>\n<td>Integrity vs despair</td>\n<td>Wisdom</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Agents of development</strong></p>\n<p>Family (first and most important), school, peer group, religion, mass media, occupation, culture.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.102","n":102,"part":1,"topic":"Learning and Personality","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is emotion? Mention the names of primary emotions.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Emotion</strong>: a complex state of feeling, arising in response to a stimulus, with three components:</p>\n<ol>\n<li><strong>Subjective</strong> experience (feeling)</li>\n<li><strong>Physiological</strong> arousal (autonomic: heart rate, BP, sweating; hormones)</li>\n<li><strong>Behavioural / expressive</strong> response (facial expression, voice, action)</li>\n</ol>\n<p><strong>Primary (basic) emotions</strong></p>\n<table>\n<thead>\n<tr>\n<th>Model</th>\n<th>Emotions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Ekman (6, universal facial expressions)</td>\n<td>Happiness, sadness, fear, anger, surprise, disgust</td>\n</tr>\n<tr>\n<td>Plutchik (8)</td>\n<td>Joy, trust, fear, surprise, sadness, disgust, anger, anticipation</td>\n</tr>\n</tbody>\n</table>\n<p>Secondary (complex) emotions arise from mixtures: love, guilt, shame, jealousy, pride, anxiety.</p>\n<p><strong>Relevance to health</strong></p>\n<ul>\n<li>Chronic negative emotions (anxiety, anger) → stress → hypertension, peptic ulcer, CHD (psychosomatic illness).</li>\n<li>Fear influences care-seeking and compliance.</li>\n<li>Emotional dimension of health; emotional intelligence of doctors improves care.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences; Mental Health).</p>"},{"id":"DU.103","n":103,"part":1,"topic":"Mental Health","stars":3,"years":["22Nov"],"colleges":"MuMC (1st Final D2)","asked":"5 criteria of good mental health","note":"","kind":"","sub":"","q":"<p>What are the features of a mentally healthy person?</p>","a":"<p><strong>Features of a mentally healthy person (Park)</strong></p>\n<ol>\n<li>Free from internal <strong>conflicts</strong>; not at war with himself.</li>\n<li><strong>Well adjusted</strong>: gets along with others; accepts praise and criticism.</li>\n<li>Searches for <strong>identity</strong>.</li>\n<li>Strong sense of <strong>self-esteem</strong>.</li>\n<li>Knows himself, his needs, problems and goals (<strong>self-actualisation</strong>).</li>\n<li>Good <strong>self-control</strong>: balances rationality and emotionality.</li>\n<li>Faces problems and tries to solve them <strong>intelligently</strong>; copes with stress and anxiety.</li>\n</ol>\n<p><strong>Other features</strong></p>\n<ul>\n<li>Realistic perception of reality.</li>\n<li>Ability to form satisfying relationships (love and friendship).</li>\n<li>Works productively; contributes to the community.</li>\n<li>Takes responsibility for own actions.</li>\n<li>Adapts to change; flexible.</li>\n</ul>\n<p><strong>Five criteria (Jahoda)</strong></p>\n<ol>\n<li>Positive attitude towards self</li>\n<li>Growth and self-actualisation</li>\n<li>Integration of personality</li>\n<li>Autonomy</li>\n<li>Accurate perception of reality and environmental mastery</li>\n</ol>\n<p><strong>WHO (2022)</strong>: mental health is a state of mental well-being that enables people to cope with stresses, realise abilities, learn and work well, and contribute to their community.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Mental Health); WHO, 2022.</p>"},{"id":"DU.104","n":104,"part":1,"topic":"I.Q.","stars":3,"years":["22Nov","16Ja","05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is IQ?</p>","a":"<p><strong>Intelligence</strong></p>\n<p>The global capacity to act purposefully, think rationally and deal effectively with the environment (Wechsler); ability to learn, reason, solve problems and adapt.</p>\n<p><strong>IQ (Intelligence Quotient)</strong></p>\n<p>A numerical index of intelligence relative to age.</p>\n<p><strong>Formula (ratio IQ; Stern, Terman)</strong></p>\n<p>IQ = (Mental age ÷ Chronological age) × 100</p>\n<ul>\n<li><strong>Mental age (MA)</strong>: the age level at which a person performs on an intelligence test.</li>\n<li><strong>Chronological age (CA)</strong>: actual age.</li>\n<li>Average IQ = 100 (MA = CA).</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Mental Health).</p>"},{"id":"DU.105","n":105,"part":1,"topic":"I.Q.","stars":3,"years":["19M","13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention IQ and interpret / categorize people in accordance to IQ range.</p>","a":"<p><strong>Classification of people by IQ</strong></p>\n<table>\n<thead>\n<tr>\n<th>IQ range</th>\n<th>Category</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>≥140</td>\n<td>Genius / near genius</td>\n</tr>\n<tr>\n<td>120–139</td>\n<td>Very superior</td>\n</tr>\n<tr>\n<td>110–119</td>\n<td>Superior</td>\n</tr>\n<tr>\n<td>90–109</td>\n<td><strong>Average (normal)</strong></td>\n</tr>\n<tr>\n<td>80–89</td>\n<td>Dull normal (low average)</td>\n</tr>\n<tr>\n<td>70–79</td>\n<td>Borderline</td>\n</tr>\n<tr>\n<td>&lt;70</td>\n<td><strong>Intellectual disability (mental retardation)</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Grades of intellectual disability</strong></p>\n<table>\n<thead>\n<tr>\n<th>Grade</th>\n<th>IQ</th>\n<th>Mental age (adult)</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mild</td>\n<td>50–69</td>\n<td>9–12 years</td>\n<td>Educable; can live independently with some support</td>\n</tr>\n<tr>\n<td>Moderate</td>\n<td>35–49</td>\n<td>6–9 years</td>\n<td>Trainable; self-care and simple work under supervision</td>\n</tr>\n<tr>\n<td>Severe</td>\n<td>20–34</td>\n<td>3–6 years</td>\n<td>Needs constant supervision; limited speech</td>\n</tr>\n<tr>\n<td>Profound</td>\n<td>&lt;20</td>\n<td>&lt;3 years</td>\n<td>Total care needed</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Interpretation</strong></p>\n<ul>\n<li>About two-thirds of people have IQ 85–115 (mean ± 1 SD).</li>\n<li>IQ must be interpreted with adaptive behaviour (social and daily-living skills) before diagnosing intellectual disability.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Mental Health).</p>"},{"id":"DU.106","n":106,"part":1,"topic":"I.Q.","stars":2,"years":["17Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you calculate IQ? / Calculate IQ of a girl of 10 years with mental age of 2 and interpret.</p>","a":"<p><strong>Calculation</strong></p>\n<p>IQ = (Mental age ÷ Chronological age) × 100</p>\n<p><strong>Given</strong></p>\n<p>Chronological age = 10 years; mental age = 2 years.</p>\n<p>IQ = (2 ÷ 10) × 100 = <strong>20</strong></p>\n<p><strong>Interpretation</strong></p>\n<table>\n<thead>\n<tr>\n<th>IQ range</th>\n<th>Grade</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>50–69</td>\n<td>Mild intellectual disability</td>\n</tr>\n<tr>\n<td>35–49</td>\n<td>Moderate</td>\n</tr>\n<tr>\n<td><strong>20–34</strong></td>\n<td><strong>Severe</strong></td>\n</tr>\n<tr>\n<td>&lt;20</td>\n<td>Profound</td>\n</tr>\n</tbody>\n</table>\n<p>IQ 20 = <strong>severe intellectual disability</strong> (at the borderline with profound).</p>\n<p><strong>Implications</strong></p>\n<ol>\n<li>Functions like a 2-year-old: limited speech, needs help with self-care.</li>\n<li>Needs <strong>constant supervision</strong> and family support.</li>\n<li>Requires <strong>special education</strong>, training in basic self-care, speech and physiotherapy.</li>\n<li>Look for causes: birth asphyxia, congenital hypothyroidism, iodine deficiency, genetic syndromes (Down syndrome), infections, malnutrition.</li>\n<li>Assess adaptive behaviour; counsel the family; link to disability services.</li>\n</ol>\n<p><strong>Note</strong></p>\n<p>Ratio IQ is used for children; for adults, deviation IQ is used (chronological age above ~15–16 years is not used in the formula).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Mental Health).</p>"},{"id":"DU.107","n":107,"part":1,"topic":"Family and Leadership","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is family?</p>","a":"<p><strong>Definition</strong></p>\n<ul>\n<li><strong>Park</strong>: a group of biologically related individuals living together and eating from a common kitchen.</li>\n<li><strong>Sociological (Burgess and Locke)</strong>: a group of persons united by marriage, blood or adoption, forming a single household, interacting in their social roles (husband, wife, parents, children, siblings) and sharing a common culture.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.108","n":108,"part":1,"topic":"Family and Leadership","stars":3,"years":["17Ja","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the functions of a family? / Mention the functions of family relevant to health behavior and health.</p>","a":"<p><strong>Functions of the family</strong></p>\n<table>\n<thead>\n<tr>\n<th>Function</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Biological / reproductive</strong></td>\n<td>Regulates sexual relations; produces and continues generations</td>\n</tr>\n<tr>\n<td>2. <strong>Socialisation and education</strong></td>\n<td>Teaches language, values, norms, habits, culture</td>\n</tr>\n<tr>\n<td>3. <strong>Economic</strong></td>\n<td>Earns, shares income and property; provides food, clothing, shelter</td>\n</tr>\n<tr>\n<td>4. <strong>Emotional (affectional)</strong></td>\n<td>Love, security, companionship</td>\n</tr>\n<tr>\n<td>5. <strong>Protective and caring</strong></td>\n<td>Care of children, sick, disabled and elderly</td>\n</tr>\n<tr>\n<td>6. <strong>Social status (placement)</strong></td>\n<td>Gives name, identity, religion, social position</td>\n</tr>\n<tr>\n<td>7. <strong>Recreational</strong></td>\n<td>Leisure and relaxation</td>\n</tr>\n<tr>\n<td>8. <strong>Religious / moral</strong></td>\n<td>Moral and religious training</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Functions relevant to health and health behaviour</strong></p>\n<ol>\n<li><strong>Nutrition</strong> and child feeding: breastfeeding, complementary feeding.</li>\n<li><strong>Hygiene and sanitation</strong> at home: hand-washing, safe water, latrine use.</li>\n<li><strong>Health habits</strong> learned from parents: diet, exercise, tobacco avoidance.</li>\n<li><strong>Care of the sick</strong>: home nursing, ORS, compliance with treatment.</li>\n<li><strong>Decision making</strong> on care-seeking, ANC, facility delivery, immunisation.</li>\n<li><strong>Family planning</strong> and birth spacing.</li>\n<li><strong>Financing</strong> of health care.</li>\n<li><strong>Emotional support</strong> in chronic illness, mental illness and disability.</li>\n<li><strong>Care of the elderly</strong> and rehabilitation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.109","n":109,"part":1,"topic":"Family and Leadership","stars":3,"years":["25M","18Nov","16Nov","16Ja","14Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How does the family influence a person's health and illness? / Discuss the role of family in health and disease.</p>","a":"<p><strong>Role of family in health and disease</strong></p>\n<p><strong>A. In causation of disease</strong></p>\n<ol>\n<li><strong>Heredity</strong>: genetic diseases (thalassaemia, haemophilia), consanguineous marriage.</li>\n<li><strong>Family size and spacing</strong>: malnutrition, infections, maternal depletion.</li>\n<li><strong>Socio-economic status</strong>: poverty, overcrowding, poor housing → TB, diarrhoea.</li>\n<li><strong>Habits and lifestyle</strong> passed on: diet, smoking, betel quid, inactivity.</li>\n<li><strong>Spread of infection</strong> within household: TB, scabies, hepatitis, COVID-19.</li>\n<li><strong>Family disharmony</strong>: broken or problem families → delinquency, depression, substance abuse, child abuse.</li>\n</ol>\n<p><strong>B. In recognition of disease</strong></p>\n<p>Family members notice symptoms and danger signs first; they decide when and where to seek care.</p>\n<p><strong>C. In care and treatment</strong></p>\n<ol>\n<li>Home care and nursing; ORS for diarrhoea.</li>\n<li>Ensures <strong>compliance</strong> (DOTS, insulin, antihypertensives).</li>\n<li>Pays for treatment.</li>\n<li>Emotional support reduces stress and aids recovery.</li>\n</ol>\n<p><strong>D. In rehabilitation</strong></p>\n<p>Care of disabled, elderly, mentally ill; reintegration into society.</p>\n<p><strong>E. In prevention and promotion</strong></p>\n<p>Immunisation, breastfeeding, family planning, hygiene, healthy diet, ANC, safe delivery.</p>\n<p><strong>Concept</strong></p>\n<p>The family is the <strong>basic unit of health care</strong>; family-centred care improves outcomes.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.110","n":110,"part":1,"topic":"Family and Leadership","stars":3,"years":["16Nov","16Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify family.</p>","a":"<p><strong>Classification of family</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Meaning / example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Structure (Park)</strong></td>\n<td><strong>Nuclear</strong> (elementary)</td>\n<td>Husband, wife and unmarried children</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Joint</strong> (extended)</td>\n<td>Several nuclear families sharing residence, kitchen and property (brothers with wives and children, parents)</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Three-generation</strong></td>\n<td>Grandparents, parents and children together</td>\n</tr>\n<tr>\n<td><strong>Marriage</strong></td>\n<td>Monogamous</td>\n<td>One husband, one wife</td>\n</tr>\n<tr>\n<td></td>\n<td>Polygamous: polygyny / polyandry</td>\n<td>One husband, several wives / one wife, several husbands</td>\n</tr>\n<tr>\n<td><strong>Authority</strong></td>\n<td>Patriarchal / matriarchal / egalitarian</td>\n<td>Father / mother / both hold authority</td>\n</tr>\n<tr>\n<td><strong>Residence</strong></td>\n<td>Patrilocal / matrilocal / neolocal</td>\n<td>Live with husband's / wife's family / new home</td>\n</tr>\n<tr>\n<td><strong>Descent</strong></td>\n<td>Patrilineal / matrilineal</td>\n<td>Descent through father (Bangladesh) / mother (Garo community)</td>\n</tr>\n<tr>\n<td><strong>Membership</strong></td>\n<td>Family of orientation / procreation</td>\n<td>Family one is born into / family one creates by marriage</td>\n</tr>\n<tr>\n<td><strong>Other</strong></td>\n<td>Single-parent, broken, blended, problem family</td>\n<td>One parent; separated; remarriage; family with persistent social and health problems</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medicine and Social Sciences).</p>"},{"id":"DU.111","n":111,"part":1,"topic":"Family and Leadership","stars":3,"years":["13Ja","05Ja"],"colleges":"DMC (1st Assess D2); MMC (1st Supp B1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention types of leadership.</p>","a":"<p><strong>Types of leadership</strong></p>\n<p><strong>A. By style (Lewin)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Features</th>\n<th>Health example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Autocratic (authoritarian)</strong></td>\n<td>Leader decides alone; strict control; one-way communication</td>\n<td>Emergency resuscitation, disaster response</td>\n</tr>\n<tr>\n<td><strong>Democratic (participative)</strong></td>\n<td>Decisions shared with group; two-way communication</td>\n<td>Upazila health team planning EPI micro-plans</td>\n</tr>\n<tr>\n<td><strong>Laissez-faire (free-rein)</strong></td>\n<td>Leader gives freedom; minimal direction</td>\n<td>Experienced research team</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Other types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Bureaucratic</td>\n<td>Works strictly by rules and procedures</td>\n</tr>\n<tr>\n<td>Paternalistic</td>\n<td>Leader acts like a parent; caring but controlling</td>\n</tr>\n<tr>\n<td>Charismatic</td>\n<td>Influence through personal charm and vision</td>\n</tr>\n<tr>\n<td>Transactional</td>\n<td>Reward and punishment for performance</td>\n</tr>\n<tr>\n<td>Transformational</td>\n<td>Inspires, motivates change, develops followers</td>\n</tr>\n<tr>\n<td>Situational (Hersey–Blanchard)</td>\n<td>Style varies with followers' readiness: telling, selling, participating, delegating</td>\n</tr>\n<tr>\n<td>Servant</td>\n<td>Leader serves the needs of the team</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. By position</strong></p>\n<p>Formal (appointed: UH&amp;FPO, civil surgeon) vs informal (emerges from the group: respected village elder, imam, teacher).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management; Communication for Health Education).</p>"},{"id":"DU.112","n":112,"part":1,"topic":"Family and Leadership","stars":3,"years":["24Nov","12Ju"],"colleges":"DMC (1st Assess D2); ShSMC (2nd Term C4); MMC (1st Supp B1)","asked":"qualities expected from a leader / three characteristics of an effective health service leader","note":"","kind":"","sub":"","q":"<p>Mention the criteria of a good leader.</p>","a":"<p><strong>Criteria / qualities of a good leader</strong></p>\n<ol>\n<li><strong>Vision</strong>: clear goals and direction.</li>\n<li><strong>Integrity and honesty</strong>: trusted by the team.</li>\n<li><strong>Competence and knowledge</strong> of the field.</li>\n<li><strong>Communication</strong>: listens, explains, gives feedback.</li>\n<li><strong>Decision-making</strong> and problem-solving ability.</li>\n<li><strong>Motivates and inspires</strong> others; recognises good work.</li>\n<li><strong>Delegation</strong>: assigns tasks according to ability.</li>\n<li><strong>Fairness</strong>: impartial; no favouritism.</li>\n<li><strong>Empathy and emotional intelligence</strong>.</li>\n<li><strong>Accountability</strong>: accepts responsibility for outcomes.</li>\n<li><strong>Confidence and courage</strong> in difficult situations.</li>\n<li><strong>Flexibility</strong>: adapts style to the situation.</li>\n<li><strong>Team building</strong> and conflict resolution.</li>\n<li><strong>Commitment and hard work</strong>: leads by example.</li>\n<li><strong>Humility</strong>: open to advice and criticism.</li>\n<li><strong>Creativity and innovation</strong>.</li>\n</ol>\n<p><strong>In health care</strong></p>\n<p>A good leader (e.g., UH&amp;FPO) coordinates the team, community and other sectors, uses data for decisions and maintains quality of care.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.113","n":113,"part":1,"topic":"Family and Leadership","stars":0,"years":[],"colleges":"DMC (1st Assess D2)","asked":"","note":"","kind":"","sub":"","q":"<p>Which type of leadership is ideal and why?</p>","a":"<p><strong>Ideal leadership: democratic (participative), adapted to the situation</strong></p>\n<p><strong>Why democratic is generally ideal in health care</strong></p>\n<ol>\n<li>Health care is <strong>teamwork</strong>; members have different skills.</li>\n<li><strong>Shared decisions</strong> use the knowledge of all members → better decisions.</li>\n<li><strong>Motivation and job satisfaction</strong> rise; staff feel valued (esteem needs).</li>\n<li><strong>Commitment and acceptance</strong> of decisions; easier implementation.</li>\n<li><strong>Two-way communication</strong>; problems surface early.</li>\n<li>Develops <strong>future leaders</strong>; builds trust.</li>\n<li>Fits <strong>community participation</strong> principle of PHC.</li>\n</ol>\n<p><strong>Limitations</strong></p>\n<p>Slow in emergencies; needs skilled, willing members.</p>\n<p><strong>Conclusion</strong></p>\n<p>No single style suits every situation (<strong>situational leadership</strong>); democratic is ideal for most health settings, with an autocratic shift in emergencies; transformational qualities make it more effective.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.114","n":114,"part":1,"topic":"Family and Leadership","stars":0,"years":[],"colleges":"ShSMC (2nd Term C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Which leadership style encourages participation of staff in decision making?</p>","a":"<p><strong>Answer</strong></p>\n<p><strong>Democratic (participative) leadership</strong> encourages participation of staff in decision-making.</p>\n<p><strong>Features</strong></p>\n<ol>\n<li>Leader consults staff and shares decision-making.</li>\n<li>Two-way communication; ideas welcomed.</li>\n<li>Responsibility delegated; teamwork encouraged.</li>\n<li>Decisions often by consensus or majority.</li>\n<li>Leader guides, coordinates and keeps final accountability.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.115","n":115,"part":1,"topic":"Family and Leadership","stars":0,"years":[],"colleges":"MMC (1st Supp B1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define leader.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Leader</strong>: a person who influences, guides and directs the behaviour of a group towards achieving common goals, and whom the group accepts.</p>\n<p><strong>Leadership</strong>: the process (art) of influencing people so that they work willingly and enthusiastically towards group goals.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management; Communication for Health Education).</p>"},{"id":"DU.116","n":116,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the major events of vital statistics.</p>","a":"<p><strong>Vital statistics</strong></p>\n<p>Numerical records of vital events occurring in a population (births, deaths, marriages and related events); collected by registration and sample registration.</p>\n<p><strong>Major vital events (UN list)</strong></p>\n<ol>\n<li><strong>Live birth</strong></li>\n<li><strong>Death</strong> (including infant, neonatal and maternal deaths)</li>\n<li><strong>Fetal death</strong> (stillbirth)</li>\n<li><strong>Marriage</strong></li>\n<li><strong>Divorce</strong></li>\n<li>Annulment of marriage</li>\n<li>Judicial separation</li>\n<li>Adoption</li>\n<li>Legitimation</li>\n<li>Recognition (of paternity)</li>\n</ol>\n<p>Births and deaths are the most important for health; marriages and divorces matter for fertility.</p>\n<p><strong>Rates derived</strong></p>\n<p>Crude birth rate, crude death rate, IMR, NMR, MMR, life expectancy, fertility rates, marriage rate.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics; Demography and Family Planning).</p>"},{"id":"DU.117","n":117,"part":2,"topic":"Biostatistics and Data","stars":0,"years":["06M","04M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the sources of demographic statistics?</p>","a":"<p><strong>Sources of demographic statistics</strong></p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Description</th>\n<th>Bangladesh example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Census</strong></td>\n<td>Complete count of population at one time; age, sex, education, occupation, housing</td>\n<td>Population and Housing Census (every 10 years; latest 2022)</td>\n</tr>\n<tr>\n<td>2. <strong>Registration of vital events</strong> (civil registration)</td>\n<td>Continuous, compulsory recording of births, deaths, marriages</td>\n<td>Births and Deaths Registration Act 2004</td>\n</tr>\n<tr>\n<td>3. <strong>Sample registration system</strong></td>\n<td>Continuous registration in a representative sample with independent survey (dual record)</td>\n<td>SVRS (BBS)</td>\n</tr>\n<tr>\n<td>4. <strong>Sample surveys</strong></td>\n<td>Periodic national surveys</td>\n<td>BDHS, MICS, HIES, Labour Force Survey</td>\n</tr>\n<tr>\n<td>5. <strong>Population registers</strong></td>\n<td>Continuous record of each resident</td>\n<td>National ID database</td>\n</tr>\n<tr>\n<td>6. <strong>Health service records</strong></td>\n<td>Hospital records, EPI and FP registers, HMIS/DHIS2</td>\n<td>DGHS, DGFP records</td>\n</tr>\n<tr>\n<td>7. <strong>Notification and special registers</strong></td>\n<td>Notifiable diseases, cancer registry</td>\n<td>IEDCR</td>\n</tr>\n<tr>\n<td>8. <strong>Other records</strong></td>\n<td>School enrolment, migration, NGO records</td>\n<td>Ministry of Education data</td>\n</tr>\n<tr>\n<td>9. <strong>International estimates</strong></td>\n<td>UN World Population Prospects, World Bank</td>\n<td>UN WPP</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning; Health Information and Basic Medical Statistics).</p>"},{"id":"DU.118","n":118,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["22Nov","16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the uses of biostatistics?</p>","a":"<p><strong>Biostatistics</strong></p>\n<p>Application of statistical methods to biological, medical and health data.</p>\n<p><strong>Uses</strong></p>\n<p><strong>A. Medicine and research</strong></p>\n<ol>\n<li>Define <strong>normal limits</strong> (Hb, BP, height, weight).</li>\n<li>Compare efficacy of <strong>drugs, vaccines and procedures</strong> (clinical trials).</li>\n<li>Find <strong>associations</strong> between risk factors and disease (smoking and lung cancer).</li>\n<li>Design studies: sample size, sampling, randomisation.</li>\n<li>Test <strong>hypotheses</strong>; judge significance (p-value, confidence interval).</li>\n<li>Evaluate <strong>diagnostic and screening tests</strong> (sensitivity, specificity).</li>\n</ol>\n<p><strong>B. Community medicine / public health</strong></p>\n<ol>\n<li>Measure <strong>health status</strong> of a community (IMR, MMR, life expectancy).</li>\n<li><strong>Compare</strong> health status between areas, groups and times.</li>\n<li>Identify <strong>priority problems</strong> and high-risk groups (community diagnosis).</li>\n<li><strong>Plan, monitor and evaluate</strong> health programmes (EPI coverage, CPR).</li>\n<li><strong>Surveillance</strong> and outbreak detection (trends, epidemic thresholds).</li>\n<li>Demography: population growth, projections.</li>\n</ol>\n<p><strong>C. Health administration</strong></p>\n<ol>\n<li>Planning services, manpower, beds, budget.</li>\n<li>Hospital statistics: bed occupancy, average length of stay.</li>\n</ol>\n<p><strong>D. Basic sciences</strong></p>\n<p>Physiology, anatomy, pharmacology (dose–response, bioassay), genetics.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.119","n":119,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["26M","25Nov","23M","22Nov","17Ja","16Nov"],"colleges":"ShSMC (1st Term B3); MMC (1st Supp D1); MuMC (1st Final C3, 1st Supp C2)","asked":"differentiate discrete and continuous variable with example","note":"","kind":"","sub":"","q":"<p>Define variable. Discuss different types of variables with examples.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Variable</strong>: a characteristic that varies (takes different values) from person to person, place to place or time to time (e.g., age, sex, Hb, BP).</p>\n<p><strong>Types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Sub-type</th>\n<th>Meaning</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Qualitative (categorical)</strong></td>\n<td><strong>Nominal</strong></td>\n<td>Categories without order</td>\n<td>Sex, blood group, religion</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Ordinal</strong></td>\n<td>Categories with natural order</td>\n<td>Stage of cancer, socio-economic class, grade of anaemia</td>\n</tr>\n<tr>\n<td><strong>Quantitative (numerical)</strong></td>\n<td><strong>Discrete</strong></td>\n<td>Whole numbers; counted</td>\n<td>Number of children, pulse rate, number of decayed teeth</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Continuous</strong></td>\n<td>Any value in a range; measured</td>\n<td>Height, weight, Hb, BP, temperature</td>\n</tr>\n</tbody>\n</table>\n<p><strong>By role in research</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Example (smoking and lung cancer)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Independent (exposure)</td>\n<td>Presumed cause</td>\n<td>Smoking</td>\n</tr>\n<tr>\n<td>Dependent (outcome)</td>\n<td>Presumed effect</td>\n<td>Lung cancer</td>\n</tr>\n<tr>\n<td>Confounding</td>\n<td>Related to both, distorts association</td>\n<td>Age, air pollution</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Discrete vs continuous</strong></p>\n<table>\n<thead>\n<tr>\n<th>Discrete</th>\n<th>Continuous</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Counted</td>\n<td>Measured</td>\n</tr>\n<tr>\n<td>Whole numbers only</td>\n<td>Fractions possible</td>\n</tr>\n<tr>\n<td>Gaps between values</td>\n<td>Unbroken scale</td>\n</tr>\n<tr>\n<td>Number of ANC visits</td>\n<td>Birth weight</td>\n</tr>\n<tr>\n<td>Shown by bar diagram</td>\n<td>Shown by histogram, frequency polygon</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.120","n":120,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["24Nov","21M","19Nov","18M","16M","16Ja","12Ju","08Ja","05M"],"colleges":"SSMC (1st Supp B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Define data. Classify data with examples / what are the different types of data / differentiate between qualitative and quantitative data.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Data</strong>: a collection of facts, figures or observations (numbers or categories) recorded on variables, from which information is derived.</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nature</td>\n<td><strong>Qualitative</strong> / <strong>Quantitative</strong></td>\n<td>Sex, blood group / Hb, age</td>\n</tr>\n<tr>\n<td>Quantitative</td>\n<td><strong>Discrete</strong> / <strong>Continuous</strong></td>\n<td>Number of children / height</td>\n</tr>\n<tr>\n<td>Scale of measurement</td>\n<td>Nominal, ordinal, interval, ratio</td>\n<td>Religion; pain grade; temperature (°C); weight</td>\n</tr>\n<tr>\n<td>Source</td>\n<td><strong>Primary</strong> / <strong>Secondary</strong></td>\n<td>Own survey / census, hospital records</td>\n</tr>\n<tr>\n<td>Arrangement</td>\n<td>Ungrouped (raw) / Grouped</td>\n<td>List of ages / frequency table by age group</td>\n</tr>\n<tr>\n<td>Time</td>\n<td>Cross-sectional / Time-series</td>\n<td>One survey / yearly IMR trend</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Qualitative vs quantitative data</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Qualitative</th>\n<th>Quantitative</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nature</td>\n<td>Attributes, categories</td>\n<td>Numbers, measurements</td>\n</tr>\n<tr>\n<td>Obtained by</td>\n<td>Classification, counting frequency</td>\n<td>Measurement or counting</td>\n</tr>\n<tr>\n<td>Sub-types</td>\n<td>Nominal, ordinal</td>\n<td>Discrete, continuous</td>\n</tr>\n<tr>\n<td>Summary</td>\n<td>Proportion, percentage, ratio</td>\n<td>Mean, median, SD</td>\n</tr>\n<tr>\n<td>Presentation</td>\n<td>Bar diagram, pie chart</td>\n<td>Histogram, frequency polygon, line graph</td>\n</tr>\n<tr>\n<td>Tests</td>\n<td>Chi-square</td>\n<td>t-test, ANOVA, correlation</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Immunised / not immunised</td>\n<td>Birth weight 2.8 kg</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.121","n":121,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["24M","16Nov"],"colleges":"MMC (1st Supp C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Classify sources of data.</p>","a":"<p><strong>Sources of data</strong></p>\n<p><strong>A. Primary data</strong>: collected first-hand by the investigator for the study.</p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Surveys (interview, questionnaire)</td>\n<td>Household survey on hand-washing</td>\n</tr>\n<tr>\n<td>Observation</td>\n<td>Observing hygiene practices in a school</td>\n</tr>\n<tr>\n<td>Measurement / examination</td>\n<td>BP, Hb, anthropometry</td>\n</tr>\n<tr>\n<td>Experiments and trials</td>\n<td>Vaccine trial</td>\n</tr>\n<tr>\n<td>Focus group discussions, in-depth interviews</td>\n<td>Barriers to ANC</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Secondary data</strong>: already collected by others for other purposes.</p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Census</td>\n<td>Population and Housing Census 2022</td>\n</tr>\n<tr>\n<td>Vital registration, SVRS</td>\n<td>Birth and death rates</td>\n</tr>\n<tr>\n<td>National surveys</td>\n<td>BDHS, MICS, HIES</td>\n</tr>\n<tr>\n<td>Hospital and health service records</td>\n<td>OPD registers, HMIS/DHIS2</td>\n</tr>\n<tr>\n<td>Disease notification, registers</td>\n<td>IEDCR surveillance, cancer registry</td>\n</tr>\n<tr>\n<td>Published literature and reports</td>\n<td>Journals, WHO and UNICEF reports</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other classifications</strong></p>\n<p>Internal (within the institution) vs external; routine (continuous) vs ad hoc (special surveys).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.122","n":122,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["22Nov","20Nov","18Nov","17Nov"],"colleges":"DMC (1st Assess B2); SSMC (1st Supp B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Name / write down the different methods of data collection (also: mention the parts of a table).</p>","a":"<p><strong>Methods of data collection</strong></p>\n<ol>\n<li><strong>Observation</strong>: participant / non-participant; structured (checklist) / unstructured.</li>\n<li><strong>Interview</strong>: face-to-face or telephone; structured, semi-structured, unstructured; interview schedule.</li>\n<li><strong>Questionnaire</strong>: self-administered, mailed, online.</li>\n<li><strong>Physical examination and measurement</strong>: clinical examination, anthropometry (weight, height, MUAC), BP.</li>\n<li><strong>Laboratory investigations</strong>: Hb, blood glucose, stool, sputum.</li>\n<li><strong>Record review (documentary)</strong>: hospital records, registers, case notes.</li>\n<li><strong>Qualitative methods</strong>: focus group discussion (FGD), in-depth interview (IDI), key informant interview (KII).</li>\n<li><strong>Experiments / trials</strong>.</li>\n<li><strong>Mechanical / electronic</strong>: data loggers, mobile data collection (ODK, KoBo).</li>\n</ol>\n<p><strong>Parts of a table</strong></p>\n<table>\n<thead>\n<tr>\n<th>Part</th>\n<th>Content</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Table number</td>\n<td>Serial number (Table 1)</td>\n</tr>\n<tr>\n<td>2. Title</td>\n<td>Brief, clear: what, where, when</td>\n</tr>\n<tr>\n<td>3. Column headings (captions)</td>\n<td>Labels of columns, with units</td>\n</tr>\n<tr>\n<td>4. Row headings (stubs)</td>\n<td>Labels of rows (categories)</td>\n</tr>\n<tr>\n<td>5. Body (cells)</td>\n<td>The data (frequencies, %)</td>\n</tr>\n<tr>\n<td>6. Totals</td>\n<td>Row and column totals</td>\n</tr>\n<tr>\n<td>7. Footnote</td>\n<td>Explanations, abbreviations</td>\n</tr>\n<tr>\n<td>8. Source</td>\n<td>Origin of data</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.123","n":123,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["24Nov","22Nov","21M","19M","16Ju","15Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can data be presented in a study? / What are the methods of data presentation? / State graphical presentation of data.</p>","a":"<p><strong>Methods of data presentation</strong></p>\n<p><strong>A. Textual</strong>: short description in sentences.</p>\n<p><strong>B. Tabulation</strong></p>\n<ol>\n<li>Simple table (one variable).</li>\n<li>Frequency distribution table (grouped).</li>\n<li>Complex / cross-table (two or more variables).</li>\n</ol>\n<p><strong>C. Graphical (charts and diagrams)</strong></p>\n<table>\n<thead>\n<tr>\n<th>For quantitative (continuous) data</th>\n<th>For qualitative / discrete data</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Histogram</strong></td>\n<td><strong>Bar diagram</strong>: simple, multiple, component, proportional</td>\n</tr>\n<tr>\n<td><strong>Frequency polygon</strong></td>\n<td><strong>Pie (sector) chart</strong></td>\n</tr>\n<tr>\n<td>Frequency curve</td>\n<td><strong>Pictogram</strong></td>\n</tr>\n<tr>\n<td><strong>Line graph</strong> (trend over time)</td>\n<td><strong>Map diagram</strong>: spot map, shaded map</td>\n</tr>\n<tr>\n<td>Cumulative frequency curve (ogive)</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Scatter diagram</strong> (correlation)</td>\n<td></td>\n</tr>\n<tr>\n<td>Box-and-whisker plot; stem-and-leaf</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Principles of good presentation</strong></p>\n<ol>\n<li>Self-explanatory title; numbered.</li>\n<li>Clear labels and units; scales start at zero.</li>\n<li>Simple; not overcrowded.</li>\n<li>Source and footnotes.</li>\n<li>Right diagram for the type of data.</li>\n</ol>\n<p><strong>Uses</strong></p>\n<p>Makes data easy to understand, compare and remember; shows trends and relationships.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.124","n":124,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["22Nov"],"colleges":"DMC (1st Assess B5); SSMC (1st Supp B3); MMC (1st Supp D1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the criteria of normal distribution curve.</p>","a":"<p><strong>Criteria (characteristics) of the normal distribution curve</strong></p>\n<ol>\n<li><strong>Bell-shaped</strong> and <strong>symmetrical</strong> about the mean.</li>\n<li><strong>Mean = median = mode</strong> (at the centre).</li>\n<li><strong>Unimodal</strong>: one peak.</li>\n<li><strong>Asymptotic</strong>: tails approach but never touch the x-axis.</li>\n<li>Total <strong>area under the curve = 1 (100%)</strong>.</li>\n<li>Defined fully by two parameters: <strong>mean (μ)</strong> and <strong>standard deviation (σ)</strong>.</li>\n<li>Fixed area relationships:</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Range</th>\n<th>Area (observations)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mean ± 1 SD</td>\n<td>68.27%</td>\n</tr>\n<tr>\n<td>Mean ± 1.96 SD</td>\n<td>95%</td>\n</tr>\n<tr>\n<td>Mean ± 2 SD</td>\n<td>95.45%</td>\n</tr>\n<tr>\n<td>Mean ± 2.58 SD</td>\n<td>99%</td>\n</tr>\n<tr>\n<td>Mean ± 3 SD</td>\n<td>99.73%</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"8\">\n<li><strong>Skewness = 0</strong>; kurtosis mesokurtic.</li>\n<li>Points of inflection at mean ± 1 SD.</li>\n<li><strong>Standard normal curve</strong>: mean 0, SD 1 (z-score = (x − mean) ÷ SD).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.125","n":125,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["25M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Describe the characteristics of a bar diagram.</p>","a":"<p><strong>Bar diagram: characteristics</strong></p>\n<ol>\n<li>Used for <strong>qualitative (categorical)</strong> or <strong>discrete</strong> data.</li>\n<li>Bars of <strong>equal width</strong>; only the <strong>length (height)</strong> shows the value.</li>\n<li>Length proportional to frequency or percentage.</li>\n<li><strong>Equal gaps</strong> between bars (bars do not touch).</li>\n<li>Bars may be <strong>vertical (column)</strong> or <strong>horizontal</strong>.</li>\n<li>Scale on the value axis <strong>starts from zero</strong>.</li>\n<li>Bars arranged in a logical order (ascending, descending, alphabetical or time).</li>\n<li>Clear <strong>title</strong>, axis labels, units, legend (for multiple / component bars).</li>\n<li>Simple to draw and easy to compare.</li>\n</ol>\n<p><strong>Types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Use</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Simple</td>\n<td>One variable</td>\n<td>Immunisation coverage by vaccine</td>\n</tr>\n<tr>\n<td>Multiple (grouped)</td>\n<td>Two or more variables side by side</td>\n<td>Male vs female literacy by division</td>\n</tr>\n<tr>\n<td>Component (sub-divided)</td>\n<td>Parts of a total within one bar</td>\n<td>Causes of child deaths each year</td>\n</tr>\n<tr>\n<td>Proportional (100%)</td>\n<td>Percentage composition</td>\n<td>Proportion of deliveries by place</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Bar diagram vs histogram</strong></p>\n<table>\n<thead>\n<tr>\n<th>Bar diagram</th>\n<th>Histogram</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Qualitative / discrete data</td>\n<td>Continuous data</td>\n</tr>\n<tr>\n<td>Gaps between bars</td>\n<td>Bars touch (no gaps)</td>\n</tr>\n<tr>\n<td>Width has no meaning</td>\n<td>Width = class interval; area = frequency</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.126","n":126,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["24M","17M"],"colleges":"MMC (1st Supp C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Calculate mean from the following observations of age in years: 12, 14, 16, 18, 20, 22, 25, 30, 35, 40.</p>","a":"<p><strong>Data</strong>: 12, 14, 16, 18, 20, 22, 25, 30, 35, 40 (n = 10)</p>\n<p><strong>Formula</strong></p>\n<p>Mean (x̄) = Σx ÷ n</p>\n<p><strong>Calculation</strong></p>\n<p>Σx = 12 + 14 + 16 + 18 + 20 + 22 + 25 + 30 + 35 + 40 = 232</p>\n<p>x̄ = 232 ÷ 10 = <strong>23.2 years</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>The average age of the 10 persons is 23.2 years. The data are skewed to the right (a few older ages: 30, 35, 40), so the mean is greater than the median (21 years).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.127","n":127,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Calculate mean and median from the values: 65, 45, 46, 35, 33, 77, 39, 49.</p>","a":"<p><strong>Data</strong>: 65, 45, 46, 35, 33, 77, 39, 49 (n = 8)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 65 + 45 + 46 + 35 + 33 + 77 + 39 + 49 = 389</p>\n<p>x̄ = 389 ÷ 8 = <strong>48.63</strong> (≈ 48.6)</p>\n<p><strong>Median</strong></p>\n<p>Arrange in ascending order: 33, 35, 39, <strong>45, 46</strong>, 49, 65, 77</p>\n<p>n = 8 (even) → median = average of the (n/2)th and (n/2 + 1)th values = 4th and 5th values</p>\n<p>Median = (45 + 46) ÷ 2 = <strong>45.5</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (48.6) &gt; median (45.5) → slight positive (right) skew due to high values 65 and 77; median better represents the centre.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.128","n":128,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Find out the median and mode from the series: 7, 10, 6, 3, 2, 7, 8, 10, 5, 4.</p>","a":"<p><strong>Data</strong>: 7, 10, 6, 3, 2, 7, 8, 10, 5, 4 (n = 10)</p>\n<p><strong>Ascending order</strong></p>\n<p>2, 3, 4, 5, <strong>6, 7</strong>, 7, 8, 10, 10</p>\n<p><strong>Median</strong></p>\n<p>n = 10 (even) → average of 5th and 6th values</p>\n<p>Median = (6 + 7) ÷ 2 = <strong>6.5</strong></p>\n<p><strong>Mode</strong></p>\n<table>\n<thead>\n<tr>\n<th>Value</th>\n<th>2</th>\n<th>3</th>\n<th>4</th>\n<th>5</th>\n<th>6</th>\n<th>7</th>\n<th>8</th>\n<th>10</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Frequency</td>\n<td>1</td>\n<td>1</td>\n<td>1</td>\n<td>1</td>\n<td>1</td>\n<td><strong>2</strong></td>\n<td>1</td>\n<td><strong>2</strong></td>\n</tr>\n</tbody>\n</table>\n<p>7 and 10 each occur twice → <strong>Mode = 7 and 10 (bimodal series)</strong></p>\n<p>(Mean = 62 ÷ 10 = 6.2, for reference.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.129","n":129,"part":2,"topic":"Biostatistics and Data","stars":2,"years":["20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Calculate median from the following observations (height in cm): 70, 68, 85, 75, 72 and 80.</p>","a":"<p><strong>Data (height, cm)</strong>: 70, 68, 85, 75, 72, 80 (n = 6)</p>\n<p><strong>Ascending order</strong></p>\n<p>68, 70, <strong>72, 75</strong>, 80, 85</p>\n<p><strong>Median</strong></p>\n<p>n = 6 (even) → average of (n/2)th = 3rd and (n/2 + 1)th = 4th values</p>\n<p>Median = (72 + 75) ÷ 2 = <strong>73.5 cm</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Half of the children are shorter than 73.5 cm and half are taller.</p>\n<p><strong>Note</strong></p>\n<p>Median is not affected by extreme values; useful for skewed data.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.130","n":130,"part":2,"topic":"Biostatistics and Data","stars":0,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Construct a diagram with the following data: Mother's education Nil-80%, Primary-60%, Secondary-50%. What type of diagram is it?</p>","a":"<p><strong>Type of diagram</strong></p>\n<p>Data are <strong>qualitative (categorical)</strong> (levels of mother's education) with a percentage for each → <strong>simple bar diagram</strong> (vertical or horizontal).</p>\n<p><strong>Diagram (simple bar diagram)</strong></p>\n<pre><code>Percentage (%)\n100 |\n 80 |  ████\n 60 |  ████     ████\n 50 |  ████     ████     ████\n 40 |  ████     ████     ████\n 20 |  ████     ████     ████\n  0 +--------------------------------\n       Nil     Primary  Secondary\n          Mother's education\n</code></pre>\n<p><strong>Figure</strong>: Percentage by level of mother's education (Nil 80%, Primary 60%, Secondary 50%).</p>\n<p><strong>Interpretation</strong></p>\n<p>The percentage falls as mother's education rises (80% → 60% → 50%), showing an inverse relationship between maternal education and the outcome.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.131","n":131,"part":2,"topic":"Biostatistics and Data","stars":3,"years":["25M","24M"],"colleges":"SSMC (2nd Term B2); MMC (2nd Term B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Define census. Mention the types of census.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Census</strong>: the total process of collecting, compiling, evaluating, analysing and publishing demographic, economic and social data relating to <strong>all persons</strong> in a country (or defined part) at a <strong>specified time</strong> (UN).</p>\n<p><strong>Types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Type</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Place of counting</td>\n<td><strong>De facto</strong></td>\n<td>Counts people where they are found on census night</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>De jure</strong></td>\n<td>Counts people at their usual place of residence</td>\n</tr>\n<tr>\n<td>Coverage</td>\n<td>Complete census</td>\n<td>Whole population</td>\n</tr>\n<tr>\n<td></td>\n<td>Sample census</td>\n<td>Part of population for detailed questions</td>\n</tr>\n<tr>\n<td>Subject</td>\n<td>Population and housing census; agricultural; economic census</td>\n<td>—</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.132","n":132,"part":2,"topic":"Biostatistics and Data","stars":0,"years":[],"colleges":"DMC (1st Assess B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss different types of bar diagram with figure.</p>","a":"<p><strong>Types of bar diagram</strong></p>\n<p><strong>1. Simple bar diagram</strong>: one variable; one bar per category.</p>\n<pre><code>Coverage (%)\n 90 | ████\n 80 | ████  ████\n 70 | ████  ████  ████\n    +------------------\n      BCG   Penta3  MR1\n</code></pre>\n<p><strong>2. Multiple (grouped) bar diagram</strong>: two or more related variables side by side for each category; shading distinguishes them.</p>\n<pre><code>Literacy (%)     ▓ Male  ░ Female\n 80 | ▓▓░░\n 60 | ▓▓░░   ▓▓░░\n 40 | ▓▓░░   ▓▓░░\n    +----------------\n      Urban   Rural\n</code></pre>\n<p><strong>3. Component (sub-divided) bar diagram</strong>: each bar shows the total, divided into parts.</p>\n<pre><code>Total deaths\n 100 | ░░░ (others)\n  60 | ▒▒▒ (diarrhoea)\n  30 | ▓▓▓ (pneumonia)\n     +-----\n       2024\n</code></pre>\n<p><strong>4. Proportional (percentage) bar diagram</strong>: all bars of equal height (100%), divided into percentage components; compares composition across groups.</p>\n<pre><code>100% | ░░░  ░░░\n     | ▒▒▒  ░░░\n     | ▓▓▓  ▒▒▒\n     +-----------\n      Urban Rural\n  ▓ Facility  ▒ Home (trained)  ░ Home (untrained)\n</code></pre>\n<p><strong>General rules</strong></p>\n<p>Equal bar width and spacing; scale from zero; title, labels, legend.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.133","n":133,"part":2,"topic":"Biostatistics and Data","stars":0,"years":[],"colleges":"SSMC (1st Supp B3)","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the importance of vital statistics.</p>","a":"<p><strong>Importance (uses) of vital statistics</strong></p>\n<p><strong>A. Health</strong></p>\n<ol>\n<li><strong>Measure health status</strong> of a population: CBR, CDR, IMR, MMR, life expectancy.</li>\n<li><strong>Compare</strong> health between regions, groups and countries; over time.</li>\n<li><strong>Identify problems</strong> and high-risk groups (high neonatal or maternal deaths).</li>\n<li><strong>Plan, monitor and evaluate</strong> health programmes (MCH, EPI, FP).</li>\n<li><strong>Research</strong>: trends and causes of death; epidemiological studies.</li>\n<li>Monitor <strong>national and international goals</strong> (SDG 3).</li>\n</ol>\n<p><strong>B. Demographic</strong></p>\n<ol>\n<li>Population growth, natural increase, fertility.</li>\n<li>Population <strong>projections</strong> for planning.</li>\n</ol>\n<p><strong>C. Legal and administrative (individual)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Certificate</th>\n<th>Uses</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Birth certificate</td>\n<td>Proof of age, nationality; school admission; marriage age; passport, NID; inheritance; employment</td>\n</tr>\n<tr>\n<td>Death certificate</td>\n<td>Inheritance and property transfer; insurance and pension claims; cause-of-death statistics</td>\n</tr>\n<tr>\n<td>Marriage registration</td>\n<td>Legal rights of spouses; prevention of child marriage</td>\n</tr>\n</tbody>\n</table>\n<p><strong>D. Social and economic planning</strong></p>\n<p>Education, housing, employment, food supply, social security.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics; Demography and Family Planning).</p>"},{"id":"DU.134","n":134,"part":2,"topic":"Biostatistics and Data","stars":0,"years":[],"colleges":"SSMC (2nd Term B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between de facto and de jure census.</p>","a":"<p><strong>De facto vs de jure census</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>De facto census</th>\n<th>De jure census</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Meaning</td>\n<td>Persons counted <strong>where they are found</strong> at the census moment</td>\n<td>Persons counted at their <strong>usual place of residence</strong></td>\n</tr>\n<tr>\n<td>Basis</td>\n<td>Actual presence</td>\n<td>Legal / usual residence</td>\n</tr>\n<tr>\n<td>Visitors</td>\n<td>Counted where present</td>\n<td>Counted at home</td>\n</tr>\n<tr>\n<td>Absent residents</td>\n<td>Not counted at home</td>\n<td>Counted at home</td>\n</tr>\n<tr>\n<td>Procedure</td>\n<td>Simpler; usually done in one night</td>\n<td>Longer period; needs rules for &quot;usual residence&quot;</td>\n</tr>\n<tr>\n<td>Error risk</td>\n<td>Less omission or double count</td>\n<td>Possible double counting or omission</td>\n</tr>\n<tr>\n<td>Picture given</td>\n<td>Population present (good for services on the spot)</td>\n<td>Permanent population (good for planning)</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Traveller on census night counted at the hotel</td>\n<td>Traveller counted at his home district</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.135","n":135,"part":2,"topic":"Research","stars":0,"years":["17Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define and classify research instrument.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Research instrument</strong>: a tool or device used to collect, measure and record data from study subjects in a valid and reliable way.</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Use</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Questionnaire</strong> (self-administered)</td>\n<td>Literate respondents; large samples</td>\n<td>Online survey on smoking</td>\n</tr>\n<tr>\n<td><strong>Interview schedule</strong> (structured / semi-structured / unstructured)</td>\n<td>Interviewer asks and records</td>\n<td>Household survey on ANC</td>\n</tr>\n<tr>\n<td><strong>Observation checklist</strong></td>\n<td>Recording observed behaviour or conditions</td>\n<td>Hand-hygiene audit</td>\n</tr>\n<tr>\n<td><strong>Measuring instruments</strong></td>\n<td>Physical and physiological measurements</td>\n<td>Weighing scale, stadiometer, MUAC tape, sphygmomanometer</td>\n</tr>\n<tr>\n<td><strong>Laboratory instruments / tests</strong></td>\n<td>Biochemical and microbiological data</td>\n<td>Haemoglobinometer, glucometer, GeneXpert</td>\n</tr>\n<tr>\n<td><strong>Rating scales / psychometric tools</strong></td>\n<td>Attitudes, symptoms, quality of life</td>\n<td>Likert scale, PHQ-9, WHOQOL-BREF</td>\n</tr>\n<tr>\n<td><strong>Record review form (data extraction sheet)</strong></td>\n<td>Secondary data</td>\n<td>Hospital record review</td>\n</tr>\n<tr>\n<td><strong>Qualitative guides</strong></td>\n<td>FGD guide, in-depth interview guide</td>\n<td>Barriers to facility delivery</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Qualities of a good instrument</strong></p>\n<p>Valid; reliable; simple; acceptable; culturally appropriate; pretested; easy to code and analyse.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics; Principles of Epidemiology).</p>"},{"id":"DU.136","n":136,"part":2,"topic":"Research","stars":0,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the importance of research in biomedical science.</p>","a":"<p><strong>Importance of research in biomedical science</strong></p>\n<ol>\n<li><strong>New knowledge</strong>: structure and function of the body, mechanisms of disease.</li>\n<li><strong>Causes and risk factors</strong>: e.g., smoking and lung cancer; HPV and cervical cancer.</li>\n<li><strong>New diagnostics</strong>: rapid tests, GeneXpert for TB.</li>\n<li><strong>New treatments and vaccines</strong>: antibiotics, ART, HPV vaccine.</li>\n<li><strong>Evidence-based medicine</strong>: replaces opinion with tested evidence.</li>\n<li><strong>Evaluation</strong> of drugs, procedures and programmes (efficacy, safety, cost-effectiveness).</li>\n<li><strong>Prevention strategies</strong> and public health policy.</li>\n<li><strong>Health systems improvement</strong>: quality, access, efficiency (operational research).</li>\n<li><strong>Local problems</strong>: research in the local setting finds suitable solutions.</li>\n<li><strong>Training and critical thinking</strong> of doctors.</li>\n<li><strong>Economic benefit</strong>: reduces cost of disease; supports pharmaceutical industry.</li>\n<li><strong>Ethics and safety</strong>: detects adverse effects (pharmacovigilance).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.137","n":137,"part":2,"topic":"Research","stars":3,"years":["25M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Explain the importance of literature review in research.</p>","a":"<p><strong>Literature review</strong></p>\n<p>A systematic search, reading and critical summary of published and unpublished work on the research topic.</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li><strong>Shows what is already known</strong> and what is not → identifies the <strong>gap</strong>.</li>\n<li><strong>Avoids duplication</strong> of research already done.</li>\n<li><strong>Refines the research problem</strong>, question, objectives and hypothesis.</li>\n<li><strong>Justifies the study</strong> (rationale, significance).</li>\n<li>Builds the <strong>conceptual / theoretical framework</strong> and identifies variables.</li>\n<li>Guides choice of <strong>study design, methods, sample size and instruments</strong> (validated tools).</li>\n<li>Warns of <strong>problems and biases</strong> faced by others.</li>\n<li>Helps <strong>interpret and compare results</strong> in the discussion.</li>\n<li>Provides <strong>references</strong> and credibility.</li>\n<li>Improves the researcher's knowledge and critical thinking.</li>\n<li><strong>Ethical</strong>: prevents exposing subjects to unnecessary research.</li>\n</ol>\n<p><strong>Sources</strong></p>\n<p>Textbooks, journals (PubMed, Google Scholar, BanglaJOL), reports (WHO, BDHS), theses, grey literature.</p>\n<p><strong>Steps</strong></p>\n<p>Search → Select → Read critically → Organise → Write summary → Cite references</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.138","n":138,"part":2,"topic":"Research","stars":0,"years":[],"colleges":"MMC (1st Supp C5)","asked":"","note":"","kind":"","sub":"","q":"<p>Define and classify research.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Research</strong>: a systematic, organised and objective investigation, using the scientific method, to discover new facts, verify existing knowledge and find relationships, in order to solve problems.</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Purpose</strong></td>\n<td>Basic (pure) / Applied / Action research</td>\n<td>Mechanism of insulin resistance / best diabetes education method / improving CC services</td>\n</tr>\n<tr>\n<td><strong>Approach</strong></td>\n<td>Quantitative / Qualitative / Mixed methods</td>\n<td>Prevalence of hypertension / reasons for home delivery (FGD)</td>\n</tr>\n<tr>\n<td><strong>Design</strong></td>\n<td>Descriptive (case report, case series, cross-sectional)</td>\n<td>Prevalence of anaemia</td>\n</tr>\n<tr>\n<td></td>\n<td>Analytical observational (case-control, cohort)</td>\n<td>Smoking and lung cancer</td>\n</tr>\n<tr>\n<td></td>\n<td>Experimental / interventional (RCT, field trial, community trial)</td>\n<td>Vaccine trial</td>\n</tr>\n<tr>\n<td><strong>Time</strong></td>\n<td>Cross-sectional / Longitudinal; retrospective / prospective</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>Field</strong></td>\n<td>Biomedical, clinical, epidemiological, health systems / operational research</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>Setting</strong></td>\n<td>Laboratory / clinical (hospital) / field (community)</td>\n<td>—</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.139","n":139,"part":2,"topic":"Research","stars":0,"years":[],"colleges":"MMC (1st Supp C5)","asked":"","note":"","kind":"","sub":"","q":"<p>You are going to conduct research: what steps will you follow to do it?</p>","a":"<p><strong>Steps of research</strong></p>\n<p>Problem → Literature review → Objectives / hypothesis → Design → Sampling → Tools → Ethics → Data collection → Analysis → Report → Use</p>\n<ol>\n<li><strong>Identify and define the research problem</strong> (relevant, feasible, ethical).</li>\n<li><strong>Review the literature</strong>.</li>\n<li><strong>Formulate research question, objectives</strong> (general, specific) and <strong>hypothesis</strong>.</li>\n<li>Identify <strong>variables</strong>; draw the <strong>conceptual framework</strong>; operational definitions.</li>\n<li>Select the <strong>study design</strong> (cross-sectional, case-control, cohort, trial).</li>\n<li>Define <strong>study population, place and period</strong>; inclusion and exclusion criteria.</li>\n<li>Decide <strong>sample size and sampling technique</strong>.</li>\n<li>Choose <strong>data collection methods</strong> and prepare <strong>instruments</strong>; <strong>pretest</strong>.</li>\n<li>Plan <strong>data management and analysis</strong> (statistical tests, software).</li>\n<li>Obtain <strong>ethical clearance</strong> (e.g., BMRC / institutional review board) and informed consent.</li>\n<li>Prepare <strong>work plan, budget</strong> → complete <strong>research protocol</strong>.</li>\n<li><strong>Collect data</strong>; supervise quality.</li>\n<li><strong>Process and analyse data</strong>.</li>\n<li><strong>Interpret</strong> results; draw conclusions.</li>\n<li><strong>Write the report</strong> / paper and <strong>disseminate</strong> (seminar, journal).</li>\n<li><strong>Utilise findings</strong> for policy and practice.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.140","n":140,"part":2,"topic":"Research","stars":0,"years":[],"colleges":"MuMC (1st Final B4, 1st Supp B3)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the rules of writing an abstract?</p>","a":"<p><strong>Rules of writing an abstract</strong></p>\n<p><strong>A. Structure (structured abstract)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Heading</th>\n<th>Content</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Background / Introduction</td>\n<td>Problem and why it matters (1–2 lines)</td>\n</tr>\n<tr>\n<td>Objective</td>\n<td>Aim of the study</td>\n</tr>\n<tr>\n<td>Methods</td>\n<td>Design, setting, period, participants, sample size, sampling, tools, analysis</td>\n</tr>\n<tr>\n<td>Results</td>\n<td>Main findings with key numbers (%, mean, OR, CI, p-value)</td>\n</tr>\n<tr>\n<td>Conclusion</td>\n<td>Main message and recommendation</td>\n</tr>\n<tr>\n<td>Keywords</td>\n<td>3–6 terms (MeSH)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Rules</strong></p>\n<ol>\n<li><strong>Brief</strong>: within word limit (usually 150–300 words; follow the journal or conference).</li>\n<li><strong>Self-contained</strong>: understandable without the full paper.</li>\n<li><strong>Write it last</strong>, after the full report.</li>\n<li><strong>Consistent</strong> with the main text; no new information.</li>\n<li><strong>No references, tables, figures</strong> or long quotations.</li>\n<li>Avoid <strong>abbreviations</strong>, or define them at first use.</li>\n<li>Use <strong>past tense</strong> for methods and results.</li>\n<li>Give <strong>specific results</strong> with numbers, not vague statements.</li>\n<li>Conclusion must follow from the results; no over-claiming.</li>\n<li>Clear, simple language; no jargon.</li>\n<li>Title and abstract should contain the key words for indexing.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.141","n":141,"part":2,"topic":"Research","stars":0,"years":[],"colleges":"MuMC (1st Final B4, 1st Supp B3)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention three qualities of a good questionnaire.</p>","a":"<p><strong>Three qualities of a good questionnaire</strong></p>\n<ol>\n<li><strong>Valid</strong>: measures what it is meant to measure.</li>\n<li><strong>Reliable</strong>: gives consistent answers on repetition.</li>\n<li><strong>Simple and clear</strong>: short, easy, unambiguous questions in the respondent's language.</li>\n</ol>\n<p><strong>Other qualities</strong></p>\n<ol start=\"4\">\n<li><strong>Relevant</strong> to study objectives; no unnecessary questions.</li>\n<li><strong>Logical sequence</strong>: general to specific; sensitive questions later.</li>\n<li><strong>Unbiased</strong>: no leading or loaded questions; no double-barrelled questions.</li>\n<li><strong>Appropriate mix</strong> of closed (easy to analyse) and open questions.</li>\n<li><strong>Pretested</strong> (pilot study) and revised.</li>\n<li>Clear <strong>instructions</strong> and skip patterns.</li>\n<li>Attractive <strong>layout</strong>; easy to code and enter.</li>\n<li><strong>Ethical</strong>: consent statement; confidentiality; respects culture.</li>\n<li>Reasonable <strong>length</strong> (avoids respondent fatigue).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.142","n":142,"part":2,"topic":"Sample and Sampling","stars":3,"years":["24M","20Nov","19Nov","17Ja","16Nov","09Ja"],"colleges":"DMC (1st Assess B1); MMC (1st Supp C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Define population, sample, study population. What is sampling?</p>","a":"<p><strong>Definitions</strong></p>\n<table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Definition</th>\n<th>Example (study of hypertension among adults in Mymensingh)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Population (target / reference population)</strong></td>\n<td>The whole group of individuals (or units) about whom information is required and to whom results will apply</td>\n<td>All adults (≥18 years) of Mymensingh</td>\n</tr>\n<tr>\n<td><strong>Study population (accessible population)</strong></td>\n<td>The part of the target population that is actually available and from which the sample is drawn</td>\n<td>Adults of selected wards listed in the sampling frame</td>\n</tr>\n<tr>\n<td><strong>Sample</strong></td>\n<td>A part (subset) of the population selected for study, which should represent the population</td>\n<td>400 adults selected by random sampling</td>\n</tr>\n<tr>\n<td><strong>Sampling</strong></td>\n<td>The process of selecting a sample from the population</td>\n<td>Simple random, systematic, cluster sampling</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.143","n":143,"part":2,"topic":"Sample and Sampling","stars":3,"years":["25M","23Nov","22Nov","19M","18M","17Nov","17M","17Ja","16Nov","15Ja","12Ju","11Ju","09Ja"],"colleges":"DMC (1st Assess B1)","asked":"briefly discuss simple random sampling with an example","note":"","kind":"","sub":"","q":"<p>Classify sampling / what are the types (methods, techniques) of sampling? Briefly describe the various methods (also: classify sampling for data collection with examples).</p>","a":"<p><strong>Classification of sampling</strong></p>\n<p><strong>A. Probability (random) sampling</strong>: every unit has a known, non-zero chance of selection → representative; results can be generalised.</p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Procedure</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Simple random</strong></td>\n<td>Each unit has an equal chance; lottery or random number table/computer</td>\n<td>50 students chosen by lottery from a list of 500</td>\n</tr>\n<tr>\n<td><strong>Systematic</strong></td>\n<td>Every kᵗʰ unit after a random start (k = N ÷ n)</td>\n<td>Every 10th household in a village</td>\n</tr>\n<tr>\n<td><strong>Stratified</strong></td>\n<td>Population divided into homogeneous strata (age, sex, urban/rural); random sample from each</td>\n<td>Sampling urban and rural mothers separately</td>\n</tr>\n<tr>\n<td><strong>Cluster</strong></td>\n<td>Groups (villages, schools) randomly selected; all units in chosen clusters studied</td>\n<td>EPI 30-cluster coverage survey</td>\n</tr>\n<tr>\n<td><strong>Multistage</strong></td>\n<td>Sampling in stages (district → upazila → union → household)</td>\n<td>BDHS</td>\n</tr>\n<tr>\n<td>Multiphase</td>\n<td>Some information from whole sample, more from a sub-sample</td>\n<td>Screening all, detailed tests in positives</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Non-probability sampling</strong>: selection not by chance; may not represent the population.</p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Procedure</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Convenience</td>\n<td>Whoever is easily available</td>\n<td>OPD patients on study days</td>\n</tr>\n<tr>\n<td>Purposive (judgement)</td>\n<td>Chosen by researcher for a purpose</td>\n<td>Key informants for FGD</td>\n</tr>\n<tr>\n<td>Quota</td>\n<td>Fixed numbers from each category, chosen conveniently</td>\n<td>50 men and 50 women</td>\n</tr>\n<tr>\n<td>Snowball</td>\n<td>Subjects refer others</td>\n<td>Injecting drug users</td>\n</tr>\n<tr>\n<td>Consecutive</td>\n<td>All eligible patients in a period</td>\n<td>All MI cases admitted in 3 months</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Simple random sampling (example)</strong></p>\n<p>To select 50 out of 500 school children: number them 1–500 → draw 50 numbers by lottery or random number table → each child has an equal (1 in 10) chance.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.144","n":144,"part":2,"topic":"Sample and Sampling","stars":0,"years":["10Ja","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the types of probability sampling techniques with example.</p>","a":"<p><strong>Types of probability sampling</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Description</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Simple random sampling</strong></td>\n<td>Every unit has an equal and independent chance; lottery, random number table or computer</td>\n<td>Selecting 100 patients from a list of 1,000 registered diabetics</td>\n</tr>\n<tr>\n<td>2. <strong>Systematic random sampling</strong></td>\n<td>First unit random, then every kᵗʰ unit (sampling interval k = N ÷ n)</td>\n<td>N = 2,000 households, n = 200 → every 10th household after a random start</td>\n</tr>\n<tr>\n<td>3. <strong>Stratified random sampling</strong></td>\n<td>Population divided into strata by a characteristic; random sample from each (proportionate or not)</td>\n<td>Selecting students separately from each year of MBBS</td>\n</tr>\n<tr>\n<td>4. <strong>Cluster sampling</strong></td>\n<td>Naturally occurring groups (clusters) randomly selected; all members studied</td>\n<td>30 villages selected; all under-5 children examined</td>\n</tr>\n<tr>\n<td>5. <strong>Multistage sampling</strong></td>\n<td>Random selection in successive stages</td>\n<td>Division → district → upazila → union → household</td>\n</tr>\n<tr>\n<td>6. <strong>Multiphase sampling</strong></td>\n<td>All sampled units give basic data; a sub-sample gives detailed data</td>\n<td>All children screened for anaemia; detailed tests in a sub-sample</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Merits of probability sampling</strong></p>\n<p>Representative; free from selection bias; sampling error can be measured; results can be generalised.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.145","n":145,"part":2,"topic":"Sample and Sampling","stars":0,"years":[],"colleges":"MuMC (1st Final C3, 1st Supp C2)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention three important differences between sample and population.</p>","a":"<p><strong>Sample vs population</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Population</th>\n<th>Sample</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Meaning</td>\n<td>Whole group of units about which information is required</td>\n<td>Part (subset) of the population selected for study</td>\n</tr>\n<tr>\n<td>2. Size</td>\n<td>Large (N)</td>\n<td>Smaller (n)</td>\n</tr>\n<tr>\n<td>3. Measures</td>\n<td><strong>Parameters</strong> (μ, σ, P), fixed but usually unknown</td>\n<td><strong>Statistics</strong> (x̄, s, p), vary from sample to sample; estimate parameters</td>\n</tr>\n<tr>\n<td>4. Study method</td>\n<td>Census (complete enumeration)</td>\n<td>Sampling survey</td>\n</tr>\n<tr>\n<td>5. Cost and time</td>\n<td>High</td>\n<td>Low</td>\n</tr>\n<tr>\n<td>6. Error</td>\n<td>No sampling error (may have non-sampling errors)</td>\n<td>Sampling error present</td>\n</tr>\n<tr>\n<td>7. Accuracy of collection</td>\n<td>Hard to supervise large numbers</td>\n<td>Better supervision, more detailed data</td>\n</tr>\n<tr>\n<td>8. Example</td>\n<td>All adults of Bangladesh</td>\n<td>2,000 adults in a national survey</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.146","n":146,"part":2,"topic":"Sample and Sampling","stars":0,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"SEQ","sub":"","q":"<p>If a study is carried out to see the prevalence of hypertension of a senior citizen of old Dhaka</p>\n<ul>\n<li>a) What would be the study design and why?</li>\n<li>b) Who will be your sample and what is your sampling technique?</li>\n<li>c) Who will be your population?</li>\n</ul>","a":"<p><strong>a) Study design and why</strong></p>\n<p><strong>Descriptive cross-sectional study</strong>.<br />\nWhy:</p>\n<ol>\n<li>Aim is <strong>prevalence</strong> (existing cases at one point in time).</li>\n<li>Exposure and outcome measured <strong>once</strong>, at the same time; no follow-up needed.</li>\n<li>Quick, cheap, feasible in a community.</li>\n<li>Gives baseline data for planning services for the elderly.</li>\n</ol>\n<p><strong>b) Sample and sampling technique</strong></p>\n<ul>\n<li><strong>Sample</strong>: a representative number of senior citizens (aged ≥60 years) living in old Dhaka, selected from the population, who meet inclusion criteria (permanent residents, consent) and exclusion criteria (seriously ill, unable to respond).</li>\n<li><strong>Sample size</strong>: n = z²pq ÷ d² (z = 1.96; p = expected prevalence of hypertension; q = 1 − p; d = allowable error).</li>\n<li><strong>Sampling technique</strong>: <strong>multistage (cluster) random sampling</strong>:<br />\nOld Dhaka wards → random selection of wards (clusters) → random selection of mohallas → systematic random selection of households → all eligible elderly persons in selected households.<br />\n(If a complete list of the elderly is available: simple or systematic random sampling.)</li>\n</ul>\n<p><strong>c) Population</strong></p>\n<ul>\n<li><strong>Target population</strong>: all senior citizens (≥60 years) residing in old Dhaka.</li>\n<li><strong>Study population</strong>: senior citizens of the selected wards who are available during the study period.</li>\n</ul>\n<p><strong>Outcome measurement</strong></p>\n<p>BP measured with a standard sphygmomanometer (two readings); hypertension = SBP ≥140 and/or DBP ≥90 mmHg or on treatment.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology; Health Information and Basic Medical Statistics).</p>"},{"id":"DU.147","n":147,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["16Ju","15Ja","13Ja","07Ju","05M","04M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the measures of central tendency? / Write down the statistical average with example / discuss with example.</p>","a":"<p><strong>Measures of central tendency (statistical averages)</strong></p>\n<p>A single value that represents the centre of a set of data.</p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Definition</th>\n<th>Formula / method</th>\n<th>Example (2, 3, 3, 5, 7)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Arithmetic mean</strong></td>\n<td>Sum of observations ÷ number</td>\n<td>x̄ = Σx ÷ n; grouped: Σfx ÷ Σf</td>\n<td>20 ÷ 5 = 4</td>\n</tr>\n<tr>\n<td><strong>Median</strong></td>\n<td>Middle value when data are arranged in order</td>\n<td>Odd n: (n + 1)/2 th value; even n: average of two middle values</td>\n<td>3</td>\n</tr>\n<tr>\n<td><strong>Mode</strong></td>\n<td>Most frequently occurring value</td>\n<td>Value with highest frequency</td>\n<td>3</td>\n</tr>\n<tr>\n<td>Geometric mean</td>\n<td>nth root of product of n values</td>\n<td>antilog (Σ log x ÷ n)</td>\n<td>Antibody titres, bacterial counts</td>\n</tr>\n<tr>\n<td>Harmonic mean</td>\n<td>Reciprocal of mean of reciprocals</td>\n<td>n ÷ Σ(1/x)</td>\n<td>Rates, speeds</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Merits and demerits</strong></p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Merits</th>\n<th>Demerits</th>\n<th>Best used for</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mean</td>\n<td>Uses all values; basis for further statistics</td>\n<td>Affected by extreme values</td>\n<td>Symmetrical data (Hb, height)</td>\n</tr>\n<tr>\n<td>Median</td>\n<td>Not affected by extremes; easy</td>\n<td>Ignores actual values; less used in tests</td>\n<td>Skewed data (income, survival time)</td>\n</tr>\n<tr>\n<td>Mode</td>\n<td>Easy; usable for qualitative data</td>\n<td>May be absent or multiple; unstable</td>\n<td>Most common category (commonest blood group)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Relationship</strong></p>\n<p>Symmetrical distribution: mean = median = mode. Skewed: Mode ≈ 3 Median − 2 Mean.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.148","n":148,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Find out the mean, median and mode of the series 1, 2, 3, 3, 3, 4, 5.</p>","a":"<p><strong>Data</strong>: 1, 2, 3, 3, 3, 4, 5 (n = 7; already in ascending order)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 1 + 2 + 3 + 3 + 3 + 4 + 5 = 21<br />\nx̄ = 21 ÷ 7 = <strong>3</strong></p>\n<p><strong>Median</strong></p>\n<p>n = 7 (odd) → median = (n + 1)/2 = 4th value<br />\n1, 2, 3, <strong>3</strong>, 3, 4, 5 → Median = <strong>3</strong></p>\n<p><strong>Mode</strong></p>\n<p>3 occurs 3 times (most frequent) → Mode = <strong>3</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean = median = mode = 3 → the distribution is <strong>symmetrical</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.149","n":149,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Find out mean and median from the values 4, 7, 5, 8, 6, 9, 7, 10, 8.</p>","a":"<p><strong>Data</strong>: 4, 7, 5, 8, 6, 9, 7, 10, 8 (n = 9)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 4 + 7 + 5 + 8 + 6 + 9 + 7 + 10 + 8 = 64<br />\nx̄ = 64 ÷ 9 = <strong>7.11</strong></p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 4, 5, 6, 7, <strong>7</strong>, 8, 8, 9, 10<br />\nn = 9 (odd) → (n + 1)/2 = 5th value → Median = <strong>7</strong></p>\n<p><strong>(Mode)</strong>: 7 and 8 each occur twice → bimodal (7, 8).</p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (7.11) and median (7) are almost equal → nearly symmetrical distribution.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.150","n":150,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["19M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Calculate mean from the following data of age in years.</p>\n<table>\n<thead>\n<tr>\n<th>Age in years</th>\n<th>5-9</th>\n<th>10-14</th>\n<th>15-19</th>\n<th>20-24</th>\n<th>25-29</th>\n<th>30-34</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Frequency</td>\n<td>6</td>\n<td>8</td>\n<td>9</td>\n<td>5</td>\n<td>3</td>\n<td>2</td>\n</tr>\n</tbody>\n</table>","a":"<p><strong>Formula (grouped data)</strong></p>\n<p>Mean x̄ = Σfx ÷ Σf, where x = mid-point of class interval</p>\n<p><strong>Calculation</strong></p>\n<table>\n<thead>\n<tr>\n<th>Age (years)</th>\n<th>Mid-point (x)</th>\n<th>Frequency (f)</th>\n<th>fx</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>5–9</td>\n<td>7</td>\n<td>6</td>\n<td>42</td>\n</tr>\n<tr>\n<td>10–14</td>\n<td>12</td>\n<td>8</td>\n<td>96</td>\n</tr>\n<tr>\n<td>15–19</td>\n<td>17</td>\n<td>9</td>\n<td>153</td>\n</tr>\n<tr>\n<td>20–24</td>\n<td>22</td>\n<td>5</td>\n<td>110</td>\n</tr>\n<tr>\n<td>25–29</td>\n<td>27</td>\n<td>3</td>\n<td>81</td>\n</tr>\n<tr>\n<td>30–34</td>\n<td>32</td>\n<td>2</td>\n<td>64</td>\n</tr>\n<tr>\n<td><strong>Total</strong></td>\n<td></td>\n<td><strong>Σf = 33</strong></td>\n<td><strong>Σfx = 546</strong></td>\n</tr>\n</tbody>\n</table>\n<p>Mid-point = (lower limit + upper limit) ÷ 2, e.g., (5 + 9) ÷ 2 = 7</p>\n<p>x̄ = 546 ÷ 33 = <strong>16.55 years</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>The mean age of the 33 persons is about 16.5 years; the modal class is 15–19 years (highest frequency, 9).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.151","n":151,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Estimated Hb% of eight pregnant mothers are 8, 8.5, 9.5, 10, 10.5, 11, 13 &amp; 12 mg/dl. Find out the median Hb level &amp; present the data graphically.</p>","a":"<p><strong>Data (Hb of 8 pregnant mothers)</strong>: 8, 8.5, 9.5, 10, 10.5, 11, 13, 12<br />\n(Unit should be <strong>g/dl</strong>, not mg/dl.)</p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 8, 8.5, 9.5, <strong>10, 10.5</strong>, 11, 12, 13<br />\nn = 8 (even) → average of 4th and 5th values<br />\nMedian = (10 + 10.5) ÷ 2 = <strong>10.25 g/dl</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Half the mothers have Hb below 10.25 g/dl; since anaemia in pregnancy is Hb &lt;11 g/dl (WHO), 5 of 8 mothers (62.5%) are anaemic.</p>\n<p><strong>Graphical presentation (simple bar diagram of each mother's Hb)</strong></p>\n<pre><code>Hb (g/dl)\n13 |                               ██\n12 |                          ██   ██\n11 |                     ██   ██   ██\n10 |           ██   ██   ██   ██   ██\n 9 |      ██   ██   ██   ██   ██   ██\n 8 | ██   ██   ██   ██   ██   ██   ██   ██\n   +---------------------------------------\n     M1   M2   M3   M4   M5   M6   M7   M8\n (M1 = 8, M2 = 8.5, M3 = 9.5, M4 = 10, M5 = 10.5, M6 = 11, M7 = 12, M8 = 13; arranged in ascending order)\n</code></pre>\n<p>Alternatively: dot plot along an Hb scale, with a line at 11 g/dl marking the anaemia cut-off.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics); WHO, haemoglobin cut-offs for anaemia.</p>"},{"id":"DU.152","n":152,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Calculate mean, median and modal values of: 52, 65, 52, 60, 45.</p>","a":"<p><strong>Data</strong>: 52, 65, 52, 60, 45 (n = 5)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 52 + 65 + 52 + 60 + 45 = 274<br />\nx̄ = 274 ÷ 5 = <strong>54.8</strong></p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 45, 52, <strong>52</strong>, 60, 65<br />\nn = 5 (odd) → (n + 1)/2 = 3rd value → Median = <strong>52</strong></p>\n<p><strong>Mode</strong></p>\n<p>52 occurs twice → Mode = <strong>52</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (54.8) &gt; median (52) = mode (52) → slight positive skew (pulled up by 65).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.153","n":153,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Give the flowchart of a study design to find out the outcomes of tobacco consumption. Age of 10 people are 83, 75, 81, 79, 71, 95, 75, 77, 84 &amp; 90 years. Find out the standard deviation of age.</p>","a":"<p><strong>a) Flowchart: cohort study to find outcomes of tobacco consumption</strong></p>\n<p>Defined population free of the outcomes (e.g., adults without cancer or CHD)<br />\n→ Classify by exposure:<br />\n<strong>Exposed</strong>: tobacco users | <strong>Non-exposed</strong>: non-users<br />\n→ Follow up both groups over time (e.g., 10 years)<br />\n→ Record outcomes: lung / oral cancer, CHD, stroke, COPD (develop / do not develop)<br />\n→ Calculate incidence in exposed and non-exposed<br />\n→ Relative risk = incidence in exposed ÷ incidence in non-exposed; attributable risk = difference</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>Outcome +</th>\n<th>Outcome −</th>\n<th>Total</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Tobacco users</td>\n<td>a</td>\n<td>b</td>\n<td>a + b</td>\n</tr>\n<tr>\n<td>Non-users</td>\n<td>c</td>\n<td>d</td>\n<td>c + d</td>\n</tr>\n</tbody>\n</table>\n<p>RR = [a/(a + b)] ÷ [c/(c + d)]</p>\n<p><strong>b) Standard deviation of age</strong></p>\n<p>Data: 83, 75, 81, 79, 71, 95, 75, 77, 84, 90 (n = 10)<br />\nMean = 810 ÷ 10 = <strong>81 years</strong></p>\n<table>\n<thead>\n<tr>\n<th>x</th>\n<th>x − x̄</th>\n<th>(x − x̄)²</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>83</td>\n<td>2</td>\n<td>4</td>\n</tr>\n<tr>\n<td>75</td>\n<td>−6</td>\n<td>36</td>\n</tr>\n<tr>\n<td>81</td>\n<td>0</td>\n<td>0</td>\n</tr>\n<tr>\n<td>79</td>\n<td>−2</td>\n<td>4</td>\n</tr>\n<tr>\n<td>71</td>\n<td>−10</td>\n<td>100</td>\n</tr>\n<tr>\n<td>95</td>\n<td>14</td>\n<td>196</td>\n</tr>\n<tr>\n<td>75</td>\n<td>−6</td>\n<td>36</td>\n</tr>\n<tr>\n<td>77</td>\n<td>−4</td>\n<td>16</td>\n</tr>\n<tr>\n<td>84</td>\n<td>3</td>\n<td>9</td>\n</tr>\n<tr>\n<td>90</td>\n<td>9</td>\n<td>81</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><strong>Σ = 482</strong></td>\n</tr>\n</tbody>\n</table>\n<p>SD = √[Σ(x − x̄)² ÷ (n − 1)] = √(482 ÷ 9) = √53.56 = <strong>7.32 years</strong><br />\n(Small sample, n &lt;30, so n − 1 is used; with n as divisor, SD = √48.2 = 6.94 years.)</p>\n<p><strong>Interpretation</strong>: ages vary on average by about 7.3 years around the mean of 81 years.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology; Health Information and Basic Medical Statistics).</p>"},{"id":"DU.154","n":154,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Compute mean, median and modal values from: 62, 75, 62, 70, 55, 52, 56, 68, 46, 63 and 50.</p>","a":"<p><strong>Data</strong>: 62, 75, 62, 70, 55, 52, 56, 68, 46, 63, 50 (n = 11)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 62 + 75 + 62 + 70 + 55 + 52 + 56 + 68 + 46 + 63 + 50 = 659<br />\nx̄ = 659 ÷ 11 = <strong>59.91</strong></p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 46, 50, 52, 55, 56, <strong>62</strong>, 62, 63, 68, 70, 75<br />\nn = 11 (odd) → (n + 1)/2 = 6th value → Median = <strong>62</strong></p>\n<p><strong>Mode</strong></p>\n<p>62 occurs twice → Mode = <strong>62</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (59.9) &lt; median (62) = mode (62) → slight negative (left) skew, pulled down by low values (46, 50).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.155","n":155,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["16Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is simple random sample (SRS)? Compute mean, median and modal values from: 52, 65, 52, 60, 45, 42, 46, 58, 36, 52, 40.</p>","a":"<p><strong>Simple random sample (SRS)</strong></p>\n<p>A sample in which <strong>every unit of the population has an equal and independent chance</strong> of being selected; drawn by lottery, random number table or computer from a complete sampling frame.<br />\nExample: selecting 50 children by lottery from a school list of 500.</p>\n<p><strong>Calculation</strong></p>\n<p>Data: 52, 65, 52, 60, 45, 42, 46, 58, 36, 52, 40 (n = 11)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 52 + 65 + 52 + 60 + 45 + 42 + 46 + 58 + 36 + 52 + 40 = 548<br />\nx̄ = 548 ÷ 11 = <strong>49.82</strong></p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 36, 40, 42, 45, 46, <strong>52</strong>, 52, 52, 58, 60, 65<br />\nn = 11 (odd) → 6th value → Median = <strong>52</strong></p>\n<p><strong>Mode</strong></p>\n<p>52 occurs 3 times → Mode = <strong>52</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (49.8) &lt; median = mode (52) → slight negative skew.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.156","n":156,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["22M","12Ja"],"colleges":"ShSMC (1st Term C2)","asked":"write down the measures of dispersion with example","note":"","kind":"","sub":"","q":"<p>Name measures of dispersion.</p>","a":"<p><strong>Measures of dispersion (variation)</strong></p>\n<p>Show how widely observations are scattered around the central value.</p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Definition / formula</th>\n<th>Example (2, 4, 6, 8, 10; mean 6)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Range</strong></td>\n<td>Highest − lowest value</td>\n<td>10 − 2 = 8</td>\n</tr>\n<tr>\n<td>2. <strong>Interquartile range</strong></td>\n<td>Q3 − Q1 (middle 50% of data)</td>\n<td>Used with median in skewed data</td>\n</tr>\n<tr>\n<td>3. <strong>Mean deviation</strong></td>\n<td>Σ|x − x̄| ÷ n</td>\n<td>(4 + 2 + 0 + 2 + 4) ÷ 5 = 2.4</td>\n</tr>\n<tr>\n<td>4. <strong>Standard deviation (SD)</strong></td>\n<td>√[Σ(x − x̄)² ÷ (n − 1)]</td>\n<td>√(40 ÷ 4) = 3.16</td>\n</tr>\n<tr>\n<td>5. <strong>Variance</strong></td>\n<td>SD²</td>\n<td>10</td>\n</tr>\n<tr>\n<td>6. <strong>Coefficient of variation (CV)</strong></td>\n<td>(SD ÷ mean) × 100</td>\n<td>(3.16 ÷ 6) × 100 = 52.7%</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.157","n":157,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Diastolic blood pressures (DBP) of 10 people are 83, 75, 81, 79, 71, 90, 75, 95, 77 and 94 mmHg. What is the range of DBP?</p>","a":"<p><strong>Data (DBP, mmHg)</strong>: 83, 75, 81, 79, 71, 90, 75, 95, 77, 94</p>\n<p><strong>Range</strong></p>\n<p>Range = highest value − lowest value<br />\nHighest = 95 mmHg; lowest = 71 mmHg<br />\nRange = 95 − 71 = <strong>24 mmHg</strong> (71 to 95 mmHg)</p>\n<p><strong>Interpretation</strong></p>\n<p>Diastolic pressures of the 10 people spread over 24 mmHg.</p>\n<p><strong>Note</strong></p>\n<p>Range is the simplest measure of dispersion but uses only two extreme values; SD is more reliable.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.158","n":158,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":2,"years":["12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>In a slum, there are 50 children with PEM out of 500 children. Total 2000 people live in that slum. Calculate proportion of PEM among the children.</p>","a":"<p><strong>Proportion</strong></p>\n<p>Proportion = (number with the characteristic ÷ total in the group from which they come) × 100</p>\n<p><strong>Calculation</strong></p>\n<p>Children with PEM = 50; total children = 500</p>\n<p>Proportion of PEM among children = (50 ÷ 500) × 100 = <strong>10%</strong></p>\n<p><strong>Note</strong></p>\n<ul>\n<li>The denominator must be <strong>children</strong> (the population at risk), not the total slum population (2,000), because the question asks about PEM among children.</li>\n<li>2,000 would give PEM per total population = (50 ÷ 2,000) × 100 = 2.5%, which is not the asked measure.</li>\n</ul>\n<p><strong>Interpretation</strong></p>\n<p>One in every ten children in the slum has protein-energy malnutrition; this is the <strong>prevalence</strong> of PEM among children.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.159","n":159,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Age of 8 people are 52, 42, 65, 52, 60, 45, 38, 40. Find out median age and present the data graphically.</p>","a":"<p><strong>Data (age, years)</strong>: 52, 42, 65, 52, 60, 45, 38, 40 (n = 8)</p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 38, 40, 42, <strong>45, 52</strong>, 52, 60, 65<br />\nn = 8 (even) → average of 4th and 5th values<br />\nMedian = (45 + 52) ÷ 2 = <strong>48.5 years</strong></p>\n<p><strong>Graphical presentation (simple bar diagram, persons arranged by age)</strong></p>\n<pre><code>Age (years)\n70 |\n60 |                               ██   ██\n50 |                     ██   ██   ██   ██\n40 |      ██   ██   ██   ██   ██   ██   ██\n30 | ██   ██   ██   ██   ██   ██   ██   ██\n   +---------------------------------------\n     P1   P2   P3   P4   P5   P6   P7   P8\n   (38) (40) (42) (45) (52) (52) (60) (65)\n</code></pre>\n<p>The median (48.5 years) lies between the 4th and 5th bars.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.160","n":160,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":0,"years":[],"colleges":"DMC (1st Assess B5)","asked":"","note":"","kind":"","sub":"","q":"<p>The mid-upper arm circumference (in cm) of 22 children is given: 20, 19, 22, 16, 18, 17, 14, 20, 12, 18, 16, 17, 21, 24, 22, 20, 18, 19, 20, 18, 17 and 20. Calculate the mean, median and mode.</p>","a":"<p><strong>Data (MUAC, cm; n = 22)</strong>: 20, 19, 22, 16, 18, 17, 14, 20, 12, 18, 16, 17, 21, 24, 22, 20, 18, 19, 20, 18, 17, 20</p>\n<p><strong>Frequency table</strong></p>\n<table>\n<thead>\n<tr>\n<th>MUAC (x)</th>\n<th>12</th>\n<th>14</th>\n<th>16</th>\n<th>17</th>\n<th>18</th>\n<th>19</th>\n<th>20</th>\n<th>21</th>\n<th>22</th>\n<th>24</th>\n<th>Total</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>f</td>\n<td>1</td>\n<td>1</td>\n<td>2</td>\n<td>3</td>\n<td>4</td>\n<td>2</td>\n<td><strong>5</strong></td>\n<td>1</td>\n<td>2</td>\n<td>1</td>\n<td>22</td>\n</tr>\n<tr>\n<td>fx</td>\n<td>12</td>\n<td>14</td>\n<td>32</td>\n<td>51</td>\n<td>72</td>\n<td>38</td>\n<td>100</td>\n<td>21</td>\n<td>44</td>\n<td>24</td>\n<td><strong>408</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Mean</strong></p>\n<p>x̄ = Σfx ÷ n = 408 ÷ 22 = <strong>18.55 cm</strong></p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 12, 14, 16, 16, 17, 17, 17, 18, 18, 18, <strong>18, 19</strong>, 19, 20, 20, 20, 20, 20, 21, 22, 22, 24<br />\nn = 22 (even) → average of 11th and 12th values = (18 + 19) ÷ 2 = <strong>18.5 cm</strong></p>\n<p><strong>Mode</strong></p>\n<p>20 occurs 5 times → Mode = <strong>20 cm</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean 18.55, median 18.5, mode 20 cm; slight negative skew (low values 12, 14). (Note: MUAC values below 11.5 cm in children 6–59 months indicate severe acute malnutrition.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.161","n":161,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":0,"years":[],"colleges":"SSMC (1st Supp D1)","asked":"","note":"","kind":"","sub":"","q":"<p>Calculate mean &amp; median from the following data: 1, 2, 3, 5, 7, 9.</p>","a":"<p><strong>Data</strong>: 1, 2, 3, 5, 7, 9 (n = 6; already in ascending order)</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 1 + 2 + 3 + 5 + 7 + 9 = 27<br />\nx̄ = 27 ÷ 6 = <strong>4.5</strong></p>\n<p><strong>Median</strong></p>\n<p>n = 6 (even) → average of 3rd and 4th values<br />\n1, 2, <strong>3, 5</strong>, 7, 9 → Median = (3 + 5) ÷ 2 = <strong>4</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (4.5) &gt; median (4) → slight positive skew (higher values 7 and 9).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.162","n":162,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":0,"years":[],"colleges":"MuMC (1st Final D5, 1st Supp D4)","asked":"","note":"","kind":"","sub":"","q":"<p>A community medicine researcher collected the following systolic blood pressure (mmHg) readings of adult patients attending an outpatient department: 120, 130, 125, 140, 135, 128, 132, 130, 138, 126. Calculate mean, median &amp; mode of the given data. (The 1st Final paper says 11 patients, the 1st Supp paper says 10; the list printed has 10 values.)</p>","a":"<p><strong>Data (SBP, mmHg; 10 values as printed)</strong>: 120, 130, 125, 140, 135, 128, 132, 130, 138, 126</p>\n<p><strong>Mean</strong></p>\n<p>Σx = 120 + 130 + 125 + 140 + 135 + 128 + 132 + 130 + 138 + 126 = 1304<br />\nx̄ = 1304 ÷ 10 = <strong>130.4 mmHg</strong></p>\n<p><strong>Median</strong></p>\n<p>Ascending order: 120, 125, 126, 128, <strong>130, 130</strong>, 132, 135, 138, 140<br />\nn = 10 (even) → average of 5th and 6th values<br />\nMedian = (130 + 130) ÷ 2 = <strong>130 mmHg</strong></p>\n<p><strong>Mode</strong></p>\n<p>130 occurs twice → Mode = <strong>130 mmHg</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Mean (130.4) ≈ median (130) = mode (130) → nearly <strong>symmetrical</strong> distribution; average SBP of OPD adults is about 130 mmHg.</p>\n<p><strong>Note</strong></p>\n<p>If 11 values are given in the paper, add the extra value, recompute Σx ÷ 11, and take the 6th ordered value as the median.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.163","n":163,"part":2,"topic":"Central Tendency & Measures of Dispersion","stars":0,"years":[],"colleges":"ShSMC (1st Term B5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>Two groups have SBP: Group A: Mean = 120 mmHg, SD = 5; Group B: Mean = 120 mmHg, SD = 20. [7]</p>\n<ul>\n<li>a) Which group has greater variability? (2)</li>\n<li>b) Interpret SD of both. (3)</li>\n<li>c) Which group is more consistent? (2)</li>\n</ul>","a":"<p><strong>a) Greater variability (2)</strong></p>\n<p><strong>Group B</strong> (SD = 20 mmHg) has greater variability than Group A (SD = 5 mmHg), though both have the same mean (120 mmHg).</p>\n<p><strong>b) Interpretation of SD (3)</strong></p>\n<p>Assuming normal distribution:</p>\n<table>\n<thead>\n<tr>\n<th>Range</th>\n<th>Group A (120 ± 5)</th>\n<th>Group B (120 ± 20)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mean ± 1 SD (~68%)</td>\n<td>115–125 mmHg</td>\n<td>100–140 mmHg</td>\n</tr>\n<tr>\n<td>Mean ± 2 SD (~95%)</td>\n<td>110–130 mmHg</td>\n<td>80–160 mmHg</td>\n</tr>\n<tr>\n<td>Mean ± 3 SD (~99.7%)</td>\n<td>105–135 mmHg</td>\n<td>60–180 mmHg</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Group A</strong>: SBP values lie close to the mean; members are similar (homogeneous); the mean represents the group well.</li>\n<li><strong>Group B</strong>: SBP values are widely scattered; some members may be hypotensive and others hypertensive (≥140 mmHg); the mean alone is misleading.</li>\n</ul>\n<p><strong>Coefficient of variation</strong></p>\n<p>CV(A) = (5 ÷ 120) × 100 = <strong>4.2%</strong>; CV(B) = (20 ÷ 120) × 100 = <strong>16.7%</strong></p>\n<p><strong>c) More consistent (2)</strong></p>\n<p><strong>Group A</strong> is more consistent (uniform): smaller SD and CV, less spread of values around the mean.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.164","n":164,"part":3,"topic":"Communication","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Why communication skills are essential to provide health education?</p>","a":"<p><strong>Why communication skills are essential for health education</strong></p>\n<p>Health education is basically a <strong>communication process</strong>: Communicator → Message → Channel → Audience → Feedback. Its success depends on the communicator's skill.</p>\n<ol>\n<li><strong>Information transfer</strong>: correct facts must reach people clearly (e.g., EPI schedule, danger signs).</li>\n<li><strong>Understanding (comprehension)</strong>: messages must be in the audience's language and level; jargon blocks learning.</li>\n<li><strong>Motivation and persuasion</strong>: skilful communication arouses interest and changes attitudes, not just knowledge.</li>\n<li><strong>Behaviour change</strong>: the goal of health education is adoption of healthy practices; this needs two-way, convincing communication.</li>\n<li><strong>Credibility and trust</strong>: good communicators win confidence of the community.</li>\n<li><strong>Feedback</strong>: lets the educator check understanding and correct misconceptions.</li>\n<li><strong>Overcoming barriers</strong>: physiological, psychological, environmental and cultural barriers can be reduced by skilled communicators.</li>\n<li><strong>Choice of methods and media</strong>: right method (individual, group, mass) and AV aids for the audience.</li>\n<li><strong>Counselling</strong>: sensitive issues (family planning, HIV, mental illness) need empathy and listening.</li>\n<li><strong>Community participation</strong>: dialogue builds partnership.</li>\n<li><strong>Compliance</strong>: patients follow treatment better when it is explained well (TB, diabetes).</li>\n<li><strong>Doctor–patient relationship</strong> improves; satisfaction rises.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.165","n":165,"part":3,"topic":"Communication","stars":3,"years":["26M","25M","24Nov","24M","19M","18Nov","16Ju","16Ja","12Ju","11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the components / elements of communication? Explain / draw the communication process (model) with diagram and its functions.</p>","a":"<p><strong>Components (elements) of communication</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Communicator (sender, source)</strong></td>\n<td>Person who originates the message</td>\n<td>Doctor, health worker</td>\n</tr>\n<tr>\n<td>2. <strong>Message</strong></td>\n<td>Information, ideas or feelings sent (content)</td>\n<td>&quot;Wash hands with soap before eating&quot;</td>\n</tr>\n<tr>\n<td>3. <strong>Encoding</strong></td>\n<td>Converting ideas into words, symbols, gestures</td>\n<td>Simple Bangla words, pictures</td>\n</tr>\n<tr>\n<td>4. <strong>Channel (medium)</strong></td>\n<td>Means by which message travels</td>\n<td>Face-to-face, radio, TV, poster, mobile</td>\n</tr>\n<tr>\n<td>5. <strong>Audience (receiver)</strong></td>\n<td>Person or group receiving the message</td>\n<td>Mothers, school children</td>\n</tr>\n<tr>\n<td>6. <strong>Decoding</strong></td>\n<td>Receiver interprets the message</td>\n<td>Understanding the advice</td>\n</tr>\n<tr>\n<td>7. <strong>Feedback</strong></td>\n<td>Receiver's response returned to sender</td>\n<td>Questions, demonstration, change in practice</td>\n</tr>\n<tr>\n<td>8. <strong>Noise / barriers</strong></td>\n<td>Anything that distorts the message</td>\n<td>Loud environment, language difference</td>\n</tr>\n<tr>\n<td>9. <strong>Effect</strong></td>\n<td>Change in knowledge, attitude, practice</td>\n<td>Mothers start using ORS</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Communication process (model)</strong></p>\n<p>Communicator → (encoding) → Message → Channel → (decoding) → Audience → Effect<br />\n↑______________________ Feedback ______________________|</p>\n<p>(Noise can interfere at every step.)</p>\n<p><strong>Functions of communication</strong></p>\n<ol>\n<li>Information</li>\n<li>Education</li>\n<li>Motivation</li>\n<li>Persuasion</li>\n<li>Counselling</li>\n<li>Raising morale</li>\n<li>Health development</li>\n<li>Organisation (coordinating people and activities)</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.166","n":166,"part":3,"topic":"Communication","stars":3,"years":["19M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the types of motives.</p>","a":"<p><strong>Motive</strong></p>\n<p>An internal state (need or desire) that energises and directs behaviour towards a goal.</p>\n<p><strong>Types of motives</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primary (biological / physiological)</strong></td>\n<td>Inborn, unlearned; necessary for survival</td>\n<td>Hunger, thirst, sleep, sex, avoidance of pain, need for air, temperature regulation</td>\n</tr>\n<tr>\n<td><strong>Secondary (social / psychological / learned)</strong></td>\n<td>Acquired through experience and society</td>\n<td>Affiliation (belonging), achievement, power, approval, recognition, money, security</td>\n</tr>\n<tr>\n<td><strong>Intrinsic</strong></td>\n<td>Arise from within; activity is rewarding in itself</td>\n<td>Curiosity, satisfaction of learning</td>\n</tr>\n<tr>\n<td><strong>Extrinsic</strong></td>\n<td>Arise from external rewards or pressures</td>\n<td>Prize, salary, fear of punishment</td>\n</tr>\n<tr>\n<td>General (unlearned, non-physiological)</td>\n<td>Curiosity, exploration, need for activity, contact comfort</td>\n<td>Child exploring surroundings</td>\n</tr>\n</tbody>\n</table>\n<p><strong>In health education</strong></p>\n<ul>\n<li>Motivation is the central task: &quot;people must feel the need&quot; (felt need).</li>\n<li>Use secondary motives (child's health, family approval, social status) to promote behaviour change, e.g., mothers immunise children for their child's safety.</li>\n<li><strong>Incentives</strong> (rewards) act as external motivators.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.167","n":167,"part":3,"topic":"Communication","stars":0,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss how effective communication can be achieved in medical education and research.</p>","a":"<p><strong>A. In medical education</strong></p>\n<ol>\n<li><strong>Clear learning objectives</strong> (knowledge, attitude, skill) shared with students.</li>\n<li><strong>Two-way, interactive teaching</strong>: questions, discussion, problem-based learning, case-based learning.</li>\n<li><strong>Small-group teaching</strong>: tutorials, seminars, bedside teaching.</li>\n<li><strong>Audio-visual aids</strong>: slides, videos, models, simulation and skills labs.</li>\n<li><strong>Simple, organised language</strong>; known → unknown; simple → complex.</li>\n<li><strong>Feedback</strong>: formative assessment, constructive comments, OSCE debriefing.</li>\n<li><strong>Role modelling</strong> of good communication with patients.</li>\n<li><strong>Communication skills training</strong>: history-taking, counselling, breaking bad news, role play with simulated patients.</li>\n<li><strong>Digital platforms</strong>: learning management systems, online resources.</li>\n<li>Good teacher–student relationship; mentorship.</li>\n</ol>\n<p><strong>B. In research</strong></p>\n<ol>\n<li>Clear <strong>research question</strong> and protocol shared with the team.</li>\n<li><strong>Informed consent</strong> explained in the participant's language.</li>\n<li>Standardised <strong>instructions and training</strong> of data collectors.</li>\n<li>Regular <strong>team meetings</strong>; clear roles.</li>\n<li>Communication with <strong>ethics committees</strong> and stakeholders.</li>\n<li><strong>Scientific writing</strong>: structured abstract, IMRaD format, tables and graphs.</li>\n<li><strong>Dissemination</strong>: seminars, conferences, journal publication, policy briefs, plain-language summaries for the community.</li>\n<li>Feedback of results to participants and communities.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.168","n":168,"part":3,"topic":"Communication","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the criteria of sender having good communication skill.</p>","a":"<p><strong>Criteria of a sender with good communication skill</strong></p>\n<ol>\n<li><strong>Knowledge</strong> of the subject; accurate information.</li>\n<li><strong>Clear objective</strong>: knows what change he wants.</li>\n<li><strong>Credibility</strong>: trustworthy, respected, sincere.</li>\n<li><strong>Knows the audience</strong>: their language, level, needs, culture, beliefs.</li>\n<li><strong>Simple, clear language</strong>; avoids jargon.</li>\n<li><strong>Good listener</strong>; encourages questions.</li>\n<li><strong>Empathy</strong> and respect for the audience.</li>\n<li><strong>Good non-verbal skills</strong>: eye contact, posture, facial expression, tone.</li>\n<li><strong>Uses feedback</strong> to check understanding and adjust the message.</li>\n<li><strong>Organised</strong> presentation: logical, brief, relevant.</li>\n<li><strong>Uses suitable methods and AV aids</strong>.</li>\n<li><strong>Confidence</strong>, clear voice and modulation.</li>\n<li><strong>Patience</strong> and good human relations.</li>\n<li><strong>Sets an example</strong> (practises what he preaches).</li>\n<li><strong>Persuasive and motivating</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.169","n":169,"part":3,"topic":"Communication","stars":3,"years":["14Ja","10Ja","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the importance of audio-visual aids with its classification / advantages of audio-visual aids in teaching.</p>","a":"<p><strong>Audio-visual (AV) aids</strong></p>\n<p>Devices that appeal to the senses of hearing and sight to make communication and learning more effective.</p>\n<p><strong>Classification (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Auditory aids</strong></td>\n<td>Radio, tape and digital audio, public address system (miking), telephone, podcasts</td>\n</tr>\n<tr>\n<td><strong>2. Visual aids</strong> (a) not requiring projection</td>\n<td>Chalkboard / whiteboard, leaflets, posters, charts, flannel graph, flash cards, exhibits, models, specimens, photographs</td>\n</tr>\n<tr>\n<td>(b) requiring projection</td>\n<td>Slides, film strips, overhead projector, multimedia projector</td>\n</tr>\n<tr>\n<td><strong>3. Combined audio-visual aids</strong></td>\n<td>Television, sound films, video, cinema, computer and mobile multimedia, internet</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Importance / advantages</strong></p>\n<ol>\n<li><strong>Attract attention</strong> and arouse interest.</li>\n<li><strong>Clarify</strong> difficult concepts (models, diagrams).</li>\n<li><strong>Better retention</strong>: more senses involved (&quot;seeing is believing&quot;).</li>\n<li><strong>Overcome language and literacy barriers</strong> (pictures).</li>\n<li><strong>Save time</strong> in explanation.</li>\n<li><strong>Reach large audiences</strong> (TV, radio).</li>\n<li>Make learning <strong>concrete and realistic</strong>.</li>\n<li><strong>Stimulate discussion</strong> and participation.</li>\n<li><strong>Reinforce</strong> messages.</li>\n<li>Increase <strong>credibility</strong> of messages.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.170","n":170,"part":3,"topic":"Communication","stars":3,"years":["20Nov"],"colleges":"MuMC (1st Final C4, 1st Supp C3)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the criteria of a good message?</p>","a":"<p><strong>Criteria of a good message (Park)</strong></p>\n<ol>\n<li>In line with the <strong>objectives</strong> of the programme.</li>\n<li><strong>Meaningful</strong>: relevant to the audience.</li>\n<li>Based on <strong>felt needs</strong> of the audience.</li>\n<li><strong>Clear and understandable</strong>: simple language, no jargon.</li>\n<li><strong>Specific</strong>: tells exactly what to do.</li>\n<li><strong>Accurate</strong> and scientifically correct.</li>\n<li><strong>Timely</strong>: given when needed (e.g., dengue messages before monsoon).</li>\n<li><strong>Adequate</strong>: neither too little nor too much.</li>\n<li><strong>Fits the culture</strong> and social context of the audience.</li>\n<li><strong>Interesting</strong>: attracts attention and arouses curiosity.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.171","n":171,"part":3,"topic":"Communication","stars":3,"years":["25Nov","20Nov","17M","15Ja","14Ja","11Ju"],"colleges":"SSMC (1st Supp A3); ShSMC (1st Term D5)","asked":"other barriers of communication (part of the language-barrier case)","note":"","kind":"","sub":"","q":"<p>List the barriers of communication with examples (including physical barriers).</p>","a":"<p><strong>Barriers of communication (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Physiological</strong></td>\n<td>Difficulty in hearing (deafness), poor vision, aphasia, speech defects, fatigue, pain</td>\n</tr>\n<tr>\n<td><strong>2. Psychological</strong></td>\n<td>Emotional disturbance, anxiety, fear, neurosis, low intelligence, poor attention, prejudice, comprehension difficulty</td>\n</tr>\n<tr>\n<td><strong>3. Environmental (physical)</strong></td>\n<td>Noise, poor visibility, congestion, poor lighting, interruptions, distance, faulty equipment</td>\n</tr>\n<tr>\n<td><strong>4. Cultural</strong></td>\n<td>Illiteracy, differences in levels of knowledge and understanding, customs, beliefs, religion, attitudes, economic and social class differences, language, cultural gap between communicator and audience</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other barriers</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Semantic / language</td>\n<td>Medical jargon, different dialect (Chattogram, Sylhet), indigenous languages</td>\n</tr>\n<tr>\n<td>Organisational</td>\n<td>Rigid hierarchy, overcrowded OPD, short consultation time</td>\n</tr>\n<tr>\n<td>Interpersonal</td>\n<td>Lack of trust, poor rapport, arrogance, gender difference</td>\n</tr>\n<tr>\n<td>Technological</td>\n<td>Poor network, no electricity</td>\n</tr>\n<tr>\n<td>Message-related</td>\n<td>Too long, too technical, contradictory messages</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Example</strong></p>\n<p>A doctor uses English medical terms to explain insulin use to an illiterate rural woman in a noisy OPD → language, cultural, environmental and psychological (anxiety) barriers together.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.172","n":172,"part":3,"topic":"Communication","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Briefly discuss the functions of health communication.</p>","a":"<p><strong>Functions of health communication (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Function</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Information</strong></td>\n<td>Basic function: spreading knowledge about health</td>\n<td>Dengue symptoms and prevention</td>\n</tr>\n<tr>\n<td>2. <strong>Education</strong></td>\n<td>Systematic learning to change knowledge, attitude and practice</td>\n<td>School health education</td>\n</tr>\n<tr>\n<td>3. <strong>Motivation</strong></td>\n<td>Arousing interest and desire to act</td>\n<td>Encouraging ANC visits</td>\n</tr>\n<tr>\n<td>4. <strong>Persuasion</strong></td>\n<td>Convincing people to adopt a practice</td>\n<td>Quitting smoking</td>\n</tr>\n<tr>\n<td>5. <strong>Counselling</strong></td>\n<td>Helping individuals understand problems and decide</td>\n<td>Family planning, HIV counselling</td>\n</tr>\n<tr>\n<td>6. <strong>Raising morale</strong></td>\n<td>Building confidence and team spirit</td>\n<td>Encouraging health workers during epidemics</td>\n</tr>\n<tr>\n<td>7. <strong>Health development</strong></td>\n<td>Promoting community action for better health</td>\n<td>Community-led total sanitation</td>\n</tr>\n<tr>\n<td>8. <strong>Organisation</strong></td>\n<td>Coordinating people and activities</td>\n<td>Planning vaccination campaigns</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other roles</strong></p>\n<ul>\n<li>Advocacy for healthy policies (tobacco control).</li>\n<li>Risk and crisis communication in outbreaks (COVID-19).</li>\n<li>Increasing demand for and use of services.</li>\n<li>Correcting misinformation and rumours.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.173","n":173,"part":3,"topic":"Communication","stars":2,"years":["17M"],"colleges":"MuMC (1st Final D4, 1st Supp D3)","asked":"disadvantages of one-way communication","note":"","kind":"","sub":"","q":"<p>Lecture is a one way communication – explain.</p>","a":"<p><strong>Lecture as one-way communication</strong></p>\n<p>In a lecture, the <strong>flow of communication is from the communicator to the audience only</strong> (didactic method); the audience listens passively, with little or no chance to ask questions or give feedback.</p>\n<p>Lecturer → Message → Passive audience (no feedback)</p>\n<p><strong>Features</strong></p>\n<ol>\n<li>Authoritative; knowledge &quot;imposed&quot;.</li>\n<li>Audience passive.</li>\n<li>No feedback; speaker cannot check understanding.</li>\n<li>Fast; covers much content to many people.</li>\n</ol>\n<p><strong>Disadvantages of one-way communication</strong></p>\n<ol>\n<li>Learning is <strong>passive</strong>; little participation.</li>\n<li><strong>No feedback</strong>; misunderstandings remain.</li>\n<li>Little effect on <strong>attitude and behaviour</strong>.</li>\n<li>Poor <strong>retention</strong>; attention declines after 15–20 minutes.</li>\n<li>Ignores individual differences.</li>\n<li>Can be boring; monotonous.</li>\n<li>Audience needs and doubts not addressed.</li>\n</ol>\n<p><strong>Advantages</strong></p>\n<p>Saves time; reaches large groups; useful for introducing new information.</p>\n<p><strong>Making a lecture two-way</strong></p>\n<p>Ask and invite questions; brief discussion; AV aids; demonstrations; case examples; quizzes; follow-up group work.</p>\n<p><strong>Two-way (Socratic) communication</strong>: communicator and audience both take part → active learning, feedback, more likely to change behaviour.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.174","n":174,"part":3,"topic":"Communication","stars":2,"years":[],"colleges":"DMC (1st Assess C4); SSMC (1st Supp A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Classify communication / mention the types of communication with examples.</p>","a":"<p><strong>Types of communication</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Type</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Direction</strong></td>\n<td><strong>One-way</strong> (didactic)</td>\n<td>Lecture, radio talk</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Two-way</strong> (Socratic)</td>\n<td>Discussion, counselling</td>\n</tr>\n<tr>\n<td><strong>Mode</strong></td>\n<td><strong>Verbal</strong>: oral</td>\n<td>Talk, telephone</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Verbal</strong>: written</td>\n<td>Letters, leaflets, prescriptions</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Non-verbal</strong></td>\n<td>Gestures, facial expression, posture, eye contact, touch</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Visual</strong></td>\n<td>Charts, posters, pictures, maps</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Telecommunication and internet</strong></td>\n<td>TV, mobile phone, SMS, social media, email</td>\n</tr>\n<tr>\n<td><strong>Formality</strong></td>\n<td><strong>Formal</strong></td>\n<td>Official orders, reports, meetings</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Informal</strong> (&quot;grapevine&quot;)</td>\n<td>Chat among colleagues</td>\n</tr>\n<tr>\n<td><strong>Number involved</strong></td>\n<td>Intrapersonal</td>\n<td>Thinking, self-talk</td>\n</tr>\n<tr>\n<td></td>\n<td>Interpersonal</td>\n<td>Doctor–patient talk</td>\n</tr>\n<tr>\n<td></td>\n<td>Group</td>\n<td>Group discussion with mothers</td>\n</tr>\n<tr>\n<td></td>\n<td>Mass</td>\n<td>TV campaign</td>\n</tr>\n<tr>\n<td><strong>Organisational flow</strong></td>\n<td>Downward / upward / horizontal</td>\n<td>Director to staff / staff report / peer coordination</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.175","n":175,"part":3,"topic":"Communication","stars":0,"years":[],"colleges":"MuMC (1st Final C4, 1st Supp C3)","asked":"","note":"","kind":"","sub":"","q":"<p>How can traditional or folk media influence communication – explain from the Bangladesh perspective.</p>","a":"<p><strong>Traditional / folk media</strong></p>\n<p>Indigenous forms of entertainment and communication rooted in local culture, used to carry health messages.</p>\n<p><strong>Bangladesh examples</strong></p>\n<p>Jatra (folk theatre), puppet show (<em>putul nach</em>), <em>kobigan</em> (poetic duel), <em>jari-sari</em> and <em>baul</em> songs, <em>gombhira</em> (Rajshahi), <em>pot gaan</em> (scroll painting with songs), <em>pala gaan</em>, street drama (<em>pathanatok</em>), storytelling, <em>haat-bazaar</em> announcements, folk proverbs.</p>\n<p><strong>How they influence communication</strong></p>\n<ol>\n<li><strong>Culturally familiar</strong> → high acceptance and credibility.</li>\n<li><strong>Local language and dialect</strong> → easy to understand.</li>\n<li><strong>Reach illiterate and rural people</strong> who lack access to print media.</li>\n<li><strong>Entertaining</strong> → attracts large crowds and holds attention.</li>\n<li><strong>Participatory</strong>: audience reacts, sings along; allows discussion and feedback.</li>\n<li><strong>Emotional appeal</strong> → can change attitudes, not just knowledge.</li>\n<li><strong>Low cost</strong>; local artists and materials.</li>\n<li><strong>Flexible</strong>: messages can be adapted to local problems.</li>\n<li><strong>Respects tradition</strong> → less resistance to sensitive topics (family planning, child marriage, HIV).</li>\n</ol>\n<p><strong>Health uses in Bangladesh</strong></p>\n<p>Family planning, EPI, ORS, breastfeeding, sanitation, arsenic awareness, dengue, HIV prevention, anti-dowry and anti-child-marriage campaigns.</p>\n<p><strong>Limitations</strong></p>\n<p>Limited reach compared to mass media; quality depends on performers; risk of message distortion; needs pretesting and monitoring.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.176","n":176,"part":3,"topic":"Communication","stars":0,"years":[],"colleges":"MuMC (1st Final D4, 1st Supp D3)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the potential key person (PKP) in a community for effective communication.</p>","a":"<p><strong>Potential key persons (PKP)</strong></p>\n<p>Respected, influential persons in a community through whom health messages can be passed effectively (opinion leaders, gatekeepers).</p>\n<p><strong>PKPs in a Bangladeshi community</strong></p>\n<ol>\n<li><strong>Religious leaders</strong>: imam, khatib, priest, monk.</li>\n<li><strong>Teachers</strong> of schools and madrasas.</li>\n<li><strong>Local government representatives</strong>: union parishad chairman and members, ward councillor.</li>\n<li><strong>Village elders</strong> (<em>matbor</em>, <em>murubbi</em>).</li>\n<li><strong>Community health workers</strong>: CHCP, health assistant, FWA, NGO volunteers.</li>\n<li><strong>Traditional birth attendants</strong> (<em>dai</em>) and village doctors.</li>\n<li><strong>Women's group and mothers' club leaders</strong>.</li>\n<li><strong>Youth club, sports and cultural leaders</strong>.</li>\n<li><strong>Community group (CG) members</strong> of community clinics.</li>\n<li><strong>Local businessmen</strong>, pharmacy owners.</li>\n<li><strong>Students</strong> (child-to-child approach).</li>\n<li><strong>Local journalists</strong> and social media influencers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.177","n":177,"part":3,"topic":"Communication","stars":0,"years":[],"colleges":"ShSMC (1st Term D5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A doctor explained diabetic diet control to a patient, but the patient failed to understand due to language barrier and poor attention. [7]</p>\n<ul>\n<li>a) Mention the characteristics of effective communication. (2)</li>\n<li>b) Highlight about other barriers of communication not mentioned in the question. (2)</li>\n<li>c) How we can improve doctor patient relationship? (3)</li>\n</ul>","a":"<p><strong>a) Characteristics of effective communication (2)</strong></p>\n<ol>\n<li><strong>Clear</strong>: simple language the patient understands (Bangla, local dialect).</li>\n<li><strong>Concise and specific</strong>: only key points (e.g., &quot;avoid sweets, eat more vegetables&quot;).</li>\n<li><strong>Correct and complete</strong>: accurate, all needed information.</li>\n<li><strong>Two-way</strong>: listening, questions, <strong>feedback</strong> (teach-back).</li>\n<li><strong>Relevant</strong> to patient's needs and culture (local foods).</li>\n<li><strong>Courteous and empathetic</strong>; respectful.</li>\n<li><strong>Supported by aids</strong>: food pictures, diet chart.</li>\n<li><strong>Right time and place</strong>: patient attentive, quiet setting.</li>\n</ol>\n<p><strong>b) Other barriers of communication (2)</strong> (besides language and poor attention)</p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Physiological</td>\n<td>Hearing or vision problems, fatigue, pain, illness</td>\n</tr>\n<tr>\n<td>Psychological</td>\n<td>Anxiety, fear, denial, depression, low intelligence, prejudice</td>\n</tr>\n<tr>\n<td>Environmental</td>\n<td>Noise, overcrowded OPD, lack of privacy, interruptions, little time</td>\n</tr>\n<tr>\n<td>Cultural</td>\n<td>Illiteracy; food beliefs and taboos; religious practices (fasting); social class gap</td>\n</tr>\n<tr>\n<td>Semantic</td>\n<td>Medical jargon (&quot;glycaemic index&quot;, &quot;carbohydrate&quot;)</td>\n</tr>\n<tr>\n<td>Interpersonal</td>\n<td>Lack of trust, doctor's hurried or rude manner</td>\n</tr>\n</tbody>\n</table>\n<p><strong>c) Improving doctor–patient relationship (3)</strong></p>\n<ol>\n<li>Use the <strong>patient's language</strong>; interpreter if needed; avoid jargon.</li>\n<li><strong>Listen actively</strong>; give adequate time; show empathy and respect.</li>\n<li><strong>Explain</strong> diagnosis and plan; use <strong>teach-back</strong> to confirm understanding.</li>\n<li><strong>Involve the patient and family</strong> in decisions (shared decision-making).</li>\n<li>Use <strong>AV aids</strong>: printed diet chart with pictures.</li>\n<li>Maintain <strong>privacy and confidentiality</strong>.</li>\n<li>Be <strong>honest</strong> about cost, prognosis and options; respect beliefs.</li>\n<li><strong>Follow-up</strong> and continuity of care; accessible for questions.</li>\n<li>System support: reduce OPD crowding, appointment systems, communication skills training, complaint handling.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education; Medicine and Social Sciences).</p>"},{"id":"DU.178","n":178,"part":3,"topic":"Health Education","stars":3,"years":["21M","09Ja"],"colleges":"MMC (1st Supp B5)","asked":"","note":"","kind":"","sub":"","q":"<p>Define health education.</p>","a":"<p><strong>Definitions</strong></p>\n<ol>\n<li><strong>Park (National Conference on Preventive Medicine, USA)</strong>: a process that <strong>informs, motivates and helps</strong> people to adopt and maintain healthy practices and lifestyles, advocates environmental changes needed for this goal, and conducts professional training and research to the same end.</li>\n<li><strong>Alma-Ata (1978)</strong>: &quot;education concerning prevailing health problems and the methods of preventing and controlling them&quot; (first element of PHC).</li>\n<li><strong>WHO (Health Promotion Glossary, 1998)</strong>: consciously constructed opportunities for learning, involving communication, designed to improve <strong>health literacy</strong> (knowledge and life skills) for individual and community health.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.179","n":179,"part":3,"topic":"Health Education","stars":1,"years":["08Ju","07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Highlight the objectives of health education with examples.</p>","a":"<p><strong>Objectives of health education (WHO; Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Objective</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. To encourage people to <strong>adopt and sustain health-promoting lifestyles and practices</strong></td>\n<td>Hand-washing, balanced diet, exercise, no tobacco</td>\n</tr>\n<tr>\n<td>2. To promote the <strong>proper use of health services</strong> available to them</td>\n<td>ANC, facility delivery, immunisation, DOTS completion</td>\n</tr>\n<tr>\n<td>3. To arouse interest, provide new knowledge, improve skills and change attitudes so people make <strong>rational decisions</strong> to solve their own problems</td>\n<td>Mothers learning to prepare ORS and recognise pneumonia danger signs</td>\n</tr>\n<tr>\n<td>4. To stimulate <strong>individual and community self-reliance and participation</strong> in health development, from identifying problems to solving them</td>\n<td>Community dengue source-reduction drives; community clinic management</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other aims</strong></p>\n<ul>\n<li>Promote <strong>positive health</strong> and prevent disease.</li>\n<li>Develop <strong>health literacy</strong>.</li>\n<li>Support <strong>healthy public policy</strong> and environmental change.</li>\n<li>Reduce <strong>stigma</strong> (TB, HIV, mental illness).</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.180","n":180,"part":3,"topic":"Health Education","stars":2,"years":["06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the approaches of health education.</p>","a":"<p><strong>Approaches to health education (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Approach</th>\n<th>Meaning</th>\n<th>Example</th>\n<th>Limitation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Regulatory (legal) approach</strong></td>\n<td>Laws and regulations to protect health</td>\n<td>Tobacco control law, food adulteration laws, helmet law</td>\n<td>Behaviour cannot be changed by law alone; enforcement difficult</td>\n</tr>\n<tr>\n<td><strong>2. Service approach</strong></td>\n<td>Providing health services to people (taking services to their doorstep)</td>\n<td>Free latrines, tube wells</td>\n<td>Failed when people's felt needs and beliefs were ignored; services not used</td>\n</tr>\n<tr>\n<td><strong>3. Health education approach</strong></td>\n<td>Educating people to adopt healthy behaviour voluntarily</td>\n<td>Mass campaigns, counselling</td>\n<td>Slow; results take time</td>\n</tr>\n<tr>\n<td><strong>4. Primary health care approach</strong></td>\n<td>Health education as part of PHC with community participation, starting from people's own needs (&quot;bottom-up&quot;)</td>\n<td>Community clinics, CHWs, community-led total sanitation</td>\n<td>Needs organisation and commitment</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Models of health education</strong></p>\n<ol>\n<li><strong>Medical model</strong>: emphasis on disease prevention by medical interventions; health education as an appendage.</li>\n<li><strong>Motivation model</strong>: individual motivation through knowledge leads to behaviour change (KAP).</li>\n<li><strong>Social intervention model</strong>: changing the social and physical environment (policy, community action) to support healthy behaviour.</li>\n</ol>\n<p><strong>Best approach</strong></p>\n<p>A <strong>combination</strong>, with the PHC approach (community participation) as the core.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.181","n":181,"part":3,"topic":"Health Education","stars":3,"years":["23Nov","18M","16Ju","12Ju","11Ju","05S","05Ja"],"colleges":"DMC (1st Assess C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Briefly discuss the various stages for adoption of new ideas and practices / stages of health education / stages of adaptation of a new concept.</p>","a":"<p><strong>Stages of adoption of new ideas and practices (Park)</strong></p>\n<p>Awareness → Interest → Evaluation → Trial → Adoption</p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>What happens</th>\n<th>Example (exclusive breastfeeding)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Awareness</strong></td>\n<td>Person first hears of the new idea; knows little</td>\n<td>Mother hears about exclusive breastfeeding on TV</td>\n</tr>\n<tr>\n<td>2. <strong>Interest</strong></td>\n<td>Seeks more information, details</td>\n<td>Asks the CHCP what it means</td>\n</tr>\n<tr>\n<td>3. <strong>Evaluation</strong></td>\n<td>Weighs advantages and disadvantages for herself; mental trial</td>\n<td>Thinks about whether her baby will get enough</td>\n</tr>\n<tr>\n<td>4. <strong>Trial</strong></td>\n<td>Tries the practice on a small scale</td>\n<td>Breastfeeds only for a few days</td>\n</tr>\n<tr>\n<td>5. <strong>Adoption</strong></td>\n<td>Accepts and practises regularly after satisfaction</td>\n<td>Continues exclusive breastfeeding to 6 months</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Notes</strong></p>\n<ol>\n<li>People move through stages at different speeds; some reject at any stage.</li>\n<li>Adopter categories: innovators → early adopters → early majority → late majority → laggards.</li>\n<li>Health educator must support each stage: information (awareness), counselling (interest, evaluation), demonstration and support (trial), reinforcement (adoption).</li>\n<li><strong>Rejection</strong> can occur at any stage; follow-up prevents relapse.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.182","n":182,"part":3,"topic":"Health Education","stars":3,"years":["24Nov","24M","16Ju","16M"],"colleges":"MMC (1st Supp B5)","asked":"principles to follow when conducting a health education session","note":"","kind":"","sub":"","q":"<p>What are the principles of health education? (at least 8 / important 10).</p>","a":"<p><strong>Principles of health education (Park)</strong></p>\n<ol>\n<li><strong>Interest</strong>: people learn what interests them; start from felt needs.</li>\n<li><strong>Participation</strong>: active involvement (learning by doing, discussion) → acceptance.</li>\n<li><strong>Motivation</strong>: awaken desire to learn and act; use incentives.</li>\n<li><strong>Comprehension</strong>: communicate at the level and in the language of the audience.</li>\n<li><strong>Reinforcement</strong>: repeat messages at intervals.</li>\n<li><strong>Learning by doing</strong>: &quot;I hear and forget; I see and remember; I do and I know&quot;.</li>\n<li><strong>Known to unknown</strong>: begin with what people know.</li>\n<li><strong>Setting an example</strong>: educator must practise what he teaches.</li>\n<li><strong>Good human relations</strong>: friendly, sympathetic approach.</li>\n<li><strong>Feedback</strong>: check understanding; adjust.</li>\n<li><strong>Leaders</strong>: use local opinion leaders to spread messages.</li>\n<li><strong>Credibility</strong>: message consistent with scientific knowledge, local culture and goals; trusted source.</li>\n</ol>\n<p><strong>&quot;Soil, seed and sower&quot;</strong></p>\n<p>People = soil; health facts = seed; communicator = sower. All three must be favourable for results.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.183","n":183,"part":3,"topic":"Health Education","stars":3,"years":["21M","16Nov","16Ju","15Ja","08Ja"],"colleges":"ShSMC (1st Term D4)","asked":"why media & methods are important in health education & communication","note":"","kind":"","sub":"","q":"<p>Classify / enumerate the media and methods used in health education. How can health be promoted?</p>","a":"<p><strong>Methods of health education (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Approach</th>\n<th>Methods / media</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Individual</strong></td>\n<td>Personal contact, home visits, personal letters, counselling, phone</td>\n<td>FWA counselling a couple on contraception</td>\n</tr>\n<tr>\n<td><strong>2. Group</strong></td>\n<td>Lecture (chalk talk), demonstration (method and result), group discussion, panel discussion, symposium, workshop, seminar, conference, role play</td>\n<td>ORS demonstration to mothers</td>\n</tr>\n<tr>\n<td><strong>3. Mass</strong></td>\n<td>Television, radio, newspapers, printed material (leaflets, posters), direct mailing, health museums and exhibitions, folk media, internet and social media, SMS</td>\n<td>National campaigns (EPI, dengue)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Media (AV aids)</strong></p>\n<p>Auditory (radio, audio); visual (posters, charts, flannel graph, models, slides); combined (TV, film, video, mobile multimedia).</p>\n<p><strong>Why methods and media matter</strong></p>\n<p>Choice depends on objective, audience, message and resources; using several together gives best effect.</p>\n<p><strong>How health can be promoted</strong></p>\n<ol>\n<li>Health education (all three approaches).</li>\n<li>Environmental modification (water, sanitation, housing).</li>\n<li>Nutritional interventions.</li>\n<li>Lifestyle and behavioural change.</li>\n<li>Healthy public policy and laws (Ottawa Charter actions).</li>\n<li>Community action and participation.</li>\n<li>Reorienting health services towards prevention.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education; Concept of Health and Disease).</p>"},{"id":"DU.184","n":184,"part":3,"topic":"Health Education","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the methods and media of developing attitude and skill of the medical graduates.</p>","a":"<p><strong>Developing attitude (affective domain)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Media / tools</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Role modelling by teachers</td>\n<td>Observation in wards and community</td>\n</tr>\n<tr>\n<td>Role play, simulated patients</td>\n<td>Scenarios on breaking bad news, consent</td>\n</tr>\n<tr>\n<td>Group discussion, reflective writing</td>\n<td>Case discussions on ethics, professionalism</td>\n</tr>\n<tr>\n<td>Community attachment, field visits</td>\n<td>Residential field sites, village surveys, home visits</td>\n</tr>\n<tr>\n<td>Video demonstrations and films</td>\n<td>Patient stories, documentaries</td>\n</tr>\n<tr>\n<td>Mentoring and counselling</td>\n<td>Faculty mentors</td>\n</tr>\n<tr>\n<td>Feedback on behaviour</td>\n<td>Multisource (360°) feedback</td>\n</tr>\n<tr>\n<td>Ethics and professionalism sessions</td>\n<td>Case-based ethics seminars</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Developing skill (psychomotor domain)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Media / tools</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Demonstration → supervised practice → independent practice (&quot;see one, do one, teach one&quot;, with safety)</td>\n<td>Bedside teaching</td>\n</tr>\n<tr>\n<td>Skills laboratory</td>\n<td>Mannequins, task trainers (IV cannulation, suturing, CPR)</td>\n</tr>\n<tr>\n<td>Simulation</td>\n<td>High-fidelity simulators, OSCE stations</td>\n</tr>\n<tr>\n<td>Clinical rotations and internship</td>\n<td>Logbooks, direct observation (DOPS, mini-CEX)</td>\n</tr>\n<tr>\n<td>Communication skills training</td>\n<td>Simulated patients, video recording with feedback</td>\n</tr>\n<tr>\n<td>Field practice</td>\n<td>Immunisation, health education sessions, surveys</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Principles</strong></p>\n<p>Clear objectives; learning by doing; repeated practice; immediate feedback; assessment by OSCE and workplace-based tools.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.185","n":185,"part":3,"topic":"Health Education","stars":3,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can health education promote public health?</p>","a":"<p><strong>How health education promotes public health</strong></p>\n<ol>\n<li><strong>Prevents disease</strong>: hand-washing, safe water, sanitation, safe sex, vector control.</li>\n<li><strong>Promotes healthy lifestyles</strong>: diet, exercise, no tobacco or alcohol → fewer NCDs.</li>\n<li><strong>Increases use of services</strong>: immunisation, ANC, facility delivery, family planning, screening.</li>\n<li><strong>Early care-seeking</strong>: recognising danger signs (pneumonia, pregnancy complications) reduces deaths.</li>\n<li><strong>Improves compliance</strong>: TB, hypertension, diabetes treatment.</li>\n<li><strong>Self-care</strong>: ORS at home, first aid, self-monitoring.</li>\n<li><strong>Community participation</strong>: people take part in identifying and solving health problems.</li>\n<li><strong>Supports national programmes</strong>: EPI, family planning, nutrition, dengue, TB.</li>\n<li><strong>Reduces stigma and misconceptions</strong> (TB, HIV, mental illness, vaccine rumours).</li>\n<li><strong>Advocacy</strong>: builds public support for healthy policies (tobacco control, food safety).</li>\n<li><strong>Health literacy</strong> and empowerment → equity.</li>\n<li><strong>Cost-effective</strong>: low-cost intervention with wide impact.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.186","n":186,"part":3,"topic":"Health Education","stars":3,"years":[],"colleges":"DMC (1st Assess D1); SSMC (1st Supp C3); ShSMC (1st Term D2)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the contents (components) of health education?</p>","a":"<p><strong>Contents (components) of health education (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Content</th>\n<th>Topics</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Human biology</strong></td>\n<td>Structure and function of the body; how disease affects it; effects of alcohol, tobacco, drugs</td>\n</tr>\n<tr>\n<td>2. <strong>Nutrition</strong></td>\n<td>Balanced diet, local foods, breastfeeding, complementary feeding, food hygiene, avoiding junk food</td>\n</tr>\n<tr>\n<td>3. <strong>Hygiene</strong></td>\n<td>Personal hygiene (bathing, hand-washing, oral care) and environmental hygiene (safe water, latrines, waste disposal)</td>\n</tr>\n<tr>\n<td>4. <strong>Family health care</strong></td>\n<td>Family planning, ANC, safe delivery, child care, immunisation, care of elderly</td>\n</tr>\n<tr>\n<td>5. <strong>Control of communicable diseases</strong></td>\n<td>Mode of spread and prevention of diarrhoea, TB, dengue, malaria, HIV, COVID-19</td>\n</tr>\n<tr>\n<td>6. <strong>Mental health</strong></td>\n<td>Stress management, recognising mental illness, reducing stigma</td>\n</tr>\n<tr>\n<td>7. <strong>Prevention of accidents</strong></td>\n<td>Road safety, drowning prevention, burns, home and occupational safety</td>\n</tr>\n<tr>\n<td>8. <strong>Use of health services</strong></td>\n<td>Where and when to seek care, referral, rights</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Additional modern contents</strong></p>\n<p>NCD risk factors; sexual and reproductive health for adolescents; substance abuse; environmental health (arsenic, air pollution); disaster preparedness; oral health; consumer health (rational drug use).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.187","n":187,"part":3,"topic":"Health Education","stars":0,"years":[],"colleges":"ShSMC (1st Term D3)","asked":"","note":"","kind":"","sub":"","q":"<p>What do you understand by BCC (behaviour change communication)? Explain the relationship between BCC and health education with example.</p>","a":"<p><strong>Behaviour change communication (BCC)</strong></p>\n<p>An interactive process with individuals and communities to develop <strong>tailored messages and approaches</strong>, using multiple channels, to promote <strong>positive behaviours</strong> and to provide a <strong>supportive environment</strong> that enables people to adopt and maintain them.</p>\n<p><strong>Features</strong></p>\n<ol>\n<li>Focus on <strong>specific behaviours</strong>, not just knowledge.</li>\n<li>Based on <strong>research</strong> of the audience (barriers, motivators).</li>\n<li>Uses <strong>multiple channels</strong>: interpersonal, community, mass media, digital.</li>\n<li><strong>Two-way</strong>, participatory.</li>\n<li>Addresses <strong>social norms</strong> and enabling environment (services, policy).</li>\n<li>Monitored and evaluated by behaviour change indicators.</li>\n</ol>\n<p><strong>Relationship between BCC and health education</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Health education</th>\n<th>BCC</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Scope</td>\n<td>Broad learning process (KAP)</td>\n<td>Strategic, behaviour-focused communication</td>\n</tr>\n<tr>\n<td>Main aim</td>\n<td>Knowledge, attitude, practice</td>\n<td>Measurable behaviour change and maintenance</td>\n</tr>\n<tr>\n<td>Planning</td>\n<td>Often general messages</td>\n<td>Audience research, segmentation, pretesting</td>\n</tr>\n<tr>\n<td>Environment</td>\n<td>Mainly individual learning</td>\n<td>Also social and service environment</td>\n</tr>\n<tr>\n<td>Relation</td>\n<td><strong>Foundation</strong></td>\n<td><strong>Evolution / application</strong> of health education</td>\n</tr>\n</tbody>\n</table>\n<p>Both share principles (participation, motivation, feedback); BCC builds on health education and IEC (information, education, communication) and adds strategy and evaluation; it moves people from awareness to sustained practice.</p>\n<p><strong>Example</strong></p>\n<p>Hand-washing with soap: health education explains germs; BCC identifies barriers (no soap near latrine), promotes a hand-washing station, uses TV spots + school activities + mothers' groups, and measures observed hand-washing.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.188","n":188,"part":3,"topic":"Health Education","stars":0,"years":[],"colleges":"ShSMC (1st Term D4)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the limitations of mass media?</p>","a":"<p><strong>Limitations of mass media</strong></p>\n<ol>\n<li><strong>One-way communication</strong>: no immediate feedback; misunderstandings not corrected.</li>\n<li><strong>Cannot individualise</strong>: same message for all; personal doubts not answered.</li>\n<li><strong>Mainly creates awareness</strong>; less effective in changing attitudes and behaviour alone.</li>\n<li><strong>Reach is unequal</strong>: poor, rural, illiterate people may lack TV, internet or newspapers; print excludes the illiterate.</li>\n<li><strong>Message may be misinterpreted</strong> or ignored; selective attention.</li>\n<li><strong>Costly</strong> to produce and air (TV, newspapers).</li>\n<li><strong>Short exposure</strong>; messages quickly forgotten without repetition.</li>\n<li><strong>Competition</strong> with commercial and entertainment content; message overload.</li>\n<li><strong>Misinformation</strong> and rumours spread quickly on social media.</li>\n<li><strong>Difficult to evaluate</strong> impact.</li>\n<li>Cultural and language differences limit relevance in diverse groups.</li>\n</ol>\n<p><strong>Overcoming limitations</strong></p>\n<p>Combine mass media with interpersonal and group methods; pretest messages; repeat; use local languages and folk media; use feedback channels (hotlines).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.189","n":189,"part":3,"topic":"Health Education","stars":0,"years":[],"colleges":"MuMC (1st Final D4, 1st Supp D3)","asked":"","note":"","kind":"","sub":"","q":"<p>Justify “known to unknown” in health education.</p>","a":"<p><strong>&quot;Known to unknown&quot;: principle of health education</strong></p>\n<p>Begin with what the audience <strong>already knows</strong> (their experience, beliefs, local terms) and move step by step to <strong>new knowledge</strong>.</p>\n<p>Existing knowledge → link → new idea → understanding → acceptance</p>\n<p><strong>Justification</strong></p>\n<ol>\n<li><strong>Learning theory</strong>: new learning is anchored to existing knowledge (meaningful learning); easier to understand.</li>\n<li><strong>Comprehension</strong>: familiar examples and words make abstract ideas concrete.</li>\n<li><strong>Interest and confidence</strong>: people feel respected when their knowledge is acknowledged.</li>\n<li><strong>Less resistance</strong>: building on beliefs (where harmless) avoids rejection.</li>\n<li><strong>Better retention</strong>: new facts linked to old memories are remembered longer.</li>\n<li><strong>Participation</strong>: starting from people's experience encourages discussion.</li>\n<li><strong>Corrects misconceptions</strong> gently by contrasting known ideas with correct ones.</li>\n</ol>\n<p><strong>Examples</strong></p>\n<ul>\n<li>Explaining <strong>ORS</strong>: start from the known practice of giving saline water / <em>lobon-gur</em> → then exact proportions and why it prevents dehydration.</li>\n<li>Explaining <strong>germs</strong>: start from the known fact that rotten food smells and causes illness → invisible germs on dirty hands.</li>\n<li>Explaining <strong>vaccination</strong>: start from known experience that a person who once had measles does not get it again → vaccine gives the same protection safely.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Communication for Health Education).</p>"},{"id":"DU.190","n":190,"part":4,"topic":"Environmental Health (General)","stars":3,"years":["22Nov","19Nov","17M"],"colleges":"MMC (2nd Term A1)","asked":"outline the components of environment with examples","note":"","kind":"","sub":"","q":"<p>Classify environment with examples of each. Mention the role of biological environment in disease causation.</p>","a":"<p><strong>Classification of environment (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Includes</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Physical</strong></td>\n<td>Non-living things and physical forces</td>\n<td>Air, water, soil, housing, climate, geography, heat, light, noise, radiation, debris</td>\n</tr>\n<tr>\n<td><strong>2. Biological</strong></td>\n<td>Living things around man, including other humans</td>\n<td>Plants, animals, insects (vectors), rodents, microbes, other people</td>\n</tr>\n<tr>\n<td><strong>3. Psychosocial</strong></td>\n<td>Social and cultural surroundings</td>\n<td>Cultural values, customs, beliefs, habits, attitudes, religion, morals, education, lifestyle, community life, health services, social and political organisation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other classification</strong></p>\n<ul>\n<li><strong>Internal environment</strong>: inside the body (tissues, organs, homeostasis).</li>\n<li><strong>External (macro) environment</strong>: physical + biological + psychosocial.</li>\n<li><strong>Micro (domestic) environment</strong>: home, family, personal way of living.</li>\n</ul>\n<p><strong>Role of biological environment in disease causation</strong></p>\n<ol>\n<li><strong>Source of disease agents</strong>: bacteria, viruses, parasites, fungi in water, food, soil, air.</li>\n<li><strong>Animal reservoirs (zoonoses)</strong>: dog (rabies), cattle (anthrax, TB), rats (plague, leptospirosis), birds (avian influenza), bats (Nipah).</li>\n<li><strong>Vectors</strong>: Anopheles (malaria), Aedes (dengue, chikungunya), Culex (filariasis, Japanese encephalitis), sandfly (kala-azar), rat flea (plague), housefly (mechanical carrier of diarrhoeal diseases).</li>\n<li><strong>Intermediate hosts</strong>: snail (schistosomiasis), cyclops (guinea worm), pig (taeniasis), fish (fish tapeworm).</li>\n<li><strong>Other humans</strong>: cases and carriers spread TB, typhoid, HIV, COVID-19.</li>\n<li><strong>Plants</strong>: pollen allergens (asthma), poisonous plants, mycotoxins (aflatoxin → liver cancer).</li>\n<li><strong>Food chain</strong>: contaminated food; biological magnification.</li>\n<li>Ecological imbalance (deforestation, urbanisation) brings humans close to vectors and wildlife → emerging diseases.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.191","n":191,"part":4,"topic":"Environmental Health (General)","stars":2,"years":["24M","18M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify macro-environment with examples.</p>","a":"<p><strong>Macro-environment (external environment)</strong></p>\n<p>Everything external to the individual human host; classified into three components.</p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Examples</th>\n<th>Health relevance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Physical</strong></td>\n<td>Air, water, soil, housing, climate, geography, heat, light, noise, radiation</td>\n<td>Air pollution → COPD, asthma; arsenic water → arsenicosis; heat → heat stroke</td>\n</tr>\n<tr>\n<td><strong>Biological</strong></td>\n<td>Plants, animals, insects, rodents, microorganisms, other humans</td>\n<td>Mosquitoes → dengue, malaria; dogs → rabies; microbes → infections</td>\n</tr>\n<tr>\n<td><strong>Psychosocial</strong></td>\n<td>Customs, culture, beliefs, habits, religion, education, lifestyle, social organisation, health services</td>\n<td>Child marriage → maternal deaths; smoking culture → cancer</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.192","n":192,"part":4,"topic":"Environmental Health (General)","stars":0,"years":[],"colleges":"MMC (2nd Term A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define environment.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Environment</strong>: all that which is <strong>external to the individual human host</strong> (Park); the sum total of all physical, biological and psychosocial factors and conditions surrounding man that influence his health and life.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.193","n":193,"part":4,"topic":"Environmental Health (General)","stars":0,"years":["26M","24M","17Ja"],"colleges":"MuMC (2nd Final C2)","asked":"","note":"","kind":"","sub":"","q":"<p>Define offensive trades with examples. Name / classify the different types of offensive trades.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Offensive trades</strong>: trades or industries that are <strong>injurious to health</strong> or create a <strong>nuisance</strong> to the neighbourhood by offensive smell, smoke, dust, noise, effluents or flies; they need licensing and control under public health law.</p>\n<p><strong>Examples</strong></p>\n<p>Slaughter houses; blood boiling and blood drying; bone boiling and bone crushing; fat melting; tripe cleaning; gut scraping; glue and size making; soap boiling; tanning and leather dressing; fellmongering (hide and skin storing); fish drying and fish markets; manure, rag and bone dealing; lime burning; brick kilns; cattle sheds and dairies; poultry farms.</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>By nuisance</th>\n<th>Examples (Bangladesh)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Offensive smell</td>\n<td>Tanneries, slaughter houses, bone mills, fish drying (<em>shutki</em>)</td>\n</tr>\n<tr>\n<td>Smoke and fumes</td>\n<td>Brick kilns, lime burning</td>\n</tr>\n<tr>\n<td>Dust</td>\n<td>Stone crushing, rice mills, cement works</td>\n</tr>\n<tr>\n<td>Noise</td>\n<td>Saw mills, metal workshops</td>\n</tr>\n<tr>\n<td>Water pollution (effluents)</td>\n<td>Tanneries, textile dyeing, slaughter houses</td>\n</tr>\n<tr>\n<td>Flies and rodents</td>\n<td>Manure stores, poultry and dairy farms, rag and bone shops</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.194","n":194,"part":4,"topic":"Water & Arsenicosis","stars":2,"years":["25Nov","06M"],"colleges":"SSMC (2nd Term D1); MMC (2nd Term A2)","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by safe and wholesome water? Mention the criteria for wholesome water.</p>","a":"<p><strong>Safe and wholesome water</strong></p>\n<p>Water that is:</p>\n<ol>\n<li><strong>Free from pathogenic agents</strong> (bacteria, viruses, protozoa, helminths).</li>\n<li><strong>Free from harmful chemical substances</strong> (arsenic, lead, excess fluoride, nitrate).</li>\n<li><strong>Pleasant to taste</strong>: free from colour, odour, turbidity.</li>\n<li><strong>Usable for domestic purposes</strong> (drinking, cooking, washing).</li>\n</ol>\n<p><strong>Criteria (quality standards)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Aspect</th>\n<th>Criteria</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Physical</strong></td>\n<td>Clear (low turbidity; &lt;1 NTU desirable for disinfection), colourless, odourless, pleasant taste, cool</td>\n</tr>\n<tr>\n<td><strong>Chemical</strong></td>\n<td>Toxic chemicals within guideline values (arsenic ≤0.01 mg/L, lead ≤0.01 mg/L, fluoride ≤1.5 mg/L, nitrate ≤50 mg/L; WHO); pH 6.5–8.5; acceptable hardness and iron</td>\n</tr>\n<tr>\n<td><strong>Bacteriological</strong></td>\n<td><strong>E. coli / thermotolerant coliforms not detectable in any 100 ml sample</strong> (WHO)</td>\n</tr>\n<tr>\n<td><strong>Virological / parasitological</strong></td>\n<td>Free from viruses, protozoal cysts, helminth ova</td>\n</tr>\n<tr>\n<td><strong>Radiological</strong></td>\n<td>Below WHO screening levels</td>\n</tr>\n<tr>\n<td><strong>Disinfection</strong></td>\n<td>Free residual chlorine ≥0.5 mg/L after 30–60 minutes' contact; ≥0.2 mg/L at point of delivery</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Note</strong></p>\n<p><strong>Safe</strong> = no health hazard; <strong>wholesome</strong> = also palatable and acceptable; &quot;potable&quot; water.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO, Guidelines for Drinking-water Quality.</p>"},{"id":"DU.195","n":195,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":["06M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Describe the impounding reservoir.</p>","a":"<p><strong>Impounding reservoir</strong></p>\n<p>An <strong>artificial lake</strong> formed by building a <strong>dam across a river or valley</strong>, to store water for public supply.</p>\n<p><strong>Features</strong></p>\n<ol>\n<li>Usually fed by streams from upland catchment areas.</li>\n<li>Water is <strong>soft</strong>, pleasant to taste and relatively free from pathogens because of storage.</li>\n<li>Quality depends on protection of the <strong>catchment area</strong>.</li>\n</ol>\n<p><strong>Self-purification by storage</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Change</th>\n<th>Result</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Physical</td>\n<td>Sedimentation</td>\n<td>Most suspended matter settles within 24 hours; water clears</td>\n</tr>\n<tr>\n<td>Chemical</td>\n<td>Oxidation of organic matter by aerobic bacteria</td>\n<td>Free ammonia falls; nitrates rise</td>\n</tr>\n<tr>\n<td>Biological</td>\n<td>Pathogens die (unfavourable conditions)</td>\n<td>Large fall in bacteria within the first week</td>\n</tr>\n</tbody>\n</table>\n<p>Optimum storage period: about <strong>10–14 days</strong>; longer storage favours algae growth (bad taste and odour).</p>\n<p><strong>Drawbacks</strong></p>\n<p>Algae and vegetation growth; tastes and odours; contamination from catchment (grazing, human habitation); stratification and low oxygen in deep water.</p>\n<p><strong>Protective measures</strong></p>\n<ol>\n<li>Catchment area free of human habitation, cultivation and grazing.</li>\n<li>Fence and patrol the area; no bathing or washing.</li>\n<li>Control algae (copper sulphate).</li>\n<li>Further treatment: filtration and <strong>chlorination</strong> before supply.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.196","n":196,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":["22Nov"],"colleges":"MMC (2nd Term A1)","asked":"what is the prime source of water?","note":"","kind":"","sub":"","q":"<p>Enumerate the sources of water.</p>","a":"<p><strong>Sources of water (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Types</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Rain</strong></td>\n<td>Rainwater (directly collected)</td>\n<td><strong>Prime (ultimate) source</strong> of all water; purest natural water; soft; may pick up dust and gases; storage needed</td>\n</tr>\n<tr>\n<td><strong>2. Surface water</strong></td>\n<td>(a) Impounding reservoirs (b) Rivers and streams (c) Tanks, ponds and lakes</td>\n<td>Easily contaminated by sewage, industrial and agricultural waste; needs treatment</td>\n</tr>\n<tr>\n<td><strong>3. Ground water</strong></td>\n<td>(a) Shallow wells (b) Deep wells (c) Springs</td>\n<td>Filtered through soil: usually free of pathogens; may contain dissolved minerals (hardness, iron, arsenic, fluoride)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Wells</strong></p>\n<ul>\n<li><strong>Shallow well</strong>: taps water above the first impervious layer; easily polluted.</li>\n<li><strong>Deep well / deep tube well</strong>: taps water below the first impervious layer; safer.</li>\n<li><strong>Sanitary well</strong>: properly located (at least 15 m from sources of contamination), lined, covered, with parapet, platform and drain, and a hand pump.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.197","n":197,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["26M","22Nov","22M","17Nov","17M","13Ja","12Ju","11Ju"],"colleges":"MuMC (2nd Final A2)","asked":"five major water-borne diseases of Bangladesh","note":"","kind":"","sub":"","q":"<p>List / enlist / classify the water-borne diseases; mention the diseases transmitted by contaminated water (also: water-borne diseases prevailing among slum dwellers).</p>","a":"<p><strong>Classification of water-borne diseases (Park)</strong></p>\n<p><strong>A. Biological</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>(i) Caused by presence of infective agent in water</td>\n<td></td>\n</tr>\n<tr>\n<td>Viral</td>\n<td>Hepatitis A, hepatitis E, poliomyelitis, rotavirus diarrhoea</td>\n</tr>\n<tr>\n<td>Bacterial</td>\n<td>Cholera, typhoid and paratyphoid, bacillary dysentery (shigellosis), <em>E. coli</em> diarrhoea</td>\n</tr>\n<tr>\n<td>Protozoal</td>\n<td>Amoebiasis, giardiasis, cryptosporidiosis</td>\n</tr>\n<tr>\n<td>Helminthic</td>\n<td>Roundworm (ascariasis), threadworm, hydatid disease</td>\n</tr>\n<tr>\n<td>Leptospiral</td>\n<td>Weil's disease (leptospirosis)</td>\n</tr>\n<tr>\n<td>(ii) Due to presence of an aquatic host</td>\n<td>Snail → schistosomiasis; cyclops → guinea worm (dracunculiasis), fish tapeworm</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Chemical (water-related)</strong></p>\n<p>Arsenicosis (arsenic), fluorosis (fluoride), methaemoglobinaemia (nitrate), lead poisoning.</p>\n<p><strong>Other water-related groups (Bradley)</strong></p>\n<p>Water-washed (scabies, trachoma); water-related insect vectors (malaria, dengue, filariasis).</p>\n<p><strong>Five major water-borne diseases of Bangladesh</strong></p>\n<ol>\n<li>Cholera / acute watery diarrhoea</li>\n<li>Typhoid (enteric) fever</li>\n<li>Hepatitis E and A</li>\n<li>Bacillary dysentery (shigellosis)</li>\n<li>Amoebiasis / giardiasis<br />\n(+ arsenicosis from groundwater)</li>\n</ol>\n<p><strong>Among slum dwellers</strong>: diarrhoea, cholera, typhoid, hepatitis E, worm infestation, skin infections (water-washed), dengue.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.198","n":198,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can water-borne diseases be prevented?</p>","a":"<p><strong>Prevention of water-borne diseases</strong></p>\n<p><strong>A. Safe water supply</strong></p>\n<ol>\n<li>Protected sources: sanitary tube wells, deep tube wells, piped supply.</li>\n<li><strong>Purification</strong>: large scale (storage → filtration → chlorination); household (boiling, chlorine tablets, filters).</li>\n<li>Maintain <strong>residual chlorine</strong> in distribution; repair leaking pipes; avoid cross-connection with sewers.</li>\n<li>Safe storage at home: covered containers, use of a ladle.</li>\n</ol>\n<p><strong>B. Sanitation</strong></p>\n<ol>\n<li>Sanitary latrines; end open defecation.</li>\n<li>Safe disposal of sewage, sullage and refuse.</li>\n<li>Protect water sources from contamination (distance from latrines ≥15 m).</li>\n</ol>\n<p><strong>C. Personal and food hygiene</strong></p>\n<p>Hand-washing with soap (after toilet, before eating and feeding); safe food handling.</p>\n<p><strong>D. Water quality surveillance</strong></p>\n<p>Regular bacteriological (E. coli) and chemical (arsenic) testing; sanitary inspection.</p>\n<p><strong>E. Specific protection</strong></p>\n<p>Vaccines: typhoid conjugate vaccine, oral cholera vaccine (outbreaks, camps), hepatitis A.</p>\n<p><strong>F. Health education</strong></p>\n<p>Safe water use, hygiene, ORS, early care-seeking.</p>\n<p><strong>G. Case management and outbreak control</strong></p>\n<p>Early diagnosis and treatment (ORS, zinc, antibiotics where indicated); notification; outbreak investigation; chlorination of sources during floods.</p>\n<p><strong>H. Control of aquatic hosts and chemical hazards</strong></p>\n<p>Snail and cyclops control; arsenic-safe water options.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.199","n":199,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["17Nov","16Ju","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist the sources of water pollution / sources of pollution of the river Buriganga.</p>","a":"<p><strong>Sources of water pollution (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Sewage</strong></td>\n<td>Domestic waste water: faeces, urine, sullage; decomposable organic matter and pathogens</td>\n</tr>\n<tr>\n<td><strong>2. Industrial and trade wastes</strong></td>\n<td>Toxic chemicals, heavy metals (chromium, lead, mercury), acids, alkalis, dyes, oils</td>\n</tr>\n<tr>\n<td><strong>3. Agricultural pollutants</strong></td>\n<td>Fertilisers (nitrates, phosphates → eutrophication), pesticides, animal waste</td>\n</tr>\n<tr>\n<td><strong>4. Physical pollutants</strong></td>\n<td>Heat (thermal pollution), radioactive substances</td>\n</tr>\n<tr>\n<td><strong>5. Others</strong></td>\n<td>Solid waste dumping, hospital waste, oil spills, plastics, natural arsenic and fluoride</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Sources of pollution of the river Buriganga</strong></p>\n<ol>\n<li><strong>Untreated domestic sewage</strong> of Dhaka city through drains and canals.</li>\n<li><strong>Tannery effluents</strong> (historically from Hazaribagh: chromium, sulphides, organic matter).</li>\n<li><strong>Industrial effluents</strong>: textile dyeing, washing, chemical and pharmaceutical units.</li>\n<li><strong>Solid waste and plastics</strong> dumped along banks.</li>\n<li><strong>Hospital and clinical waste</strong>.</li>\n<li><strong>Waste, oil and fuel from launches and boats</strong> at Sadarghat.</li>\n<li><strong>Kitchen-market waste</strong> and slaughter waste.</li>\n<li><strong>Encroachment</strong> and silting, which reduce flow and self-purification.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.200","n":200,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["24Nov","07Ja"],"colleges":"ShSMC (2nd Term A2)","asked":"two important indicators of bacteriological quality of drinking water","note":"","kind":"","sub":"","q":"<p>What are the coliform organisms used as indicators of fecal pollution? Why is <em>E. coli</em> an important tool for bacteriological surveillance of drinking water?</p>","a":"<p><strong>Coliform organisms</strong></p>\n<p>Aerobic and facultatively anaerobic, Gram-negative, non-sporing, rod-shaped bacilli that grow in the presence of bile salts and ferment lactose at 35–37 °C with acid and gas production within 48 hours.</p>\n<p><strong>Indicators of faecal pollution</strong></p>\n<table>\n<thead>\n<tr>\n<th>Indicator</th>\n<th>Significance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Total coliforms</strong></td>\n<td>Include faecal and non-faecal (soil) types; indicate treatment efficiency and integrity of distribution</td>\n</tr>\n<tr>\n<td><strong>Faecal (thermotolerant) coliforms</strong>: <em><strong>Escherichia coli</strong></em></td>\n<td>Grow at 44 °C; definite faecal origin; <strong>best indicator</strong></td>\n</tr>\n<tr>\n<td>Faecal streptococci (enterococci)</td>\n<td>Supportive evidence of faecal pollution</td>\n</tr>\n<tr>\n<td><em>Clostridium perfringens</em> (sulphite-reducing clostridia)</td>\n<td>Spores survive long; indicate remote or intermittent pollution</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Two important indicators of bacteriological quality</strong></p>\n<p>E. coli (thermotolerant coliforms) and total coliforms.</p>\n<p><strong>Why E. coli is an important tool</strong></p>\n<ol>\n<li><strong>Always present in large numbers</strong> in human and animal faeces.</li>\n<li><strong>Exclusively faecal origin</strong>; not found in unpolluted water or soil.</li>\n<li>Presence = <strong>recent faecal contamination</strong> → possible presence of pathogens.</li>\n<li><strong>Easily detected and counted</strong> by simple, cheap methods (multiple tube / MPN, membrane filtration).</li>\n<li><strong>Survives in water at least as long as most bacterial pathogens</strong>; more resistant to chlorination than some pathogens.</li>\n<li><strong>Absence</strong> indicates water is bacteriologically safe (for bacterial pathogens).</li>\n<li>WHO standard: <strong>E. coli not detectable in any 100 ml sample</strong> of drinking water.</li>\n</ol>\n<p><strong>Limitation</strong></p>\n<p>Not a perfect indicator for viruses and protozoal cysts, which resist chlorine more.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO, Guidelines for Drinking-water Quality.</p>"},{"id":"DU.201","n":201,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["22M","17M","10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can water be purified? Enumerate briefly water purification on large scale.</p>","a":"<p><strong>Purification of water on a large scale</strong></p>\n<p>Storage → Filtration → Disinfection</p>\n<p><strong>1. Storage</strong></p>\n<p>Water stored in reservoirs: physical (sedimentation), chemical (oxidation) and biological (pathogens die) self-purification; optimum 10–14 days.</p>\n<p><strong>2. Filtration</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Basis</th>\n<th>Key points</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Slow sand (biological) filter</strong></td>\n<td>Vital (biological) layer</td>\n<td>Sand bed ~1 m; rate 0.1–0.4 m³/m²/hour; removes 99.9% of bacteria; large area</td>\n</tr>\n<tr>\n<td><strong>Rapid sand (mechanical) filter</strong></td>\n<td>Coagulation and mechanical straining</td>\n<td>Preceded by coagulation (alum), rapid mixing, flocculation and sedimentation; rate 5–15 m³/m²/hour; cleaned by backwashing</td>\n</tr>\n</tbody>\n</table>\n<p><strong>3. Disinfection</strong></p>\n<ul>\n<li><strong>Chlorination</strong> (most common): chlorine gas, chloramine, perchloron / high-test hypochlorite.</li>\n<li>Others: ozonation, UV irradiation.</li>\n<li>Aim: free residual chlorine <strong>0.5 mg/L after 1 hour contact</strong>.</li>\n</ul>\n<p><strong>Additional treatment as needed</strong></p>\n<p>Aeration (removes iron, gases, odours); softening; fluoridation or defluoridation; arsenic and iron removal.</p>\n<p><strong>Typical modern plant flow</strong></p>\n<p>Intake → Screening → Aeration → Coagulation and flocculation → Sedimentation → Rapid sand filtration → Chlorination → Storage → Distribution</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.202","n":202,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["19Nov","18Nov","16Ja","11Ju","11Ja","06S"],"colleges":"ShSMC (2nd Term A2)","asked":"","note":"","kind":"","sub":"","q":"<p>How can you purify water at household / individual / domestic level (small scale)?</p>","a":"<p><strong>Purification of water at household (small-scale) level</strong></p>\n<p><strong>1. Boiling</strong></p>\n<ul>\n<li>Rolling boil for 5–10 minutes.</li>\n<li>Kills bacteria, viruses, spores, cysts and ova; removes temporary hardness and dissolved gases.</li>\n<li>Drawbacks: fuel cost; no residual protection; can be recontaminated; flat taste.</li>\n</ul>\n<p><strong>2. Chemical disinfection</strong></p>\n<table>\n<thead>\n<tr>\n<th>Agent</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Bleaching powder</strong> (chlorinated lime, ~33% available chlorine)</td>\n<td>Cheap; used as 1% stock solution or for wells</td>\n</tr>\n<tr>\n<td><strong>Chlorine solution</strong></td>\n<td>Prepared from bleaching powder</td>\n</tr>\n<tr>\n<td><strong>High-test hypochlorite (HTH / perchloron)</strong></td>\n<td>60–70% available chlorine; stable</td>\n</tr>\n<tr>\n<td><strong>Chlorine tablets</strong> (sodium dichloroisocyanurate, halazone)</td>\n<td>Convenient for emergencies and floods; 30 minutes' contact</td>\n</tr>\n<tr>\n<td><strong>Iodine</strong></td>\n<td>2 drops of 2% tincture per litre; short-term use</td>\n</tr>\n<tr>\n<td>Potassium permanganate</td>\n<td>Not recommended (weak against coliforms)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>3. Filtration</strong></p>\n<p>Ceramic filters (Pasteur–Chamberland, Berkefeld, Katadyn); candle filters; cloth filtration (reduces cholera by removing plankton); bio-sand filters.</p>\n<p><strong>4. Solar disinfection (SODIS)</strong></p>\n<p>Clear plastic bottles exposed to sunlight for 6 hours.</p>\n<p><strong>5. Combined methods</strong></p>\n<p>Flocculant + chlorine sachets (for turbid water); alum settling followed by chlorination.</p>\n<p><strong>Safe storage</strong></p>\n<p>Narrow-mouthed, covered container; pour or use a long-handled ladle.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.203","n":203,"part":4,"topic":"Water & Arsenicosis","stars":1,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss slow sand filtration method with diagram for purification of water.</p>","a":"<p><strong>Slow sand (biological) filter: elements</strong></p>\n<table>\n<thead>\n<tr>\n<th>Element</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Supernatant (raw) water</strong></td>\n<td>Depth 1–1.5 m above the sand; provides constant head to drive water through; waiting period 3–12 hours allows sedimentation, oxidation and agglutination of particles</td>\n</tr>\n<tr>\n<td><strong>2. Bed of graded sand</strong></td>\n<td>About 1 m thick; effective size 0.2–0.3 mm; supported by about 0.3 m of graded gravel; the <strong>vital layer</strong> forms on its surface</td>\n</tr>\n<tr>\n<td><strong>3. Under-drainage system</strong></td>\n<td>Porous or perforated pipes at the bottom; collects filtered water and supports the bed</td>\n</tr>\n<tr>\n<td><strong>4. System of filter control valves</strong></td>\n<td>Regulate and maintain a constant rate of filtration (0.1–0.4 m³/m²/hour); venturi meter measures resistance (loss of head)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Diagram (vertical section)</strong></p>\n<pre><code>        Raw water inlet →\n  ┌─────────────────────────────────┐\n  │  Supernatant water (1–1.5 m)    │\n  │.................................│ ← Vital layer (schmutzdecke)\n  │  Sand bed (~1 m; 0.2–0.3 mm)    │\n  │  Graded gravel (~0.3 m)         │\n  │═══ Under-drainage pipes ════════│ → Filter control valve → Filtered water\n  └─────────────────────────────────┘\n</code></pre>\n<p><strong>Mechanism</strong></p>\n<p>Mechanical straining, sedimentation, adsorption, oxidation and <strong>biological action</strong> of the vital layer.</p>\n<p><strong>Cleaning</strong></p>\n<p>When resistance becomes too high (loss of head about 1.3 m), the top 1–2 cm of sand (with vital layer) is scraped off; after repeated scrapings the bed is re-sanded.</p>\n<p><strong>Advantages</strong></p>\n<p>Simple to build and operate; cheap; excellent quality: bacterial removal 99.9–99.99%, E. coli 99–99.9%.</p>\n<p><strong>Disadvantages</strong></p>\n<p>Needs large area; slow; cannot handle very turbid water; affected by algae; not suitable for big cities.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.204","n":204,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":["09Ja","07Ju","04S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss vital layer (biological layer) of filter: its constituents and role.</p>","a":"<p><strong>Vital layer (biological layer)</strong></p>\n<p>Also called <strong>schmutzdecke</strong>, zoogleal layer, dirty skin or biological layer: a slimy, gelatinous film that forms on the <strong>surface of the sand bed</strong> of a slow sand filter within a few days of starting.</p>\n<p><strong>Formation</strong></p>\n<p>New filter → raw water passes → organisms and particles collect on the sand surface → layer grows in several days → filter is &quot;<strong>ripened</strong>&quot;. Until then, filtered water is run to waste.</p>\n<p><strong>Constituents</strong></p>\n<ol>\n<li>Thread-like <strong>algae</strong></li>\n<li><strong>Plankton</strong></li>\n<li><strong>Diatoms</strong></li>\n<li><strong>Bacteria</strong></li>\n<li>Other micro-organisms and trapped organic matter</li>\n</ol>\n<p><strong>Role (functions)</strong></p>\n<ol>\n<li>The <strong>&quot;heart&quot; of the slow sand filter</strong>.</li>\n<li><strong>Removes organic matter</strong>.</li>\n<li><strong>Holds back bacteria</strong> and destroys them.</li>\n<li><strong>Oxidises ammoniacal nitrogen into nitrates</strong>.</li>\n<li>Helps yield <strong>bacteria-free water</strong> (99.9% removal).</li>\n<li>Acts as a fine strainer for suspended particles.</li>\n</ol>\n<p><strong>Practical point</strong></p>\n<p>As the layer thickens, resistance rises; it is scraped off during cleaning and re-forms naturally.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.205","n":205,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":["05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Describe rapid sand filtration process.</p>","a":"<p><strong>Rapid sand (mechanical) filtration: steps</strong></p>\n<table>\n<thead>\n<tr>\n<th>Step</th>\n<th>Process</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Coagulation</strong></td>\n<td>Alum (5–40 mg/L, by turbidity) added to raw water</td>\n</tr>\n<tr>\n<td>2. <strong>Rapid mixing</strong></td>\n<td>Violent agitation for a few minutes to disperse alum</td>\n</tr>\n<tr>\n<td>3. <strong>Flocculation</strong></td>\n<td>Slow, gentle stirring (~30 minutes) → thick, white flocs of aluminium hydroxide form</td>\n</tr>\n<tr>\n<td>4. <strong>Sedimentation</strong></td>\n<td>Water held in settling tanks for 2–6 hours; flocs carry down impurities and bacteria</td>\n</tr>\n<tr>\n<td>5. <strong>Filtration</strong></td>\n<td>Partly clarified water passes through rapid sand filters: sand bed ~1 m, effective size 0.4–0.7 mm, rate 5–15 m³/m²/hour; remaining floc forms a layer that removes bacteria</td>\n</tr>\n<tr>\n<td>6. <strong>Backwashing</strong></td>\n<td>When resistance (loss of head) becomes high, flow is reversed with water (and compressed air) to clean the sand; takes about 15 minutes</td>\n</tr>\n<tr>\n<td>7. <strong>Chlorination</strong></td>\n<td>Final disinfection before distribution</td>\n</tr>\n</tbody>\n</table>\n<p>Raw water → Alum → Rapid mix → Flocculation → Sedimentation → Rapid sand filter → Chlorination → Supply</p>\n<p><strong>Advantages</strong></p>\n<p>Less space; fast; deals with raw, turbid water; easy and quick cleaning; plant can be compact.</p>\n<p><strong>Disadvantages</strong></p>\n<p>Costly to build and run; needs skilled staff and chemicals; bacterial removal (98–99%) lower than slow sand filter, so chlorination is essential.</p>\n<p><strong>Slow vs rapid sand filter</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Slow sand</th>\n<th>Rapid sand</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Space</td>\n<td>Large</td>\n<td>Small</td>\n</tr>\n<tr>\n<td>Rate</td>\n<td>0.1–0.4 m³/m²/hour</td>\n<td>5–15 m³/m²/hour</td>\n</tr>\n<tr>\n<td>Sand size</td>\n<td>0.2–0.3 mm</td>\n<td>0.4–0.7 mm</td>\n</tr>\n<tr>\n<td>Pre-treatment</td>\n<td>Plain sedimentation</td>\n<td>Coagulation and flocculation</td>\n</tr>\n<tr>\n<td>Main action</td>\n<td>Biological (vital layer)</td>\n<td>Mechanical</td>\n</tr>\n<tr>\n<td>Cleaning</td>\n<td>Scraping</td>\n<td>Backwashing</td>\n</tr>\n<tr>\n<td>Bacterial removal</td>\n<td>99.9–99.99%</td>\n<td>98–99%</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.206","n":206,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["17Ja","09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the principles / methods of chlorination for disinfecting large amount of water?</p>","a":"<p><strong>Action of chlorine</strong></p>\n<p>Cl₂ + H₂O → HOCl (hypochlorous acid) + HCl; HOCl ⇌ H⁺ + OCl⁻ (hypochlorite ion). <strong>HOCl</strong> is the main germicidal agent (stronger at low pH); chlorine also oxidises iron, manganese, hydrogen sulphide and organic matter, and controls algae.</p>\n<p><strong>Principles of chlorination (Park)</strong></p>\n<ol>\n<li>Water must be <strong>clear</strong>, free from turbidity (turbidity shields organisms).</li>\n<li><strong>Chlorine demand</strong> must be estimated: the amount of chlorine needed to destroy bacteria and oxidise organic matter and ammonia; the point where free residual chlorine begins to appear is the <strong>break point</strong>.</li>\n<li><strong>Contact period</strong>: free residual chlorine must be present for <strong>at least 1 hour</strong> to kill bacteria and viruses.</li>\n<li><strong>Minimum free residual chlorine: 0.5 mg/L</strong> for 1 hour.</li>\n<li><strong>Dose = chlorine demand + free residual chlorine</strong>.</li>\n</ol>\n<p><strong>Methods of chlorination (large scale)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Chlorine gas</strong></td>\n<td>First choice: cheap, quick, efficient, easy to apply; needs special equipment (chlorinator)</td>\n</tr>\n<tr>\n<td><strong>Chloramine</strong></td>\n<td>Chlorine + ammonia; slow action; less taste; longer-lasting residual in distribution</td>\n</tr>\n<tr>\n<td><strong>Perchloron (high-test hypochlorite)</strong></td>\n<td>Calcium hypochlorite, 60–70% available chlorine; used where gas is not available</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.207","n":207,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["17Ja","13Ju","08Ja","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by break point chlorination?</p>","a":"<p><strong>Break-point chlorination</strong></p>\n<p>Adding chlorine to water <strong>beyond the break point</strong>, so that a <strong>free residual chlorine</strong> is present after the chlorine demand is fully met.</p>\n<p><strong>What happens as chlorine is added (chlorine demand curve)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Event</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>Chlorine first used up by reducing substances (iron, H₂S, organic matter) → no residual</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Chlorine combines with ammonia → <strong>combined chlorine (chloramines)</strong>; residual rises</td>\n</tr>\n<tr>\n<td>3</td>\n<td>More chlorine <strong>oxidises chloramines</strong> → residual falls</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Break point</strong>: lowest point; all ammonia and organic matter oxidised</td>\n</tr>\n<tr>\n<td>5</td>\n<td>Beyond break point, <strong>free residual chlorine</strong> rises in direct proportion to chlorine added</td>\n</tr>\n</tbody>\n</table>\n<p>Chlorine added → demand met → combined residual ↑ → destroyed ↓ → <strong>break point</strong> → free residual ↑</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.208","n":208,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the steps in well disinfection with example.</p>","a":"<p><strong>Steps in disinfection of a well (with bleaching powder)</strong></p>\n<p><strong>1. Find the volume of water in the well</strong></p>\n<p>Measure diameter (d, metres) and depth of water column (h, metres).<br />\nVolume (litres) = (3.14 × d² × h ÷ 4) × 1000</p>\n<p><strong>2. Find the amount of bleaching powder required</strong></p>\n<p>Estimate chlorine demand with <strong>Horrock's apparatus</strong>; as a rule of thumb about <strong>2.5 g of good bleaching powder per 1,000 litres</strong> gives 1 mg/L chlorine with 0.5 mg/L free residual after 1 hour.</p>\n<p><strong>3. Dissolve the bleaching powder</strong></p>\n<p>Make a thin paste in a bucket with a little water; add more water to fill, stir, let settle for ~10 minutes; use the clear supernatant (chlorine solution); discard sediment (lime).</p>\n<p><strong>4. Deliver the chlorine solution into the well</strong></p>\n<p>Lower the bucket deep into the well water; jerk it up and down several times to mix thoroughly.</p>\n<p><strong>5. Contact period</strong></p>\n<p>Allow <strong>1 hour</strong> before water is drawn.</p>\n<p><strong>6. Test for residual chlorine (OT test)</strong></p>\n<p>Free residual chlorine should be <strong>≥0.5 mg/L</strong> after 1 hour; if less, repeat the process.</p>\n<p><strong>Example</strong></p>\n<p>Well diameter 2 m, water depth 5 m:<br />\nVolume = 3.14 × 2² × 5 ÷ 4 × 1000 = <strong>15,700 litres</strong><br />\nBleaching powder = 15.7 × 2.5 g ≈ <strong>39 g</strong></p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.209","n":209,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":["07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write the names of the chemicals in excess that may constitute ground for rejection of public water supply.</p>","a":"<p><strong>Chemicals in excess that make public water supply unacceptable (grounds for rejection)</strong></p>\n<p><strong>A. Toxic substances (health hazard)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Chemical</th>\n<th>WHO guideline value (mg/L)</th>\n<th>Health effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Arsenic</strong></td>\n<td>0.01</td>\n<td>Arsenicosis, skin, lung, bladder cancers</td>\n</tr>\n<tr>\n<td><strong>Lead</strong></td>\n<td>0.01</td>\n<td>Neurotoxicity in children, anaemia</td>\n</tr>\n<tr>\n<td><strong>Cadmium</strong></td>\n<td>0.003</td>\n<td>Kidney damage</td>\n</tr>\n<tr>\n<td><strong>Mercury</strong> (inorganic)</td>\n<td>0.006</td>\n<td>Kidney and nervous system damage</td>\n</tr>\n<tr>\n<td><strong>Chromium</strong></td>\n<td>0.05</td>\n<td>Carcinogen (Cr VI)</td>\n</tr>\n<tr>\n<td><strong>Selenium</strong></td>\n<td>0.04</td>\n<td>Hair and nail loss, neuropathy</td>\n</tr>\n<tr>\n<td><strong>Cyanide</strong></td>\n<td>—</td>\n<td>Acute poisoning</td>\n</tr>\n<tr>\n<td><strong>Barium</strong>, <strong>antimony</strong>, <strong>nickel</strong>, <strong>uranium</strong></td>\n<td>Low guideline values</td>\n<td>Various organ toxicity</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Chemicals affecting health in excess</strong></p>\n<table>\n<thead>\n<tr>\n<th>Chemical</th>\n<th>WHO guideline value (mg/L)</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Fluoride</strong></td>\n<td>1.5</td>\n<td>Dental and skeletal fluorosis</td>\n</tr>\n<tr>\n<td><strong>Nitrate</strong> (as NO₃⁻)</td>\n<td>50</td>\n<td>Methaemoglobinaemia (blue baby)</td>\n</tr>\n<tr>\n<td><strong>Nitrite</strong></td>\n<td>3</td>\n<td>Methaemoglobinaemia</td>\n</tr>\n<tr>\n<td>Boron, manganese</td>\n<td>Guideline values set</td>\n<td>Toxicity</td>\n</tr>\n<tr>\n<td>Pesticides, organic chemicals (benzene, vinyl chloride)</td>\n<td>Very low values</td>\n<td>Cancers, organ toxicity</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Substances affecting acceptability (aesthetic)</strong></p>\n<p>Iron, manganese, high hardness, chloride, sulphate, total dissolved solids, zinc, copper, hydrogen sulphide; colour, taste, odour, turbidity.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO, Guidelines for Drinking-water Quality (4th ed.).</p>"},{"id":"DU.210","n":210,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["25Nov","23Nov"],"colleges":"SSMC (2nd Term D1)","asked":"WHO criteria of drinking water","note":"","kind":"","sub":"","q":"<p>Write down the microbiological parameter of drinking water according to the WHO guideline.</p>","a":"<p><strong>Microbiological parameters of drinking water (WHO Guidelines for Drinking-water Quality)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Water</th>\n<th>Parameter</th>\n<th>Guideline</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>All water directly intended for drinking</strong></td>\n<td><em><strong>E. coli</strong></em> or thermotolerant coliform bacteria</td>\n<td><strong>Not detectable in any 100 ml sample</strong></td>\n</tr>\n<tr>\n<td><strong>Treated water entering the distribution system</strong></td>\n<td><em>E. coli</em> or thermotolerant coliforms</td>\n<td>Not detectable in any 100 ml sample</td>\n</tr>\n<tr>\n<td><strong>Treated water in the distribution system</strong></td>\n<td><em>E. coli</em> or thermotolerant coliforms</td>\n<td>Not detectable in any 100 ml sample</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Supporting criteria</strong></p>\n<ol>\n<li><strong>Total coliforms</strong>: should not be detectable in treated water entering distribution; their presence indicates inadequate treatment or post-treatment contamination.</li>\n<li><strong>No pathogenic organisms</strong> (bacteria, viruses, protozoa, helminths).</li>\n<li><strong>Turbidity</strong> below 1 NTU (ideally lower) for effective disinfection.</li>\n<li><strong>Free residual chlorine</strong>: ≥0.5 mg/L after at least 30 minutes' contact (pH &lt;8); ≥0.2 mg/L at the point of delivery.</li>\n<li>Regular <strong>sanitary inspection</strong> and monitoring (Water Safety Plans).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO, Guidelines for Drinking-water Quality (4th ed.).</p>"},{"id":"DU.211","n":211,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":["05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by hardness of water?</p>","a":"<p><strong>Hardness of water</strong></p>\n<p>The <strong>soap-destroying power</strong> of water; caused mainly by dissolved <strong>calcium and magnesium</strong> salts (bicarbonates, sulphates, chlorides, nitrates). Hard water needs more soap to lather.</p>\n<p><strong>Types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Caused by</th>\n<th>Removed by boiling?</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Temporary (carbonate) hardness</strong></td>\n<td>Bicarbonates of Ca and Mg</td>\n<td>Yes</td>\n</tr>\n<tr>\n<td><strong>Permanent (non-carbonate) hardness</strong></td>\n<td>Sulphates, chlorides, nitrates of Ca and Mg</td>\n<td>No</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.212","n":212,"part":4,"topic":"Water & Arsenicosis","stars":1,"years":["06S","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you remove the hardness of water?</p>","a":"<p><strong>Removal of hardness</strong></p>\n<p><strong>A. Temporary hardness</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Reaction / description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Boiling</strong></td>\n<td>Ca(HCO₃)₂ → CaCO₃↓ + H₂O + CO₂↑ (calcium carbonate precipitates)</td>\n</tr>\n<tr>\n<td><strong>2. Addition of lime (Clark's method)</strong></td>\n<td>Ca(HCO₃)₂ + Ca(OH)₂ → 2CaCO₃↓ + 2H₂O; lime removes CO₂ and precipitates carbonate; used on a large scale</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Permanent hardness</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Reaction / description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Addition of sodium carbonate (washing soda)</strong></td>\n<td>CaSO₄ + Na₂CO₃ → CaCO₃↓ + Na₂SO₄ (also removes temporary hardness)</td>\n</tr>\n<tr>\n<td><strong>2. Base exchange process (permutit / zeolite)</strong></td>\n<td>Water passed through sodium permutit: Na₂-Z + Ca²⁺ / Mg²⁺ → Ca-Z / Mg-Z + 2Na⁺; removes both types (can give zero hardness); permutit regenerated with strong brine (NaCl)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Modern methods</strong></p>\n<p>Ion-exchange resins (demineralisation); reverse osmosis; nanofiltration.</p>\n<p><strong>Advantages of softening</strong></p>\n<p>Saves soap and fuel; prevents scaling in pipes and boilers; better cooking and washing.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.213","n":213,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["16Ju","12Ju"],"colleges":"ShSMC (2nd Term B4)","asked":"characteristic skin manifestation and three health effects of chronic arsenic exposure","note":"","kind":"","sub":"","q":"<p>What is arsenicosis?</p>","a":"<p><strong>Arsenicosis</strong></p>\n<p>A chronic health condition caused by prolonged ingestion (usually ≥6 months) of arsenic above the safe level, usually shown by <strong>characteristic skin lesions</strong>, with or without involvement of internal organs and malignancies (WHO).</p>\n<p><strong>Characteristic skin manifestations</strong></p>\n<table>\n<thead>\n<tr>\n<th>Lesion</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Melanosis</strong></td>\n<td>Diffuse or spotted (&quot;raindrop&quot;) dark pigmentation, mainly on trunk and limbs</td>\n</tr>\n<tr>\n<td><strong>Leucomelanosis</strong></td>\n<td>Mixed white (depigmented) and dark spots</td>\n</tr>\n<tr>\n<td><strong>Keratosis</strong></td>\n<td>Thickening and nodules of <strong>palms and soles</strong> (hyperkeratosis)</td>\n</tr>\n<tr>\n<td>Later</td>\n<td>Bowen's disease, squamous and basal cell carcinoma of skin</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Occupational Health).</p>"},{"id":"DU.214","n":214,"part":4,"topic":"Water & Arsenicosis","stars":3,"years":["15Ja","14Ja"],"colleges":"ShSMC (2nd Term B4)","asked":"two community-level preventive measures","note":"","kind":"","sub":"","q":"<p>Suggest provision of safe water in an arsenicosis affected community.</p>","a":"<p><strong>Provision of safe water in an arsenic-affected community</strong></p>\n<p><strong>A. Identify safe and unsafe sources</strong></p>\n<ol>\n<li><strong>Test every tube well</strong> (field kits / laboratory).</li>\n<li><strong>Mark</strong> tube wells: <strong>red</strong> = unsafe (above standard), <strong>green</strong> = safe.</li>\n<li>Encourage <strong>well-switching</strong> to nearby green (safe) wells.</li>\n</ol>\n<p><strong>B. Alternative safe water options</strong></p>\n<table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Deep tube wells</strong></td>\n<td>Tap deeper, usually arsenic-free aquifers (below the first impervious layer)</td>\n</tr>\n<tr>\n<td><strong>Rainwater harvesting</strong></td>\n<td>Collect roof rainwater in clean tanks; arsenic-free</td>\n</tr>\n<tr>\n<td><strong>Pond sand filter (PSF)</strong></td>\n<td>Pond water filtered through a sand filter for community use</td>\n</tr>\n<tr>\n<td><strong>Dug (ring) wells</strong></td>\n<td>Shallow, well-aerated; usually low arsenic; need protection and disinfection</td>\n</tr>\n<tr>\n<td><strong>Piped water supply</strong></td>\n<td>Treated surface or deep groundwater supplied through pipes</td>\n</tr>\n<tr>\n<td><strong>Arsenic removal technologies</strong></td>\n<td>Household filters (e.g., SONO, three-pitcher); community arsenic-iron removal plants</td>\n</tr>\n<tr>\n<td><strong>Treated surface water</strong></td>\n<td>River or pond water with filtration and chlorination</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Supporting measures</strong></p>\n<ol>\n<li>Health education on arsenic risk and use of safe sources.</li>\n<li>Community participation in maintaining shared safe sources.</li>\n<li>Screening and management of arsenicosis patients.</li>\n<li>Nutrition support; no stigma for patients.</li>\n<li>Regular water-quality monitoring; ban on installing new shallow wells in contaminated areas.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.215","n":215,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":[],"colleges":"MMC (2nd Term A2)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the daily requirement of water for all purposes for rural and urban people.</p>","a":"<p><strong>Daily water requirement</strong></p>\n<table>\n<thead>\n<tr>\n<th>Use</th>\n<th>Requirement (per person per day)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Physiological (drinking)</strong></td>\n<td>About 2–3 litres (more in hot climate and heavy work)</td>\n</tr>\n<tr>\n<td><strong>Basic access (WHO)</strong></td>\n<td>At least <strong>20 litres</strong> for drinking, cooking and basic hygiene</td>\n</tr>\n<tr>\n<td><strong>All domestic needs (UN / WHO)</strong></td>\n<td><strong>50–100 litres</strong></td>\n</tr>\n<tr>\n<td><strong>Urban: all purposes (Park)</strong></td>\n<td><strong>150–200 litres</strong> (drinking, cooking, bathing, washing, flushing, plus public, trade and industrial uses)</td>\n</tr>\n<tr>\n<td><strong>Rural (Park; Indian norm)</strong></td>\n<td>About <strong>40 litres</strong> for domestic needs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Factors affecting requirement</strong></p>\n<p>Climate; standard of living; habits; type of sanitation (flush vs pit); industry and trade; cost and availability; leakage and waste.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO / UN, right to water.</p>"},{"id":"DU.216","n":216,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":[],"colleges":"MMC (2nd Term A4)","asked":"","note":"","kind":"","sub":"","q":"<p>You are posted as a medical officer in a flood-affected area where all the tube wells are submerged under water. Describe in detail how you will ensure safe drinking water for the people of that area.</p>","a":"<p><strong>Situation</strong></p>\n<p>Tube wells submerged → groundwater sources contaminated by flood water, faeces and debris → high risk of cholera, diarrhoea, typhoid, hepatitis E, leptospirosis, skin infections.</p>\n<p><strong>A. Immediate assessment</strong></p>\n<ol>\n<li>Rapid survey of population, shelters, water sources, latrines; identify vulnerable groups.</li>\n<li>Coordinate with Upazila administration, DPHE, NGOs, WASH partners; set up a control room.</li>\n<li>Start <strong>disease surveillance</strong> (daily diarrhoea reporting) and ORS corners.</li>\n</ol>\n<p><strong>B. Emergency safe water supply</strong></p>\n<ol>\n<li><strong>Distribute household water treatment</strong>: water purification tablets (chlorine/NaDCC), bleaching powder solution, or flocculant–disinfectant sachets with clear instructions; 30 minutes' contact.</li>\n<li><strong>Boil water</strong> where fuel is available (rolling boil).</li>\n<li><strong>Supply bottled or tanker water</strong> to shelters; mobile water treatment plants.</li>\n<li><strong>Rainwater harvesting</strong> with clean containers.</li>\n<li>Provide <strong>clean, covered containers</strong> (jerry cans) and ladles; at least 15 litres/person/day in emergency (Sphere), minimum 2–3 litres for drinking.</li>\n<li>Use <strong>raised or high-platform tube wells</strong> not submerged; clean their surroundings.</li>\n</ol>\n<p><strong>C. After water recedes: restore sources</strong></p>\n<ol>\n<li><strong>Disinfect tube wells</strong>: pump out water until clear; pour chlorine solution (bleaching powder) into the well pipe; contact for several hours (overnight); pump out until chlorine smell disappears.</li>\n<li><strong>Disinfect dug wells</strong>: Horrock's test; ~2.5 g bleaching powder/1,000 L; 1 hour contact; OT test for residual ≥0.5 mg/L.</li>\n<li>Repair platforms and drains; test water (E. coli, arsenic) before reuse.</li>\n</ol>\n<p><strong>D. Sanitation and hygiene</strong></p>\n<ol>\n<li>Emergency latrines away (≥15 m) and downhill from water sources; avoid open defecation.</li>\n<li>Hygiene kits: soap, sanitary pads; hand-washing points.</li>\n<li>Safe disposal of refuse and dead animals; chlorinate flooded latrines.</li>\n</ol>\n<p><strong>E. Health measures</strong></p>\n<p>Health education (boil/chlorinate, hand-washing, safe food); ORS and zinc stocks; early case management and referral; <strong>oral cholera vaccine</strong> if outbreak risk; outbreak response team.</p>\n<p><strong>F. Monitoring</strong></p>\n<p>Daily residual chlorine checks at distribution points (≥0.2–0.5 mg/L); disease trends; feedback to community.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Disaster Management).</p>"},{"id":"DU.217","n":217,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":[],"colleges":"DMC (2nd Assess C5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A rural community is experiencing frequent outbreaks of diseases. Health professional observed that most households obtain drinking water from an unprotected pond. [7]</p>\n<ul>\n<li>a) List five diseases commonly transmitted through contaminated water. (2)</li>\n<li>b) Describe the methods of purification of water at community level. (2.5)</li>\n<li>c) Describe the methods of purification of water at household levels. (2.5)</li>\n</ul>","a":"<p><strong>a) Five diseases transmitted through contaminated water (2)</strong></p>\n<ol>\n<li>Cholera / acute watery diarrhoea</li>\n<li>Typhoid (enteric) fever</li>\n<li>Hepatitis E and A</li>\n<li>Bacillary dysentery (shigellosis)</li>\n<li>Amoebiasis / giardiasis<br />\n(Also: poliomyelitis, rotavirus diarrhoea, leptospirosis, worm infestations.)</li>\n</ol>\n<p><strong>b) Purification of water at community level (2.5)</strong></p>\n<p>Storage → Filtration → Disinfection</p>\n<ol>\n<li><strong>Storage</strong>: sedimentation, oxidation, natural die-off of pathogens.</li>\n<li><strong>Filtration</strong>:\n<ul>\n<li>Slow sand filter (biological; vital layer; pond sand filter in villages).</li>\n<li>Rapid sand filter (coagulation with alum → flocculation → sedimentation → filtration → backwashing).</li>\n</ul>\n</li>\n<li><strong>Disinfection: chlorination</strong>: principles: clear water, estimate chlorine demand, free residual chlorine 0.5 mg/L after 1 hour contact; methods: chlorine gas, chloramine, perchloron.</li>\n<li><strong>Disinfection of wells</strong> with bleaching powder (Horrock's test; OT test).</li>\n<li><strong>Alternative safe sources</strong>: sanitary tube wells, deep tube wells, piped supply; protect pond (fencing, no bathing or washing).</li>\n</ol>\n<p><strong>c) Purification at household level (2.5)</strong></p>\n<ol>\n<li><strong>Boiling</strong>: rolling boil 5–10 minutes; kills all pathogens.</li>\n<li><strong>Chemical disinfection</strong>: bleaching powder solution, chlorine tablets (NaDCC), high-test hypochlorite; 30 minutes' contact.</li>\n<li><strong>Filtration</strong>: ceramic or candle filters; cloth filtration (folded sari cloth reduces cholera).</li>\n<li><strong>Solar disinfection (SODIS)</strong>: clear bottles in sunlight for 6 hours.</li>\n<li><strong>Combined</strong>: alum settling + chlorination; flocculant–disinfectant sachets.</li>\n<li><strong>Safe storage</strong>: covered, narrow-mouthed container; ladle for drawing water.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.218","n":218,"part":4,"topic":"Water & Arsenicosis","stars":0,"years":[],"colleges":"MuMC (2nd Final A5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A rural community develops an outbreak of acute diarrheal disease following flooding. Several tube-wells were submerged and some latrines are located close to the water sources. [2+2+3]</p>\n<ul>\n<li>(a) Describe the possible routes of contamination of drinking water in this situation. (2)</li>\n<li>(b) Analyze the environmental factors responsible for the outbreak. (2)</li>\n<li>(c) Develop a community-level plan to prevent further transmission of the disease. (3)</li>\n</ul>","a":"<p><strong>(a) Routes of contamination of drinking water (2)</strong></p>\n<ol>\n<li><strong>Flood water entering submerged tube wells</strong> through the pump head, broken platforms and loose joints.</li>\n<li><strong>Overflowing latrines</strong> near water sources → faecal matter washed into wells and ponds.</li>\n<li><strong>Seepage</strong> of faecally contaminated surface water into shallow aquifers.</li>\n<li><strong>Contaminated storage and handling</strong>: dirty containers, hands, utensils.</li>\n<li>Use of <strong>flood or pond water</strong> for drinking, washing and cooking.</li>\n<li>Animal carcasses, solid waste and sewage in flood water.</li>\n</ol>\n<p><strong>(b) Environmental factors responsible (2)</strong></p>\n<ol>\n<li><strong>Flooding</strong>: spreads faecal contamination; damages water and sanitation infrastructure.</li>\n<li><strong>Poor siting of latrines</strong> (&lt;15 m from water sources; upslope).</li>\n<li><strong>Unsafe water sources</strong>: submerged shallow tube wells, ponds.</li>\n<li><strong>Inadequate sanitation</strong>: open defecation, unsanitary latrines.</li>\n<li><strong>Crowding</strong> in shelters; poor hygiene; lack of soap.</li>\n<li><strong>Warm, humid climate</strong> favouring bacterial growth; flies.</li>\n<li>Poor <strong>food hygiene</strong>; lack of fuel for boiling.</li>\n</ol>\n<p><strong>(c) Community-level plan to prevent further transmission (3)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Actions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Surveillance and case management</td>\n<td>Daily case reporting; ORS corners; zinc; refer severe cases; stool samples to IEDCR; line list</td>\n</tr>\n<tr>\n<td>Safe water</td>\n<td>Distribute chlorine tablets/bleaching powder; boil water; tanker or bottled water; disinfect tube wells after flood; test water</td>\n</tr>\n<tr>\n<td>Sanitation</td>\n<td>Emergency latrines ≥15 m and downslope from water sources; desludge or seal flooded latrines; safe disposal of child faeces</td>\n</tr>\n<tr>\n<td>Hygiene</td>\n<td>Hand-washing stations with soap; hygiene kits; food hygiene</td>\n</tr>\n<tr>\n<td>Health education</td>\n<td>Mass and interpersonal messages through CHWs, imams, teachers, miking</td>\n</tr>\n<tr>\n<td>Specific protection</td>\n<td>Oral cholera vaccine campaign if cholera confirmed</td>\n</tr>\n<tr>\n<td>Coordination</td>\n<td>Upazila health and disaster committee, DPHE, NGOs; community volunteers</td>\n</tr>\n<tr>\n<td>Long-term</td>\n<td>Raised-platform tube wells; proper latrine siting; flood-resilient WASH</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Epidemiology of Communicable Diseases).</p>"},{"id":"DU.219","n":219,"part":4,"topic":"Air Pollution","stars":2,"years":["12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is air pollution?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Air pollution</strong>: the presence in the outdoor (or indoor) air of one or more contaminants (gases, particles, biological agents) in such quantity and for such duration as to be harmful to human, animal or plant life or property, or to interfere unreasonably with the comfortable enjoyment of life or property (WHO concept).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO Global Air Quality Guidelines, 2021.</p>"},{"id":"DU.220","n":220,"part":4,"topic":"Air Pollution","stars":3,"years":["21M","19Nov"],"colleges":"SSMC (2nd Term D2)","asked":"sources of major air pollutants","note":"","kind":"","sub":"","q":"<p>How does air become polluted? Enumerate the causes of air pollution. What are the air-borne diseases?</p>","a":"<p><strong>How air becomes polluted: sources (causes)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Pollutants</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Automobiles</strong></td>\n<td>CO, NOx, hydrocarbons, PM, lead (leaded fuel), smoke</td>\n</tr>\n<tr>\n<td><strong>2. Industries</strong></td>\n<td>SO₂, NOx, PM, fluorides, metals, organic chemicals</td>\n</tr>\n<tr>\n<td><strong>3. Domestic sources</strong></td>\n<td>Burning of wood, coal, cow dung, kerosene → smoke, CO, PM</td>\n</tr>\n<tr>\n<td><strong>4. Brick kilns</strong></td>\n<td>PM, SO₂, CO, black carbon</td>\n</tr>\n<tr>\n<td><strong>5. Construction and road dust</strong></td>\n<td>Coarse and fine PM</td>\n</tr>\n<tr>\n<td><strong>6. Miscellaneous</strong></td>\n<td>Burning of refuse, incinerators, pesticide spraying, aircraft, nuclear tests</td>\n</tr>\n<tr>\n<td><strong>7. Natural</strong></td>\n<td>Volcanoes, forest fires, dust storms, pollen, sea salt</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Process</strong></p>\n<p>Emission of primary pollutants → dispersion (affected by wind, temperature inversion, humidity) → chemical reactions (sunlight → ozone, smog; SO₂ + water → acid rain) → exposure.</p>\n<p><strong>Air-borne diseases</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Infections spread by droplets / droplet nuclei</td>\n<td>Tuberculosis, influenza, COVID-19, measles, chickenpox, diphtheria, pertussis, pneumonia, mumps, meningococcal meningitis</td>\n</tr>\n<tr>\n<td>Due to air pollutants</td>\n<td>Asthma, chronic bronchitis, COPD, lung cancer, ischaemic heart disease, stroke, pneumoconiosis (occupational dusts), allergic rhinitis</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.221","n":221,"part":4,"topic":"Air Pollution","stars":0,"years":["06Ja"],"colleges":"SSMC (2nd Term D2)","asked":"effects of air pollutants on human health","note":"","kind":"","sub":"","q":"<p>Mention the effects of air pollution.</p>","a":"<p><strong>Effects of air pollution</strong></p>\n<p><strong>A. Health effects</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Effects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Immediate (acute)</strong></td>\n<td>Eye, nose and throat irritation; cough; acute bronchitis; asthma attacks; CO poisoning; deaths in smog episodes (London smog, 1952)</td>\n</tr>\n<tr>\n<td><strong>Delayed (chronic)</strong></td>\n<td>Chronic bronchitis, COPD, emphysema, <strong>lung cancer</strong>, reduced lung function in children, ischaemic heart disease, stroke</td>\n</tr>\n<tr>\n<td><strong>Specific pollutants</strong></td>\n<td>CO → carboxyhaemoglobin, hypoxia; SO₂ → bronchospasm; NO₂ → lung irritation, infections; ozone → reduced lung function; lead → anaemia, neurotoxicity in children; PM₂.₅ → enters lungs and blood, CVD</td>\n</tr>\n<tr>\n<td><strong>Vulnerable groups</strong></td>\n<td>Children, elderly, pregnant women (low birth weight, preterm birth), people with heart and lung disease</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Social and economic effects</strong></p>\n<ol>\n<li>Damage to plants and crops; reduced yield.</li>\n<li>Harm to animals.</li>\n<li>Corrosion and soiling of buildings, metals, monuments.</li>\n<li>Reduced visibility → accidents, flight delays.</li>\n<li>Loss of working days; health-care costs.</li>\n</ol>\n<p><strong>C. Environmental effects</strong></p>\n<p>Acid rain; photochemical smog; ozone layer depletion (CFCs); global warming (CO₂, methane, black carbon).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.222","n":222,"part":4,"topic":"Air Pollution","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the impacts of indoor air pollution.</p>","a":"<p><strong>Indoor (household) air pollution</strong></p>\n<p>Pollution of air inside homes, schools and workplaces, mainly from burning solid fuels for cooking and heating in poorly ventilated kitchens.</p>\n<p><strong>Sources</strong></p>\n<p>Biomass fuels (wood, crop residue, cow dung), coal, kerosene; tobacco smoke; mosquito coils; incense; building materials (asbestos, formaldehyde); dampness and moulds; radon; cleaning chemicals.</p>\n<p><strong>Impacts on health</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Effects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Children</strong></td>\n<td>Acute respiratory infections and <strong>pneumonia</strong> (leading cause of under-5 deaths); otitis media; reduced lung growth</td>\n</tr>\n<tr>\n<td><strong>Women</strong> (cooks)</td>\n<td><strong>COPD</strong>, chronic bronchitis, lung cancer (coal), cataract, headache, eye irritation</td>\n</tr>\n<tr>\n<td><strong>Pregnancy</strong></td>\n<td>Low birth weight, stillbirth, preterm birth</td>\n</tr>\n<tr>\n<td><strong>All</strong></td>\n<td>TB, asthma, ischaemic heart disease, stroke</td>\n</tr>\n<tr>\n<td><strong>Acute</strong></td>\n<td>CO poisoning, burns, kerosene poisoning in children</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other impacts</strong></p>\n<ol>\n<li>Time lost collecting fuel; drudgery for women and girls.</li>\n<li>Deforestation; contribution to climate change (black carbon).</li>\n<li>Economic loss from illness.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.223","n":223,"part":4,"topic":"Air Pollution","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the tools for monitoring air pollution.</p>","a":"<p><strong>Tools for monitoring air pollution</strong></p>\n<p><strong>A. Classical methods (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Tool / index</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Sulphur dioxide</strong> measurement (lead peroxide candle; chemical methods)</td>\n<td>SO₂ concentration</td>\n</tr>\n<tr>\n<td><strong>Smoke or soiling index</strong></td>\n<td>Darkening of filter paper by smoke</td>\n</tr>\n<tr>\n<td><strong>Grit and dust measurement</strong> (deposit gauge)</td>\n<td>Settleable particles</td>\n</tr>\n<tr>\n<td><strong>Coefficient of haze</strong></td>\n<td>Light transmission through filtered air</td>\n</tr>\n<tr>\n<td><strong>Air pollution index</strong></td>\n<td>Combined value from several pollutants</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Modern methods</strong></p>\n<ol>\n<li><strong>Continuous Air Monitoring Stations (CAMS)</strong>: automatic analysers for PM₂.₅, PM₁₀, SO₂, NO₂, CO, O₃ (Bangladesh Department of Environment).</li>\n<li><strong>High-volume and low-volume samplers</strong> for particulate matter (gravimetric).</li>\n<li><strong>Air Quality Index (AQI)</strong>: converts pollutant levels into colour-coded categories for public warning.</li>\n<li><strong>Low-cost sensors</strong> and online platforms.</li>\n<li><strong>Satellite remote sensing</strong> (aerosol optical depth, NO₂).</li>\n<li><strong>Personal exposure monitors</strong> (indoor air, workers).</li>\n<li><strong>Biomonitoring</strong>: blood lead, carboxyhaemoglobin, lichens as bio-indicators.</li>\n<li><strong>Health surveillance</strong>: hospital visits for asthma, COPD during high pollution days.</li>\n</ol>\n<p><strong>Uses</strong></p>\n<p>Compare with standards (WHO AQG 2021, national standards); warn the public; evaluate control measures.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.224","n":224,"part":4,"topic":"Air Pollution","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the air pollution of Dhaka city.</p>","a":"<p><strong>Air pollution in Dhaka city</strong></p>\n<p>Dhaka is among the most polluted cities in the world; levels of <strong>PM₂.₅</strong> many times the WHO guideline (annual 5 µg/m³), worst in the <strong>dry season (November–March)</strong>.</p>\n<p><strong>Main sources</strong></p>\n<ol>\n<li><strong>Brick kilns</strong> around the city (dry season).</li>\n<li><strong>Vehicle emissions</strong>: old, poorly maintained buses and trucks; diesel; traffic congestion.</li>\n<li><strong>Construction and road dust</strong>: unpaved roads, open building sites, metro and flyover works, digging.</li>\n<li><strong>Industrial emissions</strong>: steel re-rolling, chemical and textile units.</li>\n<li><strong>Open burning</strong> of waste and biomass.</li>\n<li><strong>Trans-boundary pollution</strong> from neighbouring regions in winter.</li>\n<li>Household fuel use in slums.</li>\n</ol>\n<p><strong>Contributing factors</strong></p>\n<p>Rapid unplanned urbanisation; high population density; weak enforcement; temperature inversion and low wind in winter.</p>\n<p><strong>Health impact</strong></p>\n<p>Respiratory infections, asthma, COPD, lung cancer, heart disease, stroke; reduced life expectancy; worst in children, elderly and outdoor workers.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO Global Air Quality Guidelines, 2021.</p>"},{"id":"DU.225","n":225,"part":4,"topic":"Air Pollution","stars":3,"years":["22Nov","14Ja","12Ja"],"colleges":"DMC (2nd Assess C3); ShSMC (2nd Term B2)","asked":"measures to control air pollution in Dhaka / how air pollution can be prevented according to WHO","note":"","kind":"","sub":"","q":"<p>How can air pollution be prevented / controlled (also: in Dhaka city; WHO strategy)?</p>","a":"<p><strong>Prevention and control of air pollution (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Principle</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Containment</strong></td>\n<td>Prevent escape of pollutants: filters, electrostatic precipitators, scrubbers, closed processes</td>\n</tr>\n<tr>\n<td><strong>2. Replacement</strong></td>\n<td>Change process or fuel: unleaded petrol, CNG/LPG, electric vehicles, cleaner technology</td>\n</tr>\n<tr>\n<td><strong>3. Dilution</strong></td>\n<td>Green belts, tall chimneys, zoning of industries away from residential areas</td>\n</tr>\n<tr>\n<td><strong>4. Legislation</strong></td>\n<td>Air quality standards; emission limits; vehicle fitness tests; licensing</td>\n</tr>\n<tr>\n<td><strong>5. International action</strong></td>\n<td>WHO air quality guidelines; monitoring networks; climate agreements</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Control in Dhaka city</strong></p>\n<ol>\n<li><strong>Brick kilns</strong>: replace old kilns with cleaner technology (zigzag, hybrid Hoffmann); promote hollow and concrete blocks; relocate kilns away from city.</li>\n<li><strong>Vehicles</strong>: phase out old and unfit vehicles; emission testing; CNG and electric public transport; mass transit (metro rail, BRT); traffic management.</li>\n<li><strong>Construction dust</strong>: cover sites and materials; water spraying; finish road works quickly; pave roads; street cleaning.</li>\n<li><strong>Industry</strong>: emission control devices; enforcement by Department of Environment.</li>\n<li><strong>No open burning</strong> of waste; proper solid waste management.</li>\n<li><strong>Urban greening</strong>: trees, parks.</li>\n<li><strong>Monitoring</strong>: CAMS, public AQI alerts; health advisories (masks, limit outdoor activity).</li>\n<li><strong>Laws</strong>: Environment Conservation Act 1995; Air Pollution (Control) Rules 2022.</li>\n<li><strong>Household</strong>: clean cooking fuels.</li>\n<li><strong>Regional cooperation</strong> on trans-boundary pollution.</li>\n</ol>\n<p><strong>WHO strategy</strong></p>\n<p>Global Air Quality Guidelines (2021); WHO road map on health and air pollution; promote clean household energy, sustainable transport, monitoring and health-sector advocacy.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO Global Air Quality Guidelines, 2021.</p>"},{"id":"DU.226","n":226,"part":4,"topic":"Air Pollution","stars":0,"years":[],"colleges":"DMC (2nd Assess C3)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the components of air quality?</p>","a":"<p><strong>Components of air quality</strong></p>\n<p><strong>A. Normal composition of air (dry, by volume)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Gas</th>\n<th>Percentage</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nitrogen</td>\n<td>~78%</td>\n</tr>\n<tr>\n<td>Oxygen</td>\n<td>~21%</td>\n</tr>\n<tr>\n<td>Argon</td>\n<td>~0.93%</td>\n</tr>\n<tr>\n<td>Carbon dioxide</td>\n<td>~0.04%</td>\n</tr>\n<tr>\n<td>Others (neon, helium, hydrogen, ozone)</td>\n<td>Traces</td>\n</tr>\n<tr>\n<td>Water vapour</td>\n<td>Variable</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Physical (thermal comfort) components</strong></p>\n<ol>\n<li>Air temperature</li>\n<li>Humidity</li>\n<li>Air movement (velocity)</li>\n<li>Radiation (mean radiant temperature)<br />\nIndices: corrected effective temperature, predicted 4-hour sweat rate.</li>\n</ol>\n<p><strong>C. Purity (pollutant) components</strong></p>\n<ol>\n<li>Particulate matter (PM₂.₅, PM₁₀)</li>\n<li>Gases: CO, SO₂, NO₂, ozone</li>\n<li>Lead and other metals</li>\n<li>Volatile organic compounds</li>\n<li>Biological agents: bacteria, viruses, pollen, moulds</li>\n<li>Odour</li>\n</ol>\n<p><strong>D. Ventilation</strong></p>\n<p>Adequate fresh air supply and removal of contaminated air (air changes per hour).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.227","n":227,"part":4,"topic":"Air Pollution","stars":0,"years":[],"colleges":"SSMC (2nd Term D2)","asked":"","note":"","kind":"","sub":"","q":"<p>Name the major air pollutants.</p>","a":"<p><strong>Major air pollutants</strong></p>\n<table>\n<thead>\n<tr>\n<th>Pollutant</th>\n<th>Main sources</th>\n<th>Health effects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Particulate matter (PM₂.₅, PM₁₀)</strong>, smoke, soot</td>\n<td>Vehicles, brick kilns, construction, burning</td>\n<td>Respiratory and heart disease, lung cancer</td>\n</tr>\n<tr>\n<td><strong>Carbon monoxide (CO)</strong></td>\n<td>Incomplete combustion; vehicles, stoves</td>\n<td>Carboxyhaemoglobin, hypoxia, death</td>\n</tr>\n<tr>\n<td><strong>Sulphur dioxide (SO₂)</strong></td>\n<td>Coal and oil burning, industry, kilns</td>\n<td>Bronchospasm, acid rain</td>\n</tr>\n<tr>\n<td><strong>Nitrogen oxides (NO, NO₂)</strong></td>\n<td>Vehicles, power plants</td>\n<td>Airway irritation, smog</td>\n</tr>\n<tr>\n<td><strong>Ozone (O₃)</strong> (secondary)</td>\n<td>Sunlight + NOx + hydrocarbons</td>\n<td>Reduced lung function, asthma</td>\n</tr>\n<tr>\n<td><strong>Hydrocarbons / VOCs</strong> (benzene)</td>\n<td>Vehicles, solvents</td>\n<td>Cancer, smog formation</td>\n</tr>\n<tr>\n<td><strong>Lead</strong></td>\n<td>Leaded fuel (past), industry, batteries</td>\n<td>Anaemia, neurotoxicity in children</td>\n</tr>\n<tr>\n<td>Fluorides</td>\n<td>Aluminium, fertiliser industries</td>\n<td>Fluorosis</td>\n</tr>\n<tr>\n<td>Other metals (cadmium, arsenic, mercury)</td>\n<td>Industry</td>\n<td>Organ toxicity, cancer</td>\n</tr>\n<tr>\n<td>Biological (pollen, spores, microbes)</td>\n<td>Plants, waste</td>\n<td>Allergy, infections</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Criteria pollutants (WHO / national standards)</strong></p>\n<p>PM₂.₅, PM₁₀, O₃, NO₂, SO₂, CO (and lead).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.228","n":228,"part":4,"topic":"Air Pollution","stars":0,"years":[],"colleges":"ShSMC (2nd Term B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist three important sources of indoor air pollution in our country.</p>","a":"<p><strong>Three important sources of indoor air pollution in Bangladesh</strong></p>\n<ol>\n<li><strong>Burning of solid biomass fuels</strong> (wood, crop residues, cow-dung cakes, coal) for cooking in poorly ventilated kitchens: smoke, PM₂.₅, CO.</li>\n<li><strong>Tobacco smoking</strong> indoors (second-hand smoke).</li>\n<li><strong>Mosquito coils</strong> and kerosene lamps or stoves.</li>\n</ol>\n<p><strong>Other sources</strong></p>\n<p>Incense; cooking oil fumes; dampness and moulds; building materials and paints; cleaning chemicals; asbestos; poor ventilation in crowded slums.</p>\n<p><strong>Most affected</strong></p>\n<p>Women who cook, and young children kept near the stove → pneumonia, COPD, low birth weight.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.229","n":229,"part":4,"topic":"Ventilation & Noise","stars":0,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Categorize ventilation.</p>","a":"<p><strong>Ventilation</strong></p>\n<p>Replacement of vitiated (used) air by fresh outdoor air, to maintain comfort and remove heat, moisture, odours and contaminants.</p>\n<p><strong>Categories</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Mechanism / methods</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>A. Natural ventilation</strong></td>\n<td></td>\n</tr>\n<tr>\n<td>1. Wind (perflation)</td>\n<td>Wind blows through openings (doors, windows); <strong>cross-ventilation</strong> through opposite openings</td>\n</tr>\n<tr>\n<td>2. Diffusion</td>\n<td>Slow passage of air through openings and porous walls</td>\n</tr>\n<tr>\n<td>3. Inequality of temperature (stack effect)</td>\n<td>Warm air rises and leaves through high openings; cool air enters low</td>\n</tr>\n<tr>\n<td><strong>B. Artificial (mechanical) ventilation</strong></td>\n<td></td>\n</tr>\n<tr>\n<td>1. Exhaust (extraction) ventilation</td>\n<td>Fans remove vitiated air; fresh air enters by openings (kitchens, toilets, factories)</td>\n</tr>\n<tr>\n<td>2. Plenum (supply / propulsion) ventilation</td>\n<td>Fresh air blown in; foul air escapes by vents</td>\n</tr>\n<tr>\n<td>3. Balanced ventilation</td>\n<td>Combination of supply and exhaust</td>\n</tr>\n<tr>\n<td>4. Air conditioning</td>\n<td>Controls temperature, humidity, air movement and purity</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Standards (Park)</strong></p>\n<p>Air change: 2–3 per hour in living rooms (more in workplaces); window area at least 1/10 of floor area (doors + windows ~2/5); adequate cubic space per person.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.230","n":230,"part":4,"topic":"Ventilation & Noise","stars":0,"years":["06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Describe the types of artificial ventilation.</p>","a":"<p><strong>Types of artificial (mechanical) ventilation</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Description</th>\n<th>Uses</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Exhaust (extraction) ventilation</strong></td>\n<td>Electric fans or blowers draw out vitiated air; fresh air enters through doors, windows and inlets</td>\n<td>Kitchens, toilets, factories, laboratories (local exhaust hoods over dust or fumes)</td>\n</tr>\n<tr>\n<td><strong>2. Plenum (supply / propulsion) ventilation</strong></td>\n<td>Fresh air (often filtered, cooled or heated) blown in by fans; used air escapes through outlets</td>\n<td>Theatres, large halls, mines, operation theatres (positive pressure)</td>\n</tr>\n<tr>\n<td><strong>3. Balanced ventilation</strong></td>\n<td>Combination of supply and exhaust systems, matched to keep correct pressure</td>\n<td>Large buildings, hospitals, isolation rooms (negative pressure for TB/airborne infections)</td>\n</tr>\n<tr>\n<td><strong>4. Air conditioning</strong></td>\n<td>Controls temperature, humidity, air movement and air purity (filtration) simultaneously</td>\n<td>Hospitals, offices, ICUs, cinemas</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other devices</strong></p>\n<p>Ceiling and table fans (air movement only; no fresh air exchange); air coolers; HEPA filters and air purifiers.</p>\n<p><strong>Advantages</strong></p>\n<p>Independent of wind and temperature; controllable; filtration possible.</p>\n<p><strong>Disadvantages</strong></p>\n<p>Cost; power needed; noise; poor maintenance can spread infection (Legionella).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.231","n":231,"part":4,"topic":"Ventilation & Noise","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Illustrate the simplest system of ventilating a small dwelling.</p>","a":"<p><strong>Simplest system: natural cross-ventilation</strong></p>\n<p>Openings (windows / doors) on <strong>opposite walls</strong> + <strong>ventilators</strong> high on the walls near the ceiling.</p>\n<p><strong>Diagram (section of a room)</strong></p>\n<pre><code>   Outlet ventilator (high, near ceiling) → warm, used air out\n  ┌──────────────────────────────┐\n  │ ▒▒                       ▒▒  │\n  │                              │\n  │  ← fresh air      warm air ↑ │\n  │                              │\nWindow ▶   →  →  →  →  →  →    ◀ Window (opposite wall)\n  │  (inlet, lower level)        │\n  └──────────────────────────────┘\n</code></pre>\n<p>Fresh air enters through the lower window on the windward side → crosses the room → warm, used air rises and leaves through high ventilators and the opposite window.</p>\n<p><strong>Principles</strong></p>\n<ol>\n<li><strong>Perflation</strong>: wind through opposite openings.</li>\n<li><strong>Stack effect</strong>: warm air rises and escapes at the top; cool air enters below.</li>\n<li>Inlets low, outlets high.</li>\n<li>Openings unobstructed; window area at least 1/10 of floor area.</li>\n</ol>\n<p><strong>Advantages</strong></p>\n<p>Cheap, no power needed, simple; suits rural and low-income homes in Bangladesh.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.232","n":232,"part":4,"topic":"Ventilation & Noise","stars":2,"years":["22Nov","22M","21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write what you know about noise / mention the sources of noise.</p>","a":"<p><strong>Noise</strong></p>\n<p><strong>Wrong sound, in the wrong place, at the wrong time</strong>; any unwanted sound that annoys or harms.</p>\n<p><strong>Properties</strong></p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Unit</th>\n<th>Note</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Intensity (loudness)</td>\n<td>Decibel (dB)</td>\n<td>Logarithmic; +10 dB ≈ 10 times intensity</td>\n</tr>\n<tr>\n<td>Frequency (pitch)</td>\n<td>Hertz (Hz)</td>\n<td>Human hearing 20–20,000 Hz; most sensitive 2,000–5,000 Hz</td>\n</tr>\n<tr>\n<td>Duration</td>\n<td>Time</td>\n<td>Longer exposure → more damage</td>\n</tr>\n</tbody>\n</table>\n<p>Hearing damage risk: prolonged exposure <strong>above 85 dB(A)</strong> (8 hours/day).</p>\n<p><strong>Sources of noise</strong></p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Traffic</td>\n<td>Horns (hydraulic horns), engines, buses, motorcycles, trains</td>\n</tr>\n<tr>\n<td>Industry</td>\n<td>Machines, generators, looms, presses, metal workshops</td>\n</tr>\n<tr>\n<td>Construction</td>\n<td>Pile drivers, drills, mixers</td>\n</tr>\n<tr>\n<td>Aircraft</td>\n<td>Airports, flight paths</td>\n</tr>\n<tr>\n<td>Social / community</td>\n<td>Loudspeakers and microphones (<em>miking</em>), festivals, firecrackers, weddings, political rallies</td>\n</tr>\n<tr>\n<td>Domestic</td>\n<td>Television, music, appliances, generators</td>\n</tr>\n<tr>\n<td>Commercial</td>\n<td>Markets, shops with speakers</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Typical levels</strong></p>\n<p>Whisper ~30 dB; conversation ~60 dB; heavy traffic ~85–90 dB; hydraulic horn 100+ dB; jet engine ~140 dB.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.233","n":233,"part":4,"topic":"Ventilation & Noise","stars":2,"years":["24Nov","22M","12Ja","11Ja"],"colleges":"DMC (2nd Assess A4)","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the effects of noise pollution on health.</p>","a":"<p><strong>Effects of noise pollution on health</strong></p>\n<p><strong>A. Auditory effects</strong></p>\n<ol>\n<li><strong>Auditory fatigue</strong> (temporary threshold shift): above ~90 dB, recovers with rest.</li>\n<li><strong>Noise-induced hearing loss</strong> (permanent threshold shift): prolonged exposure &gt;85 dB; first at <strong>4,000 Hz</strong> (&quot;4 kHz notch&quot;); irreversible.</li>\n<li><strong>Acoustic trauma</strong>: sudden very loud noise (&gt;140 dB, blasts) → ruptured eardrum.</li>\n<li><strong>Tinnitus</strong>.</li>\n</ol>\n<p><strong>B. Non-auditory effects</strong></p>\n<table>\n<thead>\n<tr>\n<th>Effect</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Interference with speech</td>\n<td>Communication difficulty; accidents from missed warnings</td>\n</tr>\n<tr>\n<td>Annoyance</td>\n<td>Irritation, anger</td>\n</tr>\n<tr>\n<td>Sleep disturbance</td>\n<td>Insomnia, fatigue</td>\n</tr>\n<tr>\n<td>Reduced efficiency</td>\n<td>Poor concentration and work output; more errors</td>\n</tr>\n<tr>\n<td>Physiological</td>\n<td>Rise in BP and heart rate, hypertension, CVD, headache, raised intracranial pressure, increased sweating, nausea, vertigo</td>\n</tr>\n<tr>\n<td>Psychological</td>\n<td>Stress, anxiety, neurosis, aggression</td>\n</tr>\n<tr>\n<td>Children</td>\n<td>Impaired learning and reading; delayed speech</td>\n</tr>\n<tr>\n<td>Pregnancy</td>\n<td>Possible low birth weight with high exposure</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Vulnerable groups</strong></p>\n<p>Traffic police, drivers, factory and construction workers, children, elderly, patients in hospitals.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Occupational Health).</p>"},{"id":"DU.234","n":234,"part":4,"topic":"Ventilation & Noise","stars":0,"years":[],"colleges":"DMC (2nd Assess A4)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the noise control measures in Dhaka city.</p>","a":"<p><strong>Noise control measures in Dhaka city</strong></p>\n<p><strong>A. Legislation and enforcement</strong></p>\n<ol>\n<li><strong>Noise Pollution (Control) Rules 2006</strong>: zone-wise day and night limits (silent, residential, mixed, commercial, industrial zones).</li>\n<li><strong>Silent zones</strong> around hospitals, schools, offices and courts; no horns.</li>\n<li><strong>Ban on hydraulic horns</strong>; mobile courts and fines.</li>\n<li>Permits and time limits for loudspeakers and construction at night.</li>\n</ol>\n<p><strong>B. At the source</strong></p>\n<ol>\n<li>Vehicle fitness checks; silencers; ban on old noisy vehicles.</li>\n<li>Traffic management to reduce congestion and honking.</li>\n<li>Low-noise machinery; enclosures for generators and industrial machines.</li>\n<li>Construction work only in daytime; quieter equipment.</li>\n</ol>\n<p><strong>C. Along the path</strong></p>\n<ol>\n<li><strong>Zoning</strong>: industries and workshops away from homes, schools and hospitals.</li>\n<li><strong>Green belts</strong> and trees; noise barriers along highways and flyovers.</li>\n<li>Sound insulation of buildings; double-glazed windows in hospitals.</li>\n</ol>\n<p><strong>D. At the receiver</strong></p>\n<p>Ear plugs and muffs for workers and traffic police; periodic audiometry.</p>\n<p><strong>E. Education and awareness</strong></p>\n<p>Campaigns against unnecessary honking; driver training; community participation; school education.</p>\n<p><strong>F. Monitoring</strong></p>\n<p>Regular noise measurement by Department of Environment; mapping noise hotspots.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.235","n":235,"part":4,"topic":"Ventilation & Noise","stars":0,"years":[],"colleges":"SSMC (2nd Term D5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>During a survey in Chawkbazar, Dhaka, a public health team recorded noise levels above 90 dB from different nearby activities. [2+2+3]</p>\n<ul>\n<li>a) Mention the common sources of noise pollution in this scenario.</li>\n<li>b) Mention the health effects of prolonged exposure to excessive noise.</li>\n<li>c) Mention some control measures that can be implemented by the local authority.</li>\n</ul>","a":"<p><strong>a) Common sources of noise in Chawkbazar (2)</strong></p>\n<ol>\n<li><strong>Traffic</strong>: honking (including hydraulic horns), rickshaw and vehicle congestion, trucks loading goods.</li>\n<li><strong>Small factories and workshops</strong>: plastic, metal, printing and packaging units; machines and generators.</li>\n<li><strong>Commercial activities</strong>: wholesale markets, shop loudspeakers, hawkers.</li>\n<li><strong>Construction</strong> and demolition.</li>\n<li><strong>Social events</strong>: loudspeakers, processions, religious and festive gatherings.</li>\n</ol>\n<p><strong>b) Health effects of prolonged excessive noise (2)</strong></p>\n<ol>\n<li><strong>Noise-induced hearing loss</strong> (permanent; first at 4 kHz); tinnitus.</li>\n<li><strong>Hypertension</strong>, cardiovascular disease, headache.</li>\n<li><strong>Sleep disturbance</strong>, fatigue.</li>\n<li><strong>Stress, irritability, anxiety</strong>, reduced concentration and work efficiency.</li>\n<li><strong>Speech interference</strong> → accidents.</li>\n<li>Impaired learning in children.</li>\n</ol>\n<p><strong>c) Control measures by the local authority (3)</strong></p>\n<ol>\n<li><strong>Enforce Noise Pollution (Control) Rules 2006</strong>: zone limits; fines by mobile courts.</li>\n<li><strong>Ban hydraulic horns</strong>; declare no-horn zones near schools, hospitals and mosques.</li>\n<li><strong>Traffic management</strong>: one-way routes, fixed loading/unloading hours, rickshaw lanes.</li>\n<li><strong>Relocate or zone</strong> noisy factories and workshops away from residential areas; require sound-proof enclosures for generators and machines.</li>\n<li><strong>Regulate loudspeakers</strong> and construction hours (no night work).</li>\n<li><strong>Noise barriers and tree planting</strong>.</li>\n<li><strong>Regular noise monitoring</strong> and public display of levels.</li>\n<li><strong>Awareness campaigns</strong> for drivers, traders and residents; ear protection for exposed workers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.236","n":236,"part":4,"topic":"Radiation","stars":0,"years":["05M","04Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the sources of radiation exposure.</p>","a":"<p><strong>Sources of radiation exposure</strong></p>\n<p><strong>A. Natural (background) sources</strong>: the largest share of human exposure.</p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cosmic rays</td>\n<td>From outer space; higher at high altitude and in air travel</td>\n</tr>\n<tr>\n<td>Terrestrial</td>\n<td>Uranium, thorium, radium in soil and rocks; building materials</td>\n</tr>\n<tr>\n<td><strong>Radon</strong> gas</td>\n<td>From soil into houses; main natural source</td>\n</tr>\n<tr>\n<td>Internal</td>\n<td>Potassium-40, carbon-14 in the body; from food and water</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Man-made (artificial) sources</strong></p>\n<table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Medical</strong> (largest man-made source)</td>\n<td>Diagnostic X-ray, CT scan, fluoroscopy, nuclear medicine (isotope scans), radiotherapy</td>\n</tr>\n<tr>\n<td>Occupational</td>\n<td>Radiology staff, nuclear workers, industrial radiography, miners</td>\n</tr>\n<tr>\n<td>Nuclear power and fuel cycle</td>\n<td>Reactors (e.g., Rooppur nuclear power plant), waste</td>\n</tr>\n<tr>\n<td>Nuclear accidents and weapon tests</td>\n<td>Chernobyl, Fukushima; fallout</td>\n</tr>\n<tr>\n<td>Consumer products</td>\n<td>Luminous dials, smoke detectors, tobacco (polonium-210)</td>\n</tr>\n<tr>\n<td>Industrial and research uses</td>\n<td>Radioisotopes, sterilisation of medical products</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Non-ionising radiation</strong></p>\n<p>Ultraviolet (sun), visible light, infrared, microwaves, radiofrequency (mobile phones), lasers.</p>\n<p><strong>Units</strong></p>\n<p>Absorbed dose: gray (Gy); effective dose: sievert (Sv).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Occupational Health).</p>"},{"id":"DU.237","n":237,"part":4,"topic":"Radiation","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss radiation hazards.</p>","a":"<p><strong>Radiation hazards</strong></p>\n<p><strong>A. Ionising radiation</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Effects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Somatic: immediate (deterministic)</strong></td>\n<td>Acute radiation syndrome; skin erythema, burns, epilation; sterility; cataract; bone marrow depression; fetal death</td>\n</tr>\n<tr>\n<td><strong>Somatic: delayed (stochastic)</strong></td>\n<td><strong>Cancers</strong>: leukaemia, thyroid, breast, lung, bone, skin cancer; shortened life span</td>\n</tr>\n<tr>\n<td><strong>Genetic</strong></td>\n<td>Mutations in germ cells → congenital defects in descendants</td>\n</tr>\n<tr>\n<td><strong>In utero exposure</strong></td>\n<td>Abortion, microcephaly, intellectual disability, growth retardation, childhood cancer</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Deterministic vs stochastic</strong></p>\n<table>\n<thead>\n<tr>\n<th>Deterministic</th>\n<th>Stochastic</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Threshold dose exists</td>\n<td>No threshold</td>\n</tr>\n<tr>\n<td>Severity increases with dose</td>\n<td>Probability increases with dose</td>\n</tr>\n<tr>\n<td>e.g., burns, cataract, ARS</td>\n<td>e.g., cancer, genetic effects</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Factors affecting harm</strong></p>\n<p>Dose, dose rate, type of radiation, part of body exposed, age (children and fetus most sensitive), cell sensitivity (rapidly dividing cells: bone marrow, gut, gonads, skin).</p>\n<p><strong>B. Non-ionising radiation</strong></p>\n<p>UV: sunburn, skin cancer, cataract, snow blindness; infrared: heat cataract (glass-blowers), burns; microwaves: tissue heating; lasers: retinal burns.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Occupational Health).</p>"},{"id":"DU.238","n":238,"part":4,"topic":"Radiation","stars":0,"years":["06S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is acute radiation syndrome?</p>","a":"<p><strong>Acute radiation syndrome (ARS)</strong></p>\n<p>An acute illness caused by <strong>whole-body (or most of body) exposure to a high dose of penetrating ionising radiation (&gt;1 Gy) over a short time</strong> (minutes).</p>\n<p><strong>Phases</strong></p>\n<p>Prodromal (nausea, vomiting, fatigue: minutes–days) → Latent (apparent recovery) → Manifest illness → Recovery or death</p>\n<p><strong>Syndromes by dose</strong></p>\n<table>\n<thead>\n<tr>\n<th>Syndrome</th>\n<th>Dose (approx.)</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Haematopoietic (bone marrow)</strong></td>\n<td>1–8 Gy</td>\n<td>Pancytopenia → infections, bleeding, anaemia; death in weeks without treatment</td>\n</tr>\n<tr>\n<td><strong>Gastrointestinal</strong></td>\n<td>~6–10 Gy or more</td>\n<td>Severe vomiting, bloody diarrhoea, dehydration, sepsis; usually fatal</td>\n</tr>\n<tr>\n<td><strong>Cardiovascular / CNS</strong></td>\n<td>&gt;20–50 Gy</td>\n<td>Confusion, convulsions, coma, shock; death within hours–days</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>LD₅₀/₆₀</strong> (dose killing 50% in 60 days) without treatment: about 3.5–4 Gy.</li>\n<li><strong>Cutaneous radiation injury</strong> often accompanies ARS.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.239","n":239,"part":4,"topic":"Radiation","stars":3,"years":["16Ja","14Ju","12Ja","09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss radiation protection / how can X-ray technicians and radio imaging technologists be protected from radiation hazards?</p>","a":"<p><strong>Principles of radiation protection (ICRP)</strong></p>\n<ol>\n<li><strong>Justification</strong>: every exposure must do more good than harm.</li>\n<li><strong>Optimisation (ALARA)</strong>: dose kept &quot;as low as reasonably achievable&quot;.</li>\n<li><strong>Dose limits</strong>: occupational 20 mSv/year (averaged over 5 years, not &gt;50 mSv in any one year); public 1 mSv/year.</li>\n</ol>\n<p><strong>Protection of X-ray technicians and imaging staff</strong></p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Time</strong></td>\n<td>Minimise time near the source</td>\n</tr>\n<tr>\n<td><strong>Distance</strong></td>\n<td>Stay as far as possible (inverse square law: doubling distance → ¼ dose)</td>\n</tr>\n<tr>\n<td><strong>Shielding</strong></td>\n<td>Lead aprons, thyroid collars, lead gloves, lead-glass screens and goggles; lead/concrete walls and doors of X-ray rooms</td>\n</tr>\n<tr>\n<td><strong>Personal monitoring</strong></td>\n<td>TLD / film badges worn at work; dose records</td>\n</tr>\n<tr>\n<td><strong>Equipment safety</strong></td>\n<td>Collimation, filtration, regular calibration and maintenance; no leakage</td>\n</tr>\n<tr>\n<td><strong>Safe work practice</strong></td>\n<td>Never hold patients during exposure; use immobilisers; control panel behind shield</td>\n</tr>\n<tr>\n<td><strong>Warning signs</strong></td>\n<td>Radiation symbol, red light outside room</td>\n</tr>\n<tr>\n<td><strong>Medical surveillance</strong></td>\n<td>Pre-employment and periodic examination, blood counts, eye check</td>\n</tr>\n<tr>\n<td><strong>Training</strong></td>\n<td>Radiation safety education</td>\n</tr>\n<tr>\n<td><strong>Pregnant staff</strong></td>\n<td>Declare pregnancy; dose to fetus ≤1 mSv for rest of pregnancy</td>\n</tr>\n<tr>\n<td><strong>Regulation</strong></td>\n<td>Licensing and inspection (Bangladesh Atomic Energy Regulatory Authority)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Protection of patients and public</strong></p>\n<p>Avoid unnecessary or repeat X-rays; use lowest dose; gonadal and thyroid shields; ask about pregnancy (ten-day rule); prefer ultrasound or MRI when suitable.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Occupational Health).</p>"},{"id":"DU.240","n":240,"part":4,"topic":"Green House Effect","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List the green house gases.</p>","a":"<p><strong>Greenhouse gases (GHGs)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Gas</th>\n<th>Main sources</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Carbon dioxide (CO₂)</strong></td>\n<td>Burning fossil fuels (coal, oil, gas), deforestation, cement</td>\n</tr>\n<tr>\n<td><strong>Methane (CH₄)</strong></td>\n<td>Rice paddies, livestock, landfills, gas leaks</td>\n</tr>\n<tr>\n<td><strong>Nitrous oxide (N₂O)</strong></td>\n<td>Fertilisers, burning of biomass, industry</td>\n</tr>\n<tr>\n<td><strong>Chlorofluorocarbons (CFCs)</strong>, HCFCs, <strong>HFCs</strong></td>\n<td>Refrigerators, air conditioners, aerosols, foam</td>\n</tr>\n<tr>\n<td><strong>Water vapour</strong></td>\n<td>Natural evaporation (feedback amplifier)</td>\n</tr>\n<tr>\n<td><strong>Tropospheric ozone (O₃)</strong></td>\n<td>Secondary pollutant from vehicles and industry</td>\n</tr>\n<tr>\n<td>Perfluorocarbons (PFCs), sulphur hexafluoride (SF₆)</td>\n<td>Industry, electrical equipment</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.241","n":241,"part":4,"topic":"Green House Effect","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Environmental pollution is challenging for current millennium – discuss.</p>","a":"<p><strong>Environmental pollution: the challenge of this millennium</strong></p>\n<p>Environment-related risks cause about a quarter of global deaths and disease (WHO, 2016 estimate for 2012).</p>\n<p><strong>Types and problems</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Main problems</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Air pollution</td>\n<td>Respiratory and heart disease, lung cancer; Dhaka among the most polluted cities</td>\n</tr>\n<tr>\n<td>Water pollution</td>\n<td>Diarrhoea, cholera, typhoid; arsenic; river pollution (Buriganga, Turag)</td>\n</tr>\n<tr>\n<td>Soil pollution</td>\n<td>Pesticides, heavy metals, industrial waste; enters food chain</td>\n</tr>\n<tr>\n<td>Noise pollution</td>\n<td>Hearing loss, stress, hypertension</td>\n</tr>\n<tr>\n<td>Plastic and solid waste</td>\n<td>Drain blockage, flooding, microplastics</td>\n</tr>\n<tr>\n<td>E-waste and hospital waste</td>\n<td>Toxic metals, infections</td>\n</tr>\n<tr>\n<td>Chemical pollution</td>\n<td>Lead, mercury, pesticides, endocrine disruptors</td>\n</tr>\n<tr>\n<td>Radiation</td>\n<td>Cancer, genetic effects</td>\n</tr>\n<tr>\n<td><strong>Climate change</strong> (GHG pollution)</td>\n<td>Heat, floods, cyclones, sea-level rise, vector-borne disease</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Why it is a challenge</strong></p>\n<ol>\n<li><strong>Rapid urbanisation and industrialisation</strong>; population growth.</li>\n<li><strong>Global and trans-boundary</strong> nature (air, rivers, climate).</li>\n<li><strong>Long-term, cumulative</strong> effects (cancers, climate).</li>\n<li><strong>Poor and vulnerable</strong> suffer most → inequity.</li>\n<li><strong>Weak enforcement</strong> of laws in developing countries.</li>\n<li>Conflicts with economic growth; high cost of control.</li>\n<li>Loss of biodiversity and ecosystem services.</li>\n</ol>\n<p><strong>Responses</strong></p>\n<p>SDGs (3.9: reduce deaths from pollution; 6: water and sanitation; 11: sustainable cities; 13: climate action); Paris Agreement; national laws (Environment Conservation Act 1995); cleaner technologies; waste management; public awareness; intersectoral action.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health); WHO, Preventing disease through healthy environments, 2016.</p>"},{"id":"DU.242","n":242,"part":4,"topic":"Green House Effect","stars":1,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by global warming?</p>","a":"<p><strong>Global warming</strong></p>\n<p>The <strong>rise in the average temperature of the earth's surface and lower atmosphere</strong> due to increased concentration of greenhouse gases (enhanced greenhouse effect) from human activities since the industrial revolution.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.243","n":243,"part":4,"topic":"Green House Effect","stars":3,"years":["15Ja","10Ja"],"colleges":"MMC (2nd Term A3); MuMC (2nd Final D2)","asked":"greenhouse effects in context of Bangladesh / 5 major health and environmental hazards due to climate change","note":"","kind":"","sub":"","q":"<p>Discuss the climate change and its impact on health (in Bangladesh).</p>","a":"<p><strong>Climate change</strong></p>\n<p>Long-term change in temperature, rainfall and weather patterns, mainly due to human-made greenhouse gas emissions. Bangladesh is among the most vulnerable countries: low-lying delta, dense population, poverty.</p>\n<p><strong>Impact on health in Bangladesh</strong></p>\n<table>\n<thead>\n<tr>\n<th>Climate effect</th>\n<th>Health impact</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Heat waves</strong>, rising temperature</td>\n<td>Heat stroke, dehydration, kidney disease, deaths in elderly and outdoor workers; reduced work capacity</td>\n</tr>\n<tr>\n<td><strong>Floods</strong></td>\n<td>Drowning, injuries, diarrhoea, cholera, typhoid, hepatitis E, leptospirosis, skin infections, snake bites</td>\n</tr>\n<tr>\n<td><strong>Cyclones and storm surges</strong> (Sidr 2007, Aila 2009, Amphan 2020)</td>\n<td>Deaths, injuries, destruction of health facilities, displacement</td>\n</tr>\n<tr>\n<td><strong>Sea-level rise and salinity</strong> (coastal areas)</td>\n<td>Unsafe drinking water; hypertension, pre-eclampsia, skin disease; reduced crop yield</td>\n</tr>\n<tr>\n<td><strong>Changing rainfall and temperature</strong></td>\n<td>Spread of <strong>dengue</strong>, chikungunya, malaria to new areas and seasons</td>\n</tr>\n<tr>\n<td><strong>Drought and crop loss</strong></td>\n<td>Food insecurity, malnutrition, stunting</td>\n</tr>\n<tr>\n<td><strong>Displacement and migration</strong></td>\n<td>Urban slums, overcrowding, poor sanitation, TB, mental stress</td>\n</tr>\n<tr>\n<td><strong>Air quality</strong></td>\n<td>Worse air pollution and pollen allergies</td>\n</tr>\n<tr>\n<td><strong>Mental health</strong></td>\n<td>Anxiety, depression, PTSD after disasters</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Greenhouse effect in Bangladesh context</strong></p>\n<p>Bangladesh emits little but suffers most → climate justice.</p>\n<p><strong>Responses</strong></p>\n<ol>\n<li><strong>Adaptation</strong>: cyclone shelters and early warning, flood-resilient WASH, climate-resilient health facilities, disease surveillance, heat action plans, saline-tolerant crops.</li>\n<li><strong>Mitigation</strong>: renewable energy (solar home systems), afforestation (coastal green belt), energy efficiency.</li>\n<li><strong>Policies</strong>: Bangladesh Climate Change Strategy and Action Plan 2009; National Adaptation Plan 2023–2050; health-sector climate strategy.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health; Disaster Management).</p>"},{"id":"DU.244","n":244,"part":4,"topic":"Green House Effect","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the impact of ozone layer depletion on community health.</p>","a":"<p><strong>Ozone layer</strong></p>\n<p>Layer of ozone (O₃) in the <strong>stratosphere</strong> (~15–35 km) that absorbs most harmful <strong>ultraviolet-B (UV-B)</strong> radiation from the sun.</p>\n<p><strong>Depletion</strong></p>\n<p>Caused by <strong>chlorofluorocarbons (CFCs)</strong>, halons, carbon tetrachloride, methyl chloroform, methyl bromide → release chlorine and bromine, which destroy ozone; &quot;ozone hole&quot; over Antarctica.</p>\n<p><strong>Impact on community health</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Effects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Skin</strong></td>\n<td>Sunburn; <strong>skin cancers</strong>: basal cell, squamous cell carcinoma, malignant melanoma; photo-ageing</td>\n</tr>\n<tr>\n<td><strong>Eyes</strong></td>\n<td><strong>Cataract</strong>, photokeratitis (snow blindness), pterygium, ocular cancers</td>\n</tr>\n<tr>\n<td><strong>Immune system</strong></td>\n<td>Suppression → more infections, reduced vaccine response, reactivation of herpes</td>\n</tr>\n<tr>\n<td><strong>Food and nutrition</strong></td>\n<td>Reduced crop yield; damage to marine phytoplankton and fisheries → food insecurity</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>Damage to ecosystems; more ground-level ozone and smog</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.245","n":245,"part":4,"topic":"Green House Effect","stars":0,"years":[],"colleges":"MMC (2nd Term A3)","asked":"","note":"","kind":"","sub":"","q":"<p>What is the greenhouse phenomenon?</p>","a":"<p><strong>Greenhouse phenomenon (greenhouse effect)</strong></p>\n<p>The warming of the earth's surface because certain gases in the atmosphere trap heat, like the glass of a greenhouse.</p>\n<p><strong>Mechanism</strong></p>\n<p>Sun's short-wave radiation passes through atmosphere → absorbed by earth's surface → earth emits long-wave <strong>infrared (heat)</strong> radiation → <strong>greenhouse gases</strong> (CO₂, methane, N₂O, CFCs, water vapour, ozone) absorb and re-radiate it back → lower atmosphere and surface warm up</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.246","n":246,"part":4,"topic":"Housing","stars":0,"years":["10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define housing.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Housing</strong> (residential environment, WHO): not only the physical structure that gives shelter, but also its <strong>immediate surroundings</strong> and the related <strong>community services and facilities</strong> needed for the physical, mental and social well-being of the family and individual.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.247","n":247,"part":4,"topic":"Housing","stars":3,"years":["22Nov","13Ju","10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the features / criteria of healthful housing? &quot;Healthful housing for healthy life&quot; – explain.</p>","a":"<p><strong>Criteria of healthful housing (WHO Expert Committee)</strong></p>\n<p>Healthful housing provides a physical structure that promotes physical, mental and social well-being:</p>\n<ol>\n<li>Meets <strong>fundamental physiological needs</strong>: protection from weather; adequate light, ventilation, temperature; clean air; space for rest and exercise.</li>\n<li>Meets <strong>psychological needs</strong>: privacy, comfort, normal family and community life.</li>\n<li>Protects <strong>against contagion</strong>: safe water, sanitary excreta and refuse disposal, no overcrowding, freedom from vermin.</li>\n<li>Protects <strong>against accidents</strong>: safe structure, fire safety, electrical safety, safe stairs.</li>\n</ol>\n<p><strong>Housing standards (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Standard</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Site</td>\n<td>Elevated, well drained, away from nuisances (dust, smoke, noise, odour)</td>\n</tr>\n<tr>\n<td>Set-back</td>\n<td>Open space around the house for light and air</td>\n</tr>\n<tr>\n<td>Floor</td>\n<td>Impermeable, easy to clean, damp-proof</td>\n</tr>\n<tr>\n<td>Walls</td>\n<td>Strong, smooth, damp-proof, poor heat conductors</td>\n</tr>\n<tr>\n<td>Roof</td>\n<td>Weather-proof; height ≥10 feet</td>\n</tr>\n<tr>\n<td>Rooms</td>\n<td>At least two rooms, with adequate floor space per person</td>\n</tr>\n<tr>\n<td>Windows</td>\n<td>Area at least 1/10 of floor area; doors + windows about 2/5 of floor area</td>\n</tr>\n<tr>\n<td>Lighting</td>\n<td>Adequate daylight in all rooms</td>\n</tr>\n<tr>\n<td>Kitchen</td>\n<td>Separate, with smoke outlet</td>\n</tr>\n<tr>\n<td>Latrine</td>\n<td>Sanitary latrine</td>\n</tr>\n<tr>\n<td>Water supply</td>\n<td>Safe and adequate</td>\n</tr>\n<tr>\n<td>Drainage, waste disposal</td>\n<td>Proper</td>\n</tr>\n<tr>\n<td>Bathing and washing</td>\n<td>Facilities provided</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Overcrowding standards (persons per room)</strong></p>\n<p>1 room: 2 persons; 2 rooms: 3; 3 rooms: 5; 4 rooms: 7; 5+ rooms: 10 (+2 per extra room). Children &lt;1 year not counted; 1–10 years counted as half.</p>\n<p><strong>&quot;Healthful housing for healthy life&quot;</strong></p>\n<p>Good housing prevents infections (TB, diarrhoea, scabies), accidents and mental stress; supports family life, child development and productivity, so it is a basic need for health.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.248","n":248,"part":4,"topic":"Housing","stars":2,"years":["11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the effects of poor housing?</p>","a":"<p><strong>Effects of poor housing</strong></p>\n<p><strong>A. Physical health</strong></p>\n<table>\n<thead>\n<tr>\n<th>Housing defect</th>\n<th>Health effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Overcrowding, poor ventilation</td>\n<td><strong>Tuberculosis</strong>, common cold, influenza, pneumonia, diphtheria, whooping cough, measles, meningococcal meningitis</td>\n</tr>\n<tr>\n<td>Poor sanitation, unsafe water</td>\n<td>Diarrhoea, cholera, typhoid, hepatitis, worm infestations</td>\n</tr>\n<tr>\n<td>Crowding, lack of water</td>\n<td>Skin infections: scabies, impetigo, fungal infections; lice</td>\n</tr>\n<tr>\n<td>Rats and insects</td>\n<td>Plague, leptospirosis, dengue, malaria, filariasis</td>\n</tr>\n<tr>\n<td>Dampness</td>\n<td>Rheumatism, arthritis, respiratory disease, asthma (moulds)</td>\n</tr>\n<tr>\n<td>Indoor smoke</td>\n<td>ARI in children, COPD in women</td>\n</tr>\n<tr>\n<td>Poor lighting, unsafe structure</td>\n<td><strong>Accidents</strong>: falls, burns, fires, electrocution; eye strain</td>\n</tr>\n<tr>\n<td>Lead paint, asbestos</td>\n<td>Poisoning, cancer</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Psychological effects</strong></p>\n<p>Stress, frustration, lack of privacy, depression, mental illness, sleep disturbance.</p>\n<p><strong>C. Social effects</strong></p>\n<p>Juvenile delinquency, alcoholism, drug abuse, crime, prostitution, family breakdown, poor school performance.</p>\n<p><strong>D. Mortality</strong></p>\n<p>Higher morbidity and mortality, especially <strong>infant mortality</strong> and TB deaths, in slums.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.249","n":249,"part":4,"topic":"Disposal of Wastes & Excreta","stars":3,"years":["16Ju","14Ju","10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the possible methods of disposal of refuse / sanitary disposal of refuse at a rural setting.</p>","a":"<p><strong>Methods of refuse disposal (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Description</th>\n<th>Remarks</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Dumping</strong></td>\n<td>Refuse dumped in low-lying land; open dumps</td>\n<td>Cheap but attracts flies, rats, odour, fires, leachate; unsanitary</td>\n</tr>\n<tr>\n<td><strong>2. Controlled tipping / sanitary landfill</strong></td>\n<td>Refuse placed in layers, compacted, covered daily with ~20–30 cm earth; final cover ~60 cm</td>\n<td>Most satisfactory for cities where land is available</td>\n</tr>\n<tr>\n<td><strong>3. Incineration</strong></td>\n<td>Burning in a furnace</td>\n<td>Best for hospital (infectious) waste; costly; air pollution if poorly run</td>\n</tr>\n<tr>\n<td><strong>4. Composting</strong></td>\n<td>Refuse + night soil decomposed by bacteria into humus (manure); <strong>Bangalore method</strong> (anaerobic, in trenches) or mechanical composting</td>\n<td>Gives manure; suits Indian/Bangladeshi refuse rich in organic matter</td>\n</tr>\n<tr>\n<td><strong>5. Manure pits</strong></td>\n<td>Rural households throw refuse and cattle dung into pits; covered with earth after each day</td>\n<td>Manure ready in 5–6 months</td>\n</tr>\n<tr>\n<td><strong>6. Burial</strong></td>\n<td>Small amounts buried in trenches and covered</td>\n<td>Small camps, villages</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Sanitary disposal at a rural setting</strong></p>\n<ol>\n<li><strong>Manure pits</strong> near the house (away from water sources).</li>\n<li><strong>Composting</strong> of organic waste with cattle dung and night soil.</li>\n<li><strong>Burial</strong> of small quantities.</li>\n<li><strong>Biogas plants</strong> using cattle dung and organic waste.</li>\n<li>Segregation; reuse and recycling (paper, plastic, metal).</li>\n<li>Health education; no throwing waste into ponds, canals or roadsides.</li>\n</ol>\n<p><strong>Modern principles</strong></p>\n<p>3R (reduce, reuse, recycle); source segregation; waste-to-energy.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.250","n":250,"part":4,"topic":"Disposal of Wastes & Excreta","stars":3,"years":["24M","23Nov","20Nov","18M","17Nov","06Ja","05M"],"colleges":"ShSMC (2nd Term B3)","asked":"three health hazards of improper solid waste disposal","note":"","kind":"","sub":"","q":"<p>Mention health hazards due to improper disposal of excreta / solid waste; discuss the extent of health problem.</p>","a":"<p><strong>Health hazards of improper disposal of solid waste</strong></p>\n<ol>\n<li><strong>Fly breeding</strong> → diarrhoea, dysentery, typhoid, cholera, trachoma.</li>\n<li><strong>Rat harbourage</strong> → plague, leptospirosis, murine typhus, rat-bite fever; food loss.</li>\n<li><strong>Mosquito breeding</strong> in discarded containers and tyres → <strong>dengue</strong>, chikungunya.</li>\n<li><strong>Water and soil pollution</strong> by leachate (heavy metals, pathogens, chemicals).</li>\n<li><strong>Air pollution and odour</strong> from decomposition and open burning (dioxins, smoke).</li>\n<li><strong>Drain blockage</strong> (plastics) → waterlogging, urban flooding.</li>\n<li><strong>Injuries and infections</strong> for waste pickers (cuts, needle-stick → HBV, HCV, HIV; tetanus).</li>\n<li>Fire hazard and methane explosions at dumps.</li>\n<li>Aesthetic nuisance; lower quality of life.</li>\n<li>Stray animals; spread of zoonoses.</li>\n</ol>\n<p><strong>Health hazards of improper excreta disposal</strong></p>\n<ol>\n<li><strong>Faeco-oral diseases</strong>: cholera, typhoid, paratyphoid, bacillary and amoebic dysentery, giardiasis, hepatitis A and E, poliomyelitis, rotavirus diarrhoea.</li>\n<li><strong>Worm infestations</strong>: hookworm (through soil), roundworm, whipworm, threadworm, tapeworm.</li>\n<li><strong>Pollution</strong> of water and soil; fly breeding; odour.</li>\n</ol>\n<p><strong>Extent of the problem</strong></p>\n<p>Diarrhoeal diseases and worm infestations remain major causes of child illness and malnutrition; one gram of faeces may carry millions of viruses and bacteria and many parasite eggs; unsafe excreta disposal is a leading environmental cause of disease, especially in slums and flood-prone areas.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.251","n":251,"part":4,"topic":"Disposal of Wastes & Excreta","stars":2,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can disease be carried out by excreta?</p>","a":"<p><strong>Transmission of disease from excreta (&quot;F-diagram&quot;)</strong></p>\n<p>Faeces contain pathogens; they reach a new host through the &quot;<strong>5 Fs</strong>&quot;:</p>\n<table>\n<thead>\n<tr>\n<th>Route</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Fluids (water)</strong></td>\n<td>Contaminated wells and ponds → cholera, typhoid, hepatitis</td>\n</tr>\n<tr>\n<td><strong>Fingers (hands)</strong></td>\n<td>Unwashed hands after defecation → shigellosis, threadworm</td>\n</tr>\n<tr>\n<td><strong>Flies</strong></td>\n<td>Carry faecal matter to food → diarrhoea, typhoid</td>\n</tr>\n<tr>\n<td><strong>Fields (soil)</strong></td>\n<td>Hookworm larvae penetrate bare feet; roundworm eggs on vegetables</td>\n</tr>\n<tr>\n<td><strong>Food</strong></td>\n<td>Contaminated by the above → food poisoning, hepatitis A</td>\n</tr>\n</tbody>\n</table>\n<p>Faeces → (Fluids, Fingers, Flies, Fields) → Food / mouth → New host</p>\n<p><strong>Diseases spread by excreta</strong></p>\n<p>Cholera, typhoid and paratyphoid, bacillary and amoebic dysentery, giardiasis, hepatitis A and E, poliomyelitis, rotavirus diarrhoea, ascariasis, hookworm, trichuriasis, threadworm, taeniasis, schistosomiasis (urine and faeces).</p>\n<p><strong>Prevention</strong></p>\n<p><strong>Sanitation barrier</strong> (sanitary latrine) blocks faeces at source; plus safe water, hand-washing, fly control, food hygiene, wearing footwear.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.252","n":252,"part":4,"topic":"Disposal of Wastes & Excreta","stars":3,"years":["26M","20Nov","17Ja","16Ju","15Ja","14Ja","13Ja","12Ja","10Ja"],"colleges":"SSMC (2nd Term D4)","asked":"","note":"","kind":"","sub":"","q":"<p>What is sanitation barrier? Illustrate / draw and label it; explain its importance in context of rural Bangladesh; how does it prevent disease transmission?</p>","a":"<p><strong>Sanitation barrier</strong></p>\n<p><strong>Segregation of faeces</strong> so that they cannot reach water, hands, flies, soil or food; achieved by a <strong>sanitary latrine</strong>. It breaks the chain of faeco-oral transmission at its <strong>source</strong>.</p>\n<p><strong>Diagram (Park)</strong></p>\n<pre><code>                Water ──┐\n                Hands ──┤\n Faeces ═║ BARRIER ║    Flies ──┼──→ Food → New host → Death / disease\n       (sanitary   ║    Soil  ──┘\n        latrine)   ║\n</code></pre>\n<p>Without the barrier: Faeces → water, fingers, flies, soil → food / mouth → new host.<br />\nWith the barrier: faeces are isolated; all routes are blocked at once.</p>\n<p><strong>How it prevents disease transmission</strong></p>\n<ol>\n<li>Excreta confined in a pit or sealed system → <strong>no access for flies</strong> (water seal).</li>\n<li><strong>No contamination of soil</strong> → no hookworm larvae or worm eggs.</li>\n<li><strong>No contamination of ground and surface water</strong> (latrine ≥15 m from and downhill of water source).</li>\n<li>Reduces <strong>hand contamination</strong> when combined with hand-washing.</li>\n<li>Prevents <strong>food</strong> contamination indirectly.</li>\n</ol>\n<p><strong>Importance in rural Bangladesh</strong></p>\n<ol>\n<li>Diarrhoea, typhoid, hepatitis E and worm infestations remain common, especially after floods.</li>\n<li>High water table and floods make proper latrines vital.</li>\n<li>Large reductions in open defecation have occurred; maintaining and upgrading latrines (hygienic, water-sealed, flood-resilient) is the next step.</li>\n<li>Low-cost <strong>ring-slab water-seal latrines</strong> are available.</li>\n<li>Prevents child stunting linked to repeated infections.</li>\n<li>Combined with safe water and hand-washing (WASH), it is the most effective prevention of faeco-oral disease.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.253","n":253,"part":4,"topic":"Disposal of Wastes & Excreta","stars":1,"years":["10Ja"],"colleges":"SSMC (2nd Term D4)","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the different methods of excreta disposal.</p>","a":"<p><strong>Methods of excreta disposal (Park)</strong></p>\n<p><strong>A. Unsewered areas</strong></p>\n<ol>\n<li><strong>Service-type latrines (conservancy system)</strong>: excreta removed manually by sweepers (unsanitary; being abolished).</li>\n<li><strong>Non-service type (sanitary latrines)</strong>:\n<ul>\n<li>(a) <strong>Bore-hole latrine</strong></li>\n<li>(b) <strong>Dug-well (pit) latrine</strong></li>\n<li>(c) <strong>Water-seal type latrine</strong>: PRAI type, RCA type (Bangladesh: ring-slab latrine, twin-pit pour-flush)</li>\n<li>(d) <strong>Septic tank</strong></li>\n<li>(e) <strong>Aqua privy</strong></li>\n</ul>\n</li>\n<li><strong>Latrines for camps and temporary use</strong>:\n<ul>\n<li>Shallow trench latrine</li>\n<li>Deep trench latrine</li>\n<li>Pit latrine</li>\n<li>Bore-hole latrine</li>\n</ul>\n</li>\n</ol>\n<p><strong>B. Sewered areas</strong></p>\n<p><strong>Water-carriage system</strong> → sewers → <strong>sewage treatment</strong> (primary: screening, grit chamber, sedimentation; secondary: trickling filter or activated sludge; sludge digestion) → safe disposal.</p>\n<p><strong>Other methods</strong></p>\n<p>Composting (night soil with refuse), biogas plants, ecological sanitation (urine-diverting toilets), faecal sludge management for pit and septic-tank contents.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.254","n":254,"part":4,"topic":"Disposal of Wastes & Excreta","stars":3,"years":["17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the advantages of water seal latrine at rural area.</p>","a":"<p><strong>Water-seal latrine</strong></p>\n<p>Pit latrine with a squatting pan connected to a <strong>trap holding water</strong> (water seal ~2 cm deep) that separates the pan from the pit; flushed by pouring water. Bangladesh: <strong>ring-slab latrine</strong>, twin-pit pour-flush.</p>\n<p><strong>Components</strong></p>\n<p>Location (≥15 m from and downhill of water source) → squatting slab → pan → trap (water seal) → connecting pipe → pit (rings) → superstructure.</p>\n<p><strong>Advantages in rural areas</strong></p>\n<ol>\n<li><strong>Fly-proof</strong>: water seal prevents flies reaching excreta → fewer fly-borne diseases.</li>\n<li><strong>Odour-free</strong>: seal blocks smell → people accept and use it.</li>\n<li><strong>Prevents mosquito breeding</strong> in the pit.</li>\n<li><strong>Low cost</strong>: simple materials (concrete rings, slab), locally made.</li>\n<li><strong>Simple to build and maintain</strong>; no daily handling of excreta; no sweeper needed.</li>\n<li><strong>Little water needed</strong>: 1–2 litres per flush (pour-flush).</li>\n<li><strong>Long life</strong> of pit; <strong>twin-pit</strong> design allows alternate use and safe manure.</li>\n<li>Protects <strong>ground water</strong> and soil when properly sited.</li>\n<li><strong>Privacy, dignity and safety</strong> for women and girls.</li>\n<li>Culturally acceptable (squatting, use of water for anal cleansing).</li>\n</ol>\n<p><strong>Limitations</strong></p>\n<p>Needs water; blocked by solid materials; pits may overflow in floods if not raised.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.255","n":255,"part":4,"topic":"Disposal of Wastes & Excreta","stars":3,"years":["18Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the criteria of a sanitary latrine.</p>","a":"<p><strong>Criteria of a sanitary latrine (Park)</strong></p>\n<ol>\n<li>Excreta should <strong>not contaminate ground water</strong>.</li>\n<li>Excreta should <strong>not contaminate surface soil</strong>.</li>\n<li>Excreta should <strong>not contaminate surface water</strong>.</li>\n<li>Excreta should <strong>not be accessible to flies or animals</strong>.</li>\n<li><strong>No handling of fresh excreta</strong>; or, when unavoidable, kept to the minimum.</li>\n<li>Should be <strong>free from odours</strong> and unsightly conditions.</li>\n<li>Method should be <strong>simple and inexpensive</strong> in construction and operation.</li>\n</ol>\n<p><strong>Location criteria</strong></p>\n<ul>\n<li>At least <strong>15 m (50 feet)</strong> from any water source.</li>\n<li><strong>Downhill</strong> or on a lower level than wells.</li>\n<li>Pit bottom above the ground-water level where possible.</li>\n<li>Easily accessible, with privacy and light.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.256","n":256,"part":4,"topic":"Disposal of Wastes & Excreta","stars":0,"years":[],"colleges":"ShSMC (2nd Term B3)","asked":"","note":"","kind":"","sub":"","q":"<p>Describe the advantages of sanitary landfill over open dumping.</p>","a":"<p><strong>Sanitary landfill vs open dumping</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Open dumping</th>\n<th>Sanitary landfill (controlled tipping)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Method</td>\n<td>Waste thrown in open low-lying land</td>\n<td>Waste spread in layers, compacted and <strong>covered daily with earth</strong></td>\n</tr>\n<tr>\n<td>Flies, rats, mosquitoes</td>\n<td>Breed freely</td>\n<td>Controlled by cover</td>\n</tr>\n<tr>\n<td>Odour</td>\n<td>Strong</td>\n<td>Minimal</td>\n</tr>\n<tr>\n<td>Open burning, fires</td>\n<td>Common</td>\n<td>Prevented</td>\n</tr>\n<tr>\n<td>Leachate</td>\n<td>Pollutes ground and surface water</td>\n<td>Controlled by lining, drainage and treatment</td>\n</tr>\n<tr>\n<td>Gas (methane)</td>\n<td>Uncontrolled; fire and explosion risk</td>\n<td>Collected or vented; can generate energy</td>\n</tr>\n<tr>\n<td>Scavenging</td>\n<td>Waste pickers exposed to injury and infection</td>\n<td>Restricted</td>\n</tr>\n<tr>\n<td>Appearance</td>\n<td>Unsightly</td>\n<td>Acceptable; site reclaimed later</td>\n</tr>\n<tr>\n<td>Land use</td>\n<td>Land wasted</td>\n<td>Land reclaimed for parks, playgrounds</td>\n</tr>\n<tr>\n<td>Spread of disease</td>\n<td>High</td>\n<td>Low</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Advantages of sanitary landfill</strong></p>\n<ol>\n<li>Hygienic; prevents vector breeding.</li>\n<li>Protects water and air.</li>\n<li>Relatively cheap and simple where land is available.</li>\n<li>Handles all kinds of non-hazardous waste.</li>\n<li>Reclaims low-lying land.</li>\n<li>Landfill gas can be used as energy.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.257","n":257,"part":5,"topic":"School Health","stars":3,"years":["24M","22Nov","22M","21M","19Nov","16M","08Ju"],"colleges":"DMC (2nd Assess A1)","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the objectives / aims of school health (services).</p>","a":"<p><strong>Objectives of school health services (Park)</strong></p>\n<ol>\n<li><strong>Promotion of positive health</strong>.</li>\n<li><strong>Prevention of diseases</strong>.</li>\n<li><strong>Early diagnosis, treatment and follow-up</strong> of defects and diseases.</li>\n<li><strong>Awakening health consciousness</strong> in children.</li>\n<li><strong>Provision of a healthful school environment</strong>.</li>\n</ol>\n<p><strong>Aspects (components) of school health services</strong></p>\n<ol>\n<li>Health appraisal of school children and school personnel.</li>\n<li>Remedial measures and follow-up.</li>\n<li>Prevention of communicable diseases (immunisation, deworming).</li>\n<li>Healthful school environment.</li>\n<li>Nutritional services (school feeding, IFA).</li>\n<li>First aid and emergency care.</li>\n<li>Mental health.</li>\n<li>Dental health.</li>\n<li>Eye health.</li>\n<li>Health education.</li>\n<li>Education of handicapped children.</li>\n<li>Proper maintenance and use of school health records.</li>\n</ol>\n<p><strong>Importance</strong></p>\n<p>School children form a large, accessible, receptive group; healthy habits formed at school last for life and spread to families (child-to-child).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.258","n":258,"part":5,"topic":"School Health","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the risk of a school health service to rural priorities.</p>","a":"<p><strong>Role (priority) of school health services in rural areas</strong></p>\n<ol>\n<li><strong>Large, accessible group</strong>: most rural children attend primary school → easy to reach for screening, immunisation, deworming.</li>\n<li><strong>High burden of preventable problems</strong>: malnutrition, anaemia, worm infestations, skin and eye infections, dental caries, diarrhoea.</li>\n<li><strong>Few health facilities</strong> nearby → school is a key service point.</li>\n<li><strong>Early detection</strong> of defects (vision, hearing, learning problems) that affect schooling.</li>\n<li><strong>Health education</strong> reaches families through children (child-to-child, child-to-parent).</li>\n<li><strong>Healthy habits</strong> (hand-washing, latrine use, safe water, nutrition) are formed early.</li>\n<li><strong>Adolescent girls</strong>: menstrual hygiene, IFA, Td and HPV vaccination; prevention of child marriage.</li>\n<li><strong>Improves attendance and learning</strong>; reduces dropout.</li>\n<li>Supports <strong>national programmes</strong>: EPI catch-up, deworming, nutrition, vaccination campaigns (MR, TCV, HPV).</li>\n<li>Cost-effective, community-centred.</li>\n</ol>\n<p><strong>Risks / challenges in rural settings</strong></p>\n<p>Shortage of trained staff; poor school WASH facilities; weak follow-up and referral; poverty; lack of teacher training; poor records; low priority in budgets.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.259","n":259,"part":5,"topic":"School Health","stars":3,"years":["20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the criteria of an ideal class room.</p>","a":"<p><strong>Criteria of an ideal classroom (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Standard</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Number of students</td>\n<td>Not more than <strong>40</strong> per class</td>\n</tr>\n<tr>\n<td>Floor space</td>\n<td>At least <strong>10 sq ft (≈1 m²) per student</strong></td>\n</tr>\n<tr>\n<td>Ceiling / wall height</td>\n<td>At least 10 feet</td>\n</tr>\n<tr>\n<td>Windows</td>\n<td>Window area at least <strong>25% of floor area</strong>; good cross-ventilation</td>\n</tr>\n<tr>\n<td>Lighting</td>\n<td>Natural light, preferably from the <strong>left side</strong> (for right-handed writers); no glare</td>\n</tr>\n<tr>\n<td>Colour</td>\n<td>Ceilings white; walls light colour; low reflectance for desks and floors</td>\n</tr>\n<tr>\n<td>Floor</td>\n<td>Impervious, easy to clean, non-slippery</td>\n</tr>\n<tr>\n<td>Furniture</td>\n<td><strong>Individual desks and chairs</strong>; <strong>minus-type desks</strong>; chairs with backrest; size suited to age</td>\n</tr>\n<tr>\n<td>Blackboard</td>\n<td>Non-glare, at suitable height and distance</td>\n</tr>\n<tr>\n<td>Doors</td>\n<td>Open outward; adequate exits for emergencies</td>\n</tr>\n<tr>\n<td>Noise</td>\n<td>Away from busy roads, markets</td>\n</tr>\n<tr>\n<td>Temperature</td>\n<td>Comfortable; fans</td>\n</tr>\n<tr>\n<td>Cleanliness</td>\n<td>Clean, free from dust; dustbins</td>\n</tr>\n</tbody>\n</table>\n<p><strong>School environment links</strong></p>\n<p>Safe drinking water; separate latrines for boys and girls (Park: 1 urinal per 60 and 1 latrine per 100 students); hand-washing facilities; playground.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.260","n":260,"part":5,"topic":"School Health","stars":1,"years":["10Ju","07Ju","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is health appraisal in school health? Explain health appraisal of school children.</p>","a":"<p><strong>Health appraisal</strong></p>\n<p>Assessment of the physical and mental health status of school children (and school personnel) by <strong>periodic medical examination</strong> and <strong>daily observation by teachers</strong>.</p>\n<p><strong>Components</strong></p>\n<p><strong>1. Periodic medical examination</strong></p>\n<ul>\n<li>At school entry, then every 4 years (Park); yearly where possible.</li>\n<li><strong>History</strong>: past illness, immunisation, family history.</li>\n<li><strong>General examination</strong>: anthropometry (height, weight, BMI-for-age), nutritional status, pallor, skin, hair.</li>\n<li><strong>Systemic examination</strong>: heart (murmurs, rheumatic heart disease), lungs, abdomen.</li>\n<li><strong>Special senses</strong>: vision (Snellen's chart), hearing (whisper test, tuning fork), dental check.</li>\n<li><strong>Investigations</strong> as needed: Hb, stool for ova, urine.</li>\n<li><strong>Immunisation status</strong> checked and updated.</li>\n<li><strong>Mental and behavioural</strong> problems, learning difficulties.</li>\n</ul>\n<p><strong>2. Daily morning inspection by the teacher</strong></p>\n<p>Look for: unusual pallor, red or watery eyes, running nose, rash, cough, fever, sores, lice, dirty clothes, drowsiness, unusual behaviour; refer if needed.</p>\n<p><strong>3. Health appraisal of school personnel</strong></p>\n<p>Teachers and staff examined (especially for TB) because they can infect children and affect their mental health.</p>\n<p><strong>4. Records</strong></p>\n<p>Cumulative health record card for each child; follow-up of defects.</p>\n<p><strong>Purpose</strong></p>\n<p>Early detection, treatment and follow-up of defects; prevention of spread of infection; planning school health services; health education opportunity.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.261","n":261,"part":5,"topic":"School Health","stars":3,"years":["25Nov","25M","18Nov","16Ju","16M","14Ja","13Ja","12Ja"],"colleges":"DMC (2nd Assess A1); MMC (2nd Term B3)","asked":"5 criteria of a healthful school environment","note":"","kind":"","sub":"","q":"<p>What do you mean by healthful school environment? Categorize / assess the criteria; write down the measures; how can you ensure it?</p>","a":"<p><strong>Healthful school environment</strong></p>\n<p>The physical, social and emotional conditions of the school that promote the health, safety and learning of children and staff.</p>\n<p><strong>Criteria (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Criteria</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Location</strong></td>\n<td>Central, away from busy roads, markets, factories, noise, smoke</td>\n</tr>\n<tr>\n<td><strong>2. Site</strong></td>\n<td>Elevated, well drained, fenced; enough open space</td>\n</tr>\n<tr>\n<td><strong>3. Structure</strong></td>\n<td>Safe, strong; nursery schools single-storey; walls ≥10 ft high; impervious floor</td>\n</tr>\n<tr>\n<td><strong>4. Classroom</strong></td>\n<td>≤40 students; ≥10 sq ft per student</td>\n</tr>\n<tr>\n<td><strong>5. Furniture</strong></td>\n<td>Individual minus-type desks; chairs with backrest; suited to age</td>\n</tr>\n<tr>\n<td><strong>6. Doors and windows</strong></td>\n<td>Window area ≥25% of floor area; cross-ventilation</td>\n</tr>\n<tr>\n<td><strong>7. Colour</strong></td>\n<td>White ceilings, light-coloured walls</td>\n</tr>\n<tr>\n<td><strong>8. Lighting</strong></td>\n<td>Adequate natural light from the left</td>\n</tr>\n<tr>\n<td><strong>9. Water supply</strong></td>\n<td>Safe, adequate drinking water</td>\n</tr>\n<tr>\n<td><strong>10. Eating facilities</strong></td>\n<td>Clean place for meals; food hygiene</td>\n</tr>\n<tr>\n<td><strong>11. Latrines and urinals</strong></td>\n<td>Separate for boys and girls; 1 urinal per 60 and 1 latrine per 100 students; hand-washing with soap; menstrual hygiene facilities</td>\n</tr>\n<tr>\n<td><strong>12. Playground</strong></td>\n<td>Safe, adequate for physical activity</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Psychosocial environment</strong></p>\n<p>No corporal punishment or bullying; supportive teachers; no tobacco; inclusive of disabled children.</p>\n<p><strong>How to ensure it</strong></p>\n<p>School health committee; regular inspection by school health team; funds for WASH and maintenance; teacher training; student health clubs; community and parent involvement.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.262","n":262,"part":5,"topic":"School Health","stars":3,"years":["22M","18M","14Ja","11Ja","10Ja"],"colleges":"SSMC (2nd Term D3)","asked":"","note":"","kind":"","sub":"","q":"<p>Describe / classify the school desks: types, uses, advantages and importance.</p>","a":"<p><strong>School desks: classification (by horizontal distance between the edge of the seat and the edge of the desk)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Arrangement</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Plus desk</strong></td>\n<td>Edge of desk is <strong>behind</strong> (away from) the front edge of the seat → a gap</td>\n<td>Child must bend forward to write → poor posture, fatigue, backache, spinal curvature (kyphosis, scoliosis), eye strain (book too near)</td>\n</tr>\n<tr>\n<td><strong>Zero desk</strong></td>\n<td>Edge of desk is <strong>vertically above</strong> the edge of the seat</td>\n<td>Better than plus, but child still leans</td>\n</tr>\n<tr>\n<td><strong>Minus desk</strong></td>\n<td>Edge of desk <strong>projects over</strong> the seat</td>\n<td>Child sits erect while writing → <strong>best (recommended)</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Diagram (side view)</strong></p>\n<pre><code> Plus:   desk ▁▁▁        (gap)    ▁▁▁ seat\n Zero:   desk ▁▁▁|▁▁▁ seat  (edges in line)\n Minus:  desk ▁▁▁▁▁▁           (desk overlaps seat)\n              ▁▁▁▁ seat\n</code></pre>\n<p><strong>Desirable features</strong></p>\n<ol>\n<li><strong>Minus</strong> type; <strong>individual</strong> (one seat per child).</li>\n<li>Height matched to child's height (adjustable or graded by class).</li>\n<li>Chair with <strong>backrest</strong> supporting lower back; feet flat on floor.</li>\n<li>Writing surface sloped (~15°) for reading; flat portion for pens.</li>\n<li>Smooth, rounded edges; sturdy.</li>\n</ol>\n<p><strong>Uses / importance</strong></p>\n<p>Correct posture; prevents spinal deformities and backache; reduces eye strain and fatigue; improves attention and learning.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.263","n":263,"part":5,"topic":"School Health","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List the medicolegal importance of school desk.</p>","a":"<p><strong>Medical (and medicolegal) importance of the school desk</strong></p>\n<ol>\n<li><strong>Posture</strong>: wrong desk (plus type, wrong height) forces stooping → <strong>kyphosis, scoliosis, lordosis</strong>, round shoulders.</li>\n<li><strong>Backache and neck pain</strong>; musculoskeletal strain.</li>\n<li><strong>Eye strain</strong> and possible <strong>myopia</strong> (book held too close).</li>\n<li><strong>Fatigue</strong> and poor concentration → poor learning.</li>\n<li><strong>Respiratory and digestive</strong> discomfort from cramped chest and abdomen.</li>\n<li><strong>Injuries</strong> from broken desks or sharp edges.</li>\n<li><strong>Crowding</strong> on shared benches → spread of infections (scabies, lice, respiratory infections).</li>\n</ol>\n<p><strong>Legal / administrative aspects</strong></p>\n<ul>\n<li>Schools are responsible for a <strong>safe and healthful environment</strong>; unsafe furniture causing injury or deformity may lead to complaints or liability.</li>\n<li>Furniture should follow approved <strong>standards</strong> (minus type, individual, size by age) during school inspection and registration.</li>\n<li>School health medical officers record deformities linked to furniture and recommend correction.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.264","n":264,"part":5,"topic":"School Health","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the criteria of an ideal table.</p>","a":"<p><strong>Criteria of an ideal (school) table / desk</strong></p>\n<ol>\n<li><strong>Minus type</strong>: front edge projects slightly over the seat, so the child sits erect.</li>\n<li><strong>Height</strong> suited to the child: top at about elbow level when seated; graded by age or adjustable.</li>\n<li><strong>Writing surface sloped</strong> about 15° (flat strip at top for pens and inkpot).</li>\n<li><strong>Width and depth</strong> enough for a book and notebook (individual table).</li>\n<li><strong>Individual</strong> (one child per table) to avoid crowding and spread of infections.</li>\n<li><strong>Knee room</strong> and foot space under the table.</li>\n<li><strong>Smooth, rounded edges</strong>; no splinters or sharp corners.</li>\n<li><strong>Strong, stable</strong>, easy to clean.</li>\n<li><strong>Non-glare, light-coloured</strong> surface.</li>\n<li>Proper <strong>distance from eyes</strong> (~30–35 cm) when writing.</li>\n<li>Placed so that <strong>light comes from the left</strong>.</li>\n<li>Matched with a <strong>chair with backrest</strong>, feet resting flat on the floor.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.265","n":265,"part":5,"topic":"School Health","stars":3,"years":["16Nov","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is a plus desk? Explain the importance of minus desk.</p>","a":"<p><strong>Plus desk</strong></p>\n<p>A desk in which the <strong>front edge of the desk is behind the front edge of the seat</strong> (positive horizontal distance) → the child must <strong>bend forward</strong> to write.</p>\n<p>Effects: stooping posture, backache, kyphosis/scoliosis, eye strain, fatigue.</p>\n<p><strong>Minus desk</strong></p>\n<p>The <strong>front edge of the desk projects over the seat</strong> (negative horizontal distance).</p>\n<p><strong>Importance of the minus desk</strong></p>\n<ol>\n<li>Child can <strong>sit erect</strong> while reading and writing.</li>\n<li><strong>Prevents spinal deformities</strong>: kyphosis, scoliosis, round shoulders.</li>\n<li><strong>Prevents backache</strong> and neck strain.</li>\n<li>Keeps book at proper <strong>distance from eyes</strong> → less eye strain and myopia risk.</li>\n<li><strong>Less fatigue</strong>, better concentration and learning.</li>\n<li>Allows free chest expansion and comfortable breathing.</li>\n<li>Recommended standard for school furniture (with individual seat and backrest).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.266","n":266,"part":5,"topic":"School Health","stars":3,"years":["26M","25M","22Nov","22M","19Nov","18Nov","17Ja","16Nov","16Ju","05S"],"colleges":"MuMC (2nd Final C2)","asked":"","note":"","kind":"","sub":"","q":"<p>Evaluate the major school health problems / enumerate common health problems and diseases of school children (primary school; in Bangladesh).</p>","a":"<p><strong>Common health problems of school children (Bangladesh)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Problems</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Nutritional</strong></td>\n<td>Stunting, underweight, thinness; <strong>anaemia</strong> (iron deficiency); vitamin A and iodine deficiency; rising overweight and obesity in urban schools</td>\n</tr>\n<tr>\n<td><strong>Infections</strong></td>\n<td><strong>Worm infestations</strong> (roundworm, hookworm); diarrhoea, typhoid, hepatitis A and E; ARI, TB; dengue; measles and other vaccine-preventable diseases</td>\n</tr>\n<tr>\n<td><strong>Skin</strong></td>\n<td>Scabies, pediculosis (lice), impetigo, fungal infections</td>\n</tr>\n<tr>\n<td><strong>Eye</strong></td>\n<td><strong>Refractive errors</strong> (myopia), conjunctivitis, squint, vitamin A deficiency signs</td>\n</tr>\n<tr>\n<td><strong>Ear, nose, throat</strong></td>\n<td>Otitis media, wax, hearing loss, tonsillitis</td>\n</tr>\n<tr>\n<td><strong>Dental</strong></td>\n<td><strong>Dental caries</strong>, gum disease, malocclusion</td>\n</tr>\n<tr>\n<td><strong>Heart</strong></td>\n<td>Rheumatic fever and rheumatic heart disease, congenital heart disease</td>\n</tr>\n<tr>\n<td><strong>Injuries</strong></td>\n<td><strong>Drowning</strong>, road traffic injuries, falls, burns, snake bite</td>\n</tr>\n<tr>\n<td><strong>Mental and behavioural</strong></td>\n<td>Learning disability, ADHD, anxiety, depression, exam stress, bullying, screen addiction</td>\n</tr>\n<tr>\n<td><strong>Adolescent</strong></td>\n<td>Menstrual hygiene problems, child marriage and early pregnancy, substance use (smoking), sexual and reproductive health issues</td>\n</tr>\n<tr>\n<td><strong>Disability</strong></td>\n<td>Visual, hearing, physical and intellectual disabilities</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Commonest in primary schools</strong></p>\n<p>Malnutrition and anaemia, worm infestation, dental caries, skin infections, eye and ear problems, diarrhoea and ARI, injuries.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.267","n":267,"part":5,"topic":"School Health","stars":2,"years":["12Ju","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention role of school teachers in school health service.</p>","a":"<p><strong>Role of school teachers in school health services</strong></p>\n<ol>\n<li><strong>Daily morning inspection</strong> of children: pallor, red eyes, rash, cough, fever, lice, scabies, unusual behaviour → refer.</li>\n<li><strong>Health education</strong>: hygiene, hand-washing, nutrition, dental care, safe water, road safety, menstrual hygiene; integrate into lessons.</li>\n<li><strong>Role model</strong> of healthy behaviour (no smoking, cleanliness, punctuality).</li>\n<li><strong>Healthful school environment</strong>: clean classrooms, latrines, water supply, seating, lighting.</li>\n<li><strong>First aid</strong> and emergency care; keep first-aid box.</li>\n<li><strong>Assist health appraisal</strong>: weigh and measure children, test vision (Snellen's chart), keep records.</li>\n<li><strong>Follow-up</strong> of children with defects; inform parents.</li>\n<li><strong>Immunisation and campaigns</strong>: mobilise children for vaccination (Td, HPV, MR, TCV), deworming, IFA.</li>\n<li><strong>School feeding / nutrition</strong> supervision.</li>\n<li><strong>Mental health</strong>: identify learning, emotional and behavioural problems; prevent bullying; supportive atmosphere.</li>\n<li><strong>Inclusive education</strong> for disabled children.</li>\n<li><strong>Link</strong> between school health team, parents and community; run health clubs.</li>\n<li><strong>Exclusion and readmission</strong> of children with communicable diseases as advised.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.268","n":268,"part":5,"topic":"School Health","stars":3,"years":["21M","08Ja"],"colleges":"SSMC (2nd Term D3)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the duties / role of a school health medical officer?</p>","a":"<p><strong>Duties of a school health medical officer</strong></p>\n<ol>\n<li><strong>Health appraisal</strong>: periodic medical examination of children (at entry and at intervals) and of school staff.</li>\n<li><strong>Treatment and referral</strong> of minor ailments and defects; follow-up (remedial measures).</li>\n<li><strong>Immunisation</strong>: check and complete schedules; school vaccination campaigns.</li>\n<li><strong>Prevention and control of communicable diseases</strong>: surveillance, exclusion and readmission, outbreak control.</li>\n<li><strong>Inspection of the school environment</strong>: buildings, classrooms, furniture, lighting, water, latrines, canteen.</li>\n<li><strong>Nutrition services</strong>: assess nutritional status; supervise school feeding; IFA, deworming.</li>\n<li><strong>Health education</strong> of children, teachers and parents.</li>\n<li><strong>Training of teachers</strong> in daily inspection, first aid and health education.</li>\n<li><strong>First aid and emergency care</strong> arrangements.</li>\n<li><strong>Mental health</strong>: identify behavioural and learning problems; counselling; referral.</li>\n<li><strong>Special services</strong>: dental, eye (vision screening, spectacles), ear.</li>\n<li><strong>Care of handicapped children</strong>; advise on special education.</li>\n<li><strong>Records and reports</strong>: maintain cumulative health records; report to authorities.</li>\n<li><strong>Coordination</strong>: school health committee, parents, local health services.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.269","n":269,"part":5,"topic":"School Health","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention school health programmes of Bangladesh.</p>","a":"<p><strong>School health programmes / activities in Bangladesh</strong></p>\n<ol>\n<li><strong>School health clinics</strong> under DGHS in selected districts: health appraisal, treatment, referral, health education.</li>\n<li><strong>School deworming</strong>: periodic mass deworming of school children (albendazole/mebendazole).</li>\n<li><strong>Immunisation in schools</strong>: Td for adolescent girls; <strong>HPV vaccine</strong> for girls; school-based campaigns (measles-rubella, <strong>typhoid conjugate vaccine</strong>).</li>\n<li><strong>Weekly iron-folic acid</strong> supplementation for adolescent girls.</li>\n<li><strong>School feeding programme</strong> in poverty-prone areas (fortified biscuits / midday meal).</li>\n<li><strong>WASH in schools</strong>: safe water, separate latrines, hand-washing, menstrual hygiene management.</li>\n<li><strong>Health education</strong> in the national curriculum (physical education and health, life skills, adolescent health).</li>\n<li><strong>Vision and dental screening</strong> programmes (with NGOs).</li>\n<li><strong>Adolescent health</strong>: adolescent-friendly health services; school health corners; anti-child-marriage awareness.</li>\n<li><strong>Tobacco-free and drug-free school</strong> initiatives.</li>\n<li><strong>Disaster preparedness</strong> and drowning prevention (swimming lessons by NGOs).</li>\n<li><strong>School mental health</strong> awareness.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.270","n":270,"part":5,"topic":"School Health","stars":3,"years":["18Nov","17Nov","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist the (three) responsibilities of health assistant.</p>","a":"<p><strong>Responsibilities of the Health Assistant (in school health and community)</strong></p>\n<p><strong>Three main responsibilities</strong></p>\n<ol>\n<li><strong>Immunisation</strong>: vaccinate children and adolescent girls (Td, HPV, campaign vaccines); register and track defaulters.</li>\n<li><strong>Health education</strong>: personal hygiene, hand-washing, safe water, sanitation, nutrition, prevention of communicable diseases.</li>\n<li><strong>Surveillance and reporting</strong>: detect and report communicable diseases (measles, AFP, diarrhoea outbreaks) and refer sick children.</li>\n</ol>\n<p><strong>Other responsibilities</strong></p>\n<ol start=\"4\">\n<li>Help <strong>school health appraisal</strong>: weight, height, vision screening; record keeping.</li>\n<li><strong>Deworming</strong> and IFA distribution campaigns.</li>\n<li><strong>Inspection</strong> of school sanitation and water supply; advise on improvement.</li>\n<li><strong>TB and leprosy</strong> case finding; follow-up.</li>\n<li><strong>First aid</strong> and referral to community clinic or UHC.</li>\n<li>Coordinate with teachers and school health committee.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services; Health Care of the Community).</p>"},{"id":"DU.271","n":271,"part":5,"topic":"School Health","stars":3,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What appliances does a school health medical officer need to carry?</p>","a":"<p><strong>Appliances needed by a school health medical officer</strong></p>\n<table>\n<thead>\n<tr>\n<th>Purpose</th>\n<th>Appliances</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Anthropometry</strong></td>\n<td>Weighing scale, height-measuring rod (stadiometer), measuring tape, MUAC tape, growth / BMI-for-age charts</td>\n</tr>\n<tr>\n<td><strong>General examination</strong></td>\n<td>Stethoscope, BP instrument (paediatric cuffs), thermometer, torch, tongue depressors, magnifying glass</td>\n</tr>\n<tr>\n<td><strong>Eye</strong></td>\n<td><strong>Snellen's chart</strong> (or E-chart), pinhole, colour vision (Ishihara) chart</td>\n</tr>\n<tr>\n<td><strong>Ear</strong></td>\n<td>Otoscope, tuning fork (512 Hz), (portable audiometer)</td>\n</tr>\n<tr>\n<td><strong>Dental</strong></td>\n<td>Mouth mirror, probe, gloves</td>\n</tr>\n<tr>\n<td><strong>Laboratory</strong></td>\n<td>Haemoglobinometer (Sahli / digital), urine dipsticks, stool containers</td>\n</tr>\n<tr>\n<td><strong>Immunisation</strong> (if given)</td>\n<td>Vaccine carrier with ice packs, AD syringes, safety box, AEFI kit (adrenaline)</td>\n</tr>\n<tr>\n<td><strong>Drugs</strong></td>\n<td>Deworming tablets, IFA, ORS, paracetamol, antiseptics, skin ointments</td>\n</tr>\n<tr>\n<td><strong>First aid</strong></td>\n<td>First-aid box: bandages, gauze, splints, antiseptic, scissors, gloves</td>\n</tr>\n<tr>\n<td><strong>Records</strong></td>\n<td>Cumulative health record cards, referral slips, registers</td>\n</tr>\n<tr>\n<td><strong>Health education</strong></td>\n<td>Flip charts, posters, models, leaflets</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.272","n":272,"part":5,"topic":"School Health","stars":0,"years":[],"colleges":"MMC (2nd Term B3)","asked":"","note":"","kind":"","sub":"","q":"<p>Name some school health emergencies.</p>","a":"<p><strong>School health emergencies</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Emergencies</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Injuries</strong></td>\n<td>Falls, fractures, sprains, cuts and bleeding, head injury, dental injuries</td>\n</tr>\n<tr>\n<td><strong>Burns and scalds</strong></td>\n<td>Laboratory, kitchen, fireworks</td>\n</tr>\n<tr>\n<td><strong>Fainting (syncope)</strong></td>\n<td>Prolonged standing at assembly, heat, hunger</td>\n</tr>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Convulsions (epilepsy, febrile), <strong>asthma attack</strong>, anaphylaxis (insect sting, food allergy), hypoglycaemia (diabetic child), heat stroke, acute abdominal pain, high fever</td>\n</tr>\n<tr>\n<td><strong>Bites and stings</strong></td>\n<td><strong>Dog bite</strong>, <strong>snake bite</strong>, bee sting</td>\n</tr>\n<tr>\n<td><strong>Foreign bodies</strong></td>\n<td>In eye, ear, nose; choking (airway obstruction)</td>\n</tr>\n<tr>\n<td><strong>Nose bleed (epistaxis)</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Drowning</strong></td>\n<td>Ponds near schools, during excursions</td>\n</tr>\n<tr>\n<td><strong>Poisoning</strong></td>\n<td>Food poisoning, accidental chemical ingestion</td>\n</tr>\n<tr>\n<td><strong>Electric shock</strong></td>\n<td>Faulty wiring</td>\n</tr>\n<tr>\n<td><strong>Mass events</strong></td>\n<td>Mass psychogenic illness, AEFI after school vaccination, fire, earthquake, building collapse</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Preparedness</strong></p>\n<p>Trained teachers in first aid; first-aid box; emergency contact numbers; referral to nearest health facility; safety drills.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (School Health Services).</p>"},{"id":"DU.273","n":273,"part":5,"topic":"Occupational Health","stars":0,"years":["04M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define occupational health.</p>","a":"<p><strong>Definition (Joint ILO/WHO Committee on Occupational Health, 1950; revised 1995)</strong></p>\n<p>Occupational health aims at:</p>\n<ol>\n<li><strong>Promotion and maintenance</strong> of the highest degree of physical, mental and social well-being of workers in all occupations;</li>\n<li><strong>Prevention</strong> of departures from health caused by working conditions;</li>\n<li><strong>Protection</strong> of workers from risks resulting from factors adverse to health;</li>\n<li><strong>Placing and maintaining</strong> the worker in an occupational environment adapted to his physiological and psychological capabilities;<br />\nin short, <strong>the adaptation of work to man and of each man to his job</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.274","n":274,"part":5,"topic":"Occupational Health","stars":3,"years":["25M","18Nov","08Ju"],"colleges":"DMC (2nd Assess A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Define and write down objectives of ergonomics. What is ergonomics?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Ergonomics</strong>: the science of <strong>&quot;fitting the job to the worker&quot;</strong>: designing tasks, tools, equipment, workstations and the work environment to match human physical and mental capabilities and limitations (from Greek <em>ergon</em> = work, <em>nomos</em> = law).</p>\n<p><strong>Objectives</strong></p>\n<ol>\n<li><strong>Fit the job to the worker</strong> (and the worker to the job).</li>\n<li><strong>Improve health and safety</strong>: prevent accidents, musculoskeletal disorders (backache, neck pain, repetitive strain injury), eye strain.</li>\n<li><strong>Reduce fatigue</strong> and physical and mental stress.</li>\n<li><strong>Increase efficiency and productivity</strong>; reduce errors.</li>\n<li><strong>Improve comfort and job satisfaction</strong>; reduce absenteeism and turnover.</li>\n<li><strong>Accommodate</strong> older, disabled and female workers.</li>\n</ol>\n<p><strong>Applications</strong></p>\n<p>Height-adjustable chairs and tables; correct sewing-machine height for garment workers; lifting aids; proper lighting; job rotation and rest breaks; computer workstation design; tool handles suited to hand size.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.275","n":275,"part":5,"topic":"Occupational Health","stars":3,"years":["22Nov"],"colleges":"ShSMC (2nd Term B1)","asked":"three occupational health services available for industrial workers","note":"","kind":"","sub":"","q":"<p>What are the objectives of occupational health services?</p>","a":"<p><strong>Objectives of occupational health services (ILO/WHO)</strong></p>\n<ol>\n<li><strong>Protect workers</strong> against health hazards arising from work or working conditions.</li>\n<li><strong>Adapt work to workers</strong> (and workers to suitable jobs) according to their physical and mental capacity.</li>\n<li>Contribute to the <strong>physical and mental well-being</strong> of workers.</li>\n<li><strong>Prevent occupational diseases and accidents</strong>; early detection.</li>\n<li>Provide <strong>treatment, first aid and emergency care</strong>.</li>\n<li><strong>Rehabilitate</strong> injured or ill workers; return to suitable work.</li>\n<li><strong>Health education</strong> and counselling.</li>\n<li>Advise management on a <strong>safe and healthy environment</strong>.</li>\n<li>Maintain <strong>records</strong> for planning, evaluation and compensation.</li>\n</ol>\n<p><strong>Components (services)</strong></p>\n<ol>\n<li>Pre-placement medical examination.</li>\n<li>Periodic medical examination.</li>\n<li>Medical and health care services (first aid, treatment).</li>\n<li>Notification of occupational diseases.</li>\n<li>Supervision of the working environment.</li>\n<li>Maintenance and analysis of records.</li>\n<li>Health education and counselling.</li>\n</ol>\n<p><strong>Three services commonly available</strong></p>\n<p>Pre-placement examination; periodic medical examination; first aid and emergency treatment.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.276","n":276,"part":5,"topic":"Occupational Health","stars":3,"years":["15Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify occupational diseases caused by physical agents.</p>","a":"<p><strong>Occupational diseases caused by physical agents (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Physical agent</th>\n<th>Diseases / conditions</th>\n<th>Workers at risk</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Heat</strong></td>\n<td>Heat hyperpyrexia (heat stroke), heat exhaustion, heat syncope, heat cramps, burns, prickly heat</td>\n<td>Furnace, foundry, glass, steel, bakery, boiler workers</td>\n</tr>\n<tr>\n<td><strong>Cold</strong></td>\n<td>Chilblains, erythrocyanosis, immersion (trench) foot, frostbite</td>\n<td>Cold storage, fishermen</td>\n</tr>\n<tr>\n<td><strong>Light</strong></td>\n<td>Occupational cataract (infrared), miner's nystagmus (poor light), eye strain, headache, photokeratitis (UV in welding)</td>\n<td>Glass-blowers, welders, miners</td>\n</tr>\n<tr>\n<td><strong>Pressure</strong></td>\n<td>Caisson disease (decompression sickness), air embolism, blast injury</td>\n<td>Divers, tunnel and caisson workers</td>\n</tr>\n<tr>\n<td><strong>Noise</strong></td>\n<td>Occupational deafness (NIHL), tinnitus, stress, hypertension</td>\n<td>Textile, metal, construction workers</td>\n</tr>\n<tr>\n<td><strong>Radiation</strong></td>\n<td>Cancer, leukaemia, aplastic anaemia, sterility, cataract, genetic effects</td>\n<td>Radiology, nuclear workers</td>\n</tr>\n<tr>\n<td><strong>Mechanical factors</strong></td>\n<td>Injuries, accidents, repetitive strain injury</td>\n<td>All industries</td>\n</tr>\n<tr>\n<td><strong>Electricity</strong></td>\n<td>Burns, electric shock</td>\n<td>Electricians</td>\n</tr>\n<tr>\n<td><strong>Vibration</strong></td>\n<td>Vibration white finger (Raynaud's), bone and joint damage</td>\n<td>Pneumatic drill users</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.277","n":277,"part":5,"topic":"Occupational Health","stars":3,"years":["11Ju"],"colleges":"DMC (2nd Assess A3)","asked":"classify occupational hazards with examples","note":"","kind":"","sub":"","q":"<p>List the occupational health hazards.</p>","a":"<p><strong>Classification of occupational hazards (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Hazard</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Physical</strong></td>\n<td>Heat, cold, light, noise, vibration, ultraviolet and ionising radiation, pressure, electricity</td>\n</tr>\n<tr>\n<td><strong>2. Chemical</strong></td>\n<td>(a) <strong>Local action</strong> on skin: dermatitis, eczema, ulcers, cancer (b) <strong>Inhalation</strong>: dusts (silica, coal, asbestos, cotton), gases (simple and chemical asphyxiants, irritant gases), metals (lead, mercury, cadmium, manganese) (c) <strong>Ingestion</strong>: lead, mercury, arsenic, chromium, phosphorus</td>\n</tr>\n<tr>\n<td><strong>3. Biological</strong></td>\n<td>Brucellosis, leptospirosis, anthrax, tetanus, hydatidosis, psittacosis, Q fever, fungal infections, TB, hepatitis B and C, HIV (health workers)</td>\n</tr>\n<tr>\n<td><strong>4. Mechanical</strong></td>\n<td>Accidents and injuries from machines, falls, moving parts</td>\n</tr>\n<tr>\n<td><strong>5. Psychosocial</strong></td>\n<td>Frustration, lack of job satisfaction, insecurity, poor human relations, emotional tension → anxiety, depression, alcoholism, drug abuse, absenteeism, psychosomatic illness (headache, backache, peptic ulcer, hypertension, heart disease)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Also: ergonomic hazards</strong></p>\n<p>Poor posture, repetitive movements, heavy lifting → musculoskeletal disorders.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.278","n":278,"part":5,"topic":"Occupational Health","stars":0,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist biological hazards in an industry.</p>","a":"<p><strong>Biological hazards in industry</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disease</th>\n<th>Source / industry</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Anthrax</strong></td>\n<td>Wool, hair, hide and leather industries, tanneries, bone mills</td>\n</tr>\n<tr>\n<td><strong>Brucellosis</strong></td>\n<td>Dairy, abattoirs, meat processing, veterinary work</td>\n</tr>\n<tr>\n<td><strong>Leptospirosis</strong></td>\n<td>Sewer workers, abattoirs, rice fields, mines (rat urine)</td>\n</tr>\n<tr>\n<td><strong>Tetanus</strong></td>\n<td>Injuries in construction, agriculture, metal work</td>\n</tr>\n<tr>\n<td><strong>Q fever</strong></td>\n<td>Abattoirs, dairy, animal handling</td>\n</tr>\n<tr>\n<td><strong>Psittacosis</strong></td>\n<td>Poultry and bird processing</td>\n</tr>\n<tr>\n<td><strong>Hydatid disease</strong></td>\n<td>Butchers, abattoirs (dogs, sheep)</td>\n</tr>\n<tr>\n<td><strong>Glanders, erysipeloid</strong></td>\n<td>Horse handlers; fish and meat handlers</td>\n</tr>\n<tr>\n<td><strong>Fungal infections</strong> (sporotrichosis, ringworm, candidiasis)</td>\n<td>Wet work, gardening, food industry</td>\n</tr>\n<tr>\n<td><strong>Tuberculosis</strong></td>\n<td>Crowded factories, health care, silica-exposed workers</td>\n</tr>\n<tr>\n<td><strong>Hepatitis B, C, HIV</strong></td>\n<td>Health care, laboratory, waste handlers (needle-stick)</td>\n</tr>\n<tr>\n<td><strong>Rabies</strong></td>\n<td>Veterinary, animal handlers</td>\n</tr>\n<tr>\n<td><strong>Avian influenza, Nipah</strong></td>\n<td>Poultry farms; date-palm sap collectors</td>\n</tr>\n<tr>\n<td>Allergic and toxic reactions to moulds</td>\n<td>Grain and hay handling (farmer's lung), bagasse</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.279","n":279,"part":5,"topic":"Occupational Health","stars":3,"years":["14Ju","10Ju","09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State / discuss health problems and hazards due to (indiscriminate) industrialization.</p>","a":"<p><strong>Health problems due to (indiscriminate) industrialisation (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Problem</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Environmental sanitation</strong></td>\n<td>Water pollution by industrial effluents; air pollution; soil pollution; noise; poor waste disposal</td>\n</tr>\n<tr>\n<td><strong>2. Housing</strong></td>\n<td>Overcrowding, slums and squatter settlements around factories</td>\n</tr>\n<tr>\n<td><strong>3. Communicable diseases</strong></td>\n<td>TB, respiratory infections, diarrhoea, typhoid, STIs and HIV (migrant single workers)</td>\n</tr>\n<tr>\n<td><strong>4. Food sanitation</strong></td>\n<td>Contaminated street food, adulteration, malnutrition</td>\n</tr>\n<tr>\n<td><strong>5. Mental health</strong></td>\n<td>Stress, anxiety, depression, psychosomatic disorders, loss of family support</td>\n</tr>\n<tr>\n<td><strong>6. Accidents</strong></td>\n<td>Industrial accidents, fires, building collapse, road traffic accidents</td>\n</tr>\n<tr>\n<td><strong>7. Social problems</strong></td>\n<td>Alcoholism, drug addiction, gambling, crime, prostitution, juvenile delinquency, family breakdown</td>\n</tr>\n<tr>\n<td><strong>8. Occupational diseases</strong></td>\n<td>Pneumoconioses, lead poisoning, chemical poisoning, NIHL, occupational cancers</td>\n</tr>\n<tr>\n<td><strong>9. Morbidity and mortality</strong></td>\n<td>Increased; vulnerable groups: women, children (child labour), migrants</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Prevention</strong></p>\n<p>Planned industrialisation; zoning; effluent treatment; enforcement of environmental and labour laws; workers' housing and welfare; occupational health services.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.280","n":280,"part":5,"topic":"Occupational Health","stars":3,"years":["21M","15Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate the occupational hazards among industrial workers / garments workers.</p>","a":"<p><strong>Occupational hazards among industrial / garment workers</strong></p>\n<table>\n<thead>\n<tr>\n<th>Hazard</th>\n<th>Examples in garment and other industries</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Physical</strong></td>\n<td>Heat and poor ventilation; noise (sewing and cutting machines); poor lighting → eye strain; electrical hazards; <strong>fire</strong> (locked exits, overcrowding)</td>\n</tr>\n<tr>\n<td><strong>Chemical</strong></td>\n<td>Dyes, bleaches, solvents, formaldehyde → dermatitis, asthma, headache; cotton and fabric dust</td>\n</tr>\n<tr>\n<td><strong>Biological</strong></td>\n<td>TB and respiratory infections (crowding); diarrhoea (unsafe water); UTIs (few toilet breaks)</td>\n</tr>\n<tr>\n<td><strong>Mechanical</strong></td>\n<td>Needle and cutting injuries; machine accidents; <strong>building collapse</strong> (Rana Plaza, 2013); stampedes</td>\n</tr>\n<tr>\n<td><strong>Ergonomic</strong></td>\n<td>Prolonged sitting or standing, repetitive movements → backache, neck and shoulder pain, carpal tunnel syndrome, varicose veins</td>\n</tr>\n<tr>\n<td><strong>Dust</strong></td>\n<td>Cotton dust → <strong>byssinosis</strong>, chronic bronchitis (spinning, weaving)</td>\n</tr>\n<tr>\n<td><strong>Psychosocial</strong></td>\n<td>Long hours, forced overtime, low wages, production pressure, job insecurity, harassment, stress, depression</td>\n</tr>\n<tr>\n<td><strong>Nutritional and reproductive</strong></td>\n<td>Anaemia, malnutrition, menstrual problems, adverse pregnancy outcomes</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.281","n":281,"part":5,"topic":"Occupational Health","stars":3,"years":["26M","25M"],"colleges":"MMC (2nd Term B1)","asked":"occupational hazards encountered by doctors","note":"","kind":"","sub":"","q":"<p>Write down the occupational hazards for healthcare providers / medical practitioners.</p>","a":"<p><strong>Occupational hazards for health-care providers</strong></p>\n<table>\n<thead>\n<tr>\n<th>Hazard</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Biological</strong></td>\n<td><strong>Needle-stick and sharps injuries</strong> → hepatitis B, hepatitis C, HIV; <strong>TB</strong> (including MDR-TB); COVID-19, influenza, measles, varicella; diarrhoeal infections; scabies</td>\n</tr>\n<tr>\n<td><strong>Chemical</strong></td>\n<td>Disinfectants and sterilants (glutaraldehyde, formaldehyde, chlorine) → dermatitis, asthma; <strong>latex allergy</strong>; anaesthetic gases; cytotoxic drugs; mercury</td>\n</tr>\n<tr>\n<td><strong>Physical</strong></td>\n<td>Ionising radiation (X-ray, fluoroscopy, nuclear medicine); lasers; noise; electrical hazards; slips and falls</td>\n</tr>\n<tr>\n<td><strong>Ergonomic</strong></td>\n<td>Back injury from lifting and moving patients; prolonged standing in surgery; neck strain</td>\n</tr>\n<tr>\n<td><strong>Psychosocial</strong></td>\n<td>Stress, <strong>burnout</strong>, long hours and <strong>night shifts</strong>, sleep deprivation, depression, substance use, suicide; <strong>violence against doctors and nurses</strong>; litigation</td>\n</tr>\n<tr>\n<td><strong>Mechanical</strong></td>\n<td>Cuts from scalpels and broken glass; injuries from equipment</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.282","n":282,"part":5,"topic":"Occupational Health","stars":3,"years":["10Ja","04Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Illustrate psychological hazards of garments female worker.</p>","a":"<p><strong>Psychological hazards of female garment workers</strong></p>\n<p><strong>Causes (stressors)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stressor</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Work pressure</td>\n<td>High production targets, long hours, compulsory overtime, few breaks</td>\n</tr>\n<tr>\n<td>Job insecurity</td>\n<td>Fear of dismissal, irregular wages, factory closures</td>\n</tr>\n<tr>\n<td>Low wages</td>\n<td>Financial strain; poor housing and food</td>\n</tr>\n<tr>\n<td>Harassment</td>\n<td>Verbal abuse, sexual harassment, gender-based violence at work and while commuting</td>\n</tr>\n<tr>\n<td>Double burden</td>\n<td>Factory work + household work + child care</td>\n</tr>\n<tr>\n<td>Lack of maternity protection</td>\n<td>Fear of losing job if pregnant; poor child-care facilities</td>\n</tr>\n<tr>\n<td>Unsafe workplace</td>\n<td>Fear of fire and building collapse (after Rana Plaza, Tazreen)</td>\n</tr>\n<tr>\n<td>Poor living conditions</td>\n<td>Crowded slums, lack of privacy, unsafe water and toilets</td>\n</tr>\n<tr>\n<td>Separation from family</td>\n<td>Rural migrants living alone</td>\n</tr>\n<tr>\n<td>Lack of voice</td>\n<td>Weak trade unions, no grievance mechanism</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Effects</strong></p>\n<ol>\n<li><strong>Stress, anxiety, depression</strong>; sleep disturbance; fatigue.</li>\n<li><strong>Psychosomatic complaints</strong>: headache, backache, abdominal pain, palpitations.</li>\n<li><strong>Post-traumatic stress disorder</strong> after disasters.</li>\n<li>Low self-esteem; frustration; irritability.</li>\n<li>Absenteeism, low productivity, job turnover.</li>\n<li>Family conflict; neglect of children.</li>\n<li>Suicidal ideation in severe cases.</li>\n</ol>\n<p><strong>Prevention</strong></p>\n<p>Reasonable hours and targets; fair wages; anti-harassment committees and policies; safe workplace; crèches and maternity benefits; counselling services; safe transport; welfare and recreation; enforcement of Bangladesh Labour Act.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.283","n":283,"part":5,"topic":"Occupational Health","stars":3,"years":["26M","22Nov","22M","17Nov","14Ja"],"colleges":"DMC (2nd Assess B1); SSMC (2nd Term B3); MMC (2nd Term B1)","asked":"disease spectrum of organic and inorganic dust pneumoconiosis / classify pneumoconiosis / what is pneumoconiosis with examples","note":"","kind":"","sub":"","q":"<p>Define and classify pneumoconiosis; enlist common pneumoconioses; names of organic dust-borne pneumoconiosis.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Pneumoconiosis</strong>: a group of lung diseases caused by <strong>inhalation of dust</strong>, usually at work, with reaction of lung tissue (mostly fibrosis) to the deposited dust.</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dust</th>\n<th>Disease</th>\n<th>Cause / occupation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>A. Inorganic dusts</strong></td>\n<td><strong>Silicosis</strong></td>\n<td>Free silica: stone crushing, mining, quarrying, sand blasting, glass, pottery, foundry</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Anthracosis</strong> (coal workers' pneumoconiosis)</td>\n<td>Coal dust: coal miners</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Asbestosis</strong></td>\n<td>Asbestos: mining, insulation, ship-breaking, brake linings (also mesothelioma, lung cancer)</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Siderosis</strong></td>\n<td>Iron oxide: welders, iron ore workers</td>\n</tr>\n<tr>\n<td></td>\n<td>Berylliosis, stannosis (tin), talcosis, baritosis</td>\n<td>Respective metals and minerals</td>\n</tr>\n<tr>\n<td><strong>B. Organic dusts</strong></td>\n<td><strong>Byssinosis</strong></td>\n<td>Cotton, flax, hemp dust: textile (spinning) workers</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Bagassosis</strong></td>\n<td>Sugarcane bagasse: paper, board industry</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Farmer's lung</strong></td>\n<td>Mouldy hay or grain (thermophilic actinomycetes)</td>\n</tr>\n<tr>\n<td></td>\n<td>Bird fancier's lung, mushroom worker's lung, malt worker's lung, tobacosis</td>\n<td>Respective organic dusts</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Common pneumoconioses</strong>: silicosis, anthracosis, asbestosis, byssinosis.</p>\n<p><strong>Organic dust diseases (names)</strong>: byssinosis, bagassosis, farmer's lung, bird fancier's lung, tobacosis.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.284","n":284,"part":5,"topic":"Occupational Health","stars":3,"years":["26M","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the characteristics of dust particle causing pneumoconiosis / factors related to hazardous effect of dust in the lungs.</p>","a":"<p><strong>Factors / characteristics of dust that decide its harmful effect on the lungs</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Size of particles</strong></td>\n<td>Particles <strong>0.5–3 µm</strong> reach the alveoli and are most dangerous (&quot;respirable dust&quot;); &gt;10 µm are trapped in the nose; 5–10 µm deposited in airways and cleared</td>\n</tr>\n<tr>\n<td><strong>2. Chemical composition</strong></td>\n<td><strong>Free silica</strong> is most fibrogenic; asbestos fibres carcinogenic; coal and iron less harmful</td>\n</tr>\n<tr>\n<td><strong>3. Concentration</strong> in the air</td>\n<td>Higher concentration → more deposition</td>\n</tr>\n<tr>\n<td><strong>4. Duration of exposure</strong></td>\n<td>Most pneumoconioses need years of exposure (silicosis often 10+ years)</td>\n</tr>\n<tr>\n<td><strong>5. Individual susceptibility</strong></td>\n<td>Pre-existing lung disease, smoking, TB, poor mucociliary clearance</td>\n</tr>\n<tr>\n<td><strong>6. Shape</strong></td>\n<td>Long thin fibres (asbestos) penetrate deep and resist clearance</td>\n</tr>\n<tr>\n<td><strong>7. Solubility</strong></td>\n<td>Insoluble dusts persist in lungs → fibrosis</td>\n</tr>\n<tr>\n<td><strong>8. Rate of breathing</strong></td>\n<td>Heavy work → deeper breathing → more inhaled dust</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.285","n":285,"part":5,"topic":"Occupational Health","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention protective measures of garment workers against cotton dust.</p>","a":"<p><strong>Protective measures for garment / textile workers against cotton dust (byssinosis)</strong></p>\n<p><strong>A. Engineering (environmental) control</strong></p>\n<ol>\n<li><strong>Dust control at source</strong>: enclosure of machines; local exhaust ventilation; dust extraction systems.</li>\n<li><strong>Wet methods / humidification</strong> to keep dust down.</li>\n<li><strong>General ventilation</strong> and air filtration.</li>\n<li><strong>Good housekeeping</strong>: vacuum cleaning instead of sweeping or compressed-air blowing.</li>\n<li>Washing or steaming raw cotton; mechanisation of dusty processes.</li>\n<li><strong>Dust monitoring</strong> against permissible limits.</li>\n</ol>\n<p><strong>B. Personal protection</strong></p>\n<p>Respirators or dust masks; work clothes; personal hygiene.</p>\n<p><strong>C. Medical measures</strong></p>\n<ol>\n<li><strong>Pre-placement examination</strong>: exclude asthma and chronic lung disease.</li>\n<li><strong>Periodic examination</strong>: symptoms (&quot;Monday chest tightness&quot;), lung function tests (FEV₁ before and after shift), chest X-ray.</li>\n<li>Early detection → <strong>job transfer</strong> from dusty areas.</li>\n<li>Treatment; smoking cessation.</li>\n</ol>\n<p><strong>D. Administrative</strong></p>\n<p>Job rotation; limited exposure time; training and health education; record keeping.</p>\n<p><strong>E. Legislation</strong></p>\n<p>Bangladesh Labour Act 2006: dust and fume control, ventilation, PPE; notification and compensation of occupational disease; factory inspection.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.286","n":286,"part":5,"topic":"Occupational Health","stars":2,"years":["12Ja","05Ja","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write short note on sickness absenteeism.</p>","a":"<p><strong>Sickness absenteeism</strong></p>\n<p>Absence from work attributed by the employee to sickness and accepted as such by the employer. It is a useful <strong>index of the health and morale</strong> of workers and of working conditions.</p>\n<p><strong>Causes / factors</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Respiratory infections, diarrhoea, injuries, musculoskeletal pain, chronic diseases, pregnancy complications</td>\n</tr>\n<tr>\n<td><strong>Economic</strong></td>\n<td>Sick-leave benefits; low wages; second jobs</td>\n</tr>\n<tr>\n<td><strong>Social</strong></td>\n<td>Family illness or obligations, festivals, marriages, housing and transport problems</td>\n</tr>\n<tr>\n<td><strong>Work-related</strong></td>\n<td>Poor working conditions, job dissatisfaction, poor human relations, shift and night work, monotony</td>\n</tr>\n<tr>\n<td><strong>Personal</strong></td>\n<td>Alcoholism, drug use, age, sex (higher among women with double burden), personality</td>\n</tr>\n<tr>\n<td><strong>Seasonal</strong></td>\n<td>Winter respiratory illness, monsoon diseases</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Measurement</strong></p>\n<p>Sickness absence rate = (days lost due to sickness ÷ total working days) × 100; frequency and duration of spells.</p>\n<p><strong>Effects</strong></p>\n<p>Loss of production and wages; extra burden on co-workers; cost to industry.</p>\n<p><strong>Control</strong></p>\n<p>Occupational health services; better working conditions; health education; good human relations and welfare; investigation of causes; rehabilitation; verification of sickness certificates.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.287","n":287,"part":5,"topic":"Occupational Health","stars":3,"years":["17Ja","13Ja","10Ju","08Ja"],"colleges":"SSMC (2nd Term B3)","asked":"","note":"Asked together with: classify pneumoconiosis","kind":"","sub":"Agricultural Workers","q":"<p>What is farmer's lung? (Write short note.)</p>","a":"<p><strong>Farmer's lung</strong></p>\n<p>An occupational <strong>hypersensitivity pneumonitis (extrinsic allergic alveolitis)</strong> caused by inhalation of dust from <strong>mouldy hay, straw or grain</strong> containing <strong>thermophilic actinomycetes</strong> (<em>Saccharopolyspora rectivirgula</em>, formerly <em>Micropolyspora faeni</em>; <em>Thermoactinomyces vulgaris</em>). It is an <strong>organic-dust pneumoconiosis</strong>.</p>\n<p><strong>At risk</strong></p>\n<p>Farmers handling damp, stored hay, straw, grain; agricultural and dairy workers.</p>\n<p><strong>Clinical features</strong></p>\n<ul>\n<li><strong>Acute</strong>: 4–8 hours after exposure: fever, chills, malaise, cough, breathlessness, crepitations; resolves in 1–2 days if exposure stops.</li>\n<li><strong>Chronic</strong> (repeated exposure): progressive breathlessness, weight loss, <strong>pulmonary fibrosis</strong>, cor pulmonale.</li>\n</ul>\n<p><strong>Diagnosis</strong></p>\n<p>History of exposure; chest X-ray (diffuse nodular shadows; fibrosis later); lung function (restrictive pattern); serum precipitins to the antigens.</p>\n<p><strong>Prevention</strong></p>\n<ol>\n<li>Dry hay and grain properly before storage (prevents mould growth).</li>\n<li>Mechanical handling; good ventilation of barns.</li>\n<li>Dust masks / respirators.</li>\n<li>Health education; early recognition.</li>\n<li>Removal from exposure of affected workers.</li>\n</ol>\n<p><strong>Treatment</strong></p>\n<p>Avoid further exposure; corticosteroids in acute severe cases.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.288","n":288,"part":5,"topic":"Occupational Health","stars":3,"years":["23Nov","22M"],"colleges":"SSMC (2nd Term B4); MuMC (2nd Final C3)","asked":"common occupational cancers with exposure factors / list the occupational cancers in Bangladesh","note":"","kind":"","sub":"","q":"<p>Name some industries where workers develop cancer / name the occupational cancers.</p>","a":"<p><strong>Occupational cancers and causative exposures</strong></p>\n<table>\n<thead>\n<tr>\n<th>Cancer</th>\n<th>Agent</th>\n<th>Industry / workers</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Skin</strong></td>\n<td>Soot, tar, pitch, mineral oils, arsenic, UV</td>\n<td>Chimney sweeps (scrotal cancer, Pott 1775), tar and petroleum workers, outdoor workers</td>\n</tr>\n<tr>\n<td><strong>Lung</strong></td>\n<td>Asbestos, arsenic, chromium, nickel, uranium/radon, coal-tar fumes, cadmium, beryllium, silica</td>\n<td>Asbestos and ship-breaking, mining, chrome plating, tanneries, nickel refining</td>\n</tr>\n<tr>\n<td><strong>Mesothelioma</strong></td>\n<td>Asbestos</td>\n<td>Insulation, ship-breaking, construction</td>\n</tr>\n<tr>\n<td><strong>Urinary bladder</strong></td>\n<td>Aromatic amines (benzidine, β-naphthylamine)</td>\n<td><strong>Dye</strong>, rubber, cable, chemical industries</td>\n</tr>\n<tr>\n<td><strong>Leukaemia</strong></td>\n<td>Benzene; ionising radiation</td>\n<td>Petroleum, rubber, shoe industries; radiology</td>\n</tr>\n<tr>\n<td><strong>Liver (angiosarcoma)</strong></td>\n<td>Vinyl chloride</td>\n<td>PVC plastic industry</td>\n</tr>\n<tr>\n<td><strong>Nasal sinus</strong></td>\n<td>Wood dust, nickel, leather dust</td>\n<td>Furniture, nickel, leather workers</td>\n</tr>\n<tr>\n<td><strong>Bone</strong></td>\n<td>Radium</td>\n<td>Luminous dial painters</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Industries in Bangladesh with cancer risk</strong></p>\n<p>Ship-breaking (asbestos), tanneries (chromium), dyeing and textile (aromatic amines), rubber, chemical and pesticide factories, battery recycling, agriculture (pesticides).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.289","n":289,"part":5,"topic":"Occupational Health","stars":3,"years":["23Nov","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Label the industrial cancer control measures / discuss control measures of common occupational cancers with examples.</p>","a":"<p><strong>Control measures of occupational cancers (Park)</strong></p>\n<ol>\n<li><strong>Elimination or substitution</strong> of carcinogens (ban asbestos; replace benzidine dyes; replace benzene with safer solvents).</li>\n<li><strong>Engineering control</strong>: closed processes, enclosure, automation, local exhaust ventilation.</li>\n<li><strong>Medical examination</strong>:\n<ul>\n<li>Pre-placement.</li>\n<li><strong>Periodic</strong>: urine cytology (bladder cancer in dye workers), chest X-ray and sputum cytology (asbestos, chromium), skin examination, blood counts (benzene).</li>\n<li>Continued follow-up <strong>after leaving the job</strong> (long latent period).</li>\n</ul>\n</li>\n<li><strong>Personal hygiene</strong>: daily bath, change of clothes, no eating in work areas.</li>\n<li><strong>Personal protective equipment</strong>: respirators, gloves, aprons.</li>\n<li><strong>Inspection of factories</strong> and monitoring of exposure levels against permissible limits.</li>\n<li><strong>Notification</strong> of occupational cancers; cancer registries.</li>\n<li><strong>Licensing</strong> of industries using carcinogens.</li>\n<li><strong>Health education</strong> and training of workers; no smoking (synergy with asbestos).</li>\n<li><strong>Legislation</strong> and compensation.</li>\n<li><strong>Research</strong>: identify new carcinogens.</li>\n</ol>\n<p><strong>Examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Cancer</th>\n<th>Specific control</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Bladder (dyes)</td>\n<td>Ban benzidine; urine cytology every 6 months</td>\n</tr>\n<tr>\n<td>Mesothelioma, lung (asbestos)</td>\n<td>Ban or strict control of asbestos; wet methods; respirators; no smoking</td>\n</tr>\n<tr>\n<td>Skin (tar, oils)</td>\n<td>Protective clothing, washing, barrier creams</td>\n</tr>\n<tr>\n<td>Leukaemia (benzene, radiation)</td>\n<td>Substitution; radiation protection; blood counts</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.290","n":290,"part":5,"topic":"Occupational Health","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List at-risk workers for plumbism.</p>","a":"<p><strong>Workers at risk of plumbism (lead poisoning)</strong></p>\n<ol>\n<li><strong>Lead–acid battery</strong> manufacturing and <strong>recycling</strong> (major risk in Bangladesh's informal sector).</li>\n<li>Lead <strong>mining, smelting and refining</strong>.</li>\n<li><strong>Painters</strong> using lead-based paints; paint manufacture; scraping old paint.</li>\n<li><strong>Printing</strong> (type-metal workers).</li>\n<li><strong>Plumbers</strong> and pipe makers.</li>\n<li><strong>Ceramic and pottery</strong> glazing; glass making.</li>\n<li><strong>Ship-breaking</strong>, welding and cutting of lead-painted metal.</li>\n<li>Cable and solder makers; electronics recycling.</li>\n<li><strong>Rubber and plastic</strong> industries (lead stabilisers).</li>\n<li>Ammunition makers; firing-range staff.</li>\n<li>Petrol industry (historically tetraethyl lead).</li>\n<li>Cosmetic (kohl/surma) and traditional medicine makers.</li>\n</ol>\n<p><strong>Routes</strong></p>\n<p>Mainly <strong>inhalation</strong> of fumes and dust; also ingestion (eating, smoking with dirty hands). Children of workers exposed through dust brought home.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.291","n":291,"part":5,"topic":"Occupational Health","stars":3,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the features of plumbism?</p>","a":"<p><strong>Features of plumbism (lead poisoning)</strong></p>\n<p><strong>A. Symptoms and signs (Park)</strong></p>\n<ol>\n<li><strong>Facial pallor</strong>, especially around the mouth: earliest and most consistent sign.</li>\n<li><strong>Abdominal colic</strong> (lead colic), obstinate <strong>constipation</strong>, loss of appetite, metallic taste.</li>\n<li><strong>Burtonian line</strong>: blue line on the gums (lead sulphide).</li>\n<li><strong>Anaemia</strong>: microcytic hypochromic, with <strong>punctate basophilia</strong> (basophilic stippling of RBCs).</li>\n<li><strong>Peripheral neuropathy</strong> (motor): <strong>wrist drop</strong>, foot drop.</li>\n<li><strong>Encephalopathy</strong> (more in children): headache, irritability, convulsions, coma; learning and behaviour problems.</li>\n<li><strong>Kidney</strong>: nephropathy, hypertension, gout (saturnine gout).</li>\n<li><strong>Reproductive</strong>: abortion, stillbirth, reduced sperm count.</li>\n<li>Fatigue, muscle and joint pain.</li>\n</ol>\n<p><strong>B. Laboratory diagnosis</strong></p>\n<table>\n<thead>\n<tr>\n<th>Test</th>\n<th>Finding</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Blood lead</td>\n<td>Raised (best indicator of recent exposure)</td>\n</tr>\n<tr>\n<td>Urinary lead</td>\n<td>Raised</td>\n</tr>\n<tr>\n<td><strong>Urinary coproporphyrin (CPU)</strong></td>\n<td>Raised (useful screening test)</td>\n</tr>\n<tr>\n<td><strong>Urinary δ-aminolaevulinic acid (ALA)</strong></td>\n<td>Raised</td>\n</tr>\n<tr>\n<td>Blood film</td>\n<td>Basophilic stippling, anaemia</td>\n</tr>\n<tr>\n<td>Zinc protoporphyrin</td>\n<td>Raised</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Management</strong></p>\n<p>Remove from exposure; chelation (calcium disodium EDTA, DMSA/succimer, penicillamine); treat anaemia and colic.</p>\n<p><strong>D. Prevention</strong></p>\n<p>Substitution; exhaust ventilation; wet methods; personal hygiene (wash before eating, no eating at work); PPE; periodic blood lead and CPU tests; job rotation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.292","n":292,"part":5,"topic":"Occupational Health","stars":0,"years":[],"colleges":"ShSMC (2nd Term B1)","asked":"","note":"","kind":"","sub":"","q":"<p>State two purposes of periodic medical examination of workers.</p>","a":"<p><strong>Two purposes of periodic medical examination of workers</strong></p>\n<ol>\n<li><strong>Early detection</strong> of occupational diseases and adverse health effects (e.g., silicosis, lead poisoning, NIHL) at a reversible or treatable stage, so the worker can be treated or transferred.</li>\n<li><strong>Evaluation of control measures</strong>: shows whether the working environment and preventive measures (ventilation, PPE) are effective.</li>\n</ol>\n<p><strong>Other purposes</strong></p>\n<ul>\n<li>Detect <strong>non-occupational diseases</strong> (TB, diabetes, hypertension).</li>\n<li>Check continued <strong>fitness</strong> for the job; protect vulnerable workers (pregnant women, adolescents).</li>\n<li>Maintain <strong>records</strong> for research and compensation claims.</li>\n<li>Opportunity for <strong>health education</strong> and counselling.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.293","n":293,"part":5,"topic":"Occupational Health","stars":3,"years":["24Nov","23Nov","17J","13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Agricultural Workers","q":"<p>State the health problems / identify the occupational hazards faced by agricultural workers.</p>","a":"<p><strong>Occupational hazards of agricultural workers (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Hazard</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Zoonotic / biological</strong></td>\n<td>Brucellosis, leptospirosis, anthrax, tetanus, Q fever, rabies, hookworm and cutaneous larva migrans, fungal infections; vector-borne (malaria, kala-azar, dengue, scrub typhus); Nipah (date-palm sap)</td>\n</tr>\n<tr>\n<td><strong>2. Accidents</strong></td>\n<td>Injuries from tractors, threshers, power tillers, sharp tools; falls from trees; <strong>snake bites</strong>, insect and animal bites; lightning strikes; drowning</td>\n</tr>\n<tr>\n<td><strong>3. Toxic (chemical)</strong></td>\n<td><strong>Pesticide poisoning</strong> (organophosphates, carbamates); herbicides; fertilisers; skin and eye irritation</td>\n</tr>\n<tr>\n<td><strong>4. Physical</strong></td>\n<td>Heat stress and heat stroke, sun exposure (skin cancer, cataract), rain and cold, noise of machines, vibration</td>\n</tr>\n<tr>\n<td><strong>5. Respiratory</strong></td>\n<td>Organic dusts: farmer's lung, grain dust, bagassosis; smoke from crop burning</td>\n</tr>\n<tr>\n<td><strong>6. Ergonomic</strong></td>\n<td>Backache, joint pain from bending, lifting, prolonged squatting</td>\n</tr>\n<tr>\n<td><strong>7. Psychosocial</strong></td>\n<td>Economic insecurity, debt, crop failure → stress, depression, suicide (often by pesticide ingestion)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.294","n":294,"part":5,"topic":"Occupational Health","stars":3,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Agricultural Workers","q":"<p>Mention the biological hazards faced by agricultural workers.</p>","a":"<p><strong>Biological hazards faced by agricultural workers</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disease</th>\n<th>Source / mode</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Tetanus</strong></td>\n<td>Soil-contaminated wounds</td>\n</tr>\n<tr>\n<td><strong>Leptospirosis</strong></td>\n<td>Rat urine in flooded paddy fields, water</td>\n</tr>\n<tr>\n<td><strong>Hookworm</strong>, cutaneous larva migrans</td>\n<td>Walking barefoot on faecally contaminated soil</td>\n</tr>\n<tr>\n<td><strong>Brucellosis</strong></td>\n<td>Contact with cattle, goats; raw milk</td>\n</tr>\n<tr>\n<td><strong>Anthrax</strong></td>\n<td>Handling infected animals, carcasses, hides</td>\n</tr>\n<tr>\n<td><strong>Q fever</strong></td>\n<td>Cattle, sheep, goats</td>\n</tr>\n<tr>\n<td><strong>Rabies</strong></td>\n<td>Bites of dogs, jackals, mongooses</td>\n</tr>\n<tr>\n<td><strong>Snake bites</strong>, scorpion and insect stings</td>\n<td>Fields, bushes, during rainy season</td>\n</tr>\n<tr>\n<td><strong>Fungal infections</strong></td>\n<td>Wet work: tinea, candidiasis; mycetoma (Madura foot)</td>\n</tr>\n<tr>\n<td><strong>Vector-borne diseases</strong></td>\n<td>Malaria, kala-azar, dengue, Japanese encephalitis, scrub typhus</td>\n</tr>\n<tr>\n<td><strong>Nipah virus</strong></td>\n<td>Raw date-palm sap contaminated by bats</td>\n</tr>\n<tr>\n<td><strong>Farmer's lung</strong></td>\n<td>Mouldy hay and grain (actinomycetes)</td>\n</tr>\n<tr>\n<td><strong>Schistosomiasis</strong> (where endemic)</td>\n<td>Water contact</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.295","n":295,"part":5,"topic":"Occupational Health","stars":3,"years":["20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Agricultural Workers","q":"<p>How can we protect an agricultural worker from occupational health hazard?</p>","a":"<p><strong>Protection of agricultural workers</strong></p>\n<p><strong>A. Against biological hazards</strong></p>\n<ol>\n<li><strong>Tetanus immunisation</strong> (Td) for all farmers.</li>\n<li><strong>Footwear and gloves</strong>; protect wounds.</li>\n<li>Rodent control; avoid wading in contaminated water (leptospirosis).</li>\n<li><strong>Vaccination of animals</strong>; safe handling of carcasses; boiling milk.</li>\n<li>Rabies post-exposure prophylaxis; dog vaccination.</li>\n<li>Bed nets, repellents against vectors.</li>\n<li>Avoid raw date-palm sap (Nipah).</li>\n<li><strong>Antivenom</strong> at upazila health complexes; first aid for snake bite.</li>\n</ol>\n<p><strong>B. Against chemical hazards (pesticides)</strong></p>\n<ol>\n<li>Training in <strong>safe use</strong>: correct dose, mixing, spraying with the wind.</li>\n<li><strong>PPE</strong>: gloves, mask, goggles, long clothes; wash after spraying.</li>\n<li>Safe storage away from children and food; proper disposal of containers.</li>\n<li><strong>Integrated pest management</strong>; ban highly hazardous pesticides.</li>\n<li>Atropine and pralidoxime available at health facilities.</li>\n</ol>\n<p><strong>C. Against physical and accident hazards</strong></p>\n<p>Machine guards and training; safe use of tools; rest, shade and drinking water in heat; hats; lightning safety; first-aid kits.</p>\n<p><strong>D. Ergonomic</strong></p>\n<p>Better tools; correct lifting; rest breaks; mechanisation.</p>\n<p><strong>E. Health services and welfare</strong></p>\n<p>Primary health care in rural areas; periodic health check-ups; health education; crop and health insurance; social protection; mental health support.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.296","n":296,"part":5,"topic":"Occupational Health","stars":3,"years":["22Nov","18Nov","17Nov","11Ja","11Ju"],"colleges":"SSMC (2nd Term B4)","asked":"control measures of occupational diseases","note":"","kind":"","sub":"Prevention of Occupational Hazards","q":"<p>What are the general measures for prevention of occupational health hazards?</p>","a":"<p><strong>General measures for prevention of occupational hazards (Park)</strong></p>\n<p><strong>A. Medical measures</strong></p>\n<ol>\n<li><strong>Pre-placement examination</strong>: place the right worker in the right job; baseline data.</li>\n<li><strong>Periodic medical examination</strong>: early detection; evaluation of controls.</li>\n<li><strong>Medical and health care services</strong>: first aid, treatment, immunisation, rehabilitation.</li>\n<li><strong>Notification</strong> of occupational diseases.</li>\n<li><strong>Supervision of working environment</strong>: inspection, monitoring.</li>\n<li><strong>Maintenance and analysis of records</strong>.</li>\n<li><strong>Health education and counselling</strong>.</li>\n</ol>\n<p><strong>B. Engineering measures</strong></p>\n<ol>\n<li>Proper <strong>design of building</strong> (space, light, ventilation).</li>\n<li><strong>Good housekeeping</strong> (cleanliness, wet sweeping).</li>\n<li><strong>General ventilation</strong>.</li>\n<li><strong>Mechanisation</strong> and automation of hazardous processes.</li>\n<li><strong>Substitution</strong> of less harmful materials or processes.</li>\n<li><strong>Dust control</strong>: prevent formation, wet methods, suppression.</li>\n<li><strong>Enclosure</strong> of hazardous processes.</li>\n<li><strong>Isolation</strong> of hazardous processes (in space or time).</li>\n<li><strong>Local exhaust ventilation</strong>.</li>\n<li><strong>Protective devices</strong> (PPE): respirators, ear plugs, gloves, goggles, aprons.</li>\n<li><strong>Environmental monitoring</strong> of hazards.</li>\n<li><strong>Statistical monitoring</strong> of health and absence data.</li>\n<li><strong>Research</strong>.</li>\n</ol>\n<p><strong>C. Legislative measures</strong></p>\n<p>Labour and factory laws; permissible exposure limits; inspection; compensation; ILO conventions.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.297","n":297,"part":5,"topic":"Occupational Health","stars":3,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"Prevention of Occupational Hazards","q":"<p>What legislative measures should be taken to prevent industrial health hazards?</p>","a":"<p><strong>Legislative measures to prevent industrial health hazards (Bangladesh)</strong></p>\n<p><strong>Bangladesh Labour Act 2006 (amended) and Labour Rules 2015</strong> provide for:</p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Provisions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Health and hygiene</strong></td>\n<td>Cleanliness; ventilation and temperature; dust and fume control; artificial humidification standards; overcrowding limits; lighting; safe drinking water; latrines and urinals; spittoons; waste disposal</td>\n</tr>\n<tr>\n<td><strong>Safety</strong></td>\n<td>Fire precautions, exits and drills; fencing of machinery; safety of buildings and machinery; pressure plant; protection of eyes; dangerous fumes; restriction on lifting excessive weights; safety committees</td>\n</tr>\n<tr>\n<td><strong>Welfare</strong></td>\n<td>First aid; canteen; rest rooms; <strong>crèche</strong> for children of women workers; washing facilities</td>\n</tr>\n<tr>\n<td><strong>Working hours</strong></td>\n<td>Limits on daily and weekly hours; rest intervals; weekly holiday; limited overtime</td>\n</tr>\n<tr>\n<td><strong>Women</strong></td>\n<td><strong>Maternity benefit</strong> (16 weeks); restrictions on dangerous work</td>\n</tr>\n<tr>\n<td><strong>Children and adolescents</strong></td>\n<td>Prohibition of employment of children; restrictions and fitness certificates for adolescents</td>\n</tr>\n<tr>\n<td><strong>Notification</strong></td>\n<td>Accidents, dangerous occurrences and occupational diseases</td>\n</tr>\n<tr>\n<td><strong>Compensation</strong></td>\n<td>For injury, occupational disease and death</td>\n</tr>\n<tr>\n<td><strong>Inspection</strong></td>\n<td>Department of Inspection for Factories and Establishments (DIFE)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other measures</strong></p>\n<p>National Occupational Health and Safety Policy (2013); Environment Conservation Act 1995; building codes; post-Rana Plaza factory safety inspections (fire, electrical, structural); ratification of ILO conventions; permissible exposure limits; licensing of hazardous industries.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.298","n":298,"part":5,"topic":"Occupational Health","stars":2,"years":["12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Prevention of Occupational Hazards","q":"<p>How can coal miners be prevented from anthracosis?</p>","a":"<p><strong>Anthracosis (coal workers' pneumoconiosis)</strong></p>\n<p>Pneumoconiosis caused by inhalation of <strong>coal dust</strong> in coal mines (Bangladesh: Barapukuria).</p>\n<p><strong>Prevention</strong></p>\n<p><strong>A. Dust control (engineering)</strong></p>\n<ol>\n<li><strong>Wet methods</strong>: water sprays at cutting points; wet drilling; water infusion into coal seams.</li>\n<li><strong>Adequate mine ventilation</strong> to dilute and remove dust.</li>\n<li>Dust extraction at source; enclosed conveyors.</li>\n<li><strong>Regular dust monitoring</strong> against permissible limits.</li>\n</ol>\n<p><strong>B. Personal protection</strong></p>\n<p>Respirators / dust masks; protective clothing.</p>\n<p><strong>C. Medical measures</strong></p>\n<ol>\n<li><strong>Pre-placement examination</strong>: chest X-ray, lung function; exclude TB and chronic lung disease.</li>\n<li><strong>Periodic examination</strong>: chest X-ray (ILO classification), spirometry, sputum for TB.</li>\n<li>Early cases transferred to dust-free work.</li>\n<li>Treatment and rehabilitation; TB screening.</li>\n</ol>\n<p><strong>D. Administrative</strong></p>\n<p>Limit duration of exposure; job rotation; training and health education; <strong>no smoking</strong> (adds to lung damage).</p>\n<p><strong>E. Legislative</strong></p>\n<p>Mines Act and labour laws; inspection; notification; compensation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.299","n":299,"part":5,"topic":"Occupational Health","stars":0,"years":[],"colleges":"ShSMC (2nd Term B5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A nurse accidentally sustains a needle stick injury while recapping a used needle after giving an injection to a patient whose infection status is unknown. [1+3+3]</p>\n<ul>\n<li>a) What type of occupational hazard has occurred? (1)</li>\n<li>b) What factors would you assess to determine the risk of transmission of a blood borne infection following this exposure? (3)</li>\n<li>c) If the source patient is confirmed to be HBsAg positive, what occupational health measures should be considered for the exposed nurse? (3)</li>\n</ul>","a":"<p><strong>a) Type of occupational hazard (1)</strong></p>\n<p><strong>Biological hazard</strong>: percutaneous exposure to <strong>blood-borne pathogens</strong> (hepatitis B, hepatitis C, HIV) through a <strong>needle-stick (sharps) injury</strong>; caused by unsafe practice (recapping).</p>\n<p><strong>b) Factors to assess the risk of transmission (3)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Higher risk if</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Type of device</strong></td>\n<td><strong>Hollow-bore</strong> needle containing blood (vs solid suture needle)</td>\n</tr>\n<tr>\n<td><strong>Depth of injury</strong></td>\n<td>Deep penetration</td>\n</tr>\n<tr>\n<td><strong>Visible blood</strong> on the device</td>\n<td>Present</td>\n</tr>\n<tr>\n<td><strong>Site of prior use</strong></td>\n<td>Needle placed directly in the patient's vein or artery</td>\n</tr>\n<tr>\n<td><strong>Volume of blood</strong></td>\n<td>Larger; recently used needle</td>\n</tr>\n<tr>\n<td><strong>Barrier</strong></td>\n<td>No gloves (gloves wipe off some blood)</td>\n</tr>\n<tr>\n<td><strong>Source patient</strong></td>\n<td>HBsAg positive (especially HBeAg positive / high viral load), anti-HCV positive, HIV positive (high viral load, advanced disease); test source with consent</td>\n</tr>\n<tr>\n<td><strong>Exposed person</strong></td>\n<td><strong>Hepatitis B vaccination status and anti-HBs level</strong>; baseline HBV, HCV, HIV status</td>\n</tr>\n<tr>\n<td><strong>Time and first aid</strong></td>\n<td>Delay in washing and reporting</td>\n</tr>\n</tbody>\n</table>\n<p>Approximate transmission risk after needle-stick: HBV ~6–30% (non-immune), HCV ~1.8%, HIV ~0.3%.</p>\n<p><strong>c) Measures if the source is HBsAg positive (3)</strong></p>\n<ol>\n<li><strong>Immediate first aid</strong>: wash with soap and running water; do not squeeze or suck; report and document the incident.</li>\n<li><strong>Baseline tests</strong> of the nurse: HBsAg, anti-HBs, anti-HCV, HIV.</li>\n<li><strong>Post-exposure prophylaxis by vaccination status</strong>:</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Nurse's status</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Unvaccinated</td>\n<td><strong>HBIG</strong> (0.06 ml/kg IM) + start <strong>hepatitis B vaccine series</strong>, as soon as possible (ideally within 24 hours)</td>\n</tr>\n<tr>\n<td>Vaccinated, known responder (anti-HBs ≥10 mIU/ml)</td>\n<td>No treatment</td>\n</tr>\n<tr>\n<td>Vaccinated, known non-responder</td>\n<td>HBIG ×2 (one month apart), or HBIG + revaccination</td>\n</tr>\n<tr>\n<td>Vaccinated, response unknown</td>\n<td>Test anti-HBs: adequate → nothing; inadequate → HBIG + vaccine booster</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"4\">\n<li><strong>Follow-up testing</strong> (HBsAg, anti-HBc, anti-HBs) at about 6 months; also HCV and HIV follow-up as indicated.</li>\n<li><strong>Counselling</strong>; avoid donating blood, organs or semen during follow-up; no work restriction needed.</li>\n<li><strong>Prevention of recurrence</strong>: no recapping; sharps containers at point of use; safety-engineered devices; training; hepatitis B vaccination of all health workers; incident reporting system; compensation if infection occurs.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health; Epidemiology of Communicable Diseases).</p>"},{"id":"DU.300","n":300,"part":5,"topic":"Occupational Health","stars":0,"years":[],"colleges":"MuMC (2nd Final D5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A worker came to you with the complaints of irritant cough, dyspnea on exertion. On lab examination you found “snow storm” appearance in x-ray chest. [2+2+3]</p>\n<ul>\n<li>(a) What is your diagnosis and what may be his occupation? (2)</li>\n<li>(b) State preventive measures for this occupational disease. (2)</li>\n<li>(c) Name the disease which can occur due to organic and inorganic dusts? (3)</li>\n</ul>","a":"<p><strong>(a) Diagnosis and occupation (2)</strong></p>\n<ul>\n<li><strong>Diagnosis</strong>: <strong>Silicosis</strong> (irritant cough, exertional dyspnoea, &quot;snow-storm&quot; nodular opacities on chest X-ray).</li>\n<li><strong>Likely occupations</strong>: stone crushing, quarrying, mining, tunnelling, <strong>sand blasting</strong>, glass and pottery making, foundry work, construction (cutting concrete or stone), ceramic and tile industries.</li>\n</ul>\n<p><strong>(b) Preventive measures (2)</strong></p>\n<ol>\n<li><strong>Dust control</strong>: wet drilling and cutting; enclosure; local exhaust ventilation; substitute silica sand with safer abrasives (steel grit) in blasting.</li>\n<li><strong>Dust monitoring</strong> against permissible limits.</li>\n<li><strong>Respirators</strong> and protective clothing.</li>\n<li><strong>Medical examination</strong>: pre-placement and periodic chest X-ray and lung function; early removal from exposure.</li>\n<li><strong>TB screening</strong> (silicosis greatly raises TB risk); no smoking.</li>\n<li>Health education; limit exposure time; legislation, notification and compensation.</li>\n</ol>\n<p><strong>(c) Diseases due to organic and inorganic dusts (3)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Inorganic dusts</th>\n<th>Organic dusts</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Silicosis</strong> (silica)</td>\n<td><strong>Byssinosis</strong> (cotton, flax, hemp)</td>\n</tr>\n<tr>\n<td><strong>Anthracosis</strong> (coal)</td>\n<td><strong>Bagassosis</strong> (sugarcane)</td>\n</tr>\n<tr>\n<td><strong>Asbestosis</strong> (asbestos); mesothelioma, lung cancer</td>\n<td><strong>Farmer's lung</strong> (mouldy hay, grain)</td>\n</tr>\n<tr>\n<td><strong>Siderosis</strong> (iron)</td>\n<td>Bird fancier's lung</td>\n</tr>\n<tr>\n<td>Berylliosis (beryllium)</td>\n<td>Mushroom worker's lung, malt worker's lung</td>\n</tr>\n<tr>\n<td>Stannosis (tin), talcosis, baritosis</td>\n<td>Tobacosis; occupational asthma (wood dust)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health).</p>"},{"id":"DU.301","n":301,"part":6,"topic":"National Health Situations & Programmes","stars":0,"years":["07Ju"],"colleges":"MMC (2nd Term D1)","asked":"common communicable and non-communicable diseases of Bangladesh","note":"","kind":"","sub":"","q":"<p>What are the common health problems?</p>","a":"<p><strong>Common health problems of Bangladesh</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Problems</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Communicable diseases</strong></td>\n<td>ARI and pneumonia; diarrhoeal diseases; tuberculosis; <strong>dengue</strong> (large urban outbreaks); typhoid; hepatitis B and E; malaria (hill tracts); measles and other vaccine-preventable diseases (outbreaks when coverage drops); STIs/HIV (low prevalence, key populations); emerging infections (Nipah, COVID-19)</td>\n</tr>\n<tr>\n<td><strong>Non-communicable diseases</strong> (now the leading causes of death)</td>\n<td>Hypertension, ischaemic heart disease, <strong>stroke</strong>, <strong>diabetes</strong>, COPD and asthma, cancers (lung, oral, cervical, breast), chronic kidney disease</td>\n</tr>\n<tr>\n<td><strong>Maternal and child health</strong></td>\n<td>Maternal and neonatal deaths (birth asphyxia, prematurity, sepsis); home deliveries; child marriage and adolescent pregnancy</td>\n</tr>\n<tr>\n<td><strong>Nutrition</strong></td>\n<td>Stunting (23.6% of under-5s, 2022), wasting, underweight; anaemia in women and children; micronutrient deficiencies; rising overweight and obesity</td>\n</tr>\n<tr>\n<td><strong>Mental health</strong></td>\n<td>Depression, anxiety, substance use, suicide</td>\n</tr>\n<tr>\n<td><strong>Injuries</strong></td>\n<td>Road traffic injuries, <strong>drowning</strong> (leading killer of children aged 1–4), burns, falls, occupational injuries</td>\n</tr>\n<tr>\n<td><strong>Environmental</strong></td>\n<td>Arsenic in groundwater, air pollution, unsafe water and sanitation in slums, climate-related disasters</td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Snake bite, population ageing, disability, antimicrobial resistance, tobacco use</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Underlying factors</strong></p>\n<p>Poverty, illiteracy, high population density, rapid urbanisation, out-of-pocket health spending, shortage and maldistribution of health workers.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community); Our World in Data, Bangladesh health profile, https://ourworldindata.org/profile/health/bangladesh</p>"},{"id":"DU.302","n":302,"part":6,"topic":"National Health Situations & Programmes","stars":0,"years":["07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List the names of important national health programmes.</p>","a":"<p><strong>Important national health programmes of Bangladesh</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Programmes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Immunisation</strong></td>\n<td><strong>Expanded Programme on Immunization (EPI)</strong> (since 1979)</td>\n</tr>\n<tr>\n<td><strong>Communicable diseases</strong></td>\n<td>National Tuberculosis Control Programme; National Leprosy Programme; National Malaria Elimination Programme; Kala-azar Elimination Programme; Lymphatic Filariasis Elimination Programme; National AIDS/STD Programme; dengue control; hepatitis control; zoonotic disease control</td>\n</tr>\n<tr>\n<td><strong>Maternal, newborn, child and adolescent health</strong></td>\n<td>MNC&amp;AH programme; IMCI; safe motherhood; adolescent health</td>\n</tr>\n<tr>\n<td><strong>Family planning</strong></td>\n<td>National Family Planning Programme (DGFP)</td>\n</tr>\n<tr>\n<td><strong>Nutrition</strong></td>\n<td>National Nutrition Services (vitamin A, IYCF, micronutrients, SAM management); salt iodisation</td>\n</tr>\n<tr>\n<td><strong>Non-communicable diseases</strong></td>\n<td>NCD Control programme (hypertension, diabetes, cancer, stroke, COPD screening); tobacco control; mental health; eye care</td>\n</tr>\n<tr>\n<td><strong>Primary health care</strong></td>\n<td>Community Based Health Care (community clinics)</td>\n</tr>\n<tr>\n<td><strong>Environmental health</strong></td>\n<td>Arsenic mitigation; WASH (with DPHE)</td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>School health; occupational health; emergency preparedness; hospital services; health information (MIS)</td>\n</tr>\n</tbody>\n</table>\n<p>These run as operational plans under the national Health, Population and Nutrition Sector Programme.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.303","n":303,"part":6,"topic":"National Health Situations & Programmes","stars":2,"years":["12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the components of ESP.</p>","a":"<p><strong>Essential Service Package (ESP)</strong></p>\n<p>A set of cost-effective, high-priority primary-level services provided free or at low cost to all, especially women, children and the poor; introduced under the Health and Population Sector Programme (1998) and continued in later sector programmes.</p>\n<p><strong>Components</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Services</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Reproductive health care</strong></td>\n<td>Safe motherhood (ANC, delivery, PNC, EmOC referral); family planning; menstrual regulation and post-abortion care; adolescent reproductive health; RTI/STI management</td>\n</tr>\n<tr>\n<td><strong>2. Child health care</strong></td>\n<td>EPI; IMCI (ARI, diarrhoea, malaria, measles, malnutrition); newborn care; vitamin A; growth monitoring</td>\n</tr>\n<tr>\n<td><strong>3. Communicable disease control</strong></td>\n<td>TB (DOTS), leprosy, malaria, kala-azar, filariasis, HIV/AIDS, dengue</td>\n</tr>\n<tr>\n<td><strong>4. Limited curative care</strong></td>\n<td>First aid, treatment of common illnesses and injuries; referral</td>\n</tr>\n<tr>\n<td><strong>5. Behaviour change communication (BCC)</strong></td>\n<td>Health, nutrition and family planning messages</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Later additions (revised ESP)</strong></p>\n<p>Nutrition services; NCD screening (hypertension, diabetes); mental health; eye and oral health; elderly care.</p>\n<p><strong>Delivery points</strong></p>\n<p>Community clinics, union facilities, Upazila Health Complexes, urban PHC centres, outreach (satellite clinics, EPI sites).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.304","n":304,"part":6,"topic":"National Health Situations & Programmes","stars":3,"years":["24Nov","16Ja","15Ja","12Ju","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List five national and five international NGOs working in Bangladesh / name health related NGOs / enlist national NGOs rendering health care services / name 5 international organizations working in health.</p>","a":"<p><strong>National NGOs working in health (Bangladesh)</strong></p>\n<ol>\n<li><strong>BRAC</strong> (community health workers, TB, maternal and child health, WASH)</li>\n<li><strong>icddr,b</strong> (International Centre for Diarrhoeal Disease Research, Bangladesh; research and hospital services)</li>\n<li><strong>Gonoshasthaya Kendra</strong> (community health, low-cost drugs)</li>\n<li><strong>Diabetic Association of Bangladesh (BADAS)</strong> / BIRDEM</li>\n<li><strong>Family Planning Association of Bangladesh (FPAB)</strong></li>\n<li><strong>Marie Stopes Bangladesh</strong> (reproductive health)</li>\n<li><strong>Social Marketing Company (SMC)</strong> (ORS, contraceptives, nutrition products)</li>\n<li><strong>Bangladesh Red Crescent Society</strong></li>\n<li>Sajida Foundation, Shimantik, Dhaka Ahsania Mission, Bangladesh Women's Health Coalition</li>\n<li>Surjer Hasi (Smiling Sun) clinic network</li>\n</ol>\n<p><strong>International NGOs</strong></p>\n<ol>\n<li><strong>Save the Children</strong></li>\n<li><strong>CARE</strong></li>\n<li><strong>Plan International</strong></li>\n<li><strong>World Vision</strong></li>\n<li><strong>Médecins Sans Frontières (MSF)</strong></li>\n<li>Helen Keller International</li>\n<li>WaterAid</li>\n<li>Concern Worldwide</li>\n<li>Pathfinder International, EngenderHealth</li>\n<li>Sightsavers, The Leprosy Mission, Islamic Relief, Oxfam</li>\n</ol>\n<p><strong>International organisations (UN and others)</strong></p>\n<p>WHO, UNICEF, UNFPA, UNDP, UNAIDS, WFP, FAO, UNHCR, IOM, World Bank, Asian Development Bank, Gavi, Global Fund, JICA, FCDO.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health; Health Care of the Community).</p>"},{"id":"DU.305","n":305,"part":6,"topic":"National Health Situations & Programmes","stars":3,"years":["13Ju","09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss diabetes association of Bangladesh / mention its activities.</p>","a":"<p><strong>Diabetic Association of Bangladesh (BADAS)</strong></p>\n<ul>\n<li>Voluntary, non-profit social welfare organisation founded in <strong>1956</strong> by <strong>Prof. Mohammad Ibrahim</strong>.</li>\n<li>Pioneer in comprehensive diabetes care in Bangladesh and South Asia.</li>\n<li>Central institute: <strong>BIRDEM</strong> (Bangladesh Institute of Research and Rehabilitation in Diabetes, Endocrine and Metabolic Disorders), Dhaka; a WHO Collaborating Centre.</li>\n<li>Network of affiliated associations and diabetes centres in districts and upazilas.</li>\n</ul>\n<p><strong>Activities</strong></p>\n<ol>\n<li><strong>Registration and care</strong>: lifelong registration of diabetic patients (guide book); outpatient and inpatient care at low cost or free for the poor.</li>\n<li><strong>Health education</strong>: patients, families, public; diet, exercise, foot care, insulin use.</li>\n<li><strong>Prevention</strong>: screening campaigns; awareness on World Diabetes Day; primary prevention programmes.</li>\n<li><strong>Specialist services</strong>: BIRDEM General Hospital (endocrinology, cardiology, nephrology, eye, foot care), maternal and child health in diabetes (gestational diabetes).</li>\n<li><strong>Rehabilitation</strong>: vocational and social support for diabetic patients.</li>\n<li><strong>Training and education</strong>: Ibrahim Medical College, Bangladesh University of Health Sciences, nursing and allied health institutes; postgraduate courses.</li>\n<li><strong>Research</strong>: epidemiological and clinical research on diabetes and NCDs.</li>\n<li><strong>Supply</strong> of insulin and drugs at fair prices.</li>\n<li><strong>Advocacy</strong> and partnership with government on NCD policy.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.306","n":306,"part":6,"topic":"International Health","stars":3,"years":["25M","21M"],"colleges":"MMC (1st Supp B3)","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist four important UN organizations working in Bangladesh / mention the names of international health organizations.</p>","a":"<p><strong>UN organisations working in Bangladesh (health-related)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Organisation</th>\n<th>Main work</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>WHO</strong> (World Health Organization)</td>\n<td>Technical support for health policy, disease control, EPI, emergencies, IHR</td>\n</tr>\n<tr>\n<td><strong>UNICEF</strong> (United Nations Children's Fund)</td>\n<td>Child health, immunisation (vaccine supply), nutrition, WASH, education, child protection</td>\n</tr>\n<tr>\n<td><strong>UNFPA</strong> (United Nations Population Fund)</td>\n<td>Reproductive health, family planning, midwifery, gender-based violence</td>\n</tr>\n<tr>\n<td><strong>UNDP</strong> (United Nations Development Programme)</td>\n<td>Development, poverty reduction, governance, climate</td>\n</tr>\n<tr>\n<td><strong>UNAIDS</strong></td>\n<td>HIV/AIDS coordination</td>\n</tr>\n<tr>\n<td><strong>WFP</strong> (World Food Programme)</td>\n<td>Food assistance, school feeding, nutrition</td>\n</tr>\n<tr>\n<td><strong>FAO</strong> (Food and Agriculture Organization)</td>\n<td>Food security, agriculture, zoonoses (One Health)</td>\n</tr>\n<tr>\n<td><strong>UNHCR</strong>, <strong>IOM</strong></td>\n<td>Refugees (Rohingya), migrants</td>\n</tr>\n<tr>\n<td><strong>ILO</strong></td>\n<td>Labour standards, occupational safety</td>\n</tr>\n<tr>\n<td><strong>World Bank</strong></td>\n<td>Financing of health sector programmes</td>\n</tr>\n</tbody>\n</table>\n<p><strong>International health organisations (general)</strong></p>\n<p>WHO, UNICEF, UNFPA, UNDP, ILO, FAO, World Bank; International Red Cross and Red Crescent Movement; bilateral agencies (USAID, JICA, FCDO, SIDA); global partnerships (Gavi, Global Fund); international NGOs (Save the Children, CARE, MSF).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.307","n":307,"part":6,"topic":"International Health","stars":3,"years":["25M","24M","18M","16Ju","15Ja","08Ja"],"colleges":"MMC (1st Supp B3); MuMC (1st Final A2, 1st Supp A2)","asked":"","note":"","kind":"","sub":"","q":"<p>Name the regional headquarters of WHO / enlist the regions of WHO with their headquarters.</p>","a":"<p><strong>WHO regions and regional headquarters</strong></p>\n<table>\n<thead>\n<tr>\n<th>Region</th>\n<th>Regional office (headquarters)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>South-East Asia Region (SEARO)</strong></td>\n<td><strong>New Delhi, India</strong> (Bangladesh belongs here)</td>\n</tr>\n<tr>\n<td>African Region (AFRO)</td>\n<td>Brazzaville, Republic of the Congo</td>\n</tr>\n<tr>\n<td>Region of the Americas (AMRO / PAHO)</td>\n<td>Washington, DC, USA</td>\n</tr>\n<tr>\n<td>European Region (EURO)</td>\n<td>Copenhagen, Denmark</td>\n</tr>\n<tr>\n<td>Eastern Mediterranean Region (EMRO)</td>\n<td>Cairo, Egypt</td>\n</tr>\n<tr>\n<td>Western Pacific Region (WPRO)</td>\n<td>Manila, Philippines</td>\n</tr>\n</tbody>\n</table>\n<p><strong>WHO headquarters</strong>: Geneva, Switzerland.<br />\n<strong>WHO founded</strong>: 7 April 1948 (World Health Day).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.308","n":308,"part":6,"topic":"International Health","stars":3,"years":["25M","22Nov","22M","21M","12Ju","12Ja","10Ja","09Ja","06Ja"],"colleges":"DMC (1st Assess A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the functions of WHO / state activities of WHO / role and functions of WHO Secretariat.</p>","a":"<p><strong>Functions of WHO (Constitution, Article 2: main points)</strong></p>\n<ol>\n<li>Act as the <strong>directing and coordinating authority</strong> on international health work.</li>\n<li>Collaborate with the UN, specialised agencies, governments and professional groups.</li>\n<li><strong>Assist governments</strong> to strengthen health services.</li>\n<li>Provide <strong>technical assistance</strong> and, in emergencies, necessary aid.</li>\n<li>Stimulate work to <strong>eradicate epidemic, endemic and other diseases</strong>.</li>\n<li>Promote prevention of accidental injuries.</li>\n<li>Promote improved <strong>nutrition, housing, sanitation</strong>, working conditions and environmental hygiene.</li>\n<li>Promote <strong>maternal and child health</strong> and <strong>mental health</strong>.</li>\n<li>Promote and conduct <strong>research</strong>.</li>\n<li>Propose <strong>conventions, agreements and regulations</strong> (IHR 2005, Framework Convention on Tobacco Control).</li>\n<li>Set <strong>international standards</strong> for food, biological, pharmaceutical products; <strong>international nomenclature</strong> of diseases (ICD).</li>\n<li>Promote <strong>training</strong> of health personnel.</li>\n<li>Develop informed <strong>public opinion</strong> on health.</li>\n</ol>\n<p><strong>Main areas of work (Park)</strong></p>\n<p>Prevention and control of specific diseases; development of comprehensive health services; family health; environmental health; health statistics; biomedical research; health literature and information; cooperation with other organisations.</p>\n<p><strong>Organs</strong></p>\n<p>World Health Assembly (policy) → Executive Board (executive) → Secretariat (Director-General; administrative and technical).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health); WHO Constitution, 1948.</p>"},{"id":"DU.309","n":309,"part":6,"topic":"International Health","stars":3,"years":["14Ja","11Ju"],"colleges":"MuMC (1st Final A2, 1st Supp A2)","asked":"5 WHO-supported programmes in Bangladesh","note":"","kind":"","sub":"","q":"<p>Enumerate the (current) health related activities of WHO in Bangladesh / name 3 major activities.</p>","a":"<p><strong>WHO's health-related activities in Bangladesh</strong></p>\n<ol>\n<li><strong>Immunisation</strong>: technical support to EPI; polio and measles-rubella surveillance; vaccine safety; campaigns.</li>\n<li><strong>Communicable disease control and elimination</strong>: TB, malaria, dengue, hepatitis, NTDs; supported elimination of <strong>lymphatic filariasis</strong> and <strong>kala-azar</strong> as public health problems (validated 2023).</li>\n<li><strong>Health emergencies</strong>: Rohingya humanitarian response, disease outbreaks (dengue, cholera, COVID-19), floods and cyclones.</li>\n<li><strong>International Health Regulations</strong>: strengthening surveillance and response (with IEDCR).</li>\n<li><strong>NCD prevention and control</strong>: hypertension and diabetes management (HEARTS), tobacco control (FCTC), cancer, mental health.</li>\n<li><strong>Maternal, newborn, child and adolescent health</strong>; nutrition.</li>\n<li><strong>Health systems and UHC</strong>: health financing, workforce, primary health care, quality of care, health information (DHIS2).</li>\n<li><strong>Medicines and regulation</strong>: essential medicines, drug regulation (DGDA), antimicrobial resistance.</li>\n<li><strong>Environmental health and climate</strong>: air quality, WASH, climate-resilient health systems.</li>\n<li><strong>Policy advice, guidelines, research and training</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health); WHO, 2023, https://www.who.int/news/item/31-10-2023-bangladesh-achieves-historic-milestone-by-eliminating-kala-azar-as-a-public-health-problem</p>"},{"id":"DU.310","n":310,"part":6,"topic":"International Health","stars":3,"years":["24M"],"colleges":"DMC (1st Assess A3)","asked":"slogan of World Health Day 2026","note":"","kind":"","sub":"","q":"<p>What is the slogan of WHO for the year 2024?</p>","a":"<p><strong>World Health Day (7 April) themes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Year</th>\n<th>Theme (slogan)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>2024</strong></td>\n<td><strong>&quot;My health, my right&quot;</strong></td>\n</tr>\n<tr>\n<td>2025</td>\n<td>&quot;Healthy beginnings, hopeful futures&quot; (maternal and newborn health; year-long campaign)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> WHO, World Health Day.</p>"},{"id":"DU.311","n":311,"part":6,"topic":"International Health","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Name two of WHO in global health.</p>","a":"<p><strong>Two roles of WHO in global health</strong></p>\n<ol>\n<li><strong>Directing and coordinating authority on international health</strong>: leads global responses (e.g., smallpox eradication, polio eradication, COVID-19 response) and coordinates countries and partners.</li>\n<li><strong>Setting norms and standards</strong>: International Health Regulations (2005), Framework Convention on Tobacco Control, International Classification of Diseases (ICD), essential medicines list, treatment guidelines, drinking-water and air-quality guidelines.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.312","n":312,"part":6,"topic":"International Health","stars":0,"years":["05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by executive body of WHO?</p>","a":"<p><strong>Executive body of WHO: the Executive Board (EB)</strong></p>\n<p><strong>Composition</strong></p>\n<ul>\n<li><strong>34 members</strong>, technically qualified in the field of health, designated by Member States elected by the World Health Assembly.</li>\n<li>Members serve <strong>three-year terms</strong>; seats distributed among WHO regions.</li>\n</ul>\n<p><strong>Functions</strong></p>\n<ol>\n<li><strong>Gives effect to the decisions and policies</strong> of the World Health Assembly (executive organ).</li>\n<li>Prepares the <strong>agenda</strong> of the World Health Assembly.</li>\n<li>Advises the Assembly on questions referred to it.</li>\n<li>Submits the <strong>programme of work</strong> and budget proposals.</li>\n<li>Takes <strong>emergency measures</strong> within WHO's functions (e.g., outbreaks, disasters).</li>\n<li>Nominates the <strong>Director-General</strong> for appointment by the Assembly.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.313","n":313,"part":6,"topic":"International Health","stars":3,"years":["26M","24Nov","23Nov","20Nov","18M","16Ju","15Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the functions / activities (health, child and communicable-disease related) of UNICEF in Bangladesh.</p>","a":"<p><strong>UNICEF (United Nations Children's Fund)</strong></p>\n<p>Founded 1946; works for the survival, development and protection of children; in Bangladesh since the early 1950s.</p>\n<p><strong>Activities in Bangladesh</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Activities</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Child health</strong></td>\n<td>Support to <strong>EPI</strong>: vaccine procurement, cold chain, campaigns (polio, measles-rubella, typhoid conjugate, HPV); newborn care (special care newborn units); IMCI</td>\n</tr>\n<tr>\n<td><strong>Communicable disease control</strong></td>\n<td>Immunisation; ORS and zinc promotion; diarrhoea and pneumonia control; HIV prevention among adolescents; outbreak response (cholera vaccines, COVID-19 vaccine delivery)</td>\n</tr>\n<tr>\n<td><strong>Nutrition</strong></td>\n<td>Vitamin A supplementation; IYCF and breastfeeding promotion; management of severe acute malnutrition; salt iodisation; micronutrients</td>\n</tr>\n<tr>\n<td><strong>Maternal health</strong></td>\n<td>ANC, facility delivery, midwifery support (with UNFPA)</td>\n</tr>\n<tr>\n<td><strong>WASH</strong></td>\n<td>Safe water (arsenic-safe options), sanitation, hygiene, WASH in schools</td>\n</tr>\n<tr>\n<td><strong>Education</strong></td>\n<td>Primary and early childhood education; out-of-school children</td>\n</tr>\n<tr>\n<td><strong>Child protection</strong></td>\n<td>Birth registration; prevention of child marriage, child labour and violence; Meena communication initiative</td>\n</tr>\n<tr>\n<td><strong>Adolescents</strong></td>\n<td>Health, menstrual hygiene, life skills</td>\n</tr>\n<tr>\n<td><strong>Emergencies</strong></td>\n<td>Rohingya response; floods and cyclones</td>\n</tr>\n<tr>\n<td><strong>Social policy</strong></td>\n<td>Child-sensitive social protection; advocacy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.314","n":314,"part":6,"topic":"International Health","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Critically analyze USAID support to improve health sector in Bangladesh.</p>","a":"<p><strong>USAID support to the health sector of Bangladesh: critical analysis</strong></p>\n<p><strong>A. Contributions (strengths)</strong></p>\n<ol>\n<li><strong>Family planning</strong>: long-term support for contraceptive supply and social marketing (SMC); contributed to the fall in fertility.</li>\n<li><strong>Maternal, newborn and child health</strong>: community-based newborn care, chlorhexidine cord care, safe delivery, nutrition.</li>\n<li><strong>Health surveys and data</strong>: Bangladesh Demographic and Health Surveys (BDHS) and other surveys.</li>\n<li><strong>NGO service delivery</strong>: urban and rural clinic networks (Smiling Sun / Surjer Hasi).</li>\n<li><strong>TB control</strong>: case finding, MDR-TB management.</li>\n<li><strong>Research</strong>: support to icddr,b (ORS, zinc, newborn care evidence).</li>\n<li><strong>Nutrition and food security</strong>; humanitarian aid (Rohingya response).</li>\n<li>Health systems strengthening: supply chain, health information.</li>\n</ol>\n<p><strong>B. Limitations (criticisms)</strong></p>\n<ol>\n<li><strong>Donor dependence</strong>; questions of sustainability after funding ends.</li>\n<li><strong>Vertical, project-based</strong> programmes not always aligned with national sector priorities.</li>\n<li>Funding linked to US policy priorities and conditions (e.g., restrictions on abortion-related services under the Mexico City Policy).</li>\n<li>High administrative and consultancy costs; parallel systems.</li>\n<li>Uneven geographic coverage; limited capacity transfer in some projects.</li>\n</ol>\n<p><strong>C. Recent change</strong></p>\n<p>The <strong>2025 US foreign-aid freeze and restructuring of USAID</strong> abruptly stopped or cut many programmes (family planning, TB, nutrition, surveys, humanitarian support), showing the risk of dependence on a single donor.</p>\n<p><strong>Lesson</strong></p>\n<p>Strengthen government ownership and domestic financing; align donor support with the national sector programme; build sustainable systems.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.315","n":315,"part":6,"topic":"International Health","stars":2,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the role of international health agencies in the health care services of Bangladesh.</p>","a":"<p><strong>Role of international health agencies in Bangladesh's health services</strong></p>\n<table>\n<thead>\n<tr>\n<th>Role</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Policy and technical support</strong></td>\n<td>WHO guidelines and technical advice on EPI, TB, NCDs, UHC</td>\n</tr>\n<tr>\n<td><strong>2. Financing</strong></td>\n<td>World Bank and development partners through the Health, Population and Nutrition Sector Programme (pooled funds); Global Fund (TB, malaria, HIV); Gavi (vaccines)</td>\n</tr>\n<tr>\n<td><strong>3. Supplies and logistics</strong></td>\n<td>UNICEF vaccine procurement and cold chain; UNFPA contraceptives and reproductive health supplies</td>\n</tr>\n<tr>\n<td><strong>4. Disease control and elimination</strong></td>\n<td>WHO and partners: polio eradication, kala-azar and filariasis elimination, malaria, dengue response</td>\n</tr>\n<tr>\n<td><strong>5. Maternal and child health, nutrition</strong></td>\n<td>UNICEF, UNFPA, WFP: newborn care, midwifery, vitamin A, school feeding</td>\n</tr>\n<tr>\n<td><strong>6. Emergencies</strong></td>\n<td>WHO, UNICEF, UNHCR, IOM, WFP, MSF, Red Cross/Red Crescent: Rohingya crisis, floods, cyclones, COVID-19</td>\n</tr>\n<tr>\n<td><strong>7. Research</strong></td>\n<td>Support to icddr,b and universities</td>\n</tr>\n<tr>\n<td><strong>8. Human resources</strong></td>\n<td>Training of health workers, midwifery education, fellowships</td>\n</tr>\n<tr>\n<td><strong>9. Health information</strong></td>\n<td>Surveys (BDHS, MICS), DHIS2, surveillance</td>\n</tr>\n<tr>\n<td><strong>10. Advocacy</strong></td>\n<td>Health rights, gender, tobacco control, SDGs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Challenges</strong></p>\n<p>Dependence on external funds, fragmentation, alignment and coordination problems, sustainability; sudden aid cuts.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.316","n":316,"part":6,"topic":"International Health","stars":0,"years":["05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the activities of Red Crescent.</p>","a":"<p><strong>Red Crescent</strong></p>\n<p>Part of the <strong>International Red Cross and Red Crescent Movement</strong> (ICRC, IFRC and national societies). In Bangladesh: <strong>Bangladesh Red Crescent Society (BDRCS)</strong>, a national voluntary humanitarian organisation (formerly Bangladesh Red Cross Society; renamed in 1988).</p>\n<p><strong>Fundamental principles</strong></p>\n<p>Humanity, impartiality, neutrality, independence, voluntary service, unity, universality.</p>\n<p><strong>Activities</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Activities</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Disaster management</strong></td>\n<td><strong>Cyclone Preparedness Programme</strong> (with government): early warning, evacuation by volunteers; relief and recovery after floods, cyclones, fires</td>\n</tr>\n<tr>\n<td><strong>Health services</strong></td>\n<td>Hospitals (Holy Family Red Crescent Medical College Hospital), maternity and child health centres, community health programmes</td>\n</tr>\n<tr>\n<td><strong>Blood services</strong></td>\n<td>Voluntary blood donation and blood banks</td>\n</tr>\n<tr>\n<td><strong>First aid</strong></td>\n<td>Training of volunteers, students and public; ambulance services</td>\n</tr>\n<tr>\n<td><strong>Refugee and humanitarian aid</strong></td>\n<td>Rohingya response: health, WASH, shelter, psychosocial support</td>\n</tr>\n<tr>\n<td><strong>WASH</strong></td>\n<td>Safe water, sanitation, hygiene in disasters</td>\n</tr>\n<tr>\n<td><strong>Restoring family links</strong></td>\n<td>Tracing missing persons (with ICRC)</td>\n</tr>\n<tr>\n<td><strong>Youth</strong></td>\n<td>Red Crescent Youth: volunteering, health awareness</td>\n</tr>\n<tr>\n<td><strong>Climate adaptation</strong></td>\n<td>Community resilience, early action</td>\n</tr>\n<tr>\n<td><strong>Dissemination</strong></td>\n<td>International humanitarian law, protection of the emblem</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.317","n":317,"part":6,"topic":"International Health","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the role of CARE in Bangladesh in health &amp; agriculture sectors.</p>","a":"<p><strong>CARE in Bangladesh</strong></p>\n<p>CARE (Cooperative for Assistance and Relief Everywhere) is an international NGO working in Bangladesh for decades, focusing on poverty, women's empowerment and humanitarian response.</p>\n<p><strong>Health sector</strong></p>\n<ol>\n<li><strong>Maternal and newborn health</strong>: community-based skilled birth attendants, ANC, safe delivery, postnatal care.</li>\n<li><strong>Nutrition</strong>: food security and nutrition programmes for poor households (e.g., SHOUHARDO), growth monitoring, IYCF.</li>\n<li><strong>WASH</strong>: safe water, sanitation, hygiene behaviour change.</li>\n<li><strong>Reproductive health and family planning</strong>; adolescent health.</li>\n<li><strong>HIV prevention</strong> among vulnerable groups (earlier programmes).</li>\n<li><strong>Health systems</strong>: community engagement and accountability (community scorecards), support to local government health services.</li>\n<li><strong>Emergency health</strong>: Rohingya response, disasters.</li>\n</ol>\n<p><strong>Agriculture sector</strong></p>\n<ol>\n<li><strong>Food security</strong> and improved farming for poor and women farmers.</li>\n<li><strong>Climate-resilient agriculture</strong>: saline- and flood-tolerant crops, homestead gardening.</li>\n<li><strong>Livestock and dairy</strong> value chains; market linkages.</li>\n<li>Women's economic empowerment; savings groups.</li>\n<li>Disaster risk reduction for farming communities.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health).</p>"},{"id":"DU.318","n":318,"part":6,"topic":"International Health","stars":2,"years":["21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the achievement of BIRDEM.</p>","a":"<p><strong>Achievements of BIRDEM</strong></p>\n<p>BIRDEM (Bangladesh Institute of Research and Rehabilitation in Diabetes, Endocrine and Metabolic Disorders), Dhaka: central institute of the <strong>Diabetic Association of Bangladesh</strong>; a <strong>WHO Collaborating Centre</strong>.</p>\n<ol>\n<li><strong>Model of comprehensive diabetes care</strong>: registration, treatment, education and rehabilitation under one roof, at low cost; free care for the poor.</li>\n<li><strong>Large tertiary hospital</strong> (BIRDEM General Hospital) with endocrinology, cardiology, nephrology and dialysis, eye, foot care, surgery, ICU.</li>\n<li><strong>Nationwide network</strong> of affiliated diabetic centres in districts and upazilas.</li>\n<li><strong>Health education</strong> of patients (diet, insulin, foot care) and public awareness.</li>\n<li><strong>Research</strong>: epidemiological and clinical research on diabetes, gestational diabetes, NCDs; publications.</li>\n<li><strong>Training and education</strong>: postgraduate courses; Ibrahim Medical College; Bangladesh University of Health Sciences; nursing and allied health institutes.</li>\n<li><strong>Maternal and child health in diabetes</strong>; childhood diabetes services.</li>\n<li><strong>Prevention programmes</strong>: screening, primary prevention, World Diabetes Day activities.</li>\n<li><strong>Recognition</strong>: WHO Collaborating Centre for research and training in diabetes; regional leader in diabetes care.</li>\n<li><strong>Rehabilitation</strong>: social and vocational support for diabetic patients.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.319","n":319,"part":6,"topic":"International Health","stars":0,"years":[],"colleges":"MuMC (1st Final D5, 1st Supp D4)","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by IHR 2005?</p>","a":"<p><strong>International Health Regulations (IHR, 2005)</strong></p>\n<p>A <strong>legally binding international instrument</strong> adopted by the World Health Assembly in <strong>2005</strong>, in force since <strong>2007</strong>, binding on all WHO Member States (States Parties).</p>\n<p><strong>Purpose and scope</strong></p>\n<p>To prevent, protect against, control and provide a public health response to the <strong>international spread of disease</strong>, in ways that are proportionate to the public health risk and that avoid unnecessary interference with international traffic and trade.</p>\n<p><strong>Key features</strong></p>\n<ol>\n<li><strong>All-hazards</strong>: covers infectious, chemical, radiological and other events, not a fixed list of diseases.</li>\n<li><strong>Notification</strong> to WHO within <strong>24 hours</strong> of assessing an event that may constitute a <strong>Public Health Emergency of International Concern (PHEIC)</strong> (decision instrument, Annex 2).</li>\n<li><strong>National IHR Focal Point</strong> in each country (Bangladesh: DGHS / IEDCR).</li>\n<li><strong>Core capacities</strong>: surveillance, laboratory, response, risk communication, points of entry (airports, ports, land crossings).</li>\n<li><strong>PHEIC</strong> declared by the WHO Director-General on advice of an <strong>Emergency Committee</strong>; temporary and standing recommendations.</li>\n<li><strong>Health measures at points of entry</strong>: vaccination certificates (yellow fever), screening, isolation.</li>\n<li>Monitoring by annual reporting and joint external evaluation.</li>\n<li><strong>Amended in 2024</strong> (in force 2025): adds a &quot;pandemic emergency&quot; level and strengthens equity and coordination.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health); WHO, International Health Regulations (2005).</p>"},{"id":"DU.320","n":320,"part":6,"topic":"International Health","stars":0,"years":[],"colleges":"MuMC (1st Final D5, 1st Supp D4)","asked":"","note":"","kind":"","sub":"","q":"<p>What is the importance of IHR (International Health Regulations) in public health?</p>","a":"<p><strong>Importance of IHR in public health</strong></p>\n<ol>\n<li><strong>Global health security</strong>: early detection and containment of outbreaks before they spread across borders.</li>\n<li><strong>Legal obligation</strong>: binding on all States Parties; ensures timely <strong>notification</strong> and information sharing.</li>\n<li><strong>All-hazards approach</strong>: covers infectious, chemical, radiological and food-safety events.</li>\n<li><strong>Builds national core capacities</strong>: surveillance, laboratories, rapid response teams, risk communication, emergency preparedness.</li>\n<li><strong>Points of entry</strong>: health measures at airports, ports and land crossings (screening, isolation, vaccination certificates).</li>\n<li><strong>Coordinated international response</strong>: WHO can declare a <strong>PHEIC</strong> and issue recommendations to guide countries.</li>\n<li><strong>Balances health with trade and travel</strong>: prevents unnecessary restrictions that harm economies.</li>\n<li><strong>Protects human rights</strong> of travellers (dignity, privacy).</li>\n<li><strong>Accountability</strong>: monitoring and evaluation of country capacities.</li>\n<li><strong>One Health</strong> linkage: zoonotic and environmental threats.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (International Health); WHO, International Health Regulations (2005).</p>"},{"id":"DU.321","n":321,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["25M","15Ja","13Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Name three insects prevalent in Bangladesh and diseases caused by them / mention (name common) arthropod-borne diseases of Bangladesh.</p>","a":"<p><strong>Common insects in Bangladesh and diseases transmitted</strong></p>\n<table>\n<thead>\n<tr>\n<th>Insect</th>\n<th>Diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Mosquito</strong></td>\n<td><em>Aedes</em>: <strong>dengue</strong>, chikungunya, Zika; <em>Anopheles</em>: <strong>malaria</strong>; <em>Culex</em>: <strong>lymphatic filariasis</strong>, Japanese encephalitis</td>\n</tr>\n<tr>\n<td><strong>Sandfly</strong> (<em>Phlebotomus argentipes</em>)</td>\n<td><strong>Kala-azar</strong> (visceral leishmaniasis), PKDL</td>\n</tr>\n<tr>\n<td><strong>Housefly</strong> (<em>Musca domestica</em>)</td>\n<td>Diarrhoea, dysentery, cholera, typhoid, hepatitis A, trachoma, conjunctivitis, worm eggs, myiasis</td>\n</tr>\n<tr>\n<td><strong>Louse</strong></td>\n<td>Pediculosis; epidemic typhus, relapsing fever, trench fever (body louse)</td>\n</tr>\n<tr>\n<td><strong>Rat flea</strong> (<em>Xenopsylla cheopis</em>)</td>\n<td>Plague, murine typhus</td>\n</tr>\n<tr>\n<td>Cockroach</td>\n<td>Mechanical carrier of enteric pathogens; allergy</td>\n</tr>\n<tr>\n<td>Bed bug</td>\n<td>Nuisance, sleep loss, anaemia (heavy infestation)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other arthropods (non-insects)</strong></p>\n<p>Itch mite → <strong>scabies</strong>; trombiculid mite → <strong>scrub typhus</strong>; ticks → tick-borne fevers; cyclops → guinea worm (not in Bangladesh).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.322","n":322,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["25Nov","24M","22M","21M","18Nov","17Nov"],"colleges":"DMC (1st Assess C1); SSMC (1st Supp B1); ShSMC (1st Term A3); MMC (1st Supp C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define and classify medically important arthropods (with illustrations).</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Medically important arthropods</strong>: invertebrate animals with jointed legs, segmented body and chitinous exoskeleton (phylum <strong>Arthropoda</strong>) that cause disease directly or transmit infectious agents to man.</p>\n<p><strong>Classification (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Class</th>\n<th>Main features</th>\n<th>Examples and importance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Insecta</strong></td>\n<td>Body: head, thorax, abdomen; <strong>3 pairs of legs</strong>; 1 pair of antennae; usually wings</td>\n<td>Mosquito, housefly, sandfly, tsetse fly, blackfly, louse, flea, reduviid bug, cockroach</td>\n</tr>\n<tr>\n<td><strong>2. Arachnida</strong></td>\n<td>Body: cephalothorax + abdomen; <strong>4 pairs of legs</strong>; no antennae, no wings</td>\n<td>Ticks (tick fevers), mites (scabies, scrub typhus), spiders, scorpions (venom)</td>\n</tr>\n<tr>\n<td><strong>3. Crustacea</strong></td>\n<td>Two pairs of antennae; mostly aquatic; gills</td>\n<td>Cyclops (guinea worm, fish tapeworm), crabs and crayfish (paragonimiasis)</td>\n</tr>\n<tr>\n<td><strong>4. Chilopoda</strong></td>\n<td>Centipedes: one pair of legs per segment</td>\n<td>Venomous bites</td>\n</tr>\n<tr>\n<td><strong>5. Diplopoda</strong></td>\n<td>Millipedes: two pairs of legs per segment</td>\n<td>Irritant secretions</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Illustration (body plans)</strong></p>\n<pre><code>Insect:     [Head]-[Thorax: 3 pairs legs, wings]-[Abdomen]\nArachnid:   [Cephalothorax: 4 pairs legs]-[Abdomen]\nCrustacean: [Cephalothorax: 2 pairs antennae]-[Abdomen]\n</code></pre>\n<p><strong>Ways arthropods harm man</strong></p>\n<ol>\n<li><strong>Transmit disease</strong> (vectors): malaria, dengue, kala-azar, plague.</li>\n<li><strong>Cause disease directly</strong>: scabies, pediculosis, myiasis.</li>\n<li><strong>Bites and stings</strong>: venom, allergy.</li>\n<li><strong>Nuisance</strong> and psychological stress.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.323","n":323,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["17Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention personal protective measures for disease prevention.</p>","a":"<p><strong>Personal protective measures against arthropod-borne diseases</strong></p>\n<ol>\n<li><strong>Bed nets</strong>: insecticide-treated / long-lasting insecticidal nets (LLIN); use also for daytime naps (dengue).</li>\n<li><strong>Repellents</strong>: DEET, picaridin, IR3535 or plant-based (citronella) on exposed skin.</li>\n<li><strong>Protective clothing</strong>: long-sleeved shirts, full trousers, socks; light colours; insecticide-treated clothing.</li>\n<li><strong>Screening</strong> of doors and windows with wire mesh; fine mesh against sandflies.</li>\n<li><strong>Mosquito coils, vaporisers, mats</strong>, electric bats (for nuisance relief).</li>\n<li><strong>Avoid exposure</strong> at peak biting times (dusk and dawn for <em>Anopheles</em> and <em>Culex</em>; early morning and late afternoon for <em>Aedes</em>).</li>\n<li><strong>Personal hygiene</strong>: regular bathing, clean clothes and bedding → prevents lice and scabies; avoid sharing combs and clothes.</li>\n<li><strong>Footwear</strong> and avoiding rodent-infested areas (fleas, mites); insect repellent on legs in scrub areas (scrub typhus).</li>\n<li><strong>Chemoprophylaxis</strong> for travellers to malaria-endemic areas.</li>\n<li><strong>Vaccination</strong> where available (Japanese encephalitis).</li>\n<li>Removing breeding sites around one's own home (water containers, flower vases).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.324","n":324,"part":7,"topic":"Arthropod Diseases and Control","stars":2,"years":["25Nov","24Nov","18M","11Ju","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How are arthropod-borne diseases transmitted? / Illustrate key mechanisms / what are the modes of transmission of vector-borne diseases?</p>","a":"<p><strong>Modes of transmission of arthropod-borne (vector-borne) diseases (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Mechanism</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Direct contact</strong></td>\n<td>Arthropod transferred by close contact; causes disease itself</td>\n<td>Scabies (itch mite), pediculosis (lice)</td>\n</tr>\n<tr>\n<td><strong>2. Mechanical transmission</strong></td>\n<td>Agent carried on body, legs, mouthparts or in gut without multiplication or development</td>\n<td>Housefly: typhoid, cholera, dysentery, trachoma</td>\n</tr>\n<tr>\n<td><strong>3. Biological transmission</strong></td>\n<td>Agent multiplies and/or develops in the vector before it can be transmitted (extrinsic incubation period)</td>\n<td></td>\n</tr>\n<tr>\n<td>(a) Propagative</td>\n<td>Multiplication only, no change in form</td>\n<td>Plague bacilli in rat flea; dengue virus in <em>Aedes</em></td>\n</tr>\n<tr>\n<td>(b) Cyclo-propagative</td>\n<td>Change in form + multiplication</td>\n<td>Malaria parasite in <em>Anopheles</em></td>\n</tr>\n<tr>\n<td>(c) Cyclo-developmental</td>\n<td>Change in form, no multiplication</td>\n<td>Filarial worm in <em>Culex</em>; guinea worm in cyclops</td>\n</tr>\n<tr>\n<td><strong>4. Transovarial transmission</strong></td>\n<td>Agent passes from infected female to her eggs and next generation</td>\n<td>Scrub typhus in mites; some arboviruses in mosquitoes and ticks</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Routes from vector to man</strong></p>\n<p>Bite (inoculation of saliva: malaria, dengue); regurgitation (blocked flea in plague); contamination of bite wound with vector faeces (murine typhus, Chagas disease); crushing of vector on skin (louse in relapsing fever); ingestion (cyclops in water).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.325","n":325,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["20Nov","08Ja","05S"],"colleges":"","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>Discuss biological transmission of arthropod-borne (vector-borne) diseases / modes of biological transmission in mosquitoes with example.</p>","a":"<p><strong>Biological transmission</strong></p>\n<p>The infectious agent undergoes <strong>multiplication and/or developmental changes inside the vector</strong> before it becomes infective; there is an <strong>extrinsic incubation period</strong> before the vector can transmit.</p>\n<p><strong>Types (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>What happens in the vector</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Propagative</strong></td>\n<td>Agent <strong>multiplies</strong> but does not change form</td>\n<td>Plague bacillus in rat flea; dengue, chikungunya, Japanese encephalitis viruses in mosquitoes; yellow fever virus in <em>Aedes</em></td>\n</tr>\n<tr>\n<td><strong>Cyclo-propagative</strong></td>\n<td>Agent <strong>changes form (cycle) and multiplies</strong></td>\n<td><strong>Malaria</strong>: gametocytes → gametes → zygote → ookinete → oocyst → thousands of sporozoites in salivary glands of <em>Anopheles</em></td>\n</tr>\n<tr>\n<td><strong>Cyclo-developmental</strong></td>\n<td>Agent <strong>develops (changes form) but does not multiply</strong></td>\n<td><strong>Filariasis</strong>: microfilaria → L1 → L2 → L3 (infective larva) in <em>Culex</em>; one microfilaria gives at most one L3; guinea worm in cyclops</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Modes of biological transmission in mosquitoes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mosquito</th>\n<th>Disease</th>\n<th>Type</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><em>Anopheles</em></td>\n<td>Malaria</td>\n<td>Cyclo-propagative</td>\n</tr>\n<tr>\n<td><em>Culex</em></td>\n<td>Filariasis</td>\n<td>Cyclo-developmental</td>\n</tr>\n<tr>\n<td><em>Culex</em></td>\n<td>Japanese encephalitis</td>\n<td>Propagative</td>\n</tr>\n<tr>\n<td><em>Aedes</em></td>\n<td>Dengue, chikungunya, Zika, yellow fever</td>\n<td>Propagative (also transovarial for some viruses)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Importance</strong></p>\n<p>Extrinsic incubation period depends on temperature; control can target vector longevity (adult control) so that it dies before becoming infective.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.326","n":326,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["20Nov","18Nov","11Ja","09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the principles of arthropod control measures.</p>","a":"<p><strong>Principles of arthropod control (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Principle</th>\n<th>Methods</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Environmental control</strong> (most permanent)</td>\n<td>Source reduction: eliminate breeding and resting places; drainage, filling, cleaning; sanitation; improved housing</td>\n<td>Emptying water containers (<em>Aedes</em>); clearing drains (<em>Culex</em>); plastering cracks (sandfly); refuse disposal (flies)</td>\n</tr>\n<tr>\n<td><strong>2. Chemical control</strong></td>\n<td>Insecticides: residual sprays (indoor residual spraying), space sprays (fogging), larvicides; repellents</td>\n<td>Pyrethroids for IRS; malathion fogging; temephos larvicide</td>\n</tr>\n<tr>\n<td><strong>3. Biological control</strong></td>\n<td>Living organisms or their products that kill vectors</td>\n<td>Larvivorous fish (<em>Gambusia</em>, guppy); <em>Bacillus thuringiensis israelensis</em> (Bti), <em>B. sphaericus</em></td>\n</tr>\n<tr>\n<td><strong>4. Genetic control</strong></td>\n<td>Altering vector reproduction</td>\n<td>Sterile male technique; <em>Wolbachia</em>-infected mosquitoes</td>\n</tr>\n<tr>\n<td><strong>5. Personal protection</strong></td>\n<td>Nets, repellents, screens, clothing</td>\n<td>LLINs</td>\n</tr>\n<tr>\n<td><strong>6. Integrated vector management (IVM)</strong></td>\n<td>Rational combination of the above, based on local ecology, with community participation and intersectoral action</td>\n<td>Dengue control in cities</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Supporting measures</strong></p>\n<p>Entomological surveillance (larval indices); monitoring insecticide resistance; legislation (fines for breeding sites); health education and community participation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.327","n":327,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["16Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down your concept about the class insects.</p>","a":"<p><strong>Class Insecta</strong></p>\n<p>The largest class of the phylum Arthropoda.</p>\n<p><strong>Characteristic features</strong></p>\n<ol>\n<li>Body divided into <strong>three parts</strong>: head, thorax, abdomen.</li>\n<li><strong>Head</strong>: one pair of <strong>antennae</strong>, compound eyes, mouthparts (piercing-sucking in mosquito, sponging in housefly, biting).</li>\n<li><strong>Thorax</strong>: <strong>three pairs of jointed legs</strong>; usually <strong>two pairs of wings</strong> (one pair in flies and mosquitoes; none in lice and fleas).</li>\n<li><strong>Abdomen</strong>: segmented; no legs.</li>\n<li>Chitinous exoskeleton; breathe through tracheae and spiracles.</li>\n<li>Sexes separate.</li>\n</ol>\n<p><strong>Metamorphosis</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Stages</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Complete (holometabolous)</strong></td>\n<td>Egg → Larva → Pupa → Adult</td>\n<td>Mosquito, housefly, sandfly, flea</td>\n</tr>\n<tr>\n<td><strong>Incomplete (hemimetabolous)</strong></td>\n<td>Egg → Nymph → Adult</td>\n<td>Louse, bed bug, reduviid bug, cockroach</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Medically important insects</strong></p>\n<p>Mosquitoes, flies (housefly, sandfly, tsetse, blackfly), lice, fleas, bugs (reduviid, bed bug), cockroaches.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.328","n":328,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["18M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the importance of knowing medical entomology.</p>","a":"<p><strong>Importance of knowing medical entomology</strong></p>\n<ol>\n<li><strong>Identify vectors</strong> of important diseases (malaria, dengue, kala-azar, filariasis, plague).</li>\n<li>Understand <strong>modes of transmission</strong> (mechanical, biological) and the extrinsic incubation period.</li>\n<li>Know <strong>life cycle, breeding, biting and resting habits</strong> → choose the right control method and timing (e.g., daytime protection against <em>Aedes</em>).</li>\n<li><strong>Plan and evaluate vector control</strong> programmes (IRS, larviciding, source reduction).</li>\n<li><strong>Entomological surveillance</strong>: larval indices, vector density, infection rates → predict outbreaks.</li>\n<li><strong>Epidemiological investigation</strong> of outbreaks.</li>\n<li><strong>Monitor insecticide resistance</strong> and choose effective insecticides.</li>\n<li>Recognise <strong>emerging and re-emerging</strong> vector-borne diseases (Zika, chikungunya) and effects of climate change on vectors.</li>\n<li><strong>Health education</strong> of the community on prevention.</li>\n<li>Diagnose and manage diseases caused directly by arthropods (scabies, pediculosis, myiasis).</li>\n<li>Support elimination programmes (kala-azar, filariasis, malaria in Bangladesh).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.329","n":329,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":[],"colleges":"ShSMC (1st Term A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Define medical entomology.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Medical entomology</strong>: the branch of science that deals with the study of <strong>arthropods of medical importance</strong> (insects and related arthropods): their identification, structure, life cycle, habits, role in causing and transmitting disease to man, and their control.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.330","n":330,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":[],"colleges":"ShSMC (1st Term A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Define vector.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Vector</strong>: an arthropod or other living carrier that transports an infectious agent from an infected individual (or its wastes) to a susceptible individual, or to its food or immediate surroundings (Park).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.331","n":331,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>Distinguish between Aedes and Anopheles mosquitoes.</p>","a":"<p><strong>Aedes vs Anopheles mosquitoes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th><em>Aedes</em></th>\n<th><em>Anopheles</em></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Eggs</strong></td>\n<td>Laid singly; cigar-shaped; no floats; resist drying for months</td>\n<td>Laid singly; boat-shaped with <strong>lateral floats</strong></td>\n</tr>\n<tr>\n<td><strong>Larva</strong></td>\n<td>Short, stout <strong>siphon tube</strong>; hangs head-down at an angle to water surface</td>\n<td><strong>No siphon</strong>; lies <strong>parallel</strong> to water surface; palmate hairs</td>\n</tr>\n<tr>\n<td><strong>Adult colour</strong></td>\n<td>Black with <strong>white stripes</strong> on body and legs (&quot;tiger mosquito&quot;)</td>\n<td>Dark; <strong>spotted wings</strong> (dark and pale scales)</td>\n</tr>\n<tr>\n<td><strong>Resting position</strong></td>\n<td>Body <strong>parallel</strong> to surface (humped)</td>\n<td>Body at an <strong>angle</strong> (~45°) to surface; proboscis and body in one line</td>\n</tr>\n<tr>\n<td><strong>Palps (female)</strong></td>\n<td>Short</td>\n<td>As long as proboscis</td>\n</tr>\n<tr>\n<td><strong>Biting time</strong></td>\n<td><strong>Daytime</strong> (early morning, late afternoon)</td>\n<td><strong>Night</strong> (dusk to dawn)</td>\n</tr>\n<tr>\n<td><strong>Breeding</strong></td>\n<td><strong>Clean water in artificial containers</strong>: tyres, flower pots, water tanks, coconut shells, construction sites</td>\n<td>Clean water: ponds, streams, rice fields, wells; some in brackish water</td>\n</tr>\n<tr>\n<td><strong>Habitat</strong></td>\n<td>Urban, domestic; rests indoors in dark places</td>\n<td>Rural, forest, foothills (Bangladesh: hill tracts)</td>\n</tr>\n<tr>\n<td><strong>Flight range</strong></td>\n<td>Short</td>\n<td>Longer</td>\n</tr>\n<tr>\n<td><strong>Diseases</strong></td>\n<td><strong>Dengue</strong>, chikungunya, Zika, yellow fever</td>\n<td><strong>Malaria</strong> (also filariasis in some areas)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.332","n":332,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>Differentiate between Anopheles and Culex mosquitoes.</p>","a":"<p><strong>Anopheles vs Culex mosquitoes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th><em>Anopheles</em></th>\n<th><em>Culex</em></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Eggs</strong></td>\n<td>Laid <strong>singly</strong>; boat-shaped with <strong>lateral floats</strong></td>\n<td>Laid in <strong>rafts</strong> (clusters); cigar-shaped; no floats</td>\n</tr>\n<tr>\n<td><strong>Larva</strong></td>\n<td><strong>No siphon tube</strong>; rests <strong>parallel</strong> to water surface</td>\n<td><strong>Long, narrow siphon tube</strong>; hangs <strong>at an angle</strong> with head down</td>\n</tr>\n<tr>\n<td><strong>Pupa</strong></td>\n<td>Short, broad respiratory trumpets</td>\n<td>Long, narrow respiratory trumpets</td>\n</tr>\n<tr>\n<td><strong>Adult resting position</strong></td>\n<td>Body at an <strong>angle</strong> to the surface</td>\n<td>Body <strong>parallel</strong> to the surface (humped back)</td>\n</tr>\n<tr>\n<td><strong>Wings</strong></td>\n<td><strong>Spotted</strong></td>\n<td><strong>Unspotted</strong></td>\n</tr>\n<tr>\n<td><strong>Palps (female)</strong></td>\n<td><strong>As long as</strong> proboscis</td>\n<td><strong>Much shorter</strong> than proboscis</td>\n</tr>\n<tr>\n<td><strong>Colour</strong></td>\n<td>Dark, spotted</td>\n<td>Dull brown</td>\n</tr>\n<tr>\n<td><strong>Breeding</strong></td>\n<td><strong>Clean</strong> water: ponds, streams, rice fields</td>\n<td><strong>Dirty, polluted</strong> water: drains, cesspools, septic tanks, ditches</td>\n</tr>\n<tr>\n<td><strong>Biting time</strong></td>\n<td>Night</td>\n<td>Night (major urban nuisance)</td>\n</tr>\n<tr>\n<td><strong>Diseases</strong></td>\n<td><strong>Malaria</strong></td>\n<td><strong>Lymphatic filariasis</strong> (<em>C. quinquefasciatus</em>), <strong>Japanese encephalitis</strong> (<em>C. tritaeniorhynchus</em>), West Nile fever</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.333","n":333,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["22Nov","19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>What do you know about breeding habit of mosquitoes? Write about biting habit and breeding habit of Aedes mosquito.</p>","a":"<p><strong>Breeding habits of mosquitoes (general)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Genus</th>\n<th>Breeding places</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><em>Anopheles</em></td>\n<td>Clean, unpolluted water: ponds, streams, rice fields, wells, hill streams; some in brackish water</td>\n</tr>\n<tr>\n<td><em>Culex</em></td>\n<td>Dirty, polluted water: drains, cesspits, septic tanks, ditches, burrow pits</td>\n</tr>\n<tr>\n<td><em>Aedes</em></td>\n<td>Clean water in <strong>artificial and natural containers</strong></td>\n</tr>\n<tr>\n<td><em>Mansonia</em></td>\n<td>Ponds with aquatic plants (larvae attach to roots)</td>\n</tr>\n</tbody>\n</table>\n<p>Life cycle: Egg → Larva → Pupa → Adult (aquatic stages ~7–10 days in warm weather).</p>\n<p><strong>Aedes aegypti: breeding habits</strong></p>\n<ol>\n<li>Breeds in <strong>clean, stagnant water</strong> in <strong>artificial containers</strong>: water tanks and drums, flower vases and pots, discarded tyres, tins, bottles, coconut shells, refrigerator trays, air-cooler trays, construction sites, roof gutters.</li>\n<li><strong>Eggs laid singly</strong> just above the water line on container walls; <strong>withstand drying for months</strong> → hatch when flooded (rain).</li>\n<li>Small amounts of water are enough (bottle caps).</li>\n<li><em>Aedes albopictus</em> also breeds in natural containers: tree holes, leaf axils, bamboo stumps.</li>\n</ol>\n<p><strong>Aedes aegypti: biting habits</strong></p>\n<ol>\n<li><strong>Day-biter</strong>: peaks in early morning and late afternoon.</li>\n<li><strong>Anthropophilic</strong> (prefers human blood); bites mainly around ankles and legs.</li>\n<li><strong>Domestic and endophilic</strong>: rests indoors in dark, cool places (under furniture, behind curtains).</li>\n<li><strong>Multiple feeding</strong>: bites several people in one blood meal cycle → efficient epidemic spread.</li>\n<li>Short flight range (around the house).</li>\n<li>Nervous feeder: disturbed easily, then bites again.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.334","n":334,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["22Nov","19M","16Ja","14Ju","11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>Write down the names of mosquito-borne diseases (prevailing in Bangladesh).</p>","a":"<p><strong>Mosquito-borne diseases (prevailing in Bangladesh)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mosquito</th>\n<th>Disease</th>\n<th>Agent</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><em>Aedes aegypti</em>, <em>Ae. albopictus</em></strong></td>\n<td><strong>Dengue</strong> (and severe dengue)</td>\n<td>Dengue virus (4 serotypes)</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Chikungunya</strong></td>\n<td>Chikungunya virus</td>\n</tr>\n<tr>\n<td></td>\n<td>Zika (sporadic)</td>\n<td>Zika virus</td>\n</tr>\n<tr>\n<td><em><strong>Anopheles</strong></em></td>\n<td><strong>Malaria</strong> (mainly Chattogram Hill Tracts and border districts)</td>\n<td><em>Plasmodium falciparum</em>, <em>P. vivax</em></td>\n</tr>\n<tr>\n<td><em><strong>Culex quinquefasciatus</strong></em></td>\n<td><strong>Lymphatic filariasis</strong> (eliminated as public health problem, 2023)</td>\n<td><em>Wuchereria bancrofti</em></td>\n</tr>\n<tr>\n<td><em><strong>Culex tritaeniorhynchus</strong></em> / <em>Culex vishnui</em> group</td>\n<td><strong>Japanese encephalitis</strong></td>\n<td>JE virus</td>\n</tr>\n<tr>\n<td><em>Culex</em></td>\n<td>West Nile fever (risk)</td>\n<td>West Nile virus</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other mosquito-borne diseases (global)</strong></p>\n<p>Yellow fever, Rift Valley fever, brugian filariasis (<em>Mansonia</em>).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology; Epidemiology of Communicable Diseases).</p>"},{"id":"DU.335","n":335,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["25M","24M","21M","15Ja","10Ja"],"colleges":"DMC (1st Assess C1)","asked":"how can Aedes mosquitoes be controlled in an urban area?","note":"","kind":"","sub":"Mosquito","q":"<p>How can mosquitoes (tiger mosquito, Dhaka city, urban area) be controlled? Discuss general principles of mosquito control.</p>","a":"<p><strong>General principles of mosquito control</strong></p>\n<p><strong>A. Anti-larval measures</strong></p>\n<ol>\n<li><strong>Environmental control (source reduction)</strong>: drain, fill or clean breeding places; remove containers; proper water storage; clean drains.</li>\n<li><strong>Chemical larvicides</strong>: temephos (Abate), fenthion, mineral oil (MLO), insect growth regulators (pyriproxyfen).</li>\n<li><strong>Biological control</strong>: larvivorous fish (<em>Gambusia</em>, guppy) in ponds and tanks; <em>Bacillus thuringiensis israelensis</em> (Bti).</li>\n</ol>\n<p><strong>B. Anti-adult measures</strong></p>\n<ol>\n<li><strong>Indoor residual spraying</strong> (malaria vectors).</li>\n<li><strong>Space spraying / fogging</strong> (malathion, pyrethroids) in outbreaks.</li>\n<li>Genetic control (sterile males, <em>Wolbachia</em>).</li>\n</ol>\n<p><strong>C. Personal protection</strong></p>\n<p>Bed nets (LLIN), repellents, screening, protective clothing, coils and vaporisers.</p>\n<p><strong>D. Supporting</strong></p>\n<p>Surveillance (larval and adult indices), insecticide-resistance monitoring, health education, community participation, legislation, <strong>integrated vector management</strong>.</p>\n<p><strong>Control of Aedes (tiger mosquito) in Dhaka city / urban areas</strong></p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Actions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Source reduction (most important)</strong></td>\n<td>Empty, clean and cover water containers every week; remove tyres, tins, bottles, coconut shells; clean roof gardens, flower pots, air-cooler and fridge trays; manage water at construction sites; clean gutters</td>\n</tr>\n<tr>\n<td><strong>Community action</strong></td>\n<td>Weekly &quot;search and destroy&quot; campaigns in homes, offices, schools; volunteer and ward-level drives</td>\n</tr>\n<tr>\n<td><strong>Larviciding</strong></td>\n<td>Temephos or Bti in containers that cannot be emptied</td>\n</tr>\n<tr>\n<td><strong>Adult control</strong></td>\n<td>Targeted fogging around dengue cases during outbreaks (not routine)</td>\n</tr>\n<tr>\n<td><strong>Surveillance</strong></td>\n<td>Larval indices: house index, container index, <strong>Breteau index</strong> (positive containers per 100 houses; &gt;20 = high risk); case reporting</td>\n</tr>\n<tr>\n<td><strong>Legislation</strong></td>\n<td>City corporation inspection; fines for breeding sites on premises (mobile courts)</td>\n</tr>\n<tr>\n<td><strong>Personal protection</strong></td>\n<td>Daytime nets for children and patients, repellents, long clothes, screens</td>\n</tr>\n<tr>\n<td><strong>Health education</strong></td>\n<td>Mass media, schools, mosques before and during monsoon</td>\n</tr>\n<tr>\n<td><strong>Intersectoral</strong></td>\n<td>City corporations, DGHS, housing, education, construction regulators</td>\n</tr>\n<tr>\n<td><strong>Research</strong></td>\n<td><em>Wolbachia</em>, insecticide resistance</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology; Epidemiology of Communicable Diseases).</p>"},{"id":"DU.336","n":336,"part":7,"topic":"Arthropod Diseases and Control","stars":1,"years":["10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>Why organo-chlorine compound is not suitable for larvicidal operations?</p>","a":"<p><strong>Why organochlorine compounds (DDT, BHC/lindane, dieldrin) are not suitable for larvicidal operations</strong></p>\n<ol>\n<li><strong>Very persistent</strong> in the environment; do not break down easily.</li>\n<li><strong>Bio-accumulation and bio-magnification</strong> in the food chain (water → plankton → fish → birds and man).</li>\n<li><strong>Highly toxic to fish</strong> and other aquatic non-target organisms, including larvivorous fish used for biological control.</li>\n<li><strong>Contaminate water</strong> sources used for drinking, bathing and fishing; poorly soluble in water.</li>\n<li><strong>Widespread resistance</strong> in mosquito larvae (e.g., <em>Culex</em>, <em>Anopheles</em>).</li>\n<li><strong>Health hazards</strong> in man: neurotoxic; stored in body fat; possible carcinogenic and endocrine effects.</li>\n<li><strong>Banned or restricted</strong> under the Stockholm Convention (2001); DDT allowed only for limited indoor residual spraying.</li>\n</ol>\n<p><strong>Preferred larvicides</strong></p>\n<p>Temephos (Abate; low mammalian toxicity, safe for drinking water at recommended dose), fenthion, mineral oils, <em>Bacillus thuringiensis israelensis</em> (Bti), insect growth regulators (pyriproxyfen, methoprene).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.337","n":337,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":[],"colleges":"MMC (1st Supp C3)","asked":"","note":"","kind":"","sub":"Mosquito","q":"<p>While reading at night in your hostel, some mosquitoes create nuisance. What is the genus of these mosquitoes? Narrate the control measures for these mosquitoes.</p>","a":"<p><strong>Genus</strong></p>\n<p>Night-time biting nuisance mosquitoes in hostels and urban buildings are usually <em><strong>Culex</strong></em> (<em>Culex quinquefasciatus</em>): breeds in dirty, polluted water (drains, septic tanks, cesspits), bites at night, vector of <strong>lymphatic filariasis</strong>.</p>\n<p><strong>Control measures</strong></p>\n<p><strong>A. Anti-larval</strong></p>\n<ol>\n<li><strong>Environmental</strong>: clean and repair drains; remove stagnant polluted water; fill ditches and cesspits; cover septic tanks and manholes; proper sewage disposal; mosquito-proof soak pits.</li>\n<li><strong>Polystyrene beads</strong> floated in pit latrines, cesspools and soak pits (block larval breathing).</li>\n<li><strong>Chemical larvicides</strong>: temephos, fenthion, mineral oil in drains.</li>\n<li><strong>Biological</strong>: larvivorous fish in ponds; <em>Bacillus sphaericus</em>.</li>\n</ol>\n<p><strong>B. Anti-adult</strong></p>\n<ol>\n<li>Space spraying (fogging) with pyrethroids or malathion in heavy infestation.</li>\n<li>Indoor residual spraying where needed.</li>\n</ol>\n<p><strong>C. Personal protection in the hostel</strong></p>\n<p>Bed nets (LLIN), wire-mesh screens on windows and doors, repellent creams, mosquito coils or vaporisers, electric mosquito bats, long-sleeved clothes in the evening.</p>\n<p><strong>D. Administrative and community</strong></p>\n<p>Regular hostel sanitation inspections; student and staff involvement in cleaning drains; coordination with city corporation; health education.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.338","n":338,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["24Nov","22Nov","21M","16Ju","16Ja","14Ja","11Ja","08Ju","04M"],"colleges":"SSMC (1st Supp B1); MuMC (1st Final D3, 1st Supp D2)","asked":"how diseases are transmitted by house fly","note":"","kind":"","sub":"House Fly","q":"<p>Name / list the diseases and health hazards transmitted by housefly (including Musca domestica); how does housefly act as a vector?</p>","a":"<p><strong>Diseases and hazards transmitted by housefly (<em>Musca domestica</em>)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Enteric (faeco-oral)</strong></td>\n<td>Typhoid and paratyphoid, cholera, bacillary dysentery, amoebic dysentery, infantile diarrhoea, gastroenteritis, hepatitis A, poliomyelitis (possible)</td>\n</tr>\n<tr>\n<td><strong>Eye</strong></td>\n<td>Trachoma, conjunctivitis</td>\n</tr>\n<tr>\n<td><strong>Parasitic</strong></td>\n<td>Eggs of roundworm, whipworm, tapeworm; protozoal cysts</td>\n</tr>\n<tr>\n<td><strong>Skin</strong></td>\n<td>Yaws, cutaneous infections; anthrax (rare)</td>\n</tr>\n<tr>\n<td><strong>Myiasis</strong></td>\n<td>Maggots in wounds, nose, ear</td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Tuberculosis bacilli carried; nuisance; food spoilage</td>\n</tr>\n</tbody>\n</table>\n<p><strong>How the housefly acts as a vector (mechanical transmission)</strong></p>\n<ol>\n<li><strong>Habits</strong>: breeds and feeds on filth (faeces, garbage, manure) and then visits human food indiscriminately.</li>\n<li><strong>Carries pathogens on body</strong>: legs, sticky foot pads (pulvilli) and body hairs pick up germs from filth and deposit them on food.</li>\n<li><strong>Vomit drop</strong>: liquefies food by regurgitating saliva and gut contents (containing germs) onto food.</li>\n<li><strong>Faeces</strong>: defecates frequently on food; pathogens survive in its gut.</li>\n<li><strong>Flight</strong>: moves between latrines, garbage and kitchens; large numbers in summer.</li>\n<li>Fast breeding: life cycle (egg → larva → pupa → adult) in about a week in hot weather.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.339","n":339,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["05M","04Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"House Fly","q":"<p>Discuss the measures for control of housefly.</p>","a":"<p><strong>Control of housefly (Park)</strong></p>\n<p><strong>1. Environmental control (most important and permanent)</strong></p>\n<ul>\n<li>Proper <strong>storage, collection and disposal of refuse</strong> (covered bins, daily removal, sanitary landfill, composting).</li>\n<li><strong>Sanitary excreta disposal</strong>; stop open defecation; fly-proof latrines (water seal).</li>\n<li>Sanitary disposal of animal manure; clean cattle sheds.</li>\n<li>Clean markets, slaughter houses and food establishments; general cleanliness.</li>\n</ul>\n<p><strong>2. Insecticidal control</strong></p>\n<ul>\n<li><strong>Residual sprays</strong> on resting surfaces (organophosphates: malathion, diazinon; pyrethroids).</li>\n<li><strong>Space sprays</strong> (pyrethrum, pyrethroids) for quick kill.</li>\n<li><strong>Baits</strong>: sugar or syrup with insecticide.</li>\n<li>Insecticide-impregnated cords and strips.</li>\n<li>Larvicides on breeding material.<br />\n(Flies develop resistance quickly → rotate insecticides.)</li>\n</ul>\n<p><strong>3. Mechanical / physical</strong></p>\n<p>Fly papers, fly traps, electric fly killers.</p>\n<p><strong>4. Protection against flies</strong></p>\n<p><strong>Screening</strong> of kitchens, dining areas, hospitals and food shops; food covers; mosquito-net cupboards.</p>\n<p><strong>5. Health education</strong></p>\n<p>Covering food, cleanliness, safe disposal of waste and faeces, hand-washing.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.340","n":340,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":[],"colleges":"MuMC (1st Final D3, 1st Supp D2)","asked":"","note":"","kind":"","sub":"House Fly","q":"<p>A health worker at his village house noticed some insects with hopping behavior. Identify the insect with its habits.</p>","a":"<p><strong>Identification</strong></p>\n<p>Small insects moving in <strong>short hops</strong> in a village house, especially at night near mud walls and cattle sheds → <strong>sandfly</strong> (<em>Phlebotomus argentipes</em>), vector of <strong>kala-azar</strong>.<br />\n(If the insects jump on people, rats or pets and are wingless, they are <strong>fleas</strong>.)</p>\n<p><strong>Habits of sandfly</strong></p>\n<table>\n<thead>\n<tr>\n<th>Habit</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Appearance</strong></td>\n<td>Very small (1.5–3.5 mm), hairy, yellowish or sandy-coloured; wings held <strong>erect in a V-shape</strong> at rest</td>\n</tr>\n<tr>\n<td><strong>Flight</strong></td>\n<td>Weak fliers; move in <strong>short hops</strong>; short flight range; cannot fly in wind</td>\n</tr>\n<tr>\n<td><strong>Breeding</strong></td>\n<td><strong>Not in water</strong>: moist soil rich in organic matter in <strong>cracks and crevices of mud walls and floors</strong>, cattle sheds, termite hills, rubbish</td>\n</tr>\n<tr>\n<td><strong>Resting</strong></td>\n<td>Dark, humid places: cracks in walls, under furniture, cattle sheds, usually low (below ~2 m)</td>\n</tr>\n<tr>\n<td><strong>Biting</strong></td>\n<td><strong>Night-biters</strong>; only females suck blood; bite exposed skin; silent (no buzzing)</td>\n</tr>\n<tr>\n<td><strong>Host preference</strong></td>\n<td><em>P. argentipes</em> feeds on cattle and humans</td>\n</tr>\n<tr>\n<td><strong>Life cycle</strong></td>\n<td>Egg → larva → pupa → adult (complete metamorphosis; ~1–2 months)</td>\n</tr>\n<tr>\n<td><strong>Season</strong></td>\n<td>More numerous in warm, humid months</td>\n</tr>\n<tr>\n<td><strong>Passage</strong></td>\n<td>Small enough to pass through ordinary mosquito nets</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Diseases</strong>: kala-azar, PKDL (Bangladesh); elsewhere cutaneous leishmaniasis, sandfly fever, Oroya fever.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.341","n":341,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["06M"],"colleges":"","asked":"","note":"","kind":"","sub":"Sand Fly & Louse Infestation","q":"<p>How does mosquito differ from sand fly?</p>","a":"<p><strong>Mosquito vs sandfly</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th>Mosquito</th>\n<th>Sandfly</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Size</td>\n<td>Larger (4–10 mm)</td>\n<td>Very small (1.5–3.5 mm)</td>\n</tr>\n<tr>\n<td>Body covering</td>\n<td>Scales</td>\n<td>Dense <strong>hairs</strong></td>\n</tr>\n<tr>\n<td>Wings at rest</td>\n<td>Lie <strong>flat</strong> over the body</td>\n<td>Held <strong>erect, V-shaped</strong></td>\n</tr>\n<tr>\n<td>Flight</td>\n<td>Strong fliers</td>\n<td>Weak; move in <strong>hops</strong></td>\n</tr>\n<tr>\n<td>Sound</td>\n<td>Buzzing</td>\n<td>Silent</td>\n</tr>\n<tr>\n<td>Proboscis</td>\n<td>Long</td>\n<td>Short</td>\n</tr>\n<tr>\n<td>Breeding</td>\n<td><strong>Water</strong> (aquatic larvae and pupae)</td>\n<td><strong>Moist soil</strong>, cracks and crevices (terrestrial larvae)</td>\n</tr>\n<tr>\n<td>Larva</td>\n<td>Aquatic; breathes at surface</td>\n<td>Caterpillar-like, on land</td>\n</tr>\n<tr>\n<td>Biting time</td>\n<td>Varies by genus (day: <em>Aedes</em>; night: <em>Anopheles</em>, <em>Culex</em>)</td>\n<td>Night</td>\n</tr>\n<tr>\n<td>Net</td>\n<td>Stopped by ordinary nets</td>\n<td>Passes through ordinary nets (needs fine mesh or treated nets)</td>\n</tr>\n<tr>\n<td>Diseases</td>\n<td>Malaria, dengue, chikungunya, filariasis, Japanese encephalitis</td>\n<td>Kala-azar, PKDL, cutaneous leishmaniasis, sandfly fever, Oroya fever</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.342","n":342,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["22Nov","17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Sand Fly & Louse Infestation","q":"<p>Enlist the diseases transmitted by sand flies.</p>","a":"<p><strong>Diseases transmitted by sandflies</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disease</th>\n<th>Agent</th>\n<th>Sandfly</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Kala-azar</strong> (visceral leishmaniasis)</td>\n<td><em>Leishmania donovani</em></td>\n<td><em>Phlebotomus argentipes</em> (Bangladesh, India)</td>\n</tr>\n<tr>\n<td><strong>Post-kala-azar dermal leishmaniasis (PKDL)</strong></td>\n<td><em>L. donovani</em> (sequel)</td>\n<td>Reservoir for further spread</td>\n</tr>\n<tr>\n<td><strong>Cutaneous leishmaniasis</strong> (oriental sore)</td>\n<td><em>L. tropica</em>, <em>L. major</em></td>\n<td><em>Phlebotomus</em> spp.</td>\n</tr>\n<tr>\n<td><strong>Mucocutaneous leishmaniasis</strong> (espundia)</td>\n<td><em>L. braziliensis</em></td>\n<td><em>Lutzomyia</em> (Americas)</td>\n</tr>\n<tr>\n<td><strong>Sandfly fever</strong> (phlebotomus / pappataci fever)</td>\n<td>Phlebovirus</td>\n<td><em>P. papatasi</em></td>\n</tr>\n<tr>\n<td><strong>Oroya fever / Carrion's disease</strong> (bartonellosis)</td>\n<td><em>Bartonella bacilliformis</em></td>\n<td><em>Lutzomyia</em> (South America)</td>\n</tr>\n<tr>\n<td>Chandipura encephalitis</td>\n<td>Chandipura virus</td>\n<td>Sandflies (India)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.343","n":343,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Sand Fly & Louse Infestation","q":"<p>Discuss stages in life history of lice.</p>","a":"<p><strong>Life history of lice</strong></p>\n<p>Lice undergo <strong>incomplete metamorphosis</strong>: Egg (nit) → Nymph (3 moults) → Adult</p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Egg (nit)</strong></td>\n<td>Oval, white; firmly <strong>cemented to hair</strong> (head louse) or to <strong>seams of clothing</strong> (body louse); hatches in about a week</td>\n</tr>\n<tr>\n<td><strong>Nymph</strong></td>\n<td>Resembles a small adult; sucks blood from the start; moults <strong>three times</strong> over about 1–2 weeks</td>\n</tr>\n<tr>\n<td><strong>Adult</strong></td>\n<td>Wingless, flattened dorso-ventrally; 3 pairs of legs with claws for gripping hair or fibres; both sexes suck blood several times a day; lives about a month; female lays a few hundred eggs in her life</td>\n</tr>\n</tbody>\n</table>\n<p>Whole cycle (egg to egg-laying adult): about 2–3 weeks.</p>\n<p><strong>Types of human lice</strong></p>\n<table>\n<thead>\n<tr>\n<th>Louse</th>\n<th>Site</th>\n<th>Importance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Head louse (<em>Pediculus humanus capitis</em>)</td>\n<td>Scalp hair</td>\n<td>Pediculosis capitis; school children</td>\n</tr>\n<tr>\n<td>Body louse (<em>P. h. corporis</em>)</td>\n<td>Clothing seams</td>\n<td><strong>Epidemic typhus</strong>, <strong>relapsing fever</strong>, <strong>trench fever</strong></td>\n</tr>\n<tr>\n<td>Crab louse (<em>Phthirus pubis</em>)</td>\n<td>Pubic hair</td>\n<td>Pediculosis pubis (sexual contact)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Control</strong></p>\n<p>Personal hygiene; washing clothes in hot water; ironing seams; combing with fine-toothed comb; permethrin 1% lotion or other pediculicides; delousing in camps; avoid sharing combs, caps, clothes.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.344","n":344,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["16Ja","13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Sand Fly & Louse Infestation","q":"<p>How to control sand fly in rural community?</p>","a":"<p><strong>Control of sandfly in a rural community</strong></p>\n<p><strong>1. Insecticidal control (main method)</strong></p>\n<ul>\n<li><strong>Indoor residual spraying (IRS)</strong> of houses and <strong>cattle sheds</strong> with synthetic pyrethroids (deltamethrin, alpha-cypermethrin); earlier DDT.</li>\n<li>Spray walls up to about 2 m height (sandflies rest low), cracks, crevices, under furniture.</li>\n<li>Two rounds a year in endemic areas, timed before peak season.</li>\n</ul>\n<p><strong>2. Environmental control (source reduction)</strong></p>\n<ul>\n<li><strong>Plaster cracks and crevices</strong> of mud walls and floors with mud, lime or cement.</li>\n<li>Remove rubbish, vegetation and damp organic matter near houses.</li>\n<li>Keep <strong>cattle sheds away</strong> from human dwellings; improve housing (brick, cement).</li>\n<li>Proper drainage; reduce dampness.</li>\n</ul>\n<p><strong>3. Personal protection</strong></p>\n<ul>\n<li><strong>Insecticide-treated / long-lasting insecticidal nets</strong>; fine-mesh nets.</li>\n<li>Repellents; covering the body at night; sleeping on raised beds (sandflies fly low).</li>\n</ul>\n<p><strong>4. Control of the reservoir (anthroponotic kala-azar)</strong></p>\n<p>Active case detection and prompt treatment of kala-azar and <strong>PKDL</strong> cases.</p>\n<p><strong>5. Community participation and health education</strong></p>\n<p>Awareness of sandfly habits; cooperation with spraying teams; early reporting of fever and splenomegaly.</p>\n<p><strong>6. Surveillance</strong></p>\n<p>Entomological monitoring of sandfly density and insecticide resistance.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.345","n":345,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Fleas and Scabies","q":"<p>Classify fleas of importance in public health with diseases transmitted by them.</p>","a":"<p><strong>Fleas of public health importance</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Species</th>\n<th>Diseases / importance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Rat fleas</strong></td>\n<td><em><strong>Xenopsylla cheopis</strong></em> (oriental rat flea: most important)</td>\n<td><strong>Plague</strong>, <strong>murine (endemic) typhus</strong>, <em>Hymenolepis diminuta</em></td>\n</tr>\n<tr>\n<td></td>\n<td><em>X. astia</em>, <em>X. brasiliensis</em></td>\n<td>Plague (less efficient vectors)</td>\n</tr>\n<tr>\n<td></td>\n<td><em>Nosopsyllus fasciatus</em> (northern rat flea)</td>\n<td>Plague, murine typhus</td>\n</tr>\n<tr>\n<td><strong>2. Human flea</strong></td>\n<td><em>Pulex irritans</em></td>\n<td>Nuisance, dermatitis; plague (minor role)</td>\n</tr>\n<tr>\n<td><strong>3. Cat and dog fleas</strong></td>\n<td><em>Ctenocephalides felis</em>, <em>C. canis</em></td>\n<td>Dog tapeworm (<em>Dipylidium caninum</em>), cat-scratch disease (<em>Bartonella</em>), dermatitis</td>\n</tr>\n<tr>\n<td><strong>4. Sand flea (chigoe)</strong></td>\n<td><em>Tunga penetrans</em></td>\n<td><strong>Tungiasis</strong> (burrows in skin of feet)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Features of fleas</strong></p>\n<p>Wingless, laterally compressed, strong hind legs for <strong>jumping</strong>; both sexes suck blood; complete metamorphosis (egg → larva → pupa → adult).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.346","n":346,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Fleas and Scabies","q":"<p>Discuss habit of rat fleas with disease transmission.</p>","a":"<p><strong>Habits of the rat flea (<em>Xenopsylla cheopis</em>)</strong></p>\n<ol>\n<li><strong>Both sexes are blood feeders</strong>; feed on rats, and on man when rats are not available.</li>\n<li><strong>Leave a dead or dying host</strong> quickly and seek a new one → when rats die of plague, fleas move to humans.</li>\n<li><strong>Jump</strong> onto hosts; live in rat burrows and nests.</li>\n<li><strong>Favourable conditions</strong>: moderate temperature (about 20–25 °C) and high humidity → seasonal plague.</li>\n<li><strong>Survive</strong> for weeks without feeding.</li>\n<li><strong>Eggs</strong> laid in rat nests and burrows; larvae feed on organic debris; complete metamorphosis.</li>\n</ol>\n<p><strong>Disease transmission</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disease</th>\n<th>Mechanism</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Plague</strong> (<em>Yersinia pestis</em>)</td>\n<td>Bacilli multiply in the flea's proventriculus and form a <strong>block</strong> → &quot;<strong>blocked flea</strong>&quot; cannot swallow blood, becomes hungry, bites repeatedly and <strong>regurgitates</strong> infected blood into the bite wound (biological, propagative transmission)</td>\n</tr>\n<tr>\n<td><strong>Murine typhus</strong> (<em>Rickettsia typhi</em>)</td>\n<td>Infected <strong>flea faeces</strong> rubbed into bite wounds or abrasions</td>\n</tr>\n<tr>\n<td><em>Hymenolepis diminuta</em></td>\n<td>Accidental ingestion of infected fleas</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Flea indices (plague surveillance)</strong></p>\n<ul>\n<li><strong>Total flea index</strong>: average number of fleas per rat.</li>\n<li><strong>Specific flea (cheopis) index</strong>: average number of <em>X. cheopis</em> per rat; <strong>&gt;1 indicates danger</strong> of plague outbreak.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.347","n":347,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Fleas and Scabies","q":"<p>Write distinguishing features and types of rodents.</p>","a":"<p><strong>Distinguishing features of rodents (order Rodentia)</strong></p>\n<ol>\n<li><strong>One pair of chisel-shaped incisors</strong> in each jaw that <strong>grow continuously</strong>; worn down by gnawing.</li>\n<li><strong>No canine teeth</strong>; gap (<strong>diastema</strong>) between incisors and molars.</li>\n<li><strong>Gnawing habit</strong>: damage food, buildings, cables.</li>\n<li><strong>High fertility</strong>: breed rapidly, many litters a year.</li>\n<li>Mostly <strong>nocturnal</strong>; omnivorous; can climb, burrow or swim.</li>\n<li>Live close to man (commensal).</li>\n</ol>\n<p><strong>Types of rodents</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Species</th>\n<th>Habits</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Domestic (commensal)</strong></td>\n<td><em>Rattus rattus</em> (black / house / roof rat)</td>\n<td>Slender, pointed snout, large ears, <strong>tail longer than head + body</strong>; good climber; lives in roofs</td>\n</tr>\n<tr>\n<td></td>\n<td><em>Rattus norvegicus</em> (brown / Norway / sewer rat)</td>\n<td>Heavy, blunt snout, small ears, <strong>tail shorter than head + body</strong>; burrows; sewers, drains</td>\n</tr>\n<tr>\n<td></td>\n<td><em>Mus musculus</em> (house mouse)</td>\n<td>Small; in houses and stores</td>\n</tr>\n<tr>\n<td></td>\n<td><em>Bandicota bengalensis</em> (lesser bandicoot)</td>\n<td>Field and urban; burrows; common in Bangladesh</td>\n</tr>\n<tr>\n<td></td>\n<td><em>Bandicota indica</em> (greater bandicoot)</td>\n<td>Large; fields, markets</td>\n</tr>\n<tr>\n<td><strong>Wild (field)</strong></td>\n<td><em>Tatera indica</em> (Indian gerbil)</td>\n<td>Natural reservoir of plague (wild cycle)</td>\n</tr>\n<tr>\n<td></td>\n<td>Squirrels, field mice</td>\n<td>Field reservoirs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.348","n":348,"part":7,"topic":"Arthropod Diseases and Control","stars":0,"years":["04S"],"colleges":"","asked":"","note":"","kind":"","sub":"Fleas and Scabies","q":"<p>What are the main diagnostic features of scabies?</p>","a":"<p><strong>Scabies</strong></p>\n<p>Contagious skin infestation by the <strong>itch mite <em>Sarcoptes scabiei</em> var. <em>hominis</em></strong>; spread by prolonged skin-to-skin contact (family, hostels, madrasas, prisons); fomites in crusted scabies.</p>\n<p><strong>Main diagnostic features</strong></p>\n<ol>\n<li><strong>Intense itching, worse at night</strong> (and after a hot bath).</li>\n<li><strong>Burrows</strong>: thin, greyish, wavy lines 5–15 mm long, with a tiny papule at the end (<strong>pathognomonic</strong>).</li>\n<li><strong>Typical sites</strong>: finger webs, sides of fingers, flexor wrists, elbows, axillary folds, waist, umbilicus, buttocks, around nipples (women), genitalia (penile and scrotal nodules in men). Head and face spared in adults.</li>\n<li><strong>Infants</strong>: palms, soles, face and scalp involved; vesicles and pustules.</li>\n<li><strong>Lesions</strong>: papules, vesicles, excoriations; <strong>secondary bacterial infection</strong> (impetigo, boils) → risk of post-streptococcal glomerulonephritis.</li>\n<li><strong>Several family members</strong> or close contacts itching at the same time.</li>\n<li><strong>Crusted (Norwegian) scabies</strong>: thick crusts with huge mite load in immunocompromised, elderly; little itching.</li>\n</ol>\n<p><strong>Confirmation</strong></p>\n<p>Skin scraping from burrow under microscope (mite, eggs, faecal pellets); burrow ink test; dermoscopy (&quot;delta-wing jet&quot; sign).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.349","n":349,"part":7,"topic":"Arthropod Diseases and Control","stars":3,"years":["16Ju","10Ju","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Fleas and Scabies","q":"<p>How can you prevent and control scabies?</p>","a":"<p><strong>Prevention and control of scabies</strong></p>\n<p><strong>A. Treatment of cases and contacts</strong></p>\n<ol>\n<li>Treat the patient and <strong>all household and close contacts at the same time</strong>, even without symptoms.</li>\n<li>Scabicides:</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Drug</th>\n<th>Use</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Permethrin 5% cream</strong></td>\n<td>First choice; apply from neck to toes (including scalp and face in infants), wash off after 8–12 hours; repeat after 7 days</td>\n</tr>\n<tr>\n<td>Benzyl benzoate 25%</td>\n<td>Adults (diluted for children); apply twice</td>\n</tr>\n<tr>\n<td><strong>Oral ivermectin</strong> (200 µg/kg, two doses 1–2 weeks apart)</td>\n<td>Crusted scabies, mass treatment; not under 15 kg or in pregnancy</td>\n</tr>\n<tr>\n<td>Sulphur ointment (5–10%)</td>\n<td>Infants and pregnant women</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"3\">\n<li>Treat <strong>secondary infection</strong> (antibiotics) and itching (antihistamines).</li>\n</ol>\n<p><strong>B. Measures against re-infestation</strong></p>\n<ol>\n<li><strong>Wash clothes, towels and bedding</strong> in hot water (≥50 °C) and dry in the sun, or seal in a plastic bag for 3 days.</li>\n<li>Do not share clothes, beds, towels.</li>\n<li>Personal hygiene: daily bath, clean clothes.</li>\n</ol>\n<p><strong>C. Community / institutional control</strong></p>\n<ol>\n<li><strong>Mass treatment</strong> in hostels, madrasas, prisons, refugee camps (ivermectin mass drug administration where prevalence is high).</li>\n<li><strong>Health education</strong>: early recognition, treatment of all contacts, hygiene.</li>\n<li>Reduce overcrowding; adequate water supply for washing.</li>\n<li>Screening of new entrants in institutions.</li>\n<li>Avoid stigma; school exclusion only until the day after treatment.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Medical Entomology).</p>"},{"id":"DU.350","n":350,"part":7,"topic":"Arthropod Diseases and Control","stars":1,"years":["10Ju","08Ju","03M"],"colleges":"","asked":"","note":"","kind":"","sub":"Fleas and Scabies","q":"<p>Define source and reservoir with example. How can you describe reservoir of infection for human?</p>","a":"<p><strong>Definitions (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Definition</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Reservoir</strong></td>\n<td>Any person, animal, arthropod, plant, soil or substance (or combination) in which an infectious agent normally <strong>lives and multiplies</strong>, on which it depends for survival, and from which it can be transmitted to a susceptible host</td>\n<td>Man for typhoid; dog for rabies; soil for tetanus</td>\n</tr>\n<tr>\n<td><strong>Source</strong></td>\n<td>The person, animal, object or substance <strong>from which the infectious agent passes</strong> to the host (immediate source)</td>\n<td>Contaminated water or food for typhoid</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Difference (example: hookworm)</strong></p>\n<p>Reservoir = <strong>man</strong> (infected person); source = <strong>soil</strong> contaminated with faeces containing larvae.<br />\nTyphoid: reservoir = case or carrier; source = faeces, urine, contaminated food or water.</p>\n<p><strong>Reservoirs of infection</strong></p>\n<p><strong>1. Human reservoir</strong></p>\n<p>(a) <strong>Cases</strong>: clinical (mild, moderate, severe), subclinical (inapparent), latent infections.<br />\n(b) <strong>Carriers</strong>: infected persons without symptoms who shed the agent.</p>\n<table>\n<thead>\n<tr>\n<th>Classification of carriers</th>\n<th>Types</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>By type</td>\n<td>Incubatory (measles, diphtheria), convalescent (typhoid, cholera), healthy (polio, meningococcus)</td>\n</tr>\n<tr>\n<td>By duration</td>\n<td>Temporary; chronic (typhoid, hepatitis B)</td>\n</tr>\n<tr>\n<td>By portal of exit</td>\n<td>Urinary, intestinal, respiratory, nasal, skin</td>\n</tr>\n</tbody>\n</table>\n<p><strong>2. Animal reservoir (zoonoses)</strong>: rabies (dog), plague (rat), Nipah (bat), anthrax (cattle), avian influenza (poultry).</p>\n<p><strong>3. Non-living reservoir</strong>: soil (tetanus, anthrax spores), water, inanimate matter.</p>\n<p><strong>Importance</strong></p>\n<p>Human reservoirs (especially carriers and subclinical cases) are dangerous because they are hidden and move freely; control of reservoir is the first line of communicable disease control.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.351","n":351,"part":7,"topic":"Sterilization & Disinfection","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you disinfect hospital beddings (mattresses, linen &amp; clothes)?</p>","a":"<p><strong>Disinfection of hospital bedding (mattresses, linen, clothes)</strong></p>\n<p><strong>A. Linen and clothes (bed sheets, pillow covers, patient gowns)</strong></p>\n<ol>\n<li><strong>Handle carefully</strong>: collect in bags at the bedside without shaking; soiled linen in separate, leak-proof, colour-coded bags.</li>\n<li><strong>Steam (autoclave) or boiling</strong>: boil for 30 minutes or steam at 100 °C for 30 minutes.</li>\n<li><strong>Hot-water washing</strong> in a laundry machine: ≥70 °C for at least 25 minutes with detergent.</li>\n<li><strong>Chemical disinfection</strong> (heat-sensitive fabrics): soak in 1% sodium hypochlorite (bleaching solution) or 2% Lysol / phenolic for 30–60 minutes, then wash.</li>\n<li><strong>Sun-drying</strong> and ironing (heat kills remaining organisms).</li>\n<li>Linen soiled with blood or body fluids: wash with cold water first, then disinfect.</li>\n</ol>\n<p><strong>B. Mattresses and pillows</strong></p>\n<ol>\n<li>Use <strong>waterproof (plastic) covers</strong>; wipe with detergent and then 0.5–1% hypochlorite or 70% alcohol after each patient.</li>\n<li>Uncovered mattresses: <strong>steam disinfection</strong> (autoclave chamber) or exposure to sunlight; <strong>formalin vapour</strong> in a closed chamber (older method).</li>\n<li>Heavily contaminated mattresses (e.g., anthrax, plague): <strong>burn</strong>.</li>\n</ol>\n<p><strong>C. Blankets</strong></p>\n<p>Wash with detergent in warm water; or formaldehyde vapour / steam.</p>\n<p><strong>Principles</strong></p>\n<p>Concurrent disinfection during illness; terminal disinfection after discharge or death; protect laundry staff (gloves, aprons, hepatitis B vaccination).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disinfection).</p>"},{"id":"DU.352","n":352,"part":7,"topic":"Sterilization & Disinfection","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you disinfect milk in large scale?</p>","a":"<p><strong>Disinfection of milk on a large scale: pasteurisation</strong></p>\n<p>Heating milk to a temperature and for a time that <strong>destroys all pathogenic organisms</strong> (without boiling), followed by rapid cooling. Named after Louis Pasteur.</p>\n<p><strong>Methods</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Temperature and time</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Holder (vat) method</strong></td>\n<td><strong>63–66 °C for 30 minutes</strong>, then rapid cooling to ≤5 °C</td>\n<td>Older; small dairies</td>\n</tr>\n<tr>\n<td><strong>2. HTST (high temperature short time; flash) method</strong></td>\n<td><strong>72 °C for at least 15 seconds</strong>, then rapid cooling to ≤4 °C</td>\n<td>Most widely used in large dairies</td>\n</tr>\n<tr>\n<td><strong>3. UHT (ultra-high temperature) method</strong></td>\n<td><strong>125 °C for a few seconds</strong> (often 135–150 °C for 1–2 s), then aseptic packing</td>\n<td>Long shelf life without refrigeration</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Tests for efficiency</strong></p>\n<ol>\n<li><strong>Phosphatase test</strong>: alkaline phosphatase (destroyed by proper pasteurisation) should be absent.</li>\n<li><strong>Standard plate count</strong> and <strong>coliform count</strong> (bacteriological quality).</li>\n<li>Methylene blue reduction test (keeping quality).</li>\n</ol>\n<p><strong>Diseases prevented</strong></p>\n<p>TB (bovine), brucellosis, typhoid, Q fever, streptococcal infections, diphtheria, salmonellosis, <em>E. coli</em> infections.</p>\n<p><strong>Domestic method</strong>: boiling.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health; Disinfection).</p>"},{"id":"DU.353","n":353,"part":7,"topic":"Sterilization & Disinfection","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How to sterilize surgical instruments at a satellite clinic in a rural area?</p>","a":"<p><strong>Sterilisation of surgical instruments at a rural satellite clinic</strong></p>\n<p><strong>Step 1: Decontamination</strong></p>\n<p>Soak used instruments in <strong>0.5% chlorine (hypochlorite) solution for 10 minutes</strong> immediately after use → kills HBV, HIV; makes handling safer.</p>\n<p><strong>Step 2: Cleaning</strong></p>\n<p>Scrub with a brush, detergent and water (wear gloves); rinse; dry.</p>\n<p><strong>Step 3: Sterilisation or high-level disinfection (HLD)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Procedure</th>\n<th>Use</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Portable autoclave / pressure cooker</strong> (best)</td>\n<td><strong>121 °C, 15 lb/in² (1 atm) for 20–30 minutes</strong> (wrapped items 30 min)</td>\n<td>Metal instruments, linen, gloves</td>\n</tr>\n<tr>\n<td><strong>Dry heat</strong> (if electricity: hot-air oven)</td>\n<td>160 °C for 2 hours or 170 °C for 1 hour</td>\n<td>Glass, sharp instruments</td>\n</tr>\n<tr>\n<td><strong>Boiling (HLD)</strong></td>\n<td>Boil fully immersed for <strong>20 minutes</strong> from the time water boils, lid closed</td>\n<td>Where no autoclave; kills vegetative bacteria and viruses, not all spores</td>\n</tr>\n<tr>\n<td><strong>Chemical (HLD)</strong></td>\n<td>2% glutaraldehyde for 20 minutes (sterilisation needs 8–10 hours), or 8% formaldehyde</td>\n<td>Heat-sensitive items</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Step 4: Storage</strong></p>\n<p>Dry, covered, sterile container or wrapped packs; use within a week; label with date.</p>\n<p><strong>Additional points</strong></p>\n<p>Use disposable (auto-disable) syringes; safe sharps disposal (safety box); keep a register; train staff; check autoclave with indicator tapes.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disinfection).</p>"},{"id":"DU.354","n":354,"part":7,"topic":"Sterilization & Disinfection","stars":3,"years":["19M","09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the types of disinfection? How are concurrent &amp; terminal disinfection beneficial for prevention of disease transmission?</p>","a":"<p><strong>Types of disinfection (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Concurrent disinfection</strong></td>\n<td>Immediate disinfection of infectious discharges (faeces, urine, sputum, vomit) and articles soiled by them, <strong>during the course of illness</strong></td>\n<td>Disinfecting a cholera patient's stools and linen daily</td>\n</tr>\n<tr>\n<td><strong>2. Terminal disinfection</strong></td>\n<td>Disinfection of the patient's room, furniture, bedding and articles <strong>after the patient has been removed</strong> (recovery, transfer, death) or isolation ends</td>\n<td>Cleaning a TB or COVID-19 isolation room after discharge</td>\n</tr>\n<tr>\n<td><strong>3. Precurrent (prophylactic) disinfection</strong></td>\n<td>Disinfection done in advance to prevent infection</td>\n<td>Chlorination of water, pasteurisation of milk, hand-washing</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Benefits for prevention of transmission</strong></p>\n<p><strong>Concurrent disinfection</strong></p>\n<ol>\n<li>Destroys agents <strong>at the source</strong>, as soon as they leave the body.</li>\n<li>Prevents spread to attendants, family and other patients.</li>\n<li>Reduces environmental contamination (water, flies, fomites).</li>\n<li>Most important type in communicable disease control.</li>\n</ol>\n<p><strong>Terminal disinfection</strong></p>\n<ol>\n<li>Makes the room and articles safe for the <strong>next occupant</strong>.</li>\n<li>Removes residual contamination of surfaces and objects.</li>\n<li>Important for organisms that survive long in the environment (spores, <em>C. difficile</em>, MRSA).</li>\n<li>Today less emphasised than concurrent disinfection; thorough cleaning, airing and sunlight are often enough for most diseases.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disinfection).</p>"},{"id":"DU.355","n":355,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["24M","23Nov","22M","21M","19Nov","17Nov"],"colleges":"ShSMC (1st Term D1); MMC (1st Supp D3)","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by immunity?</p>","a":"<p><strong>Immunity</strong></p>\n<p>The resistance of the body to infections and harmful foreign substances, provided by <strong>specific (adaptive)</strong> and <strong>non-specific (innate)</strong> defence mechanisms, mediated by antibodies and immune cells.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.356","n":356,"part":7,"topic":"Immunity & Immune Response","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by host defense against infection?</p>","a":"<p><strong>Host defence against infection</strong></p>\n<p><strong>A. Non-specific (innate) defences</strong></p>\n<table>\n<thead>\n<tr>\n<th>Line</th>\n<th>Mechanisms</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>First line (barriers)</strong></td>\n<td>Intact skin; mucous membranes and mucus; cilia; cough and sneeze reflexes; tears, saliva (lysozyme); gastric acid; normal flora; urinary flow; vaginal acidity</td>\n</tr>\n<tr>\n<td><strong>Second line</strong></td>\n<td>Phagocytes (neutrophils, macrophages); natural killer cells; complement; interferons; inflammation; fever</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Specific (adaptive) defences</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Mechanism</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Humoral immunity</strong></td>\n<td>B cells → plasma cells → antibodies (IgG, IgM, IgA, IgE, IgD): neutralise toxins and viruses, opsonise bacteria, activate complement</td>\n<td>Protection against tetanus toxin, measles</td>\n</tr>\n<tr>\n<td><strong>Cell-mediated immunity</strong></td>\n<td>T cells: helper (CD4) coordinate; cytotoxic (CD8) kill infected cells; macrophage activation</td>\n<td>Protection against TB, viruses, fungi</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Factors affecting host defence</strong></p>\n<p>Age, nutrition (protein, vitamin A, zinc), genetic factors, hormones, pregnancy, chronic diseases (diabetes, HIV), drugs (steroids, chemotherapy), stress.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.357","n":357,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["23Nov","17Nov","11Ja","09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify immunity with examples.</p>","a":"<p><strong>Classification of immunity (Park)</strong></p>\n<pre><code>Immunity\n├── Innate (non-specific): species, racial, individual\n└── Acquired (specific)\n     ├── Active\n     │    ├── Natural: after clinical or subclinical infection (measles)\n     │    └── Artificial: vaccination (BCG, MR, pentavalent)\n     └── Passive\n          ├── Natural: maternal antibodies via placenta (IgG) and breast milk (IgA)\n          └── Artificial: immunoglobulins / antisera (tetanus immunoglobulin, rabies immunoglobulin, antivenom)\n</code></pre>\n<p><strong>Examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Innate</td>\n<td>Humans do not get canine distemper; sickle-cell trait resists falciparum malaria</td>\n</tr>\n<tr>\n<td>Natural active</td>\n<td>Lifelong immunity after measles</td>\n</tr>\n<tr>\n<td>Artificial active</td>\n<td>Hepatitis B vaccine</td>\n</tr>\n<tr>\n<td>Natural passive</td>\n<td>Newborn protected against measles by maternal IgG for ~6–9 months</td>\n</tr>\n<tr>\n<td>Artificial passive</td>\n<td>HBIG after needle-stick; anti-tetanus serum</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.358","n":358,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["25Nov","22Nov","21M"],"colleges":"SSMC (1st Supp C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between active and passive immunity / how active immunity varies from passive immunity.</p>","a":"<p><strong>Active vs passive immunity</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Active immunity</th>\n<th>Passive immunity</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Production</td>\n<td>Body produces its own antibodies / cells in response to antigen</td>\n<td>Ready-made antibodies given from outside</td>\n</tr>\n<tr>\n<td>Induced by</td>\n<td>Infection (natural) or vaccine (artificial)</td>\n<td>Maternal antibodies (natural) or immunoglobulin / antiserum (artificial)</td>\n</tr>\n<tr>\n<td>Onset</td>\n<td><strong>Slow</strong> (latent period 1–2 weeks or more)</td>\n<td><strong>Immediate</strong></td>\n</tr>\n<tr>\n<td>Duration</td>\n<td><strong>Long-lasting</strong> (years, often lifelong)</td>\n<td><strong>Short</strong> (weeks to months)</td>\n</tr>\n<tr>\n<td>Memory</td>\n<td>Present: booster gives secondary response</td>\n<td>Absent</td>\n</tr>\n<tr>\n<td>Cell-mediated immunity</td>\n<td>Produced</td>\n<td>Not produced</td>\n</tr>\n<tr>\n<td>Negative phase</td>\n<td>May occur</td>\n<td>No</td>\n</tr>\n<tr>\n<td>Adverse reactions</td>\n<td>Usually mild</td>\n<td>Risk of serum sickness, anaphylaxis (animal sera)</td>\n</tr>\n<tr>\n<td>Use</td>\n<td><strong>Prevention</strong> (prophylaxis)</td>\n<td><strong>Immediate protection</strong> (post-exposure, treatment); immunodeficiency</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>BCG, MR, Td vaccines</td>\n<td>Tetanus immunoglobulin, rabies immunoglobulin, HBIG, maternal IgG</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.359","n":359,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss how active immunity can be acquired.</p>","a":"<p><strong>Ways of acquiring active immunity</strong></p>\n<p><strong>A. Naturally acquired</strong></p>\n<ol>\n<li><strong>Following clinical infection</strong>: measles, chickenpox, mumps, smallpox → long-lasting immunity.</li>\n<li><strong>Following subclinical (inapparent) infection</strong>: polio, diphtheria, hepatitis A in childhood → immunity without illness.</li>\n</ol>\n<p><strong>B. Artificially acquired (immunisation)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Antigen type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Live attenuated vaccines</strong></td>\n<td>BCG, OPV, measles-rubella, MMR, varicella, yellow fever, rotavirus</td>\n</tr>\n<tr>\n<td><strong>Inactivated (killed) vaccines</strong></td>\n<td>IPV, rabies, hepatitis A, typhoid (whole-cell), pertussis (whole-cell)</td>\n</tr>\n<tr>\n<td><strong>Toxoids</strong></td>\n<td>Tetanus, diphtheria</td>\n</tr>\n<tr>\n<td><strong>Subunit / recombinant / conjugate vaccines</strong></td>\n<td>Hepatitis B, HPV, Hib, pneumococcal (PCV), typhoid conjugate (TCV)</td>\n</tr>\n<tr>\n<td><strong>Newer platforms</strong></td>\n<td>mRNA and viral-vector vaccines (COVID-19)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Mechanism</strong></p>\n<p>Antigen → presented by antigen-presenting cells → activation of B and T cells → antibodies and effector cells → <strong>memory cells</strong> → rapid secondary response on later exposure.</p>\n<p><strong>Factors affecting response</strong></p>\n<p>Age, nutrition, dose and number of doses, route, adjuvants, immune status, cold chain (vaccine potency).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.360","n":360,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Why is active immunity considered superior to passive immunity?</p>","a":"<p><strong>Why active immunity is superior to passive immunity</strong></p>\n<ol>\n<li><strong>Long-lasting</strong>: years or lifelong, vs weeks to months for passive.</li>\n<li><strong>Immunological memory</strong>: re-exposure or booster produces a rapid, strong secondary response; passive has no memory.</li>\n<li><strong>Both humoral and cell-mediated immunity</strong> are produced; passive gives only antibodies.</li>\n<li><strong>Wider protection</strong>: local (IgA) and systemic immunity; some vaccines (OPV) also block transmission.</li>\n<li><strong>Contributes to herd immunity</strong>.</li>\n<li><strong>Fewer serious reactions</strong>; passive animal sera can cause serum sickness and anaphylaxis.</li>\n<li><strong>Cheaper and practical</strong> for mass prevention programmes (EPI).</li>\n<li>Not destroyed quickly; passive antibodies are catabolised (half-life of IgG ~3 weeks).</li>\n</ol>\n<p><strong>Limitation of active immunity</strong></p>\n<p>Slow onset → in emergencies passive immunity is used first (e.g., rabies, tetanus-prone wounds), often combined with active immunisation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.361","n":361,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["22Nov","22M","19Nov"],"colleges":"SSMC (1st Supp C2)","asked":"","note":"","kind":"","sub":"","q":"<p>How can you categorize / classify immunizing agents?</p>","a":"<p><strong>Classification of immunising agents (Park)</strong></p>\n<p><strong>A. Vaccines</strong> (active immunity)</p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Live attenuated</td>\n<td>BCG, OPV, measles, MR, MMR, yellow fever, varicella, rotavirus, live typhoid (Ty21a)</td>\n</tr>\n<tr>\n<td>Inactivated (killed)</td>\n<td>IPV, rabies, hepatitis A, Japanese encephalitis, whole-cell pertussis</td>\n</tr>\n<tr>\n<td>Subunit / fractions</td>\n<td>Hepatitis B (recombinant), HPV, acellular pertussis, influenza split</td>\n</tr>\n<tr>\n<td>Polysaccharide and conjugate</td>\n<td>Pneumococcal, meningococcal, Hib, typhoid Vi and conjugate</td>\n</tr>\n<tr>\n<td>Toxoids</td>\n<td>Tetanus, diphtheria</td>\n</tr>\n<tr>\n<td>Newer</td>\n<td>mRNA, viral-vector vaccines</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Immunoglobulins</strong> (passive immunity)</p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Normal human immunoglobulin</strong></td>\n<td>Hepatitis A, measles prophylaxis</td>\n</tr>\n<tr>\n<td><strong>Specific (hyperimmune) human immunoglobulins</strong></td>\n<td>Hepatitis B (HBIG), rabies (RIG), tetanus (TIG), varicella-zoster (VZIG), anti-D</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Antisera / antitoxins</strong> (from animals, usually horse)</p>\n<p>Antitetanus serum, antidiphtheritic serum, anti-rabies serum, anti-snake venom, anti-gas gangrene serum.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.362","n":362,"part":7,"topic":"Immunity & Immune Response","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Name five types of immunoglobulins.</p>","a":"<p><strong>Five types of immunoglobulins</strong></p>\n<table>\n<thead>\n<tr>\n<th>Ig</th>\n<th>Main features</th>\n<th>Function</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>IgG</strong></td>\n<td>Most abundant in serum (~75%); monomer; <strong>crosses the placenta</strong></td>\n<td>Long-term immunity; neutralises toxins and viruses; newborn protection; secondary response</td>\n</tr>\n<tr>\n<td><strong>IgM</strong></td>\n<td>Pentamer; largest; first produced</td>\n<td><strong>Primary (early) response</strong>; indicates recent infection; activates complement</td>\n</tr>\n<tr>\n<td><strong>IgA</strong></td>\n<td>In secretions (<strong>breast milk</strong>, saliva, tears, gut and respiratory mucus) as secretory dimer</td>\n<td><strong>Mucosal (local) immunity</strong></td>\n</tr>\n<tr>\n<td><strong>IgE</strong></td>\n<td>Binds mast cells and basophils</td>\n<td><strong>Allergy</strong> (type I hypersensitivity); defence against parasites (helminths)</td>\n</tr>\n<tr>\n<td><strong>IgD</strong></td>\n<td>On surface of B cells</td>\n<td>B-cell activation (antigen receptor)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Mnemonic</strong>: GAMED (G, A, M, E, D).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.363","n":363,"part":7,"topic":"Immunity & Immune Response","stars":0,"years":["05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the types of immune response?</p>","a":"<p><strong>Types of immune response</strong></p>\n<p><strong>A. By mechanism</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Mediated by</th>\n<th>Effective against</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Humoral</strong></td>\n<td>B lymphocytes → antibodies</td>\n<td>Bacteria, toxins, viruses in blood (tetanus, diphtheria, polio)</td>\n</tr>\n<tr>\n<td><strong>Cell-mediated</strong></td>\n<td>T lymphocytes (CD4 helper, CD8 cytotoxic), macrophages</td>\n<td>Intracellular pathogens (TB, leprosy, viruses), fungi, tumours, graft rejection</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. By exposure (sequence)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Primary response</th>\n<th>Secondary (booster / anamnestic) response</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Occurs</td>\n<td>First exposure to antigen</td>\n<td>Re-exposure</td>\n</tr>\n<tr>\n<td>Latent period</td>\n<td>Long (5–10 days or more)</td>\n<td>Short (1–3 days)</td>\n</tr>\n<tr>\n<td>Antibody level</td>\n<td>Low</td>\n<td>High (often 10× or more)</td>\n</tr>\n<tr>\n<td>Main antibody</td>\n<td>IgM, then IgG</td>\n<td>IgG</td>\n</tr>\n<tr>\n<td>Duration</td>\n<td>Short</td>\n<td>Long</td>\n</tr>\n<tr>\n<td>Affinity</td>\n<td>Low</td>\n<td>High</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Innate vs adaptive</strong></p>\n<p>Innate: immediate, non-specific, no memory. Adaptive: delayed, specific, memory.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.364","n":364,"part":7,"topic":"Immunity & Immune Response","stars":0,"years":["10Ja","08Ja","05S","04M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss mechanism of immune response (after vaccination; first-time response to an antigen).</p>","a":"<p><strong>Mechanism of immune response after vaccination (first exposure)</strong></p>\n<p>Vaccine antigen → uptake by antigen-presenting cells → presentation to T cells → B-cell activation → antibodies + memory</p>\n<p><strong>Steps</strong></p>\n<ol>\n<li><strong>Antigen entry</strong>: vaccine given (IM, SC, ID, oral); local inflammation (adjuvant helps).</li>\n<li><strong>Uptake and processing</strong>: dendritic cells and macrophages take up antigen and carry it to regional lymph nodes.</li>\n<li><strong>Presentation</strong>: antigen displayed on MHC molecules to <strong>T-helper (CD4) cells</strong>.</li>\n<li><strong>T-cell activation</strong>: helper cells release cytokines; cytotoxic T cells (CD8) activated (live vaccines).</li>\n<li><strong>B-cell activation</strong>: B cells recognise antigen, receive T-cell help → proliferate → <strong>plasma cells</strong> produce antibodies.</li>\n<li><strong>Primary response</strong>:\n<ul>\n<li>Latent (lag) phase: 5–10 days, no detectable antibody.</li>\n<li><strong>IgM</strong> appears first, then <strong>IgG</strong> rises.</li>\n<li>Antibody level peaks in ~2–3 weeks, then declines.</li>\n</ul>\n</li>\n<li><strong>Memory cells</strong> (B and T) formed; persist for years.</li>\n<li><strong>Negative phase</strong>: brief fall in antibody immediately after antigen (combines with existing antibody).</li>\n</ol>\n<p><strong>On later exposure or booster (secondary response)</strong></p>\n<p>Memory cells → rapid, strong, long-lasting IgG response with high affinity → protection.</p>\n<p><strong>Practical implications</strong></p>\n<p>Multiple doses (primary series) and boosters; minimum interval between doses (4 weeks); protection begins after 2–3 weeks; live vaccines give stronger cell-mediated immunity.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.365","n":365,"part":7,"topic":"Herd Immunity","stars":2,"years":["06S"],"colleges":"SSMC (1st Supp C1); MMC (1st Supp D3)","asked":"write a note on herd immunity","note":"","kind":"","sub":"","q":"<p>Define herd immunity.</p>","a":"<p><strong>Herd immunity</strong></p>\n<p><strong>Definition</strong>: the level of resistance of a <strong>community or group</strong> to the attack of a disease, resulting from the immunity of a large proportion of its members, which <strong>reduces the chance of an infected person meeting a susceptible one</strong>; it protects even non-immune individuals.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.366","n":366,"part":7,"topic":"Herd Immunity","stars":2,"years":["04S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the merits of herd immunity?</p>","a":"<p><strong>Merits (advantages) of herd immunity</strong></p>\n<ol>\n<li><strong>Protects non-immune persons</strong>: newborns too young for vaccination, people with contraindications (immunodeficiency, cancer chemotherapy), vaccine non-responders.</li>\n<li><strong>Interrupts transmission</strong>: epidemics do not occur or are small.</li>\n<li><strong>Makes elimination and eradication possible</strong> (smallpox eradicated without vaccinating everyone; polio eradication).</li>\n<li><strong>Cost-effective</strong>: full coverage of every individual is not required (except tetanus).</li>\n<li><strong>Reduces disease burden</strong> and deaths in the whole community.</li>\n<li><strong>Indirect protection of high-risk groups</strong> (elderly protected by vaccinating children against pneumococcus and influenza).</li>\n<li><strong>Reduces antibiotic use</strong> and resistance.</li>\n<li>Basis for planning <strong>coverage targets</strong> in immunisation programmes.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.367","n":367,"part":7,"topic":"Herd Immunity","stars":0,"years":["11Ja","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the elements of herd immunity or herd structure?</p>","a":"<p><strong>Elements of herd immunity (herd structure) (Park)</strong></p>\n<p>Herd immunity depends on:</p>\n<ol>\n<li><strong>Occurrence of clinical and subclinical infections</strong> in the herd (natural immunity).</li>\n<li><strong>Immunisation</strong> of the herd (vaccination coverage).</li>\n<li><strong>Herd structure</strong>, which is constantly changing:\n<ul>\n<li><strong>Births</strong>: new susceptibles enter.</li>\n<li><strong>Deaths</strong>: immune persons leave.</li>\n<li><strong>Migration</strong>: entry or exit of susceptible or immune persons.</li>\n</ul>\n</li>\n</ol>\n<p>Also influenced by: presence and distribution of <strong>alternative animal hosts</strong>; environmental factors favouring spread (crowding); social factors.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.368","n":368,"part":7,"topic":"Herd Immunity","stars":3,"years":["26M","11Ja"],"colleges":"MuMC (1st Final A3, 1st Supp A3)","asked":"how does herd immunity develop?","note":"","kind":"","sub":"","q":"<p>How can herd immunity be attained?</p>","a":"<p><strong>How herd immunity is attained (developed)</strong></p>\n<ol>\n<li><strong>Natural infection</strong>: clinical and subclinical infections in the community give immunity (e.g., polio, hepatitis A in childhood); but with illness and deaths.</li>\n<li><strong>Immunisation (best and safest)</strong>:\n<ul>\n<li>High, sustained <strong>routine coverage</strong> (EPI) above the threshold (e.g., ≥95% for measles with two doses).</li>\n<li><strong>Supplementary campaigns</strong> (NIDs, MR campaigns) to close immunity gaps.</li>\n<li>Reaching <strong>all areas and groups</strong> equally (no pockets of unvaccinated).</li>\n<li>Vaccines that block <strong>transmission</strong> (OPV, MR, PCV).</li>\n</ul>\n</li>\n<li><strong>Maintaining herd structure</strong>: vaccinate newborns promptly; vaccinate migrants and catch-up for missed children.</li>\n<li><strong>Good cold chain and vaccine quality</strong> for real protection.</li>\n<li><strong>Surveillance</strong> to detect immunity gaps and outbreaks.</li>\n</ol>\n<p><strong>Example</strong></p>\n<p>Smallpox eradication; Bangladesh polio-free status through high OPV coverage and NIDs.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.369","n":369,"part":7,"topic":"Herd Immunity","stars":0,"years":[],"colleges":"ShSMC (2nd Term D1)","asked":"","note":"","kind":"","sub":"","q":"<p>Why does measles require a higher population immunity level than many other vaccine-preventable diseases?</p>","a":"<p><strong>Why measles needs higher population immunity</strong></p>\n<ol>\n<li><strong>Extremely contagious</strong>: basic reproduction number (R₀) about <strong>12–18</strong> (one case infects 12–18 susceptibles), among the highest of all infections.</li>\n<li>Herd immunity threshold = 1 − 1/R₀ → about <strong>92–95%</strong> immunity needed (vs ~80–86% for polio).</li>\n<li><strong>Airborne spread</strong>: virus stays in air and on surfaces for up to 2 hours; spreads in rooms after the patient leaves.</li>\n<li><strong>Infectious before rash</strong> (4 days before to 4 days after rash) → spread before diagnosis.</li>\n<li><strong>Almost all infections are clinical</strong> (no large subclinical immune pool from silent infection in vaccinated era).</li>\n<li><strong>Vaccine efficacy</strong>: one dose at 9 months protects ~85%, two doses ~95%+ → two doses and very high coverage needed.</li>\n<li><strong>Maternal antibody</strong> interferes before 9 months → infants are an unprotected group.</li>\n<li>Rapid accumulation of susceptibles (births, missed doses) → outbreaks every few years when coverage falls (e.g., Bangladesh's large 2026 outbreak after first-dose coverage fell to 86% in 2023).</li>\n</ol>\n<p><strong>Implication</strong></p>\n<p>Two doses (MR at 9 and 15 months) with <strong>≥95% coverage</strong> in every district, plus periodic campaigns.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); IANS, Sept 2026, https://ianslive.in/measles-outbreak-in-bangladesh-kills-over-1000-in-6-months-as-vaccination-gaps-persist-report--20260915143141</p>"},{"id":"DU.370","n":370,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["18Nov","17Nov","12Ju"],"colleges":"ShSMC (1st Term D1)","asked":"","note":"","kind":"","sub":"","q":"<p>Classify vaccine with examples.</p>","a":"<p><strong>Classification of vaccines</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Nature</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Live attenuated</strong></td>\n<td>Weakened live organisms</td>\n<td>BCG, OPV, measles, MR, MMR, yellow fever, varicella, rotavirus, oral typhoid (Ty21a)</td>\n</tr>\n<tr>\n<td><strong>2. Inactivated (killed)</strong></td>\n<td>Whole organisms killed by heat or chemicals</td>\n<td>IPV (Salk), rabies (cell culture), hepatitis A, whole-cell pertussis, Japanese encephalitis, cholera (oral killed)</td>\n</tr>\n<tr>\n<td><strong>3. Toxoids</strong></td>\n<td>Inactivated toxins</td>\n<td>Tetanus toxoid, diphtheria toxoid (Td)</td>\n</tr>\n<tr>\n<td><strong>4. Subunit / recombinant</strong></td>\n<td>Purified antigens or proteins</td>\n<td>Hepatitis B (recombinant), HPV, acellular pertussis, influenza split</td>\n</tr>\n<tr>\n<td><strong>5. Polysaccharide</strong></td>\n<td>Capsular polysaccharide</td>\n<td>Pneumococcal PPSV23, meningococcal, typhoid Vi</td>\n</tr>\n<tr>\n<td><strong>6. Conjugate</strong></td>\n<td>Polysaccharide linked to protein carrier (works in infants)</td>\n<td>Hib, PCV10/13, meningococcal conjugate, typhoid conjugate (TCV)</td>\n</tr>\n<tr>\n<td><strong>7. Newer</strong></td>\n<td>Nucleic acid / vector</td>\n<td>mRNA (COVID-19), viral-vector (COVID-19, Ebola)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other classifications</strong></p>\n<ul>\n<li>By number of antigens: monovalent (BCG), combined (pentavalent: DPT-HepB-Hib; MR).</li>\n<li>By route: oral (OPV), intradermal (BCG, fIPV), subcutaneous (MR), intramuscular (pentavalent, PCV).</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.371","n":371,"part":7,"topic":"Vaccine, Immunization & NID","stars":2,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Name live vaccines.</p>","a":"<p><strong>Live (attenuated) vaccines</strong></p>\n<p><strong>Bacterial</strong></p>\n<ol>\n<li><strong>BCG</strong> (tuberculosis)</li>\n<li>Oral typhoid vaccine (Ty21a)</li>\n<li>Oral cholera (live, CVD 103-HgR; not used in Bangladesh EPI)</li>\n</ol>\n<p><strong>Viral</strong></p>\n<ol>\n<li><strong>Oral polio vaccine (OPV / bOPV)</strong></li>\n<li><strong>Measles</strong>, <strong>measles-rubella (MR)</strong>, MMR</li>\n<li>Mumps, rubella</li>\n<li><strong>Yellow fever</strong> (17D)</li>\n<li><strong>Varicella</strong> (chickenpox), zoster (live)</li>\n<li><strong>Rotavirus</strong></li>\n<li>Live Japanese encephalitis (SA 14-14-2)</li>\n<li>Live influenza (nasal)</li>\n<li>Dengue (some live attenuated vaccines)</li>\n</ol>\n<p><strong>In Bangladesh EPI</strong>: BCG, bOPV, MR.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.372","n":372,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["18M"],"colleges":"MuMC (1st Final A3, 1st Supp A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Live vaccines are superior to inactivated vaccine – justify.</p>","a":"<p><strong>Live vaccines are superior to inactivated vaccines: justification</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Live vaccine</th>\n<th>Inactivated vaccine</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Multiplication in host</td>\n<td>Yes → natural-like infection</td>\n<td>No</td>\n</tr>\n<tr>\n<td>Number of doses</td>\n<td>Usually <strong>one</strong> (or few)</td>\n<td>Several doses + boosters</td>\n</tr>\n<tr>\n<td>Duration of immunity</td>\n<td><strong>Long-lasting</strong>, often lifelong</td>\n<td>Shorter; boosters needed</td>\n</tr>\n<tr>\n<td>Type of immunity</td>\n<td><strong>Humoral + cell-mediated</strong> + local (IgA)</td>\n<td>Mainly humoral</td>\n</tr>\n<tr>\n<td>Local / mucosal immunity</td>\n<td>Yes (OPV gives gut IgA; blocks transmission)</td>\n<td>Little</td>\n</tr>\n<tr>\n<td>Herd effect</td>\n<td>Strong (OPV spreads to contacts)</td>\n<td>Weaker</td>\n</tr>\n<tr>\n<td>Dose of antigen</td>\n<td>Small</td>\n<td>Large</td>\n</tr>\n<tr>\n<td>Adjuvant</td>\n<td>Not needed</td>\n<td>Often needed</td>\n</tr>\n<tr>\n<td>Cost</td>\n<td>Usually cheaper</td>\n<td>Often costlier</td>\n</tr>\n<tr>\n<td>Route</td>\n<td>Natural route possible (oral, nasal)</td>\n<td>Injection</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Limitations of live vaccines (to be balanced)</strong></p>\n<p>Need strict <strong>cold chain</strong>; risk in <strong>immunocompromised</strong> and pregnancy; rare reversion to virulence (vaccine-derived poliovirus); interference by maternal antibodies.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.373","n":373,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["25Nov","19M"],"colleges":"DMC (1st Assess C5)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the complications of a live vaccine? Mention the adverse effects following immunization.</p>","a":"<p><strong>Complications of live vaccines</strong></p>\n<ol>\n<li><strong>Vaccine-induced disease</strong> in immunocompromised persons (disseminated BCG; vaccine measles).</li>\n<li><strong>Reversion to virulence</strong>: vaccine-associated paralytic polio (VAPP) and circulating vaccine-derived poliovirus (cVDPV) with OPV.</li>\n<li><strong>Mild disease-like reactions</strong>: fever and rash 5–12 days after measles vaccine; mild parotitis after mumps; arthralgia after rubella (adult women).</li>\n<li><strong>Local reactions</strong>: BCG ulcer, abscess, regional lymphadenitis.</li>\n<li><strong>Contamination</strong> with other agents (rare; quality failures).</li>\n<li><strong>Fetal risk</strong> (theoretical) in pregnancy (rubella, yellow fever).</li>\n<li>Toxic shock syndrome from contaminated reconstituted vial used beyond 6 hours (measles: programme error).</li>\n<li>Allergy (gelatin, egg in some vaccines).</li>\n</ol>\n<p><strong>Adverse events following immunisation (AEFI): types (WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Vaccine product-related reaction</td>\n<td>Fever, local pain, BCG lymphadenitis, febrile seizure, anaphylaxis</td>\n</tr>\n<tr>\n<td>2. Vaccine quality defect-related</td>\n<td>Due to manufacturing defect</td>\n</tr>\n<tr>\n<td>3. <strong>Immunisation error-related</strong> (programme error)</td>\n<td>Abscess (unsterile injection), toxic shock (contaminated reconstituted vaccine), wrong vaccine or diluent</td>\n</tr>\n<tr>\n<td>4. Immunisation anxiety-related</td>\n<td>Fainting, hyperventilation</td>\n</tr>\n<tr>\n<td>5. Coincidental event</td>\n<td>Illness unrelated to vaccine</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Common minor reactions</strong>: pain, swelling, redness, fever, irritability.<br />\n<strong>Serious</strong>: anaphylaxis, encephalopathy, seizures, death (rare) → report and investigate.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.374","n":374,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the contra-indications of live vaccines. State ring immunization.</p>","a":"<p><strong>Contraindications of live vaccines</strong></p>\n<ol>\n<li><strong>Immunodeficiency</strong>: congenital immunodeficiency, symptomatic HIV/AIDS (BCG not given to symptomatic HIV-infected infants), leukaemia, lymphoma, other malignancies.</li>\n<li><strong>Immunosuppressive therapy</strong>: high-dose corticosteroids, anti-cancer drugs, radiotherapy, transplant drugs.</li>\n<li><strong>Pregnancy</strong> (rubella, MMR, varicella, yellow fever; theoretical fetal risk).</li>\n<li><strong>Severe allergic reaction</strong> (anaphylaxis) to a previous dose or vaccine component.</li>\n<li><strong>Severe acute illness</strong> with high fever: postpone (minor illness is not a contraindication).</li>\n<li>Recent <strong>blood transfusion or immunoglobulin</strong> (interferes with measles, MR): delay by 3 months or more.</li>\n<li>Another live injectable vaccine within the past 4 weeks (unless given on the same day).</li>\n</ol>\n<p><strong>Not contraindications (false contraindications)</strong></p>\n<p>Mild fever, cold, diarrhoea, malnutrition, prematurity, breastfeeding, mild local reaction after previous dose.</p>\n<p><strong>Ring immunisation</strong></p>\n<p>Vaccination of all <strong>susceptible contacts around a case</strong> (household, neighbours, the surrounding &quot;ring&quot;) to create a barrier of immune people and stop spread of an outbreak.</p>\n<ul>\n<li>Used in <strong>smallpox eradication</strong> (surveillance–containment strategy).</li>\n<li>Also used in Ebola outbreaks and some measles and polio outbreak responses.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology; Epidemiology of Communicable Diseases).</p>"},{"id":"DU.375","n":375,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["25M","24Nov","21M","20Nov","15Ja","14Ja","12Ju","12Ja","11Ja","09Ja"],"colleges":"DMC (1st Assess C5); SSMC (2nd Term C1); MMC (1st Supp D2); MuMC (1st Final A4)","asked":"classify EPI diseases with dose schedule; U1A4 asked as: vaccine name, doses, route and age of administration","note":"","kind":"","sub":"","q":"<p>Mention the vaccines with dose used in EPI schedule / state (write down) the (updated, WHO recommended) EPI vaccination schedule under 1 year of age in Bangladesh.</p>","a":"<p><strong>EPI schedule for infants in Bangladesh (under 1 year and second year)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Age</th>\n<th>Vaccine</th>\n<th>Dose and route</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>At birth (as early as possible)</strong></td>\n<td><strong>BCG</strong></td>\n<td>0.05 ml intradermal, left upper arm</td>\n</tr>\n<tr>\n<td><strong>6 weeks</strong></td>\n<td><strong>Pentavalent-1</strong> (DPT-HepB-Hib)</td>\n<td>0.5 ml IM, anterolateral thigh</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>bOPV-1</strong></td>\n<td>2 drops oral</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>PCV-1</strong> (pneumococcal conjugate)</td>\n<td>0.5 ml IM, thigh</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>fIPV-1</strong> (fractional inactivated polio)</td>\n<td>0.1 ml intradermal, right upper arm</td>\n</tr>\n<tr>\n<td><strong>10 weeks</strong></td>\n<td>Pentavalent-2, bOPV-2, PCV-2</td>\n<td>As above</td>\n</tr>\n<tr>\n<td><strong>14 weeks</strong></td>\n<td>Pentavalent-3, bOPV-3</td>\n<td>As above</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>fIPV-2</strong></td>\n<td>0.1 ml intradermal</td>\n</tr>\n<tr>\n<td><strong>18 weeks</strong></td>\n<td><strong>PCV-3</strong></td>\n<td>0.5 ml IM</td>\n</tr>\n<tr>\n<td><strong>9 months</strong></td>\n<td><strong>MR-1</strong> (measles-rubella)</td>\n<td>0.5 ml subcutaneous, right upper arm</td>\n</tr>\n<tr>\n<td><strong>15 months</strong></td>\n<td><strong>MR-2</strong></td>\n<td>0.5 ml subcutaneous</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Minimum interval</strong> between doses of the same vaccine: 4 weeks.</p>\n<p><strong>Women (15–49 years)</strong>: <strong>TT/Td</strong> 5 doses (1st at first contact; 2nd after ≥4 weeks; 3rd after ≥6 months; 4th after ≥1 year; 5th after ≥1 year) → lifelong protection against maternal and neonatal tetanus.</p>\n<p><strong>Adolescent girls</strong>: <strong>HPV</strong> vaccine (cervical cancer prevention).</p>\n<p><strong>Diseases covered</strong>: tuberculosis, diphtheria, pertussis, tetanus, hepatitis B, <em>Haemophilus influenzae</em> type b, poliomyelitis, pneumococcal disease, measles, rubella (+ HPV).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology; Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.376","n":376,"part":7,"topic":"Vaccine, Immunization & NID","stars":0,"years":["20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is BCG plus?</p>","a":"<p><strong>BCG plus</strong></p>\n<p>BCG vaccination given <strong>without prior tuberculin (Mantoux) testing</strong> to all eligible children; any child who develops an <strong>accelerated (Koch's) reaction</strong> is then investigated for tuberculosis.</p>\n<p><strong>Basis</strong></p>\n<ul>\n<li><strong>Direct BCG vaccination</strong> (without tuberculin test) is safe and cheap; pre-testing is costly and delays coverage.</li>\n<li>In a person already infected with TB, BCG produces an <strong>accelerated reaction</strong>: induration within 2–3 days and ulceration within about a week (instead of 2–3 weeks).</li>\n<li>So BCG acts as a <strong>diagnostic aid</strong> (&quot;plus&quot;) for detecting TB infection.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.377","n":377,"part":7,"topic":"Vaccine, Immunization & NID","stars":0,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the side effects of BCG vaccine?</p>","a":"<p><strong>Normal reaction after BCG</strong></p>\n<p>2–3 weeks: small papule → enlarges (4–8 mm) → <strong>ulcerates</strong> at about 5–6 weeks → heals in 6–12 weeks leaving a small <strong>scar</strong> (evidence of vaccination). No dressing or antiseptic needed.</p>\n<p><strong>Side effects / complications</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Prolonged severe ulceration</strong></td>\n<td>Large ulcer persisting &gt;3 months</td>\n</tr>\n<tr>\n<td><strong>Suppurative (BCG) lymphadenitis</strong></td>\n<td>Enlarged, sometimes discharging, axillary or cervical nodes (more with excess dose or subcutaneous injection)</td>\n</tr>\n<tr>\n<td><strong>Abscess</strong></td>\n<td>Cold abscess at the site (usually from deep / subcutaneous injection: programme error)</td>\n</tr>\n<tr>\n<td><strong>Keloid</strong></td>\n<td>Overgrown scar, more if injected higher on the shoulder</td>\n</tr>\n<tr>\n<td><strong>Lupoid reaction</strong></td>\n<td>Rare skin reaction</td>\n</tr>\n<tr>\n<td><strong>Disseminated BCG infection (BCG-osis)</strong></td>\n<td>Very rare; in immunodeficient children (SCID, symptomatic HIV)</td>\n</tr>\n<tr>\n<td><strong>Osteitis / osteomyelitis</strong></td>\n<td>Very rare</td>\n</tr>\n<tr>\n<td><strong>Accelerated (Koch's) reaction</strong></td>\n<td>In already infected children (basis of BCG plus)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.378","n":378,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is NID?</p>","a":"<p><strong>NID (National Immunisation Day)</strong></p>\n<p>A supplementary immunisation activity in which <strong>all children of a target age group</strong> (usually <strong>under 5 years</strong>) are given an extra dose of <strong>oral polio vaccine (OPV)</strong> across the whole country <strong>on the same day(s)</strong>, <strong>regardless of previous vaccination status</strong>; usually two rounds 4–6 weeks apart in the low-transmission (cool, dry) season.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.379","n":379,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["23Nov","14Ju","12Ju","10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How does NID / immunization contribute to eradicate poliomyelitis? Identify the epidemiological basis / approach of poliomyelitis eradication.</p>","a":"<p><strong>Epidemiological basis of polio eradication</strong></p>\n<ol>\n<li><strong>Man is the only reservoir</strong>; no animal or environmental reservoir.</li>\n<li><strong>No long-term carrier state</strong>; virus survives in environment only for short periods.</li>\n<li><strong>Effective, cheap, oral vaccine (OPV)</strong> that induces <strong>gut (mucosal) immunity</strong> → blocks transmission; easy to give (drops) by volunteers.</li>\n<li>OPV virus spreads to contacts → <strong>indirect immunisation</strong> (herd effect).</li>\n<li>Immunity after infection or vaccination is long-lasting.</li>\n<li><strong>Seasonal</strong> transmission → campaigns timed in low season.</li>\n<li>Good diagnostic tools (stool culture) and <strong>AFP surveillance</strong> to find every case.</li>\n</ol>\n<p><strong>Strategies (WHO) and how NIDs contribute</strong></p>\n<table>\n<thead>\n<tr>\n<th>Strategy</th>\n<th>Contribution</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. High routine immunisation coverage</strong> (OPV/IPV)</td>\n<td>Builds baseline immunity</td>\n</tr>\n<tr>\n<td><strong>2. Supplementary immunisation: NIDs and sub-NIDs</strong></td>\n<td>Extra OPV doses to all under-5s on the same day → closes immunity gaps, displaces wild virus in gut with vaccine virus, <strong>interrupts transmission</strong> simultaneously across the country</td>\n</tr>\n<tr>\n<td><strong>3. AFP surveillance</strong> with lab confirmation</td>\n<td>Detects any circulating virus; target non-polio AFP rate ≥2/100,000 under-15s</td>\n</tr>\n<tr>\n<td><strong>4. Mop-up campaigns</strong></td>\n<td>House-to-house OPV in areas where virus is found</td>\n</tr>\n<tr>\n<td><strong>Environmental surveillance</strong> (sewage testing)</td>\n<td>Detects silent circulation</td>\n</tr>\n<tr>\n<td><strong>Switch from tOPV to bOPV + IPV</strong></td>\n<td>Reduces vaccine-derived polio risk</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Result</strong></p>\n<p>Wild polio type 2 and type 3 eradicated globally; Bangladesh polio-free.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.380","n":380,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["25Nov","24M","22Nov","19Nov","18Nov","17Nov","10Ja"],"colleges":"SSMC (1st Supp C2); MMC (1st Supp D3)","asked":"how cold chain is maintained at different levels in our country","note":"","kind":"","sub":"","q":"<p>State cold chain system. What is cold chain? What are its components? How is it maintained at national level / at different levels of health care service?</p>","a":"<p><strong>Cold chain</strong></p>\n<p>A system of <strong>storing and transporting vaccines at recommended temperatures</strong> from the point of manufacture to the point of use (child).</p>\n<p><strong>Components</strong></p>\n<ol>\n<li><strong>Personnel</strong>: trained staff to manage vaccines and equipment.</li>\n<li><strong>Equipment</strong>: walk-in coolers and freezers, ice-lined refrigerators (ILR), deep freezers, solar refrigerators, cold boxes, <strong>vaccine carriers</strong>, ice packs, thermometers, temperature loggers, freeze indicators.</li>\n<li><strong>Procedures</strong>: correct storage, handling, transport, monitoring, maintenance, stock management.</li>\n</ol>\n<p><strong>Temperature requirements</strong></p>\n<table>\n<thead>\n<tr>\n<th>Vaccine</th>\n<th>Storage</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Most EPI vaccines (BCG, pentavalent, PCV, IPV, MR, Td, HPV)</td>\n<td><strong>+2 to +8 °C</strong>; <strong>do not freeze</strong> (pentavalent, PCV, IPV, Td, HepB damaged by freezing)</td>\n</tr>\n<tr>\n<td>OPV</td>\n<td>Freezer (−15 to −25 °C) at central/regional stores; +2 to +8 °C at service level</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Cold chain at different levels (Bangladesh)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Equipment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>National (central) store (EPI HQ, Dhaka)</td>\n<td>Walk-in coolers and freezers</td>\n</tr>\n<tr>\n<td>Divisional / district stores</td>\n<td>Walk-in coolers, ILRs, deep freezers</td>\n</tr>\n<tr>\n<td>Upazila (UHC)</td>\n<td>ILRs, deep freezers (ice packs), cold boxes</td>\n</tr>\n<tr>\n<td>Union / outreach sites</td>\n<td><strong>Vaccine carriers</strong> with conditioned ice packs</td>\n</tr>\n<tr>\n<td>Session</td>\n<td>Vaccine carrier; opened vials on a foam pad</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Maintenance</strong></p>\n<p>Twice-daily temperature recording; vaccine vial monitor (VVM) checks; shake test for freeze damage; &quot;earliest expiry, first out&quot;; open-vial policy; generator / solar back-up.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.381","n":381,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["25M","24Nov","20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is the importance of cold chain? Why is cold chain important for vaccines?</p>","a":"<p><strong>Importance of cold chain</strong></p>\n<ol>\n<li>Vaccines are <strong>biological products</strong> that lose <strong>potency</strong> when exposed to heat (live vaccines: BCG, OPV, MR) or <strong>freezing</strong> (pentavalent, PCV, IPV, Td, hepatitis B).</li>\n<li><strong>Loss of potency is irreversible</strong>; once lost, it cannot be restored by cooling again.</li>\n<li>Damaged vaccines <strong>look normal</strong> → children receive impotent vaccine → <strong>vaccine failure</strong> and outbreaks, loss of trust.</li>\n<li>Ensures <strong>effectiveness</strong> of the immunisation programme and herd immunity.</li>\n<li>Prevents <strong>wastage</strong> of costly vaccines.</li>\n<li>Frozen adsorbed vaccines can cause <strong>sterile abscesses</strong>.</li>\n<li>Needed to reach remote areas safely (vaccine carriers, ice packs).</li>\n</ol>\n<p><strong>Monitoring tools</strong></p>\n<p>Thermometers, data loggers, <strong>vaccine vial monitor (VVM)</strong>, freeze indicators, <strong>shake test</strong>.</p>\n<p><strong>Sensitivity</strong></p>\n<table>\n<thead>\n<tr>\n<th>Most heat-sensitive</th>\n<th>Most freeze-sensitive</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>OPV, MR (reconstituted), BCG</td>\n<td>Hepatitis B, pentavalent, Td, PCV, IPV</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.382","n":382,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>In a slum among 5000 population there are 500 children of 0-12 month age group. Only 50 infants in the slum are vaccinated against tetanus. Calculate prevalence of T.T. vaccination among slum infants.</p>","a":"<p><strong>Calculation</strong></p>\n<p>Prevalence (proportion) of TT vaccination among slum infants<br />\n= (number of infants vaccinated ÷ total infants) × 100</p>\n<p><strong>Given</strong></p>\n<p>Infants (0–12 months) = 500; infants vaccinated against tetanus = 50; total population 5,000 (not needed).</p>\n<p><strong>Result</strong></p>\n<p>(50 ÷ 500) × 100 = <strong>10%</strong></p>\n<p><strong>Interpretation</strong></p>\n<p>Only 1 in 10 infants is protected; coverage is very low. (Note: infants are protected against tetanus through the <strong>pentavalent</strong> vaccine; TT/Td is given to women of childbearing age to prevent neonatal tetanus. The low figure calls for urgent catch-up vaccination and strengthening of EPI in the slum.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.383","n":383,"part":7,"topic":"Vaccine, Immunization & NID","stars":3,"years":["24M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the principles of autoclaving.</p>","a":"<p><strong>Autoclaving</strong></p>\n<p>Sterilisation by <strong>steam under pressure</strong>; the most reliable method for sterilising instruments, linen, dressings and culture media.</p>\n<p><strong>Principles</strong></p>\n<ol>\n<li><strong>Raised boiling point under pressure</strong>: at 15 lb/in² (1 atmosphere above normal), water boils at <strong>121 °C</strong>.</li>\n<li><strong>Moist heat kills by coagulation and denaturation of proteins</strong>, more efficient than dry heat at lower temperature.</li>\n<li><strong>Latent heat</strong>: when steam condenses on cooler articles, it releases a large amount of heat → rapid heating.</li>\n<li><strong>Contraction in volume</strong> on condensation draws more steam into the load → penetration into porous materials.</li>\n<li><strong>Removal of air</strong> is essential: air–steam mixtures have lower temperature; air pockets prevent sterilisation.</li>\n<li><strong>Time–temperature relationship</strong>:</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Temperature</th>\n<th>Pressure</th>\n<th>Holding time</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>121 °C</td>\n<td>15 lb/in²</td>\n<td>15–20 minutes (wrapped loads ~30 minutes)</td>\n</tr>\n<tr>\n<td>134 °C</td>\n<td>30 lb/in²</td>\n<td>3–4 minutes</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"7\">\n<li>Kills <strong>all</strong> microorganisms including <strong>bacterial spores</strong>.</li>\n</ol>\n<p><strong>Not suitable for</strong></p>\n<p>Heat-sensitive plastics, oils, powders.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disinfection).</p>"},{"id":"DU.384","n":384,"part":7,"topic":"Vaccine, Immunization & NID","stars":0,"years":[],"colleges":"MMC (1st Supp D2)","asked":"","note":"","kind":"","sub":"","q":"<p>A five-months pregnant woman came to you for TT vaccination; she did not take any TT vaccine earlier. What measures will you take for her?</p>","a":"<p><strong>Management of a 5-month pregnant woman with no previous TT/Td</strong></p>\n<p><strong>A. Tetanus immunisation</strong></p>\n<ol>\n<li>Give <strong>TT/Td-1 now</strong> (0.5 ml IM, deltoid).</li>\n<li>Give <strong>TT/Td-2 at least 4 weeks later</strong>, ideally <strong>at least 2 weeks before delivery</strong> → protects mother and newborn against tetanus.</li>\n<li>Complete the <strong>5-dose schedule</strong> after delivery: TT3 ≥6 months after TT2; TT4 ≥1 year after TT3; TT5 ≥1 year after TT4 → lifelong protection.</li>\n<li>Record on the TT card; explain the importance.</li>\n</ol>\n<p><strong>B. Antenatal care (same visit)</strong></p>\n<ol>\n<li>Full history and examination: weight, BP, pallor, oedema, fundal height, fetal heart.</li>\n<li>Investigations: Hb, blood group and Rh, urine for protein and sugar, blood sugar, HBsAg, syphilis test; ultrasound.</li>\n<li><strong>Iron-folic acid</strong> and <strong>calcium</strong> supplements; <strong>deworming</strong> (after first trimester).</li>\n<li>Nutrition counselling: extra meal, iodised salt.</li>\n<li>Plan <strong>at least 8 ANC contacts</strong> (WHO); identify danger signs (bleeding, headache, convulsions, fever, reduced fetal movement).</li>\n<li><strong>Birth preparedness</strong>: facility delivery with skilled attendant; transport and money plan.</li>\n<li>Clean delivery and <strong>cord care</strong> (chlorhexidine), early breastfeeding.</li>\n<li>Health education on family planning after delivery.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.385","n":385,"part":7,"topic":"Vaccine, Immunization & NID","stars":0,"years":[],"colleges":"MuMC (1st Final A4)","asked":"","note":"","kind":"","sub":"","q":"<p>Why can’t measles vaccine be given before 9 months of age?</p>","a":"<p><strong>Why measles vaccine is not given before 9 months</strong></p>\n<ol>\n<li><strong>Maternal antibodies</strong> (IgG) transferred across the placenta persist in the infant for about 6–9 months.</li>\n<li>These antibodies <strong>neutralise the live attenuated vaccine virus</strong> → vaccine virus cannot multiply → <strong>poor seroconversion</strong> (vaccine failure).</li>\n<li>At 9 months most infants have lost maternal antibody → seroconversion ~85%; at 12–15 months ~95% → hence a <strong>second dose at 15 months</strong> (MR-2).</li>\n<li>The <strong>immune system</strong> of young infants is also less mature, giving weaker responses.</li>\n<li>9 months is a <strong>compromise</strong> in developing countries: early enough to protect before the high-risk age of measles (many cases occur in the second half of infancy), late enough for good response.</li>\n</ol>\n<p><strong>Exception</strong></p>\n<p>During <strong>outbreaks</strong>, in humanitarian settings or for HIV-exposed infants, an extra dose may be given from <strong>6 months</strong>; this dose is not counted, and routine doses at 9 and 15 months are still given.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.386","n":386,"part":7,"topic":"Vaccine, Immunization & NID","stars":0,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"SEQ","sub":"","q":"<p>A 3 months old baby was brought to health centre with high grade fever and excessive crying. The child received the pentavalent vaccine a few hours back as a schedule EPI.</p>\n<ul>\n<li>a) Mention the name of this situation.</li>\n<li>b) Mention the cause of this problem.</li>\n<li>c) What is the management of this situation?</li>\n</ul>","a":"<p><strong>a) Name of the situation</strong></p>\n<p><strong>Adverse event following immunisation (AEFI)</strong>: a <strong>vaccine product-related reaction</strong> (common, minor systemic reaction) after pentavalent (DPT-HepB-Hib) vaccine: high fever and persistent crying.</p>\n<p><strong>b) Cause</strong></p>\n<ol>\n<li><strong>Pertussis (whole-cell) component</strong> of pentavalent vaccine is the main cause of fever, irritability and <strong>persistent inconsolable crying</strong> (≥3 hours) within 24–48 hours.</li>\n<li>Local inflammation at injection site (pain, swelling).</li>\n<li>Rule out <strong>immunisation error</strong> (wrong dose, wrong route, contamination → abscess, toxic shock) and <strong>coincidental illness</strong> (infection, meningitis).</li>\n</ol>\n<p><strong>c) Management</strong></p>\n<ol>\n<li><strong>Reassure</strong> the mother: usually mild, self-limiting within 1–2 days.</li>\n<li><strong>Examine</strong> the child: temperature, injection site, hydration, signs of serious illness (convulsion, hypotonia, bulging fontanelle, rash).</li>\n<li><strong>Paracetamol</strong> (10–15 mg/kg/dose, 6-hourly as needed).</li>\n<li><strong>Tepid sponging</strong>; light clothing; adequate fluids.</li>\n<li><strong>Continue breastfeeding</strong>.</li>\n<li>Cold compress at the injection site if painful; do not massage.</li>\n<li><strong>Watch for danger signs</strong>: convulsions, high-pitched cry, unresponsiveness, hypotonic–hyporesponsive episode, anaphylaxis → urgent referral.</li>\n<li><strong>Record and report</strong> the AEFI (AEFI form) to the EPI supervisor / UH&amp;FPO; investigate if serious or clustered.</li>\n<li><strong>Next dose</strong>: continue the schedule; whole-cell pertussis is contraindicated only after encephalopathy within 7 days or anaphylaxis.</li>\n<li>Advise the mother to return if symptoms persist beyond 48 hours.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.387","n":387,"part":8,"topic":"Demography & Fertility","stars":3,"years":["22Nov","20Nov","12Ju"],"colleges":"SSMC (2nd Term B1); MuMC (2nd Final C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define demography.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Demography</strong>: the scientific study of <strong>human population</strong>, focusing on (1) <strong>changes in population size</strong> (growth or decline), (2) the <strong>composition</strong> of the population (age, sex, marital status, education, occupation) and (3) the <strong>distribution</strong> of population in space (Park).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.388","n":388,"part":8,"topic":"Demography & Fertility","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What information may be gathered together from demographic data?</p>","a":"<p><strong>Information obtained from demographic data</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Information</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Size</strong></td>\n<td>Total population; growth rate; density</td>\n</tr>\n<tr>\n<td><strong>Composition (structure)</strong></td>\n<td>Age and sex structure (population pyramid); sex ratio; dependency ratio; marital status; religion; ethnicity</td>\n</tr>\n<tr>\n<td><strong>Distribution</strong></td>\n<td>Urban–rural; regional; migration patterns; urbanisation</td>\n</tr>\n<tr>\n<td><strong>Fertility</strong></td>\n<td>CBR, GFR, TFR, age-specific fertility, NRR</td>\n</tr>\n<tr>\n<td><strong>Mortality</strong></td>\n<td>CDR, IMR, U5MR, MMR, life expectancy, causes of death</td>\n</tr>\n<tr>\n<td><strong>Social characteristics</strong></td>\n<td>Literacy and education, occupation, family size and type, household size</td>\n</tr>\n<tr>\n<td><strong>Economic characteristics</strong></td>\n<td>Income, employment, labour force</td>\n</tr>\n<tr>\n<td><strong>Housing and amenities</strong></td>\n<td>Housing type, water, sanitation, electricity</td>\n</tr>\n<tr>\n<td><strong>Trends and projections</strong></td>\n<td>Future population, ageing, demographic dividend</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.389","n":389,"part":8,"topic":"Demography & Fertility","stars":3,"years":["25M","24M","22M","20Nov","14Ju","11Ju"],"colleges":"MMC (2nd Term B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the five processes of demography / what are the processes that influence demographic changes?</p>","a":"<p><strong>Five demographic processes (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Process</th>\n<th>Effect on population</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Fertility</strong></td>\n<td>Adds to population (births)</td>\n</tr>\n<tr>\n<td><strong>2. Mortality</strong></td>\n<td>Reduces population (deaths)</td>\n</tr>\n<tr>\n<td><strong>3. Marriage</strong></td>\n<td>Influences fertility (age at marriage, proportion married)</td>\n</tr>\n<tr>\n<td><strong>4. Migration</strong></td>\n<td>Changes size and distribution (in-migration, out-migration, urbanisation)</td>\n</tr>\n<tr>\n<td><strong>5. Social mobility</strong></td>\n<td>Movement between social classes; affects fertility, education, occupation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Population change equation</strong></p>\n<p>Population change = (Births − Deaths) + (In-migrants − Out-migrants)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.390","n":390,"part":8,"topic":"Demography & Fertility","stars":3,"years":["24Nov","24M","23Nov","22Nov","21M","19Nov","18Nov","17Nov","17M","17Ja","16Ju","15Ja","14Ja","13Ja","12Ja","08Ja","06Ja"],"colleges":"DMC (2nd Assess B2); SSMC (2nd Term B1); MuMC (2nd Final C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention / describe / illustrate the stages of demography (demographic cycle); discuss demographic transition; demographic process in context of Bangladesh.</p>","a":"<p><strong>Demographic cycle (Blacker): five stages</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Birth rate</th>\n<th>Death rate</th>\n<th>Growth</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. High stationary</strong></td>\n<td>High</td>\n<td>High</td>\n<td>Stationary (balanced)</td>\n<td>Pre-industrial societies; India until 1920</td>\n</tr>\n<tr>\n<td><strong>2. Early expanding</strong></td>\n<td>High</td>\n<td><strong>Begins to fall</strong></td>\n<td>Rapid increase</td>\n<td>Many sub-Saharan countries</td>\n</tr>\n<tr>\n<td><strong>3. Late expanding</strong></td>\n<td><strong>Begins to fall</strong></td>\n<td>Falls further (low)</td>\n<td>Increases, but more slowly</td>\n<td><strong>Bangladesh</strong>, India</td>\n</tr>\n<tr>\n<td><strong>4. Low stationary</strong></td>\n<td>Low</td>\n<td>Low</td>\n<td>Stationary or slow</td>\n<td>Many developed countries (Denmark)</td>\n</tr>\n<tr>\n<td><strong>5. Declining</strong></td>\n<td><strong>Lower than death rate</strong></td>\n<td>Low</td>\n<td>Population <strong>declines</strong></td>\n<td>Japan, Germany, some East European countries</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Demographic transition</strong></p>\n<p>Shift from high birth and death rates to low birth and death rates with socio-economic development. Death rate falls first (better nutrition, sanitation, vaccines, medical care); birth rate falls later (education, urbanisation, family planning) → the gap produces rapid growth.</p>\n<p><strong>Bangladesh in context</strong></p>\n<ol>\n<li>Death rate has fallen sharply (CDR 6.1/1000; life expectancy 72.3 years, SVRS 2023).</li>\n<li>Fertility has fallen to near replacement (TFR 2.17, SVRS 2023) through family planning, female education and later marriage.</li>\n<li>Bangladesh is in the <strong>late expanding stage</strong>, moving toward low stationary.</li>\n<li>Large young working-age population → <strong>demographic dividend</strong>; ageing rising (65+ about 6% in 2023).</li>\n<li>Population still grows because of <strong>population momentum</strong> (many young people entering reproductive age).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning); BBS SVRS 2023 (The Financial Express, 2024), https://today.thefinancialexpress.com.bd/print/life-expectancy-falls-in-bd-bbs-1724781053</p>"},{"id":"DU.391","n":391,"part":8,"topic":"Demography & Fertility","stars":3,"years":["18Nov","18M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between developed and developing countries (in respect of demographic characteristics).</p>","a":"<p><strong>Developed vs developing countries: demographic characteristics</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th>Developed countries</th>\n<th>Developing countries</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Birth rate</td>\n<td>Low</td>\n<td>High (falling)</td>\n</tr>\n<tr>\n<td>Death rate</td>\n<td>Low</td>\n<td>Moderate to low (falling)</td>\n</tr>\n<tr>\n<td>Growth rate</td>\n<td>Low, zero or negative</td>\n<td>High to moderate</td>\n</tr>\n<tr>\n<td>Stage of demographic cycle</td>\n<td>Low stationary / declining</td>\n<td>Early or late expanding</td>\n</tr>\n<tr>\n<td>Age structure</td>\n<td><strong>Old</strong>: few children, many elderly</td>\n<td><strong>Young</strong>: many children and young adults</td>\n</tr>\n<tr>\n<td>Population pyramid</td>\n<td>Narrow base, broad top, nearly vertical sides</td>\n<td>Broad base, narrow top</td>\n</tr>\n<tr>\n<td>Dependency ratio</td>\n<td>High <strong>old-age</strong> dependency</td>\n<td>High <strong>child</strong> dependency</td>\n</tr>\n<tr>\n<td>Life expectancy</td>\n<td>High (80+ years)</td>\n<td>Lower (but rising)</td>\n</tr>\n<tr>\n<td>IMR, MMR</td>\n<td>Very low</td>\n<td>Higher</td>\n</tr>\n<tr>\n<td>TFR</td>\n<td>Below replacement (&lt;2.1)</td>\n<td>Higher (above or near replacement)</td>\n</tr>\n<tr>\n<td>Sex ratio</td>\n<td>More women in older ages</td>\n<td>Variable; sometimes fewer women</td>\n</tr>\n<tr>\n<td>Urbanisation</td>\n<td>High</td>\n<td>Lower but rising fast</td>\n</tr>\n<tr>\n<td>Disease pattern</td>\n<td>Mainly NCDs</td>\n<td>Double burden: infections + NCDs</td>\n</tr>\n<tr>\n<td>Literacy</td>\n<td>High</td>\n<td>Lower</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.392","n":392,"part":8,"topic":"Demography & Fertility","stars":3,"years":["26M","25Nov","24Nov","19Nov","17M"],"colleges":"DMC (2nd Assess B2)","asked":"draw an age-sex pyramid of Bangladesh","note":"","kind":"","sub":"","q":"<p>What are the characteristics of a population pyramid? Draw and interpret an age-sex pyramid of a developing country. Compare the pyramids of developing and developed countries.</p>","a":"<p><strong>Population (age–sex) pyramid</strong></p>\n<p>A graphic presentation of the age and sex composition of a population: horizontal bars for 5-year age groups, males on the left, females on the right; length shows number or percentage.</p>\n<p><strong>Characteristics</strong></p>\n<ol>\n<li>Shows <strong>age structure</strong> and <strong>sex ratio</strong> at a glance.</li>\n<li>Reflects past <strong>fertility, mortality and migration</strong>.</li>\n<li><strong>Shape</strong> indicates the stage of demographic transition.</li>\n<li>Predicts future growth, dependency and service needs.</li>\n</ol>\n<p><strong>Pyramid of a developing country (e.g., Bangladesh in past decades)</strong></p>\n<pre><code>           Male | Female\n   70+          ▌|▐\n   60–69       ▐█|█▌\n   50–59      ▐██|██▌\n   40–49     ▐███|███▌\n   30–39    ▐████|████▌\n   20–29   ▐█████|█████▌\n   10–19  ▐██████|██████▌\n   0–9   ▐███████|███████▌\n</code></pre>\n<p><strong>Interpretation</strong></p>\n<ol>\n<li><strong>Broad base</strong>: high birth rate; many children.</li>\n<li><strong>Rapid narrowing upward</strong>: high mortality at all ages; low life expectancy.</li>\n<li><strong>Narrow top</strong>: few elderly.</li>\n<li>High <strong>child dependency ratio</strong>; young population; built-in <strong>population momentum</strong>.</li>\n<li>Bangladesh today: base <strong>narrowing</strong> (falling fertility) and a <strong>bulge in ages 15–34</strong> (youth bulge) → demographic dividend phase.</li>\n</ol>\n<p><strong>Developing vs developed pyramids</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th>Developing</th>\n<th>Developed</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Shape</td>\n<td>Triangular (expansive)</td>\n<td>Beehive / rectangular or inverted base (constrictive)</td>\n</tr>\n<tr>\n<td>Base</td>\n<td>Broad</td>\n<td>Narrow</td>\n</tr>\n<tr>\n<td>Top</td>\n<td>Narrow</td>\n<td>Broad</td>\n</tr>\n<tr>\n<td>Sides</td>\n<td>Concave, tapering fast</td>\n<td>Nearly vertical</td>\n</tr>\n<tr>\n<td>Meaning</td>\n<td>High fertility, high mortality, young population</td>\n<td>Low fertility, low mortality, ageing population</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.393","n":393,"part":8,"topic":"Demography & Fertility","stars":3,"years":["22M","19Nov","07Ja"],"colleges":"ShSMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"","q":"<p>How can growth rate be calculated? Calculate growth rate of Bangladesh.</p>","a":"<p><strong>Growth rate</strong></p>\n<p><strong>1. Rate of natural increase (RNI)</strong></p>\n<p>RNI = Crude birth rate − Crude death rate (per 1,000 population)<br />\nGrowth rate (%) = (CBR − CDR) ÷ 10</p>\n<p><strong>2. Overall (actual) growth rate</strong></p>\n<p>Growth rate = [(Births − Deaths) + (Immigrants − Emigrants)] ÷ mid-year population × 100</p>\n<p><strong>3. From two censuses (annual exponential growth rate)</strong></p>\n<p>r = [ln(Pₜ ÷ P₀) ÷ t] × 100, where P₀ and Pₜ are populations at two censuses t years apart.</p>\n<p><strong>4. Doubling time</strong></p>\n<p>Doubling time (years) ≈ 70 ÷ growth rate (%).</p>\n<p><strong>Calculation for Bangladesh (method, with illustrative values)</strong></p>\n<p>If CBR = 18 per 1,000 and CDR = 6 per 1,000:<br />\nRNI = 18 − 6 = 12 per 1,000 = <strong>1.2% per year</strong><br />\nDoubling time ≈ 70 ÷ 1.2 ≈ <strong>58 years</strong><br />\n(Substitute the latest SVRS/census CBR and CDR in the same formula; Bangladesh's CDR was 6.1 per 1,000 in SVRS 2023.)</p>\n<p><strong>Interpretation</strong></p>\n<p>Growth has slowed with falling fertility, but the absolute increase is still large because of the big young population (population momentum).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.394","n":394,"part":8,"topic":"Demography & Fertility","stars":3,"years":["22Nov","19Nov","15Ja","10Ju"],"colleges":"SSMC (2nd Term A4)","asked":"factors influencing fertility","note":"","kind":"","sub":"","q":"<p>List the causes / discuss the factors of high fertility in Bangladesh / factors influencing the process of fertility.</p>","a":"<p><strong>Factors influencing fertility (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Age at marriage</strong></td>\n<td>Early marriage → longer reproductive span → higher fertility</td>\n</tr>\n<tr>\n<td><strong>2. Duration of married life</strong></td>\n<td>Longer → more children</td>\n</tr>\n<tr>\n<td><strong>3. Spacing of children</strong></td>\n<td>Short birth intervals → more births</td>\n</tr>\n<tr>\n<td><strong>4. Education</strong> (especially female)</td>\n<td>Higher education → later marriage, more contraception, fewer children</td>\n</tr>\n<tr>\n<td><strong>5. Economic status</strong></td>\n<td>Poverty → children seen as earners and old-age security → high fertility</td>\n</tr>\n<tr>\n<td><strong>6. Religion and caste</strong></td>\n<td>Beliefs about family size and contraception</td>\n</tr>\n<tr>\n<td><strong>7. Nutrition</strong></td>\n<td>Indirect effects on fecundity</td>\n</tr>\n<tr>\n<td><strong>8. Family planning</strong></td>\n<td>Use of contraception → lower fertility</td>\n</tr>\n<tr>\n<td><strong>9. Other</strong></td>\n<td>Child mortality (replacement births), son preference, urbanisation, women's employment, status of women</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Causes of (past) high fertility in Bangladesh</strong></p>\n<ol>\n<li><strong>Early marriage</strong> of girls; adolescent pregnancy.</li>\n<li><strong>Son preference</strong>.</li>\n<li><strong>High infant and child mortality</strong> (insurance births).</li>\n<li><strong>Poverty</strong>; children as economic assets and old-age security.</li>\n<li><strong>Low female education</strong> and employment; low status of women.</li>\n<li><strong>Religious and cultural beliefs</strong>; joint-family pressure.</li>\n<li><strong>Unmet need for family planning</strong>; limited method choice; rumours about side effects.</li>\n<li><strong>Rural residence</strong>; poor access to services in hard-to-reach areas.</li>\n<li>Low male involvement in family planning.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.395","n":395,"part":8,"topic":"Demography & Fertility","stars":3,"years":["16Ja","13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How could high fertility of Bangladesh be reduced?</p>","a":"<p><strong>Reducing fertility in Bangladesh</strong></p>\n<p><strong>A. Family planning services</strong></p>\n<ol>\n<li>Ensure <strong>availability and choice</strong> of methods (pills, condoms, injectables, IUD, implants, permanent methods).</li>\n<li><strong>Long-acting reversible and permanent methods</strong> promotion.</li>\n<li><strong>Postpartum and post-abortion family planning</strong>.</li>\n<li>Door-to-door services by <strong>FWAs</strong>, satellite clinics, community clinics; urban slums.</li>\n<li>Reduce <strong>unmet need</strong> and discontinuation; good counselling; manage side effects.</li>\n<li>Adolescent-friendly services.</li>\n</ol>\n<p><strong>B. Socio-economic measures</strong></p>\n<ol>\n<li><strong>Prevent child marriage</strong>: enforce Child Marriage Restraint Act 2017 (girls 18, boys 21 years).</li>\n<li><strong>Female education</strong>: stipends, keep girls in school.</li>\n<li><strong>Women's employment and empowerment</strong>.</li>\n<li><strong>Reduce child mortality</strong> (EPI, nutrition) → less need for &quot;insurance&quot; births.</li>\n<li>Poverty reduction; social security for old age.</li>\n<li>Urbanisation and better living standards.</li>\n</ol>\n<p><strong>C. Behaviour change communication</strong></p>\n<p>Mass media, community leaders, imams, folk media; small-family norm; male involvement; correct rumours.</p>\n<p><strong>D. Policy and programme</strong></p>\n<p>Strong political commitment; population policy; integration of FP with MCH services; incentives and compensation for permanent methods; supply chain for contraceptives; monitoring by surveys.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.396","n":396,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"SSMC (2nd Term A4)","asked":"","note":"","kind":"","sub":"","q":"<p>Define fertility.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Fertility</strong>: the <strong>actual bearing of children</strong> (number of live births) by a woman or a population.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.397","n":397,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"DMC (2nd Assess B4)","asked":"","note":"","kind":"","sub":"","q":"<p>Explain demographic dividend.</p>","a":"<p><strong>Demographic dividend</strong></p>\n<p>The <strong>economic growth potential</strong> that arises when, after a fall in fertility, the <strong>working-age population (15–64 years)</strong> becomes large relative to the dependent population (children and elderly).</p>\n<p><strong>How it arises</strong></p>\n<p>Fall in death rate → fall in birth rate → fewer children, large cohort of young adults → low dependency ratio → &quot;<strong>window of opportunity</strong>&quot; (temporary, a few decades)</p>\n<p><strong>Benefits (if used well)</strong></p>\n<ol>\n<li>More workers and producers per dependent.</li>\n<li>Higher savings and investment.</li>\n<li>More women can join the workforce (fewer children).</li>\n<li>More resources per child for health and education.</li>\n<li>Faster economic growth (East Asian example).</li>\n</ol>\n<p><strong>Requirements to realise it</strong></p>\n<p>Quality <strong>education and skills</strong>; <strong>health</strong> and nutrition of youth; <strong>jobs</strong> for young people; <strong>women's participation</strong>; good governance, savings and investment.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.398","n":398,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"ShSMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"","q":"<p>Why is TFR preferred to crude birth rate for comparing fertility between populations?</p>","a":"<p><strong>Why TFR is preferred to CBR for comparing fertility</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Crude birth rate (CBR)</th>\n<th>Total fertility rate (TFR)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Denominator</td>\n<td><strong>Whole population</strong> (men, children, elderly included)</td>\n<td>Based on <strong>women of reproductive age</strong> (age-specific rates)</td>\n</tr>\n<tr>\n<td>Effect of age–sex structure</td>\n<td><strong>Strongly affected</strong>: a young population gives a high CBR even with low fertility per woman</td>\n<td><strong>Not affected</strong>: sum of age-specific fertility rates (a standardised measure)</td>\n</tr>\n<tr>\n<td>Meaning</td>\n<td>Births per 1,000 population</td>\n<td><strong>Average number of children per woman</strong> over her reproductive life</td>\n</tr>\n<tr>\n<td>Comparison</td>\n<td>Misleading between populations with different structures</td>\n<td><strong>Valid</strong> comparison between countries, regions and over time</td>\n</tr>\n<tr>\n<td>Use in policy</td>\n<td>General</td>\n<td>Directly shows <strong>replacement level</strong> (≈2.1)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Reasons (summary)</strong></p>\n<ol>\n<li>Independent of age and sex composition.</li>\n<li>Easy to interpret (children per woman).</li>\n<li>Directly linked to population replacement.</li>\n<li>Good for monitoring family planning programmes.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.399","n":399,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"ShSMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"","q":"<p>What does a TFR of 2.1 approximately indicate in a population with low mortality?</p>","a":"<p><strong>TFR of 2.1: replacement-level fertility</strong></p>\n<p>In a population with low mortality, a TFR of about <strong>2.1</strong> means each woman, on average, has just enough children to <strong>replace herself and her partner</strong>.</p>\n<ol>\n<li><strong>2 children</strong> replace the two parents.</li>\n<li>The extra <strong>0.1</strong> allows for:\n<ul>\n<li><strong>More boys than girls at birth</strong> (sex ratio ~105 boys per 100 girls).</li>\n<li>Some <strong>girls dying before reaching reproductive age</strong>.</li>\n</ul>\n</li>\n<li>Equivalent to <strong>NRR = 1</strong> (each woman replaced by one daughter who survives to childbearing age).</li>\n<li>If sustained, the population becomes <strong>stationary</strong> in the long run (no growth from natural increase, ignoring migration).</li>\n<li>Population may still grow for decades due to <strong>population momentum</strong> (large young cohorts).</li>\n<li>In high-mortality populations, replacement TFR is higher (2.5–3 or more).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.400","n":400,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"MMC (2nd Term B4)","asked":"","note":"","kind":"","sub":"","q":"<p>What is population explosion?</p>","a":"<p><strong>Population explosion</strong></p>\n<p>A <strong>very rapid increase in population</strong> occurring when <strong>death rates fall sharply</strong> (better sanitation, vaccines, antibiotics, food supply) while <strong>birth rates remain high</strong>; seen in the early and late expanding stages of the demographic cycle.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.401","n":401,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"MuMC (2nd Final C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define NRR (net reproduction rate).</p>","a":"<p><strong>Net reproduction rate (NRR)</strong></p>\n<p>The <strong>average number of daughters a newborn girl will bear during her lifetime</strong>, assuming she experiences the current <strong>age-specific fertility rates and age-specific mortality rates</strong> (Park).</p>\n<p><strong>Interpretation</strong></p>\n<table>\n<thead>\n<tr>\n<th>NRR</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>= 1</strong></td>\n<td><strong>Replacement level</strong>: each generation of mothers exactly replaces itself → population becomes stationary in the long run</td>\n</tr>\n<tr>\n<td>&gt; 1</td>\n<td>Population will grow</td>\n</tr>\n<tr>\n<td>&lt; 1</td>\n<td>Population will decline in the long run</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.402","n":402,"part":8,"topic":"Demography & Fertility","stars":0,"years":[],"colleges":"ShSMC (2nd Term C5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>Country A has a crude birth rate of 38/1000 and crude death rate of 8/1000. Country B has a crude birth rate of 12/1000 and crude death rate of 10/1000. Country A has a rapidly growing young population, whereas Country B has an increasing proportion of elderly people. [2+2.5+2.5]</p>\n<ul>\n<li>a) Calculate the natural increase rate for both countries and identify which country has the greater natural population increase. (2)</li>\n<li>b) Explain three demographic consequences expected in Country A. (2.5)</li>\n<li>c) Explain three major demographic challenges expected in Country B. (2.5)</li>\n</ul>","a":"<p><strong>a) Natural increase rate (2)</strong></p>\n<p>Rate of natural increase (RNI) = CBR − CDR</p>\n<table>\n<thead>\n<tr>\n<th>Country</th>\n<th>CBR</th>\n<th>CDR</th>\n<th>RNI (per 1,000)</th>\n<th>Growth rate (%)</th>\n<th>Doubling time</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>A</td>\n<td>38</td>\n<td>8</td>\n<td><strong>30</strong></td>\n<td><strong>3.0%</strong></td>\n<td>≈70 ÷ 3 ≈ 23 years</td>\n</tr>\n<tr>\n<td>B</td>\n<td>12</td>\n<td>10</td>\n<td><strong>2</strong></td>\n<td><strong>0.2%</strong></td>\n<td>≈70 ÷ 0.2 ≈ 350 years</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Country A</strong> has the greater natural increase (15 times that of B).</p>\n<p><strong>b) Demographic consequences in Country A (2.5)</strong></p>\n<ol>\n<li><strong>Young age structure</strong>: broad-based pyramid; large child population; high <strong>child dependency ratio</strong>.</li>\n<li><strong>Rapid population growth and momentum</strong>: population doubles in about 23 years; growth continues even if fertility falls.</li>\n<li><strong>Pressure on services and resources</strong>: schools, health care (MCH, immunisation), food, housing, jobs; urbanisation and slums.</li>\n<li>High demand for <strong>family planning and MCH</strong> services; risk of high maternal and child mortality.</li>\n<li>Future <strong>demographic dividend</strong> possible if fertility falls and youth are educated and employed; otherwise unemployment and poverty.</li>\n</ol>\n<p><strong>c) Demographic challenges in Country B (2.5)</strong></p>\n<ol>\n<li><strong>Population ageing</strong>: rising proportion of elderly; high <strong>old-age dependency ratio</strong>.</li>\n<li><strong>Shrinking workforce</strong>: labour shortages; dependence on immigrant workers; slower economic growth.</li>\n<li><strong>Health-care burden</strong>: NCDs, disability, dementia, need for long-term and palliative care; higher costs.</li>\n<li><strong>Pension and social security</strong> pressure on a smaller working population.</li>\n<li>Possible <strong>population decline</strong> (fertility below replacement); more deaths than births in future; feminisation of old age; loneliness and need for elderly care.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.403","n":403,"part":8,"topic":"Maternal and Child Health","stars":0,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the new concept of MCH care.</p>","a":"<p><strong>New concept of MCH care</strong></p>\n<p><strong>Traditional MCH</strong>: promotive, preventive, curative and rehabilitative care for mothers (pregnancy, childbirth) and children, with emphasis on maternal and infant mortality.</p>\n<p><strong>New (current) concept</strong></p>\n<ol>\n<li><strong>Mother and child as one unit</strong>; care of the family as a whole (<strong>family health</strong>).</li>\n<li><strong>Reproductive and Child Health (RCH)</strong> approach (after ICPD Cairo, 1994): adds family planning, safe abortion, RTI/STI, adolescent health and gender issues.</li>\n<li><strong>Continuum of care (RMNCAH+N)</strong>:\n<ul>\n<li><strong>Across the life cycle</strong>: pre-pregnancy → pregnancy → childbirth → postnatal → newborn → childhood → adolescence → adulthood.</li>\n<li><strong>Across places</strong>: home → community → health facility (referral).</li>\n</ul>\n</li>\n<li><strong>Risk approach</strong>: special care for high-risk mothers and children while giving basic care to all.</li>\n<li><strong>Integrated services</strong>: ANC, institutional delivery, newborn care, IMCI, nutrition, immunisation, family planning, under one system.</li>\n<li><strong>Rights-based and equity-focused</strong>: women's empowerment, respectful maternity care, men's involvement.</li>\n<li><strong>Community participation</strong>: CHWs, community clinics.</li>\n<li><strong>Quality of care</strong> and <strong>survive, thrive and transform</strong> agenda (Global Strategy for Women's, Children's and Adolescents' Health).</li>\n</ol>\n<p><strong>Components of MCH</strong></p>\n<p>Maternal health; family planning; child health; school health; handicapped children; care of children in special settings.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.404","n":404,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["24Nov","19Nov","18M","17M","07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the stages of maternal (maternity) cycle? Illustrate the stages / components.</p>","a":"<p><strong>Maternity cycle: stages</strong></p>\n<pre><code>          ┌──────────── Conception ────────────┐\n          ↓                                     │\n   Antenatal period                    Interconceptional period\n   (pregnancy)                         (family planning, spacing)\n          ↓                                     ↑\n   Intranatal period  ───────→  Postnatal period\n   (labour, delivery)            (puerperium, 6 weeks)\n</code></pre>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Care needed</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Conception</strong></td>\n<td>Pre-conception care: nutrition, folic acid, rubella immunity, treatment of chronic disease, healthy age (≥20 years)</td>\n</tr>\n<tr>\n<td><strong>2. Antenatal period</strong></td>\n<td>ANC (≥8 contacts, WHO), IFA, Td, nutrition, risk detection, birth preparedness</td>\n</tr>\n<tr>\n<td><strong>3. Intranatal period</strong></td>\n<td>Skilled birth attendance, clean and safe delivery, partograph, AMTSL, emergency obstetric care</td>\n</tr>\n<tr>\n<td><strong>4. Postnatal period</strong></td>\n<td>Care of mother and newborn; PNC visits; breastfeeding; detect complications</td>\n</tr>\n<tr>\n<td><strong>5. Interconceptional period</strong></td>\n<td>Family planning, birth spacing (≥24 months), nutrition recovery</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Importance</strong></p>\n<p>Each stage carries specific risks; comprehensive MCH care covers the whole cycle.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.405","n":405,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["24Nov","19M","18Nov","16M","11Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"High Risk Pregnancy","q":"<p>Who are considered high risk (at risk) mothers / high risk pregnancies?</p>","a":"<p><strong>High-risk (at-risk) mothers / pregnancies (Park)</strong></p>\n<ol>\n<li><strong>Elderly primigravida</strong> (≥30 years).</li>\n<li><strong>Short-statured primigravida</strong> (≤140 cm).</li>\n<li><strong>Malpresentations</strong> (breech, transverse lie).</li>\n<li><strong>Antepartum haemorrhage</strong>; threatened abortion.</li>\n<li><strong>Pre-eclampsia and eclampsia</strong>.</li>\n<li><strong>Anaemia</strong> (especially severe).</li>\n<li><strong>Twins</strong> (multiple pregnancy); hydramnios.</li>\n<li><strong>Previous stillbirth, intrauterine death</strong>, manual removal of placenta.</li>\n<li><strong>Prolonged pregnancy</strong> (≥14 days past expected date).</li>\n<li><strong>History of previous caesarean or instrumental delivery</strong>.</li>\n<li><strong>Pregnancy with general diseases</strong>: heart disease, diabetes, kidney disease, liver disease, TB, hypertension, epilepsy.</li>\n</ol>\n<p><strong>Other risk factors</strong></p>\n<ul>\n<li>Age <strong>&lt;18 years</strong> (adolescent) or <strong>&gt;35 years</strong>.</li>\n<li><strong>Grand multipara</strong> (≥5 deliveries); short birth interval (&lt;2 years).</li>\n<li><strong>Rh-negative</strong> mother.</li>\n<li>Previous <strong>PPH</strong>, obstructed labour, bad obstetric history, preterm birth, congenital anomaly.</li>\n<li>Poor socio-economic status, malnutrition, no ANC.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.406","n":406,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["26M","24M","16M","15Ja","14Ja","12Ju"],"colleges":"MMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"High Risk Pregnancy","q":"<p>Write down the warning (danger) signs of pregnancy.</p>","a":"<p><strong>Warning (danger) signs of pregnancy</strong></p>\n<ol>\n<li><strong>Vaginal bleeding</strong> at any time.</li>\n<li><strong>Severe headache, blurred vision</strong>.</li>\n<li><strong>Convulsions (fits)</strong> or loss of consciousness.</li>\n<li><strong>High fever</strong>.</li>\n<li><strong>Severe abdominal pain</strong>.</li>\n<li><strong>Swelling of face and hands</strong>.</li>\n<li><strong>Breathlessness</strong>, fast breathing, chest pain.</li>\n<li><strong>Reduced or absent fetal movements</strong>.</li>\n<li><strong>Leaking of watery fluid</strong> from the vagina before labour (rupture of membranes).</li>\n<li><strong>Severe or persistent vomiting</strong>.</li>\n<li>Foul-smelling vaginal discharge; burning urination.</li>\n<li>Severe weakness, pallor.</li>\n</ol>\n<p><strong>During labour / after delivery</strong></p>\n<p>Labour &gt;12 hours (prolonged / obstructed); retained placenta &gt;30 minutes; heavy bleeding after delivery; cord or hand prolapse.</p>\n<p><strong>Action</strong></p>\n<p>Go <strong>immediately</strong> to a health facility with emergency obstetric care; birth preparedness plan (transport, money, blood donor).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.407","n":407,"part":8,"topic":"Maternal and Child Health","stars":0,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Pregnancy","q":"<p>What specific health protection measures are to be taken during pregnancy?</p>","a":"<p><strong>Specific health protection during pregnancy (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Diet</strong></td>\n<td>Balanced, extra energy and protein in 2nd and 3rd trimesters; one extra meal; iodised salt</td>\n</tr>\n<tr>\n<td><strong>2. Anaemia prophylaxis</strong></td>\n<td><strong>Iron-folic acid</strong> daily throughout pregnancy (and 3 months after); treat anaemia</td>\n</tr>\n<tr>\n<td><strong>3. Other nutritional supplements</strong></td>\n<td><strong>Calcium</strong> (prevents pre-eclampsia); iodine; vitamin D where needed</td>\n</tr>\n<tr>\n<td><strong>4. Tetanus immunisation</strong></td>\n<td><strong>TT/Td</strong> (2 doses if not immunised; booster if previously immunised)</td>\n</tr>\n<tr>\n<td><strong>5. Syphilis</strong></td>\n<td>Screening (VDRL/RPR) and treatment with penicillin → prevents congenital syphilis</td>\n</tr>\n<tr>\n<td><strong>6. Rubella (German measles)</strong></td>\n<td>Vaccinate non-immune women <strong>before</strong> pregnancy; avoid exposure in pregnancy</td>\n</tr>\n<tr>\n<td><strong>7. Rh status</strong></td>\n<td>Blood grouping; anti-D for Rh-negative mothers</td>\n</tr>\n<tr>\n<td><strong>8. HIV and hepatitis B</strong></td>\n<td>Screening; PMTCT; hepatitis B vaccine and HBIG for newborn</td>\n</tr>\n<tr>\n<td><strong>9. Malaria</strong></td>\n<td>Insecticide-treated nets; prophylaxis/treatment in endemic areas</td>\n</tr>\n<tr>\n<td><strong>10. Deworming</strong></td>\n<td>After first trimester</td>\n</tr>\n<tr>\n<td><strong>11. Avoid harmful exposures</strong></td>\n<td>Unnecessary drugs, X-rays, smoking, smokeless tobacco, alcohol, heavy work</td>\n</tr>\n<tr>\n<td><strong>12. Prenatal advice</strong></td>\n<td>Rest, hygiene, sleep, safe sex, recognition of danger signs, birth preparedness</td>\n</tr>\n<tr>\n<td><strong>13. Prevention of pre-eclampsia</strong></td>\n<td>BP monitoring; low-dose aspirin for high-risk women</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.408","n":408,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["17M"],"colleges":"SSMC (2nd Term A1); MuMC (2nd Final D4)","asked":"5 objectives of ANC and WHO-recommended ideal visits / define ANC and minimum visit schedule","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>Mention the objectives of antenatal care. Write ideal number and time for antenatal visits.</p>","a":"<p><strong>Objectives of antenatal care (Park)</strong></p>\n<ol>\n<li>To <strong>promote, protect and maintain the health of the mother</strong> during pregnancy.</li>\n<li>To <strong>detect &quot;high-risk&quot; cases</strong> and give them special attention.</li>\n<li>To <strong>foresee complications and prevent them</strong>.</li>\n<li>To <strong>remove anxiety and dread</strong> associated with delivery.</li>\n<li>To <strong>reduce maternal and infant mortality and morbidity</strong>.</li>\n<li>To <strong>teach the mother</strong> the elements of child care, nutrition, personal hygiene and environmental sanitation.</li>\n<li>To sensitise the mother to the need for <strong>family planning</strong>.</li>\n<li>To attend to <strong>under-five children</strong> accompanying the mother.</li>\n</ol>\n<p><strong>Number and timing of antenatal visits</strong></p>\n<table>\n<thead>\n<tr>\n<th>Guideline</th>\n<th>Schedule</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Park (traditional ideal)</strong></td>\n<td>Monthly until 28 weeks; every 2 weeks from 28–36 weeks; weekly thereafter</td>\n</tr>\n<tr>\n<td><strong>Minimum (Bangladesh, 4 visits)</strong></td>\n<td>1st: by 16 weeks; 2nd: 24–28 weeks; 3rd: 32 weeks; 4th: 36 weeks</td>\n</tr>\n<tr>\n<td><strong>WHO (2016): at least 8 contacts</strong></td>\n<td>1st contact up to 12 weeks; then at 20, 26, 30, 34, 36, 38 and 40 weeks</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics); WHO recommendations on antenatal care for a positive pregnancy experience, 2016.</p>"},{"id":"DU.409","n":409,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["26M","22Nov","16Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>Enumerate the duties of attending physician / components of first antenatal visit.</p>","a":"<p><strong>Components of the first antenatal visit (duties of the attending physician)</strong></p>\n<p><strong>1. Registration</strong>: open ANC card; record identity, address, contact.</p>\n<p><strong>2. History</strong></p>\n<ul>\n<li>Menstrual: LMP → <strong>EDD</strong>; cycle.</li>\n<li>Obstetric: parity, previous pregnancies, abortions, stillbirths, caesarean, PPH, birth weights.</li>\n<li>Present pregnancy: symptoms (bleeding, vomiting, headache).</li>\n<li>Medical: hypertension, diabetes, heart, kidney disease, TB, epilepsy, drugs, allergies.</li>\n<li>Family: twins, diabetes, hypertension, genetic disorders.</li>\n<li>Social: age, education, nutrition, tobacco, violence.</li>\n<li>Immunisation (TT/Td) and contraception history.</li>\n</ul>\n<p><strong>3. Examination</strong></p>\n<ul>\n<li>General: height, weight (BMI), BP, pulse, pallor, jaundice, oedema, thyroid, breasts, teeth.</li>\n<li>Systemic: heart, lungs.</li>\n<li>Obstetric: fundal height (after 12 weeks), uterine size vs dates.</li>\n</ul>\n<p><strong>4. Investigations</strong></p>\n<p>Hb, blood group and Rh, urine (protein, sugar, infection), blood glucose, VDRL/RPR, HBsAg, HIV (with counselling), ultrasound (dating, viability, number).</p>\n<p><strong>5. Risk assessment</strong> → plan care and referral if high-risk.</p>\n<p><strong>6. Interventions</strong></p>\n<p>Iron-folic acid, calcium; TT/Td; deworming (after first trimester); treatment of problems.</p>\n<p><strong>7. Advice / health education</strong></p>\n<p>Diet, rest, hygiene, danger signs, avoid harmful drugs and tobacco, birth preparedness, breastfeeding, family planning.</p>\n<p><strong>8. Next visit date</strong> and follow-up plan.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.410","n":410,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>What is 'home visit'?</p>","a":"<p><strong>Home visit</strong></p>\n<p>A visit by a health worker (FWA, HA, CHCP, nurse, doctor) to a family's home to provide <strong>health care, education and follow-up</strong> in the home setting.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.411","n":411,"part":8,"topic":"Maternal and Child Health","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>Give the outline of prenatal services of a multipara woman aged 40 years.</p>","a":"<p><strong>Prenatal services for a 40-year-old multipara (high-risk pregnancy)</strong></p>\n<p><strong>A. Risks to anticipate</strong></p>\n<p>Chromosomal anomalies (Down syndrome), miscarriage, gestational diabetes, hypertension and pre-eclampsia, anaemia, malpresentation, placenta praevia, preterm birth, growth restriction, stillbirth, prolonged labour, uterine rupture, <strong>postpartum haemorrhage</strong>.</p>\n<p><strong>B. Services</strong></p>\n<ol>\n<li><strong>Early registration</strong> and <strong>risk labelling</strong>; care by a doctor/obstetrician; more frequent ANC (at least 8 contacts; more as needed).</li>\n<li><strong>History and examination</strong>: previous obstetric events (PPH, caesarean), chronic diseases; BP and weight at every visit.</li>\n<li><strong>Investigations</strong>:\n<ul>\n<li>Hb, blood group and Rh, urine, VDRL, HBsAg, HIV.</li>\n<li><strong>Blood glucose / OGTT</strong> for gestational diabetes (early and at 24–28 weeks).</li>\n<li><strong>Ultrasound</strong>: dating, multiple pregnancy, anomaly scan (18–22 weeks), growth scans, placental position.</li>\n<li><strong>Screening for aneuploidy</strong> (nuchal translucency, combined test or other available tests), with counselling about diagnostic tests.</li>\n</ul>\n</li>\n<li><strong>Supplements</strong>: iron-folic acid, calcium; low-dose aspirin if pre-eclampsia risk.</li>\n<li><strong>Td immunisation</strong> as per status.</li>\n<li><strong>Nutrition</strong> counselling and rest; avoid heavy work.</li>\n<li><strong>Danger signs</strong> education; birth preparedness and complication readiness.</li>\n<li><strong>Institutional delivery</strong> in a facility with <strong>comprehensive emergency obstetric care</strong> (CS, blood transfusion); active management of third stage to prevent PPH.</li>\n<li><strong>Family planning counselling</strong>: postpartum contraception; permanent method (tubectomy) if family complete.</li>\n<li>Psychological support.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.412","n":412,"part":8,"topic":"Maternal and Child Health","stars":2,"years":["20Nov","10Ja"],"colleges":"SSMC (2nd Term A1); MMC (2nd Term C5)","asked":"investigations at 12 weeks with reasons for each","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>What are the important laboratory investigations to be done during first antenatal visit (primi gravida)?</p>","a":"<p><strong>Laboratory investigations at the first antenatal visit (primigravida, ~12 weeks)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Investigation</th>\n<th>Reason</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Haemoglobin</strong> (CBC)</td>\n<td>Detect <strong>anaemia</strong> (Hb &lt;11 g/dl); start treatment</td>\n</tr>\n<tr>\n<td><strong>Blood group and Rh typing</strong></td>\n<td>Identify <strong>Rh-negative</strong> mothers (anti-D prophylaxis); blood for emergencies</td>\n</tr>\n<tr>\n<td><strong>Urine routine</strong> (protein, sugar, pus cells)</td>\n<td>Baseline protein (pre-eclampsia later); glycosuria; <strong>asymptomatic bacteriuria</strong> / UTI</td>\n</tr>\n<tr>\n<td><strong>Blood glucose</strong> (fasting / random; OGTT if risk)</td>\n<td>Detect pre-existing <strong>diabetes</strong></td>\n</tr>\n<tr>\n<td><strong>VDRL / RPR</strong></td>\n<td><strong>Syphilis</strong> → treat to prevent congenital syphilis</td>\n</tr>\n<tr>\n<td><strong>HBsAg</strong></td>\n<td><strong>Hepatitis B</strong> → birth-dose vaccine + HBIG for baby</td>\n</tr>\n<tr>\n<td><strong>HIV</strong> (with counselling)</td>\n<td><strong>PMTCT</strong>: ART for mother, prophylaxis for baby</td>\n</tr>\n<tr>\n<td><strong>Ultrasound</strong></td>\n<td>Confirm pregnancy, viability, <strong>dating</strong> (EDD), multiple pregnancy, early anomalies</td>\n</tr>\n<tr>\n<td>Optional / as indicated</td>\n<td>TSH (thyroid), rubella IgG, haemoglobin electrophoresis (thalassaemia carrier), stool for ova, hepatitis C</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.413","n":413,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["23Nov","22Nov","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>Why are mother and fetus (mother and child) called one unit?</p>","a":"<p><strong>Why mother and child are one unit</strong></p>\n<ol>\n<li><strong>During pregnancy</strong> the fetus is part of the mother; it depends entirely on her for nutrition, oxygen and protection.</li>\n<li><strong>Maternal health decides fetal outcome</strong>: maternal malnutrition and anaemia → <strong>low birth weight</strong>; infections (syphilis, rubella, HIV, hepatitis B) → congenital or perinatal infection; drugs, smoking, alcohol → fetal harm.</li>\n<li><strong>At delivery</strong>, complications of the mother (obstructed labour, eclampsia, haemorrhage) directly cause birth asphyxia and stillbirth.</li>\n<li><strong>After birth</strong>, the child depends on the mother for <strong>breastfeeding</strong>, warmth, care, stimulation and immunisation.</li>\n<li><strong>Maternal death</strong> greatly raises the risk of death of her baby and older children.</li>\n<li><strong>Maternal antibodies</strong> (IgG through placenta, IgA in breast milk) protect the infant.</li>\n<li>Mother's education, health behaviour and decisions shape child health.</li>\n<li>Both are a <strong>vulnerable group</strong> with linked risks; services can be delivered together (ANC, delivery care, PNC, EPI, nutrition) → <strong>integrated MCH</strong> is efficient.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.414","n":414,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["23Nov","14Ju","11Ju","10Ja"],"colleges":"DMC (2nd Assess B4); MMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>What is risk approach?</p>","a":"<p><strong>Risk approach</strong></p>\n<p>A <strong>managerial tool</strong> for improving MCH care: identify individuals or groups at <strong>higher risk</strong> of an unfavourable outcome (using risk factors), and give them <strong>more and special care in proportion to their need</strong>, while still providing <strong>basic care for all</strong>: &quot;<strong>something for all, but more for those in greater need</strong>&quot; (WHO).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.415","n":415,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>Detect (define) intranatal period.</p>","a":"<p><strong>Intranatal period</strong></p>\n<p>The period from the <strong>onset of true labour</strong> to the <strong>complete expulsion of the placenta and membranes</strong> (end of the third stage), often extended to include the first hour after delivery (fourth stage).</p>\n<p><strong>Stages of labour</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>From → to</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>First</td>\n<td>Onset of true labour → full dilatation of cervix</td>\n</tr>\n<tr>\n<td>Second</td>\n<td>Full dilatation → birth of baby</td>\n</tr>\n<tr>\n<td>Third</td>\n<td>Birth of baby → delivery of placenta and membranes</td>\n</tr>\n<tr>\n<td>(Fourth)</td>\n<td>First hour after placental delivery: observation for PPH</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Aims of intranatal care (Park)</strong></p>\n<ol>\n<li>Thorough <strong>asepsis</strong> (clean delivery).</li>\n<li><strong>Minimum injury</strong> to mother and baby.</li>\n<li><strong>Readiness to deal with complications</strong> (emergency obstetric care, referral).</li>\n<li><strong>Care of the baby</strong> at delivery: resuscitation, warmth, cord care, early breastfeeding.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.416","n":416,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["22Nov","21M","19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>What complications / danger (risk) signals may arise during intranatal period?</p>","a":"<p><strong>Complications / danger signals during the intranatal period</strong></p>\n<p><strong>A. Maternal</strong></p>\n<ol>\n<li><strong>Prolonged labour</strong> (&gt;12 hours) and <strong>obstructed labour</strong>.</li>\n<li><strong>Malpresentations</strong> (breech, transverse lie, face, brow).</li>\n<li><strong>Haemorrhage</strong>: antepartum haemorrhage; <strong>postpartum haemorrhage</strong>; retained placenta (&gt;30 minutes).</li>\n<li><strong>Eclampsia</strong> (convulsions).</li>\n<li><strong>Rupture of uterus</strong>; inversion of uterus.</li>\n<li><strong>Cord prolapse</strong> or prolapse of a hand.</li>\n<li>Premature or prolonged rupture of membranes → <strong>infection</strong> (chorioamnionitis).</li>\n<li>Perineal tears; shock.</li>\n</ol>\n<p><strong>B. Fetal</strong></p>\n<ol>\n<li><strong>Fetal distress</strong>: FHR &lt;110 or &gt;160/min, irregular; <strong>meconium-stained</strong> liquor.</li>\n<li><strong>Birth asphyxia</strong>.</li>\n<li><strong>Birth injuries</strong>.</li>\n<li>Preterm birth.</li>\n</ol>\n<p><strong>Danger signals (Park): call for help or refer</strong></p>\n<ul>\n<li>No progress despite good pains for an hour after rupture of membranes.</li>\n<li>Weak or absent pains after rupture of membranes.</li>\n<li>Prolapse of cord or limb.</li>\n<li>Excessive bleeding.</li>\n<li>Abnormal fetal heart rate or meconium-stained liquor.</li>\n<li>Convulsions, high fever, shock.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.417","n":417,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["23Nov","17Ja","14Ju","12Ja","10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>Identify three criteria for at-risk babies. Who are the high risk babies / infants?</p>","a":"<p><strong>At-risk (high-risk) babies (Park)</strong></p>\n<ol>\n<li><strong>Birth weight less than 2.5 kg</strong> (low birth weight).</li>\n<li><strong>Twins</strong> (multiple births).</li>\n<li><strong>Birth order 5 or more</strong>.</li>\n<li><strong>Artificial feeding</strong> (not breastfed).</li>\n<li><strong>Weight below 70% of expected</strong> (below −2 SD).</li>\n<li><strong>Failure to gain weight</strong> during three successive months.</li>\n<li><strong>Children with PEM or diarrhoea</strong>.</li>\n<li><strong>Working mother / one-parent family</strong>.</li>\n</ol>\n<p><strong>Other high-risk newborns</strong></p>\n<p>Preterm babies; birth asphyxia; congenital anomalies; neonatal infections; jaundice; babies of diabetic, HIV-positive or HBsAg-positive mothers; babies whose mother died.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.418","n":418,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"MMC (2nd Term C5)","asked":"","note":"","kind":"","sub":"Ante Natal Care (ANC)","q":"<p>What is Rh incompatibility?</p>","a":"<p><strong>Rh incompatibility</strong></p>\n<p>Occurs when an <strong>Rh-negative mother</strong> carries an <strong>Rh-positive fetus</strong> (father Rh-positive).</p>\n<p><strong>Mechanism</strong></p>\n<p>Fetal Rh-positive RBCs enter maternal blood (at delivery, abortion, ectopic pregnancy, APH, amniocentesis, trauma) → mother <strong>sensitised</strong> → forms <strong>anti-D (IgG)</strong> antibodies → in a <strong>later</strong> Rh-positive pregnancy antibodies cross the placenta → destroy fetal RBCs → <strong>haemolytic disease of the fetus and newborn (HDFN)</strong>.</p>\n<p><strong>Effects on baby</strong></p>\n<p>Anaemia; <strong>jaundice</strong> (early, severe) → <strong>kernicterus</strong>; hepatosplenomegaly; <strong>hydrops fetalis</strong>; stillbirth.</p>\n<p>The <strong>first pregnancy</strong> is usually unaffected (sensitisation occurs at its delivery).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.419","n":419,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["24M","15Ja","12Ju"],"colleges":"MMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"Postnatal Care","q":"<p>What complications may arise during post-natal period?</p>","a":"<p><strong>Complications of the postnatal period (mother)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Complication</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Postpartum haemorrhage</strong></td>\n<td>Primary (within 24 hours: atonic uterus, tears, retained placenta); secondary (24 hours–6 weeks: retained products, infection)</td>\n</tr>\n<tr>\n<td><strong>Puerperal sepsis</strong></td>\n<td>Fever, foul lochia, lower abdominal pain after delivery; can cause septic shock</td>\n</tr>\n<tr>\n<td><strong>Breast problems</strong></td>\n<td>Engorgement, cracked nipples, <strong>mastitis</strong>, breast abscess</td>\n</tr>\n<tr>\n<td><strong>Urinary problems</strong></td>\n<td>Retention, UTI; <strong>obstetric fistula</strong> after prolonged obstructed labour</td>\n</tr>\n<tr>\n<td><strong>Thrombophlebitis / deep vein thrombosis</strong>, pulmonary embolism</td>\n<td>Leg pain and swelling; breathlessness</td>\n</tr>\n<tr>\n<td><strong>Postpartum eclampsia / hypertension</strong></td>\n<td>Convulsions, headache</td>\n</tr>\n<tr>\n<td><strong>Sub-involution</strong> of uterus</td>\n<td>Persistent lochia, large uterus</td>\n</tr>\n<tr>\n<td><strong>Perineal wound</strong> infection or breakdown</td>\n<td>Pain, discharge</td>\n</tr>\n<tr>\n<td><strong>Anaemia</strong></td>\n<td>Weakness, breathlessness</td>\n</tr>\n<tr>\n<td><strong>Mental health problems</strong></td>\n<td>Postpartum blues, <strong>postpartum depression</strong>, puerperal psychosis</td>\n</tr>\n<tr>\n<td>Others</td>\n<td>Backache, constipation, haemorrhoids, uterine prolapse later</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Newborn problems in the same period</strong></p>\n<p>Hypothermia, sepsis, jaundice, feeding problems, cord infection.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.420","n":420,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Postnatal Care","q":"<p>Write down the common child health problems in Bangladesh.</p>","a":"<p><strong>Common child health problems in Bangladesh</strong></p>\n<table>\n<thead>\n<tr>\n<th>Age group</th>\n<th>Problems</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Newborn</strong></td>\n<td><strong>Prematurity and LBW</strong>, <strong>birth asphyxia</strong>, <strong>neonatal sepsis</strong>, hypothermia, neonatal jaundice, congenital anomalies (neonatal deaths form a large share of under-5 deaths)</td>\n</tr>\n<tr>\n<td><strong>Infancy and childhood</strong></td>\n<td><strong>Pneumonia / ARI</strong>, <strong>diarrhoea</strong>, <strong>malnutrition</strong> (stunting 23.6% in 2022, wasting, underweight), <strong>anaemia</strong>, micronutrient deficiencies</td>\n</tr>\n<tr>\n<td><strong>Infections</strong></td>\n<td>Measles and other vaccine-preventable diseases (outbreak in 2026), dengue, typhoid, TB, worm infestations, skin infections (scabies)</td>\n</tr>\n<tr>\n<td><strong>Injuries</strong></td>\n<td><strong>Drowning</strong> (leading cause of death in children aged 1–4), road traffic injuries, burns, falls, poisoning</td>\n</tr>\n<tr>\n<td><strong>Developmental</strong></td>\n<td>Cerebral palsy, autism, intellectual disability, hearing and vision problems</td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Childhood cancers, rheumatic heart disease, thalassaemia, child abuse and neglect, child labour</td>\n</tr>\n<tr>\n<td><strong>Adolescents</strong></td>\n<td>Child marriage, adolescent pregnancy, anaemia, mental health problems, substance use</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics); Our World in Data, https://ourworldindata.org/profile/health/bangladesh</p>"},{"id":"DU.421","n":421,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"MMC (2nd Term C2)","asked":"","note":"","kind":"","sub":"Postnatal Care","q":"<p>Define postnatal period.</p>","a":"<p><strong>Postnatal period (puerperium)</strong></p>\n<p>The period from the <strong>delivery of the placenta</strong> to <strong>6 weeks (42 days)</strong> after delivery, during which the reproductive organs return to their non-pregnant state.</p>\n<p><strong>Phases</strong></p>\n<table>\n<thead>\n<tr>\n<th>Phase</th>\n<th>Time</th>\n<th>Importance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Immediate</td>\n<td>First 24 hours</td>\n<td>Highest risk: PPH, eclampsia; most maternal and neonatal deaths</td>\n</tr>\n<tr>\n<td>Early</td>\n<td>Days 2–7</td>\n<td>Infection, breastfeeding problems, neonatal jaundice</td>\n</tr>\n<tr>\n<td>Late</td>\n<td>Weeks 2–6</td>\n<td>Recovery, family planning, postpartum depression</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.422","n":422,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["19M","11Ja","09Ja","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Growth & Development","q":"<p>Mention the uses of growth chart. In which conditions can learning be affected? Explain the WHO growth chart / growth monitoring with interpretation of reference curve.</p>","a":"<p><strong>Growth chart (Road to Health chart)</strong></p>\n<p>A visual record of a child's <strong>weight (and height) plotted against age</strong>, used to monitor growth over time.</p>\n<p><strong>Uses (Park)</strong></p>\n<ol>\n<li><strong>Growth monitoring</strong>: early detection of growth faltering and malnutrition, before clinical signs.</li>\n<li><strong>Tool for action</strong>: guides feeding advice, treatment, referral.</li>\n<li><strong>Educational tool</strong> for mothers: shows how the child is growing.</li>\n<li><strong>Evaluation</strong> of nutrition and health programmes.</li>\n<li><strong>Planning and policy</strong> (community nutrition status).</li>\n<li><strong>Teaching aid</strong> for health workers.</li>\n<li><strong>Record</strong> of immunisation, vitamin A, illnesses, birth weight.</li>\n</ol>\n<p><strong>WHO growth standards (2006)</strong></p>\n<p>Based on healthy breastfed children from six countries; show how children <strong>should</strong> grow.</p>\n<table>\n<thead>\n<tr>\n<th>Indicator</th>\n<th>Detects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Weight-for-age</td>\n<td>Underweight</td>\n</tr>\n<tr>\n<td>Length/height-for-age</td>\n<td><strong>Stunting</strong> (chronic malnutrition)</td>\n</tr>\n<tr>\n<td>Weight-for-length/height</td>\n<td><strong>Wasting</strong> (acute malnutrition), overweight</td>\n</tr>\n<tr>\n<td>BMI-for-age</td>\n<td>Thinness, overweight, obesity</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Interpretation (z-scores)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Position</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Above −2 SD (and below +2 SD)</td>\n<td>Normal</td>\n</tr>\n<tr>\n<td>Between −2 and −3 SD</td>\n<td>Moderate malnutrition</td>\n</tr>\n<tr>\n<td>Below −3 SD</td>\n<td>Severe malnutrition</td>\n</tr>\n<tr>\n<td>Above +2 SD (weight-for-height)</td>\n<td>Overweight</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Direction of the growth curve</strong> (more important than one point)</p>\n<table>\n<thead>\n<tr>\n<th>Curve</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Rising parallel to reference lines</td>\n<td>Good growth</td>\n</tr>\n<tr>\n<td>Flat</td>\n<td><strong>Danger</strong>: growth faltering</td>\n</tr>\n<tr>\n<td>Falling</td>\n<td><strong>Very dangerous</strong>: needs urgent action</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Conditions that affect growth and learning</strong></p>\n<p>Malnutrition (stunting), iron-deficiency anaemia, iodine deficiency, LBW and prematurity, repeated infections and worms, chronic illness, lead exposure, lack of stimulation and care.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics; Nutrition and Health).</p>"},{"id":"DU.423","n":423,"part":8,"topic":"Maternal and Child Health","stars":0,"years":["16M","09Ju","07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Growth & Development","q":"<p>Discuss / illustrate the determinants (important factors) of growth and development.</p>","a":"<p><strong>Determinants of growth and development</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Factors</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Genetic</strong></td>\n<td>Parents' height and build; sex; ethnicity; genetic and chromosomal disorders</td>\n</tr>\n<tr>\n<td><strong>2. Prenatal</strong></td>\n<td>Maternal nutrition and anaemia, age, infections (TORCH, malaria), drugs, smoking, hypertension → LBW, IUGR, prematurity</td>\n</tr>\n<tr>\n<td><strong>3. Nutrition</strong></td>\n<td>Exclusive breastfeeding; timely, adequate complementary feeding; micronutrients (iron, iodine, zinc, vitamin A)</td>\n</tr>\n<tr>\n<td><strong>4. Infections</strong></td>\n<td>Diarrhoea, pneumonia, measles, worms, TB → growth faltering; vicious cycle with malnutrition</td>\n</tr>\n<tr>\n<td><strong>5. Socio-economic</strong></td>\n<td>Family income, parental (especially maternal) education, family size, birth spacing, birth order</td>\n</tr>\n<tr>\n<td><strong>6. Environment</strong></td>\n<td>Safe water, sanitation and hygiene; housing; pollution (lead)</td>\n</tr>\n<tr>\n<td><strong>7. Hormonal</strong></td>\n<td>Growth hormone, thyroid, sex hormones, insulin</td>\n</tr>\n<tr>\n<td><strong>8. Psychosocial</strong></td>\n<td>Love, play, <strong>responsive caregiving</strong>, early learning, emotional security; neglect and violence harm development</td>\n</tr>\n<tr>\n<td><strong>9. Health care</strong></td>\n<td>Immunisation, growth monitoring, early treatment</td>\n</tr>\n<tr>\n<td><strong>10. Physical activity and sleep</strong></td>\n<td>Normal muscle and bone growth</td>\n</tr>\n<tr>\n<td><strong>11. Chronic disease</strong></td>\n<td>Heart, kidney disease, thalassaemia</td>\n</tr>\n</tbody>\n</table>\n<p><strong>WHO Nurturing Care Framework (2018): five components</strong></p>\n<p>Good health → adequate nutrition → responsive caregiving → opportunities for early learning → security and safety</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics); WHO, Nurturing care for early childhood development, 2018.</p>"},{"id":"DU.424","n":424,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["11Ju"],"colleges":"ShSMC (2nd Term C3)","asked":"define LBW, three risk factors","note":"","kind":"","sub":"Growth & Development","q":"<p>Write elaborately about low birth weight (LBW) babies. What are the causes of LBW?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Low birth weight (LBW)</strong>: birth weight <strong>less than 2,500 g</strong> (up to and including 2,499 g), regardless of gestational age, ideally measured within the first hour after birth (WHO).</p>\n<p><strong>Groups</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Preterm</strong></td>\n<td>Born before 37 completed weeks; weight appropriate for gestation</td>\n</tr>\n<tr>\n<td><strong>Small-for-date (SGA / IUGR)</strong></td>\n<td>Term or preterm but weight below the 10th percentile for gestation (fetal growth restriction)</td>\n</tr>\n</tbody>\n</table>\n<p>In Bangladesh and South Asia most LBW babies are <strong>small-for-date</strong>.</p>\n<p><strong>Causes / risk factors</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Factors</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Maternal</strong></td>\n<td>Young age (&lt;18), short stature, <strong>malnutrition</strong> and low pre-pregnancy weight, poor weight gain, <strong>anaemia</strong>, heavy physical work, short birth interval, high parity, tobacco (smoking, smokeless), alcohol</td>\n</tr>\n<tr>\n<td><strong>Medical / obstetric</strong></td>\n<td><strong>Hypertension / pre-eclampsia</strong>, APH, multiple pregnancy, infections (malaria, UTI, syphilis, HIV), chronic diseases (heart, kidney)</td>\n</tr>\n<tr>\n<td><strong>Fetal</strong></td>\n<td>Congenital anomalies, chromosomal disorders, intrauterine infections</td>\n</tr>\n<tr>\n<td><strong>Placental</strong></td>\n<td>Placental insufficiency, abnormal placentation</td>\n</tr>\n<tr>\n<td><strong>Socio-economic</strong></td>\n<td>Poverty, low education, poor ANC, indoor air pollution</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Consequences</strong></p>\n<p>Higher neonatal mortality; hypothermia, hypoglycaemia, infections, respiratory distress, jaundice, feeding problems; later stunting, developmental delay, poor school performance; adult NCDs (Barker hypothesis).</p>\n<p><strong>Prevention</strong></p>\n<p>Maternal nutrition (food supplementation, IFA, calcium), delay first pregnancy, birth spacing, treat infections and anaemia, stop tobacco, rest, ANC with BP monitoring, education of women.</p>\n<p><strong>Management</strong></p>\n<p>Thermal care and <strong>Kangaroo Mother Care</strong>; early and exclusive breastfeeding (expressed milk, cup feeding); infection prevention; vitamin K; antenatal corticosteroids for preterm labour; special care newborn units (SCANU); growth and developmental follow-up.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.425","n":425,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["21M","19M"],"colleges":"","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>What is milk injury?</p>","a":"<p><strong>Milk injury</strong></p>\n<p>Harm to an infant caused by <strong>replacing breast milk with cow's milk or other artificial milk</strong> too early (in the first months of life), or by improper artificial feeding.</p>\n<p><strong>Harmful effects</strong></p>\n<ol>\n<li><strong>Cow's milk protein</strong> → allergy and intolerance; <strong>occult intestinal blood loss</strong> → <strong>iron-deficiency anaemia</strong> (&quot;milk anaemia&quot;).</li>\n<li><strong>High solute load</strong> (protein, sodium) → strain on immature kidneys; <strong>hypernatraemic dehydration</strong>.</li>\n<li><strong>Infection</strong>: contaminated bottles and teats → <strong>diarrhoea</strong>, gastroenteritis.</li>\n<li><strong>Malnutrition</strong>: over-dilution → <strong>marasmus</strong>; wrong mixing → under- or over-feeding.</li>\n<li><strong>Lack of protective factors</strong> of breast milk (IgA, lactoferrin, lysozyme) → more ARI, otitis media, NEC.</li>\n<li>Poor iron and vitamin bioavailability; low essential fatty acids for brain development.</li>\n<li>Later <strong>obesity</strong>, allergies, diabetes risk.</li>\n<li>Loss of mother–infant bonding; earlier return of fertility in mother.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics; Nutrition and Health).</p>"},{"id":"DU.426","n":426,"part":8,"topic":"Maternal and Child Health","stars":0,"years":["12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>What is rooming in?</p>","a":"<p><strong>Rooming-in</strong></p>\n<p>Keeping the <strong>mother and newborn together in the same room (bed-side cot) 24 hours a day</strong> from birth until discharge, instead of keeping the baby in a separate nursery.</p>\n<p><strong>Benefits</strong></p>\n<ol>\n<li>Early and <strong>on-demand breastfeeding</strong>; better milk production.</li>\n<li><strong>Bonding</strong> between mother and baby.</li>\n<li>Mother learns baby care (warmth, cord care, danger signs).</li>\n<li><strong>Less hospital infection</strong> (less handling by staff).</li>\n<li>Baby kept warm; less crying.</li>\n<li>Part of the <strong>Baby-Friendly Hospital Initiative</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.427","n":427,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["22Nov","12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>What is exclusive breast feeding?</p>","a":"<p><strong>Exclusive breastfeeding (EBF)</strong></p>\n<p>The infant receives <strong>only breast milk</strong> (including expressed breast milk) and <strong>no other liquids or solids, not even water</strong>, except <strong>ORS, drops or syrups of vitamins, minerals or medicines</strong>, for the <strong>first 6 months</strong> of life (WHO).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics; Nutrition and Health).</p>"},{"id":"DU.428","n":428,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["21M"],"colleges":"SSMC (2nd Term A2); MMC (2nd Term C3)","asked":"advantages of breast feeding","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>Enumerate the benefits of exclusive breast feeding.</p>","a":"<p><strong>Benefits of exclusive breastfeeding</strong></p>\n<p><strong>A. For the baby</strong></p>\n<ol>\n<li><strong>Ideal nutrition</strong>: right proportion of protein, fat, lactose, vitamins; easily digested.</li>\n<li><strong>Anti-infective factors</strong>: secretory IgA, lactoferrin, lysozyme, macrophages, bifidus factor → protection against <strong>diarrhoea, pneumonia, otitis media, sepsis</strong>.</li>\n<li><strong>Lower infant mortality</strong> and hospitalisation.</li>\n<li><strong>Clean, safe, at the right temperature</strong>; no contamination.</li>\n<li><strong>Brain development</strong> (DHA); higher IQ.</li>\n<li><strong>Less allergy</strong>, asthma; lower later risk of obesity, diabetes.</li>\n<li><strong>Bonding</strong>, emotional security.</li>\n</ol>\n<p><strong>B. For the mother</strong></p>\n<ol>\n<li><strong>Lactational amenorrhoea</strong> → birth spacing.</li>\n<li><strong>Oxytocin</strong> release → uterine contraction, <strong>less PPH</strong>, faster involution.</li>\n<li><strong>Lower risk of breast and ovarian cancer</strong>; type 2 diabetes.</li>\n<li>Helps return to pre-pregnancy weight.</li>\n<li>Convenient; saves time.</li>\n</ol>\n<p><strong>C. For family and nation</strong></p>\n<p>Saves money (no formula, fewer illnesses); reduces health-care costs; environment-friendly; contributes to child survival and development goals.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.429","n":429,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["19Nov","12Ja","09Ja"],"colleges":"MMC (2nd Term C3)","asked":"define complementary feeding","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>What do you mean by weaning?</p>","a":"<p><strong>Weaning</strong></p>\n<p>The process of <strong>gradually introducing foods other than breast milk</strong> to the infant's diet, while breastfeeding continues, so that the child moves from breast milk to the family diet. WHO now prefers the term <strong>complementary feeding</strong>.</p>\n<p><strong>Timing</strong></p>\n<p>From <strong>6 months</strong> (180 days); breastfeeding continued up to 2 years or beyond.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health; Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.430","n":430,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>Write down the disadvantages of artificial feeding.</p>","a":"<p><strong>Disadvantages of artificial (bottle) feeding</strong></p>\n<ol>\n<li><strong>Infection</strong>: contaminated bottles, teats, water → diarrhoea, thrush.</li>\n<li><strong>Malnutrition</strong>: over-dilution → marasmus; wrong preparation.</li>\n<li>Lacks <strong>anti-infective factors</strong> (IgA, lactoferrin, lysozyme) → more ARI, otitis, NEC.</li>\n<li><strong>Cow's milk protein allergy</strong>, intolerance; occult GI bleeding → iron-deficiency anaemia.</li>\n<li>High solute load → hypernatraemic dehydration.</li>\n<li><strong>Costly</strong>; time and fuel for preparation.</li>\n<li>Later <strong>obesity</strong>, diabetes risk.</li>\n<li>Less <strong>bonding</strong>; mother loses lactational contraception.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.431","n":431,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"SSMC (1st Supp C5)","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>What is colostrum?</p>","a":"<p><strong>Colostrum</strong></p>\n<p>Thick, <strong>yellowish</strong> milk secreted during the <strong>first 2–3 days</strong> (up to ~5 days) after delivery.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.432","n":432,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"SSMC (2nd Term A2)","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>What are the contraindications of breast feeding?</p>","a":"<p><strong>Contraindications of breastfeeding (very few)</strong></p>\n<p><strong>A. Infant conditions</strong></p>\n<ol>\n<li><strong>Classic galactosaemia</strong> (absolute).</li>\n<li>Maple syrup urine disease; <strong>phenylketonuria</strong> (partial breastfeeding with special formula).</li>\n</ol>\n<p><strong>B. Maternal conditions</strong></p>\n<ol>\n<li><strong>HIV</strong> infection: where safe replacement feeding is acceptable, feasible, affordable, sustainable and safe; otherwise breastfeed with ART (WHO).</li>\n<li><strong>Active untreated TB</strong>: temporary separation until non-infectious (expressed milk can be given).</li>\n<li>HTLV-1 infection; herpes lesions on the breast (feed from the other side).</li>\n<li><strong>Drugs</strong>: anticancer drugs, radioactive isotopes, some immunosuppressants; substance abuse.</li>\n<li>Severe maternal illness (shock, eclampsia, psychosis) temporarily.</li>\n</ol>\n<p><strong>Not contraindications</strong></p>\n<p>Hepatitis B (baby gets vaccine + HBIG), common cold, diarrhoea, most drugs, mastitis.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.433","n":433,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"MMC (2nd Term C3)","asked":"","note":"","kind":"","sub":"Breast Feeding and Weaning","q":"<p>Write down the importance of complementary feeding.</p>","a":"<p><strong>Importance of complementary feeding</strong></p>\n<ol>\n<li>After <strong>6 months</strong>, breast milk alone cannot meet the child's needs for <strong>energy, protein, iron, zinc and vitamin A</strong>.</li>\n<li>Prevents <strong>growth faltering</strong>, stunting and PEM during the critical 6–24-month window.</li>\n<li>Prevents <strong>iron-deficiency anaemia</strong> and other micronutrient deficiencies.</li>\n<li>Develops <strong>chewing</strong>, swallowing and taste for family foods.</li>\n<li>Supports <strong>brain development</strong> and learning.</li>\n<li>Reduces later <strong>malnutrition-infection cycle</strong> when foods are prepared hygienically.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.434","n":434,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["25Nov","20Nov","16Nov","15Ja","13Ju","13Ja"],"colleges":"DMC (2nd Assess C1)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Mention / state the causes of (high) IMR / infant death in Bangladesh. Why is infant mortality high in developing countries like Bangladesh?</p>","a":"<p><strong>Infant mortality in Bangladesh</strong></p>\n<p>IMR 27 per 1,000 live births (SVRS 2023); most infant deaths occur in the <strong>neonatal period</strong>.</p>\n<p><strong>A. Medical causes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Period</th>\n<th>Causes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Neonatal</strong> (largest share)</td>\n<td><strong>Prematurity / LBW</strong>, <strong>birth asphyxia</strong>, <strong>neonatal sepsis</strong>, pneumonia, hypothermia, congenital anomalies, jaundice</td>\n</tr>\n<tr>\n<td><strong>Post-neonatal</strong></td>\n<td><strong>Pneumonia / ARI</strong>, <strong>diarrhoea</strong>, malnutrition, measles and other vaccine-preventable diseases, injuries (drowning in late infancy)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Underlying (social) causes: why IMR is high in developing countries</strong></p>\n<ol>\n<li><strong>Maternal factors</strong>: teenage pregnancy, short birth intervals, high parity, malnutrition and anaemia → LBW.</li>\n<li><strong>Home deliveries</strong> without skilled attendants; poor newborn care.</li>\n<li>Poor <strong>ANC</strong> and access to emergency obstetric and newborn care.</li>\n<li><strong>Poverty</strong>, illiteracy (especially female), low status of women.</li>\n<li>Poor <strong>breastfeeding</strong> practices (prelacteal feeds, late initiation) and faulty complementary feeding.</li>\n<li><strong>Unsafe water, poor sanitation and hygiene</strong>.</li>\n<li><strong>Incomplete immunisation</strong>.</li>\n<li>Delayed <strong>care-seeking</strong>; reliance on quacks.</li>\n<li>Overcrowding, indoor air pollution.</li>\n<li>Weak health system: shortage of staff, special care newborn units.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics); BBS SVRS 2023 (The Financial Express, 2024), https://today.thefinancialexpress.com.bd/print/life-expectancy-falls-in-bd-bbs-1724781053</p>"},{"id":"DU.435","n":435,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["19M","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Mention the measures for prevention of IMR / what interventions will you take to reduce IMR?</p>","a":"<p><strong>Measures to reduce IMR</strong></p>\n<p><strong>A. Before and during pregnancy</strong></p>\n<ol>\n<li>Delay first pregnancy (end child marriage); <strong>birth spacing</strong> (family planning).</li>\n<li><strong>Maternal nutrition</strong>: IFA, calcium, extra food; treat anaemia.</li>\n<li><strong>ANC</strong> (≥8 contacts); Td; screening (syphilis, HIV, HBsAg).</li>\n<li>Antenatal corticosteroids for preterm labour (facility).</li>\n</ol>\n<p><strong>B. At birth</strong></p>\n<ol>\n<li><strong>Skilled birth attendance / facility delivery</strong>; clean delivery.</li>\n<li><strong>Essential newborn care</strong>: drying, warmth, <strong>early breastfeeding</strong>, <strong>chlorhexidine</strong> cord care, vitamin K, eye care.</li>\n<li><strong>Newborn resuscitation</strong> (Helping Babies Breathe).</li>\n</ol>\n<p><strong>C. After birth</strong></p>\n<ol>\n<li><strong>Kangaroo mother care</strong> for LBW; special care newborn units.</li>\n<li>Management of possible serious bacterial infection (PSBI).</li>\n<li><strong>Exclusive breastfeeding</strong> 6 months; complementary feeding.</li>\n<li><strong>Immunisation</strong> (EPI) on time.</li>\n<li><strong>IMCI</strong>: ORS + zinc for diarrhoea, antibiotics for pneumonia; vitamin A.</li>\n<li>Postnatal home visits.</li>\n</ol>\n<p><strong>D. Community and social</strong></p>\n<p>WASH; female education; poverty reduction; health education; drowning prevention (supervision, crèches); strong referral and transport.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.436","n":436,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>In a community among 50,000 population, 1000 were under 1 year of age of which 50 died before their birthday. Total live birth was 1500. Calculate IMR of that community.</p>","a":"<p><strong>Formula</strong></p>\n<p>IMR = (Number of deaths of infants under 1 year in a year ÷ Number of live births in the same year) × 1,000</p>\n<p><strong>Calculation</strong></p>\n<p>Infant deaths = 50; live births = 1,500</p>\n<p>IMR = (50 ÷ 1,500) × 1,000 = <strong>33.3 per 1,000 live births</strong></p>\n<p><strong>Note</strong></p>\n<p>The denominator is <strong>live births</strong> (1,500), not the number of infants alive (1,000) or the total population (50,000).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Information and Basic Medical Statistics).</p>"},{"id":"DU.437","n":437,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["24Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>How is the infant mortality rate defined and what does it indicate?</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Infant mortality rate (IMR)</strong>: the number of deaths of children <strong>under one year of age</strong> in a year per <strong>1,000 live births</strong> in the same year.</p>\n<p>IMR = (Infant deaths in a year ÷ Live births in that year) × 1,000</p>\n<p><strong>Components</strong></p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Age</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Neonatal mortality</td>\n<td>0–27 days (early: 0–6 days; late: 7–27 days)</td>\n</tr>\n<tr>\n<td>Post-neonatal mortality</td>\n<td>28 days–under 1 year</td>\n</tr>\n</tbody>\n</table>\n<p><strong>What it indicates</strong></p>\n<ol>\n<li><strong>Most sensitive indicator</strong> of the health status of a community.</li>\n<li>Reflects the <strong>level of living</strong> (socio-economic status) of people.</li>\n<li>Reflects the effectiveness of <strong>MCH services</strong> (ANC, delivery care, newborn care, immunisation).</li>\n<li>Reflects <strong>maternal health, nutrition, female education</strong>, sanitation and housing.</li>\n<li>Responds quickly to improvements → good for <strong>comparing</strong> areas and monitoring programmes.</li>\n<li>Neonatal deaths reflect mainly <strong>biological / obstetric</strong> factors; post-neonatal deaths reflect <strong>environmental and social</strong> factors.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.438","n":438,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>What is neonatal mortality?</p>","a":"<p><strong>Neonatal mortality</strong></p>\n<p>Death of a live-born baby within the <strong>first 28 days of life</strong> (0–27 completed days).</p>\n<p><strong>Neonatal mortality rate (NMR)</strong></p>\n<p>NMR = (Deaths of infants under 28 days in a year ÷ Live births in the same year) × 1,000</p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Period</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Early neonatal</td>\n<td>0–6 days (first week; highest risk, first 24 hours)</td>\n</tr>\n<tr>\n<td>Late neonatal</td>\n<td>7–27 days</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Main causes</strong>: prematurity / LBW, birth asphyxia, neonatal sepsis and pneumonia, congenital anomalies, hypothermia.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.439","n":439,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Define perinatal mortality with importance.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Perinatal mortality</strong>: late fetal deaths (stillbirths at ≥28 weeks of gestation) plus early neonatal deaths (within the first 7 days of life).</p>\n<p><strong>Perinatal mortality rate (Park)</strong></p>\n<p>PMR = [(Late fetal deaths ≥28 weeks + Early neonatal deaths in first week) in a year ÷ Live births in the same year] × 1,000</p>\n<p>(WHO international comparisons use total births, i.e., live births + stillbirths, as the denominator.)</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li>Reflects <strong>quality of antenatal, intranatal and newborn care</strong>.</li>\n<li>Reflects <strong>maternal health and nutrition</strong> (LBW, pre-eclampsia, anaemia).</li>\n<li>Combines stillbirths and early neonatal deaths, which share causes (asphyxia, prematurity, obstetric complications).</li>\n<li>Sensitive indicator of <strong>obstetric services</strong> and EmOC availability.</li>\n<li>Used to plan and evaluate <strong>MCH programmes</strong>; perinatal death audit improves care.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.440","n":440,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Mention the causes of perinatal mortality.</p>","a":"<p><strong>Causes of perinatal mortality</strong></p>\n<ol>\n<li><strong>Low birth weight / prematurity</strong>.</li>\n<li><strong>Birth asphyxia</strong>; birth injuries.</li>\n<li><strong>Intrauterine and neonatal infections</strong> (syphilis, sepsis).</li>\n<li><strong>Congenital anomalies</strong>.</li>\n<li><strong>Maternal conditions</strong>: pre-eclampsia/eclampsia, APH, diabetes, anaemia, malnutrition, infections.</li>\n<li><strong>Obstetric complications</strong>: obstructed labour, malpresentation, cord prolapse, prolonged labour.</li>\n<li>Rh incompatibility; multiple pregnancy.</li>\n<li><strong>Maternal factors</strong>: age &lt;18 or &gt;35, high parity, short interval.</li>\n<li><strong>Socio-economic</strong>: poverty, illiteracy, home delivery without skilled care, poor ANC.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.441","n":441,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["15Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Write down the role of breast feeding in reducing infant mortality.</p>","a":"<p><strong>Role of breastfeeding in reducing infant mortality</strong></p>\n<ol>\n<li><strong>Early initiation</strong> (within 1 hour) reduces neonatal deaths (warmth, colostrum).</li>\n<li><strong>Anti-infective factors</strong> (IgA, lactoferrin, lysozyme) protect against <strong>diarrhoea, pneumonia and sepsis</strong>, the main killers.</li>\n<li><strong>Clean and safe</strong>: avoids contaminated bottle feeds.</li>\n<li><strong>Complete nutrition</strong> for 6 months → prevents malnutrition.</li>\n<li><strong>Birth spacing</strong> (lactational amenorrhoea) → healthier mothers and babies.</li>\n<li>Continued breastfeeding during illness aids recovery.</li>\n<li>Lower risk of NEC in preterm babies; better survival of LBW babies.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.442","n":442,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["13Ju","13Ja","11Ja"],"colleges":"DMC (2nd Assess B3); SSMC (2nd Term A2); MuMC (2nd Final B1)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Define maternal mortality / maternal mortality rate.</p>","a":"<p><strong>Maternal death (WHO, ICD)</strong></p>\n<p>The death of a woman <strong>while pregnant or within 42 days of termination of pregnancy</strong>, irrespective of the duration and site of the pregnancy, from any cause related to or aggravated by the pregnancy or its management, but <strong>not from accidental or incidental causes</strong>.</p>\n<p><strong>Maternal mortality rate</strong></p>\n<p>= (Maternal deaths in a year ÷ Women of reproductive age 15–49 in the same year) × 100,000 (or 1,000)</p>\n<p><strong>Maternal mortality ratio (MMR)</strong></p>\n<p>= (Maternal deaths in a year ÷ Live births in the same year) × 100,000</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.443","n":443,"part":8,"topic":"Maternal and Child Health","stars":3,"years":["17Ja","16M","14Ja","11Ja","07Ju","07Ja"],"colleges":"DMC (2nd Assess B3); MuMC (2nd Final B1)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>State / enumerate the (social) causes and factors of high maternal mortality (MMR) in Bangladesh.</p>","a":"<p><strong>Causes of high maternal mortality in Bangladesh</strong></p>\n<p><strong>A. Medical causes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Direct (obstetric)</th>\n<th>Indirect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Postpartum haemorrhage</strong> (leading)</td>\n<td>Anaemia</td>\n</tr>\n<tr>\n<td><strong>Eclampsia</strong> / pre-eclampsia</td>\n<td>Heart disease, hypertension, diabetes</td>\n</tr>\n<tr>\n<td>Obstructed / prolonged labour</td>\n<td>Hepatitis, TB, other infections</td>\n</tr>\n<tr>\n<td>Complications of abortion</td>\n<td>Stroke, suicide (mental illness)</td>\n</tr>\n<tr>\n<td>Puerperal sepsis</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Social and other factors</strong></p>\n<ol>\n<li><strong>Early marriage</strong> and adolescent pregnancy.</li>\n<li><strong>Low education</strong> and status of women; limited decision-making.</li>\n<li><strong>Poverty</strong>; cost of care and transport.</li>\n<li><strong>Home delivery</strong> by untrained attendants.</li>\n<li><strong>Three delays</strong>: deciding to seek care, reaching a facility, receiving care.</li>\n<li>Poor <strong>ANC</strong> use; danger signs not recognised.</li>\n<li><strong>Short birth intervals</strong>, high parity, unwanted pregnancy, unsafe abortion.</li>\n<li>Cultural beliefs, <strong>purdah</strong>, seeking care from traditional healers.</li>\n<li><strong>Health system</strong>: shortage of skilled midwives, EmOC facilities, blood transfusion; weak referral; staff absence.</li>\n<li>Malnutrition and anaemia.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.444","n":444,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"DMC (2nd Assess C1)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>How does the APGAR score help in the identification of high-risk neonates?</p>","a":"<p><strong>APGAR score (Virginia Apgar)</strong></p>\n<p>Assessed at <strong>1 and 5 minutes</strong> after birth; five signs, each scored 0–2 (total 0–10).</p>\n<table>\n<thead>\n<tr>\n<th>Sign</th>\n<th>0</th>\n<th>1</th>\n<th>2</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>A</strong>ppearance (colour)</td>\n<td>Blue / pale</td>\n<td>Body pink, extremities blue</td>\n<td>Completely pink</td>\n</tr>\n<tr>\n<td><strong>P</strong>ulse (heart rate)</td>\n<td>Absent</td>\n<td>&lt;100/min</td>\n<td>≥100/min</td>\n</tr>\n<tr>\n<td><strong>G</strong>rimace (reflex irritability)</td>\n<td>No response</td>\n<td>Grimace</td>\n<td>Cry, cough</td>\n</tr>\n<tr>\n<td><strong>A</strong>ctivity (muscle tone)</td>\n<td>Limp</td>\n<td>Some flexion</td>\n<td>Active movement</td>\n</tr>\n<tr>\n<td><strong>R</strong>espiration</td>\n<td>Absent</td>\n<td>Weak, irregular</td>\n<td>Good cry</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Use in identifying high-risk neonates</strong></p>\n<table>\n<thead>\n<tr>\n<th>Score</th>\n<th>Interpretation</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>7–10</td>\n<td>Normal</td>\n<td>Routine care</td>\n</tr>\n<tr>\n<td>4–6</td>\n<td>Moderate depression (asphyxia)</td>\n<td>Stimulation, airway clearing, oxygen, close watch</td>\n</tr>\n<tr>\n<td>0–3</td>\n<td>Severe asphyxia</td>\n<td><strong>Immediate resuscitation</strong>, special care unit</td>\n</tr>\n</tbody>\n</table>\n<p>A low 5-minute score predicts higher risk of death and neurological damage → baby labelled <strong>high-risk</strong> for follow-up.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.445","n":445,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"DMC (2nd Assess B3)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Mention the measures to reduce maternal mortality.</p>","a":"<p><strong>Measures to reduce maternal mortality</strong></p>\n<ol>\n<li><strong>Antenatal care</strong> (≥8 contacts): IFA, calcium, Td; detect high-risk mothers.</li>\n<li><strong>Skilled birth attendance</strong> and <strong>facility delivery</strong>.</li>\n<li><strong>Emergency obstetric care</strong> (basic and comprehensive) available 24/7: caesarean, <strong>blood transfusion</strong>.</li>\n<li><strong>Active management of third stage</strong> (oxytocin); <strong>misoprostol</strong> where no oxytocin.</li>\n<li><strong>Magnesium sulphate</strong> for eclampsia.</li>\n<li><strong>Family planning</strong>; safe MR and post-abortion care.</li>\n<li><strong>End child marriage</strong>; girls' education.</li>\n<li><strong>Birth preparedness</strong>; tackle the <strong>three delays</strong> (transport, community funds).</li>\n<li>Postnatal care within 24 hours.</li>\n<li>Maternal death surveillance and response.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.446","n":446,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"MuMC (2nd Final B1)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Differentiate between maternal mortality rate and maternal mortality ratio.</p>","a":"<p><strong>Maternal mortality rate vs ratio</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Maternal mortality <strong>rate</strong></th>\n<th>Maternal mortality <strong>ratio</strong> (MMR)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Formula</td>\n<td>Maternal deaths ÷ women of reproductive age (15–49)</td>\n<td>Maternal deaths ÷ live births</td>\n</tr>\n<tr>\n<td>Multiplier</td>\n<td>× 100,000 (or 1,000)</td>\n<td>× 100,000</td>\n</tr>\n<tr>\n<td>Measures</td>\n<td>Risk of maternal death among <strong>all women</strong> of reproductive age (includes fertility level)</td>\n<td><strong>Obstetric risk per pregnancy / birth</strong></td>\n</tr>\n<tr>\n<td>Affected by fertility</td>\n<td>Yes</td>\n<td>No (largely)</td>\n</tr>\n<tr>\n<td>Use</td>\n<td>Burden in population</td>\n<td>Quality of maternal care; international comparison (SDG 3.1)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.447","n":447,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"ShSMC (2nd Term C3)","asked":"","note":"","kind":"","sub":"MMR & IMR","q":"<p>Write down the three delays responsible for maternal deaths.</p>","a":"<p><strong>Three delays model (Thaddeus and Maine)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Delay</th>\n<th>Causes</th>\n<th>Solutions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Delay in deciding to seek care</strong></td>\n<td>Not recognising danger signs; low status of women; cost; cultural beliefs; previous bad experience</td>\n<td>Health education, birth preparedness, women's empowerment</td>\n</tr>\n<tr>\n<td><strong>2. Delay in reaching a health facility</strong></td>\n<td>Distance, poor roads, no transport, floods, cost</td>\n<td>Transport schemes, community funds, nearby facilities, ambulances</td>\n</tr>\n<tr>\n<td><strong>3. Delay in receiving adequate care at the facility</strong></td>\n<td>Staff shortage, no blood, drugs or theatre, poor referral, bureaucracy</td>\n<td>Functional 24/7 EmOC, trained staff, blood banks, referral system</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.448","n":448,"part":8,"topic":"Maternal and Child Health","stars":0,"years":[],"colleges":"ShSMC (1st Term A5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A 2-year-old child from a rural area presents with recurrent diarrhoea, under nutrition &amp; incomplete immunization. [7]</p>\n<ul>\n<li>a) What level(s) of prevention have failed here? (1)</li>\n<li>b) Mention appropriate preventive measures. (2)</li>\n<li>c) Highlight indicators to assess child health care. (2.5)</li>\n<li>d) Explain interaction between malnutrition and infection. (1.5)</li>\n</ul>","a":"<p><strong>a) Levels of prevention that failed (1)</strong></p>\n<p><strong>Primary prevention</strong>: health promotion (nutrition, WASH, hygiene) and specific protection (immunisation); also <strong>secondary prevention</strong> (early diagnosis and treatment of diarrhoea and malnutrition).</p>\n<p><strong>b) Preventive measures (2)</strong></p>\n<ol>\n<li>Complete <strong>immunisation</strong> (catch-up: pentavalent, OPV, IPV, PCV, MR).</li>\n<li><strong>Nutrition</strong>: continued breastfeeding, adequate complementary feeding, vitamin A, deworming, micronutrients; treat malnutrition.</li>\n<li><strong>WASH</strong>: safe water, sanitary latrine, hand-washing with soap, food hygiene.</li>\n<li><strong>Diarrhoea case management</strong>: ORS + zinc; continued feeding.</li>\n<li><strong>Growth monitoring</strong>; health education of mother; birth spacing.</li>\n</ol>\n<p><strong>c) Indicators to assess child health care (2.5)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Indicators</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mortality</td>\n<td>IMR, NMR, U5MR</td>\n</tr>\n<tr>\n<td>Nutrition</td>\n<td>Stunting, wasting, underweight; LBW; anaemia</td>\n</tr>\n<tr>\n<td>Coverage</td>\n<td>Full immunisation, MR coverage, vitamin A, EBF rate, ORS + zinc use, care-seeking for pneumonia</td>\n</tr>\n<tr>\n<td>WASH</td>\n<td>Use of safe water and sanitation</td>\n</tr>\n<tr>\n<td>Service</td>\n<td>Growth monitoring coverage, IMCI coverage, facility delivery</td>\n</tr>\n</tbody>\n</table>\n<p><strong>d) Malnutrition–infection interaction (1.5)</strong></p>\n<p><strong>Vicious cycle</strong>: malnutrition lowers immunity and gut integrity → more frequent, severe, prolonged infections; infections reduce appetite and absorption, increase losses and metabolic needs → worse malnutrition.<br />\nMalnutrition → infection → worse malnutrition → more infection → death</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease; Nutrition and Health).</p>"},{"id":"DU.449","n":449,"part":8,"topic":"Family Planning","stars":3,"years":["05S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define family planning.</p>","a":"<p><strong>Definition (WHO Expert Committee, 1971)</strong></p>\n<p><strong>Family planning</strong>: &quot;a way of thinking and living that is adopted voluntarily, upon the basis of knowledge, attitudes and responsible decisions by individuals and couples, in order to promote the health and welfare of the family group and thus contribute effectively to the social development of a country.&quot;</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.450","n":450,"part":8,"topic":"Family Planning","stars":3,"years":["22Nov","19Nov","19M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enumerate / mention the objectives of family planning.</p>","a":"<p><strong>Objectives of family planning (WHO)</strong></p>\n<p>To help individuals and couples to:</p>\n<ol>\n<li><strong>Avoid unwanted births</strong>.</li>\n<li><strong>Bring about wanted births</strong> (treat infertility).</li>\n<li><strong>Regulate the intervals</strong> between pregnancies.</li>\n<li><strong>Control the timing</strong> of births in relation to the ages of the parents.</li>\n<li><strong>Determine the number</strong> of children in the family.</li>\n</ol>\n<p><strong>Broader aims</strong></p>\n<ol>\n<li>Improve <strong>maternal and child health</strong>: reduce maternal, infant and child deaths.</li>\n<li>Reduce unsafe abortion.</li>\n<li>Enable women's education, employment and empowerment.</li>\n<li>Slow <strong>population growth</strong>; support social and economic development.</li>\n<li>Prevent STIs/HIV (condoms); improve reproductive health.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.451","n":451,"part":8,"topic":"Family Planning","stars":2,"years":["25Nov","14Ju"],"colleges":"ShSMC (2nd Term C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define / discuss unmet need for family planning.</p>","a":"<p><strong>Unmet need for family planning</strong></p>\n<p>The percentage of women of reproductive age (married or in union) who are <strong>fecund and sexually active</strong>, who <strong>want to stop</strong> having children (<strong>limiting</strong>) or <strong>delay the next birth for at least 2 years</strong> (<strong>spacing</strong>), but are <strong>not using any method of contraception</strong>.</p>\n<p><strong>Components</strong></p>\n<ol>\n<li>Unmet need for <strong>spacing</strong>.</li>\n<li>Unmet need for <strong>limiting</strong>.<br />\n(Includes pregnant women whose pregnancy was unwanted or mistimed, and amenorrhoeic women whose last birth was unwanted or mistimed.)</li>\n</ol>\n<p><strong>Total demand</strong> = met need (current users) + unmet need.</p>\n<p><strong>Causes</strong></p>\n<p>Fear of side effects; husband or family opposition; religious or cultural barriers; lack of knowledge or access; poor quality services and stock-outs; husband away (migrant workers); postpartum and breastfeeding women thinking they cannot conceive; cost.</p>\n<p><strong>Importance</strong></p>\n<p>Leads to unintended pregnancies, unsafe abortion, maternal deaths; key target for FP programmes (SDG 3.7: demand satisfied by modern methods).</p>\n<p><strong>Reducing unmet need</strong></p>\n<p>Counselling, wider method choice, postpartum FP, male involvement, community distribution, LARC, urban and hard-to-reach services.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.452","n":452,"part":8,"topic":"Family Planning","stars":2,"years":["25M","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>&quot;Family planning is more than mere birth control&quot; – mention the scope of family planning (services).</p>","a":"<p><strong>&quot;Family planning is more than mere birth control&quot;: scope of FP services (WHO)</strong></p>\n<ol>\n<li>Proper <strong>spacing and limitation</strong> of births.</li>\n<li>Advice on <strong>sterility</strong> (infertility treatment).</li>\n<li><strong>Education for parenthood</strong>.</li>\n<li><strong>Sex education</strong>.</li>\n<li><strong>Screening</strong> for pathological conditions related to the reproductive system (e.g., cervical cancer).</li>\n<li><strong>Genetic counselling</strong>.</li>\n<li><strong>Premarital consultation</strong> and examination.</li>\n<li>Carrying out <strong>pregnancy tests</strong>.</li>\n<li><strong>Marriage counselling</strong>.</li>\n<li>Preparation of couples for the arrival of their <strong>first child</strong>.</li>\n<li>Providing services for <strong>unmarried mothers</strong>.</li>\n<li>Teaching <strong>home economics and nutrition</strong>.</li>\n<li>Providing <strong>adoption services</strong>.</li>\n</ol>\n<p><strong>Modern additions</strong>: STI/HIV prevention, safe MR and post-abortion care, adolescent reproductive health, management of menopause, gender-based violence services.</p>\n<p>Thus FP promotes the <strong>health and welfare of the whole family</strong>, not only fewer births.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.453","n":453,"part":8,"topic":"Family Planning","stars":2,"years":["25M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the criteria of good family planning methods?</p>","a":"<p><strong>Criteria of a good (ideal) contraceptive method (Park)</strong></p>\n<ol>\n<li><strong>Safe</strong>: no serious side effects.</li>\n<li><strong>Effective</strong>: low failure rate.</li>\n<li><strong>Acceptable</strong> to the couple and culture.</li>\n<li><strong>Inexpensive</strong> and easily available.</li>\n<li><strong>Reversible</strong>: fertility returns after stopping (except permanent methods).</li>\n<li><strong>Simple</strong> to use or administer.</li>\n<li><strong>Independent of coitus</strong>.</li>\n<li><strong>Long-lasting</strong>.</li>\n<li>Requires <strong>little or no medical supervision</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.454","n":454,"part":8,"topic":"Family Planning","stars":3,"years":["24Nov","17M","16Nov","16Ja","11Ju"],"colleges":"DMC (2nd Assess A2)","asked":"","note":"","kind":"","sub":"","q":"<p>What is eligible couple and target couple?</p>","a":"<p><strong>Eligible couple</strong></p>\n<p>A <strong>currently married couple</strong> where the wife is in the <strong>reproductive age group</strong> (generally 15–49 years). They need family planning services.</p>\n<p><strong>Target couple</strong></p>\n<p>Eligible couples identified for priority family planning motivation: originally couples with <strong>2–3 living children</strong> (for limiting), later extended to couples with <strong>one child</strong> (for spacing) and newly married couples.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.455","n":455,"part":8,"topic":"Family Planning","stars":3,"years":["14Ju","11Ju","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by Couple Protection Rate (CPR)?</p>","a":"<p><strong>Couple protection rate (CPR)</strong></p>\n<p>The <strong>percentage of eligible couples effectively protected</strong> against childbirth by one or other approved method of family planning (sterilisation, IUD, condom, oral pills, injectables, implants).</p>\n<p>CPR = (Effectively protected eligible couples ÷ Total eligible couples) × 100</p>\n<p>Bangladesh uses <strong>contraceptive prevalence rate</strong>: modern methods 62.1% (SVRS 2023).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning); The Daily Star, 2024, https://www.thedailystar.net/opinion/views/news/why-do-our-surveys-paint-different-pictures-about-our-progress-3583291</p>"},{"id":"DU.456","n":456,"part":8,"topic":"Family Planning","stars":0,"years":["08Ju","07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Briefly discuss the achievement of family planning programmes in Bangladesh.</p>","a":"<p><strong>Achievements of the family planning programme in Bangladesh</strong></p>\n<ol>\n<li><strong>Fertility fell</strong> from very high levels in the 1970s to near replacement: TFR 2.17 (SVRS 2023).</li>\n<li><strong>Contraceptive use</strong> rose greatly: modern CPR 62.1% (SVRS 2023).</li>\n<li>Slower <strong>population growth</strong>; Bangladesh cited worldwide as a family planning success despite poverty.</li>\n<li>Fall in <strong>maternal and child mortality</strong> linked to spacing and fewer high-risk births.</li>\n<li>Nationwide <strong>door-to-door services</strong> (FWAs), satellite clinics, social marketing (SMC).</li>\n<li>Wider <strong>method mix</strong>: pills, injectables, condoms, IUD, implants, permanent methods; MR services.</li>\n<li>Strong <strong>government–NGO partnership</strong>.</li>\n</ol>\n<p><strong>Remaining challenges</strong>: high discontinuation, low LARC/permanent method use, unmet need, adolescent pregnancy, regional gaps (Chattogram, Sylhet).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning); BBS SVRS 2023 (The Daily Star, 2024), https://www.thedailystar.net/opinion/views/news/why-do-our-surveys-paint-different-pictures-about-our-progress-3583291</p>"},{"id":"DU.457","n":457,"part":8,"topic":"Family Planning","stars":0,"years":["05Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss strategies of family planning programmes of Bangladesh.</p>","a":"<p><strong>Strategies of the family planning programme of Bangladesh</strong></p>\n<ol>\n<li><strong>Domiciliary (door-to-door) services</strong> by Family Welfare Assistants.</li>\n<li><strong>Clinic-based services</strong>: UH&amp;FWCs, MCWCs, UHCs, community clinics, satellite clinics.</li>\n<li><strong>Cafeteria approach</strong>: wide choice of methods; emphasis on <strong>LARC and permanent methods</strong>.</li>\n<li><strong>Integration</strong> of FP with MCH, nutrition and health services (ESP).</li>\n<li><strong>Social marketing</strong> (SMC) of pills and condoms.</li>\n<li><strong>IEC / BCC</strong>: mass media, folk media, religious leaders.</li>\n<li><strong>Government–NGO partnership</strong>.</li>\n<li><strong>Postpartum and post-abortion FP</strong>; MR services.</li>\n<li><strong>Male involvement</strong>; adolescent reproductive health.</li>\n<li>Compensation for permanent methods; free supplies.</li>\n<li>Logistics and supply-chain management; MIS.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.458","n":458,"part":8,"topic":"Family Planning","stars":3,"years":["21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the merits of family planning at family level?</p>","a":"<p><strong>Merits of family planning at the family level</strong></p>\n<table>\n<thead>\n<tr>\n<th>For</th>\n<th>Benefits</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Mother</strong></td>\n<td>Fewer high-risk pregnancies (too early, too late, too many, too close) → less maternal death, anaemia, PPH; time to recover between births; less unsafe abortion; better health and nutrition</td>\n</tr>\n<tr>\n<td><strong>Child</strong></td>\n<td>Lower infant and child mortality; better birth weight; longer breastfeeding; more attention, food and care; better growth and education</td>\n</tr>\n<tr>\n<td><strong>Father / family</strong></td>\n<td>Lower economic burden; better standard of living; more resources for education, housing, health</td>\n</tr>\n<tr>\n<td><strong>Couple</strong></td>\n<td>Better marital harmony; planned parenthood; opportunity for woman's education and work</td>\n</tr>\n<tr>\n<td><strong>Family as a whole</strong></td>\n<td>Better quality of life; less poverty; happier family</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.459","n":459,"part":8,"topic":"Family Planning","stars":3,"years":["19Nov","19M","16Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the merits / benefits of family planning at national level / different levels of country?</p>","a":"<p><strong>Benefits of family planning at different levels</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Benefits</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Individual (mother, child)</strong></td>\n<td>Lower maternal and infant mortality; healthier mothers and children; women's education and employment</td>\n</tr>\n<tr>\n<td><strong>Family</strong></td>\n<td>Economic security; better nutrition, schooling, housing; quality of life</td>\n</tr>\n<tr>\n<td><strong>Community</strong></td>\n<td>Less pressure on schools, health services, housing, water; healthier community</td>\n</tr>\n<tr>\n<td><strong>National</strong></td>\n<td><strong>Slower population growth</strong>; demographic dividend; higher per capita income; savings and investment; food security; less unemployment; better use of resources; achievement of SDGs (3.1, 3.2, 3.7, 5)</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>Less pressure on land, forests, water; less pollution</td>\n</tr>\n<tr>\n<td><strong>Global</strong></td>\n<td>Population stabilisation; sustainable development</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.460","n":460,"part":8,"topic":"Family Planning","stars":0,"years":[],"colleges":"DMC (2nd Assess A2)","asked":"","note":"","kind":"","sub":"","q":"<p>State the indications of vasectomy and tubectomy.</p>","a":"<p><strong>Indications of vasectomy and tubectomy (permanent methods)</strong></p>\n<ol>\n<li>Couples who have <strong>completed their family</strong> and want no more children (usually at least two living children, youngest healthy).</li>\n<li><strong>Voluntary request</strong> with <strong>informed consent</strong> after counselling (permanence explained).</li>\n<li><strong>Medical reasons</strong> where pregnancy is dangerous: heart disease, severe hypertension, renal disease, repeated caesarean sections.</li>\n<li><strong>Genetic disorders</strong> with high risk of transmission.</li>\n<li>Failure of, or contraindications to, other methods.</li>\n<li>Tubectomy can be done postpartum (within 7 days), with caesarean section, or as interval procedure; vasectomy (no-scalpel) is simpler and safer.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.461","n":461,"part":8,"topic":"Family Planning","stars":0,"years":[],"colleges":"ShSMC (2nd Term C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention three major determinants of unmet need for family planning.</p>","a":"<p><strong>Three major determinants of unmet need for family planning</strong></p>\n<ol>\n<li><strong>Health concerns and fear of side effects</strong> of methods.</li>\n<li><strong>Opposition</strong> from husband, family or religious beliefs.</li>\n<li><strong>Lack of access</strong>: poor knowledge of methods or sources, stock-outs, distance, cost, poor quality of services.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.462","n":462,"part":8,"topic":"Family Planning","stars":0,"years":[],"colleges":"ShSMC (2nd Term C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between method failure and user failure of contraception.</p>","a":"<p><strong>Method failure vs user failure</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Method failure</th>\n<th>User failure</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Meaning</td>\n<td>Pregnancy despite <strong>correct and consistent use</strong> of the method</td>\n<td>Pregnancy due to <strong>incorrect or inconsistent use</strong></td>\n</tr>\n<tr>\n<td>Cause</td>\n<td>Inherent limitation of the method</td>\n<td>Human error: missed pills, condom not used every time, late injection</td>\n</tr>\n<tr>\n<td>Measure</td>\n<td>Perfect-use failure rate</td>\n<td>Typical-use minus perfect-use failure</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Pregnancy with Cu-T in place</td>\n<td>Pregnancy after forgetting 3 pills</td>\n</tr>\n<tr>\n<td>Reduction</td>\n<td>Better technology</td>\n<td>Counselling, follow-up, LARC</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.463","n":463,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["26M","22M","21M","18Nov","18M","17Nov","17M","16Nov","16Ja","12Ja"],"colleges":"MuMC (2nd Final A1)","asked":"classify temporary contraceptive methods with examples","note":"","kind":"","sub":"","q":"<p>Classify methods of contraception (contraceptive methods with examples; temporary methods; methods for female; common methods used in Bangladesh).</p>","a":"<p><strong>Classification of contraceptive methods (Park)</strong></p>\n<p><strong>A. Spacing (temporary) methods</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Methods</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Barrier methods</strong></td>\n<td>Physical: <strong>condom</strong>, diaphragm, cervical cap, vaginal sponge; Chemical: spermicides (foams, jellies, creams, tablets); Combined</td>\n</tr>\n<tr>\n<td><strong>2. Intrauterine devices</strong></td>\n<td>1st generation: Lippes loop; 2nd generation (copper): <strong>Cu-T 380A</strong>, Cu-T 200, Multiload; 3rd generation (hormonal): LNG-IUS</td>\n</tr>\n<tr>\n<td><strong>3. Hormonal methods</strong></td>\n<td><strong>Oral pills</strong> (combined, progestogen-only, emergency); <strong>injectables</strong> (DMPA 3-monthly, NET-EN); <strong>implants</strong> (Implanon, Jadelle); vaginal ring, patch</td>\n</tr>\n<tr>\n<td><strong>4. Post-conceptional methods</strong></td>\n<td><strong>Menstrual regulation</strong>, menstrual induction, abortion</td>\n</tr>\n<tr>\n<td><strong>5. Miscellaneous / natural</strong></td>\n<td>Abstinence, coitus interruptus, safe period (calendar), basal body temperature, cervical mucus method, symptothermal, <strong>LAM</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Terminal (permanent) methods</strong></p>\n<ul>\n<li>Male: <strong>vasectomy</strong> (no-scalpel vasectomy).</li>\n<li>Female: <strong>tubectomy</strong> (minilaparotomy, laparoscopic).</li>\n</ul>\n<p><strong>Methods for females</strong>: pills, injectables, implants, IUD, diaphragm, female condom, tubectomy, LAM.</p>\n<p><strong>Common in Bangladesh</strong>: oral pills (most used), injectables, condoms, implants, IUD, tubectomy, NSV, MR.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.464","n":464,"part":8,"topic":"Contraceptive Methods","stars":0,"years":["09Ja","07Ju","06Ja","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the mode of action (mechanism) of copper-T / medicated Cu-T / 3rd generation IUDs.</p>","a":"<p><strong>Mode of action of IUDs</strong></p>\n<p><strong>Copper IUD (Cu-T 380A, medicated)</strong></p>\n<ol>\n<li>Local <strong>foreign-body inflammatory reaction</strong> in the endometrium (leucocytes, macrophages) → phagocytosis of sperm.</li>\n<li><strong>Copper ions</strong> are toxic to sperm and ova: reduce sperm motility, viability and capacitation → <strong>prevent fertilisation</strong> (main action).</li>\n<li>Biochemical changes in endometrium and cervical mucus → hostile to sperm and implantation.</li>\n<li>May prevent implantation if fertilisation occurs (used as emergency contraception).</li>\n</ol>\n<p><strong>Hormone-releasing IUD (3rd generation: LNG-IUS)</strong></p>\n<ol>\n<li><strong>Thickens cervical mucus</strong> → sperm cannot pass.</li>\n<li><strong>Endometrial suppression</strong> (thin, inactive endometrium).</li>\n<li>Partial inhibition of ovulation in some cycles.</li>\n<li>Reduces menstrual blood loss.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.465","n":465,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["25Nov","20Nov","14Ju","06Ja"],"colleges":"SSMC (2nd Term A3); MMC (2nd Term C1)","asked":"who are the ideal candidates for IUCD","note":"","kind":"","sub":"","q":"<p>Outline the client criteria for IUCD / who are the ideal candidates for insertion of IUCD?</p>","a":"<p><strong>Ideal candidate (client criteria) for IUCD (Park)</strong></p>\n<p>A woman:</p>\n<ol>\n<li>Who has <strong>borne at least one child</strong>.</li>\n<li>Has <strong>no history of pelvic disease</strong> (PID, STI).</li>\n<li>Has <strong>normal menstrual periods</strong> (no heavy or irregular bleeding).</li>\n<li>Is <strong>willing to check the IUD tail</strong> (threads).</li>\n<li>Has <strong>access to follow-up</strong> and treatment of complications.</li>\n<li>Is in a <strong>monogamous relationship</strong> (low STI risk).</li>\n</ol>\n<p><strong>Other suitable clients</strong></p>\n<p>Women wanting long-acting, reversible, non-hormonal contraception; breastfeeding mothers; postpartum (within 48 hours or after 4 weeks) and post-abortion women; women with contraindications to hormones; emergency contraception within 5 days.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.466","n":466,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["17M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the contraindications of IUD.</p>","a":"<p><strong>Contraindications of IUD</strong></p>\n<p><strong>A. Absolute</strong></p>\n<ol>\n<li><strong>Suspected pregnancy</strong>.</li>\n<li><strong>Pelvic inflammatory disease</strong> (current or recent), purulent cervicitis, current gonorrhoea/chlamydia.</li>\n<li><strong>Unexplained vaginal bleeding</strong>.</li>\n<li><strong>Cancer</strong> of cervix, uterus or adnexa; malignant trophoblastic disease.</li>\n<li><strong>Previous ectopic pregnancy</strong> (Park).</li>\n<li>Puerperal sepsis; immediately after septic abortion.</li>\n<li><strong>Uterine cavity distortion</strong> (fibroids, congenital anomalies); pelvic TB.</li>\n</ol>\n<p><strong>B. Relative</strong></p>\n<ol>\n<li><strong>Anaemia</strong>; heavy or painful periods.</li>\n<li>History of PID since last pregnancy; high STI risk (multiple partners).</li>\n<li>Nulliparity, small uterus.</li>\n<li>Inability to check threads or attend follow-up.</li>\n<li>Wilson's disease or copper allergy (copper IUD).</li>\n<li>Valvular heart disease (infection risk).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.467","n":467,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["16Ja","11Ju","09Ja","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List the complications / disadvantages of IUCDs (copper-T).</p>","a":"<p><strong>Complications / disadvantages of IUCD (Cu-T)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Complication</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Bleeding</strong></td>\n<td>Heavier, longer periods; spotting; commonest cause of removal; anaemia</td>\n</tr>\n<tr>\n<td><strong>2. Pain</strong></td>\n<td>Cramps, backache; dysmenorrhoea</td>\n</tr>\n<tr>\n<td><strong>3. Pelvic infection (PID)</strong></td>\n<td>Mainly in first 20 days after insertion; STI risk</td>\n</tr>\n<tr>\n<td><strong>4. Uterine perforation</strong></td>\n<td>At insertion; device may migrate to abdomen</td>\n</tr>\n<tr>\n<td><strong>5. Expulsion</strong></td>\n<td>Mostly in first few months, often during menses</td>\n</tr>\n<tr>\n<td><strong>6. Pregnancy (failure)</strong></td>\n<td>Low (&lt;1 per 100 women-years); risk of septic abortion if left</td>\n</tr>\n<tr>\n<td><strong>7. Ectopic pregnancy</strong></td>\n<td>If pregnancy occurs, higher proportion are ectopic</td>\n</tr>\n<tr>\n<td><strong>8. Missing threads</strong></td>\n<td>Expulsion, perforation, pregnancy, curled thread</td>\n</tr>\n<tr>\n<td>9. Vaginal discharge</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other disadvantages</strong></p>\n<p>Needs trained provider for insertion and removal; pelvic examination; no protection against STIs/HIV.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.468","n":468,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify hormonal pills.</p>","a":"<p><strong>Classification of hormonal contraceptive pills</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Composition</th>\n<th>Example / use</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Combined oral pill (COC)</strong></td>\n<td>Oestrogen (ethinyl oestradiol) + progestogen</td>\n<td><strong>Monophasic</strong> (same dose all days; e.g., Shukhi, Femicon), <strong>biphasic</strong>, <strong>triphasic</strong></td>\n</tr>\n<tr>\n<td><strong>2. Progestogen-only pill (POP, mini-pill)</strong></td>\n<td>Progestogen only (levonorgestrel, desogestrel)</td>\n<td>Breastfeeding women; oestrogen contraindicated (e.g., Minicon)</td>\n</tr>\n<tr>\n<td><strong>3. Post-coital (emergency) pill</strong></td>\n<td>Levonorgestrel 1.5 mg; ulipristal acetate; Yuzpe regimen (combined pills)</td>\n<td>Within 72–120 hours of unprotected intercourse</td>\n</tr>\n<tr>\n<td><strong>4. Once-a-month pill</strong></td>\n<td>Long-acting oestrogen + short-acting progestogen</td>\n<td>Limited use</td>\n</tr>\n<tr>\n<td><strong>5. Male pill</strong></td>\n<td>Experimental</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>6. Non-steroidal weekly pill</strong></td>\n<td>Centchroman (ormeloxifene)</td>\n<td>India (Saheli)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.469","n":469,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["24M","23Nov","21M","15Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the advantages, disadvantages, complications and health hazards of OCP.</p>","a":"<p><strong>Combined oral contraceptive pill (OCP)</strong></p>\n<p><strong>Advantages</strong></p>\n<ol>\n<li><strong>Highly effective</strong> (&gt;99% with perfect use); reversible.</li>\n<li>Regular, lighter, less painful periods → <strong>less anaemia</strong>, dysmenorrhoea.</li>\n<li>Protection against <strong>ovarian and endometrial cancer</strong>, benign breast disease, functional ovarian cysts, ectopic pregnancy, PID.</li>\n<li>Reduces acne, PMS, endometriosis symptoms.</li>\n<li>Independent of coitus; user-controlled.</li>\n</ol>\n<p><strong>Disadvantages</strong></p>\n<ol>\n<li><strong>Daily intake</strong> required; missed pills → failure.</li>\n<li>No protection against <strong>STIs/HIV</strong>.</li>\n<li>Reduces <strong>milk supply</strong> (not for early breastfeeding).</li>\n<li>Needs regular supply; cost.</li>\n<li>Drug interactions (rifampicin, anticonvulsants).</li>\n</ol>\n<p><strong>Minor side effects</strong></p>\n<p>Nausea, breast tenderness, headache, spotting / breakthrough bleeding, weight gain, mood changes, amenorrhoea.</p>\n<p><strong>Complications / health hazards</strong></p>\n<ol>\n<li><strong>Venous thromboembolism</strong>, pulmonary embolism.</li>\n<li><strong>Stroke, myocardial infarction</strong> (smokers &gt;35 years, hypertension).</li>\n<li><strong>Hypertension</strong>.</li>\n<li>Liver: benign hepatic adenoma, cholestatic jaundice, gallstones.</li>\n<li>Slight increase in cervical cancer risk with long use; breast cancer risk (small, while using).</li>\n<li>Glucose intolerance; depression.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.470","n":470,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["26M","22M"],"colleges":"MuMC (2nd Final A1)","asked":"5 major absolute contraindications of OCP","note":"","kind":"","sub":"","q":"<p>Enumerate the indications and contraindications of oral contraceptive pills.</p>","a":"<p><strong>Indications of OCP</strong></p>\n<ol>\n<li>Healthy women wanting <strong>reversible, highly effective</strong> contraception (spacing).</li>\n<li><strong>Menstrual disorders</strong>: dysmenorrhoea, menorrhagia, irregular cycles, PMS.</li>\n<li><strong>Endometriosis</strong>, <strong>PCOS</strong> (acne, hirsutism), functional ovarian cysts.</li>\n<li>Women with iron-deficiency anaemia due to heavy periods.</li>\n<li>Emergency contraception (Yuzpe regimen).</li>\n</ol>\n<p><strong>Contraindications</strong></p>\n<p><strong>Absolute</strong></p>\n<ol>\n<li><strong>Thromboembolism</strong> (present or past), stroke, ischaemic heart disease.</li>\n<li><strong>Breast cancer</strong>; oestrogen-dependent tumours.</li>\n<li><strong>Liver disease</strong>: active hepatitis, cirrhosis, liver tumour.</li>\n<li><strong>Undiagnosed vaginal bleeding</strong>.</li>\n<li><strong>Pregnancy</strong>.</li>\n<li><strong>Smokers aged ≥35</strong> (≥15 cigarettes/day).</li>\n<li><strong>Severe hypertension</strong> (≥160/100 mmHg); migraine with aura.</li>\n<li>Diabetes with vascular complications.</li>\n<li>Breastfeeding &lt;6 weeks postpartum; major surgery with prolonged immobilisation.</li>\n</ol>\n<p><strong>Relative</strong></p>\n<p>Controlled hypertension, epilepsy (drug interaction), gallbladder disease, depression, age &gt;40, obesity, sickle-cell disease, use of enzyme-inducing drugs (rifampicin).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.471","n":471,"part":8,"topic":"Contraceptive Methods","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the causes of failure of vasectomy &amp; tubectomy.</p>","a":"<p><strong>Causes of failure of vasectomy</strong></p>\n<ol>\n<li><strong>Unprotected intercourse soon after the operation</strong>: sperm remain in the distal vas for about 3 months (~20 ejaculations); semen must be checked for azoospermia.</li>\n<li><strong>Spontaneous recanalisation</strong> of the vas.</li>\n<li><strong>Wrong structure ligated</strong> or one vas missed; <strong>duplicate vas</strong>.</li>\n</ol>\n<p><strong>Causes of failure of tubectomy</strong></p>\n<ol>\n<li><strong>Recanalisation</strong> or tubo-peritoneal fistula.</li>\n<li><strong>Faulty technique</strong>: wrong structure (round ligament) ligated, clip / ring misapplied.</li>\n<li><strong>Pre-existing pregnancy</strong> at the time of operation (luteal phase).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.472","n":472,"part":8,"topic":"Contraceptive Methods","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is pearl index?</p>","a":"<p><strong>Pearl index</strong></p>\n<p>The <strong>failure rate</strong> of a contraceptive method expressed as the <strong>number of failures (accidental pregnancies) per 100 woman-years of exposure</strong> (HY = 100 women using the method for one year).</p>\n<p><strong>Formula</strong></p>\n<p>Pearl index = (Total accidental pregnancies × 1,200) ÷ Total months of exposure<br />\n(1,200 = 12 months × 100 women; some use 1,300 with 13 cycles per year.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.473","n":473,"part":8,"topic":"Contraceptive Methods","stars":3,"years":[],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the merits and demerits of safe period.</p>","a":"<p><strong>Safe period (rhythm / calendar method)</strong></p>\n<p><strong>Merits</strong></p>\n<ol>\n<li><strong>No cost</strong>; no devices or drugs.</li>\n<li><strong>No side effects</strong>.</li>\n<li>Acceptable to religions and cultures that oppose other methods.</li>\n<li>Involves cooperation of <strong>both partners</strong>.</li>\n<li>Knowledge of fertile period also helps couples who <strong>want</strong> pregnancy.</li>\n</ol>\n<p><strong>Demerits</strong></p>\n<ol>\n<li><strong>High failure rate</strong> (typical use).</li>\n<li>Not usable with <strong>irregular cycles</strong>, after childbirth, during breastfeeding, near menopause.</li>\n<li>Requires <strong>abstinence</strong> for many days → frustration.</li>\n<li>Needs careful <strong>record of cycles</strong> and motivation.</li>\n<li>No protection against STIs/HIV.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.474","n":474,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["19Nov","17Nov","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you calculate safe period? (28-day cycle; shortest 22 days and longest 35 days).</p>","a":"<p><strong>Calendar (Ogino–Knaus) method</strong></p>\n<p>Based on: ovulation occurs about 14 (12–16) days before the next period; sperm survive ~3 days; ovum ~1 day.</p>\n<p><strong>Formula</strong> (using records of at least 6 cycles)</p>\n<ul>\n<li><strong>First fertile (unsafe) day</strong> = shortest cycle − 18</li>\n<li><strong>Last fertile (unsafe) day</strong> = longest cycle − 11</li>\n</ul>\n<p><strong>a) Regular 28-day cycle</strong></p>\n<p>First fertile day = 28 − 18 = <strong>day 10</strong>; last fertile day = 28 − 11 = <strong>day 17</strong><br />\n→ <strong>Unsafe: days 10–17</strong>; <strong>safe: days 1–9 and 18–28</strong>.</p>\n<p><strong>b) Shortest 22 days, longest 35 days</strong></p>\n<p>First fertile day = 22 − 18 = <strong>day 4</strong>; last fertile day = 35 − 11 = <strong>day 24</strong><br />\n→ <strong>Unsafe: days 4–24</strong>; <strong>safe: days 1–3 and from day 25 to the next period</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.475","n":475,"part":8,"topic":"Contraceptive Methods","stars":3,"years":["22M","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss emergency contraceptive pills. What is emergency contraceptive pill?</p>","a":"<p><strong>Emergency contraceptive pill (ECP)</strong></p>\n<p>Hormonal pills taken <strong>after unprotected intercourse</strong> to prevent pregnancy; &quot;morning-after pill&quot;.</p>\n<p><strong>Regimens</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Dose</th>\n<th>Time limit</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Levonorgestrel</strong></td>\n<td>1.5 mg single dose (or 0.75 mg × 2, 12 hours apart)</td>\n<td>Best within 72 hours; up to 120 hours (less effective)</td>\n</tr>\n<tr>\n<td><strong>Ulipristal acetate</strong></td>\n<td>30 mg single dose</td>\n<td>Up to 120 hours</td>\n</tr>\n<tr>\n<td><strong>Yuzpe (combined pills)</strong></td>\n<td>100 µg ethinyl oestradiol + 0.5 mg levonorgestrel, repeated after 12 hours</td>\n<td>Within 72 hours</td>\n</tr>\n<tr>\n<td>Copper IUD (most effective EC)</td>\n<td>Insertion</td>\n<td>Within 5 days</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Mode of action</strong></p>\n<p>Mainly <strong>delays or inhibits ovulation</strong>; does <strong>not</strong> cause abortion and does not harm an established pregnancy.</p>\n<p><strong>Indications</strong></p>\n<p>Unprotected sex; condom burst or slipped; missed pills; late injection; sexual assault.</p>\n<p><strong>Side effects</strong></p>\n<p>Nausea, vomiting (repeat if vomiting within 2 hours), irregular bleeding, headache, breast tenderness.</p>\n<p><strong>Points</strong></p>\n<p>Earlier = more effective; not a regular method; start a regular method afterwards; no STI protection.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.476","n":476,"part":8,"topic":"Contraceptive Methods","stars":2,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define menstrual regulation.</p>","a":"<p><strong>Menstrual regulation (MR)</strong></p>\n<p>A procedure to <strong>regulate (bring back) menstruation</strong> in a woman whose period is <strong>missed for a short time</strong>, done <strong>without confirming pregnancy</strong>, by:</p>\n<ol>\n<li><strong>Manual vacuum aspiration (MVA)</strong> of the uterine contents, or</li>\n<li><strong>Medication (MRM)</strong>: mifepristone + misoprostol.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.477","n":477,"part":8,"topic":"Contraceptive Methods","stars":0,"years":[],"colleges":"SSMC (2nd Term A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Classify IUCDs.</p>","a":"<p><strong>Classification of IUCDs</strong></p>\n<table>\n<thead>\n<tr>\n<th>Generation</th>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>First</strong></td>\n<td>Inert (non-medicated), polyethylene</td>\n<td><strong>Lippes loop</strong></td>\n</tr>\n<tr>\n<td><strong>Second</strong></td>\n<td><strong>Copper-bearing</strong></td>\n<td>Cu-7, Cu-T 200, Cu-T 220C, <strong>Cu-T 380A</strong>, Nova-T, Multiload-250/375</td>\n</tr>\n<tr>\n<td><strong>Third</strong></td>\n<td><strong>Hormone-releasing</strong></td>\n<td>Progestasert (progesterone), <strong>LNG-IUS</strong> (levonorgestrel; Mirena)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.478","n":478,"part":8,"topic":"Contraceptive Methods","stars":0,"years":[],"colleges":"MMC (2nd Term C1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the non-contraceptive uses of condom and OCP.</p>","a":"<p><strong>Non-contraceptive uses</strong></p>\n<p><strong>Condom</strong></p>\n<ol>\n<li>Prevention of <strong>STIs and HIV</strong>.</li>\n<li>Reduces risk of <strong>cervical cancer</strong> (HPV) and PID.</li>\n<li>Helps premature ejaculation.</li>\n<li>Sperm allergy (in female partner).</li>\n<li>Semen collection; cover for ultrasound probes.</li>\n<li><strong>Condom-catheter balloon tamponade</strong> for PPH.</li>\n</ol>\n<p><strong>Oral contraceptive pill</strong></p>\n<ol>\n<li>Dysmenorrhoea, menorrhagia, irregular cycles, PMS.</li>\n<li>Endometriosis; PCOS (acne, hirsutism).</li>\n<li>Functional ovarian cysts.</li>\n<li>Reduced <strong>ovarian and endometrial cancer</strong>, benign breast disease.</li>\n<li>Less iron-deficiency anaemia, ectopic pregnancy, PID.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.479","n":479,"part":8,"topic":"Contraceptive Methods","stars":0,"years":[],"colleges":"DMC (2nd Assess A5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A 28-year-old woman with two children requests for long-acting contraception. [7]</p>\n<ul>\n<li>a) What contraceptive options can be offered? (2)</li>\n<li>b) Which factors should be considered before selecting options? (2)</li>\n<li>c) Which will be the most appropriate option, justify. (3)</li>\n</ul>","a":"<p><strong>a) Long-acting options (2)</strong></p>\n<ol>\n<li><strong>Copper IUD (Cu-T 380A)</strong>: effective for 10+ years.</li>\n<li><strong>Hormonal IUD (LNG-IUS)</strong>: 5 years.</li>\n<li><strong>Implants</strong>: Implanon (3 years), Jadelle (5 years).</li>\n<li><strong>Injectable DMPA</strong> (3-monthly; medium-acting).</li>\n<li><strong>Permanent methods</strong>: tubectomy (her) or vasectomy (husband), if family is complete.</li>\n</ol>\n<p><strong>b) Factors to consider (2)</strong></p>\n<ol>\n<li><strong>Reproductive intention</strong>: wants more children later (spacing) or none (limiting).</li>\n<li><strong>Medical eligibility</strong> (WHO MEC): anaemia, heavy periods, PID or STI risk, hypertension, liver disease, breast cancer, thromboembolism.</li>\n<li><strong>Breastfeeding</strong> status; time since delivery.</li>\n<li>Menstrual pattern and tolerance of bleeding changes.</li>\n<li><strong>Partner's view</strong>, religious and cultural beliefs.</li>\n<li><strong>Side-effect concerns</strong>, previous experience.</li>\n<li>Availability, cost, access to follow-up and removal services.</li>\n<li>STI risk (use condom as well if at risk).</li>\n</ol>\n<p><strong>c) Most appropriate option, with justification (3)</strong></p>\n<p><strong>If she may want another child later: Cu-T 380A</strong> (or implant)</p>\n<ol>\n<li>Highly effective (failure &lt;1%); long-acting (up to 10–12 years).</li>\n<li><strong>Reversible</strong> immediately on removal.</li>\n<li><strong>Non-hormonal</strong>: no systemic side effects; no effect on breastfeeding.</li>\n<li>Free in government facilities; low cost; few visits.</li>\n<li>Suitable for a parous woman with two children (ideal candidate if no PID, normal periods).<br />\n(Implant is the choice if she has heavy periods or anaemia.)</li>\n</ol>\n<p><strong>If her family is complete: tubectomy (or husband's no-scalpel vasectomy)</strong>: permanent, one-time, most effective; after informed consent.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.480","n":480,"part":8,"topic":"Contraceptive Methods","stars":0,"years":[],"colleges":"SSMC (2nd Term A5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A 25-year-old mother is 3 months postpartum, exclusively breastfeeding her baby day and night. She has no menstrual bleeding yet. [3+2+2]</p>\n<ul>\n<li>a) Name the method of contraception &amp; its mode of action?</li>\n<li>b) State the advantages and limitations of the method.</li>\n<li>c) What advice should be given after 6 months?</li>\n</ul>","a":"<p><strong>a) Method and mode of action (3)</strong></p>\n<p><strong>Lactational Amenorrhoea Method (LAM)</strong>.</p>\n<p><strong>Criteria</strong> (all three needed): 1. no return of menses; 2. <strong>fully or nearly fully breastfeeding</strong> day and night; 3. baby <strong>&lt;6 months</strong> old → ~98% protection.</p>\n<p><strong>Mode of action</strong>: frequent suckling → nerve impulses to hypothalamus → raised <strong>prolactin</strong> and disturbed <strong>GnRH pulsatility</strong> → low FSH and LH → <strong>ovulation suppressed</strong> → amenorrhoea and infertility.</p>\n<p><strong>b) Advantages and limitations (2)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Advantages</th>\n<th>Limitations</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Free, natural, no drugs or devices</td>\n<td>Effective only up to <strong>6 months</strong></td>\n</tr>\n<tr>\n<td>No side effects; safe for mother and baby</td>\n<td>All three criteria must be met</td>\n</tr>\n<tr>\n<td>Starts immediately after birth</td>\n<td>Fails if feeds are spaced (&gt;4 h day, &gt;6 h night) or supplements are given</td>\n</tr>\n<tr>\n<td>Promotes exclusive breastfeeding</td>\n<td>Not reliable for working mothers away from baby</td>\n</tr>\n<tr>\n<td>Culturally and religiously acceptable</td>\n<td>No protection against STIs/HIV</td>\n</tr>\n</tbody>\n</table>\n<p><strong>c) Advice after 6 months (2)</strong></p>\n<ol>\n<li><strong>Start another method</strong> now (or earlier if menses return or breastfeeding drops): progestogen-only pill, DMPA injection, implant, Cu-T, condom; combined pill acceptable after 6 months.</li>\n<li><strong>Continue breastfeeding</strong> with complementary foods up to 2 years.</li>\n<li>Come back early if periods return or the baby starts other feeds.</li>\n<li>Spacing of at least 24 months before the next pregnancy.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.481","n":481,"part":8,"topic":"Contraceptive Methods","stars":0,"years":[],"colleges":"MuMC (2nd Final C5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A 26-year-old lady visited a primary health clinic complaining that she could not feel or trace thread of her IUCD (Cu-T) for the last few days. She had a Cu-T 380A inserted 2 years ago without any immediate complications. [2+3+2]</p>\n<ul>\n<li>(a) List the possible causes of a missing Cu-T thread. (2)</li>\n<li>(b) Explain the aims and recommended schedule of follow up after IUCD insertion. (3)</li>\n<li>(c) Evaluate the public health impact of such cases on the local Family Planning Program. (2)</li>\n</ul>","a":"<p><strong>(a) Causes of missing Cu-T thread (2)</strong></p>\n<ol>\n<li>Thread <strong>drawn up into the cervical canal or uterus</strong> (curled).</li>\n<li>Thread cut too short or broken.</li>\n<li><strong>Unnoticed expulsion</strong> of the IUD.</li>\n<li><strong>Uterine perforation</strong> / translocation into the abdomen.</li>\n<li><strong>Pregnancy</strong> (enlarging uterus pulls the thread up).</li>\n<li>Displacement / embedding in the myometrium.</li>\n</ol>\n<p><strong>Approach</strong>: exclude pregnancy; speculum and thread retriever; <strong>ultrasound</strong>; X-ray if not seen in uterus; back-up contraception until resolved.</p>\n<p><strong>(b) Aims and schedule of follow-up after IUCD insertion (3)</strong></p>\n<p><strong>Aims</strong></p>\n<ol>\n<li>Detect <strong>expulsion</strong> and check <strong>threads</strong>.</li>\n<li>Manage <strong>side effects</strong> (bleeding, pain) early.</li>\n<li>Detect <strong>infection (PID)</strong>, especially in the first weeks.</li>\n<li>Detect <strong>pregnancy / ectopic pregnancy</strong>.</li>\n<li>Reassure and counsel → reduce discontinuation.</li>\n<li>Plan <strong>timely removal / replacement</strong>.</li>\n</ol>\n<p><strong>Schedule</strong></p>\n<ol>\n<li><strong>First visit after the first menses or 3–6 weeks</strong> after insertion.</li>\n<li>Then <strong>yearly</strong>, or at any time a problem arises (pain, fever, abnormal discharge, missed period, missing or long thread).</li>\n<li>Client taught to <strong>check threads after each menstruation</strong>.</li>\n</ol>\n<p><strong>(c) Public health impact on the local FP programme (2)</strong></p>\n<ol>\n<li><strong>Loss of confidence</strong> and rumours → fewer IUD acceptors; higher discontinuation; lower CPR.</li>\n<li><strong>Unintended pregnancies</strong> if expulsion is unnoticed.</li>\n<li>Extra cost and workload (ultrasound, X-ray, surgery for perforation).</li>\n<li>Shows need for <strong>better insertion skills, counselling and follow-up</strong> → opportunity to improve quality of services.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.482","n":482,"part":9,"topic":"Food & Nutrition","stars":3,"years":["19Nov","17M","16Nov"],"colleges":"ShSMC (1st Term B2)","asked":"define food","note":"","kind":"","sub":"","q":"<p>Classify food (according to predominant functions).</p>","a":"<p><strong>Classification of foods by predominant function (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Foods</th>\n<th>Main nutrients</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Energy-yielding foods</strong></td>\n<td>Cereals (rice, wheat), roots and tubers (potato), dried fruits, <strong>sugars and fats/oils</strong></td>\n<td>Carbohydrate, fat</td>\n</tr>\n<tr>\n<td><strong>2. Body-building foods</strong></td>\n<td><strong>Milk, meat, fish, poultry, eggs</strong>; <strong>pulses</strong>, groundnuts, oilseeds</td>\n<td>Protein</td>\n</tr>\n<tr>\n<td><strong>3. Protective foods</strong></td>\n<td><strong>Vegetables, fruits</strong> (green leafy, yellow-orange), milk</td>\n<td>Vitamins, minerals</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Other classifications</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Groups</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Origin</td>\n<td>Animal / plant foods</td>\n</tr>\n<tr>\n<td>Chemical composition</td>\n<td>Proteins, fats, carbohydrates, vitamins, minerals</td>\n</tr>\n<tr>\n<td>Nutritive value</td>\n<td>Cereals and millets; pulses; vegetables; nuts and oilseeds; fruits; animal foods; fats and oils; sugar and jaggery; condiments and spices; miscellaneous</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.483","n":483,"part":9,"topic":"Food & Nutrition","stars":3,"years":["26M","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Outline the dietary goals of a balanced diet / state the dietary goals recommended by WHO.</p>","a":"<p><strong>Dietary goals (WHO; Park)</strong></p>\n<ol>\n<li><strong>Energy balance</strong>: maintain healthy body weight (BMI 18.5–24.9); reduce intake if overweight; regular physical activity.</li>\n<li><strong>Total fat</strong>: 15–30% of total energy.</li>\n<li><strong>Saturated fat</strong> &lt;10% of energy; <strong>trans fat</strong> &lt;1%; replace with unsaturated oils.</li>\n<li><strong>Cholesterol</strong> &lt;300 mg/day.</li>\n<li><strong>Free sugars</strong> &lt;10% of energy (ideally &lt;5%).</li>\n<li><strong>Salt</strong> &lt;5 g/day (sodium &lt;2 g); use <strong>iodised</strong> salt.</li>\n<li><strong>Fruits and vegetables</strong> ≥400 g/day (5 portions).</li>\n<li><strong>Complex carbohydrates and dietary fibre</strong>: whole grains, pulses; fibre ≥25 g/day.</li>\n<li><strong>Protein</strong> 10–15% of energy; mix of plant and animal sources.</li>\n<li><strong>Avoid alcohol</strong> and tobacco.</li>\n</ol>\n<p><strong>Balanced diet</strong></p>\n<p>A diet containing all nutrients in adequate amounts and proper proportion to meet requirements, with a small margin for lean periods.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health); WHO, Healthy diet fact sheet.</p>"},{"id":"DU.484","n":484,"part":9,"topic":"Food & Nutrition","stars":3,"years":["25M","18Nov","17Nov","16Nov","13Ju"],"colleges":"DMC (1st Assess C3)","asked":"importance of dietary fibre","note":"","kind":"","sub":"","q":"<p>Mention the functions / role of dietary fibre in the body, health &amp; disease.</p>","a":"<p><strong>Dietary fibre</strong></p>\n<p>Non-digestible plant carbohydrates (cellulose, hemicellulose, pectin, gums, lignin); soluble and insoluble.</p>\n<p><strong>Functions / role in health and disease</strong></p>\n<ol>\n<li><strong>Adds bulk</strong> to stool; speeds transit → prevents <strong>constipation</strong>.</li>\n<li>Reduces risk of <strong>diverticular disease, haemorrhoids, appendicitis</strong>.</li>\n<li>Lower risk of <strong>colorectal cancer</strong> (dilutes and removes carcinogens; short-chain fatty acids).</li>\n<li><strong>Lowers blood cholesterol</strong> (soluble fibre binds bile acids) → less CHD.</li>\n<li><strong>Slows glucose absorption</strong> → better glycaemic control; less type 2 diabetes.</li>\n<li><strong>Satiety</strong> → weight control, prevents obesity.</li>\n<li><strong>Prebiotic</strong>: feeds healthy gut flora.</li>\n<li>May lower blood pressure.</li>\n</ol>\n<p><strong>Sources</strong>: whole grains, pulses, vegetables, fruits, nuts; recommended ≥25 g/day.</p>\n<p><strong>Excess</strong>: may reduce absorption of iron, zinc, calcium (phytates); flatulence.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.485","n":485,"part":9,"topic":"Food & Nutrition","stars":3,"years":["21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify protein with examples.</p>","a":"<p><strong>Classification of proteins</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Source</strong></td>\n<td>Animal / vegetable</td>\n<td>Egg, milk, meat, fish / pulses, cereals, nuts</td>\n</tr>\n<tr>\n<td><strong>Nutritive value</strong></td>\n<td><strong>Complete</strong> (first class: all essential amino acids)</td>\n<td>Egg, milk, meat, fish</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Partially complete</strong></td>\n<td>Cereal proteins (low lysine), pulse proteins (low methionine)</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Incomplete</strong></td>\n<td>Gelatin, zein (maize)</td>\n</tr>\n<tr>\n<td><strong>Chemical composition</strong></td>\n<td><strong>Simple</strong></td>\n<td>Albumins, globulins, glutelins, prolamines, histones, scleroproteins (keratin, collagen)</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Conjugated</strong></td>\n<td>Nucleoproteins, glycoproteins, lipoproteins, chromoproteins (haemoglobin), phosphoproteins (casein), metalloproteins</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Derived</strong></td>\n<td>Peptones, peptides (from protein breakdown)</td>\n</tr>\n<tr>\n<td><strong>Shape</strong></td>\n<td>Fibrous / globular</td>\n<td>Collagen, keratin / albumin, haemoglobin</td>\n</tr>\n<tr>\n<td><strong>Function</strong></td>\n<td>Structural, enzymes, hormones, transport, defence, contractile</td>\n<td>Collagen, amylase, insulin, haemoglobin, antibodies, actin</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.486","n":486,"part":9,"topic":"Food & Nutrition","stars":3,"years":["25M","18Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the functions / roles of protein in the body.</p>","a":"<p><strong>Functions of protein</strong></p>\n<ol>\n<li><strong>Body building</strong>: growth and formation of new tissues (childhood, pregnancy, lactation).</li>\n<li><strong>Repair and maintenance</strong> of tissues (wound healing, cell turnover).</li>\n<li><strong>Enzymes</strong> (digestive and metabolic) and <strong>hormones</strong> (insulin, growth hormone).</li>\n<li><strong>Antibodies</strong>: immunity against infection.</li>\n<li><strong>Transport</strong>: haemoglobin (oxygen), albumin, transferrin, lipoproteins.</li>\n<li><strong>Osmotic pressure</strong>: plasma albumin keeps fluid in vessels (low protein → oedema).</li>\n<li><strong>Acid–base buffering</strong>.</li>\n<li><strong>Energy</strong>: 4 kcal/g when energy intake is inadequate.</li>\n<li><strong>Blood clotting</strong> (fibrinogen, clotting factors).</li>\n<li><strong>Muscle contraction</strong> (actin, myosin).</li>\n<li>Precursors of neurotransmitters and other compounds (tryptophan → niacin, serotonin).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.487","n":487,"part":9,"topic":"Food & Nutrition","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention disease associated with high fat intake.</p>","a":"<p><strong>Diseases associated with high fat intake</strong></p>\n<ol>\n<li><strong>Obesity</strong>.</li>\n<li><strong>Coronary heart disease</strong> and atherosclerosis (saturated and trans fats, cholesterol).</li>\n<li><strong>Hypertension</strong>, <strong>stroke</strong>.</li>\n<li><strong>Type 2 diabetes</strong>, metabolic syndrome.</li>\n<li><strong>Cancers</strong>: colon, breast, prostate.</li>\n<li><strong>Gallstones</strong>.</li>\n<li><strong>Non-alcoholic fatty liver disease</strong>.</li>\n<li>Dyslipidaemia.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.488","n":488,"part":9,"topic":"Food & Nutrition","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write the important dietary sources of antioxidants with their daily requirements.</p>","a":"<p><strong>Dietary antioxidants: sources and daily requirements (approx., adult)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Antioxidant</th>\n<th>Sources</th>\n<th>Requirement</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Vitamin C</strong></td>\n<td>Amla, guava, citrus, lemon, green leafy vegetables, tomato</td>\n<td>~40 mg/day (more in pregnancy, lactation)</td>\n</tr>\n<tr>\n<td><strong>Vitamin E</strong></td>\n<td>Vegetable oils, nuts, seeds, whole grains, green leafy vegetables</td>\n<td>~8–10 mg/day</td>\n</tr>\n<tr>\n<td><strong>β-carotene / vitamin A</strong></td>\n<td>Carrot, pumpkin, mango, papaya, green leafy vegetables</td>\n<td>~600 µg retinol (or 4,800 µg β-carotene)/day</td>\n</tr>\n<tr>\n<td><strong>Selenium</strong></td>\n<td>Seafood, meat, cereals, nuts</td>\n<td>~40 µg/day</td>\n</tr>\n<tr>\n<td>Zinc, copper, manganese</td>\n<td>Meat, pulses, nuts, whole grains</td>\n<td>Zinc ~10–12 mg/day</td>\n</tr>\n<tr>\n<td>Polyphenols, flavonoids, lycopene</td>\n<td>Tea, fruits, tomato, onion</td>\n<td>No set requirement</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Role</strong>: neutralise free radicals → protect against CHD, cancers, cataract, ageing.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.489","n":489,"part":9,"topic":"Food & Nutrition","stars":1,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is reference protein?</p>","a":"<p><strong>Reference protein</strong></p>\n<p>A protein with an <strong>ideal pattern of essential amino acids</strong>, which is fully used by the body, taken as the <strong>standard</strong> to evaluate the quality of other proteins.</p>\n<ul>\n<li><strong>Egg protein</strong> (whole egg) is used as the reference protein (human milk protein also used for infants).</li>\n<li>Its biological value and net protein utilisation are taken as ~100.</li>\n<li><strong>Amino acid score</strong> of a food = (mg of the limiting amino acid per g of test protein ÷ mg of the same amino acid per g of reference protein) × 100.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.490","n":490,"part":9,"topic":"Food & Nutrition","stars":3,"years":["18M","16Nov","16Ju","14Ja"],"colleges":"DMC (1st Assess C3)","asked":"","note":"","kind":"","sub":"","q":"<p>State the supplementary actions of protein.</p>","a":"<p><strong>Supplementary action of proteins</strong></p>\n<p>When two proteins <strong>deficient in different essential amino acids</strong> are eaten <strong>together</strong>, each supplies the amino acid the other lacks, so the <strong>mixture has a higher biological value</strong> than either alone.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.491","n":491,"part":9,"topic":"Food & Nutrition","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the health problems associated with protein deficiency.</p>","a":"<p><strong>Health problems due to protein deficiency</strong></p>\n<ol>\n<li><strong>Protein-energy malnutrition</strong>: <strong>kwashiorkor</strong>, marasmus, marasmic kwashiorkor.</li>\n<li><strong>Growth retardation</strong>: stunting, underweight; delayed puberty.</li>\n<li><strong>Oedema</strong> (hypoalbuminaemia).</li>\n<li><strong>Fatty liver</strong>.</li>\n<li><strong>Anaemia</strong>.</li>\n<li><strong>Impaired immunity</strong> → frequent, severe infections (diarrhoea, pneumonia, TB, measles).</li>\n<li><strong>Muscle wasting</strong>, weakness; low work capacity.</li>\n<li><strong>Skin and hair changes</strong>: flaky-paint dermatosis, sparse, depigmented hair (flag sign).</li>\n<li><strong>Poor wound healing</strong>.</li>\n<li><strong>Impaired mental development</strong> and learning.</li>\n<li>In pregnancy: <strong>LBW</strong> babies; poor lactation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.492","n":492,"part":9,"topic":"Food & Nutrition","stars":3,"years":["23Nov","19M","16Ja","11Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can nutritional status of a rural community (rural women) be assessed?</p>","a":"<p><strong>Assessment of nutritional status (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Details (rural women)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Clinical examination</strong></td>\n<td>Signs of deficiency: pallor (anaemia), goitre, angular stomatitis, Bitot's spots, oedema, hair and skin changes</td>\n</tr>\n<tr>\n<td><strong>2. Anthropometry</strong></td>\n<td>Weight, height, <strong>BMI</strong> (&lt;18.5 = chronic energy deficiency; ≥25 overweight), <strong>MUAC</strong> (low MUAC in pregnant women indicates undernutrition), waist circumference</td>\n</tr>\n<tr>\n<td><strong>3. Biochemical / laboratory tests</strong></td>\n<td><strong>Haemoglobin</strong> (anaemia: &lt;12 g/dl non-pregnant, &lt;11 g/dl pregnant), serum ferritin, urinary iodine, serum retinol, stool for ova</td>\n</tr>\n<tr>\n<td><strong>4. Functional assessment</strong></td>\n<td>Work capacity, dark adaptation (night blindness)</td>\n</tr>\n<tr>\n<td><strong>5. Dietary assessment</strong></td>\n<td>24-hour recall, food frequency questionnaire, <strong>women's dietary diversity</strong> (minimum 5 of 10 food groups), household food consumption survey, food security scales</td>\n</tr>\n<tr>\n<td><strong>6. Vital and health statistics</strong></td>\n<td>LBW rate, maternal mortality, anaemia prevalence, IMR</td>\n</tr>\n<tr>\n<td><strong>7. Ecological factors</strong></td>\n<td>Food production and prices, income, cultural practices, sanitation, infections</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Practical community approach</strong></p>\n<p>Sample survey of households → anthropometry and Hb of women → dietary recall → identify vulnerable groups (pregnant, lactating, adolescent girls) → plan nutrition interventions.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.493","n":493,"part":9,"topic":"Food & Nutrition","stars":3,"years":["25M","19M","18M","16Ju","15Ja","14Ja","12Ja","09Ju","04Ja"],"colleges":"SSMC (1st Supp C5)","asked":"common nutritional diseases in Bangladesh","note":"","kind":"","sub":"","q":"<p>Enlist / classify the nutritional deficiency diseases and common nutritional health problems in Bangladesh (also: among under-5 children; nutritional problems of developing countries).</p>","a":"<p><strong>Classification of nutritional problems</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Disorders</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>A. Undernutrition: macronutrient</strong></td>\n<td>Protein-energy malnutrition (stunting, wasting, underweight, kwashiorkor, marasmus); LBW; chronic energy deficiency in women</td>\n</tr>\n<tr>\n<td><strong>B. Undernutrition: micronutrient</strong></td>\n<td><strong>Iron-deficiency anaemia</strong>; <strong>vitamin A deficiency</strong> (night blindness, xerophthalmia); <strong>iodine deficiency disorders</strong> (goitre, cretinism); zinc deficiency; vitamin D deficiency (rickets, osteomalacia); B-vitamin deficiencies (angular stomatitis, beriberi, pellagra); folate deficiency (neural tube defects); calcium deficiency</td>\n</tr>\n<tr>\n<td><strong>C. Overnutrition</strong></td>\n<td>Obesity, overweight; diet-related NCDs (diabetes, hypertension, CHD)</td>\n</tr>\n<tr>\n<td><strong>D. Toxic / food-related</strong></td>\n<td>Lathyrism, aflatoxicosis, food adulteration, fluorosis</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Common nutritional problems in Bangladesh</strong></p>\n<ol>\n<li><strong>Stunting</strong> (23.6% of under-5s, 2022), <strong>wasting</strong>, <strong>underweight</strong>.</li>\n<li><strong>Low birth weight</strong>.</li>\n<li><strong>Anaemia</strong> in children, adolescent girls and women.</li>\n<li><strong>Subclinical vitamin A deficiency</strong>; <strong>iodine deficiency</strong> (improved by iodised salt).</li>\n<li><strong>Zinc deficiency</strong>; vitamin D deficiency.</li>\n<li>Chronic energy deficiency in women.</li>\n<li><strong>Rising overweight and obesity</strong> in urban areas → <strong>double burden of malnutrition</strong>.</li>\n</ol>\n<p><strong>Among under-5 children</strong>: stunting, wasting, underweight, anaemia, vitamin A and zinc deficiency.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health); Our World in Data, https://ourworldindata.org/profile/health/bangladesh</p>"},{"id":"DU.494","n":494,"part":9,"topic":"Food & Nutrition","stars":0,"years":[],"colleges":"SSMC (1st Supp C5)","asked":"","note":"","kind":"","sub":"","q":"<p>How can you improve the nutritional status of the community people?</p>","a":"<p><strong>Improving nutritional status of the community</strong></p>\n<ol>\n<li><strong>Nutrition education</strong>: balanced diet, local foods, hygiene.</li>\n<li><strong>Breastfeeding and IYCF</strong> promotion.</li>\n<li><strong>Supplementation</strong>: vitamin A, iron-folic acid, calcium, zinc (diarrhoea).</li>\n<li><strong>Fortification</strong>: iodised salt, vitamin A-fortified edible oil, fortified rice and flour.</li>\n<li><strong>Food security</strong>: homestead gardening, poultry, fish ponds, agricultural diversification.</li>\n<li><strong>Social safety nets</strong> and school feeding.</li>\n<li><strong>WASH</strong>, deworming, immunisation, treatment of infections.</li>\n<li><strong>Growth monitoring</strong>; community management of acute malnutrition.</li>\n<li><strong>Women's empowerment</strong>, education; family planning.</li>\n<li><strong>Food safety</strong> and regulation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.495","n":495,"part":9,"topic":"Food & Nutrition","stars":0,"years":[],"colleges":"MuMC (1st Final B1, 1st Supp B1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention two diseases each due to excess and deficiencies of nutrients.</p>","a":"<p><strong>Diseases due to deficiency and excess of nutrients</strong></p>\n<table>\n<thead>\n<tr>\n<th>Nutrient</th>\n<th>Deficiency</th>\n<th>Excess</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Energy / protein</td>\n<td>Kwashiorkor, marasmus</td>\n<td>Obesity</td>\n</tr>\n<tr>\n<td>Vitamin A</td>\n<td>Night blindness, xerophthalmia</td>\n<td>Hypervitaminosis A (raised ICP, liver damage, teratogenic)</td>\n</tr>\n<tr>\n<td>Vitamin D</td>\n<td>Rickets, osteomalacia</td>\n<td>Hypercalcaemia, kidney stones</td>\n</tr>\n<tr>\n<td>Iodine</td>\n<td>Goitre, cretinism</td>\n<td>Iodine-induced hyperthyroidism</td>\n</tr>\n<tr>\n<td>Fluoride</td>\n<td>Dental caries</td>\n<td><strong>Fluorosis</strong> (dental, skeletal)</td>\n</tr>\n<tr>\n<td>Iron</td>\n<td>Anaemia</td>\n<td>Haemosiderosis</td>\n</tr>\n<tr>\n<td>Sodium</td>\n<td>Hyponatraemia</td>\n<td>Hypertension</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.496","n":496,"part":9,"topic":"Food & Nutrition","stars":2,"years":[],"colleges":"SSMC (1st Supp C4); MMC (1st Supp D5)","asked":"","note":"","kind":"","sub":"","q":"<p>What is food fortification? Give examples.</p>","a":"<p><strong>Food fortification</strong></p>\n<p>The <strong>addition of one or more essential nutrients to a food</strong>, whether or not normally contained in it, to <strong>prevent or correct a demonstrated deficiency</strong> in the population or specific groups (WHO/FAO).</p>\n<p><strong>Examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Food vehicle</th>\n<th>Nutrient</th>\n<th>Target</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Salt</strong></td>\n<td>Iodine (iodised salt); iron + iodine (double-fortified salt)</td>\n<td>IDD, anaemia</td>\n</tr>\n<tr>\n<td><strong>Edible oil</strong></td>\n<td>Vitamin A (mandatory in Bangladesh)</td>\n<td>Vitamin A deficiency</td>\n</tr>\n<tr>\n<td>Wheat flour, rice</td>\n<td>Iron, folic acid, zinc, vitamins</td>\n<td>Anaemia, neural tube defects</td>\n</tr>\n<tr>\n<td>Milk</td>\n<td>Vitamins A and D</td>\n<td>Rickets, VAD</td>\n</tr>\n<tr>\n<td>Micronutrient powders</td>\n<td>Multiple micronutrients (home fortification)</td>\n<td>Child anaemia</td>\n</tr>\n<tr>\n<td><strong>Biofortification</strong></td>\n<td>Zinc-rich rice, vitamin A-rich crops (bred into plants)</td>\n<td>Zinc, VAD</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.497","n":497,"part":9,"topic":"Food & Nutrition","stars":0,"years":[],"colleges":"MMC (1st Supp D5)","asked":"","note":"","kind":"","sub":"","q":"<p>Write notes on food additives with at least three examples.</p>","a":"<p><strong>Food additives</strong></p>\n<p>Non-nutritive substances <strong>intentionally added</strong> to food in small amounts to improve its <strong>appearance, flavour, texture or keeping quality</strong>.</p>\n<p><strong>Examples</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Preservatives</strong></td>\n<td>Sodium benzoate, sorbic acid, sulphites, nitrites; salt, sugar, vinegar</td>\n</tr>\n<tr>\n<td><strong>Colours</strong></td>\n<td>Natural: turmeric, saffron; synthetic permitted: tartrazine, sunset yellow</td>\n</tr>\n<tr>\n<td><strong>Flavouring agents</strong></td>\n<td>Monosodium glutamate (MSG), vanillin</td>\n</tr>\n<tr>\n<td><strong>Antioxidants</strong></td>\n<td>BHA, BHT, vitamin E (prevent rancidity)</td>\n</tr>\n<tr>\n<td>Emulsifiers, stabilisers, thickeners</td>\n<td>Lecithin, gums, pectin, starch</td>\n</tr>\n<tr>\n<td>Sweeteners</td>\n<td>Saccharin, aspartame</td>\n</tr>\n<tr>\n<td>Acidulants</td>\n<td>Citric acid</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Hazards</strong>: allergy, hyperactivity, possible carcinogenicity when misused; illegal agents (formalin, carbide, textile dyes) are <strong>adulterants</strong>, not additives.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.498","n":498,"part":9,"topic":"Food & Nutrition","stars":0,"years":[],"colleges":"SSMC (1st Supp C4)","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Write down the difference between trace elements and minerals.</p>","a":"<p><strong>Major minerals vs trace elements</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Major (macro) minerals</th>\n<th>Trace elements</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Daily need</td>\n<td><strong>&gt;100 mg/day</strong></td>\n<td><strong>&lt;100 mg/day</strong> (often micrograms)</td>\n</tr>\n<tr>\n<td>Amount in body</td>\n<td>Large</td>\n<td>Very small</td>\n</tr>\n<tr>\n<td>Examples</td>\n<td>Calcium, phosphorus, magnesium, sodium, potassium, chloride, sulphur</td>\n<td>Iron, iodine, zinc, copper, fluoride, selenium, manganese, chromium, cobalt, molybdenum</td>\n</tr>\n<tr>\n<td>Main roles</td>\n<td>Bone structure, fluid balance, nerve and muscle function</td>\n<td>Enzyme cofactors, hormones (iodine), haemoglobin (iron)</td>\n</tr>\n<tr>\n<td>Deficiency examples</td>\n<td>Rickets/osteoporosis (Ca), hypokalaemia</td>\n<td>Anaemia (Fe), goitre (I), growth failure (Zn)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.499","n":499,"part":9,"topic":"Food & Nutrition","stars":0,"years":["25Nov","05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Vitamins","q":"<p>Classify vitamins / classify water soluble vitamins.</p>","a":"<p><strong>Classification of vitamins</strong></p>\n<p><strong>A. Fat-soluble</strong>: <strong>A</strong> (retinol), <strong>D</strong> (calciferol), <strong>E</strong> (tocopherol), <strong>K</strong> (phylloquinone).</p>\n<p><strong>B. Water-soluble</strong></p>\n<table>\n<thead>\n<tr>\n<th>Vitamin</th>\n<th>Name</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>B₁</td>\n<td>Thiamine</td>\n</tr>\n<tr>\n<td>B₂</td>\n<td>Riboflavin</td>\n</tr>\n<tr>\n<td>B₃</td>\n<td>Niacin (nicotinic acid)</td>\n</tr>\n<tr>\n<td>B₅</td>\n<td>Pantothenic acid</td>\n</tr>\n<tr>\n<td>B₆</td>\n<td>Pyridoxine</td>\n</tr>\n<tr>\n<td>B₇</td>\n<td>Biotin</td>\n</tr>\n<tr>\n<td>B₉</td>\n<td>Folic acid (folate)</td>\n</tr>\n<tr>\n<td>B₁₂</td>\n<td>Cobalamin</td>\n</tr>\n<tr>\n<td>C</td>\n<td>Ascorbic acid</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Fat- vs water-soluble</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Fat-soluble</th>\n<th>Water-soluble</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Absorption</td>\n<td>With dietary fat, bile</td>\n<td>Directly</td>\n</tr>\n<tr>\n<td>Storage</td>\n<td>Stored (liver, fat)</td>\n<td>Little storage (except B₁₂)</td>\n</tr>\n<tr>\n<td>Excretion</td>\n<td>Not easily excreted</td>\n<td>In urine</td>\n</tr>\n<tr>\n<td>Toxicity</td>\n<td>Possible (A, D)</td>\n<td>Rare</td>\n</tr>\n<tr>\n<td>Deficiency</td>\n<td>Develops slowly</td>\n<td>Develops quickly</td>\n</tr>\n<tr>\n<td>Daily intake</td>\n<td>Not essential daily</td>\n<td>Needed regularly</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.500","n":500,"part":9,"topic":"Food & Nutrition","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Vitamins","q":"<p>What are the vitamin deficiency disorders?</p>","a":"<p><strong>Vitamin deficiency disorders</strong></p>\n<table>\n<thead>\n<tr>\n<th>Vitamin</th>\n<th>Deficiency disorders</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>A</strong></td>\n<td>Night blindness, conjunctival xerosis, Bitot's spots, keratomalacia, follicular hyperkeratosis, more infections and child deaths</td>\n</tr>\n<tr>\n<td><strong>D</strong></td>\n<td><strong>Rickets</strong> (children), <strong>osteomalacia</strong> (adults), hypocalcaemic tetany</td>\n</tr>\n<tr>\n<td><strong>E</strong></td>\n<td>Haemolytic anaemia in preterm babies, neuropathy</td>\n</tr>\n<tr>\n<td><strong>K</strong></td>\n<td><strong>Haemorrhagic disease of the newborn</strong>, bleeding</td>\n</tr>\n<tr>\n<td><strong>B₁ (thiamine)</strong></td>\n<td><strong>Beriberi</strong> (dry, wet, infantile), Wernicke–Korsakoff syndrome</td>\n</tr>\n<tr>\n<td><strong>B₂ (riboflavin)</strong></td>\n<td><strong>Angular stomatitis</strong>, cheilosis, glossitis, corneal vascularisation</td>\n</tr>\n<tr>\n<td><strong>Niacin</strong></td>\n<td><strong>Pellagra</strong>: dermatitis, diarrhoea, dementia (death)</td>\n</tr>\n<tr>\n<td><strong>B₆</strong></td>\n<td>Peripheral neuropathy, infant convulsions, anaemia</td>\n</tr>\n<tr>\n<td><strong>Folate</strong></td>\n<td><strong>Megaloblastic anaemia</strong>; <strong>neural tube defects</strong> in the fetus</td>\n</tr>\n<tr>\n<td><strong>B₁₂</strong></td>\n<td>Megaloblastic (pernicious) anaemia, subacute combined degeneration of the cord</td>\n</tr>\n<tr>\n<td><strong>C</strong></td>\n<td><strong>Scurvy</strong>: bleeding gums, perifollicular haemorrhages, poor wound healing</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.501","n":501,"part":9,"topic":"Food & Nutrition","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Vitamin A","q":"<p>What are the sources of vitamin A?</p>","a":"<p><strong>Sources of vitamin A</strong></p>\n<p><strong>A. Preformed vitamin A (retinol): animal sources</strong></p>\n<p>Liver, <strong>fish liver oils</strong> (cod, shark), egg yolk, milk, butter, ghee, cheese, <strong>small fish eaten whole</strong> (mola), <strong>fortified edible oil</strong>.</p>\n<p><strong>B. Provitamin A (β-carotene): plant sources</strong></p>\n<ol>\n<li><strong>Dark green leafy vegetables</strong>: spinach, red amaranth (lal shak), kalmi shak, drumstick leaves, pui shak.</li>\n<li><strong>Yellow-orange vegetables</strong>: carrot, pumpkin, sweet potato.</li>\n<li><strong>Yellow-orange fruits</strong>: ripe <strong>mango</strong>, papaya, jackfruit.</li>\n<li>Red palm oil.</li>\n</ol>\n<p><strong>C. Breast milk</strong> (especially colostrum) for infants.</p>\n<p><strong>Requirement</strong>: about 600 µg retinol/day for adults (higher in lactation).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.502","n":502,"part":9,"topic":"Food & Nutrition","stars":3,"years":["21M","17M"],"colleges":"","asked":"","note":"","kind":"","sub":"Vitamin A","q":"<p>Mention the manifestations of vitamin A deficiency.</p>","a":"<p><strong>Manifestations of vitamin A deficiency</strong></p>\n<p><strong>A. Ocular (xerophthalmia; WHO classification)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Code</th>\n<th>Sign</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>XN</strong></td>\n<td><strong>Night blindness</strong> (earliest symptom)</td>\n</tr>\n<tr>\n<td><strong>X1A</strong></td>\n<td>Conjunctival xerosis</td>\n</tr>\n<tr>\n<td><strong>X1B</strong></td>\n<td><strong>Bitot's spots</strong></td>\n</tr>\n<tr>\n<td><strong>X2</strong></td>\n<td>Corneal xerosis</td>\n</tr>\n<tr>\n<td><strong>X3A</strong></td>\n<td>Corneal ulceration / keratomalacia &lt;⅓ of cornea</td>\n</tr>\n<tr>\n<td><strong>X3B</strong></td>\n<td>Corneal ulceration / keratomalacia ≥⅓ of cornea</td>\n</tr>\n<tr>\n<td><strong>XS</strong></td>\n<td>Corneal scar</td>\n</tr>\n<tr>\n<td><strong>XF</strong></td>\n<td>Xerophthalmic fundus</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Extra-ocular</strong></p>\n<ol>\n<li><strong>Increased susceptibility to infections</strong>: diarrhoea, ARI, severe measles.</li>\n<li><strong>Increased child mortality</strong>.</li>\n<li><strong>Follicular hyperkeratosis</strong> (dry, rough &quot;toad skin&quot;).</li>\n<li>Growth retardation; anaemia.</li>\n<li>Keratinisation of respiratory, urinary and gut epithelium.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.503","n":503,"part":9,"topic":"Food & Nutrition","stars":3,"years":["16M","12Ju","10Ju","05M","04S"],"colleges":"MMC (1st Supp D4); MuMC (1st Final B1, 1st Supp B1)","asked":"","note":"U1B1/V1B1 also ask for the preventable stage","kind":"","sub":"Vitamin A","q":"<p>Write down / discuss the stages of xerophthalmia.</p>","a":"<p><strong>Stages of xerophthalmia (WHO, 1982)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Code</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>XN: Night blindness</strong></td>\n<td>Cannot see in dim light; earliest, reversible</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>X1A: Conjunctival xerosis</strong></td>\n<td>Dry, wrinkled, lustreless bulbar conjunctiva</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>X1B: Bitot's spots</strong></td>\n<td>Triangular, foamy, silvery-white spots on temporal conjunctiva</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>X2: Corneal xerosis</strong></td>\n<td>Dull, hazy, dry cornea</td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>X3A: Corneal ulceration / keratomalacia</strong> (&lt;⅓ of corneal surface)</td>\n<td>Ulcer, melting of cornea</td>\n</tr>\n<tr>\n<td>6</td>\n<td><strong>X3B: Corneal ulceration / keratomalacia</strong> (≥⅓ of corneal surface)</td>\n<td>Extensive melting; perforation → blindness</td>\n</tr>\n<tr>\n<td>Sequelae</td>\n<td><strong>XS: Corneal scar</strong></td>\n<td>Permanent opacity</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>XF: Xerophthalmic fundus</strong></td>\n<td>White retinal spots</td>\n</tr>\n</tbody>\n</table>\n<p>XN → X1 reversible; X2–X3 are emergencies (blinding); X3 lesions cause permanent damage.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.504","n":504,"part":9,"topic":"Food & Nutrition","stars":3,"years":["24Nov","16Ju","16M","14Ju","12Ju"],"colleges":"MMC (1st Supp D4)","asked":"","note":"","kind":"","sub":"Vitamin A","q":"<p>How can you prevent and control nutritional blindness / night blindness (in a community; in Bangladesh)?</p>","a":"<p><strong>Prevention and control of nutritional blindness (vitamin A deficiency)</strong></p>\n<p><strong>A. Short-term: supplementation</strong></p>\n<p><strong>High-dose vitamin A capsules</strong> (Bangladesh: national vitamin A campaigns, twice a year):</p>\n<table>\n<thead>\n<tr>\n<th>Age</th>\n<th>Dose</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>6–11 months</td>\n<td>100,000 IU once</td>\n</tr>\n<tr>\n<td>12–59 months</td>\n<td>200,000 IU every 6 months</td>\n</tr>\n</tbody>\n</table>\n<p>Also to sick children: measles, persistent diarrhoea, severe malnutrition (as treatment).</p>\n<p><strong>B. Medium-term: fortification</strong></p>\n<p><strong>Vitamin A-fortified edible oil</strong> (mandatory in Bangladesh); other fortified foods.</p>\n<p><strong>C. Long-term: dietary approach</strong></p>\n<ol>\n<li><strong>Dietary diversification</strong>: dark green leafy vegetables, yellow fruits, small fish, eggs.</li>\n<li><strong>Homestead gardening</strong>; nutrition education.</li>\n<li><strong>Breastfeeding</strong> (give colostrum).</li>\n</ol>\n<p><strong>D. Public health measures</strong></p>\n<ol>\n<li><strong>Measles immunisation</strong>.</li>\n<li>Treatment and prevention of <strong>diarrhoea, ARI, worms</strong>.</li>\n<li>Treatment of severe malnutrition.</li>\n<li>Early detection (night blindness, Bitot's spots) and treatment.</li>\n</ol>\n<p><strong>E. Surveillance</strong></p>\n<p>Monitor coverage of capsules, serum retinol surveys.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.505","n":505,"part":9,"topic":"Food & Nutrition","stars":3,"years":["20Nov"],"colleges":"MMC (1st Supp D4)","asked":"how will you treat a 4-year-old boy with xerophthalmia?","note":"","kind":"","sub":"Vitamin A","q":"<p>How will you manage a boy of 5 years old with night blindness?</p>","a":"<p><strong>Management of a 5-year-old boy with night blindness</strong></p>\n<p><strong>1. Assessment</strong></p>\n<p>History (diet, recent measles, diarrhoea, worms); examine eyes for <strong>Bitot's spots, corneal xerosis, ulcer</strong>; check nutritional status (weight, height, MUAC), anaemia, infections.</p>\n<p><strong>2. Treatment with vitamin A (WHO schedule, age &gt;12 months)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Day</th>\n<th>Dose</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Day 1</strong></td>\n<td>200,000 IU orally</td>\n</tr>\n<tr>\n<td><strong>Day 2</strong></td>\n<td>200,000 IU</td>\n</tr>\n<tr>\n<td><strong>Day 14</strong> (or at discharge)</td>\n<td>200,000 IU</td>\n</tr>\n</tbody>\n</table>\n<p>(If corneal lesions: same schedule urgently; refer to eye specialist.)</p>\n<p><strong>3. Eye care</strong> (if corneal involvement)</p>\n<p>Antibiotic eye ointment; eye pad / protection; avoid pressure on the eye.</p>\n<p><strong>4. Treat associated conditions</strong></p>\n<p>Diarrhoea (ORS, zinc), ARI, measles; <strong>deworming</strong> (albendazole 400 mg); anaemia; malnutrition.</p>\n<p><strong>5. Dietary advice</strong></p>\n<p>Daily green leafy vegetables, yellow-orange fruits (mango, papaya), carrot, pumpkin, small fish, eggs, milk; use oil in cooking.</p>\n<p><strong>6. Follow-up</strong></p>\n<p>Check improvement of night vision (in a few days); ensure regular <strong>6-monthly vitamin A capsules</strong> until 5 years; check siblings; health education of mother.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.506","n":506,"part":9,"topic":"Food & Nutrition","stars":3,"years":["17M"],"colleges":"","asked":"","note":"","kind":"","sub":"Vitamin D","q":"<p>Enlist the functions of vitamin D.</p>","a":"<p><strong>Functions of vitamin D</strong></p>\n<ol>\n<li><strong>Promotes absorption of calcium and phosphorus</strong> from the intestine.</li>\n<li><strong>Mineralisation of bones and teeth</strong>; bone growth and remodelling.</li>\n<li><strong>Maintains serum calcium and phosphate</strong> (with parathyroid hormone): renal reabsorption of calcium, mobilisation from bone.</li>\n<li>Normal <strong>muscle function</strong>; prevents tetany.</li>\n<li><strong>Immune modulation</strong>: innate defence (e.g., against TB).</li>\n<li>Regulates <strong>cell growth and differentiation</strong>.</li>\n<li>Possible role in insulin secretion and cardiovascular health.</li>\n</ol>\n<p><strong>Sources</strong>: sunlight on skin (main), fish liver oils, oily fish, egg yolk, fortified foods.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.507","n":507,"part":9,"topic":"Food & Nutrition","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"Vitamin D","q":"<p>Write the manifestations of vitamin D deficiency.</p>","a":"<p><strong>Manifestations of vitamin D deficiency</strong></p>\n<p><strong>A. Rickets (children)</strong></p>\n<ol>\n<li><strong>Skull</strong>: craniotabes, frontal and parietal bossing, delayed closure of anterior fontanelle.</li>\n<li><strong>Chest</strong>: <strong>rickety rosary</strong> (beading of costochondral junctions), <strong>Harrison's sulcus</strong>, pigeon chest.</li>\n<li><strong>Limbs</strong>: widening of wrists and ankles, <strong>bow legs</strong> (genu varum) or <strong>knock knees</strong> (genu valgum).</li>\n<li>Delayed dentition, enamel defects.</li>\n<li>Delayed motor milestones, hypotonia, <strong>pot belly</strong>.</li>\n<li>Growth retardation; frequent respiratory infections.</li>\n<li>X-ray: cupping, fraying of metaphyses.</li>\n</ol>\n<p><strong>B. Osteomalacia (adults, especially women)</strong></p>\n<p>Bone pain and tenderness, <strong>proximal muscle weakness</strong> (waddling gait), pseudo-fractures, fractures; pelvic deformity → obstructed labour.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.508","n":508,"part":9,"topic":"Food & Nutrition","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Thiamine Deficiency","q":"<p>State thiamine deficiency disorders.</p>","a":"<p><strong>Thiamine (vitamin B₁) deficiency disorders</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disorder</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Dry beriberi</strong></td>\n<td>Peripheral neuritis: numbness, tingling, muscle wasting, foot drop, difficulty walking</td>\n</tr>\n<tr>\n<td><strong>Wet beriberi</strong></td>\n<td>Oedema, palpitations, high-output <strong>heart failure</strong></td>\n</tr>\n<tr>\n<td><strong>Infantile beriberi</strong></td>\n<td>Breastfed infants (2–4 months) of thiamine-deficient mothers: aphonia, vomiting, cyanosis, heart failure, sudden death</td>\n</tr>\n<tr>\n<td><strong>Wernicke's encephalopathy</strong></td>\n<td>Ophthalmoplegia, ataxia, confusion (alcoholics)</td>\n</tr>\n<tr>\n<td><strong>Korsakoff's psychosis</strong></td>\n<td>Memory loss, confabulation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Causes</strong>: diet of highly polished rice, excessive washing of rice, discarding cooking water, alcoholism.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.509","n":509,"part":9,"topic":"Food & Nutrition","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Discuss the role of major minerals for growth and regulation of body function.</p>","a":"<p><strong>Role of major minerals</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mineral</th>\n<th>Roles</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Calcium</strong></td>\n<td>Bones and teeth; muscle contraction; nerve conduction; blood clotting; heart rhythm; enzyme activation</td>\n</tr>\n<tr>\n<td><strong>Phosphorus</strong></td>\n<td>Bones and teeth; ATP (energy); nucleic acids; phospholipids; buffer</td>\n</tr>\n<tr>\n<td><strong>Magnesium</strong></td>\n<td>Cofactor for many enzymes; bone; nerve and muscle function</td>\n</tr>\n<tr>\n<td><strong>Sodium</strong></td>\n<td>Extracellular fluid volume and osmotic pressure; nerve impulses; acid–base balance</td>\n</tr>\n<tr>\n<td><strong>Potassium</strong></td>\n<td>Intracellular fluid; heart rhythm; muscle contraction; nerve function</td>\n</tr>\n<tr>\n<td><strong>Chloride</strong></td>\n<td>Gastric HCl; fluid and acid–base balance</td>\n</tr>\n<tr>\n<td><strong>Sulphur</strong></td>\n<td>Part of amino acids (methionine, cysteine), keratin, insulin</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Growth</strong>: calcium, phosphorus and magnesium build the skeleton; with protein they support normal growth in children.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.510","n":510,"part":9,"topic":"Food & Nutrition","stars":0,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Discuss possible interventions of preventing nutritional anemia of teen aged working women.</p>","a":"<p><strong>Preventing nutritional anaemia among teenage working women</strong></p>\n<ol>\n<li><strong>Weekly iron-folic acid supplementation</strong> (e.g., 60 mg iron + 2.8 mg folic acid weekly).</li>\n<li><strong>Dietary improvement</strong>: iron-rich foods (meat, fish, liver, eggs, green leafy vegetables, pulses); vitamin C with meals; avoid tea with meals.</li>\n<li><strong>Fortified foods</strong>: iron-fortified flour, rice; workplace canteen meals.</li>\n<li><strong>Deworming</strong> every 6 months.</li>\n<li><strong>Treat infections</strong> (malaria, TB) and heavy menstrual bleeding.</li>\n<li><strong>Delay marriage and first pregnancy</strong>; birth spacing.</li>\n<li><strong>Screening</strong> (Hb) and treatment of anaemia at the workplace.</li>\n<li><strong>WASH</strong>: safe water, latrines, menstrual hygiene facilities at factories.</li>\n<li><strong>Nutrition education</strong>; adequate wages and rest.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.511","n":511,"part":9,"topic":"Food & Nutrition","stars":2,"years":["14Ju","12Ju","08Ju","04M"],"colleges":"DMC (1st Assess B3)","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Enlist iodine deficiency disorder (IDD) spectrum / enumerate the manifestations of IDD.</p>","a":"<p><strong>Spectrum of iodine deficiency disorders (IDD)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage of life</th>\n<th>Manifestations</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Fetus</strong></td>\n<td>Abortions, stillbirths, congenital anomalies; <strong>neurological cretinism</strong> (mental deficiency, deaf-mutism, spastic diplegia, squint); <strong>myxoedematous cretinism</strong> (dwarfism, mental deficiency); psychomotor defects; increased perinatal and infant mortality</td>\n</tr>\n<tr>\n<td><strong>Neonate</strong></td>\n<td>Neonatal goitre; neonatal hypothyroidism</td>\n</tr>\n<tr>\n<td><strong>Child and adolescent</strong></td>\n<td><strong>Goitre</strong>; juvenile hypothyroidism; impaired mental function (low IQ, poor school performance); retarded physical development</td>\n</tr>\n<tr>\n<td><strong>Adult</strong></td>\n<td>Goitre with complications; hypothyroidism; impaired mental function; iodine-induced hyperthyroidism</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.512","n":512,"part":9,"topic":"Food & Nutrition","stars":0,"years":["06M"],"colleges":"","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Discuss the detrimental effects of nutritional anemia.</p>","a":"<p><strong>Detrimental effects of nutritional anaemia</strong></p>\n<ol>\n<li><strong>Fatigue, weakness</strong>, breathlessness; reduced <strong>work capacity</strong> and productivity.</li>\n<li><strong>Children</strong>: impaired <strong>cognitive development</strong>, poor school performance, delayed growth.</li>\n<li><strong>Reduced immunity</strong> → more infections.</li>\n<li><strong>Pregnancy</strong>: higher <strong>maternal mortality</strong> (poor tolerance of PPH, heart failure), <strong>LBW</strong>, preterm birth, perinatal death.</li>\n<li><strong>Heart failure</strong> in severe anaemia.</li>\n<li>Poor quality of life; pica.</li>\n<li><strong>Economic loss</strong> to families and nation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.513","n":513,"part":9,"topic":"Food & Nutrition","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>How can you prevent IDD?</p>","a":"<p><strong>Prevention of IDD (Park)</strong></p>\n<ol>\n<li><strong>Iodised salt</strong>: universal salt iodisation (Bangladesh law since 1989); adequate iodine at household level.</li>\n<li><strong>Iodised oil</strong> (oral capsules or injections) for high-risk groups in severely deficient areas.</li>\n<li><strong>Monitoring and surveillance</strong>: salt iodine at production, retail and household; <strong>urinary iodine</strong> surveys; goitre surveys; neonatal TSH.</li>\n<li><strong>Manpower training</strong>.</li>\n<li><strong>Mass communication</strong>: use only iodised salt; store salt covered, add after cooking.</li>\n<li>Legislation and enforcement (ban non-iodised edible salt).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.514","n":514,"part":9,"topic":"Food & Nutrition","stars":3,"years":["25Nov","17Nov","14Ja","12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Identify five uses / functions of zinc.</p>","a":"<p><strong>Five uses / functions of zinc</strong></p>\n<ol>\n<li><strong>Growth and development</strong>: cell division, protein and DNA synthesis → prevents stunting.</li>\n<li><strong>Immunity</strong>: T-cell function, gut barrier → fewer infections.</li>\n<li><strong>Treatment of diarrhoea</strong>: reduces duration, severity and recurrence (10 mg/day for &lt;6 months, 20 mg/day for ≥6 months, for 10–14 days with ORS).</li>\n<li><strong>Wound healing</strong> and skin health (acrodermatitis enteropathica).</li>\n<li><strong>Enzyme cofactor</strong> (&gt;300 enzymes: carbonic anhydrase, alcohol dehydrogenase, superoxide dismutase).</li>\n<li>Taste and smell; appetite.</li>\n<li><strong>Reproduction</strong>: spermatogenesis, fetal growth.</li>\n</ol>\n<p><strong>Sources</strong>: meat, fish, eggs, pulses, nuts, whole grains.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.515","n":515,"part":9,"topic":"Food & Nutrition","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Mineral Deficiency (Iron + Iodine + Zinc)","q":"<p>Enlist the factors affecting energy requirement.</p>","a":"<p><strong>Factors affecting energy requirement</strong></p>\n<ol>\n<li><strong>Age</strong>: higher per kg in infants and children (growth).</li>\n<li><strong>Sex</strong>: men need more than women (more lean mass).</li>\n<li><strong>Body size and composition</strong>: weight, lean body mass.</li>\n<li><strong>Physical activity</strong>: most variable factor (sedentary, moderate, heavy work).</li>\n<li><strong>Basal metabolic rate</strong>.</li>\n<li><strong>Physiological state</strong>: pregnancy, lactation, growth spurts.</li>\n<li><strong>Climate</strong>: more in cold climate.</li>\n<li><strong>Illness</strong>: fever, infection, injury, burns increase needs.</li>\n<li>Thermic effect of food.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.516","n":516,"part":9,"topic":"Food & Nutrition","stars":0,"years":["10Ja"],"colleges":"ShSMC (1st Term A5)","asked":"","note":"Part d of the 2-year-old child case","kind":"","sub":"Malnutrition & PEM","q":"<p>Malnutrition predisposes to infection and infection to malnutrition – justify the statement.</p>","a":"<p><strong>Malnutrition ⇄ infection: a vicious cycle</strong></p>\n<p><strong>Malnutrition predisposes to infection</strong></p>\n<ol>\n<li>Weak <strong>cell-mediated immunity</strong>, low antibodies, complement and phagocyte function.</li>\n<li>Damaged <strong>skin and mucosal barriers</strong> (vitamin A, zinc deficiency).</li>\n<li>Infections become <strong>more frequent, severe and prolonged</strong> (measles, diarrhoea, TB, pneumonia).</li>\n</ol>\n<p><strong>Infection worsens malnutrition</strong></p>\n<ol>\n<li><strong>Loss of appetite</strong>; food withheld during illness (wrong custom).</li>\n<li><strong>Malabsorption</strong>, diarrhoea, vomiting → nutrient loss.</li>\n<li><strong>Increased metabolic needs</strong> (fever).</li>\n<li><strong>Catabolism</strong>: protein and vitamin A loss (measles precipitates xerophthalmia and kwashiorkor).</li>\n<li>Worms → blood loss and anaemia.</li>\n</ol>\n<p><strong>Cycle</strong></p>\n<p>Malnutrition → lowered immunity → infection → anorexia, malabsorption, losses → worse malnutrition → more infection → death</p>\n<p><strong>Implication</strong></p>\n<p>Break the cycle with <strong>feeding during and after illness</strong>, ORS/zinc, vitamin A, immunisation, deworming, WASH, growth monitoring.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.517","n":517,"part":9,"topic":"Food & Nutrition","stars":3,"years":["17M","17Ja","16Ja","15Ja","13Ja","11Ja"],"colleges":"DMC (1st Assess B3)","asked":"","note":"","kind":"","sub":"Malnutrition & PEM","q":"<p>What is PEM? How can it be prevented (in our country)? Discuss measures for prevention and control of PEM.</p>","a":"<p><strong>Protein-energy malnutrition (PEM)</strong></p>\n<p>A range of conditions from <strong>inadequate intake or utilisation of protein and energy</strong>, often with infections; mainly in children under 5. Includes <strong>stunting, wasting, underweight, kwashiorkor, marasmus, marasmic kwashiorkor</strong>.</p>\n<p><strong>Prevention and control (Park, by levels)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Health promotion</strong></td>\n<td>Nutrition of pregnant and lactating women; <strong>breastfeeding</strong>; low-cost <strong>complementary foods</strong>; nutrition education; <strong>family planning and spacing</strong>; improving family environment (income, WASH)</td>\n</tr>\n<tr>\n<td><strong>Specific protection</strong></td>\n<td>Diet adequate in protein and energy; <strong>immunisation</strong>; <strong>fortification</strong>; vitamin A</td>\n</tr>\n<tr>\n<td><strong>Early diagnosis and treatment</strong></td>\n<td><strong>Growth monitoring</strong>; early detection of growth faltering; treatment of diarrhoea (ORS, zinc), ARI; <strong>deworming</strong></td>\n</tr>\n<tr>\n<td><strong>Rehabilitation</strong></td>\n<td>Nutritional rehabilitation; hospital treatment of severe acute malnutrition (SAM units, F-75/F-100, RUTF); follow-up</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.518","n":518,"part":9,"topic":"Food & Nutrition","stars":3,"years":["24Nov","24M","11Ju","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"Malnutrition & PEM","q":"<p>Classify PEM.</p>","a":"<p><strong>Classification of PEM</strong></p>\n<table>\n<thead>\n<tr>\n<th>Classification</th>\n<th>Basis</th>\n<th>Grades</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Gomez</strong></td>\n<td>Weight-for-age (% of reference median)</td>\n<td>Normal &gt;90%; Grade I (mild) 75–90%; Grade II (moderate) 60–75%; Grade III (severe) &lt;60%</td>\n</tr>\n<tr>\n<td><strong>Wellcome</strong></td>\n<td>Weight-for-age + oedema</td>\n<td>60–80% without oedema: underweight; 60–80% with oedema: <strong>kwashiorkor</strong>; &lt;60% without oedema: <strong>marasmus</strong>; &lt;60% with oedema: <strong>marasmic kwashiorkor</strong></td>\n</tr>\n<tr>\n<td><strong>Waterlow</strong></td>\n<td>Weight-for-height (wasting) and height-for-age (stunting)</td>\n<td>Normal; wasted; stunted; wasted and stunted</td>\n</tr>\n<tr>\n<td><strong>WHO (z-scores)</strong></td>\n<td>Weight-for-height, height-for-age, weight-for-age, MUAC, oedema</td>\n<td><strong>Moderate</strong>: −2 to −3 SD (MUAC 115–125 mm); <strong>Severe (SAM)</strong>: &lt; −3 SD weight-for-height, or <strong>MUAC &lt;115 mm</strong>, or <strong>bilateral pitting oedema</strong></td>\n</tr>\n<tr>\n<td>IAP</td>\n<td>Weight-for-age</td>\n<td>Grade I 71–80%; II 61–70%; III 51–60%; IV ≤50%</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Clinical classification</strong>: kwashiorkor, marasmus, marasmic kwashiorkor.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.519","n":519,"part":9,"topic":"Food & Nutrition","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Malnutrition & PEM","q":"<p>Classify PEM according to Gomez; advantages and disadvantages of Gomez classification.</p>","a":"<p><strong>Gomez classification (weight-for-age, % of reference median)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Grade</th>\n<th>Weight-for-age</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Normal</td>\n<td>&gt;90%</td>\n</tr>\n<tr>\n<td>I (mild)</td>\n<td>75–90%</td>\n</tr>\n<tr>\n<td>II (moderate)</td>\n<td>60–75%</td>\n</tr>\n<tr>\n<td>III (severe)</td>\n<td>&lt;60%</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Advantages</strong></p>\n<p>Simple; uses only weight and age; good for community prevalence; correlates with risk of death.</p>\n<p><strong>Disadvantages</strong></p>\n<ol>\n<li>Needs <strong>accurate age</strong>.</li>\n<li>Does not separate <strong>acute (wasting)</strong> from <strong>chronic (stunting)</strong> malnutrition.</li>\n<li>Ignores <strong>oedema</strong>: kwashiorkor may appear normal.</li>\n<li>Arbitrary cut-offs; depends on reference used.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.520","n":520,"part":9,"topic":"Food & Nutrition","stars":0,"years":["10Ja","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Malnutrition & PEM","q":"<p>State the primary causes of PEM / outline the factors of causation of severe malnutrition.</p>","a":"<p><strong>Causes of PEM</strong></p>\n<ol>\n<li><strong>Inadequate dietary intake</strong>: poverty, food insecurity, large family.</li>\n<li><strong>Faulty feeding</strong>: no exclusive breastfeeding, late or poor complementary feeding, dilute feeds.</li>\n<li><strong>Infections</strong>: diarrhoea, measles, ARI, worms, TB.</li>\n<li><strong>Low birth weight</strong>.</li>\n<li><strong>Short birth spacing</strong>, maternal malnutrition.</li>\n<li><strong>Ignorance</strong>, food taboos, maternal illiteracy.</li>\n<li><strong>Poor sanitation</strong> and unsafe water.</li>\n<li>Social factors: gender discrimination, maternal deprivation, broken families, natural disasters.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.521","n":521,"part":9,"topic":"Food & Nutrition","stars":3,"years":["25Nov","24M","23Nov","21M","19Nov","17J","16Ja","10Ju","09Ju"],"colleges":"ShSMC (1st Term B2)","asked":"why does kwashiorkor have oedema while marasmus does not?","note":"","kind":"","sub":"Malnutrition & PEM","q":"<p>Summarize the principal features of / differentiate between kwashiorkor and marasmus.</p>","a":"<p><strong>Kwashiorkor vs marasmus</strong></p>\n<table>\n<thead>\n<tr>\n<th>Feature</th>\n<th>Kwashiorkor</th>\n<th>Marasmus</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Main deficiency</td>\n<td><strong>Protein</strong> (relatively more)</td>\n<td><strong>Energy</strong> (and protein)</td>\n</tr>\n<tr>\n<td>Usual age</td>\n<td>1–3 years (after weaning)</td>\n<td>First year of life</td>\n</tr>\n<tr>\n<td>Onset</td>\n<td>Acute (often after infection)</td>\n<td>Gradual</td>\n</tr>\n<tr>\n<td><strong>Oedema</strong></td>\n<td><strong>Present</strong> (pitting, feet up)</td>\n<td><strong>Absent</strong></td>\n</tr>\n<tr>\n<td>Weight-for-age</td>\n<td>60–80%</td>\n<td>&lt;60%</td>\n</tr>\n<tr>\n<td>Muscle wasting</td>\n<td>Present, masked by oedema</td>\n<td><strong>Severe</strong> (&quot;skin and bones&quot;)</td>\n</tr>\n<tr>\n<td>Subcutaneous fat</td>\n<td>Partly preserved</td>\n<td><strong>Absent</strong></td>\n</tr>\n<tr>\n<td>Face</td>\n<td>Moon face</td>\n<td>&quot;Old man&quot; (monkey) face</td>\n</tr>\n<tr>\n<td>Mental state</td>\n<td><strong>Apathetic, irritable</strong>, miserable</td>\n<td>Alert, hungry</td>\n</tr>\n<tr>\n<td>Appetite</td>\n<td>Poor</td>\n<td>Good</td>\n</tr>\n<tr>\n<td>Skin</td>\n<td><strong>Flaky-paint dermatosis</strong></td>\n<td>Dry, wrinkled, loose</td>\n</tr>\n<tr>\n<td>Hair</td>\n<td>Sparse, thin, depigmented (<strong>flag sign</strong>)</td>\n<td>Usually normal</td>\n</tr>\n<tr>\n<td>Liver</td>\n<td><strong>Fatty, enlarged</strong></td>\n<td>Normal</td>\n</tr>\n<tr>\n<td>Serum albumin</td>\n<td>Very low</td>\n<td>Normal or slightly low</td>\n</tr>\n<tr>\n<td>Prognosis</td>\n<td>Worse</td>\n<td>Better if treated</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.522","n":522,"part":9,"topic":"Food & Nutrition","stars":3,"years":["13Ju","09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Lathyrism & Food Adulteration","q":"<p>Discuss prevention &amp; control measures of lathyrism in a community.</p>","a":"<p><strong>Lathyrism</strong></p>\n<p>Spastic paralysis of the lower limbs from eating large amounts of <strong>khesari dal</strong> (<em>Lathyrus sativus</em>) containing the neurotoxin <strong>BOAA</strong> (β-oxalyl amino alanine) over months.</p>\n<p><strong>Prevention and control (Park)</strong></p>\n<ol>\n<li><strong>Vitamin C prophylaxis</strong> in endemic areas.</li>\n<li><strong>Banning the crop</strong> (sale of khesari dal) and enforcing food laws.</li>\n<li><strong>Removal of toxin</strong>:\n<ul>\n<li><strong>Steeping</strong>: soak dal in hot water for 2 hours, discard water.</li>\n<li><strong>Parboiling</strong>.</li>\n</ul>\n</li>\n<li><strong>Genetic approach</strong>: grow low-toxin strains.</li>\n<li><strong>Education</strong>: limit khesari dal in diet; mix with other pulses and cereals.</li>\n<li>Improve food security so the poor need not depend on khesari dal in hard times.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.523","n":523,"part":9,"topic":"Food & Nutrition","stars":3,"years":["22Nov","12Ja"],"colleges":"SSMC (1st Supp C4); MMC (1st Supp D5)","asked":"write notes on food adulteration with at least three examples","note":"","kind":"","sub":"Lathyrism & Food Adulteration","q":"<p>What is food adulteration?</p>","a":"<p><strong>Food adulteration</strong></p>\n<p>Lowering the quality of food by <strong>adding inferior, harmful or unwanted substances</strong>, <strong>removing valuable constituents</strong>, or <strong>substituting</strong> cheaper materials, so that the food is not of the nature, substance or quality claimed or is injurious to health.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.524","n":524,"part":9,"topic":"Food & Nutrition","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"Milk Borne Diseases","q":"<p>List five milk borne diseases.</p>","a":"<p><strong>Milk-borne diseases</strong></p>\n<p><strong>A. From infected animals</strong></p>\n<ol>\n<li><strong>Tuberculosis</strong> (bovine, <em>M. bovis</em>)</li>\n<li><strong>Brucellosis</strong></li>\n<li><strong>Q fever</strong></li>\n<li>Salmonellosis</li>\n<li>Streptococcal and staphylococcal infections (mastitis)</li>\n<li>Anthrax, leptospirosis, foot-and-mouth disease (rare)</li>\n</ol>\n<p><strong>B. From human handlers or contaminated water and utensils</strong></p>\n<ol>\n<li><strong>Typhoid</strong> and paratyphoid</li>\n<li>Cholera</li>\n<li>Shigellosis</li>\n<li>Diphtheria, streptococcal sore throat (scarlet fever)</li>\n<li>Hepatitis A, <em>E. coli</em> infections, staphylococcal food poisoning</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.525","n":525,"part":9,"topic":"Food & Nutrition","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Food Poisoning","q":"<p>What are the features of food poisoning?</p>","a":"<p><strong>Food poisoning</strong></p>\n<p>Acute gastroenteritis caused by eating food contaminated with microorganisms, their toxins or chemicals.</p>\n<p><strong>Epidemiological features (Park)</strong></p>\n<ol>\n<li><strong>History of ingestion of a common food</strong>.</li>\n<li><strong>Large number of cases</strong>.</li>\n<li><strong>Sudden, simultaneous onset</strong> (short incubation: hours).</li>\n<li><strong>Similar symptoms</strong>: nausea, vomiting, abdominal pain, diarrhoea.</li>\n<li>Cases <strong>confined to those who ate the food</strong> (clustering).</li>\n<li><strong>No secondary cases</strong> (not person-to-person).</li>\n</ol>\n<p><strong>Investigation</strong></p>\n<p>Line list of cases; food-specific attack rates; samples of food, vomit, stool; inspection of kitchen and food handlers.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Nutrition and Health).</p>"},{"id":"DU.526","n":526,"part":10,"topic":"Accidents","stars":3,"years":["18Nov","16Ja","12Ju"],"colleges":"MMC (2nd Term D4)","asked":"safety education, safety and legislative measures to prevent RTA","note":"","kind":"","sub":"","q":"<p>Mention the measures for reducing / preventing road traffic accidents.</p>","a":"<p><strong>Prevention of road traffic accidents (RTA)</strong></p>\n<p><strong>A. Data and research</strong>: accident surveillance, black-spot identification.</p>\n<p><strong>B. Measures (Haddon's approach: human, vehicle, environment; before, during, after crash)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Human (driver, pedestrian)</strong></td>\n<td>Driver training and licensing; <strong>no drunk driving</strong>; speed limits; <strong>helmets</strong> (motorcyclists, cyclists), <strong>seat belts</strong>, child restraints; ban mobile phone use while driving; rest for drivers (no fatigue); health check of drivers (vision); road-safety education in schools</td>\n</tr>\n<tr>\n<td><strong>Vehicle</strong></td>\n<td>Fitness certificates; brakes, lights, tyres; ban unfit and overloaded vehicles; speed governors; safer designs</td>\n</tr>\n<tr>\n<td><strong>Road environment</strong></td>\n<td>Good roads, footpaths, <strong>foot-overbridges / zebra crossings</strong>, separate lanes for slow vehicles, road dividers, signs, street lights, removal of black spots, traffic signals</td>\n</tr>\n<tr>\n<td><strong>Enforcement and legislation</strong></td>\n<td>Road Transport Act 2018; traffic police; fines; CCTV; ban on illegal vehicles on highways</td>\n</tr>\n<tr>\n<td><strong>Post-crash care</strong></td>\n<td>First aid by trained bystanders; <strong>ambulance services</strong>; trauma centres; emergency number (999); rehabilitation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Bangladesh priorities</strong>: highways (buses, trucks, motorcycles), pedestrian safety, reckless and unlicensed driving, overloading, poor enforcement.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.527","n":527,"part":10,"topic":"Accidents","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the role of a pedestrian in preventing RTA in a crowded city like Dhaka.</p>","a":"<p><strong>Role of pedestrians in preventing RTA in Dhaka</strong></p>\n<ol>\n<li>Use <strong>footpaths</strong>, foot-overbridges, underpasses and <strong>zebra crossings</strong>.</li>\n<li>Cross only at signals; <strong>look right–left–right</strong>; never run across.</li>\n<li>Do not cross between parked vehicles, near bends or in front of buses.</li>\n<li>Avoid using <strong>mobile phones / earphones</strong> while walking or crossing.</li>\n<li>Walk <strong>facing oncoming traffic</strong> where there is no footpath.</li>\n<li>Wear light or reflective clothing at night.</li>\n<li>Hold children's hands; teach them road rules.</li>\n<li>Do not get on or off <strong>moving buses</strong>.</li>\n<li>Obey traffic police and signals.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.528","n":528,"part":10,"topic":"Accidents","stars":3,"years":["18M","13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist the primary factors in accidents / discuss epidemiological triad regarding accident with example.</p>","a":"<p><strong>Epidemiological triad of accidents</strong></p>\n<p>Agent ↔ Host ↔ Environment</p>\n<table>\n<thead>\n<tr>\n<th>Component</th>\n<th>Factors</th>\n<th>Example (road accident)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Agent</strong></td>\n<td><strong>Energy</strong> transferred to the body: mechanical (kinetic), thermal, chemical, electrical, radiation</td>\n<td>Speed of a bus (kinetic energy)</td>\n</tr>\n<tr>\n<td><strong>Host (human)</strong></td>\n<td>Age (children, elderly), sex (young males), alcohol and drugs, fatigue, inexperience, poor vision, illness (epilepsy), personality (risk-taking), not using helmet/seat belt</td>\n<td>Untrained, sleepy driver</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>Physical: road design, lighting, weather, traffic density; vehicle condition; social: laws, enforcement, culture, poverty</td>\n<td>Narrow highway, fog, no divider, weak enforcement</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Primary factors in accidents</strong></p>\n<ol>\n<li><strong>Human</strong>: unsafe behaviour (speeding, drunk driving), fatigue.</li>\n<li><strong>Vehicle / machine</strong>: defects, overloading.</li>\n<li><strong>Environment</strong>: unsafe roads, poor lighting, weather.</li>\n<li><strong>Socio-economic</strong>: poverty, poor laws and enforcement.</li>\n</ol>\n<p><strong>Use</strong></p>\n<p>Plan prevention at each arm (Haddon matrix): educate drivers, maintain vehicles, improve roads.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.529","n":529,"part":10,"topic":"Accidents","stars":3,"years":["19M","16Ja","14Ju","10Ju","04Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the underlying causes (factors) and possible preventive measures of industrial accident (also: in context of Bangladesh).</p>","a":"<p><strong>Industrial accidents</strong></p>\n<p><strong>A. Underlying causes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Factors</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Human</strong></td>\n<td>Lack of training, fatigue (long hours), carelessness, alcohol/drugs, inexperience, illiteracy, young or old workers</td>\n</tr>\n<tr>\n<td><strong>Machine / equipment</strong></td>\n<td>Unguarded machinery, faulty equipment, lack of maintenance</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>Poor lighting, noise, heat, slippery floors, overcrowding, poor ventilation, <strong>unsafe buildings</strong>, faulty wiring, locked or blocked exits</td>\n</tr>\n<tr>\n<td><strong>Management</strong></td>\n<td>Production pressure, no safety policy or committee, no PPE, poor supervision</td>\n</tr>\n<tr>\n<td><strong>Legal</strong></td>\n<td>Weak enforcement of safety laws, few inspectors</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Bangladesh examples</strong>: Tazreen garment factory fire (2012), <strong>Rana Plaza</strong> building collapse (2013), chemical warehouse fires in old Dhaka, ship-breaking accidents.</p>\n<p><strong>B. Preventive measures</strong></p>\n<ol>\n<li><strong>Safe building design</strong> and structural inspection; building codes.</li>\n<li><strong>Fire safety</strong>: open exits, fire doors, alarms, extinguishers, sprinklers, drills.</li>\n<li><strong>Electrical safety</strong>; machine guarding; maintenance.</li>\n<li><strong>PPE</strong>: helmets, gloves, goggles, safety shoes.</li>\n<li><strong>Training</strong> of workers and supervisors; safety committees.</li>\n<li>Reasonable <strong>working hours</strong>; rest breaks.</li>\n<li><strong>Good housekeeping</strong>: clean, uncluttered floors; safe storage of chemicals.</li>\n<li><strong>Inspection and enforcement</strong> (Bangladesh Labour Act; DIFE).</li>\n<li>First aid, emergency response, ambulance; compensation and rehabilitation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries; Occupational Health).</p>"},{"id":"DU.530","n":530,"part":10,"topic":"Accidents","stars":3,"years":["13Ja","11Ju","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify domestic accidents / mention the common domestic accidents.</p>","a":"<p><strong>Common domestic accidents</strong></p>\n<ol>\n<li><strong>Falls</strong> (stairs, roofs, beds, wet floors) — children and elderly.</li>\n<li><strong>Burns and scalds</strong> (cooking fires, hot liquids, kerosene lamps, gas cylinder explosions).</li>\n<li><strong>Drowning</strong> (ponds, buckets) — children 1–4 years.</li>\n<li><strong>Poisoning</strong> (kerosene, medicines, pesticides, cleaning agents).</li>\n<li><strong>Cuts and injuries</strong> (knives, glass, sharp tools).</li>\n<li><strong>Electric shock</strong>.</li>\n<li><strong>Choking</strong> / foreign bodies.</li>\n<li><strong>Animal bites</strong> (dog, snake).</li>\n<li>Suffocation; gas leaks.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.531","n":531,"part":10,"topic":"Accidents","stars":0,"years":["04M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the causes of domestic accidents?</p>","a":"<p><strong>Causes of domestic accidents</strong></p>\n<ol>\n<li><strong>Host</strong>: young children (curious, unsupervised), elderly (poor vision, weak), alcohol, epilepsy.</li>\n<li><strong>Unsafe home design</strong>: no railings, steep stairs, open ponds or wells nearby, poor lighting.</li>\n<li><strong>Unsafe cooking</strong>: open stoves at floor level, loose clothing, kerosene, leaking gas.</li>\n<li><strong>Unsafe storage</strong> of medicines, kerosene, pesticides within children's reach.</li>\n<li><strong>Faulty electrical wiring</strong>.</li>\n<li><strong>Lack of supervision</strong> (busy mothers).</li>\n<li><strong>Overcrowding</strong>, poverty.</li>\n<li>Lack of awareness and first-aid knowledge.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.532","n":532,"part":10,"topic":"Accidents","stars":3,"years":["18M","11Ju","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the measures for prevention of domestic accidents.</p>","a":"<p><strong>Prevention of domestic accidents</strong></p>\n<table>\n<thead>\n<tr>\n<th>Accident</th>\n<th>Preventive measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Falls</strong></td>\n<td>Railings on stairs, balconies, roofs; good lighting; non-slip floors; keep floors dry; bed rails; support for elderly</td>\n</tr>\n<tr>\n<td><strong>Burns</strong></td>\n<td>Raised, enclosed stoves; keep children away from kitchen; avoid loose clothing (sari, orna) while cooking; safe gas cylinders and pipes; fire extinguisher; matches out of reach</td>\n</tr>\n<tr>\n<td><strong>Drowning</strong></td>\n<td><strong>Fence or cover ponds, wells, buckets</strong>; supervise children; crèches (day care); swimming lessons for children aged ≥6</td>\n</tr>\n<tr>\n<td><strong>Poisoning</strong></td>\n<td>Store medicines, kerosene, pesticides <strong>locked</strong> and out of reach; original labelled containers</td>\n</tr>\n<tr>\n<td><strong>Electric shock</strong></td>\n<td>Safe wiring, earthing, socket covers, circuit breakers</td>\n</tr>\n<tr>\n<td><strong>Cuts</strong></td>\n<td>Store knives and glass safely</td>\n</tr>\n<tr>\n<td><strong>Choking</strong></td>\n<td>Keep small objects away from infants; age-appropriate food</td>\n</tr>\n</tbody>\n</table>\n<p><strong>General</strong>: health education of mothers and families; safer home design; <strong>first-aid</strong> training; emergency numbers; community awareness.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.533","n":533,"part":10,"topic":"Accidents","stars":2,"years":["19M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Give your opinions on prevention and control measures of fire accident in urban area.</p>","a":"<p><strong>Prevention and control of fire accidents in urban areas</strong></p>\n<p><strong>A. Prevention</strong></p>\n<ol>\n<li><strong>Building codes</strong>: fire-resistant materials, <strong>adequate exits</strong>, fire escapes, wide stairs; no locked exits.</li>\n<li><strong>Ban hazardous storage</strong> (chemicals, gas cylinders) in residential areas (e.g., old Dhaka); relocate chemical warehouses.</li>\n<li><strong>Safe electrical wiring</strong>; avoid overloaded connections; inspection.</li>\n<li><strong>Safe gas use</strong>: check cylinders and pipelines for leaks.</li>\n<li><strong>Fire detection</strong>: smoke detectors, alarms; <strong>extinguishers</strong>, hydrants, sprinklers.</li>\n<li><strong>Fire drills</strong> and staff training in factories, hospitals, schools, markets.</li>\n<li>Public awareness; no smoking near flammables.</li>\n<li>Regular <strong>inspection and enforcement</strong> by Fire Service and city authorities.</li>\n</ol>\n<p><strong>B. Control / response</strong></p>\n<ol>\n<li><strong>Early alarm</strong> (999), evacuation plans.</li>\n<li>Accessible roads for fire engines; water sources.</li>\n<li>Well-equipped, trained <strong>fire service</strong>.</li>\n<li><strong>Burn units</strong>, ambulances, trauma care.</li>\n<li>Rehabilitation, compensation, psychological support.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.534","n":534,"part":10,"topic":"Accidents","stars":0,"years":[],"colleges":"MMC (2nd Term D3)","asked":"","note":"","kind":"","sub":"","q":"<p>Outline the prevention and control measures of snake bite.</p>","a":"<p><strong>Snake bite: prevention and control</strong></p>\n<p><strong>A. Prevention</strong></p>\n<ol>\n<li>Wear <strong>boots</strong>, cover legs when working in fields; use a <strong>torch</strong> at night.</li>\n<li>Sleep on a raised bed under a <strong>bed net</strong>.</li>\n<li>Keep houses and surroundings clean; remove rubbish, rat holes (rats attract snakes).</li>\n<li>Avoid putting hands into holes or under rocks.</li>\n<li>Health education in rural areas.</li>\n</ol>\n<p><strong>B. First aid</strong></p>\n<ol>\n<li><strong>Reassure</strong>; immobilise the limb (splint); keep still.</li>\n<li>Remove rings and tight items.</li>\n<li><strong>No cutting, sucking, tight tourniquets</strong> or traditional healers (<em>ojha</em>).</li>\n<li><strong>Transport quickly</strong> to a health facility.</li>\n</ol>\n<p><strong>C. Treatment</strong></p>\n<p><strong>Anti-snake venom (polyvalent)</strong> for envenomation; supportive care (ventilation for neurotoxic bites, dialysis); tetanus prophylaxis.</p>\n<p><strong>D. Health system</strong></p>\n<p>Antivenom and trained staff at Upazila Health Complexes; referral; data collection.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.535","n":535,"part":10,"topic":"Accidents","stars":0,"years":[],"colleges":"MuMC (2nd Final C4)","asked":"","note":"","kind":"","sub":"","q":"<p>“Transportation injuries are a public health issue” – justify this comment.</p>","a":"<p><strong>Transportation injuries are a public health issue</strong></p>\n<ol>\n<li><strong>Large burden</strong>: a leading cause of death and disability worldwide, especially among <strong>young people</strong> (5–29 years).</li>\n<li>Cause long-term <strong>disability</strong>, loss of productive years (high DALYs).</li>\n<li><strong>Economic loss</strong>: medical costs, loss of earnings, families pushed into poverty.</li>\n<li>Affect mostly <strong>vulnerable road users</strong> (pedestrians, cyclists, motorcyclists) and the poor in LMICs.</li>\n<li><strong>Preventable</strong> by known public health measures (helmets, seat belts, speed control, safe roads).</li>\n<li>Need <strong>multisectoral</strong> action (transport, police, health, education).</li>\n<li>Pressure on <strong>health services</strong> (trauma care, rehabilitation).</li>\n<li>Included in <strong>SDG 3.6</strong> (halve road traffic deaths).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Accidents and Injuries).</p>"},{"id":"DU.536","n":536,"part":10,"topic":"Disasters","stars":3,"years":["18Nov","12Ju","12Ja","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Classify disasters (with examples).</p>","a":"<p><strong>Classification of disasters</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>A. Natural</strong></td>\n<td></td>\n</tr>\n<tr>\n<td>Meteorological / hydrological</td>\n<td><strong>Cyclones</strong>, <strong>floods</strong>, tornadoes, storm surges, <strong>drought</strong>, heat and cold waves</td>\n</tr>\n<tr>\n<td>Geophysical</td>\n<td><strong>Earthquakes</strong>, tsunamis, volcanic eruptions, <strong>landslides</strong></td>\n</tr>\n<tr>\n<td>Biological</td>\n<td><strong>Epidemics / pandemics</strong> (cholera, COVID-19), pest invasions</td>\n</tr>\n<tr>\n<td>Climatological</td>\n<td>Wildfires, river erosion</td>\n</tr>\n<tr>\n<td><strong>B. Man-made</strong></td>\n<td></td>\n</tr>\n<tr>\n<td>Industrial / technological</td>\n<td>Factory fires, explosions, chemical leaks (Bhopal), building collapse (Rana Plaza), nuclear accidents</td>\n</tr>\n<tr>\n<td>Transport</td>\n<td>Ship / launch capsizing, train and air crashes</td>\n</tr>\n<tr>\n<td>Conflict-related</td>\n<td>War, terrorism, refugee crises (Rohingya influx)</td>\n</tr>\n<tr>\n<td>Others</td>\n<td>Stampedes, structural fires</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.537","n":537,"part":10,"topic":"Disasters","stars":0,"years":["08Ju","07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Name the common natural disasters of Bangladesh (with their effects on health).</p>","a":"<p><strong>Common natural disasters of Bangladesh and health effects</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disaster</th>\n<th>Health effects</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Flood</strong></td>\n<td>Drowning, diarrhoea, cholera, typhoid, hepatitis E, leptospirosis, skin infections, snake bites, malnutrition</td>\n</tr>\n<tr>\n<td><strong>Cyclone and storm surge</strong></td>\n<td>Deaths, injuries, drowning, loss of shelter, water contamination, salinity</td>\n</tr>\n<tr>\n<td><strong>River erosion</strong></td>\n<td>Displacement, loss of livelihood, mental stress</td>\n</tr>\n<tr>\n<td><strong>Drought</strong> (north-west)</td>\n<td>Food insecurity, malnutrition</td>\n</tr>\n<tr>\n<td><strong>Heat waves</strong></td>\n<td>Heat stroke, dehydration</td>\n</tr>\n<tr>\n<td><strong>Lightning</strong></td>\n<td>Deaths, burns</td>\n</tr>\n<tr>\n<td><strong>Landslides</strong> (hill districts)</td>\n<td>Deaths, injuries</td>\n</tr>\n<tr>\n<td><strong>Earthquake</strong> (risk)</td>\n<td>Mass casualties, building collapse</td>\n</tr>\n<tr>\n<td><strong>Cold waves</strong></td>\n<td>ARI, deaths among elderly and children</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.538","n":538,"part":10,"topic":"Disasters","stars":3,"years":["16M","11Ja","07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the effects / public health impact of (natural) disasters; epidemiology of disaster and effects of different types of disaster on health.</p>","a":"<p><strong>Public health impact of disasters</strong></p>\n<p><strong>A. Common effects</strong></p>\n<table>\n<thead>\n<tr>\n<th>Effect</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Deaths and injuries</strong></td>\n<td>Sudden mass casualties (trauma, drowning)</td>\n</tr>\n<tr>\n<td><strong>Communicable diseases</strong></td>\n<td>Diarrhoea, cholera, typhoid, hepatitis, ARI, measles, leptospirosis, vector-borne diseases (from crowding, unsafe water, poor sanitation)</td>\n</tr>\n<tr>\n<td><strong>Food shortage and malnutrition</strong></td>\n<td>Crop loss; worse in children, pregnant women</td>\n</tr>\n<tr>\n<td><strong>Population displacement</strong></td>\n<td>Overcrowded shelters; loss of homes</td>\n</tr>\n<tr>\n<td><strong>Damage to health facilities</strong></td>\n<td>Disruption of services, EPI, chronic disease care</td>\n</tr>\n<tr>\n<td><strong>Water and sanitation</strong></td>\n<td>Contaminated sources, destroyed latrines</td>\n</tr>\n<tr>\n<td><strong>Mental health</strong></td>\n<td>Acute stress, anxiety, depression, PTSD</td>\n</tr>\n<tr>\n<td><strong>Environmental</strong></td>\n<td>Debris, dead bodies and animals, vector breeding</td>\n</tr>\n<tr>\n<td><strong>Socio-economic</strong></td>\n<td>Loss of livelihoods, poverty</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Effects by type of disaster</strong></p>\n<table>\n<thead>\n<tr>\n<th>Disaster</th>\n<th>Typical health problems</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Earthquake</td>\n<td>Crush injuries, fractures, deaths (trapped)</td>\n</tr>\n<tr>\n<td>Cyclone / storm surge</td>\n<td>Drowning, injuries, saline water</td>\n</tr>\n<tr>\n<td>Flood</td>\n<td>Drowning, water-borne and vector-borne diseases, snake bites</td>\n</tr>\n<tr>\n<td>Drought / famine</td>\n<td>Malnutrition, micronutrient deficiency, deaths</td>\n</tr>\n<tr>\n<td>Industrial accident</td>\n<td>Burns, poisoning, trauma</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Epidemiology of disaster</strong>: surveillance to find needs, rapid health assessment, monitoring of disease outbreaks; vulnerable groups: children, elderly, women, disabled, poor.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.539","n":539,"part":10,"topic":"Disasters","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How can you manage health problems in cyclone devastated remote area?</p>","a":"<p><strong>Managing health problems in a cyclone-devastated remote area</strong></p>\n<ol>\n<li><strong>Rapid needs assessment</strong> (population, injuries, water, sanitation, shelter, diseases).</li>\n<li><strong>Search, rescue and triage</strong>; first aid; evacuate seriously injured.</li>\n<li><strong>Mobile medical teams</strong>; temporary health posts.</li>\n<li><strong>Safe water</strong>: chlorine tablets, bleaching powder, tanker water; repair tube wells.</li>\n<li><strong>Sanitation</strong>: emergency latrines, waste and dead-body/animal disposal.</li>\n<li><strong>Disease surveillance</strong> (diarrhoea, ARI, measles); outbreak response.</li>\n<li><strong>ORS, essential drugs</strong>, tetanus prophylaxis; measles vaccination and vitamin A for children.</li>\n<li><strong>Food and nutrition</strong> support; care of pregnant women and children.</li>\n<li>Shelter, clothing, hygiene kits.</li>\n<li><strong>Psychosocial support</strong>.</li>\n<li>Coordination with administration, NGOs, Red Crescent, armed forces.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.540","n":540,"part":10,"topic":"Disasters","stars":3,"years":["16Ja","14Ju","12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the impacts / immediate health hazards of flood on public health.</p>","a":"<p><strong>Immediate health hazards of flood</strong></p>\n<ol>\n<li><strong>Drowning</strong> and <strong>injuries</strong> (especially children).</li>\n<li><strong>Water-borne diseases</strong>: acute watery diarrhoea, <strong>cholera</strong>, dysentery, <strong>typhoid</strong>, <strong>hepatitis A and E</strong>.</li>\n<li><strong>Leptospirosis</strong> (contact with flood water contaminated by rat urine).</li>\n<li><strong>Skin infections</strong> and fungal infections; eye infections (conjunctivitis).</li>\n<li><strong>Respiratory infections</strong> (crowded shelters, cold).</li>\n<li><strong>Snake bites</strong>, insect bites.</li>\n<li><strong>Vector-borne diseases</strong> (dengue, malaria) after water recedes.</li>\n<li><strong>Electrocution</strong>, injuries from debris.</li>\n<li><strong>Food shortage</strong>, malnutrition; contamination of food.</li>\n<li><strong>Disruption of health services</strong> (EPI, ANC, chronic disease drugs).</li>\n<li><strong>Displacement</strong>, overcrowding, lack of privacy for women.</li>\n<li><strong>Mental stress</strong>, anxiety.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.541","n":541,"part":10,"topic":"Disasters","stars":3,"years":["23Nov","22Nov","13Ju"],"colleges":"MuMC (2nd Final A3)","asked":"emergency preparedness and response programme in Bangladesh","note":"","kind":"","sub":"","q":"<p>Describe (briefly discuss) disaster preparedness.</p>","a":"<p><strong>Disaster preparedness</strong></p>\n<p>All measures taken <strong>before a disaster</strong> to ensure an effective response and minimise loss of life and health.</p>\n<p><strong>Disaster cycle</strong></p>\n<p>Mitigation → <strong>Preparedness</strong> → Response → Recovery / rehabilitation → (back to mitigation)</p>\n<p><strong>Components of preparedness</strong></p>\n<ol>\n<li><strong>Risk assessment and mapping</strong>: hazards, vulnerable populations, resources.</li>\n<li><strong>Disaster plan</strong> at national, district and upazila levels; clear roles (Standing Orders on Disaster).</li>\n<li><strong>Early warning systems</strong> (cyclone warning signals, flood forecasting) and communication channels.</li>\n<li><strong>Shelters</strong> (cyclone shelters) and evacuation plans.</li>\n<li><strong>Training and drills</strong> of health staff and volunteers (Cyclone Preparedness Programme).</li>\n<li><strong>Stockpiling</strong> essential drugs, ORS, water purification tablets, food, tents.</li>\n<li><strong>Health facility preparedness</strong>: emergency plans, mass casualty management, triage.</li>\n<li><strong>Public education</strong> and community participation.</li>\n<li><strong>Coordination</strong> with government, NGOs, Red Crescent, armed forces.</li>\n<li><strong>Surveillance</strong> system ready for outbreaks.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.542","n":542,"part":10,"topic":"Disasters","stars":0,"years":["25Nov"],"colleges":"MuMC (2nd Final A3)","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by triage?</p>","a":"<p><strong>Triage</strong></p>\n<p><strong>Rapid sorting and classification of casualties</strong> according to the <strong>severity of injuries and the urgency of treatment</strong>, so that the greatest number can be saved with limited resources (French <em>trier</em> = to sort).</p>\n<p><strong>Colour coding (commonly used)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Colour</th>\n<th>Priority</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Red</strong></td>\n<td><strong>Immediate</strong> (first priority): life-threatening but treatable</td>\n<td>Airway obstruction, severe bleeding, shock, tension pneumothorax</td>\n</tr>\n<tr>\n<td><strong>Yellow</strong></td>\n<td><strong>Delayed</strong> (second priority): serious, can wait a few hours</td>\n<td>Fractures, moderate burns</td>\n</tr>\n<tr>\n<td><strong>Green</strong></td>\n<td><strong>Minor</strong> (walking wounded)</td>\n<td>Minor cuts, bruises</td>\n</tr>\n<tr>\n<td><strong>Black</strong></td>\n<td><strong>Dead or expectant</strong> (unlikely to survive)</td>\n<td>No breathing after airway opening, massive injuries</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.543","n":543,"part":10,"topic":"Disasters","stars":0,"years":[],"colleges":"MMC (2nd Term A3)","asked":"","note":"","kind":"","sub":"","q":"<p>How can disasters be mitigated?</p>","a":"<p><strong>Disaster mitigation</strong></p>\n<p>Measures to <strong>reduce the impact</strong> (deaths, damage) of disasters before they happen.</p>\n<ol>\n<li><strong>Hazard mapping</strong> and land-use planning (no settlement on riverbanks, slopes).</li>\n<li><strong>Structural measures</strong>: embankments, cyclone shelters, earthquake-resistant buildings, raised homes and tube wells.</li>\n<li><strong>Coastal green belts</strong> (mangroves).</li>\n<li><strong>Early warning systems</strong>.</li>\n<li><strong>Building codes</strong> and enforcement.</li>\n<li><strong>Community awareness</strong> and training.</li>\n<li><strong>Insurance</strong>, social safety nets, livelihood diversification.</li>\n<li><strong>Climate adaptation</strong>; afforestation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.544","n":544,"part":10,"topic":"Disasters","stars":0,"years":[],"colleges":"MMC (1st Supp A3)","asked":"","note":"","kind":"","sub":"","q":"<p>Suppose you are working as a UHFPO. Flood has affected the nearby areas of your locality. How will you form a health team to address the health problems of that area?</p>","a":"<p><strong>Forming a flood health team as UH&amp;FPO</strong></p>\n<p><strong>1. Assess</strong>: rapid assessment of affected unions, population, health risks, facilities and resources.</p>\n<p><strong>2. Composition of team(s)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Member</th>\n<th>Role</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Medical officer</strong> (team leader)</td>\n<td>Clinical care, triage, referral, coordination</td>\n</tr>\n<tr>\n<td><strong>SACMO / nurse / midwife</strong></td>\n<td>Treatment of common illnesses, ANC/PNC, deliveries, first aid</td>\n</tr>\n<tr>\n<td><strong>Health Inspector / AHI / Health Assistants</strong></td>\n<td>Surveillance, water disinfection, sanitation, health education, EPI (measles, vitamin A)</td>\n</tr>\n<tr>\n<td><strong>CHCPs</strong></td>\n<td>Community-level services, referral</td>\n</tr>\n<tr>\n<td><strong>FWA / FWV</strong> (with UFPO)</td>\n<td>MCH, family planning</td>\n</tr>\n<tr>\n<td><strong>Pharmacist / storekeeper</strong></td>\n<td>Drugs, ORS, water purification tablets, logistics</td>\n</tr>\n<tr>\n<td><strong>Lab technician</strong></td>\n<td>Rapid tests, stool samples</td>\n</tr>\n<tr>\n<td><strong>Volunteers</strong> (Red Crescent, scouts, NGO workers)</td>\n<td>Distribution, mobilisation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>3. Organisation</strong></p>\n<ol>\n<li>Form <strong>mobile medical teams</strong> (one per affected union) and a <strong>control room</strong> at the UHC.</li>\n<li>Stock <strong>emergency kits</strong>: ORS, zinc, antibiotics, chlorine tablets, bleaching powder, IV fluids, antivenom, tetanus toxoid.</li>\n<li>Set up <strong>medical camps</strong> in shelters; ORS corners.</li>\n<li>Daily <strong>surveillance</strong> reporting (diarrhoea, ARI, skin, injuries) to civil surgeon.</li>\n<li>Coordinate with <strong>UNO</strong>, Upazila Disaster Management Committee, DPHE, NGOs.</li>\n<li>Transport (boats), communication (mobile phones).</li>\n</ol>\n<p><strong>4. Activities</strong></p>\n<p>Treatment, safe water and sanitation, health education, immunisation, nutrition, psychosocial support, referral, rehabilitation after flood.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.545","n":545,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["25M","24Nov","22M","20Nov","19Nov","17Ja","16Nov","15Ja","13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define epidemiology.</p>","a":"<p><strong>Definition</strong></p>\n<p><strong>Epidemiology</strong>: &quot;the study of the distribution and determinants of health-related states or events in specified populations, and the application of this study to the control of health problems&quot; (Last, Dictionary of Epidemiology, adopted by WHO).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.546","n":546,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the basic components of epidemiology.</p>","a":"<p><strong>Basic components of epidemiology</strong></p>\n<p><strong>1. Disease frequency</strong>: measurement of disease, disability or death as <strong>rates and ratios</strong> (incidence, prevalence, mortality rates).</p>\n<p><strong>2. Distribution of disease</strong>: pattern by <strong>time</strong> (when), <strong>place</strong> (where) and <strong>person</strong> (who) → descriptive epidemiology; generates hypotheses.</p>\n<p><strong>3. Determinants of disease</strong>: identification of <strong>causes and risk factors</strong> by testing hypotheses (analytical and experimental epidemiology).</p>\n<p><strong>Ultimate aim</strong></p>\n<p>Use this knowledge for <strong>prevention, control and planning</strong> of health services.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.547","n":547,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["17Nov","16Ju","15Ja","14Ja","12Ju","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the aims / uses / importance of epidemiology (also: in medical science in the light of your experience).</p>","a":"<p><strong>Aims of epidemiology (IEA)</strong></p>\n<ol>\n<li><strong>Describe</strong> the distribution and size of health problems in populations.</li>\n<li>Provide data essential to <strong>planning, implementation and evaluation</strong> of services for prevention, control and treatment.</li>\n<li><strong>Identify aetiological factors</strong> (causes, risk factors).</li>\n</ol>\n<p><strong>Uses (Morris)</strong></p>\n<ol>\n<li><strong>Study historical trends</strong> of disease (rise and fall).</li>\n<li><strong>Community diagnosis</strong>: identify health problems and their size.</li>\n<li><strong>Planning and evaluation</strong> of health services.</li>\n<li><strong>Evaluation of individual risks</strong> (risk factors).</li>\n<li><strong>Syndrome identification</strong>: describe new diseases.</li>\n<li><strong>Completing the natural history</strong> of disease.</li>\n<li><strong>Search for causes</strong> of disease.</li>\n</ol>\n<p><strong>Importance in medical science (examples)</strong></p>\n<p>Smoking and lung cancer; rubella and congenital defects; ORS trials; COVID-19 surveillance and vaccine trials; screening programmes; evidence-based clinical practice.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.548","n":548,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["26M","25Nov","22M","19Nov","19M","16Nov","12Ju","04Ja"],"colleges":"SSMC (1st Supp D3)","asked":"name the tools of measurement and explain them individually","note":"","kind":"","sub":"","q":"<p>Enumerate the measurements / mention basic tools of measurement in epidemiology with an example.</p>","a":"<p><strong>Basic tools of measurement in epidemiology</strong></p>\n<table>\n<thead>\n<tr>\n<th>Tool</th>\n<th>Definition</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Rate</strong></td>\n<td>Occurrence of events in a population over a time period: (events ÷ population at risk) × multiplier</td>\n<td>Crude death rate = deaths per 1,000 population per year</td>\n</tr>\n<tr>\n<td><strong>Ratio</strong></td>\n<td>Relation of one quantity to another (numerator not part of denominator)</td>\n<td>Sex ratio; doctor–population ratio; MMR (per 100,000 live births)</td>\n</tr>\n<tr>\n<td><strong>Proportion</strong></td>\n<td>Ratio where numerator is part of denominator, usually as %</td>\n<td>Proportion of deaths due to TB = 10%</td>\n</tr>\n</tbody>\n</table>\n<p><strong>What is measured</strong></p>\n<p>Mortality, morbidity (incidence, prevalence), disability, natality, presence of attributes (height, BP), use of health services, risk factors.</p>\n<p><strong>Measures of association</strong></p>\n<p>Relative risk, odds ratio, attributable risk.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.549","n":549,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["24M","22Nov","21M","18Nov","17Nov","16Ju","15Ja","14Ja","13Ja","12Ja","11Ja"],"colleges":"SSMC (1st Supp D2); MMC (1st Supp C2)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the approaches in epidemiology? Classify epidemiological methods / methods of epidemiological study.</p>","a":"<p><strong>Approaches in epidemiology</strong></p>\n<ol>\n<li><strong>Asking questions</strong> (what, when, where, who, why).</li>\n<li><strong>Making comparisons</strong> (between groups) to find associations.</li>\n</ol>\n<p><strong>Classification of epidemiological methods (studies)</strong></p>\n<pre><code>Epidemiological studies\n├── A. Observational\n│    ├── Descriptive studies (case report, case series, cross-sectional, ecological)\n│    └── Analytical studies\n│         ├── Ecological (correlational)\n│         ├── Cross-sectional (prevalence)\n│         ├── Case-control (case–reference)\n│         └── Cohort (follow-up)\n└── B. Experimental (intervention)\n     ├── Randomised controlled trials (patients)\n     ├── Field trials (healthy people)\n     └── Community trials (whole communities)\n</code></pre>\n<table>\n<thead>\n<tr>\n<th>Study</th>\n<th>Unit</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Descriptive</td>\n<td>Population</td>\n<td>Prevalence of anaemia</td>\n</tr>\n<tr>\n<td>Case-control</td>\n<td>Individual (cases vs controls)</td>\n<td>Betel nut and oral cancer</td>\n</tr>\n<tr>\n<td>Cohort</td>\n<td>Individual (exposed vs non-exposed)</td>\n<td>Smoking and CHD</td>\n</tr>\n<tr>\n<td>RCT</td>\n<td>Patients</td>\n<td>New antihypertensive drug</td>\n</tr>\n<tr>\n<td>Field trial</td>\n<td>Healthy individuals</td>\n<td>Vaccine trial</td>\n</tr>\n<tr>\n<td>Community trial</td>\n<td>Communities</td>\n<td>Salt-reduction programme</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.550","n":550,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["17M","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the steps of a descriptive study / steps of study design to observe distribution of a disease among a population.</p>","a":"<p><strong>Steps of a descriptive study (Park)</strong></p>\n<ol>\n<li><strong>Define the population</strong> to be studied (defined population with known size and characteristics).</li>\n<li><strong>Define the disease</strong> under study (clear case definition; operational criteria).</li>\n<li><strong>Describe the disease</strong> by:\n<ul>\n<li><strong>Time</strong>: short-term fluctuations, periodic (seasonal, cyclic), long-term (secular) trends.</li>\n<li><strong>Place</strong>: international, national, rural–urban, local (spot maps).</li>\n<li><strong>Person</strong>: age, sex, marital status, occupation, social class, behaviour, stress, migration.</li>\n</ul>\n</li>\n<li><strong>Measure the disease</strong>: incidence, prevalence, mortality rates.</li>\n<li><strong>Compare</strong> with known indices (other places, times, groups).</li>\n<li><strong>Formulate an aetiological hypothesis</strong> (what, where, when, who → why).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.551","n":551,"part":10,"topic":"Basic Principles of Epidemiology","stars":2,"years":["25Nov","11Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>How do you select cases and controls in a case control study? List the basic steps of case control study.</p>","a":"<p><strong>Basic steps of a case-control study</strong></p>\n<ol>\n<li><strong>Selection of cases and controls</strong>.</li>\n<li><strong>Matching</strong>.</li>\n<li><strong>Measurement of exposure</strong> (past exposure, in both groups, in the same way).</li>\n<li><strong>Analysis and interpretation</strong>: exposure rates; <strong>odds ratio</strong>.</li>\n</ol>\n<p><strong>Selection of cases</strong></p>\n<ol>\n<li>Clear <strong>case definition</strong> (diagnostic criteria, stage).</li>\n<li><strong>Sources</strong>: hospitals (hospital-based) or the general population (population-based); preferably <strong>incident (new) cases</strong>.</li>\n<li>Cases should be representative of all cases.</li>\n</ol>\n<p><strong>Selection of controls</strong></p>\n<ol>\n<li><strong>Free from the disease</strong> under study.</li>\n<li><strong>Similar to cases</strong> in all other respects except the disease (same population base).</li>\n<li><strong>Sources</strong>: hospital controls (patients with other diseases), relatives, neighbourhood controls, general population.</li>\n<li><strong>Matching</strong> for confounders (age, sex, socio-economic status); one or more controls per case.</li>\n</ol>\n<p><strong>Analysis</strong></p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>Cases</th>\n<th>Controls</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Exposed</td>\n<td>a</td>\n<td>b</td>\n</tr>\n<tr>\n<td>Not exposed</td>\n<td>c</td>\n<td>d</td>\n</tr>\n</tbody>\n</table>\n<p>Odds ratio = ad ÷ bc</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.552","n":552,"part":10,"topic":"Basic Principles of Epidemiology","stars":2,"years":["11Ju","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>List the basic steps of cohort study.</p>","a":"<p><strong>Basic steps of a cohort study</strong></p>\n<ol>\n<li><strong>Selection of study subjects</strong>: general population or special groups (occupational, insured).</li>\n<li><strong>Obtaining data on exposure</strong>: from subjects, records, examinations, environmental surveys.</li>\n<li><strong>Selection of comparison groups</strong>: internal comparison, external comparison, or general population rates.</li>\n<li><strong>Follow-up</strong> of all subjects over time (examinations, records, surveillance).</li>\n<li><strong>Analysis</strong>: incidence in exposed and non-exposed; <strong>relative risk</strong> and <strong>attributable risk</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.553","n":553,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["25M","20Nov","19M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the advantages (and disadvantages) of case control study.</p>","a":"<p><strong>Case-control study</strong></p>\n<p><strong>Advantages</strong></p>\n<ol>\n<li><strong>Quick and cheap</strong>; relatively easy.</li>\n<li><strong>Few subjects</strong> needed.</li>\n<li>Suitable for <strong>rare diseases</strong>.</li>\n<li><strong>No attrition</strong> problems (no follow-up).</li>\n<li>No risk to subjects; ethical.</li>\n<li>Can study <strong>several risk factors</strong> at once.</li>\n<li>Allows study of diseases with long latency.</li>\n<li>Useful first step for hypothesis testing.</li>\n</ol>\n<p><strong>Disadvantages</strong></p>\n<ol>\n<li><strong>Recall bias</strong> (memory of past exposure) and selection bias.</li>\n<li>Difficult to choose an appropriate <strong>control</strong> group.</li>\n<li>Cannot measure <strong>incidence</strong> or relative risk directly (only odds ratio estimate).</li>\n<li>Cannot study <strong>several outcomes</strong> of one exposure.</li>\n<li><strong>Temporal sequence</strong> (exposure before disease) may be unclear.</li>\n<li>Confounding.</li>\n<li>Not suitable for rare exposures.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.554","n":554,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["12Ja","07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the advantages and disadvantages / role and importance of cohort study.</p>","a":"<p><strong>Cohort study</strong></p>\n<p><strong>Advantages / importance</strong></p>\n<ol>\n<li><strong>Incidence</strong> can be calculated directly.</li>\n<li><strong>Relative risk and attributable risk</strong> measured.</li>\n<li><strong>Temporal sequence</strong> clear (exposure before outcome) → stronger causal evidence.</li>\n<li><strong>Several outcomes</strong> of one exposure can be studied.</li>\n<li>Less recall bias.</li>\n<li>Studies <strong>natural history</strong> of disease.</li>\n<li>Good for rare exposures.</li>\n</ol>\n<p><strong>Disadvantages</strong></p>\n<ol>\n<li>Needs <strong>large numbers</strong> and <strong>long follow-up</strong>; costly, time-consuming.</li>\n<li><strong>Loss to follow-up</strong> (attrition).</li>\n<li>Not suitable for <strong>rare diseases</strong>.</li>\n<li>Changes in diagnostic criteria or exposure over time.</li>\n<li>Administrative problems; ethical issues.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.555","n":555,"part":10,"topic":"Basic Principles of Epidemiology","stars":1,"years":["10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Why is cohort study more valid and reliable than case control study?</p>","a":"<p><strong>Why cohort studies are more valid and reliable than case-control studies</strong></p>\n<ol>\n<li><strong>Temporal sequence</strong>: exposure is recorded <strong>before</strong> disease occurs → cause precedes effect.</li>\n<li><strong>Direct measurement of incidence</strong>, relative risk and attributable risk (case-control gives only odds ratio).</li>\n<li><strong>Less recall bias</strong>: exposure measured at the start, not remembered later.</li>\n<li><strong>Less selection bias</strong>: subjects selected by exposure, before outcome is known.</li>\n<li><strong>Several outcomes</strong> can be studied.</li>\n<li>Exposure data are often more <strong>complete and accurate</strong> (measured, not recalled).</li>\n<li>Supports <strong>dose–response</strong> analysis.</li>\n</ol>\n<p>Hence cohort studies give <strong>stronger evidence of causation</strong>, though they are slower and costlier.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.556","n":556,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["24M","23Nov","22M","19Nov","17M","17Ja","16Ja","13Ja","09Ja"],"colleges":"SSMC (1st Supp D2); MMC (1st Supp C2)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between case-control and cohort study.</p>","a":"<p><strong>Case-control vs cohort study</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Case-control study</th>\n<th>Cohort study</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Direction</td>\n<td><strong>Effect → cause</strong> (backward, retrospective)</td>\n<td><strong>Cause → effect</strong> (forward, prospective)</td>\n</tr>\n<tr>\n<td>Starting point</td>\n<td>Disease (cases and controls)</td>\n<td>Exposure (exposed and non-exposed), disease-free</td>\n</tr>\n<tr>\n<td>Groups compared</td>\n<td>Cases vs controls</td>\n<td>Exposed vs non-exposed</td>\n</tr>\n<tr>\n<td>Measures</td>\n<td><strong>Odds ratio</strong></td>\n<td><strong>Incidence, relative risk, attributable risk</strong></td>\n</tr>\n<tr>\n<td>Time</td>\n<td>Short</td>\n<td>Long follow-up</td>\n</tr>\n<tr>\n<td>Cost</td>\n<td>Cheap</td>\n<td>Expensive</td>\n</tr>\n<tr>\n<td>Sample size</td>\n<td>Small</td>\n<td>Large</td>\n</tr>\n<tr>\n<td>Rare diseases</td>\n<td>Suitable</td>\n<td>Not suitable</td>\n</tr>\n<tr>\n<td>Rare exposures</td>\n<td>Not suitable</td>\n<td>Suitable</td>\n</tr>\n<tr>\n<td>Outcomes studied</td>\n<td>One disease, many exposures</td>\n<td>One exposure, many outcomes</td>\n</tr>\n<tr>\n<td>Bias</td>\n<td>Recall and selection bias common</td>\n<td>Loss to follow-up</td>\n</tr>\n<tr>\n<td>Causal evidence</td>\n<td>Weaker</td>\n<td>Stronger</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Betel nut and oral cancer</td>\n<td>Smoking and CHD (Framingham)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.557","n":557,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["25Nov","18M","16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between longitudinal and cross-sectional study (descriptive cross sectional vs longitudinal).</p>","a":"<p><strong>Cross-sectional vs longitudinal study</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Cross-sectional study</th>\n<th>Longitudinal study</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Observation</td>\n<td><strong>Once</strong>, at one point in time (&quot;snapshot&quot;)</td>\n<td><strong>Repeated</strong> observations over a long period (&quot;movie&quot;)</td>\n</tr>\n<tr>\n<td>Measures</td>\n<td><strong>Prevalence</strong></td>\n<td><strong>Incidence</strong>, natural history, changes over time</td>\n</tr>\n<tr>\n<td>Time and cost</td>\n<td>Quick, cheap</td>\n<td>Long, costly</td>\n</tr>\n<tr>\n<td>Temporal relation</td>\n<td>Unclear (exposure and outcome together)</td>\n<td>Clear</td>\n</tr>\n<tr>\n<td>Loss to follow-up</td>\n<td>None</td>\n<td>Common</td>\n</tr>\n<tr>\n<td>Information</td>\n<td>Burden of disease; distribution</td>\n<td>Natural history, prognosis, risk factors, growth patterns</td>\n</tr>\n<tr>\n<td>Best for</td>\n<td>Chronic diseases, planning</td>\n<td>Studying development, ageing, disease course</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Prevalence of hypertension in Dhaka adults</td>\n<td>Following children's growth from birth to 5 years</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.558","n":558,"part":10,"topic":"Basic Principles of Epidemiology","stars":2,"years":["24Nov","11Ja"],"colleges":"DMC (1st Assess A4)","asked":"role of cross-sectional studies in descriptive epidemiology","note":"","kind":"","sub":"","q":"<p>Summarize the key characteristics / advantages of cross sectional studies.</p>","a":"<p><strong>Cross-sectional study: key characteristics</strong></p>\n<ol>\n<li><strong>Exposure and outcome measured at the same time</strong> (single point).</li>\n<li>Gives <strong>prevalence</strong> (&quot;prevalence study&quot;).</li>\n<li>A <strong>sample of the population</strong> is examined once.</li>\n<li>Can be <strong>descriptive</strong> or <strong>analytical</strong> (associations).</li>\n<li>Commonly uses surveys and questionnaires.</li>\n</ol>\n<p><strong>Advantages</strong></p>\n<ol>\n<li><strong>Quick, cheap</strong>, easy to conduct.</li>\n<li>Measures <strong>disease burden</strong> → useful for <strong>planning</strong> health services.</li>\n<li>Studies <strong>several exposures and outcomes</strong> at once.</li>\n<li>No follow-up or loss to follow-up.</li>\n<li>Generates <strong>hypotheses</strong>.</li>\n<li>Good for chronic diseases and risk factor surveys (NCD STEPS, BDHS).</li>\n</ol>\n<p><strong>Disadvantages</strong></p>\n<p>Cannot establish temporal sequence or causation; not suited to rare or short diseases; prevalence–incidence bias.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.559","n":559,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is the importance of longitudinal studies?</p>","a":"<p><strong>Importance of longitudinal studies</strong></p>\n<ol>\n<li>Study the <strong>natural history</strong> of disease.</li>\n<li>Measure <strong>incidence</strong> and changes over time.</li>\n<li>Identify <strong>risk factors</strong> and their temporal relation to disease.</li>\n<li>Study <strong>growth and development</strong> of children, ageing.</li>\n<li>Assess <strong>prognosis</strong> and outcomes.</li>\n<li>Evaluate long-term effects of interventions and exposures.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.560","n":560,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["25M","20Nov","18Nov","17Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between incidence rate and prevalence rate.</p>","a":"<p><strong>Incidence vs prevalence</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Incidence rate</th>\n<th>Prevalence rate</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Definition</td>\n<td>Number of <strong>new cases</strong> occurring in a defined population during a specified period</td>\n<td>Number of <strong>all current cases (old + new)</strong> in a population at a point or during a period</td>\n</tr>\n<tr>\n<td>Formula</td>\n<td>(New cases during period ÷ population at risk) × 1,000</td>\n<td>(All existing cases ÷ total population) × 1,000 / 100</td>\n</tr>\n<tr>\n<td>Measures</td>\n<td><strong>Risk</strong> of developing disease</td>\n<td><strong>Burden</strong> of disease</td>\n</tr>\n<tr>\n<td>Time</td>\n<td>Always over a period</td>\n<td>At a point (point prevalence) or period (period prevalence)</td>\n</tr>\n<tr>\n<td>Affected by</td>\n<td>Causes / risk factors</td>\n<td>Incidence and <strong>duration</strong> (P = I × D)</td>\n</tr>\n<tr>\n<td>Useful for</td>\n<td><strong>Acute diseases</strong>; aetiology; evaluating prevention</td>\n<td><strong>Chronic diseases</strong>; planning services</td>\n</tr>\n<tr>\n<td>Obtained by</td>\n<td>Cohort studies</td>\n<td>Cross-sectional studies</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>New TB cases in 2024</td>\n<td>All TB patients on a given day</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.561","n":561,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Distinguish between point prevalence and period prevalence.</p>","a":"<p><strong>Point vs period prevalence</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Point prevalence</th>\n<th>Period prevalence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Definition</td>\n<td>All current cases (old and new) <strong>at a given point in time</strong></td>\n<td>All current cases (old and new) existing <strong>during a given period</strong> (e.g., a year)</td>\n</tr>\n<tr>\n<td>Formula</td>\n<td>(Cases at a point ÷ population at that point) × 100</td>\n<td>(Cases during period ÷ mid-period population) × 100</td>\n</tr>\n<tr>\n<td>Includes</td>\n<td>Cases present on that day</td>\n<td>Cases present at start + new cases during the period</td>\n</tr>\n<tr>\n<td>Relation</td>\n<td>—</td>\n<td>Period prevalence = point prevalence at start + incidence during period</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>TB patients on 1 January 2026</td>\n<td>All TB patients during 2026</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.562","n":562,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is randomization?</p>","a":"<p><strong>Randomisation</strong></p>\n<p>A statistical procedure by which participants are <strong>allocated to study and control groups by chance</strong> (e.g., random number tables, computer), so each has an <strong>equal chance</strong> of being in either group.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.563","n":563,"part":10,"topic":"Basic Principles of Epidemiology","stars":3,"years":["26M","22Nov","19M"],"colleges":"DMC (1st Assess D5); SSMC (1st Supp B5); ShSMC (1st Term B4); MuMC (1st Final C5, 1st Supp C4)","asked":"steps of investigation of the recent measles outbreak; U1C5/V1C4 asked as: investigating a measles outbreak in a rural community of Barisal","note":"","kind":"","sub":"","q":"<p>What are the steps of outbreak (epidemic) investigation in epidemiology?</p>","a":"<p><strong>Steps of outbreak (epidemic) investigation (Park)</strong></p>\n<ol>\n<li><strong>Verify the diagnosis</strong> (clinical examination, laboratory tests).</li>\n<li><strong>Confirm the existence of an epidemic</strong>: compare with usual frequency (expected numbers).</li>\n<li><strong>Define the population at risk</strong>: map the area, count the population (denominator).</li>\n<li><strong>Rapid search for all cases</strong> and their characteristics: case definition, line list (time, place, person).</li>\n<li><strong>Data analysis</strong>: by time (epidemic curve), place (spot map), person (age, sex, occupation) → attack rates.</li>\n<li><strong>Formulate hypotheses</strong> about source, mode of transmission.</li>\n<li><strong>Test hypotheses</strong> (analytical studies: case-control or cohort).</li>\n<li><strong>Evaluate ecological factors</strong> (water, food, vectors, sanitation).</li>\n<li><strong>Further investigation</strong> of population at risk (screening, serology).</li>\n<li><strong>Writing the report</strong> and dissemination.</li>\n</ol>\n<p><strong>Control measures</strong> start early and run alongside: treatment, isolation, source control (chlorination), health education, vaccination; continued <strong>surveillance</strong> to confirm end of epidemic.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.564","n":564,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"DMC (1st Assess A4)","asked":"","note":"","kind":"","sub":"","q":"<p>What types of information are typically collected in descriptive studies?</p>","a":"<p><strong>Information collected in descriptive studies</strong></p>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Information</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Time</strong></td>\n<td>Date of onset, season, trend over years, epidemic curve</td>\n</tr>\n<tr>\n<td><strong>Place</strong></td>\n<td>Residence, area, urban/rural, country; spot maps</td>\n</tr>\n<tr>\n<td><strong>Person</strong></td>\n<td>Age, sex, marital status, occupation, education, social class, ethnicity, religion, behaviour (smoking, diet), migration, family size</td>\n</tr>\n<tr>\n<td><strong>Disease</strong></td>\n<td>Case definition, frequency (incidence, prevalence), severity, outcome</td>\n</tr>\n<tr>\n<td><strong>Exposure / environment</strong></td>\n<td>Water, food, housing, sanitation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.565","n":565,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"DMC (1st Assess A5)","asked":"","note":"","kind":"","sub":"","q":"<p>In Bangladesh, 1000 new and 5000 old TB cases were detected in 2024. The total population of Dhaka is about 70,00000 at the same time. What is the prevalence and incidence of TB during the year 2024? [3.5+3.5]</p>","a":"<p><strong>Given</strong></p>\n<p>New TB cases in 2024 = 1,000; old cases = 5,000; population = 7,000,000.</p>\n<p><strong>a) Prevalence (period prevalence) in 2024 (3.5)</strong></p>\n<p>Prevalence = (All cases, old + new ÷ population) × 100,000<br />\n= (6,000 ÷ 7,000,000) × 100,000 = <strong>85.7 per 100,000 population</strong> (0.086%)</p>\n<p><strong>b) Incidence in 2024 (3.5)</strong></p>\n<p>Incidence = (New cases during the year ÷ population at risk) × 100,000<br />\n= (1,000 ÷ 7,000,000) × 100,000 = <strong>14.3 per 100,000 population per year</strong></p>\n<p>(Strictly, the population at risk excludes existing cases: 7,000,000 − 5,000 = 6,995,000 → incidence ≈ 14.3 per 100,000; practically unchanged.)</p>\n<p><strong>Interpretation</strong></p>\n<p>Prevalence (≈86) is about 6 times incidence (≈14) because TB is a chronic disease with long duration (P ≈ I × D).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.566","n":566,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"ShSMC (1st Term B1)","asked":"","note":"","kind":"","sub":"","q":"<p>Explain the relationship between incidence, prevalence and duration of disease.</p>","a":"<p><strong>Relationship: P = I × D</strong></p>\n<p><strong>Prevalence = Incidence × mean Duration</strong> (when the disease is stable and prevalence is low).</p>\n<table>\n<thead>\n<tr>\n<th>Situation</th>\n<th>Effect on prevalence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Incidence ↑ (more new cases)</td>\n<td>Prevalence ↑</td>\n</tr>\n<tr>\n<td>Duration ↑ (chronic disease; better treatment that prolongs life without cure, e.g., ART for HIV, insulin for diabetes)</td>\n<td>Prevalence ↑</td>\n</tr>\n<tr>\n<td>Duration ↓ (rapid cure or rapid death)</td>\n<td>Prevalence ↓</td>\n</tr>\n<tr>\n<td>Incidence = prevalence</td>\n<td>Very short diseases</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Examples</strong></p>\n<ul>\n<li>Common cold: high incidence, short duration → low prevalence.</li>\n<li>Diabetes, TB: moderate incidence, long duration → high prevalence.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.567","n":567,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"ShSMC (1st Term B1)","asked":"","note":"","kind":"","sub":"","q":"<p>Define bias along with types and example. In what type of study is bias very common?</p>","a":"<p><strong>Bias</strong></p>\n<p>Any <strong>systematic error</strong> in the design, conduct or analysis of a study that produces a result <strong>different from the truth</strong>.</p>\n<p><strong>Types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Selection bias</strong></td>\n<td>Study groups not comparable or not representative</td>\n<td>Hospital controls differ from community</td>\n</tr>\n<tr>\n<td><strong>Information / measurement bias</strong></td>\n<td>Error in measuring exposure or outcome</td>\n<td>Faulty BP machine</td>\n</tr>\n<tr>\n<td><strong>Recall bias</strong></td>\n<td>Cases remember past exposures better than controls</td>\n<td>Mothers of malformed babies recall drug use more</td>\n</tr>\n<tr>\n<td><strong>Interviewer bias</strong></td>\n<td>Interviewer probes cases more</td>\n<td>Knowing who is a case</td>\n</tr>\n<tr>\n<td><strong>Berkesonian bias</strong></td>\n<td>Different hospital admission rates for cases and controls</td>\n<td>Hospital-based case-control</td>\n</tr>\n<tr>\n<td><strong>Confounding</strong></td>\n<td>Third factor distorts the association</td>\n<td>Age in smoking–CHD</td>\n</tr>\n<tr>\n<td>Loss to follow-up</td>\n<td>Drop-outs differ from those remaining</td>\n<td>Cohort studies</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Bias is very common in case-control studies</strong> (recall, selection and interviewer bias).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.568","n":568,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"ShSMC (1st Term B3)","asked":"","note":"","kind":"","sub":"","q":"<p>Give an example of confounding.</p>","a":"<p><strong>Confounding</strong></p>\n<p>A <strong>third variable</strong> associated with both the <strong>exposure</strong> and the <strong>outcome</strong> (and not on the causal path) that distorts the true association.</p>\n<p><strong>Example</strong></p>\n<p>Studying <strong>alcohol and lung cancer</strong>: alcohol drinkers are more often <strong>smokers</strong>; smoking causes lung cancer. So <strong>smoking is a confounder</strong> → alcohol appears to cause lung cancer.</p>\n<p>Alcohol → (associated with) Smoking → Lung cancer</p>\n<p><strong>Other examples</strong>: age in the relation between grey hair and CHD; coffee and CHD confounded by smoking.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.569","n":569,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"ShSMC (1st Term C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate relative risk, attributable risk &amp; population attributable risk.</p>","a":"<p><strong>Relative risk, attributable risk, population attributable risk</strong></p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Formula</th>\n<th>Meaning</th>\n<th>Use</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Relative risk (RR)</strong></td>\n<td>Incidence in exposed ÷ incidence in non-exposed</td>\n<td>How many <strong>times</strong> more likely the exposed are to get disease</td>\n<td><strong>Strength of association</strong> (aetiology)</td>\n</tr>\n<tr>\n<td><strong>Attributable risk (AR)</strong></td>\n<td>Incidence in exposed − incidence in non-exposed (also as % of incidence in exposed)</td>\n<td>Amount of disease <strong>in the exposed</strong> due to the exposure</td>\n<td>Benefit of removing exposure <strong>for exposed individuals</strong></td>\n</tr>\n<tr>\n<td><strong>Population attributable risk (PAR)</strong></td>\n<td>Incidence in total population − incidence in non-exposed</td>\n<td>Amount of disease <strong>in the whole population</strong> due to the exposure</td>\n<td><strong>Public health impact</strong>; priority setting</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Example</strong>: lung cancer incidence 1.30/1,000 in smokers, 0.07/1,000 in non-smokers → RR ≈ 18.6; AR = 1.23/1,000 (≈95% of lung cancer in smokers is due to smoking).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.570","n":570,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"MuMC (1st Final B3, 1st Supp B2)","asked":"","note":"","kind":"","sub":"","q":"<p>To find out the incidence of lung cancer among the workers of a garments factory, which type of study will you suggest and why? [1+2.5]</p>","a":"<p><strong>Study design (1)</strong></p>\n<p><strong>Cohort (prospective) study</strong>.</p>\n<p><strong>Why (2.5)</strong></p>\n<ol>\n<li><strong>Incidence</strong> (new cases over time) can only be measured by following a disease-free group forward.</li>\n<li>Workers are a <strong>defined, accessible group</strong> with records → easy follow-up (occupational cohort).</li>\n<li>Exposure (dust, fumes, smoking) can be measured <strong>before</strong> cancer develops → clear temporal sequence.</li>\n<li>Allows comparison of <strong>exposed vs less exposed</strong> workers → relative and attributable risk.</li>\n<li>Can study <strong>several outcomes</strong> (lung cancer, COPD, TB).<br />\n(Limitation: long follow-up, costly; a historical cohort using past employment records can save time.)</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.571","n":571,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"SSMC (1st Supp D5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A study is conducted to find an association between betel nut chewing and oral cancer. [1+3+3]</p>\n<ul>\n<li>a) What will be the suitable study design?</li>\n<li>b) Interpret the measure of association.</li>\n<li>c) What are the advantages and limitations of this study?</li>\n</ul>","a":"<p><strong>a) Suitable study design (1)</strong></p>\n<p><strong>Case-control study</strong>: oral cancer patients (cases) and similar people without oral cancer (controls) compared for past betel nut chewing.</p>\n<p><strong>b) Measure of association: odds ratio (3)</strong></p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>Oral cancer (cases)</th>\n<th>No cancer (controls)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Chewers</td>\n<td>a</td>\n<td>b</td>\n</tr>\n<tr>\n<td>Non-chewers</td>\n<td>c</td>\n<td>d</td>\n</tr>\n</tbody>\n</table>\n<p><strong>OR = ad ÷ bc</strong></p>\n<table>\n<thead>\n<tr>\n<th>OR</th>\n<th>Interpretation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>No association</td>\n</tr>\n<tr>\n<td>&gt;1</td>\n<td>Betel nut chewing is a <strong>risk factor</strong> (e.g., OR = 4: chewers have about 4 times the odds of oral cancer)</td>\n</tr>\n<tr>\n<td>&lt;1</td>\n<td>Protective</td>\n</tr>\n</tbody>\n</table>\n<p>Significance judged by 95% confidence interval (excludes 1) or p-value.</p>\n<p><strong>c) Advantages and limitations (3)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Advantages</th>\n<th>Limitations</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Quick, cheap</td>\n<td><strong>Recall bias</strong> about chewing habits</td>\n</tr>\n<tr>\n<td>Few subjects</td>\n<td>Selection of comparable <strong>controls</strong> difficult</td>\n</tr>\n<tr>\n<td>Good for <strong>rare disease</strong> with long latency (oral cancer)</td>\n<td>Cannot measure incidence or RR directly</td>\n</tr>\n<tr>\n<td>Several exposures (tobacco, alcohol) studied together</td>\n<td><strong>Confounding</strong> (smoking, alcohol)</td>\n</tr>\n<tr>\n<td>No follow-up</td>\n<td>Temporal sequence less certain</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.572","n":572,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"ShSMC (1st Term C5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A pharmaceutical company developed a new antihypertensive drug. Researchers selected 400 hypertensive patients and randomly divided the patients into two groups where one group received the new drug and the other group received the standard drug. They were followed for about 6 months and then results were compared with both groups. [7]</p>\n<ul>\n<li>a) What type of study it was – justify it. (2)</li>\n<li>b) Mention the steps of conducting such particular study. (3)</li>\n<li>c) Mention two advantages &amp; disadvantages of such study. (2)</li>\n</ul>","a":"<p><strong>a) Type of study and justification (2)</strong></p>\n<p><strong>Randomised controlled trial (RCT)</strong>, an experimental (therapeutic) study:</p>\n<ol>\n<li>Investigator <strong>assigns the intervention</strong> (new vs standard drug).</li>\n<li><strong>Random allocation</strong> into two groups.</li>\n<li><strong>Control group</strong> (standard drug) for comparison.</li>\n<li><strong>Followed up</strong> for outcome (BP after 6 months).</li>\n</ol>\n<p><strong>b) Steps of an RCT (3)</strong></p>\n<ol>\n<li><strong>Drawing up a protocol</strong>: aims, criteria, outcomes, sample size, ethics.</li>\n<li><strong>Selecting reference and experimental populations</strong>; informed consent; inclusion/exclusion criteria.</li>\n<li><strong>Randomisation</strong> into study and control groups.</li>\n<li><strong>Manipulation / intervention</strong>: new drug vs standard drug.</li>\n<li><strong>Follow-up</strong> of both groups for the same period, same way.</li>\n<li><strong>Assessment of outcome</strong>: blood pressure, side effects; <strong>blinding</strong> (single, double, triple) to avoid bias.</li>\n<li><strong>Analysis and interpretation</strong>: compare outcomes; statistical tests.</li>\n</ol>\n<p><strong>c) Advantages and disadvantages (2)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Advantages</th>\n<th>Disadvantages</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Strongest evidence</strong> of cause-effect / efficacy</td>\n<td><strong>Costly</strong>, time-consuming</td>\n</tr>\n<tr>\n<td>Randomisation controls known and unknown confounders</td>\n<td><strong>Ethical</strong> limits; drop-outs</td>\n</tr>\n<tr>\n<td>Blinding reduces bias</td>\n<td>Results may not apply to general population (strict criteria)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.573","n":573,"part":10,"topic":"Basic Principles of Epidemiology","stars":0,"years":[],"colleges":"MuMC (1st Final B5, 1st Supp B4)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A public health scientist carried out a study to find out the risk factors associated with Chronic Heart Diseases. What type of study was it? Write down the cardinal features &amp; disadvantages of this study. What do you mean by OR=2? Write down 3 important differences between observational study &amp; experimental study. [1+3.5+1+1.5]</p>","a":"<p><strong>Type of study (1)</strong></p>\n<p><strong>Case-control study</strong> (analytical observational) to find risk factors: CHD cases compared with controls for past exposures.</p>\n<p><strong>Cardinal features (3.5)</strong></p>\n<ol>\n<li><strong>Both exposure and outcome have already occurred</strong> when the study starts.</li>\n<li>Proceeds <strong>from effect to cause</strong> (backward).</li>\n<li>Uses a <strong>control group</strong> to compare exposure.</li>\n<li>Measures <strong>odds ratio</strong>.</li>\n</ol>\n<p><strong>Disadvantages</strong></p>\n<p>Recall bias; selection bias; difficulty in choosing controls; confounding; cannot measure incidence or RR directly; temporal sequence uncertain.</p>\n<p><strong>OR = 2 (1)</strong></p>\n<p>The odds of exposure (e.g., smoking) among CHD cases are <strong>twice</strong> those among controls → the exposed have about <strong>2 times the risk</strong> of CHD (a positive association), if significant (95% CI excludes 1).</p>\n<p><strong>Observational vs experimental studies (1.5)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Observational</th>\n<th>Experimental</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Investigator <strong>observes</strong> naturally occurring exposures</td>\n<td>Investigator <strong>assigns</strong> the intervention</td>\n</tr>\n<tr>\n<td>No randomisation</td>\n<td><strong>Randomisation</strong></td>\n</tr>\n<tr>\n<td>More prone to bias and confounding</td>\n<td>Least biased; strongest evidence</td>\n</tr>\n<tr>\n<td>Fewer ethical problems</td>\n<td>Ethical limits</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.574","n":574,"part":10,"topic":"Infectious Disease Epidemiology","stars":3,"years":["24M","23Nov","18M","17M","16Ja","11Ja","10Ja","09Ja","08Ju","08Ja"],"colleges":"SSMC (1st Supp B5); ShSMC (1st Term B4); MMC (1st Supp C2); MuMC (1st Final C5, 1st Supp C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Define epidemic. Classify epidemic / types of epidemic with examples and figure.</p>","a":"<p><strong>Epidemic</strong></p>\n<p>The occurrence in a community or region of cases of an illness (or other health-related events) <strong>clearly in excess of normal expectancy</strong>.</p>\n<p><strong>Types of epidemics (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Features</th>\n<th>Examples</th>\n<th>Epidemic curve</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Common-source epidemic</strong></td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>(a) Single exposure (&quot;point source&quot;)</td>\n<td>All exposed at one time; cases within one incubation period; no secondary cases</td>\n<td>Food poisoning, Bhopal gas leak</td>\n<td>Sharp rise and fall (single peak)</td>\n</tr>\n<tr>\n<td>(b) Continuous or multiple exposure</td>\n<td>Exposure continues over time</td>\n<td>Contaminated well, Legionnaires' disease</td>\n<td>Rises, plateau, falls when source removed</td>\n</tr>\n<tr>\n<td><strong>2. Propagated epidemic</strong></td>\n<td>Person-to-person spread; gradual rise; continues until susceptibles exhausted</td>\n<td>Hepatitis A, polio, measles; vector-borne (dengue); animal reservoir</td>\n<td>Several successive peaks, longer duration</td>\n</tr>\n<tr>\n<td><strong>3. Slow (modern) epidemics</strong></td>\n<td>Gradual rise over years</td>\n<td>CHD, lung cancer, diabetes</td>\n<td>Long secular trend</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Figure (epidemic curves)</strong></p>\n<pre><code>Point source:       Propagated:          Continuous:\n   ▁▃█▆▃▁            ▁▂▃▅▆▇▆▅▃▂▁▁         ▁▃▆██████▆▃▁\n (one IP)          (successive waves)    (plateau)\n</code></pre>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.575","n":575,"part":10,"topic":"Infectious Disease Epidemiology","stars":3,"years":["22Nov","21M"],"colleges":"SSMC (1st Supp B5); ShSMC (1st Term B4); MuMC (1st Final C5, 1st Supp C4)","asked":"","note":"","kind":"","sub":"","q":"<p>How does endemic vary from pandemic? Differentiate epidemic from pandemic.</p>","a":"<p><strong>Endemic, epidemic and pandemic</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Endemic</th>\n<th>Epidemic</th>\n<th>Pandemic</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Meaning</td>\n<td><strong>Constant presence</strong> (usual level) of a disease in a geographic area or population without importation</td>\n<td>Cases <strong>clearly in excess of normal expectancy</strong> in a community or region</td>\n<td>An epidemic spreading over <strong>several countries or continents</strong>, affecting large numbers</td>\n</tr>\n<tr>\n<td>Frequency</td>\n<td>Usual, expected</td>\n<td>Unusual rise</td>\n<td>Unusual, worldwide</td>\n</tr>\n<tr>\n<td>Area</td>\n<td>Localised</td>\n<td>Community / region</td>\n<td>Global / multi-country</td>\n</tr>\n<tr>\n<td>Duration</td>\n<td>Continuous</td>\n<td>Limited period</td>\n<td>Variable (months–years)</td>\n</tr>\n<tr>\n<td>Examples (Bangladesh)</td>\n<td>Kala-azar (previously), typhoid, hepatitis E, TB</td>\n<td>Dengue outbreaks, cholera, measles (2026)</td>\n<td>COVID-19 (2020), influenza H1N1 (2009)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.576","n":576,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":["04M"],"colleges":"ShSMC (1st Term C3)","asked":"","note":"","kind":"","sub":"","q":"<p>What is infection chain?</p>","a":"<p><strong>Infection chain (chain of infection)</strong></p>\n<p>The sequence of links needed for transmission of an infection:</p>\n<p>Infectious agent → Reservoir / source → Portal of exit → Mode of transmission → Portal of entry → Susceptible host</p>\n<p>Simplified (Park): <strong>Source or reservoir → Mode of transmission → Susceptible host</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.577","n":577,"part":10,"topic":"Infectious Disease Epidemiology","stars":3,"years":["16Ju","14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is nosocomial infection?</p>","a":"<p><strong>Nosocomial (hospital-acquired / health care-associated) infection</strong></p>\n<p>An infection <strong>acquired in a hospital or health-care facility</strong> that was <strong>not present or incubating at admission</strong>; usually appears <strong>≥48 hours after admission</strong> (or after discharge, e.g., within 30 days of surgery). Also affects staff.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.578","n":578,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define and classify carriers.</p>","a":"<p><strong>Carrier</strong></p>\n<p>An infected person (or animal) who <strong>harbours a specific infectious agent without discernible clinical disease</strong> and serves as a <strong>potential source of infection</strong> to others.</p>\n<p><strong>Classification (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Type</strong></td>\n<td><strong>Incubatory</strong> (shed during incubation period)</td>\n<td>Measles, mumps, polio, diphtheria</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Convalescent</strong> (shed during convalescence)</td>\n<td>Typhoid, cholera, diphtheria, dysentery</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Healthy</strong> (subclinical infection, no illness)</td>\n<td>Polio, meningococcus, cholera, diphtheria</td>\n</tr>\n<tr>\n<td><strong>Duration</strong></td>\n<td><strong>Temporary</strong> (short time)</td>\n<td>Most</td>\n</tr>\n<tr>\n<td></td>\n<td><strong>Chronic</strong> (long time)</td>\n<td>Typhoid, hepatitis B, malaria</td>\n</tr>\n<tr>\n<td><strong>Portal of exit</strong></td>\n<td>Urinary, intestinal, respiratory, nasal, skin</td>\n<td>Typhoid (urinary, intestinal), staphylococci (nasal)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.579","n":579,"part":10,"topic":"Infectious Disease Epidemiology","stars":3,"years":["16Nov","15Ja","06Ja"],"colleges":"ShSMC (1st Term C3)","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the routes (modes) of transmission of infectious disease (direct modes).</p>","a":"<p><strong>Modes of transmission of infectious diseases (Park)</strong></p>\n<p><strong>A. Direct transmission</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Direct contact</strong> (skin-to-skin, mucosa-to-mucosa, kissing, sexual contact)</td>\n<td>STIs, HIV, scabies, leprosy, skin infections</td>\n</tr>\n<tr>\n<td><strong>2. Droplet infection</strong> (spray of droplets during coughing, sneezing, talking; within ~1 m)</td>\n<td>Measles, influenza, COVID-19, diphtheria, pertussis, TB (also airborne)</td>\n</tr>\n<tr>\n<td><strong>3. Contact with soil</strong></td>\n<td>Hookworm, tetanus, mycoses</td>\n</tr>\n<tr>\n<td><strong>4. Inoculation into skin or mucosa</strong></td>\n<td>Rabies (bite), hepatitis B (needle)</td>\n</tr>\n<tr>\n<td><strong>5. Transplacental (vertical)</strong></td>\n<td>Rubella, syphilis, HIV, toxoplasmosis, hepatitis B</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Indirect transmission</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Vehicle-borne</strong> (water, food, milk, blood, ice)</td>\n<td>Cholera, typhoid, hepatitis A/E, hepatitis B (blood)</td>\n</tr>\n<tr>\n<td><strong>2. Vector-borne</strong> (mechanical, biological)</td>\n<td>Malaria, dengue, kala-azar, plague</td>\n</tr>\n<tr>\n<td><strong>3. Airborne</strong> (droplet nuclei, dust)</td>\n<td>TB, measles, chickenpox, influenza</td>\n</tr>\n<tr>\n<td><strong>4. Fomite-borne</strong> (towels, utensils, toys, clothes)</td>\n<td>Diphtheria, typhoid, skin infections, trachoma</td>\n</tr>\n<tr>\n<td><strong>5. Unclean hands and fingers</strong></td>\n<td>Shigellosis, typhoid, hepatitis A, threadworm</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.580","n":580,"part":10,"topic":"Infectious Disease Epidemiology","stars":3,"years":["23Nov","18Nov","17Nov"],"colleges":"DMC (1st Assess D3)","asked":"","note":"","kind":"","sub":"","q":"<p>Differentiate between isolation and quarantine.</p>","a":"<p><strong>Isolation vs quarantine</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Isolation</th>\n<th>Quarantine</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Who</td>\n<td><strong>Infected</strong> (sick) persons or animals</td>\n<td><strong>Well (healthy) persons</strong> or animals <strong>exposed</strong> to a communicable disease</td>\n</tr>\n<tr>\n<td>Definition (Park)</td>\n<td>Separation, for the <strong>period of communicability</strong>, of infected persons from others, to prevent or limit transmission</td>\n<td>Limitation of freedom of movement of exposed well persons for a period <strong>not longer than the longest usual incubation period</strong></td>\n</tr>\n<tr>\n<td>Duration</td>\n<td>Period of communicability</td>\n<td>Longest incubation period of the disease</td>\n</tr>\n<tr>\n<td>Purpose</td>\n<td>Prevent spread from a known case</td>\n<td>Prevent spread if the exposed person becomes infected</td>\n</tr>\n<tr>\n<td>Types</td>\n<td>Standard, contact, droplet, airborne isolation; strict isolation; home isolation; cohort isolation</td>\n<td><strong>Absolute (complete)</strong> quarantine; <strong>modified</strong> quarantine (selective restriction, e.g., exclusion of children from school); <strong>segregation</strong> (separating a group)</td>\n</tr>\n<tr>\n<td>Examples</td>\n<td>TB patient in a negative-pressure room; COVID-19 patient</td>\n<td>Contacts of COVID-19 or Ebola cases; travellers from yellow-fever areas without vaccination (6 days)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.581","n":581,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What is first contact case?</p>","a":"<p><strong>Case terms in an outbreak</strong></p>\n<table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primary case</strong></td>\n<td>The <strong>first case</strong> of a communicable disease introduced into a population unit (family, school, community)</td>\n</tr>\n<tr>\n<td><strong>Index case</strong> (&quot;first contact case&quot;)</td>\n<td>The first case to <strong>come to the attention of the investigator / health system</strong>; not always the primary case</td>\n</tr>\n<tr>\n<td><strong>Secondary cases</strong></td>\n<td>Cases that develop from <strong>contact with the primary case</strong> within the range of one incubation period</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.582","n":582,"part":10,"topic":"Infectious Disease Epidemiology","stars":3,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Discuss the emergency preparedness and response programme in outbreak and pandemic situation in Bangladesh.</p>","a":"<p><strong>Emergency preparedness and response for outbreaks and pandemics in Bangladesh</strong></p>\n<p><strong>A. Institutions and coordination</strong></p>\n<ol>\n<li><strong>MOHFW / DGHS</strong>: Disease Control Division; <strong>Health Emergency Operations Centre and Control Room</strong>.</li>\n<li><strong>IEDCR</strong>: national surveillance, outbreak investigation, laboratory, IHR focal point.</li>\n<li>National, divisional, district and upazila <strong>rapid response teams (RRTs)</strong>.</li>\n<li>Multisectoral committees (health, livestock, environment: <strong>One Health</strong>); Disaster Management Act 2012.</li>\n<li>Partners: WHO, UNICEF, icddr,b, NGOs.</li>\n</ol>\n<p><strong>B. Preparedness</strong></p>\n<ol>\n<li><strong>Surveillance</strong>: indicator-based (DHIS2), event-based, sentinel (influenza, Nipah), laboratory networks, genomic surveillance.</li>\n<li><strong>Preparedness plans</strong> (pandemic influenza, COVID-19 response plan); simulation exercises.</li>\n<li><strong>Stockpiles</strong>: PPE, drugs, vaccines, test kits, oxygen.</li>\n<li><strong>Points of entry</strong> screening (airports, land ports, seaports) under IHR.</li>\n<li>Hospital preparedness: isolation wards, ICU, infection control.</li>\n<li>Training of health workers; risk communication plans.</li>\n</ol>\n<p><strong>C. Response</strong></p>\n<ol>\n<li>Early detection and <strong>verification</strong>; outbreak investigation.</li>\n<li><strong>Case management</strong>; isolation, quarantine, contact tracing.</li>\n<li><strong>Risk communication</strong> and community engagement (hotlines, media).</li>\n<li><strong>Mass vaccination</strong> (COVID-19, OCV, MR campaigns).</li>\n<li>Vector control (dengue); WASH (cholera).</li>\n<li>Coordination, logistics, data dashboards.</li>\n</ol>\n<p><strong>D. Recovery and learning</strong></p>\n<p>After-action reviews; strengthening health systems; research.</p>\n<p><strong>Challenges</strong></p>\n<p>Workforce gaps, lab capacity outside Dhaka, private-sector coordination, funding, misinformation.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology; International Health).</p>"},{"id":"DU.583","n":583,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":[],"colleges":"DMC (1st Assess C2)","asked":"","note":"","kind":"","sub":"","q":"<p>Briefly describe the mode of interruption of disease transmission.</p>","a":"<p><strong>Interruption of transmission (by mode)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Water-borne</td>\n<td>Purification (chlorination), safe sources</td>\n</tr>\n<tr>\n<td>Food-borne</td>\n<td>Food hygiene, pasteurisation, cooking, healthy food handlers</td>\n</tr>\n<tr>\n<td>Air-borne / droplet</td>\n<td>Ventilation, masks, cough etiquette, avoiding crowding</td>\n</tr>\n<tr>\n<td>Vector-borne</td>\n<td>Vector control, bed nets, repellents</td>\n</tr>\n<tr>\n<td>Contact / sexual</td>\n<td>Personal hygiene, condoms, safe practices</td>\n</tr>\n<tr>\n<td>Fomites</td>\n<td>Disinfection, sterilisation</td>\n</tr>\n<tr>\n<td>Hands</td>\n<td>Hand-washing with soap</td>\n</tr>\n<tr>\n<td>Blood / needles</td>\n<td>Safe blood, sterile and AD syringes</td>\n</tr>\n<tr>\n<td>Mother-to-child</td>\n<td>PMTCT, screening in pregnancy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>General</strong>: environmental sanitation, health education.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.584","n":584,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":[],"colleges":"DMC (1st Assess D3)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the importance of incubation period.</p>","a":"<p><strong>Importance of incubation period</strong></p>\n<ol>\n<li><strong>Tracing the source</strong> of infection and contacts.</li>\n<li><strong>Period of surveillance / quarantine</strong> of contacts = maximum incubation period.</li>\n<li><strong>Immunisation</strong>: passive or active immunisation during the IP can prevent or modify disease (measles vaccine within 72 hours, rabies PEP).</li>\n<li><strong>Identifying point-source epidemics</strong>: all cases within one IP → common source.</li>\n<li><strong>Prognosis</strong>: short IP often means severe disease (tetanus, rabies).</li>\n<li>Planning isolation and control measures; estimating time of exposure.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.585","n":585,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":[],"colleges":"DMC (1st Assess D5)","asked":"","note":"","kind":"","sub":"","q":"<p>What are the differences between outbreak and epidemic?</p>","a":"<p><strong>Outbreak vs epidemic</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Outbreak</th>\n<th>Epidemic</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Extent</td>\n<td><strong>Localised</strong> increase (village, school, hospital)</td>\n<td>Larger area or population</td>\n</tr>\n<tr>\n<td>Size</td>\n<td>Usually small number of cases</td>\n<td>Larger numbers</td>\n</tr>\n<tr>\n<td>Onset</td>\n<td>Sudden</td>\n<td>May be sudden or gradual</td>\n</tr>\n<tr>\n<td>Use of term</td>\n<td>Often used for a limited epidemic (less alarming)</td>\n<td>Wider public health event</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Food poisoning at a wedding</td>\n<td>Dengue epidemic in Dhaka</td>\n</tr>\n</tbody>\n</table>\n<p>Both mean cases in excess of normal expectancy; terms often used interchangeably.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.586","n":586,"part":10,"topic":"Infectious Disease Epidemiology","stars":0,"years":[],"colleges":"ShSMC (2nd Term D1)","asked":"","note":"","kind":"","sub":"","q":"<p>Mention three factors responsible for emergence of infectious diseases.</p>","a":"<p><strong>Three factors responsible for emergence of infectious diseases</strong></p>\n<ol>\n<li><strong>Microbial adaptation and change</strong>: mutation, genetic reassortment (influenza), antimicrobial resistance.</li>\n<li><strong>Ecological and environmental change</strong>: deforestation, climate change, urbanisation, closer human–animal contact (Nipah, avian influenza).</li>\n<li><strong>Human demographics, travel and trade</strong>: population growth, crowding, international travel, food trade.</li>\n</ol>\n<p><strong>Others</strong>: breakdown of public health measures, war and famine, poverty, new technology (blood transfusion, organ transplant).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.587","n":587,"part":11,"topic":"Communicable Diseases","stars":3,"years":["18M","04M/J"],"colleges":"","asked":"","note":"","kind":"","sub":"General","q":"<p>Mention the measures for prevention and control of communicable diseases. / Enumerate the principles for prevention and control of a communicable disease.</p>","a":"<p><strong>Prevention and control of communicable diseases (Park)</strong></p>\n<p><strong>1. Controlling the reservoir</strong></p>\n<table>\n<thead>\n<tr>\n<th>Measure</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Early diagnosis</td>\n<td>Clinical and laboratory; screening</td>\n</tr>\n<tr>\n<td><strong>Notification</strong></td>\n<td>To health authority</td>\n</tr>\n<tr>\n<td>Epidemiological investigation</td>\n<td>Source, spread</td>\n</tr>\n<tr>\n<td><strong>Isolation</strong></td>\n<td>Of cases during communicability</td>\n</tr>\n<tr>\n<td><strong>Treatment</strong></td>\n<td>Cure cases and carriers (e.g., TB, malaria)</td>\n</tr>\n<tr>\n<td><strong>Quarantine</strong></td>\n<td>Of exposed contacts</td>\n</tr>\n<tr>\n<td>Disinfection</td>\n<td>Concurrent and terminal</td>\n</tr>\n<tr>\n<td>Animal reservoir control</td>\n<td>Vaccinating dogs, rodent control, slaughter of infected animals</td>\n</tr>\n</tbody>\n</table>\n<p><strong>2. Interruption of transmission</strong></p>\n<p>Water purification, food hygiene, environmental sanitation, vector control, personal hygiene, safe sex, disinfection, hand-washing.</p>\n<p><strong>3. Protection of susceptible host</strong></p>\n<ol>\n<li><strong>Active immunisation</strong> (vaccines).</li>\n<li><strong>Passive immunisation</strong> (immunoglobulins).</li>\n<li>Combined active and passive (rabies, tetanus).</li>\n<li><strong>Chemoprophylaxis</strong> (cholera contacts, malaria travellers, TB preventive therapy).</li>\n<li>Non-specific measures: nutrition, health education, better housing.</li>\n</ol>\n<p><strong>4. Surveillance and health education</strong> (throughout)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.588","n":588,"part":11,"topic":"Communicable Diseases","stars":2,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"General","q":"<p>Discuss different aspects of infectious disease control measures in context of Bangladesh.</p>","a":"<p><strong>Aspects of infectious disease control in Bangladesh</strong></p>\n<ol>\n<li><strong>Surveillance</strong>: IEDCR, DHIS2, AFP/measles, dengue, Nipah, influenza sentinel sites.</li>\n<li><strong>Immunisation (EPI)</strong>; supplementary campaigns.</li>\n<li><strong>Disease programmes</strong>: TB (DOTS, GeneXpert), malaria (hill tracts), kala-azar and filariasis (eliminated as PH problems, 2023), leprosy, HIV.</li>\n<li><strong>WASH</strong>: safe water, arsenic-safe options, sanitation, hygiene.</li>\n<li><strong>Vector control</strong>: dengue (city corporations), malaria (nets).</li>\n<li><strong>Case management</strong>: ORS, zinc, IMCI, antibiotics.</li>\n<li><strong>Outbreak response</strong> and IHR; One Health.</li>\n<li><strong>Research</strong> (icddr,b).</li>\n<li>Health education and community participation.</li>\n</ol>\n<p><strong>Challenges</strong>: AMR, urban dengue, measles coverage gaps (2026 outbreak), Rohingya camps, workforce and lab gaps.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.589","n":589,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"General","q":"<p>Differentiate between communicable and non-communicable diseases.</p>","a":"<p><strong>Communicable vs non-communicable diseases</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Communicable diseases</th>\n<th>Non-communicable diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cause</td>\n<td><strong>Specific infectious agent</strong> (or its toxins)</td>\n<td>Usually <strong>multifactorial</strong>; no single agent</td>\n</tr>\n<tr>\n<td>Transmission</td>\n<td>From person, animal or environment to person</td>\n<td><strong>Not transmitted</strong></td>\n</tr>\n<tr>\n<td>Onset</td>\n<td>Usually <strong>acute</strong></td>\n<td>Usually <strong>gradual, chronic</strong></td>\n</tr>\n<tr>\n<td>Incubation / latency</td>\n<td>Incubation period (days–weeks)</td>\n<td>Long latent period (years)</td>\n</tr>\n<tr>\n<td>Duration</td>\n<td>Usually short</td>\n<td>Long, lifelong</td>\n</tr>\n<tr>\n<td>Epidemiological model</td>\n<td>Agent–host–environment triad</td>\n<td><strong>Web of causation</strong>; risk factors</td>\n</tr>\n<tr>\n<td>Prevention</td>\n<td>Vaccines, sanitation, vector control, treatment</td>\n<td>Lifestyle change, screening, risk-factor control</td>\n</tr>\n<tr>\n<td>Iceberg</td>\n<td>Large subclinical part in many</td>\n<td>Large undiagnosed part (hypertension, diabetes)</td>\n</tr>\n<tr>\n<td>Disease pattern</td>\n<td>Common in poorer settings</td>\n<td>Rising with ageing, urbanisation</td>\n</tr>\n<tr>\n<td>Examples</td>\n<td>TB, cholera, dengue, measles</td>\n<td>Hypertension, diabetes, CHD, cancer, COPD</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases; Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.590","n":590,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25Nov","23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"General","q":"<p>Interpret / differentiate between emerging and re-emerging diseases with examples.</p>","a":"<p><strong>Emerging vs re-emerging diseases</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Emerging</th>\n<th>Re-emerging</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Definition (WHO)</td>\n<td><strong>Newly appeared</strong> in a population, or existed before but <strong>rapidly increasing</strong> in incidence or geographic range</td>\n<td>Diseases that were <strong>once declining or controlled</strong> but are <strong>increasing again</strong></td>\n</tr>\n<tr>\n<td>Causes</td>\n<td>New pathogens, spill-over from animals, ecological change</td>\n<td>Drug resistance, vector resistance, breakdown of control programmes, falling vaccine coverage, war, climate change</td>\n</tr>\n<tr>\n<td>Examples (global)</td>\n<td>HIV/AIDS, SARS, MERS, <strong>COVID-19</strong>, avian influenza H5N1, Zika, Ebola (new areas), mpox</td>\n<td><strong>TB (MDR-TB)</strong>, malaria, cholera, dengue, diphtheria, measles</td>\n</tr>\n<tr>\n<td>Examples (Bangladesh)</td>\n<td><strong>Nipah</strong> (first outbreak 2001), avian influenza, COVID-19, chikungunya (2017)</td>\n<td><strong>Dengue</strong> (large urban epidemics), <strong>measles</strong> (2026 outbreak), diphtheria (Rohingya camps, 2017), MDR-TB</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.591","n":591,"part":11,"topic":"Communicable Diseases","stars":3,"years":["19M"],"colleges":"","asked":"","note":"","kind":"","sub":"Chickenpox (Varicella-Zoster)","q":"<p>Mention the epidemiology of chickenpox.</p>","a":"<p><strong>Epidemiology of chickenpox (varicella)</strong></p>\n<p><strong>A. Agent factors</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Agent</td>\n<td><strong>Varicella-zoster virus</strong> (VZV, human herpesvirus 3); same virus causes herpes zoster</td>\n</tr>\n<tr>\n<td>Source of infection</td>\n<td><strong>Case</strong> of chickenpox (or herpes zoster); no carriers</td>\n</tr>\n<tr>\n<td>Infective material</td>\n<td><strong>Respiratory secretions</strong> and fluid of skin lesions; scabs are not infective</td>\n</tr>\n<tr>\n<td>Communicability</td>\n<td><strong>1–2 days before</strong> rash until <strong>all lesions are crusted</strong> (~5–6 days after rash)</td>\n</tr>\n<tr>\n<td>Secondary attack rate</td>\n<td>Very high (~90% in susceptible household contacts)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Host factors</strong></p>\n<ol>\n<li><strong>Age</strong>: mainly children &lt;10 years; more severe in adults, neonates, immunocompromised.</li>\n<li><strong>Immunity</strong>: one attack gives lifelong immunity; virus stays <strong>latent</strong> in dorsal root ganglia → may reactivate as <strong>herpes zoster</strong>.</li>\n<li>Pregnancy: risk of congenital varicella and severe maternal disease.</li>\n</ol>\n<p><strong>C. Environmental factors</strong></p>\n<p>Winter and spring; crowding (schools, hostels).</p>\n<p><strong>Mode of transmission</strong>: <strong>droplet and airborne</strong> spread; direct contact with lesions; transplacental.</p>\n<p><strong>Incubation period</strong>: <strong>14–16 days</strong> (range 10–21).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.592","n":592,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Chickenpox (Varicella-Zoster)","q":"<p>Mention the distinctive features of the rash of chickenpox.</p>","a":"<p><strong>Distinctive features of chickenpox rash</strong></p>\n<ol>\n<li><strong>Centripetal distribution</strong>: most dense on trunk; less on face and limbs; <strong>axillae involved</strong>.</li>\n<li>Palms and soles usually <strong>spared</strong>.</li>\n<li><strong>Rapid evolution</strong>: macule → papule → vesicle → crust within 24–48 hours.</li>\n<li><strong>Pleomorphism</strong>: lesions at <strong>different stages</strong> in the same area (successive <strong>crops</strong> over 3–4 days).</li>\n<li><strong>Superficial, unilocular vesicles</strong> (&quot;dew drops on a rose petal&quot;); collapse on puncture.</li>\n<li>Little surrounding inflammation; <strong>itchy</strong>.</li>\n<li><strong>Mucous membranes</strong> (mouth, conjunctiva) may be involved.</li>\n<li>Fever accompanies each crop.</li>\n<li>Scabs fall off in 1–2 weeks; usually <strong>no scar</strong> unless infected.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.593","n":593,"part":11,"topic":"Communicable Diseases","stars":2,"years":["12Ja","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Chickenpox (Varicella-Zoster)","q":"<p>Mention the clinical manifestations of chickenpox.</p>","a":"<p><strong>Clinical manifestations of chickenpox</strong></p>\n<ol>\n<li><strong>Prodromal stage</strong>: mild or absent in children; adults: fever, malaise, headache, anorexia for 1–2 days.</li>\n<li><strong>Eruptive stage</strong>:\n<ul>\n<li>Rash appears on day 1 of fever, first on the trunk.</li>\n<li>Successive crops of macules → papules → <strong>vesicles</strong> → crusts (pleomorphic).</li>\n<li><strong>Centripetal</strong> distribution; itching.</li>\n<li>Mucosal lesions in mouth.</li>\n</ul>\n</li>\n<li>Fever lasts as long as new crops appear (3–5 days).</li>\n<li>Crusts fall in 1–2 weeks.</li>\n<li>Severe in adults, neonates and immunocompromised (pneumonia, haemorrhagic lesions).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.594","n":594,"part":11,"topic":"Communicable Diseases","stars":2,"years":["23Nov","12Ja","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Chickenpox (Varicella-Zoster)","q":"<p>State the complications of chickenpox.</p>","a":"<p><strong>Complications of chickenpox</strong></p>\n<ol>\n<li><strong>Secondary bacterial skin infection</strong> (commonest): impetigo, cellulitis, abscess, necrotising fasciitis; scarring.</li>\n<li><strong>Varicella pneumonia</strong>: adults, pregnant women, immunocompromised; serious.</li>\n<li><strong>Neurological</strong>: encephalitis, <strong>cerebellar ataxia</strong>, Guillain–Barré syndrome.</li>\n<li><strong>Reye's syndrome</strong> (with aspirin use).</li>\n<li><strong>Haemorrhagic chickenpox</strong> (thrombocytopenia, DIC).</li>\n<li>Hepatitis, myocarditis, nephritis, arthritis.</li>\n<li><strong>Congenital varicella syndrome</strong> (maternal infection in first half of pregnancy): limb hypoplasia, skin scarring, eye and brain defects.</li>\n<li><strong>Neonatal varicella</strong> (mother's rash 5 days before to 2 days after delivery): severe, fatal.</li>\n<li>Later <strong>herpes zoster</strong> (reactivation).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.595","n":595,"part":11,"topic":"Communicable Diseases","stars":1,"years":["11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Chickenpox (Varicella-Zoster)","q":"<p>How can you prevent chickenpox?</p>","a":"<p><strong>Prevention of chickenpox</strong></p>\n<ol>\n<li><strong>Varicella vaccine</strong> (live attenuated): 2 doses (12–15 months and 4–6 years); susceptible adolescents and adults; post-exposure within 3–5 days.</li>\n<li><strong>Varicella-zoster immunoglobulin (VZIG)</strong> for high-risk exposed persons: immunocompromised, pregnant women without immunity, newborns of mothers with peripartum varicella.</li>\n<li><strong>Isolation</strong> of cases until all lesions are crusted; exclude from school.</li>\n<li>Avoid contact of cases with pregnant and immunocompromised people.</li>\n<li><strong>Acyclovir</strong> for high-risk patients; avoid aspirin.</li>\n<li>Health education; hygiene to prevent secondary infection.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.596","n":596,"part":11,"topic":"Communicable Diseases","stars":3,"years":["24M"],"colleges":"","asked":"","note":"","kind":"","sub":"Chickenpox (Varicella-Zoster)","q":"<p>Mention the complications of varicella-zoster virus infection.</p>","a":"<p><strong>Complications of varicella-zoster virus infection</strong></p>\n<p><strong>A. Chickenpox (primary infection)</strong></p>\n<p>Secondary bacterial skin infection; pneumonia; encephalitis, cerebellar ataxia; Reye's syndrome; haemorrhagic varicella; hepatitis; congenital varicella syndrome; neonatal varicella.</p>\n<p><strong>B. Herpes zoster (reactivation)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Complication</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Post-herpetic neuralgia</strong></td>\n<td>Pain persisting &gt;3 months; commonest, especially elderly</td>\n</tr>\n<tr>\n<td><strong>Herpes zoster ophthalmicus</strong></td>\n<td>Ophthalmic division of trigeminal nerve: keratitis, uveitis, vision loss</td>\n</tr>\n<tr>\n<td><strong>Ramsay Hunt syndrome</strong></td>\n<td>Facial palsy, ear vesicles, hearing loss, vertigo</td>\n</tr>\n<tr>\n<td>Disseminated zoster</td>\n<td>Immunocompromised (HIV, cancer)</td>\n</tr>\n<tr>\n<td>Motor neuropathy</td>\n<td>Limb or bladder weakness</td>\n</tr>\n<tr>\n<td>Encephalitis, myelitis, stroke (vasculopathy)</td>\n<td>Rare</td>\n</tr>\n<tr>\n<td>Secondary bacterial infection, scarring</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.597","n":597,"part":11,"topic":"Communicable Diseases","stars":3,"years":["17M","11Ju"],"colleges":"DMC (2nd Assess D1); MMC (2nd Term D3); MuMC (2nd Final B3)","asked":"","note":"","kind":"","sub":"Measles & Mumps","q":"<p>Mention the complications of measles.</p>","a":"<p><strong>Complications of measles</strong></p>\n<table>\n<thead>\n<tr>\n<th>System</th>\n<th>Complications</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Respiratory</strong></td>\n<td><strong>Pneumonia</strong> (viral or bacterial; commonest cause of death), laryngotracheobronchitis (croup), otitis media (commonest overall), bronchiolitis</td>\n</tr>\n<tr>\n<td><strong>Gastrointestinal</strong></td>\n<td><strong>Diarrhoea</strong> (persistent), stomatitis, appendicitis</td>\n</tr>\n<tr>\n<td><strong>Nutritional</strong></td>\n<td>Precipitates <strong>PEM / kwashiorkor</strong>; weight loss</td>\n</tr>\n<tr>\n<td><strong>Eye</strong></td>\n<td><strong>Xerophthalmia and keratitis → blindness</strong> (with vitamin A deficiency), conjunctivitis</td>\n</tr>\n<tr>\n<td><strong>Neurological</strong></td>\n<td>Febrile convulsions, <strong>encephalitis</strong> (~1/1,000), <strong>SSPE</strong> (years later)</td>\n</tr>\n<tr>\n<td><strong>Immunological</strong></td>\n<td>Immune suppression → flare-up of <strong>TB</strong>, secondary infections</td>\n</tr>\n<tr>\n<td>Others</td>\n<td>Myocarditis, thrombocytopenia; abortion and preterm birth in pregnancy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>High-risk groups</strong>: malnourished, vitamin A-deficient, infants, immunocompromised.</p>\n<p><strong>Prevention of complications</strong>: <strong>vitamin A</strong> to all measles cases; nutrition; early antibiotics for pneumonia; MR vaccination.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.598","n":598,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term D1)","asked":"","note":"","kind":"","sub":"Measles & Mumps","q":"<p>What is the public health significance of a measles case?</p>","a":"<p><strong>Public health significance of a single measles case</strong></p>\n<ol>\n<li><strong>Extremely contagious</strong> (R₀ 12–18): one case can start an outbreak.</li>\n<li>Signals an <strong>immunity gap</strong> (missed vaccination, low coverage, vaccine failure).</li>\n<li><strong>Notifiable</strong>; case-based <strong>surveillance</strong> with lab confirmation (IgM) for measles–rubella elimination.</li>\n<li>Triggers <strong>outbreak response</strong>: case investigation, contact tracing, isolation (4 days after rash), <strong>vitamin A</strong> to the case, vaccination of susceptibles in the area.</li>\n<li>High risk of death and complications in malnourished children.</li>\n<li>Indicator of <strong>EPI performance</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.599","n":599,"part":11,"topic":"Communicable Diseases","stars":3,"years":["26M","16M","13Ja","11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Measles & Mumps","q":"<p>Mention the complications of mumps / list three common complications of mumps.</p>","a":"<p><strong>Complications of mumps</strong></p>\n<table>\n<thead>\n<tr>\n<th>Complication</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Orchitis</strong></td>\n<td>Post-pubertal males (~20–30%); usually unilateral; rarely sterility</td>\n</tr>\n<tr>\n<td><strong>Oophoritis</strong>, mastitis</td>\n<td>Post-pubertal females</td>\n</tr>\n<tr>\n<td><strong>Aseptic meningitis</strong> / <strong>encephalitis</strong></td>\n<td>Headache, neck stiffness; usually benign</td>\n</tr>\n<tr>\n<td><strong>Pancreatitis</strong></td>\n<td>Abdominal pain, vomiting</td>\n</tr>\n<tr>\n<td><strong>Sensorineural deafness</strong></td>\n<td>Usually unilateral, may be permanent</td>\n</tr>\n<tr>\n<td>Others</td>\n<td>Myocarditis, thyroiditis, arthritis, nephritis; first-trimester abortion</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Three common</strong>: orchitis, meningitis (meningoencephalitis), pancreatitis.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.600","n":600,"part":11,"topic":"Communicable Diseases","stars":0,"years":["05Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Diphtheria & Pertussis","q":"<p>Discuss the important epidemiological features of diphtheria.</p>","a":"<p><strong>Epidemiology of diphtheria</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Agent</td>\n<td><em>Corynebacterium diphtheriae</em> (toxigenic strains: gravis, mitis, intermedius); exotoxin causes disease</td>\n</tr>\n<tr>\n<td>Source</td>\n<td><strong>Cases and carriers</strong> (carriers far more numerous; nasal carriers most dangerous)</td>\n</tr>\n<tr>\n<td>Infective material</td>\n<td>Nasopharyngeal secretions, discharges from skin lesions, contaminated fomites</td>\n</tr>\n<tr>\n<td>Communicability</td>\n<td>~2–4 weeks; carriers longer (until treated)</td>\n</tr>\n<tr>\n<td>Age</td>\n<td>Mainly <strong>1–5 years</strong> in unimmunised populations; shifts to older children and adults when coverage is high</td>\n</tr>\n<tr>\n<td>Immunity</td>\n<td>Antitoxic immunity from vaccination or infection; waning without boosters</td>\n</tr>\n<tr>\n<td>Environment</td>\n<td>Winter; overcrowding; poor hygiene; refugee camps</td>\n</tr>\n<tr>\n<td>Transmission</td>\n<td><strong>Droplet infection</strong>; direct contact; fomites</td>\n</tr>\n<tr>\n<td>Incubation period</td>\n<td><strong>2–6 days</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.601","n":601,"part":11,"topic":"Communicable Diseases","stars":0,"years":["07Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Diphtheria & Pertussis","q":"<p>How can you control diphtheria among cases and carriers?</p>","a":"<p><strong>Control of diphtheria in cases and carriers</strong></p>\n<p><strong>Cases</strong></p>\n<ol>\n<li>Early diagnosis; <strong>notification</strong>.</li>\n<li><strong>Isolation</strong> until two cultures (24 hours apart) are negative after antibiotics stop.</li>\n<li><strong>Diphtheria antitoxin</strong> (DAT) immediately on clinical suspicion (after sensitivity test).</li>\n<li><strong>Antibiotics</strong>: penicillin or erythromycin for 14 days (eradicates organism).</li>\n<li><strong>Active immunisation</strong> after recovery (illness does not always give immunity).</li>\n<li>Concurrent disinfection of discharges and articles.</li>\n</ol>\n<p><strong>Carriers</strong></p>\n<ol>\n<li><strong>Detection</strong> by throat and nasal swabs of contacts.</li>\n<li><strong>Treatment</strong>: erythromycin 7–10 days (or single benzathine penicillin); repeat swabs.</li>\n<li>Immunisation; exclusion from school or food handling until negative.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.602","n":602,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16M","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Diphtheria & Pertussis","q":"<p>What measures should be taken to control and prevent diphtheria (in a community)?</p>","a":"<p><strong>Control and prevention of diphtheria in a community</strong></p>\n<p><strong>A. Cases and carriers</strong> (see above): notification, isolation, antitoxin, antibiotics, detection and treatment of carriers.</p>\n<p><strong>B. Contacts</strong></p>\n<ol>\n<li>List all close contacts; <strong>throat swabs</strong> for culture.</li>\n<li><strong>Chemoprophylaxis</strong>: erythromycin 7–10 days or single IM benzathine penicillin.</li>\n<li><strong>Immunisation</strong>: booster (Td/DPT) if immunised before; start primary course if not.</li>\n<li><strong>Daily observation</strong> for 7 days.</li>\n</ol>\n<p><strong>C. Community</strong></p>\n<ol>\n<li><strong>Immunisation (most important)</strong>: pentavalent (DPT-HepB-Hib) at 6, 10, 14 weeks; boosters (Td) in school age and adults; <strong>mass vaccination campaigns</strong> in outbreaks.</li>\n<li><strong>Surveillance</strong>: early detection and lab confirmation.</li>\n<li>Reduce <strong>overcrowding</strong>; improve hygiene.</li>\n<li><strong>Health education</strong>.</li>\n<li>Ensure availability of <strong>antitoxin</strong> and antibiotics.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.603","n":603,"part":11,"topic":"Communicable Diseases","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Diphtheria & Pertussis","q":"<p>Mention the complications of diphtheria.</p>","a":"<p><strong>Complications of diphtheria</strong></p>\n<ol>\n<li><strong>Toxic myocarditis</strong> (1st–2nd week): arrhythmias, heart block, heart failure; commonest cause of death.</li>\n<li><strong>Neurological (toxic neuritis)</strong>: palatal palsy (3rd week; nasal regurgitation), ocular palsy (squint, blurred vision), limb and diaphragmatic paralysis.</li>\n<li><strong>Airway obstruction</strong> (laryngeal diphtheria) → asphyxia.</li>\n<li>Renal: nephritis.</li>\n<li>Secondary infection: bronchopneumonia, otitis media.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.604","n":604,"part":11,"topic":"Communicable Diseases","stars":1,"years":["11Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Diphtheria & Pertussis","q":"<p>What are the complications of pertussis?</p>","a":"<p><strong>Complications of pertussis (whooping cough)</strong></p>\n<ol>\n<li><strong>Respiratory</strong>: <strong>bronchopneumonia</strong> (commonest cause of death), atelectasis, emphysema, pneumothorax, otitis media, later bronchiectasis.</li>\n<li><strong>Due to raised pressure during coughing</strong>: subconjunctival haemorrhage, epistaxis, ulcer of tongue frenum, hernia, rectal prolapse.</li>\n<li><strong>Neurological</strong>: convulsions, <strong>encephalopathy</strong> (hypoxia).</li>\n<li><strong>Nutritional</strong>: malnutrition, dehydration (post-tussive vomiting).</li>\n<li>Apnoea in young infants; flare-up of TB.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.605","n":605,"part":11,"topic":"Communicable Diseases","stars":1,"years":["06M","05M"],"colleges":"","asked":"","note":"","kind":"","sub":"Diphtheria & Pertussis","q":"<p>Mention the clinical stages and complications of whooping cough.</p>","a":"<p><strong>Clinical stages of whooping cough (pertussis)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Duration</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Catarrhal</strong></td>\n<td>1–2 weeks</td>\n<td>Runny nose, mild cough, low fever; <strong>most infectious</strong> stage; hard to diagnose</td>\n</tr>\n<tr>\n<td><strong>2. Paroxysmal</strong></td>\n<td>2–4 weeks</td>\n<td>Bouts of rapid coughs followed by a <strong>whoop</strong> (deep inspiration), <strong>post-tussive vomiting</strong>, cyanosis, exhaustion; infants may have apnoea instead of whoop</td>\n</tr>\n<tr>\n<td><strong>3. Convalescent</strong></td>\n<td>Weeks to months</td>\n<td>Gradual decrease in cough; may recur with later respiratory infections</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Complications</strong>: bronchopneumonia, otitis media, convulsions, encephalopathy, subconjunctival haemorrhage, hernia, rectal prolapse, malnutrition.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.606","n":606,"part":11,"topic":"Communicable Diseases","stars":3,"years":["26M","24M","17M","16M"],"colleges":"DMC (2nd Assess D1); MuMC (2nd Final D3)","asked":"classify ARI among children on two distinct age groups","note":"","kind":"","sub":"ARI / Pneumonia","q":"<p>Classify ARI (according to WHO case management for children aged 2 months to 5 years).</p>","a":"<p><strong>WHO / IMCI classification of cough or difficult breathing (child 2 months–5 years)</strong></p>\n<p><strong>Assess</strong>: general danger signs (unable to drink or breastfeed, vomits everything, convulsions, lethargic or unconscious), <strong>respiratory rate</strong>, <strong>chest indrawing</strong>, <strong>stridor</strong> in a calm child, SpO₂ where available.</p>\n<p><strong>Fast breathing</strong>: 2–12 months ≥<strong>50/min</strong>; 12 months–5 years ≥<strong>40/min</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>Classification</th>\n<th>Signs</th>\n<th>Management</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Severe pneumonia or very severe disease</strong></td>\n<td>Any <strong>general danger sign</strong> or <strong>stridor</strong> in calm child (or SpO₂ &lt;90%)</td>\n<td>First dose of injectable antibiotic; <strong>refer urgently</strong>; keep warm, prevent hypoglycaemia</td>\n</tr>\n<tr>\n<td><strong>Pneumonia</strong></td>\n<td><strong>Fast breathing</strong> and/or <strong>chest indrawing</strong></td>\n<td><strong>Oral amoxicillin</strong> (5 days for chest indrawing; 3–5 days for fast breathing); home care; follow-up in 2–3 days</td>\n</tr>\n<tr>\n<td><strong>Cough or cold (no pneumonia)</strong></td>\n<td>No signs of pneumonia</td>\n<td>Home care; soothe throat; follow-up if not better in 5 days; return if fast breathing or danger signs; cough &gt;14 days → assess for TB, asthma</td>\n</tr>\n</tbody>\n</table>\n<p>(Earlier Park classification: very severe disease; severe pneumonia (chest indrawing); pneumonia (fast breathing); no pneumonia: cough or cold. WHO revised in 2014 so that chest indrawing pneumonia is treated with oral amoxicillin.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO, Revised classification and treatment of pneumonia in children, 2014.</p>"},{"id":"DU.607","n":607,"part":11,"topic":"Communicable Diseases","stars":3,"years":["20Nov"],"colleges":"MuMC (2nd Final D3)","asked":"classify ARI among children aged 0–2 months, with management","note":"","kind":"","sub":"ARI / Pneumonia","q":"<p>Classify pneumonia among infants under 2 months of age, with management.</p>","a":"<p><strong>Young infant (&lt;2 months): classification and management</strong></p>\n<p><strong>Signs of serious illness (possible serious bacterial infection, PSBI)</strong></p>\n<p>Not feeding well; convulsions; <strong>fast breathing ≥60/min</strong>; <strong>severe chest indrawing</strong>; fever ≥37.5 °C or low temperature &lt;35.5 °C; movement only when stimulated or no movement.</p>\n<table>\n<thead>\n<tr>\n<th>Classification</th>\n<th>Signs</th>\n<th>Management</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Very severe disease (PSBI / severe pneumonia)</strong></td>\n<td>Any sign above (fast breathing ≥60 is pneumonia in 7–59 days)</td>\n<td><strong>Refer urgently</strong> after first dose of <strong>injectable ampicillin + gentamicin</strong>; keep warm (KMC), breastfeed or give expressed milk, prevent hypoglycaemia</td>\n</tr>\n<tr>\n<td>If referral not possible (WHO 2015 PSBI guideline)</td>\n<td>Fast breathing alone (7–59 days)</td>\n<td>Oral amoxicillin for 7 days</td>\n</tr>\n<tr>\n<td></td>\n<td>Clinical severe infection</td>\n<td>IM gentamicin + oral amoxicillin (7 days)</td>\n</tr>\n<tr>\n<td><strong>No pneumonia: cough or cold</strong></td>\n<td>No danger signs, no fast breathing</td>\n<td>Home care: keep warm, breastfeed frequently, clear nose; return immediately if danger signs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.608","n":608,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"ARI / Pneumonia","q":"<p>Discuss preventive measures for ARI.</p>","a":"<p><strong>Prevention of ARI</strong></p>\n<p><strong>A. Specific protection: immunisation</strong></p>\n<p>Pentavalent (pertussis, Hib), <strong>PCV</strong> (pneumococcus), <strong>measles-rubella</strong>, BCG; influenza and COVID-19 vaccines for high-risk groups.</p>\n<p><strong>B. Nutrition</strong></p>\n<p><strong>Exclusive breastfeeding</strong> 6 months; adequate complementary feeding; <strong>vitamin A</strong>; <strong>zinc</strong>; treat malnutrition; prevent LBW.</p>\n<p><strong>C. Environment</strong></p>\n<ol>\n<li><strong>Reduce indoor air pollution</strong>: clean fuel, improved stoves, ventilation, separate kitchen.</li>\n<li><strong>No smoking</strong> at home.</li>\n<li>Reduce <strong>overcrowding</strong>; better housing.</li>\n<li>Reduce outdoor air pollution.</li>\n</ol>\n<p><strong>D. Hygiene</strong></p>\n<p>Hand-washing; cough etiquette; masks during outbreaks.</p>\n<p><strong>E. Early diagnosis and treatment</strong></p>\n<p><strong>IMCI</strong> and <strong>community case management</strong> (CHWs count breaths, give amoxicillin); teach mothers danger signs (fast breathing, chest indrawing); timely referral.</p>\n<p><strong>F. Health education</strong> and keeping infants warm.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.609","n":609,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25M","17M","15Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Mention the (six) social factors predisposing to tuberculosis.</p>","a":"<p><strong>Social factors predisposing to tuberculosis (Park)</strong></p>\n<ol>\n<li><strong>Poverty</strong>.</li>\n<li><strong>Overcrowding</strong> and poor housing (poor ventilation).</li>\n<li><strong>Malnutrition</strong>.</li>\n<li><strong>Illiteracy</strong> and lack of awareness.</li>\n<li><strong>Large families</strong>; population explosion.</li>\n<li><strong>Migration</strong>, urbanisation, urban slums.</li>\n<li>Smoking, alcohol, drug use.</li>\n<li>Stigma and delayed care-seeking.</li>\n<li>Occupational exposure (silica, mining).</li>\n<li>HIV and diabetes (medical, often linked with poverty).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.610","n":610,"part":11,"topic":"Communicable Diseases","stars":3,"years":["17M","15Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>What do you mean by open case (and closed case) of tuberculosis?</p>","a":"<p><strong>Open vs closed case of tuberculosis</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Open case</th>\n<th>Closed case</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Meaning</td>\n<td><strong>Pulmonary TB</strong> patient whose <strong>sputum contains bacilli</strong> (smear- or culture-positive; bacteriologically confirmed)</td>\n<td>TB patient <strong>not discharging bacilli</strong>: smear-negative pulmonary TB or <strong>extrapulmonary TB</strong> (lymph node, bone, pleura)</td>\n</tr>\n<tr>\n<td>Infectivity</td>\n<td><strong>Infectious</strong>: main source of spread (droplet nuclei)</td>\n<td>Not (or much less) infectious</td>\n</tr>\n<tr>\n<td>Public health priority</td>\n<td><strong>Highest</strong>: early detection and treatment</td>\n<td>Treat to prevent progression</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>Sputum smear-positive cavitary TB</td>\n<td>TB lymphadenitis</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.611","n":611,"part":11,"topic":"Communicable Diseases","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>How can tuberculosis be diagnosed? Write down the treatment of tuberculosis.</p>","a":"<p><strong>Diagnosis of tuberculosis</strong></p>\n<p><strong>A. Presumptive TB</strong></p>\n<p>Cough ≥2 weeks, fever, night sweats, weight loss, haemoptysis, chest pain; contacts of TB cases; PLHIV.</p>\n<p><strong>B. Tests</strong></p>\n<table>\n<thead>\n<tr>\n<th>Test</th>\n<th>Use</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Xpert MTB/RIF (GeneXpert)</strong></td>\n<td>WHO-recommended <strong>initial test</strong>: detects TB and rifampicin resistance in ~2 hours</td>\n</tr>\n<tr>\n<td><strong>Sputum smear microscopy</strong> (Ziehl–Neelsen / fluorescence)</td>\n<td>Detects AFB; monitoring treatment</td>\n</tr>\n<tr>\n<td><strong>Culture</strong> (LJ, liquid MGIT) and <strong>drug-susceptibility testing</strong></td>\n<td>Confirmation; resistance</td>\n</tr>\n<tr>\n<td><strong>Chest X-ray</strong></td>\n<td>Screening and supportive diagnosis</td>\n</tr>\n<tr>\n<td>Line probe assay</td>\n<td>Resistance to INH, rifampicin, fluoroquinolones</td>\n</tr>\n<tr>\n<td>Tuberculin skin test / IGRA</td>\n<td>TB <strong>infection</strong> (not disease)</td>\n</tr>\n<tr>\n<td>Extrapulmonary</td>\n<td>FNAC, biopsy (histopathology), fluid analysis (ADA), Xpert on samples</td>\n</tr>\n<tr>\n<td>Children</td>\n<td>Clinical features, contact history, CXR, Xpert on sputum / gastric aspirate / stool</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Treatment (drug-susceptible TB; WHO / NTP)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Phase</th>\n<th>Drugs</th>\n<th>Duration</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Intensive</strong></td>\n<td><strong>H</strong>isoniazid + <strong>R</strong>ifampicin + <strong>P</strong>yrazinamide (<strong>Z</strong>) + <strong>E</strong>thambutol (daily FDC, by weight band)</td>\n<td><strong>2 months</strong></td>\n</tr>\n<tr>\n<td><strong>Continuation</strong></td>\n<td>Isoniazid + Rifampicin</td>\n<td><strong>4 months</strong></td>\n</tr>\n</tbody>\n</table>\n<p>Regimen: <strong>2HRZE / 4HR</strong> (6 months), under <strong>DOT / patient-centred support</strong>.</p>\n<ul>\n<li>Children: 2HRZ(E)/4HR with child-friendly FDCs; shorter 4-month regimen for non-severe childhood TB (WHO, 2022).</li>\n<li>Monitoring: sputum at end of month 2, 5 and 6; side effects (hepatitis, neuropathy, visual).</li>\n<li><strong>Drug-resistant TB</strong>: shorter all-oral regimens (e.g., 6-month BPaLM: bedaquiline, pretomanid, linezolid, moxifloxacin) at DR-TB centres (WHO, 2022).</li>\n<li>Add pyridoxine for INH neuropathy prevention in at-risk groups; treat HIV (ART).</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO consolidated guidelines on tuberculosis, 2022.</p>"},{"id":"DU.612","n":612,"part":11,"topic":"Communicable Diseases","stars":3,"years":["17Ja","14Ju","13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Highlight the approaches / measures for control of tuberculosis.</p>","a":"<p><strong>Approaches / measures for TB control</strong></p>\n<p><strong>A. Case finding</strong></p>\n<p>Passive (symptomatic patients at facilities); <strong>active case finding</strong> (contacts, PLHIV, prisons, slums, diabetics); rapid diagnosis with <strong>GeneXpert</strong>.</p>\n<p><strong>B. Treatment</strong></p>\n<p>Standardised short-course chemotherapy with <strong>FDCs</strong>; <strong>DOTS</strong> / patient support; management of DR-TB; treatment outcome monitoring.</p>\n<p><strong>C. Prevention</strong></p>\n<p><strong>BCG</strong> at birth; <strong>TB preventive therapy</strong> (isoniazid 6 months, 3HP) for contacts and PLHIV; infection control (ventilation, cough etiquette, masks, triage).</p>\n<p><strong>D. Address risk factors</strong></p>\n<p>Nutrition, HIV, diabetes, smoking, alcohol; social protection; housing.</p>\n<p><strong>E. Health system</strong></p>\n<p>Drug supply, laboratory network, recording and reporting, trained staff, public–private mix, community DOTS (BRAC).</p>\n<p><strong>F. Strategy: WHO End TB Strategy (2015)</strong></p>\n<p>Three pillars: (1) integrated, patient-centred care and prevention; (2) bold policies and supportive systems (UHC, social protection); (3) research and innovation. Targets for 2035 (vs 2015): <strong>95% fewer TB deaths, 90% lower incidence</strong>; no families facing catastrophic costs.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.613","n":613,"part":11,"topic":"Communicable Diseases","stars":3,"years":["17Ja","14Ja"],"colleges":"","asked":"","note":"Also printed as: preventive measures of ART","kind":"","sub":"Tuberculosis","q":"<p>Give preventive measures for tuberculosis.</p>","a":"<p><strong>Preventive measures for tuberculosis</strong></p>\n<ol>\n<li><strong>Early detection and treatment of infectious cases</strong> (most important: cuts transmission).</li>\n<li><strong>BCG vaccination</strong> at birth (protects children from severe forms: TB meningitis, miliary TB).</li>\n<li><strong>TB preventive therapy</strong>: household contacts (especially children &lt;5), PLHIV, other high-risk groups.</li>\n<li><strong>Infection control</strong>: ventilation, sunlight, cough etiquette, masks, separate waiting areas; N95 for health workers.</li>\n<li><strong>Contact tracing</strong> and screening.</li>\n<li><strong>Improve living conditions</strong>: nutrition, housing, less overcrowding.</li>\n<li><strong>Control of HIV, diabetes</strong>, smoking and alcohol.</li>\n<li><strong>Health education</strong>: symptoms, early care-seeking, treatment adherence, reducing stigma.</li>\n<li>Pasteurisation of milk (bovine TB).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.614","n":614,"part":11,"topic":"Communicable Diseases","stars":2,"years":["06M","05Ja","04Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Discuss the TB control programme in Bangladesh.</p>","a":"<p><strong>National TB Control Programme (NTP), Bangladesh</strong></p>\n<ol>\n<li>Run by <strong>DGHS</strong>; DOTS adopted in <strong>1993</strong>, expanded nationwide.</li>\n<li><strong>Free diagnosis and treatment</strong> at UHCs, chest disease clinics, hospitals, NGO centres.</li>\n<li><strong>Partnership with NGOs</strong> (BRAC and others) for community DOTS and case finding.</li>\n<li><strong>GeneXpert</strong> network for rapid diagnosis and rifampicin resistance.</li>\n<li><strong>DR-TB management</strong> at specialised centres (NIDCH) and decentralised sites.</li>\n<li><strong>Childhood TB</strong>, TB–HIV, TB–diabetes activities.</li>\n<li><strong>Public–private mix</strong> (private doctors, pharmacies).</li>\n<li>Urban DOTS; prison and Rohingya camp programmes.</li>\n<li>Advocacy, communication and social mobilisation; World TB Day.</li>\n<li>Recording and reporting; aligned with <strong>End TB Strategy</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.615","n":615,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25Nov","23Nov","17Ja","11Ju"],"colleges":"MMC (2nd Term C4)","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>What do you mean by DOTS and FDC? Illustrate the DOTS strategy; write down the importance of DOTS.</p>","a":"<p><strong>DOTS</strong></p>\n<p><strong>Directly Observed Treatment, Short-course</strong>: WHO's recommended TB control strategy, in which a trained person <strong>watches the patient swallow every dose</strong> of standardised short-course drugs.</p>\n<p><strong>Five components</strong></p>\n<ol>\n<li><strong>Political commitment</strong> with increased and sustained financing.</li>\n<li><strong>Case detection</strong> through quality-assured <strong>bacteriology</strong> (sputum microscopy, Xpert).</li>\n<li><strong>Standardised treatment</strong> with supervision and patient support (DOT).</li>\n<li>Effective <strong>drug supply</strong> and management system.</li>\n<li><strong>Monitoring and evaluation</strong> system and impact measurement (recording and reporting).</li>\n</ol>\n<p><strong>FDC (fixed-dose combination)</strong></p>\n<p>Two or more anti-TB drugs combined in <strong>one tablet in fixed proportions</strong>: e.g., 4-FDC (HRZE) for intensive phase, 2-FDC (HR) for continuation; dispersible paediatric FDCs.</p>\n<p><strong>Importance of DOTS</strong></p>\n<ol>\n<li>Ensures <strong>adherence</strong> → high cure rates.</li>\n<li>Prevents <strong>drug resistance</strong> (MDR-TB).</li>\n<li>Cuts <strong>transmission</strong> by curing infectious cases.</li>\n<li><strong>Cost-effective</strong>.</li>\n<li>Systematic <strong>monitoring</strong> of outcomes (cure, completion, failure, default).</li>\n<li>Builds a <strong>health system</strong> for TB control.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.616","n":616,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25Nov"],"colleges":"MMC (2nd Term C4)","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Enlist five advantages of FDC during tuberculosis treatment.</p>","a":"<p><strong>Five advantages of FDCs in TB treatment</strong></p>\n<ol>\n<li><strong>Fewer tablets</strong> → better <strong>adherence</strong>.</li>\n<li><strong>Prevents monotherapy</strong> (patient cannot take just one drug) → less <strong>drug resistance</strong>.</li>\n<li><strong>Simpler prescribing</strong> by weight bands → fewer <strong>dosing errors</strong>.</li>\n<li><strong>Easier drug management</strong>: procurement, storage, distribution.</li>\n<li><strong>Lower cost</strong> and easier <strong>DOT</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.617","n":617,"part":11,"topic":"Communicable Diseases","stars":1,"years":["11Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Discuss strategies and activities of DOTS in Bangladesh.</p>","a":"<p><strong>DOTS strategies and activities in Bangladesh</strong></p>\n<ol>\n<li><strong>Political commitment</strong>: NTP under DGHS; operational plan in health sector programme; donor support (Global Fund).</li>\n<li><strong>Case detection</strong>: sputum microscopy and <strong>GeneXpert</strong> labs; contact screening; active case finding in slums, prisons, garment factories.</li>\n<li><strong>Standardised treatment</strong> with <strong>DOT</strong> by health workers, NGO volunteers (BRAC <em>shasthya shebika</em>), family members; FDCs.</li>\n<li><strong>Drug supply</strong>: free, uninterrupted supply of FDCs.</li>\n<li><strong>Monitoring and evaluation</strong>: TB registers, quarterly reports, cohort analysis of outcomes; e-TB manager.</li>\n<li>Supporting activities: public–private mix, childhood TB, TB–HIV, DR-TB management, community awareness.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.618","n":618,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25M","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Why is prevalence of tuberculosis higher among HIV-infected patients? / Write down the link between tuberculosis and HIV.</p>","a":"<p><strong>Link between tuberculosis and HIV</strong></p>\n<p><strong>Why TB is more common in HIV-infected people</strong></p>\n<ol>\n<li>HIV destroys <strong>CD4 T cells</strong> → loss of <strong>cell-mediated immunity</strong>, the main defence against <em>M. tuberculosis</em>.</li>\n<li><strong>Reactivation of latent TB</strong>: risk ~5–10% per year in HIV-infected (vs ~5–10% lifetime in HIV-negative).</li>\n<li><strong>Rapid progression</strong> of new infection to disease.</li>\n<li><strong>Re-infection</strong> more likely.</li>\n<li>High exposure in shared settings (poverty, prisons, hospitals).</li>\n</ol>\n<p><strong>Effects of co-infection</strong></p>\n<ol>\n<li>More <strong>smear-negative and extrapulmonary</strong> TB (harder to diagnose).</li>\n<li>Higher <strong>mortality</strong>; TB is the <strong>leading cause of death among PLHIV</strong>.</li>\n<li>TB <strong>accelerates HIV progression</strong> (immune activation).</li>\n<li>Drug interactions (rifampicin with ART); IRIS.</li>\n<li>More <strong>drug-resistant TB</strong> in some settings.</li>\n</ol>\n<p><strong>Collaborative TB–HIV activities</strong></p>\n<p>HIV testing of all TB patients; TB screening of PLHIV; <strong>TB preventive therapy</strong>; infection control; early <strong>ART</strong>; <strong>cotrimoxazole</strong> preventive therapy.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.619","n":619,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25M"],"colleges":"","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Why does tuberculosis become resistant?</p>","a":"<p><strong>Why TB becomes drug-resistant</strong></p>\n<p><strong>A. Acquired (secondary) resistance: inadequate treatment</strong></p>\n<ol>\n<li><strong>Monotherapy</strong> or adding a single drug to a failing regimen.</li>\n<li><strong>Wrong regimen or doses</strong>; poor prescribing (unregulated private sector).</li>\n<li><strong>Irregular intake / non-adherence</strong>: side effects, long treatment, poverty, ignorance, stigma.</li>\n<li><strong>Premature discontinuation</strong> (patient feels better).</li>\n<li><strong>Drug stock-outs</strong> and poor-quality drugs.</li>\n<li>Poor <strong>DOT</strong> and follow-up.</li>\n<li><strong>Malabsorption</strong>, HIV, diabetes.</li>\n</ol>\n<p><strong>Mechanism</strong>: spontaneous chromosomal mutations exist in large bacillary populations; inadequate therapy kills sensitive bacilli and <strong>selects resistant mutants</strong>.</p>\n<p><strong>B. Primary resistance</strong>: transmission of resistant strains to new patients (crowded settings, poor infection control).</p>\n<p><strong>Types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Resistance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Rifampicin-resistant (RR-TB)</td>\n<td>Rifampicin</td>\n</tr>\n<tr>\n<td><strong>MDR-TB</strong></td>\n<td>At least <strong>isoniazid + rifampicin</strong></td>\n</tr>\n<tr>\n<td>Pre-XDR-TB</td>\n<td>MDR/RR + a fluoroquinolone</td>\n</tr>\n<tr>\n<td><strong>XDR-TB</strong></td>\n<td>MDR/RR + fluoroquinolone + bedaquiline and/or linezolid</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.620","n":620,"part":11,"topic":"Communicable Diseases","stars":3,"years":["26M"],"colleges":"MuMC (2nd Final D3)","asked":"","note":"","kind":"","sub":"Tuberculosis","q":"<p>Define relapse case of tuberculosis.</p>","a":"<p><strong>Relapse case of tuberculosis (WHO)</strong></p>\n<p>A patient who was <strong>previously treated for TB</strong>, was declared <strong>cured or treatment completed</strong> at the end of the last course, and is <strong>now diagnosed with a recurrent episode of TB</strong> (either true relapse or a new infection).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.621","n":621,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22M","19Nov","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Leprosy","q":"<p>Classify leprosy / mention different methods of classification of leprosy.</p>","a":"<p><strong>Classification of leprosy</strong></p>\n<table>\n<thead>\n<tr>\n<th>Classification</th>\n<th>Groups</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Madrid (1953)</strong></td>\n<td>Lepromatous (L), Tuberculoid (T), Borderline / dimorphous (B), Indeterminate (I)</td>\n</tr>\n<tr>\n<td><strong>Indian (IAL, 1981)</strong></td>\n<td>Indeterminate, Tuberculoid, Borderline, Lepromatous, <strong>Pure neuritic</strong></td>\n</tr>\n<tr>\n<td><strong>Ridley–Jopling (1966)</strong> (immunological spectrum)</td>\n<td><strong>TT</strong> (tuberculoid) – <strong>BT</strong> (borderline tuberculoid) – <strong>BB</strong> (mid-borderline) – <strong>BL</strong> (borderline lepromatous) – <strong>LL</strong> (lepromatous); plus indeterminate</td>\n</tr>\n<tr>\n<td><strong>WHO operational (for treatment)</strong></td>\n<td><strong>Paucibacillary (PB)</strong>: 1–5 skin lesions, no nerve involvement, smear-negative. <strong>Multibacillary (MB)</strong>: &gt;5 skin lesions, or nerve involvement, or smear-positive</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.622","n":622,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"Leprosy","q":"<p>Differentiate multibacillary from paucibacillary leprosy.</p>","a":"<p><strong>Multibacillary (MB) vs paucibacillary (PB) leprosy</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Paucibacillary (PB)</th>\n<th>Multibacillary (MB)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Skin lesions</td>\n<td><strong>1–5</strong></td>\n<td><strong>More than 5</strong></td>\n</tr>\n<tr>\n<td>Nerve involvement</td>\n<td>None</td>\n<td>Present (one or more nerves)</td>\n</tr>\n<tr>\n<td>Slit-skin smear</td>\n<td><strong>Negative</strong></td>\n<td><strong>Positive</strong> (any lesion count)</td>\n</tr>\n<tr>\n<td>Ridley–Jopling</td>\n<td>TT, BT (few lesions), indeterminate</td>\n<td>BB, BL, LL (and BT with many lesions)</td>\n</tr>\n<tr>\n<td>Cell-mediated immunity</td>\n<td>Good</td>\n<td>Poor</td>\n</tr>\n<tr>\n<td>Lepromin test</td>\n<td>Positive</td>\n<td>Negative</td>\n</tr>\n<tr>\n<td>Infectiousness</td>\n<td>Low</td>\n<td><strong>High</strong> (main source of infection)</td>\n</tr>\n<tr>\n<td>Lesions</td>\n<td>Few, asymmetrical, well-defined, anaesthetic</td>\n<td>Many, symmetrical, ill-defined; nodules</td>\n</tr>\n<tr>\n<td>WHO MDT duration</td>\n<td><strong>6 months</strong></td>\n<td><strong>12 months</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO Guidelines for the diagnosis, treatment and prevention of leprosy, 2018.</p>"},{"id":"DU.623","n":623,"part":11,"topic":"Communicable Diseases","stars":3,"years":[],"colleges":"","asked":"","note":"","kind":"","sub":"Leprosy","q":"<p>Write down the treatment of leprosy as per WHO guidelines.</p>","a":"<p><strong>Treatment of leprosy (WHO, 2018: uniform three-drug MDT)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Drug (adult)</th>\n<th>Dose</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Rifampicin</strong></td>\n<td>600 mg once a month (supervised)</td>\n</tr>\n<tr>\n<td><strong>Clofazimine</strong></td>\n<td>300 mg once a month (supervised) + <strong>50 mg daily</strong></td>\n</tr>\n<tr>\n<td><strong>Dapsone</strong></td>\n<td><strong>100 mg daily</strong></td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Duration</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Paucibacillary</strong></td>\n<td><strong>6 months</strong></td>\n</tr>\n<tr>\n<td><strong>Multibacillary</strong></td>\n<td><strong>12 months</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Children (10–14 years)</strong>: rifampicin 450 mg monthly; clofazimine 150 mg monthly + 50 mg alternate days; dapsone 50 mg daily (lower weight-based doses for younger children).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO Guidelines for the diagnosis, treatment and prevention of leprosy, 2018.</p>"},{"id":"DU.624","n":624,"part":11,"topic":"Communicable Diseases","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Leprosy","q":"<p>Discuss the ongoing leprosy elimination programme in Bangladesh.</p>","a":"<p><strong>Leprosy elimination programme in Bangladesh</strong></p>\n<ol>\n<li><strong>National Leprosy Programme</strong> under DGHS with NGO partners (The Leprosy Mission and others).</li>\n<li>Bangladesh reached <strong>elimination as a public health problem</strong> at national level (prevalence &lt;1 per 10,000) by the late 1990s; pockets remain in some northern and hill districts.</li>\n<li><strong>Free MDT</strong> (WHO regimen) through UHCs and partner clinics.</li>\n<li><strong>Early case detection</strong>: active case finding, <strong>contact screening</strong>, skin camps, school surveys.</li>\n<li><strong>Single-dose rifampicin PEP</strong> for contacts.</li>\n<li><strong>Disability prevention and rehabilitation</strong>: self-care groups, footwear, reconstructive surgery.</li>\n<li><strong>Stigma reduction</strong>; health education; community participation.</li>\n<li>Surveillance, recording and reporting; aligned with WHO <strong>&quot;Towards zero leprosy&quot; (2021–2030)</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.625","n":625,"part":11,"topic":"Communicable Diseases","stars":0,"years":["05S"],"colleges":"","asked":"","note":"","kind":"","sub":"Poliomyelitis","q":"<p>Discuss the epidemiology of poliomyelitis.</p>","a":"<p><strong>Epidemiology of poliomyelitis</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Agent</strong></td>\n<td>Poliovirus types 1, 2, 3 (enterovirus); wild type 2 and 3 eradicated; wild type 1 persists in a few countries; vaccine-derived poliovirus (cVDPV) also causes outbreaks</td>\n</tr>\n<tr>\n<td><strong>Reservoir</strong></td>\n<td><strong>Man only</strong>; most infections <strong>subclinical</strong> (many inapparent infections for every paralytic case); no chronic carriers</td>\n</tr>\n<tr>\n<td><strong>Infective material</strong></td>\n<td><strong>Faeces</strong> (for weeks) and <strong>oropharyngeal secretions</strong> (first week)</td>\n</tr>\n<tr>\n<td><strong>Communicability</strong></td>\n<td>Most infectious 7–10 days before and after onset of symptoms</td>\n</tr>\n<tr>\n<td><strong>Age</strong></td>\n<td>Mainly <strong>under 5 years</strong> (&quot;infantile paralysis&quot;)</td>\n</tr>\n<tr>\n<td><strong>Sex</strong></td>\n<td>Paralysis more in males</td>\n</tr>\n<tr>\n<td><strong>Risk factors for paralysis</strong></td>\n<td>Fatigue, trauma, <strong>IM injections</strong>, tonsillectomy (provocation paralysis), pregnancy, immunodeficiency</td>\n</tr>\n<tr>\n<td><strong>Immunity</strong></td>\n<td>Type-specific, long-lasting; maternal antibodies protect for a few months</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td>Rainy season; poor sanitation, crowding</td>\n</tr>\n<tr>\n<td><strong>Transmission</strong></td>\n<td><strong>Faecal–oral</strong> (main); droplet in early phase</td>\n</tr>\n<tr>\n<td><strong>Incubation period</strong></td>\n<td><strong>7–14 days</strong> (range 3–35)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.626","n":626,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov","10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Poliomyelitis","q":"<p>Identify the epidemiological basis / approach of poliomyelitis eradication.</p>","a":"<p><strong>Epidemiological basis of polio eradication</strong></p>\n<ol>\n<li><strong>Man is the only reservoir</strong>; no animal or environmental reservoir.</li>\n<li><strong>No long-term carriers</strong>; virus survives only briefly outside the host.</li>\n<li><strong>Most infections are subclinical</strong> but still give immunity → wide natural and vaccine-induced immunity possible.</li>\n<li><strong>Effective, cheap, easy oral vaccine (OPV)</strong> gives <strong>gut (mucosal) immunity</strong> that blocks transmission; vaccine virus spreads to contacts (herd effect).</li>\n<li><strong>Long-lasting, type-specific immunity</strong>.</li>\n<li><strong>Seasonal transmission</strong> → campaigns timed in the low season.</li>\n<li><strong>Good surveillance tools</strong>: AFP surveillance with stool culture; environmental (sewage) surveillance.</li>\n<li>Success of smallpox eradication showed feasibility.</li>\n</ol>\n<p><strong>Approach (WHO strategies)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Strategy</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>High <strong>routine immunisation</strong> (bOPV + IPV)</td>\n<td>Baseline immunity</td>\n</tr>\n<tr>\n<td><strong>Supplementary immunisation</strong> (NIDs, sub-NIDs)</td>\n<td>Extra OPV to all under-5s at once → interrupt transmission</td>\n</tr>\n<tr>\n<td><strong>AFP surveillance</strong> (non-polio AFP rate ≥2/100,000 under-15s; 2 stool samples within 14 days)</td>\n<td>Detect any circulating virus</td>\n</tr>\n<tr>\n<td><strong>Mop-up</strong> campaigns</td>\n<td>House-to-house OPV where virus found</td>\n</tr>\n<tr>\n<td>Environmental surveillance</td>\n<td>Detect silent circulation</td>\n</tr>\n<tr>\n<td><strong>OPV withdrawal</strong> (tOPV → bOPV switch 2016; IPV introduction)</td>\n<td>Eliminate vaccine-derived polio</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.627","n":627,"part":11,"topic":"Communicable Diseases","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Poliomyelitis","q":"<p>Write down the ongoing polio eradication programme in Bangladesh.</p>","a":"<p><strong>Polio eradication programme in Bangladesh</strong></p>\n<ol>\n<li><strong>Routine immunisation (EPI)</strong>: bOPV at 6, 10, 14 weeks; <strong>fractional IPV</strong> at 6 and 14 weeks.</li>\n<li><strong>National Immunisation Days</strong> (since 1995) with OPV for all under-5s; often with vitamin A.</li>\n<li><strong>AFP surveillance</strong> with laboratory confirmation (national polio laboratory, IPH) and WHO support.</li>\n<li><strong>Environmental surveillance</strong> of sewage in selected sites.</li>\n<li><strong>Mop-up</strong> and outbreak response plans; high-risk areas (border, hard-to-reach, Rohingya camps).</li>\n<li>Last wild polio case in <strong>2006</strong>; <strong>SEAR certified polio-free in 2014</strong>.</li>\n<li>Maintaining polio-free status: high coverage, surveillance, preparedness for importation and cVDPV.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.628","n":628,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Poliomyelitis","q":"<p>Why has inactivated polio vaccine (IPV) been introduced?</p>","a":"<p><strong>Why IPV has been introduced</strong></p>\n<ol>\n<li><strong>Polio endgame</strong>: after <strong>wild poliovirus type 2 eradication</strong> (certified 2015), the <strong>type 2 component was removed</strong> from OPV (trivalent OPV → <strong>bivalent OPV</strong>, April 2016). IPV (containing types 1, 2, 3) maintains <strong>immunity against type 2</strong>.</li>\n<li><strong>Protects against vaccine-derived polio</strong>: OPV can rarely cause <strong>VAPP</strong> and <strong>cVDPV</strong>; IPV is inactivated and cannot.</li>\n<li><strong>Closes immunity gaps</strong>: boosts humoral immunity and <strong>intestinal immunity</strong> in children already given OPV → stronger protection against all types.</li>\n<li>Prepares for <strong>eventual withdrawal of all OPV</strong> after global eradication.</li>\n<li>Safe in immunocompromised children.</li>\n</ol>\n<p><strong>In Bangladesh</strong>: <strong>fractional IPV (0.1 ml intradermal)</strong> at 6 and 14 weeks: dose-sparing, good immunity, saves scarce vaccine.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.629","n":629,"part":11,"topic":"Communicable Diseases","stars":3,"years":["26M","24Nov","23Nov","22Nov","20Nov","14Ju","09Ja"],"colleges":"MuMC (2nd Final D2)","asked":"","note":"","kind":"","sub":"Hepatitis","q":"<p>What are the modes of transmission of viral hepatitis B? (How can HBV be contaminated / transmitted?)</p>","a":"<p><strong>Modes of transmission of hepatitis B virus (HBV)</strong></p>\n<p><strong>A. Parenteral (blood-borne)</strong></p>\n<ol>\n<li>Transfusion of unscreened <strong>blood and blood products</strong>.</li>\n<li><strong>Unsafe injections</strong>: reused needles and syringes; injecting drug use.</li>\n<li><strong>Needle-stick injuries</strong> in health workers.</li>\n<li>Unsterile <strong>surgical and dental</strong> instruments; haemodialysis.</li>\n<li>Tattooing, ear-piercing, circumcision, barbers' razors, shared toothbrushes.</li>\n</ol>\n<p><strong>B. Sexual</strong></p>\n<p>Unprotected sexual contact with an infected partner (semen, vaginal fluids).</p>\n<p><strong>C. Perinatal (vertical)</strong></p>\n<p>From <strong>HBsAg-positive (especially HBeAg-positive) mother</strong> to baby, mainly at birth → up to 90% of infected babies become chronic carriers.</p>\n<p><strong>D. Horizontal (household)</strong></p>\n<p>Close contact among children through cuts, sores, shared items.</p>\n<p><strong>Not spread</strong> by food, water, casual contact, breastfeeding (with infant vaccination).</p>\n<p><strong>Infective materials</strong>: blood (most), semen, vaginal secretions, saliva (less).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.630","n":630,"part":11,"topic":"Communicable Diseases","stars":2,"years":["12Ju","08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Hepatitis","q":"<p>How can HBV infection be prevented?</p>","a":"<p><strong>Prevention of HBV infection</strong></p>\n<ol>\n<li><strong>Hepatitis B vaccination</strong>: infants (birth dose + pentavalent), health workers, high-risk adults.</li>\n<li><strong>Prevent mother-to-child transmission</strong>: screen pregnant women; <strong>birth dose vaccine + HBIG</strong> for babies of HBsAg-positive mothers; antiviral (tenofovir) for mothers with high viral load.</li>\n<li><strong>Safe blood</strong>: screen donors (HBsAg, anti-HBc where possible).</li>\n<li><strong>Safe injections</strong>: auto-disable syringes; no reuse.</li>\n<li><strong>Sterilisation</strong> of instruments; infection control in hospitals and dental clinics.</li>\n<li><strong>Safe sex</strong>: condoms.</li>\n<li>Harm reduction for injecting drug users.</li>\n<li><strong>Post-exposure prophylaxis</strong> (HBIG + vaccine).</li>\n<li>Health education; avoid sharing razors, toothbrushes.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.631","n":631,"part":11,"topic":"Communicable Diseases","stars":1,"years":["10Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Hepatitis","q":"<p>Health personnel accidentally exposed to HBV infection: what measures will you suggest?</p>","a":"<p><strong>Health worker exposed to HBV (e.g., needle-stick)</strong></p>\n<ol>\n<li><strong>First aid</strong>: wash wound with soap and water; do not squeeze; flush mucosa with water.</li>\n<li><strong>Report</strong> and document; assess exposure and source (test source for HBsAg with consent).</li>\n<li><strong>Baseline tests</strong> of the worker: HBsAg, anti-HBs (also HCV, HIV).</li>\n<li><strong>Post-exposure prophylaxis by vaccination status</strong> (source HBsAg-positive or unknown high-risk):</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Worker</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Unvaccinated</td>\n<td><strong>HBIG</strong> (0.06 ml/kg IM, within 24 hours) + start <strong>hepatitis B vaccine</strong> series</td>\n</tr>\n<tr>\n<td>Vaccinated, responder (anti-HBs ≥10 mIU/ml)</td>\n<td>No treatment</td>\n</tr>\n<tr>\n<td>Vaccinated, non-responder</td>\n<td>HBIG ×2 (1 month apart) or HBIG + revaccination</td>\n</tr>\n<tr>\n<td>Vaccinated, response unknown</td>\n<td>Test anti-HBs: adequate → none; inadequate → HBIG + booster</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"5\">\n<li><strong>Follow-up</strong> testing at ~6 months; counselling.</li>\n<li>Prevention: no recapping, sharps boxes, vaccinate all health workers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases; Occupational Health).</p>"},{"id":"DU.632","n":632,"part":11,"topic":"Communicable Diseases","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Hepatitis","q":"<p>Mention the differences between hepatitis A and C.</p>","a":"<p><strong>Hepatitis A vs hepatitis C</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Hepatitis A</th>\n<th>Hepatitis C</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Virus</td>\n<td>HAV (RNA, picornavirus)</td>\n<td>HCV (RNA, flavivirus)</td>\n</tr>\n<tr>\n<td>Transmission</td>\n<td><strong>Faeco-oral</strong> (water, food)</td>\n<td><strong>Parenteral</strong> (blood, unsafe injections, transfusion, IDU); less sexual and perinatal</td>\n</tr>\n<tr>\n<td>Incubation period</td>\n<td>15–45 days (~4 weeks)</td>\n<td>2 weeks–6 months (~6–9 weeks)</td>\n</tr>\n<tr>\n<td>Age</td>\n<td>Children, young adults</td>\n<td>Adults</td>\n</tr>\n<tr>\n<td>Onset</td>\n<td>Acute</td>\n<td>Insidious; mostly asymptomatic</td>\n</tr>\n<tr>\n<td>Chronicity</td>\n<td><strong>None</strong></td>\n<td><strong>~70–80% become chronic</strong></td>\n</tr>\n<tr>\n<td>Complications</td>\n<td>Rare fulminant hepatitis</td>\n<td>Cirrhosis, hepatocellular carcinoma</td>\n</tr>\n<tr>\n<td>Carrier state</td>\n<td>No</td>\n<td>Yes</td>\n</tr>\n<tr>\n<td>Vaccine</td>\n<td><strong>Available</strong></td>\n<td><strong>None</strong></td>\n</tr>\n<tr>\n<td>Treatment</td>\n<td>Supportive</td>\n<td><strong>Direct-acting antivirals</strong> (curative)</td>\n</tr>\n<tr>\n<td>Prevention</td>\n<td>Safe water, sanitation, hygiene, vaccine</td>\n<td>Safe blood and injections, harm reduction</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.633","n":633,"part":11,"topic":"Communicable Diseases","stars":2,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Hepatitis","q":"<p>Write the importance of the window period in hepatitis B infection.</p>","a":"<p><strong>Window period in hepatitis B</strong></p>\n<p><strong>1. Serological (&quot;core&quot;) window</strong></p>\n<p>Period during recovery from acute HBV after <strong>HBsAg has disappeared</strong> but <strong>before anti-HBs appears</strong>; only <strong>IgM anti-HBc</strong> is detectable.</p>\n<p><strong>2. Pre-seroconversion (infectious) window</strong></p>\n<p>Early infection <strong>before HBsAg becomes detectable</strong> by tests, though the person may already be infectious.</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li><strong>Missed diagnosis</strong>: testing only HBsAg will miss acute infection; <strong>anti-HBc IgM</strong> must be tested.</li>\n<li><strong>Blood safety</strong>: donors in the window period may test HBsAg-negative yet transmit infection → need sensitive tests, anti-HBc and <strong>nucleic acid testing (NAT)</strong>, careful donor selection (voluntary, low-risk donors).</li>\n<li><strong>Interpretation of serology</strong>: helps distinguish acute, resolving, chronic and past infection.</li>\n<li><strong>Post-exposure follow-up</strong> must be long enough (≈6 months).</li>\n<li>Epidemiological surveys and screening programmes must account for it.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.634","n":634,"part":11,"topic":"Communicable Diseases","stars":2,"years":["18M"],"colleges":"","asked":"","note":"","kind":"","sub":"Hepatitis","q":"<p>Write down the schedule for HBV (vaccine).</p>","a":"<p><strong>Hepatitis B vaccine schedule</strong></p>\n<p><strong>A. Infants</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dose</th>\n<th>Timing</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Birth dose</strong> (WHO recommends for all)</td>\n<td>Within <strong>24 hours</strong> of birth</td>\n</tr>\n<tr>\n<td>Doses 2–4</td>\n<td>With <strong>pentavalent</strong> (DPT-HepB-Hib) at <strong>6, 10, 14 weeks</strong> (Bangladesh EPI)</td>\n</tr>\n</tbody>\n</table>\n<p>Babies of HBsAg-positive mothers: birth dose <strong>+ HBIG</strong> within 12–24 hours.</p>\n<p><strong>B. Adults and older children (unvaccinated, high-risk, health workers)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Schedule</th>\n<th>Doses</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Standard</td>\n<td><strong>0, 1, 6 months</strong></td>\n</tr>\n<tr>\n<td>Accelerated</td>\n<td>0, 1, 2 months + booster at 12 months</td>\n</tr>\n<tr>\n<td>Rapid (urgent)</td>\n<td>0, 7, 21 days + booster at 12 months</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Dose and route</strong></p>\n<p>0.5 ml (children ≤19 years), 1 ml (adults), <strong>intramuscular</strong> (anterolateral thigh in infants, deltoid in adults); not in the buttock.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.635","n":635,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>How will you manage diarrhoea after assessing dehydration?</p>","a":"<p><strong>Assessment of dehydration (WHO / IMCI)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Sign</th>\n<th>No dehydration</th>\n<th>Some dehydration</th>\n<th>Severe dehydration</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>General condition</td>\n<td>Well, alert</td>\n<td><strong>Restless, irritable</strong></td>\n<td><strong>Lethargic or unconscious</strong></td>\n</tr>\n<tr>\n<td>Eyes</td>\n<td>Normal</td>\n<td>Sunken</td>\n<td>Sunken</td>\n</tr>\n<tr>\n<td>Drinking</td>\n<td>Drinks normally</td>\n<td><strong>Thirsty, drinks eagerly</strong></td>\n<td><strong>Drinks poorly / unable</strong></td>\n</tr>\n<tr>\n<td>Skin pinch</td>\n<td>Goes back quickly</td>\n<td>Goes back <strong>slowly</strong></td>\n<td>Goes back <strong>very slowly (&gt;2 s)</strong></td>\n</tr>\n</tbody>\n</table>\n<p>(Two or more signs in a column decide the classification.)</p>\n<p><strong>Management</strong></p>\n<table>\n<thead>\n<tr>\n<th>Plan</th>\n<th>Classification</th>\n<th>Treatment</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Plan A</strong> (home)</td>\n<td>No dehydration</td>\n<td><strong>Extra fluids</strong>: ORS after each loose stool (&lt;2 years: 50–100 ml; 2–10 years: 100–200 ml; older: as much as wanted); <strong>zinc</strong> for 10–14 days (10 mg/day &lt;6 months; 20 mg/day ≥6 months); <strong>continue feeding / breastfeeding</strong>; return if danger signs</td>\n</tr>\n<tr>\n<td><strong>Plan B</strong> (facility)</td>\n<td>Some dehydration</td>\n<td><strong>ORS 75 ml/kg over 4 hours</strong> under observation; continue breastfeeding; reassess after 4 hours; then Plan A; zinc</td>\n</tr>\n<tr>\n<td><strong>Plan C</strong> (urgent)</td>\n<td>Severe dehydration</td>\n<td><strong>IV Ringer's lactate 100 ml/kg</strong> (see below); reassess every 1–2 hours; ORS as soon as able to drink; if IV impossible: <strong>nasogastric ORS 20 ml/kg/hour for 6 hours</strong>; refer</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Plan C rates</strong></p>\n<table>\n<thead>\n<tr>\n<th>Age</th>\n<th>First 30 ml/kg in</th>\n<th>Then 70 ml/kg in</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Infants &lt;12 months</td>\n<td>1 hour</td>\n<td>5 hours</td>\n</tr>\n<tr>\n<td>≥12 months</td>\n<td>30 minutes</td>\n<td>2½ hours</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Antibiotics</strong> only for <strong>dysentery</strong> (blood in stool) and suspected <strong>cholera</strong> with severe dehydration; no antidiarrhoeal drugs in children.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.636","n":636,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>Classify diarrhoeal diseases on the basis of causative agents. How can you prevent such diseases at your locality?</p>","a":"<p><strong>Classification of diarrhoeal diseases by causative agent</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Agents</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Viral</strong></td>\n<td><strong>Rotavirus</strong> (commonest in infants), norovirus, adenovirus (enteric), astrovirus</td>\n</tr>\n<tr>\n<td><strong>Bacterial</strong></td>\n<td><em><strong>Vibrio cholerae</strong></em>, <strong>enterotoxigenic <em>E. coli</em></strong> (ETEC), EPEC, EHEC, <em><strong>Shigella</strong></em>, <em><strong>Salmonella</strong></em>, <em>Campylobacter</em>, <em>Clostridioides difficile</em>, <em>Yersinia</em>; toxins of <em>S. aureus</em>, <em>B. cereus</em></td>\n</tr>\n<tr>\n<td><strong>Protozoal</strong></td>\n<td><em><strong>Entamoeba histolytica</strong></em>, <em><strong>Giardia lamblia</strong></em>, <em>Cryptosporidium</em>, <em>Cyclospora</em></td>\n</tr>\n<tr>\n<td><strong>Helminthic</strong></td>\n<td><em>Strongyloides</em>, heavy <em>Trichuris</em> infection</td>\n</tr>\n<tr>\n<td>Non-infectious</td>\n<td>Food intolerance, drugs, toxins</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Clinical types</strong>: acute watery diarrhoea (including cholera), <strong>dysentery</strong> (bloody), <strong>persistent diarrhoea</strong> (≥14 days).</p>\n<p><strong>Prevention in the locality</strong></p>\n<ol>\n<li><strong>Safe drinking water</strong>: tube wells, boiling, chlorination.</li>\n<li><strong>Sanitary latrines</strong>; end open defecation; safe disposal of child faeces.</li>\n<li><strong>Hand-washing with soap</strong> at critical times.</li>\n<li><strong>Food hygiene</strong>: cook well, eat hot, cover food; avoid unsafe street food.</li>\n<li><strong>Exclusive breastfeeding</strong>; safe complementary feeding.</li>\n<li><strong>Vaccination</strong>: measles (and rotavirus, cholera vaccines where available).</li>\n<li><strong>Vitamin A</strong>; nutrition.</li>\n<li><strong>Fly control</strong>; refuse disposal.</li>\n<li><strong>Health education</strong>; ORS and zinc at home.</li>\n<li>Surveillance and early outbreak response.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.637","n":637,"part":11,"topic":"Communicable Diseases","stars":0,"years":["08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>Diarrhoeal disease is a major public health problem in Bangladesh – justify. Give your suggestion to combat this problem.</p>","a":"<p><strong>Diarrhoeal disease: a major public health problem in Bangladesh</strong></p>\n<ol>\n<li>Among the <strong>leading causes of illness and death</strong> in children under 5.</li>\n<li><strong>Vicious cycle with malnutrition</strong> → stunting, poor development.</li>\n<li><strong>Frequent outbreaks</strong>: cholera, acute watery diarrhoea, especially after <strong>floods</strong> and in the pre-monsoon season.</li>\n<li>Large <strong>burden on hospitals</strong> (e.g., icddr,b Dhaka hospital) and families (cost, lost work).</li>\n<li>Linked to <strong>unsafe water, poor sanitation and hygiene</strong>, urban slums, Rohingya camps.</li>\n<li>Affects all ages; typhoid, hepatitis E also water-borne.</li>\n</ol>\n<p><strong>Suggestions</strong></p>\n<p>ORS + zinc for all cases; WASH; breastfeeding; vaccines (measles; cholera and rotavirus where feasible); vitamin A; health education; surveillance and outbreak response; flood preparedness; research.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.638","n":638,"part":11,"topic":"Communicable Diseases","stars":3,"years":["17M"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>Write down the management of a diarrhoeal patient with severe dehydration.</p>","a":"<p><strong>Management of severe dehydration (Plan C)</strong></p>\n<p><strong>1. Start IV fluid immediately</strong></p>\n<p><strong>Ringer's lactate</strong> (or normal saline / cholera saline) <strong>100 ml/kg</strong>:</p>\n<table>\n<thead>\n<tr>\n<th>Age</th>\n<th>First 30 ml/kg</th>\n<th>Then 70 ml/kg</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Infants &lt;12 months</td>\n<td>In 1 hour</td>\n<td>In 5 hours</td>\n</tr>\n<tr>\n<td>≥12 months (and adults)</td>\n<td>In 30 minutes</td>\n<td>In 2½ hours</td>\n</tr>\n</tbody>\n</table>\n<p>Repeat the first 30 ml/kg once if radial pulse is still weak.</p>\n<p><strong>2. Monitor</strong></p>\n<p>Reassess every 15–30 minutes until pulse is strong, then every 1–2 hours: pulse, consciousness, eyes, skin pinch, urine output, stool volume.</p>\n<p><strong>3. ORS</strong></p>\n<p>Start <strong>ORS (5 ml/kg/hour)</strong> as soon as the patient can drink (3–4 hours in infants, 1–2 hours in older).</p>\n<p><strong>4. Reassess after IV course</strong></p>\n<p>Severe → repeat Plan C; some → Plan B; none → Plan A.</p>\n<p><strong>5. If IV not possible</strong></p>\n<p><strong>Nasogastric ORS 20 ml/kg/hour for 6 hours</strong> (120 ml/kg) or refer urgently (start ORS by mouth on the way).</p>\n<p><strong>6. Other</strong></p>\n<ol>\n<li><strong>Antibiotics</strong> for suspected <strong>cholera</strong> (e.g., azithromycin single dose; doxycycline in adults) or dysentery.</li>\n<li><strong>Zinc</strong> 10–14 days (children).</li>\n<li>Continue breastfeeding and feeding once able.</li>\n<li>Treat complications: hypokalaemia, hypoglycaemia, acidosis.</li>\n<li>Notify cholera; disinfect stools; health education.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.639","n":639,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov","13Ja"],"colleges":"MMC (1st Supp C1)","asked":"how can diarrhoea be controlled?","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>Outline the preventive / control measures of diarrhoea.</p>","a":"<p><strong>Prevention and control of diarrhoea</strong></p>\n<p><strong>A. Treatment (reduces deaths)</strong></p>\n<ol>\n<li><strong>Oral rehydration therapy</strong> (ORS; home fluids).</li>\n<li><strong>Zinc</strong> for 10–14 days.</li>\n<li><strong>Continued feeding</strong> and breastfeeding.</li>\n<li>Appropriate antibiotics for dysentery and cholera only.</li>\n</ol>\n<p><strong>B. Prevention (WHO/UNICEF 7-point plan)</strong></p>\n<ol>\n<li><strong>Rotavirus and measles vaccination</strong>.</li>\n<li><strong>Early and exclusive breastfeeding</strong>; <strong>vitamin A</strong> supplementation.</li>\n<li><strong>Hand-washing with soap</strong>.</li>\n<li>Improved <strong>water supply</strong> (quantity and quality), household water treatment and safe storage.</li>\n<li><strong>Community-wide sanitation</strong>.</li>\n</ol>\n<p><strong>C. Other measures</strong></p>\n<ol>\n<li>Food hygiene; safe complementary feeding.</li>\n<li>Fly control; refuse disposal.</li>\n<li><strong>Oral cholera vaccine</strong> in high-risk areas and outbreaks.</li>\n<li><strong>Surveillance</strong> and early outbreak response (case finding, chlorination, ORS corners).</li>\n<li><strong>Health education</strong> and community mobilisation.</li>\n<li>Nutrition improvement (break malnutrition–infection cycle).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.640","n":640,"part":11,"topic":"Communicable Diseases","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>Write on sanitation measures to control cholera.</p>","a":"<p><strong>Sanitation measures to control cholera</strong></p>\n<ol>\n<li><strong>Safe water supply</strong>: chlorination of sources, boiling, household chlorine tablets; disinfection of wells.</li>\n<li><strong>Sanitary excreta disposal</strong>: latrines; stop open defecation.</li>\n<li><strong>Disinfection</strong> of patients' stools, vomit, clothes and bedding (concurrent disinfection; 1–2% chlorine solution).</li>\n<li><strong>Food sanitation</strong>: cook well, eat hot; avoid raw seafood, cut fruits, street food; food handlers' hygiene.</li>\n<li><strong>Hand-washing</strong> with soap.</li>\n<li><strong>Fly control</strong> and refuse disposal.</li>\n<li>Safe handling and burial of dead bodies.</li>\n<li>Health education.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.641","n":641,"part":11,"topic":"Communicable Diseases","stars":3,"years":["24M","22Nov","16Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>Mention the functions / role of ICDDR,B in control of diarrhoeal diseases in Bangladesh.</p>","a":"<p><strong>Role of icddr,b in control of diarrhoeal diseases</strong></p>\n<p>icddr,b (International Centre for Diarrhoeal Disease Research, Bangladesh), Dhaka: began as the Cholera Research Laboratory (1960); international centre since 1978.</p>\n<table>\n<thead>\n<tr>\n<th>Area</th>\n<th>Contributions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Research</strong></td>\n<td>Development and field-testing of <strong>ORS</strong> (and reduced-osmolarity ORS); evidence for <strong>zinc</strong> treatment; <strong>oral cholera vaccine</strong> trials; rotavirus and typhoid research; aetiology studies</td>\n</tr>\n<tr>\n<td><strong>Clinical care</strong></td>\n<td><strong>Dhaka Hospital</strong> (&quot;cholera hospital&quot;) and Matlab hospital: free treatment of very large numbers of diarrhoea patients every year; low mortality protocols</td>\n</tr>\n<tr>\n<td><strong>Treatment protocols</strong></td>\n<td>Standard rehydration and case-management guidelines, malnutrition protocols, adopted nationally and by WHO</td>\n</tr>\n<tr>\n<td><strong>Surveillance</strong></td>\n<td>Diarrhoeal disease surveillance, antimicrobial resistance monitoring, outbreak detection</td>\n</tr>\n<tr>\n<td><strong>Training</strong></td>\n<td>National and international training of doctors, nurses, health workers</td>\n</tr>\n<tr>\n<td><strong>Community programmes</strong></td>\n<td>Matlab health and demographic surveillance; WASH, hand-washing and household water treatment research</td>\n</tr>\n<tr>\n<td><strong>Policy support</strong></td>\n<td>Advises MOHFW and WHO; national diarrhoea and zinc scale-up</td>\n</tr>\n<tr>\n<td><strong>Emergency response</strong></td>\n<td>Cholera and diarrhoea outbreaks, floods, Rohingya camps</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.642","n":642,"part":11,"topic":"Communicable Diseases","stars":3,"years":["24M"],"colleges":"","asked":"","note":"","kind":"","sub":"Diarrhoeal Diseases","q":"<p>What health education should be given during an epidemic outbreak of diarrhoea?</p>","a":"<p><strong>Health education during a diarrhoea outbreak</strong></p>\n<ol>\n<li><strong>Drink safe water</strong>: boiled or chlorinated (tablets, bleaching solution); store covered; do not use pond or river water.</li>\n<li><strong>Wash hands with soap</strong>: after toilet and cleaning a child, before preparing food, eating and feeding.</li>\n<li><strong>Use latrines</strong>; dispose of children's faeces safely; no open defecation.</li>\n<li><strong>Food hygiene</strong>: cook thoroughly, eat hot, cover food; avoid raw salads, cut fruits and street food; wash utensils with safe water.</li>\n<li><strong>Start ORS early</strong> at home; learn to prepare ORS correctly; give after every loose stool.</li>\n<li><strong>Give zinc</strong> to children for 10–14 days.</li>\n<li><strong>Continue breastfeeding and feeding</strong> during diarrhoea.</li>\n<li><strong>Danger signs</strong> → go to a health facility immediately: frequent watery stools, repeated vomiting, sunken eyes, unable to drink, lethargy, blood in stool, fever.</li>\n<li><strong>Do not use</strong> antidiarrhoeal drugs or antibiotics without advice.</li>\n<li><strong>Report</strong> new cases to health workers; cooperate with chlorination and disinfection.</li>\n<li>Keep flies away; dispose of rubbish properly.</li>\n</ol>\n<p><strong>Channels</strong>: miking, community meetings, imams, schools, CHWs, mobile messages, leaflets with pictures.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases; Communication for Health Education).</p>"},{"id":"DU.643","n":643,"part":11,"topic":"Communicable Diseases","stars":0,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Helminthic Diseases","q":"<p>Discuss approaches of hookworm prevention and control.</p>","a":"<p><strong>Hookworm prevention and control (Park)</strong></p>\n<ol>\n<li><strong>Chemotherapy</strong>: mass or targeted <strong>deworming</strong> (albendazole 400 mg single dose; mebendazole) of school children and high-risk groups, periodically.</li>\n<li><strong>Sanitation</strong>: sanitary excreta disposal; stop open defecation (breaks transmission at source).</li>\n<li><strong>Health education</strong>: <strong>wear footwear</strong>, use latrines, wash hands.</li>\n<li><strong>Iron supplementation</strong> and nutrition to correct anaemia.</li>\n<li>Treatment of cases; surveillance (stool examination).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.644","n":644,"part":11,"topic":"Communicable Diseases","stars":1,"years":["11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Helminthic Diseases","q":"<p>Write down the preventive measures of teniasis.</p>","a":"<p><strong>Prevention of taeniasis (<em>Taenia solium</em>, <em>T. saginata</em>)</strong></p>\n<ol>\n<li><strong>Meat inspection</strong> in slaughter houses; condemn measly (cysticercus-infected) meat.</li>\n<li><strong>Thorough cooking</strong> of pork and beef; avoid raw or undercooked meat; freezing kills cysts.</li>\n<li><strong>Sanitary excreta disposal</strong>: prevent pigs and cattle from eating human faeces.</li>\n<li><strong>Treatment of carriers</strong> (praziquantel, niclosamide).</li>\n<li><strong>Personal hygiene</strong> and hand-washing (prevents cysticercosis from <em>T. solium</em> eggs).</li>\n<li><strong>Pig husbandry</strong>: confine pigs.</li>\n<li>Health education.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.645","n":645,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Enteric Fever (Typhoid)","q":"<p>How can you diagnose and manage a case of enteric fever?</p>","a":"<p><strong>Diagnosis of enteric (typhoid) fever</strong></p>\n<p><strong>A. Clinical</strong></p>\n<p>Step-ladder fever, headache, malaise, abdominal pain, constipation or diarrhoea; coated tongue, relative bradycardia, tender abdomen, hepatosplenomegaly, rose spots; history of unsafe food or water.</p>\n<p><strong>B. Laboratory</strong></p>\n<table>\n<thead>\n<tr>\n<th>Test</th>\n<th>Remarks</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Blood culture</strong></td>\n<td>Test of choice; best in <strong>first week</strong></td>\n</tr>\n<tr>\n<td><strong>Bone marrow culture</strong></td>\n<td>Most sensitive (even after antibiotics)</td>\n</tr>\n<tr>\n<td>Stool and urine culture</td>\n<td>Positive from 2nd–3rd week; detect carriers</td>\n</tr>\n<tr>\n<td><strong>Widal test</strong></td>\n<td>Antibodies from 2nd week; rising titre more useful; low specificity in endemic areas</td>\n</tr>\n<tr>\n<td>Rapid antibody tests (Typhidot etc.)</td>\n<td>Supportive</td>\n</tr>\n<tr>\n<td>CBC</td>\n<td>Leucopenia, relative lymphocytosis</td>\n</tr>\n<tr>\n<td>LFT</td>\n<td>Raised enzymes</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Management</strong></p>\n<ol>\n<li><strong>Antibiotics</strong> (guided by local resistance; high fluoroquinolone resistance in Bangladesh):\n<ul>\n<li>Uncomplicated: <strong>oral azithromycin</strong> (7 days) or cefixime.</li>\n<li>Severe / complicated: <strong>IV ceftriaxone</strong> (10–14 days).</li>\n<li>Change according to culture sensitivity (carbapenem for extensively resistant strains).</li>\n</ul>\n</li>\n<li><strong>Supportive</strong>: rest, fluids, nutritious soft diet, paracetamol (no NSAIDs).</li>\n<li><strong>Complications</strong>: watch for intestinal bleeding and perforation (surgery), encephalopathy.</li>\n<li><strong>Follow-up</strong>: stool cultures to detect carriers; treat carriers (prolonged antibiotics, cholecystectomy if gallstones).</li>\n<li><strong>Public health</strong>: notification; exclude food handlers until negative cultures; hygiene; <strong>typhoid conjugate vaccine</strong>; safe water and food.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.646","n":646,"part":11,"topic":"Communicable Diseases","stars":0,"years":["06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Enteric Fever (Typhoid)","q":"<p>Mention the complications of typhoid fever.</p>","a":"<p><strong>Complications of typhoid fever</strong></p>\n<ol>\n<li><strong>Intestinal haemorrhage</strong> and <strong>perforation</strong> (usually 3rd week) → peritonitis.</li>\n<li><strong>Toxic myocarditis</strong>; shock.</li>\n<li><strong>Hepatitis</strong>, cholecystitis.</li>\n<li><strong>Typhoid encephalopathy</strong>, meningitis, psychosis.</li>\n<li>Pneumonia, bronchitis.</li>\n<li>Osteomyelitis, arthritis.</li>\n<li>Nephritis; DIC.</li>\n<li><strong>Relapse</strong>.</li>\n<li><strong>Chronic carrier state</strong> (gall bladder).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.647","n":647,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"MuMC (2nd Final C3)","asked":"","note":"","kind":"","sub":"Enteric Fever (Typhoid)","q":"<p>Identify the major environmental and behavioral factors contributing to transmission of typhoid fever.</p>","a":"<p><strong>Environmental and behavioural factors in typhoid transmission</strong></p>\n<p><strong>Environmental</strong></p>\n<ol>\n<li><strong>Unsafe drinking water</strong>: contaminated piped supply (leaking pipes near sewers), wells.</li>\n<li><strong>Poor sanitation</strong>; open defecation; inadequate sewage treatment.</li>\n<li><strong>Flies</strong>; refuse.</li>\n<li><strong>Floods</strong>, monsoon; crowding in slums.</li>\n<li>Vegetables irrigated with sewage.</li>\n</ol>\n<p><strong>Behavioural</strong></p>\n<ol>\n<li>Eating <strong>street food</strong>, raw salads, cut fruits, ice, ice cream.</li>\n<li>Poor <strong>hand-washing</strong>.</li>\n<li><strong>Carriers working as food handlers</strong>.</li>\n<li>Not boiling water; unsafe storage.</li>\n<li>Self-medication with antibiotics (resistance, carriers).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.648","n":648,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Dengue Fever","q":"<p>Appraise the recent dengue crisis in Bangladesh.</p>","a":"<p><strong>Recent dengue crisis in Bangladesh</strong></p>\n<p><strong>A. Situation</strong></p>\n<ol>\n<li>Dengue became a major problem from 2000; large outbreak in <strong>2019</strong> (over 100,000 hospitalised cases).</li>\n<li><strong>2023: the worst epidemic</strong> so far, with about <strong>321,000 hospitalised cases and over 1,700 deaths</strong> (DGHS data); high transmission continued in following years.</li>\n<li>Spread from <strong>Dhaka to all 64 districts</strong>, including rural areas.</li>\n<li>Season lengthened; cases now occur almost <strong>year-round</strong>, peaking in <strong>July–October</strong>.</li>\n<li>Shift in <strong>serotypes</strong> (e.g., DENV-2, DENV-3) → more severe secondary infections; higher case fatality.</li>\n</ol>\n<p><strong>B. Causes</strong></p>\n<ol>\n<li><strong>Unplanned urbanisation</strong>, construction sites, stored water, discarded containers, poor waste management.</li>\n<li><strong>Climate change</strong>: higher temperature, longer and erratic monsoon.</li>\n<li>Spread of <em><strong>Aedes albopictus</strong></em> to rural areas.</li>\n<li><strong>Weak vector control</strong>: irregular larval surveillance, insecticide resistance, fogging over source reduction.</li>\n<li>Low <strong>community participation</strong> and awareness.</li>\n<li><strong>Health system strain</strong>: crowded hospitals, late presentation, limited fluid-management capacity outside Dhaka.</li>\n</ol>\n<p><strong>C. Gaps and lessons</strong></p>\n<p>Need for year-round <strong>integrated vector management</strong>, strong surveillance (Breteau index), early detection (NS1 testing), standard case management at all levels, decentralised care, coordination between city corporations, DGHS and communities, research (vaccines, <em>Wolbachia</em>).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.649","n":649,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22Nov"],"colleges":"DMC (2nd Assess D2)","asked":"epidemiological determinants of dengue; how to prevent dengue in an urban community","note":"","kind":"","sub":"Dengue Fever","q":"<p>Mention the epidemiology of dengue fever with preventive measures at present situation in Bangladesh.</p>","a":"<p><strong>Epidemiology of dengue</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Agent</strong></td>\n<td>Dengue virus (flavivirus), <strong>4 serotypes</strong> (DENV-1 to 4); infection gives lifelong immunity to that serotype only</td>\n</tr>\n<tr>\n<td><strong>Vector</strong></td>\n<td><em><strong>Aedes aegypti</strong></em> (main, urban, day-biter); <em>Ae. albopictus</em> (peri-urban, rural)</td>\n</tr>\n<tr>\n<td><strong>Reservoir</strong></td>\n<td>Man and mosquito (transovarial transmission in mosquitoes)</td>\n</tr>\n<tr>\n<td><strong>Host</strong></td>\n<td>All ages; <strong>secondary infection with a different serotype</strong> → higher risk of <strong>severe dengue</strong> (antibody-dependent enhancement); infants, elderly, pregnant women, people with comorbidities at risk</td>\n</tr>\n<tr>\n<td><strong>Environment</strong></td>\n<td><strong>Monsoon (June–October)</strong>, warm, humid; urban containers holding clean water; construction sites</td>\n</tr>\n<tr>\n<td><strong>Transmission</strong></td>\n<td>Bite of infected female <em>Aedes</em></td>\n</tr>\n<tr>\n<td><strong>Extrinsic incubation</strong></td>\n<td>8–12 days in mosquito</td>\n</tr>\n<tr>\n<td><strong>Incubation period</strong></td>\n<td><strong>4–10 days</strong> (3–14)</td>\n</tr>\n<tr>\n<td><strong>Clinical (WHO 2009)</strong></td>\n<td>Dengue without warning signs; dengue <strong>with warning signs</strong> (abdominal pain, persistent vomiting, bleeding, lethargy, liver enlargement, rising haematocrit with falling platelets); <strong>severe dengue</strong> (shock, severe bleeding, organ failure)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Preventive measures in the present situation of Bangladesh</strong></p>\n<ol>\n<li><strong>Source reduction</strong>: weekly emptying, cleaning and covering of water containers; remove tyres and trash; manage construction sites, rooftop gardens.</li>\n<li><strong>Larviciding</strong> (temephos, Bti) where containers cannot be removed.</li>\n<li><strong>Targeted adult control</strong> (fogging) around cases in outbreaks.</li>\n<li><strong>Entomological surveillance</strong> (Breteau index) and case surveillance, year-round.</li>\n<li><strong>Personal protection</strong>: daytime nets, repellents, long clothes, screens.</li>\n<li><strong>Community mobilisation</strong> and school campaigns; legal action against breeding sites.</li>\n<li><strong>Early diagnosis (NS1)</strong> and <strong>standard case management</strong> (fluids, avoid NSAIDs) at all levels to prevent deaths.</li>\n<li>Intersectoral coordination (city corporations, local government, DGHS).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.650","n":650,"part":11,"topic":"Communicable Diseases","stars":3,"years":["25Nov","22Nov","22M","21M","18Nov","16Ju","06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Dengue Fever","q":"<p>How can dengue be controlled? Enumerate the preventive measures for dengue fever / DF and DHF.</p>","a":"<p><strong>Control and prevention of dengue (DF / DHF)</strong></p>\n<p><strong>A. Vector control (main measure)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Approach</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Environmental (source reduction)</strong></td>\n<td>Eliminate container breeding sites; cover water storage; proper solid waste disposal; weekly cleaning; piped water supply</td>\n</tr>\n<tr>\n<td><strong>Chemical</strong></td>\n<td>Larvicides (temephos), adulticides (space spraying in outbreaks)</td>\n</tr>\n<tr>\n<td><strong>Biological</strong></td>\n<td>Larvivorous fish, copepods, Bti; <em>Wolbachia</em>-infected mosquitoes (research)</td>\n</tr>\n<tr>\n<td><strong>Integrated vector management</strong></td>\n<td>Combination with community participation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Personal protection</strong></p>\n<p>Bed nets (including daytime), repellents, long-sleeved clothes, window screens, coils and vaporisers.</p>\n<p><strong>C. Surveillance</strong></p>\n<p>Case surveillance and early warning; entomological indices (house, container, <strong>Breteau</strong> index); lab confirmation (NS1, IgM).</p>\n<p><strong>D. Case management (prevent deaths)</strong></p>\n<p>Early diagnosis; careful <strong>fluid management</strong>; monitoring haematocrit and platelets; recognise warning signs; avoid aspirin/NSAIDs; refer severe cases.</p>\n<p><strong>E. Community and intersectoral action</strong></p>\n<p>Health education; community clean-up drives; school involvement; legislation; coordination of city corporations, DGHS, DPHE.</p>\n<p><strong>F. Vaccines</strong></p>\n<p>Dengue vaccines exist (e.g., TAK-003, recommended by WHO for some high-transmission settings) but are not part of Bangladesh's routine programme.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.651","n":651,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term D2)","asked":"","note":"","kind":"","sub":"Dengue Fever","q":"<p>What is the critical phase of dengue illness? Mention three warning signs of severe dengue. Why is source reduction more important than relying only on insecticides for dengue control?</p>","a":"<p><strong>Critical phase of dengue</strong></p>\n<p>The period around <strong>defervescence</strong> (usually days <strong>3–7</strong> of illness), lasting <strong>24–48 hours</strong>, when <strong>plasma leakage</strong> (increased capillary permeability) may occur → haemoconcentration, fluid in pleura and abdomen, <strong>shock</strong>, bleeding and organ damage. Falling fever here does not mean recovery.</p>\n<p><strong>Three warning signs of severe dengue (WHO)</strong></p>\n<ol>\n<li><strong>Abdominal pain</strong> or tenderness.</li>\n<li><strong>Persistent vomiting</strong>.</li>\n<li><strong>Mucosal bleeding</strong>; also clinical fluid accumulation, lethargy or restlessness, liver enlargement &gt;2 cm, <strong>rising haematocrit with rapid fall in platelets</strong>.</li>\n</ol>\n<p><strong>Why source reduction matters more than insecticides alone</strong></p>\n<ol>\n<li><em>Aedes</em> breeds in <strong>containers in and around homes</strong>; removing them stops new mosquitoes at the source.</li>\n<li>Insecticides (fogging) kill only <strong>adults present at that time</strong>; effect is <strong>temporary</strong>; indoor-resting <em>Aedes</em> often escape.</li>\n<li><strong>Eggs survive drying for months</strong> → only container removal or cleaning breaks the cycle.</li>\n<li><strong>Insecticide resistance</strong> develops with repeated use.</li>\n<li>Insecticides harm the <strong>environment</strong>, non-target species and health; give false sense of safety.</li>\n<li>Source reduction is <strong>cheap, sustainable</strong> and builds <strong>community participation</strong>.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.652","n":652,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"MuMC (2nd Final B3)","asked":"","note":"","kind":"","sub":"Dengue Fever","q":"<p>Enlist the classification &amp; grading of severity of dengue infection as per WHO.</p>","a":"<p><strong>WHO classification of dengue (2009)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Dengue without warning signs</strong></td>\n<td>Fever with two of: nausea/vomiting, rash, aches and pains, positive tourniquet test, leucopenia</td>\n</tr>\n<tr>\n<td><strong>Dengue with warning signs</strong></td>\n<td>Abdominal pain, persistent vomiting, fluid accumulation, mucosal bleeding, lethargy/restlessness, liver &gt;2 cm, rising haematocrit with falling platelets</td>\n</tr>\n<tr>\n<td><strong>Severe dengue</strong></td>\n<td><strong>Severe plasma leakage</strong> → shock (dengue shock syndrome) or fluid accumulation with respiratory distress; <strong>severe bleeding</strong>; <strong>severe organ involvement</strong> (AST/ALT ≥1,000, impaired consciousness, heart or other organs)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Older WHO grading (1997): DHF grades</strong></p>\n<table>\n<thead>\n<tr>\n<th>Grade</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>I</td>\n<td>Fever + positive tourniquet test (no spontaneous bleeding)</td>\n</tr>\n<tr>\n<td>II</td>\n<td>Grade I + <strong>spontaneous bleeding</strong></td>\n</tr>\n<tr>\n<td>III</td>\n<td><strong>Circulatory failure</strong>: rapid weak pulse, narrow pulse pressure (≤20 mmHg), hypotension</td>\n</tr>\n<tr>\n<td>IV</td>\n<td><strong>Profound shock</strong>: undetectable pulse and BP</td>\n</tr>\n</tbody>\n</table>\n<p>Grades III and IV = <strong>dengue shock syndrome</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.653","n":653,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"DMC (2nd Assess B5)","asked":"","note":"","kind":"Case-based","sub":"Dengue Fever","q":"<p>City Corporation team identified increasing dengue cases in urban slums. Many households have stagnant water around their homes. [7]</p>\n<ul>\n<li>a) Identify four environmental factors contributing to dengue transmission in this community. (2)</li>\n<li>b) Describe the measures that can be taken to control vector. (2)</li>\n<li>c) Mention measures for protecting individuals from Aedes mosquito bites. (1.5)</li>\n<li>d) Outline the role of community awareness in dengue prevention. (1.5)</li>\n</ul>","a":"<p><strong>a) Environmental factors (2)</strong></p>\n<ol>\n<li><strong>Stagnant water</strong> around houses and in containers (pots, drums, tyres, tins, plastic waste).</li>\n<li><strong>Water storage</strong> in uncovered containers (irregular piped supply in slums).</li>\n<li><strong>Poor solid-waste disposal</strong> and blocked drains.</li>\n<li><strong>Crowded housing</strong>, poor housing with dark indoor resting places.</li>\n<li>Warm, humid <strong>monsoon</strong> climate; construction sites nearby.</li>\n</ol>\n<p><strong>b) Vector control measures (2)</strong></p>\n<ol>\n<li><strong>Source reduction</strong>: empty, clean, cover or destroy containers weekly; remove solid waste; fill pits.</li>\n<li><strong>Larviciding</strong> (temephos, Bti) in containers that cannot be removed.</li>\n<li><strong>Biological control</strong>: larvivorous fish in water tanks.</li>\n<li><strong>Space spraying</strong> (fogging) around cases during outbreaks.</li>\n<li><strong>Entomological surveillance</strong> (Breteau index); regular inspection by city corporation.</li>\n</ol>\n<p><strong>c) Personal protection (1.5)</strong></p>\n<p>Bed nets (also for daytime naps), repellents, long-sleeved clothes, window and door screens, coils/vaporisers.</p>\n<p><strong>d) Role of community awareness (1.5)</strong></p>\n<ol>\n<li>People <strong>find and remove breeding sites</strong> in their own homes (weekly &quot;search and destroy&quot;).</li>\n<li><strong>Early recognition</strong> of fever and warning signs → early care, fewer deaths.</li>\n<li>Use of <strong>personal protection</strong>.</li>\n<li><strong>Cooperation</strong> with city corporation teams; community clean-up drives.</li>\n<li>Sustains control between outbreaks.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.654","n":654,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"SSMC (2nd Term C5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A 30-year-old man comes to the emergency department of the hospital with high fever for 05 days along with headache, rash, abdominal pain &amp; vomiting. [3+4]</p>\n<ul>\n<li>a) Identify the disease and mention its warning signs.</li>\n<li>b) Write down preventive measures of the disease from a public health perspective.</li>\n</ul>","a":"<p><strong>a) Disease and warning signs (3)</strong></p>\n<p><strong>Probable dengue fever</strong> (high fever, headache, rash, abdominal pain, vomiting; day 5 = critical phase). Confirm with NS1 antigen / IgM; CBC (platelets, haematocrit).</p>\n<p><strong>Warning signs</strong>: abdominal pain or tenderness; persistent vomiting; mucosal bleeding; fluid accumulation (ascites, pleural effusion); lethargy, restlessness; liver enlargement &gt;2 cm; rising haematocrit with rapidly falling platelets.</p>\n<p><strong>b) Public health preventive measures (4)</strong></p>\n<ol>\n<li><strong>Vector control</strong>: source reduction, larviciding, targeted fogging; integrated vector management.</li>\n<li><strong>Surveillance</strong>: case reporting, larval indices (Breteau), early warning.</li>\n<li><strong>Personal protection</strong>: nets, repellents, clothing, screens.</li>\n<li><strong>Community mobilisation</strong> and health education; school programmes.</li>\n<li><strong>Legislation</strong>: city corporation inspection; fines for breeding sites.</li>\n<li><strong>Case management</strong>: standard guidelines at all levels; early referral; avoid NSAIDs → reduces deaths.</li>\n<li><strong>Intersectoral coordination</strong>: city corporations, DGHS, local government, construction regulators.</li>\n<li>Research and vaccines when suitable.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.655","n":655,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>Write what you know about the epidemiology of malaria.</p>","a":"<p><strong>Epidemiology of malaria</strong></p>\n<p><strong>A. Agent</strong></p>\n<p><em>Plasmodium falciparum</em> (most dangerous; predominant in Bangladesh), <em>P. vivax</em>, <em>P. malariae</em>, <em>P. ovale</em> (and <em>P. knowlesi</em>).</p>\n<p><strong>B. Reservoir</strong>: man (cases and asymptomatic carriers with gametocytes).</p>\n<p><strong>C. Vector</strong></p>\n<p><strong>Female <em>Anopheles</em></strong> mosquito; in Bangladesh <em>An. dirus</em>, <em>An. minimus</em>, <em>An. philippinensis</em>, <em>An. sundaicus</em> (coastal); night biters.</p>\n<p><strong>D. Host factors</strong></p>\n<ol>\n<li>Age: children under 5 and non-immune adults most affected.</li>\n<li><strong>Pregnancy</strong>: severe malaria, anaemia, LBW, abortion.</li>\n<li>Immunity: partial immunity after repeated infections.</li>\n<li>Genetic protection: sickle-cell trait, G6PD deficiency, thalassaemia, Duffy-negative (vivax).</li>\n<li>Occupation and behaviour: forest workers, migrants, soldiers, sleeping outdoors.</li>\n</ol>\n<p><strong>E. Environmental factors</strong></p>\n<p>Temperature 20–30 °C, humidity &gt;60%, <strong>rainfall</strong> (breeding), forested hilly areas, irrigation, deforestation, population movement.</p>\n<p><strong>F. Transmission</strong></p>\n<p>Bite of infected female <em>Anopheles</em>; also blood transfusion, congenital, shared needles.</p>\n<p><strong>G. Incubation period</strong></p>\n<p><em>P. falciparum</em> ~12 days; <em>P. vivax</em> ~14 days; <em>P. malariae</em> ~28 days; <em>P. ovale</em> ~17 days.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.656","n":656,"part":11,"topic":"Communicable Diseases","stars":3,"years":["21M"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>How can you detect a case of malaria?</p>","a":"<p><strong>Detection of a malaria case</strong></p>\n<p><strong>A. Clinical suspicion</strong></p>\n<p>Fever (with chills, rigors, sweating; periodicity), headache, body ache, anaemia, splenomegaly; residence in or travel to an endemic area.</p>\n<p><strong>B. Laboratory confirmation (test all suspected cases before treatment)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Test</th>\n<th>Remarks</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Microscopy</strong> (thick and thin blood smears, Giemsa)</td>\n<td>Gold standard; species, parasite density</td>\n</tr>\n<tr>\n<td><strong>Rapid diagnostic test (RDT)</strong></td>\n<td>Detects HRP-2 (Pf) and pLDH (Pv/pan); quick; used by CHWs</td>\n</tr>\n<tr>\n<td>PCR</td>\n<td>Low-density infections; research; elimination</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Methods of case detection</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Passive case detection</strong></td>\n<td>Fever patients tested at health facilities</td>\n</tr>\n<tr>\n<td><strong>Active case detection</strong></td>\n<td>Health workers visit households regularly in endemic areas to test fever cases</td>\n</tr>\n<tr>\n<td><strong>Reactive case detection</strong></td>\n<td>Testing household members and neighbours of each confirmed case (elimination phase)</td>\n</tr>\n<tr>\n<td>Mass blood surveys</td>\n<td>In outbreaks or high-risk groups</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.657","n":657,"part":11,"topic":"Communicable Diseases","stars":3,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>How can you proceed to perform community diagnosis of an outbreak of <em>Falciparum</em> malaria?</p>","a":"<p><strong>Community diagnosis of a falciparum malaria outbreak</strong></p>\n<ol>\n<li><strong>Verify diagnosis</strong> (RDT / microscopy) and <strong>confirm outbreak</strong> (compare with previous weeks and years).</li>\n<li><strong>Define area and population</strong> at risk; map villages.</li>\n<li><strong>Active case search</strong>: house-to-house fever survey with RDTs; line list (time, place, person).</li>\n<li><strong>Calculate indices</strong>:\n<ul>\n<li>Annual parasite incidence (API) = confirmed cases ÷ population × 1,000</li>\n<li>Slide positivity rate, slide falciparum rate</li>\n<li>Annual blood examination rate</li>\n<li>Spleen rate and parasite rate in children 2–9 years</li>\n</ul>\n</li>\n<li><strong>Entomological survey</strong>: vector species, density, breeding sites, man-biting rate, sporozoite rate, insecticide susceptibility.</li>\n<li><strong>Identify risk groups and factors</strong>: forest workers, migrants, rainfall, new construction, low LLIN use, drug stock-outs.</li>\n<li><strong>Plan control</strong>: treatment, LLINs/IRS, health education; monitor.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.658","n":658,"part":11,"topic":"Communicable Diseases","stars":0,"years":["06M"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>What do you mean by Roll Back Malaria?</p>","a":"<p><strong>Roll Back Malaria (RBM)</strong></p>\n<p>A <strong>global partnership</strong> launched in <strong>1998</strong> by WHO, UNICEF, UNDP and the World Bank (with countries, donors, NGOs, private sector) to <strong>reduce the malaria burden</strong> (initial target: halve malaria deaths by 2010).</p>\n<p><strong>Core strategies</strong></p>\n<ol>\n<li><strong>Early detection and prompt, effective treatment</strong>.</li>\n<li><strong>Multiple prevention</strong>: insecticide-treated nets, IRS, intermittent preventive treatment in pregnancy.</li>\n<li><strong>Well-coordinated action</strong> and health system strengthening.</li>\n<li><strong>Dynamic global movement</strong>: advocacy, funding.</li>\n<li><strong>Focused research</strong> (drugs, vaccines, insecticides).</li>\n<li>Epidemic preparedness.</li>\n</ol>\n<p>Now called the <strong>RBM Partnership to End Malaria</strong>, supporting the WHO Global Technical Strategy 2016–2030.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.659","n":659,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16Ju","12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>Write down the malaria control measures in Bangladesh.</p>","a":"<p><strong>Malaria control (elimination) measures in Bangladesh</strong></p>\n<p><strong>Programme</strong>: <strong>National Malaria Elimination Programme (NMEP)</strong>, DGHS, with <strong>BRAC</strong>-led NGO consortium; Global Fund support; aim: <strong>elimination by 2030</strong>.</p>\n<p><strong>A. Early diagnosis and prompt treatment</strong></p>\n<ol>\n<li><strong>RDT and microscopy</strong> for all fever cases in endemic areas; community health workers test at village level.</li>\n<li>Treatment (national guideline):\n<ul>\n<li><em>P. falciparum</em>: <strong>artemether–lumefantrine</strong> (ACT) + single low-dose primaquine (blocks transmission).</li>\n<li><em>P. vivax</em>: chloroquine + <strong>primaquine</strong> (14 days) for radical cure.</li>\n<li><strong>Severe malaria</strong>: injectable <strong>artesunate</strong>; referral.</li>\n</ul>\n</li>\n</ol>\n<p><strong>B. Vector control</strong></p>\n<ol>\n<li><strong>Long-lasting insecticidal nets</strong> (mass and continuous distribution) in high-risk areas.</li>\n<li><strong>Indoor residual spraying</strong> in selected foci.</li>\n<li>Larval source management where feasible.</li>\n</ol>\n<p><strong>C. Surveillance</strong></p>\n<p>Case-based surveillance; case and focus investigation; reactive case detection; DHIS2 reporting; entomological surveillance.</p>\n<p><strong>D. Special groups</strong></p>\n<p>Forest workers, migrants, ethnic communities, border areas, Rohingya camps; <strong>cross-border collaboration</strong> with India and Myanmar.</p>\n<p><strong>E. Supporting</strong></p>\n<p>Health education (BCC), community participation, epidemic preparedness, research, quality-assured drugs and diagnostics.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.660","n":660,"part":11,"topic":"Communicable Diseases","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>Discuss stages of lymphatic filariasis.</p>","a":"<p><strong>Stages of lymphatic filariasis (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Asymptomatic amicrofilaraemia</strong></td>\n<td>Exposed people, no microfilariae, no symptoms</td>\n</tr>\n<tr>\n<td><strong>2. Asymptomatic microfilaraemia</strong></td>\n<td>Microfilariae in blood, no symptoms; important reservoir</td>\n</tr>\n<tr>\n<td><strong>3. Acute manifestations</strong></td>\n<td><strong>Filarial fever</strong>, retrograde <strong>lymphangitis</strong>, <strong>lymphadenitis</strong>, funiculitis, <strong>epididymo-orchitis</strong> (recurrent attacks)</td>\n</tr>\n<tr>\n<td><strong>4. Chronic obstructive lesions</strong></td>\n<td><strong>Hydrocele</strong>, <strong>lymphoedema</strong>, <strong>elephantiasis</strong> (legs, scrotum, arms, breast, vulva), <strong>chyluria</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Occult filariasis</strong>: tropical pulmonary eosinophilia (cough, wheeze, high eosinophils, no microfilariae in blood).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.661","n":661,"part":11,"topic":"Communicable Diseases","stars":0,"years":["04M"],"colleges":"ShSMC (2nd Term A5)","asked":"four clinical manifestations of lymphatic filariasis","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>Write down the signs of lymphatic filariasis.</p>","a":"<p><strong>Signs of lymphatic filariasis</strong></p>\n<ol>\n<li><strong>Filarial fever</strong> with chills (recurrent).</li>\n<li><strong>Lymphangitis</strong>: red, tender streak spreading <strong>downward</strong> (retrograde) along limbs.</li>\n<li><strong>Lymphadenitis</strong>: tender enlarged inguinal / axillary nodes.</li>\n<li><strong>Funiculitis, epididymo-orchitis</strong>.</li>\n<li><strong>Hydrocele</strong> (commonest chronic sign in men).</li>\n<li><strong>Lymphoedema</strong> → <strong>elephantiasis</strong>: pitting then non-pitting swelling, thickened skin, folds, warts.</li>\n<li><strong>Chyluria</strong> (milky urine).</li>\n<li>Tropical pulmonary eosinophilia (occult).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.662","n":662,"part":11,"topic":"Communicable Diseases","stars":3,"years":["12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>Explain &quot;Twin Pillars of Filariasis elimination&quot;.</p>","a":"<p><strong>Twin pillars of the Global Programme to Eliminate Lymphatic Filariasis (WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Pillar</th>\n<th>Aim</th>\n<th>Strategy</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Interrupt transmission</strong></td>\n<td>Stop spread of infection</td>\n<td><strong>Mass drug administration (MDA)</strong>: annual single dose to the whole at-risk population (≥2 years, excluding pregnant women and the very sick) of <strong>DEC + albendazole</strong> (or ivermectin + DEC + albendazole: IDA), for at least <strong>5 years</strong> with <strong>≥65% coverage of the total population</strong>; plus vector control support</td>\n</tr>\n<tr>\n<td><strong>2. Alleviate suffering</strong></td>\n<td>Reduce disability in affected people</td>\n<td><strong>Morbidity management and disability prevention (MMDP)</strong>: lymphoedema care (washing, skin care, elevation, exercise, footwear, treating entry lesions), management of acute attacks, <strong>hydrocele surgery</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.663","n":663,"part":11,"topic":"Communicable Diseases","stars":3,"years":["12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Malaria & Filariasis","q":"<p>Write down the ongoing filariasis elimination programme in Bangladesh.</p>","a":"<p><strong>Filariasis elimination programme in Bangladesh</strong></p>\n<ol>\n<li><strong>National programme</strong> started in <strong>2001</strong>; filariasis was endemic in <strong>19 of 64 districts</strong> (mainly northern and north-western).</li>\n<li><strong>Mass drug administration</strong> (DEC + albendazole) in endemic districts until targets were met.</li>\n<li><strong>Transmission assessment surveys</strong> to confirm interruption.</li>\n<li><strong>Morbidity management</strong>: lymphoedema care, hydrocele surgery, support through community clinics.</li>\n<li><strong>WHO validated elimination as a public health problem in May 2023</strong>.</li>\n<li>Current focus (national strategic plan 2018–2025): <strong>post-validation surveillance</strong>, response to any recrudescence, continued MMDP.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO SEARO, 2023, https://www.who.int/southeastasia/news/detail/13-05-2023-bangladesh-eliminates-lymphatic-filariasis</p>"},{"id":"DU.664","n":664,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term A5)","asked":"","note":"","kind":"Case-based","sub":"Malaria & Filariasis","q":"<p>A middle-aged person from a mosquito-infested area develops recurrent attacks of fever and progressive swelling of the lower limb. [2+2+3]</p>\n<ul>\n<li>a) Mention four clinical manifestations of lymphatic filariasis. (2)</li>\n<li>b) Describe three methods used for diagnosis of lymphatic filariasis. (2)</li>\n<li>c) Discuss five measures for prevention and control of lymphatic filariasis. (3)</li>\n</ul>","a":"<p><strong>a) Four clinical manifestations (2)</strong></p>\n<p>Recurrent filarial fever; lymphangitis and lymphadenitis; lymphoedema / elephantiasis of the limb; hydrocele and epididymo-orchitis (also chyluria).</p>\n<p><strong>b) Three methods of diagnosis (2)</strong></p>\n<ol>\n<li><strong>Night blood smear</strong> (10 pm–2 am) for microfilariae: thick film, concentration (Knott's), membrane filtration.</li>\n<li><strong>Circulating filarial antigen test</strong> (rapid immunochromatographic card / test strip) for <em>W. bancrofti</em>: any time of day.</li>\n<li><strong>Ultrasound</strong> of scrotum / lymphatics: &quot;filarial dance sign&quot; (moving adult worms).<br />\n(Also antibody tests, PCR, eosinophil count, lymphoscintigraphy.)</li>\n</ol>\n<p><strong>c) Five prevention and control measures (3)</strong></p>\n<ol>\n<li><strong>Mass drug administration</strong> (DEC + albendazole ± ivermectin), annually.</li>\n<li><strong>Vector control</strong> of <em>Culex</em>: clean drains, larvicides, polystyrene beads in pits and cesspools, environmental sanitation.</li>\n<li><strong>Personal protection</strong>: bed nets, repellents, screens.</li>\n<li><strong>Morbidity management and disability prevention</strong>: lymphoedema care, hydrocele surgery.</li>\n<li><strong>Surveillance</strong> (transmission assessment surveys), <strong>health education</strong> and community participation.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.665","n":665,"part":11,"topic":"Communicable Diseases","stars":0,"years":["06Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Kala-Azar","q":"<p>Write down the clinical diagnosis of kala-azar.</p>","a":"<p><strong>Clinical diagnosis of kala-azar</strong></p>\n<p><strong>Clinical case definition (WHO)</strong>: a person from an <strong>endemic area</strong> with <strong>fever for more than 2 weeks</strong> and <strong>splenomegaly</strong>, not responding to antimalarials/antibiotics.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.666","n":666,"part":11,"topic":"Communicable Diseases","stars":0,"years":["07Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Kala-Azar","q":"<p>Mention the lab diagnosis of visceral leishmaniasis.</p>","a":"<p><strong>Laboratory diagnosis of visceral leishmaniasis</strong></p>\n<table>\n<thead>\n<tr>\n<th>Test</th>\n<th>Remarks</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>rK39 rapid diagnostic test</strong> (antibody)</td>\n<td>Main field test in South Asia; high sensitivity and specificity; used with clinical case definition</td>\n</tr>\n<tr>\n<td><strong>Parasitological</strong>: aspirate for LD bodies (amastigotes)</td>\n<td><strong>Splenic</strong> (most sensitive, ~95%), bone marrow, lymph node; Giemsa stain</td>\n</tr>\n<tr>\n<td>Culture (NNN medium)</td>\n<td>Promastigotes</td>\n</tr>\n<tr>\n<td>Direct agglutination test (DAT)</td>\n<td>Serology</td>\n</tr>\n<tr>\n<td><strong>PCR</strong></td>\n<td>Sensitive; PKDL, relapse</td>\n</tr>\n<tr>\n<td>CBC</td>\n<td><strong>Pancytopenia</strong></td>\n</tr>\n<tr>\n<td>Serum proteins</td>\n<td>Hypergammaglobulinaemia, reversed albumin–globulin ratio (aldehyde test: old)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.667","n":667,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Kala-Azar","q":"<p>How can you treat a case of kala-azar?</p>","a":"<p><strong>Treatment of kala-azar (South Asia / Bangladesh national guideline)</strong></p>\n<p><strong>A. Specific treatment</strong></p>\n<table>\n<thead>\n<tr>\n<th>Regimen</th>\n<th>Details</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>First line: single-dose liposomal amphotericin B</strong> (AmBisome)</td>\n<td><strong>10 mg/kg IV once</strong>, in hospital</td>\n</tr>\n<tr>\n<td>Combination regimens</td>\n<td>Liposomal amphotericin B + miltefosine; paromomycin + miltefosine</td>\n</tr>\n<tr>\n<td>Miltefosine monotherapy</td>\n<td>Oral, 28 days (not in pregnancy; contraception needed)</td>\n</tr>\n<tr>\n<td>Conventional amphotericin B deoxycholate</td>\n<td>Alternative (more toxic)</td>\n</tr>\n<tr>\n<td>Sodium stibogluconate</td>\n<td>Older; resistance in South Asia</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. PKDL</strong></p>\n<p>Miltefosine for 12 weeks (or liposomal amphotericin B courses).</p>\n<p><strong>C. Supportive</strong></p>\n<p>Nutrition, treat anaemia (transfusion if severe), treat infections, rest.</p>\n<p><strong>D. Follow-up</strong></p>\n<p>At 6 and 12 months for relapse and <strong>PKDL</strong>; HIV testing in relapsing cases.</p>\n<p><strong>E. Public health</strong></p>\n<p>Notification, active case detection around the case, IRS and nets, health education.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.668","n":668,"part":11,"topic":"Communicable Diseases","stars":3,"years":["19M","17M"],"colleges":"ShSMC (2nd Term A3)","asked":"two community-level measures for prevention and control","note":"","kind":"","sub":"Kala-Azar","q":"<p>What are the control measures for kala-azar / leishmaniasis?</p>","a":"<p><strong>Control of kala-azar</strong></p>\n<p><strong>A. Early diagnosis and complete treatment</strong></p>\n<p>rK39 test; <strong>single-dose liposomal amphotericin B</strong>; treat <strong>PKDL</strong> (reservoir in anthroponotic kala-azar).</p>\n<p><strong>B. Integrated vector management (sandfly)</strong></p>\n<ol>\n<li><strong>Indoor residual spraying</strong> (pyrethroids) of houses and cattle sheds.</li>\n<li><strong>Long-lasting insecticidal nets</strong>.</li>\n<li>Environmental management: plaster cracks, clean surroundings, keep cattle away.</li>\n</ol>\n<p><strong>C. Active case detection</strong></p>\n<p>Index-case-based search, house-to-house surveys, camps.</p>\n<p><strong>D. Surveillance</strong> of cases, vectors, treatment outcomes.</p>\n<p><strong>E. Social mobilisation</strong> and health education.</p>\n<p><strong>F. Research</strong>: new drugs, diagnostics, vector control.</p>\n<p><strong>G. Regional cooperation</strong>: <strong>Regional Kala-azar Elimination Initiative</strong> (Bangladesh, India, Nepal, 2005); target &lt;1 case per 10,000 at upazila level.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO, 2023, https://www.who.int/news/item/31-10-2023-bangladesh-achieves-historic-milestone-by-eliminating-kala-azar-as-a-public-health-problem</p>"},{"id":"DU.669","n":669,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term A3)","asked":"","note":"","kind":"","sub":"Kala-Azar","q":"<p>Write down three epidemiological factors contributing to the transmission of kala-azar.</p>","a":"<p><strong>Three epidemiological factors in kala-azar transmission</strong></p>\n<ol>\n<li><strong>Vector</strong>: <em>Phlebotomus argentipes</em> sandflies breeding in cracks of mud walls, damp soil and cattle sheds near houses.</li>\n<li><strong>Human reservoir</strong>: untreated kala-azar and <strong>PKDL</strong> cases (anthroponotic transmission in South Asia).</li>\n<li><strong>Socio-economic and housing factors</strong>: poverty, mud houses, sleeping on the floor without nets, malnutrition, HIV co-infection, migration, low awareness.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.670","n":670,"part":11,"topic":"Communicable Diseases","stars":3,"years":["21M"],"colleges":"","asked":"","note":"","kind":"","sub":"Tetanus & Anthrax","q":"<p>Enumerate the types of tetanus.</p>","a":"<p><strong>Types of tetanus</strong></p>\n<p><strong>A. Clinical types</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Generalised</strong></td>\n<td>Commonest: trismus, rigidity, spasms of whole body</td>\n</tr>\n<tr>\n<td><strong>Localised</strong></td>\n<td>Rigidity and spasms near the wound only; may progress</td>\n</tr>\n<tr>\n<td><strong>Cephalic</strong></td>\n<td>After head/face injury or otitis media; cranial nerve palsies (facial)</td>\n</tr>\n<tr>\n<td><strong>Neonatal (tetanus neonatorum)</strong></td>\n<td>Newborns, from unclean cord care; generalised form</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. By portal of entry</strong></p>\n<p>Traumatic (wounds, burns), post-surgical, <strong>puerperal / post-abortal</strong> (maternal tetanus), otogenic, after injections, idiopathic (no wound found).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.671","n":671,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22M"],"colleges":"","asked":"","note":"","kind":"","sub":"Tetanus & Anthrax","q":"<p>Write the clinical manifestations of tetanus.</p>","a":"<p><strong>Clinical manifestations of tetanus</strong></p>\n<p><strong>Incubation period</strong>: usually 6–10 days (3–21); shorter → more severe.</p>\n<ol>\n<li><strong>Trismus (lockjaw)</strong>: often the first sign.</li>\n<li><strong>Risus sardonicus</strong> (sardonic smile).</li>\n<li><strong>Stiffness</strong> of neck, back, abdomen (board-like); <strong>opisthotonus</strong>.</li>\n<li><strong>Painful reflex spasms</strong> triggered by noise, light, touch.</li>\n<li><strong>Dysphagia</strong>; <strong>laryngospasm</strong> → asphyxia.</li>\n<li><strong>Autonomic dysfunction</strong>: tachycardia, labile BP, sweating, fever.</li>\n<li>Patient remains <strong>fully conscious</strong>.</li>\n</ol>\n<p><strong>Neonatal tetanus</strong></p>\n<p>Normal baby for the first 2 days → <strong>inability to suck</strong> (usually day 3–10), excessive crying, stiffness, spasms, trismus, opisthotonus; very high mortality.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.672","n":672,"part":11,"topic":"Communicable Diseases","stars":3,"years":["13Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Tetanus & Anthrax","q":"<p>Give the immunization schedule for mothers of reproductive age group against tetanus.</p>","a":"<p><strong>TT/Td schedule for women of reproductive age (15–49 years)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dose</th>\n<th>Timing</th>\n<th>Protection</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>TT1</strong></td>\n<td>First contact / age 15 years</td>\n<td>None</td>\n</tr>\n<tr>\n<td><strong>TT2</strong></td>\n<td>At least <strong>4 weeks</strong> after TT1</td>\n<td>~3 years</td>\n</tr>\n<tr>\n<td><strong>TT3</strong></td>\n<td>At least <strong>6 months</strong> after TT2</td>\n<td>~5 years</td>\n</tr>\n<tr>\n<td><strong>TT4</strong></td>\n<td>At least <strong>1 year</strong> after TT3</td>\n<td>~10 years</td>\n</tr>\n<tr>\n<td><strong>TT5</strong></td>\n<td>At least <strong>1 year</strong> after TT4</td>\n<td><strong>Lifelong</strong> (reproductive years)</td>\n</tr>\n</tbody>\n</table>\n<p>0.5 ml IM (deltoid). Bangladesh now uses <strong>Td</strong> (tetanus-diphtheria) in place of TT.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.673","n":673,"part":11,"topic":"Communicable Diseases","stars":2,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"Tetanus & Anthrax","q":"<p>Illustrate the methods for prevention of neonatal tetanus.</p>","a":"<p><strong>Prevention of neonatal tetanus</strong></p>\n<p><strong>A. Immunisation of mothers</strong></p>\n<ol>\n<li><strong>Td/TT to all women of reproductive age</strong> (5-dose schedule).</li>\n<li>Pregnant woman without previous doses: <strong>2 doses</strong> 4 weeks apart, the second at least 2 weeks before delivery → baby &quot;protected at birth&quot;.</li>\n</ol>\n<p><strong>B. Clean delivery practices: &quot;six cleans&quot;</strong></p>\n<ol>\n<li>Clean <strong>hands</strong> of the birth attendant.</li>\n<li>Clean <strong>delivery surface</strong>.</li>\n<li>Clean <strong>blade</strong> to cut the cord.</li>\n<li>Clean <strong>cord tie</strong>.</li>\n<li>Clean <strong>cord care</strong>: <strong>7.1% chlorhexidine</strong> to the stump; <strong>nothing harmful</strong> (cow dung, ash, oil).</li>\n<li>Clean <strong>perineum</strong>.</li>\n</ol>\n<p><strong>C. Skilled birth attendance</strong> / facility delivery; clean delivery kits; training of TBAs.</p>\n<p><strong>D. Surveillance</strong>: every NT case reported and investigated; high-risk districts targeted.</p>\n<p><strong>E. Health education</strong>: hygiene, cord care, immunisation.</p>\n<p>Bangladesh achieved <strong>maternal and neonatal tetanus elimination</strong> (&lt;1 NT case per 1,000 live births in every district) through these measures.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.674","n":674,"part":11,"topic":"Communicable Diseases","stars":2,"years":["25Nov","11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Tetanus & Anthrax","q":"<p>Demonstrate the prevention / control measures of anthrax.</p>","a":"<p><strong>Prevention and control of anthrax</strong></p>\n<p><strong>A. In animals (source)</strong></p>\n<ol>\n<li><strong>Vaccination of livestock</strong> (cattle, goats) in endemic areas (e.g., Sirajganj, Pabna, Meherpur).</li>\n<li><strong>No slaughter of sick animals</strong>; meat inspection.</li>\n<li><strong>Safe disposal of carcasses</strong>: deep burial with lime or burning; <strong>do not open</strong> carcasses (spores form on exposure to air).</li>\n<li>Disinfection of contaminated areas; decontamination of hides, wool, bones.</li>\n</ol>\n<p><strong>B. In humans</strong></p>\n<ol>\n<li><strong>Health education</strong>: do not handle, slaughter or eat sick or dead animals.</li>\n<li><strong>Protective clothing</strong> for butchers, tannery and wool workers.</li>\n<li><strong>Early diagnosis and treatment</strong> (ciprofloxacin, doxycycline, penicillin).</li>\n<li><strong>Post-exposure prophylaxis</strong>: antibiotics for exposed people.</li>\n<li>Vaccination of high-risk workers (where available).</li>\n<li>Notification, outbreak investigation.</li>\n</ol>\n<p><strong>C. One Health</strong>: coordination of health, livestock and environment departments; joint surveillance.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.675","n":675,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Plague","q":"<p>Illustrate the transmission cycles of plague.</p>","a":"<p><strong>Transmission cycles of plague</strong></p>\n<pre><code>1. Wild (sylvatic) plague:\n   Wild rodents (gerbil, marmot) ⇄ wild rodent fleas\n          ↓ (man enters natural focus: hunters, farmers)\n          Man (bubonic plague)\n\n2. Domestic (urban / murine) plague:\n   Wild rodents → peri-domestic rodents → domestic rats (Rattus rattus)\n   Domestic rats ⇄ rat flea (Xenopsylla cheopis)\n          ↓ (rats die → fleas bite man)\n          Man → bubonic plague → septicaemic plague\n\n3. Pneumonic plague:\n   Bubonic / septicaemic case → secondary pneumonia\n          ↓ droplets\n   Man → man (primary pneumonic plague)\n</code></pre>\n<p><strong>Key points</strong></p>\n<ul>\n<li>Plague is primarily a disease of <strong>wild rodents</strong>; man is an accidental host.</li>\n<li><strong>Rat fall</strong> (dying rats) precedes human epidemics.</li>\n<li><strong>Blocked flea</strong> transmits bacilli by regurgitation.</li>\n<li><strong>Pneumonic plague</strong> spreads person to person and is the most fatal.</li>\n</ul>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.676","n":676,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term D4)","asked":"","note":"","kind":"","sub":"Plague","q":"<p>What are the major epidemiological determinants of plague transmission?</p>","a":"<p><strong>Epidemiological determinants of plague</strong></p>\n<ol>\n<li><strong>Agent</strong>: <em>Yersinia pestis</em>.</li>\n<li><strong>Reservoir</strong>: wild rodents in natural foci (<em>Tatera indica</em>); domestic rats.</li>\n<li><strong>Vector</strong>: rat flea <em>Xenopsylla cheopis</em>; <strong>cheopis index &gt;1</strong> indicates danger.</li>\n<li><strong>Host</strong>: man has no natural immunity; risk in hunters, farmers, people near rat-infested houses and grain stores.</li>\n<li><strong>Environment</strong>: temperature 20–25 °C, high humidity, rainfall; poor housing and sanitation, grain storage (rat harbourage); rat population density.</li>\n<li><strong>Human factors</strong>: travel and trade, overcrowding, poverty.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.677","n":677,"part":11,"topic":"Communicable Diseases","stars":3,"years":[],"colleges":"MuMC (2nd Final B5)","asked":"five other rabid animals","note":"","kind":"","sub":"Rabies","q":"<p>Write down the names of rabid animals.</p>","a":"<p><strong>Rabid animals (animals that can transmit rabies)</strong></p>\n<ol>\n<li><strong>Dog</strong> (source of most human rabies)</li>\n<li><strong>Cat</strong></li>\n<li><strong>Jackal</strong></li>\n<li><strong>Fox</strong></li>\n<li><strong>Wolf</strong></li>\n<li><strong>Mongoose</strong></li>\n<li><strong>Monkey</strong></li>\n<li><strong>Bat</strong> (vampire and other bats)</li>\n<li>Cattle, horse, goat, pig (rarely transmit)</li>\n<li>Skunk, raccoon (Americas)</li>\n</ol>\n<p>Rodents (rats, mice, squirrels) and rabbits rarely transmit rabies.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.678","n":678,"part":11,"topic":"Communicable Diseases","stars":3,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>Differentiate between street virus and fixed virus.</p>","a":"<p><strong>Street virus vs fixed virus</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Street virus</th>\n<th>Fixed virus</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Source</td>\n<td>Naturally occurring, from infected animals</td>\n<td>Laboratory strain obtained by <strong>serial intracerebral passage</strong> (Pasteur, in rabbits)</td>\n</tr>\n<tr>\n<td>Incubation period (in animals)</td>\n<td><strong>Long and variable</strong> (1–12 weeks)</td>\n<td><strong>Short and fixed</strong> (4–6 days)</td>\n</tr>\n<tr>\n<td><strong>Negri bodies</strong></td>\n<td><strong>Formed</strong></td>\n<td>Usually <strong>not formed</strong></td>\n</tr>\n<tr>\n<td>Invasion of salivary glands</td>\n<td>Yes</td>\n<td>No</td>\n</tr>\n<tr>\n<td>Pathogenicity by peripheral routes</td>\n<td>High</td>\n<td>Low (does not readily spread from periphery)</td>\n</tr>\n<tr>\n<td>Use</td>\n<td>Causes natural rabies</td>\n<td>Used for <strong>vaccine production</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.679","n":679,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22Nov","16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>What are the (clinical) features of rabies?</p>","a":"<p><strong>Clinical features of rabies</strong></p>\n<p><strong>Incubation period</strong>: usually 1–3 months (from days to years); shorter with bites on face, head, hands and severe bites.</p>\n<p><strong>1. Prodromal stage (2–10 days)</strong></p>\n<p>Fever, headache, malaise, sore throat; <strong>pain, tingling or numbness at the bite site</strong> (characteristic); anxiety.</p>\n<p><strong>2. Acute neurological stage</strong></p>\n<table>\n<thead>\n<tr>\n<th>Furious (encephalitic) form (~80%)</th>\n<th>Paralytic (dumb) form (~20%)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Hydrophobia</strong>: painful spasms of throat on trying to drink or even seeing water</td>\n<td><strong>Ascending flaccid paralysis</strong></td>\n</tr>\n<tr>\n<td><strong>Aerophobia</strong> (spasms with air blown on face)</td>\n<td>Less agitation; hydrophobia may be absent</td>\n</tr>\n<tr>\n<td>Hyperexcitability, agitation, hallucinations, aggression</td>\n<td>Often misdiagnosed (GBS)</td>\n</tr>\n<tr>\n<td>Excess salivation, sweating; autonomic instability</td>\n<td></td>\n</tr>\n<tr>\n<td>Lucid intervals</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n<p><strong>3. Coma and death</strong></p>\n<p>Within about 1–2 weeks of onset; <strong>almost 100% fatal</strong> once symptoms appear.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.680","n":680,"part":11,"topic":"Communicable Diseases","stars":0,"years":["16M"],"colleges":"SSMC (2nd Term C2)","asked":"categorize the wound and mention immediate management","note":"","kind":"","sub":"Rabies","q":"<p>How will you manage a case bitten by a street dog?</p>","a":"<p><strong>Management of a street-dog bite</strong></p>\n<p><strong>1. Assess category of exposure (WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Exposure</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>I</strong></td>\n<td>Touching/feeding animal, licks on <strong>intact</strong> skin</td>\n<td>Wash; no PEP</td>\n</tr>\n<tr>\n<td><strong>II</strong></td>\n<td>Nibbling of uncovered skin; minor scratches/abrasions <strong>without bleeding</strong></td>\n<td>Wound care + <strong>vaccine</strong></td>\n</tr>\n<tr>\n<td><strong>III</strong></td>\n<td><strong>Transdermal bites or scratches</strong> (bleeding), licks on broken skin, saliva on mucosa, any bat exposure</td>\n<td>Wound care + <strong>vaccine</strong> + <strong>rabies immunoglobulin (RIG)</strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>2. Wound care (immediately; most important first step)</strong></p>\n<ol>\n<li><strong>Wash with soap and running water for 15 minutes</strong>.</li>\n<li>Apply <strong>antiseptic</strong> (povidone-iodine, alcohol).</li>\n<li><strong>Do not suture</strong> immediately; if needed, after RIG infiltration and with loose stitches.</li>\n<li>Do not apply chilli, oil, herbs.</li>\n<li><strong>Tetanus</strong> prophylaxis; antibiotics if infected.</li>\n</ol>\n<p><strong>3. Rabies vaccine (cell-culture)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Route (WHO 2018)</th>\n<th>Schedule</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Intradermal</strong> (0.1 ml at 2 sites)</td>\n<td>Days <strong>0, 3, 7</strong></td>\n</tr>\n<tr>\n<td><strong>Intramuscular</strong> (1 vial)</td>\n<td>Days <strong>0, 3, 7, 14–28</strong> (4 doses) or 2-1-1 (2 doses day 0, 1 on day 7, 1 on day 21)</td>\n</tr>\n</tbody>\n</table>\n<p>Bangladesh provides free intradermal vaccine at rabies prevention centres in district hospitals and UHCs.</p>\n<p><strong>4. RIG (category III)</strong></p>\n<p>Equine RIG 40 IU/kg or human RIG 20 IU/kg, <strong>infiltrated into and around the wound</strong>, as early as possible (up to day 7 after first vaccine dose).</p>\n<p><strong>5. Previously vaccinated person</strong>: 2 doses (days 0 and 3); no RIG.</p>\n<p><strong>6. Observe the dog</strong> for 10 days if possible; report the bite; counselling.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO position paper on rabies vaccines, 2018.</p>"},{"id":"DU.681","n":681,"part":11,"topic":"Communicable Diseases","stars":3,"years":["17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>How can you control rabies?</p>","a":"<p><strong>Control of rabies</strong></p>\n<p><strong>A. In animals (source: most important)</strong></p>\n<ol>\n<li><strong>Mass dog vaccination</strong> (≥70% coverage of dogs).</li>\n<li><strong>Dog population management</strong>: animal birth control (sterilisation) rather than culling; garbage control.</li>\n<li>Responsible pet ownership; registration and vaccination of pets.</li>\n<li>Stray dog surveillance; quarantine of biting animals.</li>\n</ol>\n<p><strong>B. In humans</strong></p>\n<ol>\n<li><strong>Post-exposure prophylaxis</strong>: wound care, vaccine, RIG, available free at all district and upazila centres.</li>\n<li><strong>Pre-exposure prophylaxis</strong> for high-risk groups (veterinarians, animal handlers, lab staff, children in high-risk areas).</li>\n<li><strong>Health education</strong>: avoid provoking dogs, wash wounds, seek PEP early.</li>\n</ol>\n<p><strong>C. Surveillance and One Health</strong></p>\n<p>Reporting of bites and rabies cases; laboratory diagnosis in animals; coordination of health, livestock and local government.</p>\n<p><strong>Goal</strong>: &quot;<strong>Zero by 30</strong>&quot; (end dog-mediated human rabies deaths by 2030); Bangladesh national rabies elimination programme (mass dog vaccination + free PEP).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.682","n":682,"part":11,"topic":"Communicable Diseases","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>Dog bite is a public health problem throughout the year – justify.</p>","a":"<p><strong>Dog bite: a year-round public health problem</strong></p>\n<ol>\n<li><strong>Large stray dog population</strong> in cities and villages (fed by garbage) → bites occur in all seasons.</li>\n<li><strong>Rabies is endemic</strong>; dogs are the source of most human rabies.</li>\n<li>Rabies is <strong>almost 100% fatal</strong> → every bite is a potential emergency.</li>\n<li><strong>Children</strong> are most often bitten, often on the <strong>face and head</strong> (high-risk, category III).</li>\n<li><strong>Large numbers of bite victims</strong> need PEP all year → heavy demand on vaccine and RIG; shortages.</li>\n<li><strong>Cost</strong> to families (travel, lost work) and health system.</li>\n<li><strong>Fear and psychological stress</strong>; injuries and infections (tetanus, sepsis).</li>\n<li>Low dog vaccination coverage in some areas; poor awareness of wound washing.</li>\n<li>Requires <strong>continuous</strong> services, surveillance and dog vaccination.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.683","n":683,"part":11,"topic":"Communicable Diseases","stars":3,"years":["24Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>List the different types of anti-rabies vaccines.</p>","a":"<p><strong>Types of anti-rabies vaccines</strong></p>\n<p><strong>A. Nerve tissue vaccines (old; discontinued by WHO)</strong></p>\n<p>Semple vaccine (sheep brain), suckling mouse brain vaccine: reactogenic (neuroparalytic reactions), less potent.</p>\n<p><strong>B. Cell-culture vaccines (CCVs; current)</strong></p>\n<ol>\n<li><strong>Human diploid cell vaccine (HDCV)</strong>.</li>\n<li><strong>Purified chick embryo cell vaccine (PCECV)</strong>.</li>\n<li><strong>Purified Vero cell rabies vaccine (PVRV)</strong>.</li>\n<li>Purified duck embryo vaccine (PDEV).</li>\n</ol>\n<p>Used intradermally (0.1 ml) or intramuscularly (1 vial).</p>\n<p><strong>C. Animal vaccines</strong></p>\n<p>For dogs and cats (inactivated); oral bait vaccines for wildlife.</p>\n<p><strong>D. Passive agents (not vaccines)</strong></p>\n<p>Equine RIG, human RIG, rabies monoclonal antibodies.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.684","n":684,"part":11,"topic":"Communicable Diseases","stars":2,"years":[],"colleges":"DMC (2nd Assess C2); MuMC (2nd Final B5)","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>Give an outline of the post-exposure prophylaxis for a bite by a rabid animal / the recommended PEP for rabies in Bangladesh.</p>","a":"<p><strong>Post-exposure prophylaxis (PEP) for a bite by a rabid animal</strong></p>\n<ol>\n<li><strong>Wound care</strong>: wash with soap and running water for 15 minutes; antiseptic; avoid immediate suturing.</li>\n<li><strong>Categorise exposure</strong> (WHO I, II, III).</li>\n<li><strong>Vaccine</strong> (category II and III): cell-culture vaccine, <strong>intradermal 0.1 ml at 2 sites on days 0, 3, 7</strong> (Bangladesh uses ID regimen at rabies centres), or IM schedules.</li>\n<li><strong>RIG</strong> (category III, and category II in immunocompromised): infiltrate into and around the wound.</li>\n<li><strong>Tetanus</strong> prophylaxis; antibiotics if needed.</li>\n<li><strong>Previously vaccinated</strong>: 2 booster doses (days 0, 3), no RIG.</li>\n<li>Observe the animal for 10 days; complete the course regardless of the animal's status if it cannot be observed.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases); WHO position paper on rabies vaccines, 2018.</p>"},{"id":"DU.685","n":685,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"DMC (2nd Assess C2)","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>Rabies is preventable rather than curable – explain.</p>","a":"<p><strong>Rabies is preventable, not curable</strong></p>\n<ol>\n<li>Once symptoms appear, rabies is <strong>almost always fatal</strong>; there is <strong>no effective treatment</strong> (only palliative care).</li>\n<li>The <strong>long incubation period</strong> gives time for <strong>post-exposure prophylaxis</strong>.</li>\n<li><strong>PEP</strong> (wound washing + vaccine + RIG) is nearly <strong>100% effective</strong> if given promptly and correctly.</li>\n<li><strong>Pre-exposure vaccination</strong> protects high-risk people.</li>\n<li><strong>Dog vaccination</strong> stops transmission at the source.</li>\n</ol>\n<p>So the strategy is prevention: animal control, PEP, education.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.686","n":686,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term A4)","asked":"","note":"","kind":"","sub":"Rabies","q":"<p>State the three categories of rabies exposure. Mention two immediate measures for management of a rabies-prone wound along with indication of rabies immunoglobulin.</p>","a":"<p><strong>Three categories of rabies exposure (WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Exposure</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>I</strong></td>\n<td>Touching or feeding animals; licks on intact skin</td>\n</tr>\n<tr>\n<td><strong>II</strong></td>\n<td>Nibbling of uncovered skin; minor scratches or abrasions without bleeding</td>\n</tr>\n<tr>\n<td><strong>III</strong></td>\n<td>Single or multiple transdermal bites or scratches; licks on broken skin; saliva on mucous membranes; contact with bats</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Two immediate measures for a rabies-prone wound</strong></p>\n<ol>\n<li><strong>Wash the wound thoroughly with soap and running water for 15 minutes</strong>.</li>\n<li><strong>Apply antiseptic</strong> (povidone-iodine or alcohol); avoid suturing.</li>\n</ol>\n<p><strong>Indication of rabies immunoglobulin (RIG)</strong></p>\n<ol>\n<li>All <strong>category III</strong> exposures.</li>\n<li><strong>Category II</strong> exposures in <strong>immunocompromised</strong> persons.<br />\n(Not needed for previously fully vaccinated persons.)</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.687","n":687,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"MuMC (2nd Final B5)","asked":"","note":"","kind":"Case-based","sub":"Rabies","q":"<p>A 7-year-old boy is walking along the road. A rabid dog bites him on the leg causing severe bleeding. [3+2.5+1.5]</p>\n<ul>\n<li>(a) Categorize the wound type and write down the wound management according to category. (3)</li>\n<li>(b) What are the recommended post-exposure prophylaxis measures for rabies in Bangladesh? (2.5)</li>\n<li>(c) Mention name of five other rabid animal. (1.5)</li>\n</ul>","a":"<p><strong>(a) Wound category and management (3)</strong></p>\n<p><strong>Category III</strong> exposure (transdermal bite with severe bleeding by a rabid dog).</p>\n<ol>\n<li><strong>Control bleeding</strong> with pressure.</li>\n<li><strong>Wash with soap and running water for 15 minutes</strong>; irrigate deeply.</li>\n<li><strong>Antiseptic</strong> (povidone-iodine).</li>\n<li><strong>Do not suture</strong> immediately; if essential, after RIG infiltration, loose stitches.</li>\n<li><strong>RIG infiltration</strong> into and around the wound.</li>\n<li><strong>Tetanus</strong> toxoid/TIG as needed; antibiotics for deep wounds; analgesics.</li>\n</ol>\n<p><strong>(b) PEP in Bangladesh (2.5)</strong></p>\n<ol>\n<li><strong>Free cell-culture rabies vaccine</strong>, <strong>intradermal 0.1 ml at two sites</strong> on days <strong>0, 3, 7</strong> at district/upazila rabies prevention centres.</li>\n<li><strong>Rabies immunoglobulin</strong> (equine 40 IU/kg or human 20 IU/kg) infiltrated in the wound on day 0 (up to day 7).</li>\n<li>Complete the course; counselling; report the bite; dog control by local authority.</li>\n</ol>\n<p><strong>(c) Five other rabid animals (1.5)</strong></p>\n<p>Cat, jackal, fox, mongoose, monkey (also bat, wolf).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.688","n":688,"part":11,"topic":"Communicable Diseases","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Bird Flu","q":"<p>Give the prevention &amp; control measures of bird flu (H7N9).</p>","a":"<p><strong>Prevention and control of avian influenza (bird flu: H7N9, H5N1)</strong></p>\n<p><strong>A. Animal sector</strong></p>\n<ol>\n<li><strong>Surveillance</strong> in poultry and wild birds; early reporting of sick or dead birds.</li>\n<li><strong>Culling</strong> of infected flocks; safe disposal; compensation to farmers.</li>\n<li><strong>Biosecurity</strong> in farms; separate poultry from humans and wild birds.</li>\n<li><strong>Live bird market</strong> hygiene: cleaning, disinfection, rest days, closure in outbreaks.</li>\n<li>Poultry vaccination where recommended.</li>\n</ol>\n<p><strong>B. Human sector</strong></p>\n<ol>\n<li>Avoid contact with sick or dead birds; <strong>cook poultry and eggs thoroughly</strong>; hand hygiene.</li>\n<li><strong>PPE</strong> for cullers and market workers; oseltamivir prophylaxis for exposed workers.</li>\n<li>Early diagnosis, <strong>isolation</strong> and treatment of cases with <strong>oseltamivir</strong>.</li>\n<li><strong>Contact tracing</strong> and monitoring.</li>\n<li>Seasonal flu vaccination of poultry workers (reduces reassortment risk).</li>\n<li>Notification under <strong>IHR</strong>.</li>\n</ol>\n<p><strong>C. One Health coordination</strong>, risk communication, research.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.689","n":689,"part":11,"topic":"Communicable Diseases","stars":0,"years":["04M"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Enlist the sexually transmitted diseases.</p>","a":"<p><strong>Sexually transmitted diseases (STDs / STIs)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Diseases</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Bacterial</strong></td>\n<td>Syphilis, gonorrhoea, chancroid, chlamydia (including lymphogranuloma venereum), granuloma inguinale (donovanosis), <em>Mycoplasma genitalium</em></td>\n</tr>\n<tr>\n<td><strong>Viral</strong></td>\n<td>HIV/AIDS, genital herpes (HSV), genital warts (HPV), hepatitis B, molluscum contagiosum</td>\n</tr>\n<tr>\n<td><strong>Protozoal</strong></td>\n<td>Trichomoniasis</td>\n</tr>\n<tr>\n<td><strong>Fungal</strong></td>\n<td>Candidiasis</td>\n</tr>\n<tr>\n<td><strong>Ectoparasitic</strong></td>\n<td>Scabies, pubic lice</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.690","n":690,"part":11,"topic":"Communicable Diseases","stars":0,"years":["04Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Name the STDs of viral origin.</p>","a":"<p><strong>STDs of viral origin</strong></p>\n<ol>\n<li><strong>HIV/AIDS</strong></li>\n<li><strong>Genital herpes</strong> (HSV-2, HSV-1)</li>\n<li><strong>Genital warts</strong> (HPV; also cervical cancer)</li>\n<li><strong>Hepatitis B</strong> (and less often hepatitis C)</li>\n<li>Molluscum contagiosum</li>\n<li>Cytomegalovirus, HTLV-1</li>\n<li>Mpox (sexual contact in recent outbreaks)</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.691","n":691,"part":11,"topic":"Communicable Diseases","stars":0,"years":["06S"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>What investigation strategies are to be taken to control STD?</p>","a":"<p><strong>Investigation strategies for STD control</strong></p>\n<ol>\n<li><strong>Screening</strong>: pregnant women (syphilis, HIV, HBsAg), blood donors, high-risk groups (sex workers, MSM, PWID).</li>\n<li><strong>Contact tracing / partner notification</strong>: find, test and treat sexual partners.</li>\n<li><strong>Cluster testing</strong>: test associates of cases who may be at risk.</li>\n<li><strong>Laboratory diagnosis</strong>: VDRL/RPR, TPHA, Gram stain, NAAT, HIV tests.</li>\n<li><strong>Surveillance</strong>: case reporting, sentinel surveillance in key populations, behavioural surveys.</li>\n<li><strong>Prevalence surveys</strong> to estimate burden.</li>\n<li><strong>Epidemiological treatment</strong> of contacts.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.692","n":692,"part":11,"topic":"Communicable Diseases","stars":3,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Mention epidemiological determinants of STD.</p>","a":"<p><strong>Epidemiological determinants of STDs</strong></p>\n<p><strong>A. Agent</strong></p>\n<p>Bacteria, viruses, protozoa, fungi, ectoparasites; asymptomatic infections and drug resistance (gonorrhoea) help spread.</p>\n<p><strong>B. Host factors</strong></p>\n<ol>\n<li><strong>Age</strong>: 15–29 years most affected.</li>\n<li><strong>Sex</strong>: women more prone to complications; often asymptomatic.</li>\n<li><strong>Marital status</strong>: single, separated, divorced.</li>\n<li><strong>Occupation / mobility</strong>: sex workers, truck drivers, migrant workers, seafarers.</li>\n<li><strong>Behaviour</strong>: multiple partners, unprotected sex, MSM, injecting drug use, early sexual debut.</li>\n<li>Existing STI increases HIV risk.</li>\n</ol>\n<p><strong>C. Social and environmental factors</strong></p>\n<ol>\n<li>Poverty, unemployment.</li>\n<li><strong>Commercial sex</strong>, trafficking.</li>\n<li><strong>Urbanisation and migration</strong> (separation from families).</li>\n<li>Alcohol and drug use.</li>\n<li>Lack of sex education; illiteracy.</li>\n<li><strong>Stigma</strong> → delayed care; self-medication.</li>\n<li>Gender inequality; sexual violence.</li>\n<li>Changing sexual norms; travel and tourism.</li>\n</ol>\n<p><strong>D. Health services</strong></p>\n<p>Limited access to confidential STI services, syndromic care, condoms.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.693","n":693,"part":11,"topic":"Communicable Diseases","stars":3,"years":["14Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Mention sources of HIV/AIDS.</p>","a":"<p><strong>Sources of HIV</strong></p>\n<ol>\n<li><strong>Infected persons</strong> (symptomatic or asymptomatic, including in the window period).</li>\n<li><strong>Infective materials</strong>: <strong>blood</strong>, <strong>semen</strong>, <strong>vaginal secretions</strong>, <strong>breast milk</strong>; less in other body fluids with blood.</li>\n<li><strong>Key populations</strong> at higher risk: sex workers and clients, men who have sex with men, people who inject drugs, transgender (hijra) people, returning migrant workers.</li>\n<li><strong>Routes</strong>: unprotected sex, contaminated blood and needles, mother-to-child (pregnancy, delivery, breastfeeding).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.694","n":694,"part":11,"topic":"Communicable Diseases","stars":0,"years":["06M"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Explain AIDS-related complex.</p>","a":"<p><strong>AIDS-related complex (ARC)</strong></p>\n<p>An older term for <strong>symptomatic HIV infection before full AIDS</strong>, with chronic signs of immune damage but without AIDS-defining opportunistic infections or cancers.</p>\n<p><strong>Features</strong></p>\n<ol>\n<li><strong>Persistent generalised lymphadenopathy</strong>.</li>\n<li>Prolonged fever, night sweats.</li>\n<li><strong>Weight loss</strong> &gt;10%; chronic diarrhoea &gt;1 month.</li>\n<li>Oral <strong>candidiasis</strong>, oral hairy leukoplakia.</li>\n<li>Herpes zoster, recurrent bacterial infections.</li>\n<li>Laboratory: low CD4 count, anaemia, leucopenia.</li>\n</ol>\n<p>Now included in <strong>WHO clinical stages 2–3</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.695","n":695,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16Nov","10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>How can STDs be controlled and prevented? How can spread of AIDS be prevented? / Highlight the approaches for control of AIDS.</p>","a":"<p><strong>Prevention and control of STDs and HIV/AIDS</strong></p>\n<p><strong>A. Prevent sexual transmission</strong></p>\n<ol>\n<li><strong>Health education / BCC</strong>: abstinence, faithfulness, partner reduction, <strong>condom</strong> use (ABC).</li>\n<li>Free condom distribution; <strong>targeted interventions</strong> for sex workers, MSM, hijra.</li>\n<li><strong>Pre-exposure prophylaxis (PrEP)</strong> for high-risk people.</li>\n</ol>\n<p><strong>B. Prevent blood-borne transmission</strong></p>\n<ol>\n<li><strong>Safe blood</strong>: screening all donations; voluntary donors.</li>\n<li>Sterile needles; safe injections.</li>\n<li><strong>Harm reduction</strong>: needle-syringe exchange, opioid substitution therapy for PWID.</li>\n<li><strong>Post-exposure prophylaxis</strong> for health workers and sexual assault.</li>\n</ol>\n<p><strong>C. Prevent mother-to-child transmission (PMTCT)</strong></p>\n<p>Antenatal HIV and syphilis testing; ART for mothers; safe delivery; infant prophylaxis; infant feeding counselling.</p>\n<p><strong>D. Early diagnosis and treatment</strong></p>\n<ol>\n<li><strong>HIV testing and counselling</strong>; partner testing.</li>\n<li><strong>ART for all</strong> (&quot;treat all&quot;); viral suppression prevents transmission (U = U).</li>\n<li><strong>Syndromic management</strong> of STIs; treat partners.</li>\n<li><strong>Contact tracing</strong>.</li>\n</ol>\n<p><strong>E. Vaccines</strong>: hepatitis B, HPV.</p>\n<p><strong>F. Surveillance, research, stigma reduction</strong>, legal protection, involvement of PLHIV.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.696","n":696,"part":11,"topic":"Communicable Diseases","stars":0,"years":["08Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>HIV/AIDS is an emerging serious public health problem of Bangladesh – discuss.</p>","a":"<p><strong>HIV/AIDS: an emerging public health problem in Bangladesh</strong></p>\n<ol>\n<li>First case detected in <strong>1989</strong>; overall prevalence remains <strong>low</strong> in the general population, but new infections and AIDS deaths have been <strong>rising</strong>.</li>\n<li><strong>Concentrated epidemic</strong> among key populations: <strong>people who inject drugs</strong> (especially in Dhaka), sex workers, MSM, hijra.</li>\n<li><strong>Returning migrant workers</strong> and their spouses form a large share of detected cases.</li>\n<li><strong>Rohingya refugees</strong> add new cases and vulnerability.</li>\n<li><strong>Risk factors</strong>: unprotected commercial sex, low condom use, sharing needles, mobility, poverty, low awareness.</li>\n<li><strong>Low testing and late diagnosis</strong>; stigma and discrimination.</li>\n<li>Many PLHIV not on ART; TB–HIV co-infection.</li>\n<li>Proximity to high-prevalence neighbours; cross-border movement.</li>\n</ol>\n<p><strong>Response needed</strong>: expanded testing, ART for all, harm reduction, targeted interventions, migrant programmes, stigma reduction.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.697","n":697,"part":11,"topic":"Communicable Diseases","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>State interventions taken by NASP to control HIV/AIDS in Bangladesh.</p>","a":"<p><strong>Interventions by the National AIDS/STD Programme (NASP / ASP), Bangladesh</strong></p>\n<ol>\n<li><strong>Targeted interventions</strong> for key populations: drop-in centres for sex workers, MSM, hijra and PWID; outreach, condoms, STI care.</li>\n<li><strong>Harm reduction</strong>: needle-syringe programmes, <strong>opioid substitution therapy</strong> (methadone).</li>\n<li><strong>HIV testing services</strong> (HTC) and linkage to care.</li>\n<li><strong>Free ART</strong> at designated hospitals; treat-all policy; viral load monitoring.</li>\n<li><strong>PMTCT</strong> services.</li>\n<li><strong>STI management</strong> (syndromic).</li>\n<li><strong>Blood safety</strong> (with Safe Blood Transfusion Programme).</li>\n<li><strong>BCC / awareness</strong>: mass media, youth, workplaces; pre-departure orientation for migrant workers.</li>\n<li><strong>Surveillance</strong>: serological and behavioural surveillance.</li>\n<li>Stigma reduction; partnership with NGOs and UN agencies; Global Fund support.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.698","n":698,"part":11,"topic":"Communicable Diseases","stars":3,"years":["13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Outline the management plan for vaginal discharge at PHC level.</p>","a":"<p><strong>Management of vaginal discharge at PHC level (syndromic approach)</strong></p>\n<ol>\n<li><strong>History</strong>: discharge (colour, odour, itching), lower abdominal pain, partner symptoms; <strong>risk assessment</strong> (new or multiple partners, partner with urethral discharge).</li>\n<li><strong>Examination</strong>: abdomen; speculum if possible (cervical discharge, mucopus).</li>\n<li><strong>Treat according to findings (WHO flowchart)</strong>:</li>\n</ol>\n<table>\n<thead>\n<tr>\n<th>Finding</th>\n<th>Treat for</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Risk assessment <strong>positive</strong> or cervical discharge</td>\n<td><strong>Cervicitis</strong> (gonorrhoea + chlamydia: e.g., ceftriaxone + azithromycin/doxycycline) <strong>and vaginitis</strong></td>\n</tr>\n<tr>\n<td>Risk assessment negative</td>\n<td><strong>Vaginitis</strong> only: bacterial vaginosis + trichomoniasis (<strong>metronidazole</strong>)</td>\n</tr>\n<tr>\n<td>Curd-like discharge, itching</td>\n<td>Add <strong>candidiasis</strong> treatment (clotrimazole pessary / fluconazole)</td>\n</tr>\n<tr>\n<td>Lower abdominal pain, fever, cervical motion tenderness</td>\n<td>Manage as <strong>PID</strong>; refer if severe</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"4\">\n<li><strong>4 Cs</strong>: <strong>Counselling</strong>, <strong>Condoms</strong>, <strong>Compliance</strong>, <strong>Contact (partner) treatment</strong>.</li>\n<li>Offer <strong>HIV and syphilis testing</strong>.</li>\n<li><strong>Follow-up</strong> in 7 days; refer if not improving.</li>\n<li>Pregnancy: avoid doxycycline and oral fluconazole.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.699","n":699,"part":11,"topic":"Communicable Diseases","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Mention the social and behavioral factors responsible for the spread of STDs. What are the common syndromes and sequelae of STDs?</p>","a":"<p><strong>Social and behavioural factors in the spread of STDs</strong></p>\n<ol>\n<li><strong>Multiple sexual partners</strong>; unprotected sex.</li>\n<li><strong>Commercial sex</strong> and trafficking.</li>\n<li><strong>Migration and mobility</strong> (migrant workers, truck drivers).</li>\n<li><strong>Urbanisation</strong>; breakdown of family ties.</li>\n<li><strong>Alcohol and drugs</strong>; injecting drug use.</li>\n<li><strong>Poverty</strong>, unemployment.</li>\n<li><strong>Lack of sex education</strong>; ignorance; early sexual debut.</li>\n<li><strong>Stigma</strong> → hiding symptoms, delayed treatment, self-medication.</li>\n<li><strong>Gender inequality</strong>; sexual violence; inability of women to negotiate condom use.</li>\n<li>Male–male sex in hidden settings; changing sexual norms.</li>\n</ol>\n<p><strong>Common STI syndromes</strong></p>\n<ol>\n<li><strong>Urethral discharge</strong> (men)</li>\n<li><strong>Vaginal discharge</strong></li>\n<li><strong>Genital ulcer</strong></li>\n<li><strong>Lower abdominal pain</strong> (PID)</li>\n<li><strong>Scrotal swelling</strong></li>\n<li><strong>Inguinal bubo</strong></li>\n<li><strong>Neonatal conjunctivitis</strong> (ophthalmia neonatorum)</li>\n</ol>\n<p><strong>Sequelae</strong></p>\n<table>\n<thead>\n<tr>\n<th>Women</th>\n<th>Men</th>\n<th>Newborn</th>\n<th>General</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>PID → <strong>infertility</strong>, <strong>ectopic pregnancy</strong>, chronic pelvic pain; <strong>cervical cancer</strong> (HPV); adverse pregnancy outcomes</td>\n<td>Epididymitis, <strong>infertility</strong>, urethral stricture</td>\n<td><strong>Congenital syphilis</strong>, stillbirth, LBW, ophthalmia neonatorum (blindness), neonatal herpes, perinatal HIV/HBV</td>\n<td><strong>Increased HIV transmission</strong>; neurosyphilis, cardiovascular syphilis; liver cirrhosis and cancer (HBV)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.700","n":700,"part":11,"topic":"Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term D3)","asked":"","note":"","kind":"","sub":"STIs, HIV & AIDS","q":"<p>Define the syndromic approach to STI management. Name four major STI syndromes managed syndromically. Why can syndromic management of STIs be simultaneously advantageous and problematic?</p>","a":"<p><strong>Syndromic approach to STI management</strong></p>\n<p>Classification of STIs into <strong>syndromes</strong> (groups of easily recognised symptoms and signs) and <strong>treatment at the first visit for all major organisms likely to cause that syndrome</strong>, using standard flowcharts, <strong>without waiting for laboratory confirmation</strong>; plus counselling, condoms and partner management.</p>\n<p><strong>Four major syndromes</strong></p>\n<ol>\n<li><strong>Urethral discharge</strong>.</li>\n<li><strong>Vaginal discharge</strong>.</li>\n<li><strong>Genital ulcer</strong>.</li>\n<li><strong>Lower abdominal pain</strong> (PID).<br />\n(Others: scrotal swelling, inguinal bubo, neonatal conjunctivitis.)</li>\n</ol>\n<p><strong>Advantages</strong></p>\n<ol>\n<li><strong>Same-day treatment</strong> → fewer complications, less spread.</li>\n<li><strong>No laboratory</strong> needed; usable at PHC.</li>\n<li><strong>Cheap</strong>, simple, standardised; trained non-specialists can use it.</li>\n<li>Covers <strong>mixed infections</strong>.</li>\n<li>Opportunity for counselling and condoms.</li>\n</ol>\n<p><strong>Problems</strong></p>\n<ol>\n<li><strong>Over-treatment</strong> → cost, side effects, <strong>antimicrobial resistance</strong> (gonorrhoea).</li>\n<li><strong>Misses asymptomatic infections</strong> (most chlamydia and gonorrhoea in women).</li>\n<li>Poor accuracy for <strong>cervical infection</strong> in vaginal discharge (often due to non-STI vaginitis) → mislabelling women as having STIs, partner conflict, stigma.</li>\n<li>Does not identify the specific organism (no surveillance data).</li>\n<li>Partner management difficult.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.701","n":701,"part":11,"topic":"Communicable Diseases","stars":3,"years":["20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"COVID-19","q":"<p>Discuss Bangladesh government's initiative for prevention and control of COVID-19.</p>","a":"<p><strong>Bangladesh government's initiatives against COVID-19</strong></p>\n<p><strong>A. Preparedness and coordination</strong></p>\n<ol>\n<li><strong>National Preparedness and Response Plan</strong>; national and local committees; DGHS control room; IEDCR as focal point (first cases confirmed on <strong>8 March 2020</strong>).</li>\n<li>Coordination with WHO, UNICEF and partners; armed forces support.</li>\n</ol>\n<p><strong>B. Surveillance and testing</strong></p>\n<ol>\n<li>Rapid expansion of <strong>RT-PCR laboratories</strong> across divisions, then GeneXpert and <strong>rapid antigen tests</strong>.</li>\n<li>Contact tracing; airport and land-port screening.</li>\n</ol>\n<p><strong>C. Public health and social measures</strong></p>\n<ol>\n<li><strong>General holiday / lockdown</strong> from <strong>26 March 2020</strong>; restrictions on movement, gatherings; school closures.</li>\n<li><strong>Quarantine</strong> (home and institutional) and <strong>isolation</strong>.</li>\n<li><strong>Mask mandates</strong>, hand-washing stations, physical distancing.</li>\n<li>Risk communication: <strong>333</strong> and other hotlines, media campaigns, religious leaders.</li>\n</ol>\n<p><strong>D. Case management</strong></p>\n<ol>\n<li>Designated COVID-19 hospitals; expansion of beds, <strong>ICU</strong> and <strong>oxygen</strong> (central oxygen, high-flow nasal cannula).</li>\n<li>National treatment guidelines; training of health workers; PPE.</li>\n<li><strong>Telemedicine</strong> services.</li>\n</ol>\n<p><strong>E. Vaccination</strong></p>\n<p>Mass vaccination began on <strong>7 February 2021</strong>; online registration through the <strong>Surokkha</strong> platform; vaccines from bilateral deals and <strong>COVAX</strong>; campaigns reached rural areas and Rohingya camps.</p>\n<p><strong>F. Social and economic support</strong></p>\n<p>Stimulus packages, food and cash support for the poor, support to workers.</p>\n<p><strong>Challenges</strong></p>\n<p>Testing capacity outside Dhaka, oxygen shortages during surges, private-sector regulation, misinformation, adherence to restrictions.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Communicable Diseases).</p>"},{"id":"DU.702","n":702,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["25Nov","20Nov","18Nov","18M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the criteria of chronic diseases.</p>","a":"<p><strong>Criteria of chronic disease (US Commission on Chronic Illness)</strong></p>\n<p>Impairments or deviations from normal that have <strong>one or more</strong> of the following characteristics:</p>\n<ol>\n<li><strong>Permanent</strong>.</li>\n<li><strong>Leave residual disability</strong>.</li>\n<li>Caused by <strong>non-reversible pathological alteration</strong>.</li>\n<li>Require <strong>special training of the patient for rehabilitation</strong>.</li>\n<li>May be expected to require a <strong>long period of supervision, observation or care</strong>.</li>\n</ol>\n<p><strong>Examples</strong>: diabetes, hypertension, CHD, COPD, chronic kidney disease, arthritis, cancers, stroke.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.703","n":703,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["06S"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>State the cardinal characteristics of non-communicable diseases.</p>","a":"<p><strong>Cardinal characteristics of NCDs (Park)</strong></p>\n<ol>\n<li><strong>Absence of a known agent</strong> (single specific cause).</li>\n<li><strong>Multifactorial causation</strong> (risk factors).</li>\n<li><strong>Long latent period</strong>.</li>\n<li><strong>Indefinite onset</strong>; insidious.</li>\n<li><strong>Differential effect of factors on incidence</strong> (same factor causes several diseases).</li>\n<li>Long duration (chronic); often permanent disability.</li>\n<li>Not transmitted from person to person.</li>\n<li>Largely related to <strong>lifestyle</strong> and ageing.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.704","n":704,"part":11,"topic":"Non-Communicable Diseases","stars":2,"years":["11Ju"],"colleges":"MuMC (2nd Final A4)","asked":"WHO-identified risk factors for NCDs","note":"","kind":"","sub":"","q":"<p>State the common risk factors of non-communicable diseases.</p>","a":"<p><strong>Common risk factors of NCDs (WHO)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Risk factors</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Behavioural (modifiable)</strong></td>\n<td><strong>Tobacco use</strong>, <strong>unhealthy diet</strong> (high salt, sugar, fat; low fruit and vegetables), <strong>physical inactivity</strong>, <strong>harmful use of alcohol</strong></td>\n</tr>\n<tr>\n<td><strong>Metabolic</strong></td>\n<td><strong>Raised blood pressure</strong>, <strong>overweight/obesity</strong>, <strong>raised blood glucose</strong>, <strong>raised blood lipids</strong></td>\n</tr>\n<tr>\n<td><strong>Environmental</strong></td>\n<td>Air pollution (outdoor and household)</td>\n</tr>\n<tr>\n<td><strong>Non-modifiable</strong></td>\n<td>Age, sex, genetics, family history</td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Stress, poverty, urbanisation</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.705","n":705,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["22M","18Nov"],"colleges":"MuMC (2nd Final A4)","asked":"other names of NCDs; preventable diseases under NCDs","note":"","kind":"","sub":"","q":"<p>Name the NCDs. Mention the necessary steps / measures to prevent and control NCDs.</p>","a":"<p><strong>Major NCDs</strong></p>\n<ol>\n<li><strong>Cardiovascular diseases</strong>: CHD, stroke, hypertension, rheumatic heart disease.</li>\n<li><strong>Cancers</strong>: lung, oral, cervical, breast, liver, stomach.</li>\n<li><strong>Chronic respiratory diseases</strong>: COPD, asthma.</li>\n<li><strong>Diabetes mellitus</strong>.</li>\n<li>Others: chronic kidney disease, mental disorders, obesity, blindness, accidents and injuries, dental disease.</li>\n</ol>\n<p><strong>Measures to prevent and control NCDs</strong></p>\n<p><strong>A. Primordial prevention</strong>: healthy public policy: tobacco taxes and smoke-free laws, salt and trans-fat regulation, sugar taxes, urban planning for activity.</p>\n<p><strong>B. Primary prevention</strong></p>\n<ol>\n<li><strong>Population strategy</strong>: reduce risk factors in the whole population (health education, healthy diet, physical activity, no tobacco, limit alcohol).</li>\n<li><strong>High-risk strategy</strong>: identify and manage people at high risk (raised BP, glucose, lipids, smokers).</li>\n</ol>\n<p><strong>C. Secondary prevention: screening and early treatment</strong></p>\n<p>BP and blood glucose screening (adults ≥40 years), cervical (VIA) and breast cancer screening, oral cancer examination; standard treatment protocols (WHO PEN, HEARTS).</p>\n<p><strong>D. Tertiary prevention</strong></p>\n<p>Rehabilitation (cardiac, stroke), palliative care, disability limitation.</p>\n<p><strong>E. Health system</strong></p>\n<p>NCD corners at UHCs and community clinics; essential NCD drugs; trained staff; referral; surveillance (STEPS surveys).</p>\n<p><strong>F. Multisectoral action</strong></p>\n<p>Bangladesh NCD Control Programme and multisectoral action plan; WHO &quot;<strong>best buys</strong>&quot;.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.706","n":706,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["24Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Analyze the behaviors associated with non-communicable disease and their impact on health outcomes.</p>","a":"<p><strong>Behaviours associated with NCDs and their impact</strong></p>\n<p>NCDs cause about <strong>74% of all deaths globally</strong> (WHO); four behaviours drive most of them.</p>\n<table>\n<thead>\n<tr>\n<th>Behaviour</th>\n<th>Pathway</th>\n<th>Health outcomes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Tobacco</strong> (smoking, smokeless)</td>\n<td>Atherosclerosis, carcinogens, airway damage</td>\n<td>CHD, stroke, lung and oral cancers, COPD, TB, low birth weight</td>\n</tr>\n<tr>\n<td><strong>Unhealthy diet</strong>: high salt</td>\n<td>Raised BP</td>\n<td>Hypertension, stroke, kidney disease</td>\n</tr>\n<tr>\n<td>High sugar, refined carbohydrates</td>\n<td>Obesity, insulin resistance</td>\n<td>Diabetes, dental caries, CHD</td>\n</tr>\n<tr>\n<td>Saturated and trans fats</td>\n<td>Raised LDL</td>\n<td>CHD, stroke</td>\n</tr>\n<tr>\n<td>Low fruit and vegetable intake</td>\n<td>Low fibre, antioxidants</td>\n<td>CHD, cancers, constipation</td>\n</tr>\n<tr>\n<td><strong>Physical inactivity</strong></td>\n<td>Weight gain, poor glucose control</td>\n<td>Obesity, diabetes, CHD, depression, some cancers</td>\n</tr>\n<tr>\n<td><strong>Harmful alcohol use</strong></td>\n<td>Liver and cardiac toxicity</td>\n<td>Cirrhosis, cancers, hypertension, injuries, violence</td>\n</tr>\n<tr>\n<td>Poor sleep, chronic stress</td>\n<td>Hormonal and BP changes</td>\n<td>Hypertension, depression</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Key points</strong></p>\n<ol>\n<li>Behaviours <strong>cluster</strong> and act <strong>synergistically</strong> (smoking + hypertension + diabetes multiply CHD risk).</li>\n<li>They begin in <strong>childhood and adolescence</strong> → primordial prevention.</li>\n<li>They are shaped by <strong>environment</strong> (marketing, urban design, prices) → policy measures needed.</li>\n<li>Impact: <strong>premature deaths (30–70 years)</strong>, disability, poverty from health costs, lost productivity.</li>\n<li>Changing behaviours reduces risk quickly (e.g., stopping smoking halves CHD risk within a few years).</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases); WHO, Noncommunicable diseases fact sheet.</p>"},{"id":"DU.707","n":707,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":[],"colleges":"SSMC (2nd Term B5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A primary healthcare facility in a rural upazila plans to establish an NCD prevention programme targeting adults aged ≥40 years. [2+2+3]</p>\n<ul>\n<li>a) Mention the major NCDs that should be addressed by the programme.</li>\n<li>b) Describe the role of screening assessment in NCD prevention.</li>\n<li>c) Explain the primordial and primary prevention of NCDs with suitable examples.</li>\n</ul>","a":"<p><strong>a) Major NCDs to address (2)</strong></p>\n<p>Hypertension; diabetes; cardiovascular disease and stroke (CVD risk); chronic respiratory disease (COPD, asthma); common cancers (oral, cervical, breast); also obesity, chronic kidney disease, depression.</p>\n<p><strong>b) Role of screening (2)</strong></p>\n<ol>\n<li><strong>Detects hidden disease and risk</strong> (iceberg: many with hypertension and diabetes are unaware).</li>\n<li><strong>Early treatment</strong> prevents complications (stroke, MI, kidney failure, blindness).</li>\n<li><strong>Total CVD risk assessment</strong> (WHO risk charts) targets high-risk people.</li>\n<li>Opportunity for <strong>lifestyle counselling</strong>.</li>\n<li>Provides <strong>data</strong> for planning and monitoring.</li>\n</ol>\n<p>Methods: BP measurement, blood glucose, BMI and waist, tobacco use history, VIA for cervical cancer, clinical breast and oral examination.</p>\n<p><strong>c) Primordial and primary prevention with examples (3)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Aim</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primordial</strong></td>\n<td>Prevent emergence of risk factors in the population</td>\n<td>Tobacco-free school and community campaigns; ban on tobacco advertising; healthy school food; safe spaces for walking and play; salt reduction policies; promoting traditional healthy diets among youth</td>\n</tr>\n<tr>\n<td><strong>Primary</strong></td>\n<td>Reduce risk factors before disease</td>\n<td>Health education on diet (&lt;5 g salt, fruits and vegetables), physical activity (≥150 minutes/week), quitting tobacco, avoiding alcohol; weight control; managing stress; treating raised BP and glucose in high-risk people</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.708","n":708,"part":11,"topic":"Non-Communicable Diseases","stars":1,"years":["11Ju","11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"IHD & CHD","q":"<p>Enumerate the manifestations of IHD. How can you prevent them?</p>","a":"<p><strong>Manifestations of ischaemic heart disease (Park)</strong></p>\n<ol>\n<li><strong>Angina pectoris</strong> (stable, unstable).</li>\n<li><strong>Myocardial infarction</strong>.</li>\n<li><strong>Heart failure</strong>.</li>\n<li><strong>Arrhythmias</strong>.</li>\n<li><strong>Sudden death</strong>.</li>\n</ol>\n<p><strong>Prevention</strong></p>\n<table>\n<thead>\n<tr>\n<th>Strategy</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Population strategy</strong></td>\n<td>Healthy diet (less saturated fat, salt), no tobacco, physical activity, weight control; policy support</td>\n</tr>\n<tr>\n<td><strong>High-risk strategy</strong></td>\n<td>Screen and treat hypertension, diabetes, dyslipidaemia; smoking cessation</td>\n</tr>\n<tr>\n<td><strong>Secondary prevention</strong></td>\n<td>Aspirin, statins, beta-blockers, ACE inhibitors after MI; cardiac rehabilitation; lifestyle change</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.709","n":709,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["09Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"IHD & CHD","q":"<p>How can you measure the burden of CHD?</p>","a":"<p><strong>Measuring the burden of CHD</strong></p>\n<ol>\n<li><strong>Mortality data</strong>: CHD death rates, proportional mortality, case-fatality.</li>\n<li><strong>Morbidity</strong>: incidence (cohort studies, MI registers) and prevalence surveys (Rose angina questionnaire, ECG).</li>\n<li><strong>Hospital data</strong>: admissions, outpatient attendance.</li>\n<li><strong>Risk factor surveys</strong> (STEPS): smoking, BP, lipids, diabetes, obesity.</li>\n<li><strong>Disability</strong>: DALYs, years of life lost.</li>\n<li><strong>Economic cost</strong>: treatment costs, lost productivity.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.710","n":710,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"IHD & CHD","q":"<p>Enlist high risk factors of coronary heart disease.</p>","a":"<p><strong>Risk factors of coronary heart disease</strong></p>\n<p><strong>A. Non-modifiable</strong></p>\n<ol>\n<li><strong>Age</strong> (increases with age).</li>\n<li><strong>Sex</strong> (men earlier; women after menopause).</li>\n<li><strong>Family history</strong> of premature CHD; genetic factors.</li>\n<li>Ethnicity (South Asians at higher risk).</li>\n</ol>\n<p><strong>B. Modifiable (major)</strong></p>\n<ol>\n<li><strong>Cigarette smoking</strong> and smokeless tobacco.</li>\n<li><strong>Hypertension</strong>.</li>\n<li><strong>Dyslipidaemia</strong>: high LDL cholesterol, low HDL, high triglycerides.</li>\n<li><strong>Diabetes mellitus</strong>.</li>\n<li><strong>Obesity</strong>, especially <strong>central (abdominal) obesity</strong>.</li>\n<li><strong>Physical inactivity</strong>.</li>\n<li><strong>Unhealthy diet</strong>: saturated and trans fats, high salt, low fruit and vegetables.</li>\n</ol>\n<p><strong>C. Other contributing factors</strong></p>\n<p>Alcohol excess; <strong>psychosocial stress</strong>, type A personality; oral contraceptives (older high-dose, with smoking); air pollution; chronic kidney disease; metabolic syndrome.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.711","n":711,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["05S"],"colleges":"","asked":"","note":"","kind":"","sub":"IHD & CHD","q":"<p>Discuss the preventive measures of CHD.</p>","a":"<p><strong>Preventive measures of CHD (Park)</strong></p>\n<p><strong>1. Population strategy</strong> (prevention in the whole population)</p>\n<ul>\n<li>Primordial: prevent emergence of risk factors (healthy policies, school education).</li>\n<li>Change lifestyle and environment: reduce fat and salt, increase fruits and vegetables; <strong>stop smoking</strong>; regular physical activity; weight control; limit alcohol.</li>\n<li>Legislation: tobacco control, food labelling.</li>\n</ul>\n<p><strong>2. High-risk strategy</strong></p>\n<p>Identify and manage people with high BP, high cholesterol, diabetes, smokers, obesity, family history; total CVD risk assessment; drugs (antihypertensives, statins).</p>\n<p><strong>3. Secondary prevention</strong></p>\n<p>Prevent recurrence and progression in those with CHD: aspirin, beta-blockers, ACE inhibitors, statins; cardiac rehabilitation; lifestyle change; surgery or angioplasty when needed.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.712","n":712,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["25Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"IHD & CHD","q":"<p>A 60-year-old businessman has H/O myocardial infarction 3 months back. List the spectrum of diseases this patient might have. What will be the preventive measures and advice for him?</p>","a":"<p><strong>Spectrum of diseases he may have</strong></p>\n<ol>\n<li><strong>Coronary heart disease</strong>: recurrent MI, angina, heart failure, arrhythmias, sudden cardiac death.</li>\n<li><strong>Associated risk-factor diseases</strong>: hypertension, diabetes, dyslipidaemia, obesity, metabolic syndrome.</li>\n<li><strong>Other atherosclerotic diseases</strong>: stroke / TIA, peripheral arterial disease, chronic kidney disease.</li>\n<li><strong>Psychological</strong>: depression, anxiety; sexual dysfunction.</li>\n<li>Lifestyle-related: smoking-related lung disease, fatty liver.</li>\n</ol>\n<p><strong>Preventive measures and advice (secondary prevention)</strong></p>\n<p><strong>A. Drugs (lifelong unless contraindicated)</strong></p>\n<ol>\n<li><strong>Aspirin</strong> (+ second antiplatelet such as clopidogrel / ticagrelor for 12 months after MI).</li>\n<li><strong>High-intensity statin</strong> (LDL target &lt;70 mg/dl or lower).</li>\n<li><strong>Beta-blocker</strong>.</li>\n<li><strong>ACE inhibitor / ARB</strong> (especially with LV dysfunction, diabetes, hypertension).</li>\n<li>Treat <strong>hypertension</strong> (&lt;130/80 mmHg) and <strong>diabetes</strong> (HbA1c ~7%).</li>\n<li>Adherence; regular follow-up.</li>\n</ol>\n<p><strong>B. Lifestyle advice</strong></p>\n<ol>\n<li><strong>Stop smoking</strong> and tobacco completely; avoid second-hand smoke.</li>\n<li><strong>Diet</strong>: low salt (&lt;5 g/day), less saturated fat, no trans fat, more fruits, vegetables, whole grains, fish; avoid sweets.</li>\n<li><strong>Physical activity</strong>: start with supervised <strong>cardiac rehabilitation</strong>; then ≥150 minutes/week of moderate activity (brisk walking).</li>\n<li><strong>Weight control</strong> (BMI &lt;23 for South Asians; waist &lt;90 cm).</li>\n<li><strong>Limit alcohol</strong>.</li>\n<li><strong>Stress management</strong>; balance business work, adequate sleep.</li>\n<li>Gradual return to work and normal activity, including sexual activity, as advised.</li>\n</ol>\n<p><strong>C. Other</strong></p>\n<p>Influenza vaccination; recognise warning symptoms (chest pain, breathlessness) and seek urgent care; keep emergency medicines (sublingual nitrate); periodic check of lipids, glucose, ECG, echo.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.713","n":713,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["17M","14Ja","12Ju","07Ju","06S"],"colleges":"DMC (2nd Assess D3)","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>Identify / mention the (modifiable) risk factors for hypertension.</p>","a":"<p><strong>Risk factors for hypertension</strong></p>\n<p><strong>A. Modifiable</strong></p>\n<ol>\n<li><strong>Obesity / overweight</strong> (central obesity).</li>\n<li><strong>High salt (sodium) intake</strong>; low potassium intake (few fruits and vegetables).</li>\n<li><strong>Physical inactivity</strong>.</li>\n<li><strong>Alcohol</strong> excess.</li>\n<li><strong>Tobacco</strong> use.</li>\n<li><strong>Psychosocial stress</strong>.</li>\n<li><strong>Diabetes</strong>, dyslipidaemia.</li>\n<li>Unhealthy diet (high saturated fat).</li>\n<li><strong>Oral contraceptives</strong>; certain drugs (NSAIDs, steroids).</li>\n<li>Obstructive sleep apnoea.</li>\n<li><strong>Environmental</strong>: noise, air pollution; <strong>saline drinking water</strong> in coastal Bangladesh.</li>\n<li>Socio-economic factors, urbanisation.</li>\n</ol>\n<p><strong>B. Non-modifiable</strong></p>\n<p>Age, family history and genetics, sex, ethnicity, low birth weight.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.714","n":714,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>Discuss briefly the non-modifiable risk factors for hypertension.</p>","a":"<p><strong>Non-modifiable risk factors for hypertension</strong></p>\n<ol>\n<li><strong>Age</strong>: BP rises with age (arterial stiffness); systolic hypertension common in elderly.</li>\n<li><strong>Sex</strong>: more in men in young and middle age; in women after menopause.</li>\n<li><strong>Genetic factors / family history</strong>: risk higher if one or both parents are hypertensive; polygenic inheritance.</li>\n<li><strong>Ethnicity</strong>: higher in people of African and South Asian origin.</li>\n<li><strong>Low birth weight</strong> (fetal programming).</li>\n</ol>\n<p>These cannot be changed but identify people for <strong>regular screening</strong> and stricter control of modifiable risks.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.715","n":715,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["16Ju","14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>How can you measure morbidity (like hypertension) in a community?</p>","a":"<p><strong>Measuring morbidity in a community</strong></p>\n<p><strong>A. Measures (Park)</strong></p>\n<ol>\n<li><strong>Incidence rate</strong> (new cases over time).</li>\n<li><strong>Prevalence rate</strong> (point and period).</li>\n<li>Notification rates.</li>\n<li>Hospital data: admissions, OPD attendance, length of stay.</li>\n<li>Sickness absence from work or school.</li>\n<li>Disease registers.</li>\n</ol>\n<p><strong>B. Methods</strong></p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Example for hypertension</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Cross-sectional prevalence survey</strong> (household health examination survey)</td>\n<td>Random sample of adults; <strong>standardised BP measurement</strong> (validated device, correct cuff, rest 5 minutes, 2–3 readings); WHO <strong>STEPS</strong> approach (questionnaire + physical measures + biochemistry)</td>\n</tr>\n<tr>\n<td><strong>Cohort study</strong></td>\n<td>Follow normotensive adults to measure incidence</td>\n</tr>\n<tr>\n<td><strong>Screening camps</strong></td>\n<td>Opportunistic detection at community clinics, NCD corners</td>\n</tr>\n<tr>\n<td><strong>Health interview surveys</strong></td>\n<td>Self-reported diagnosis and treatment</td>\n</tr>\n<tr>\n<td><strong>Routine records</strong></td>\n<td>DHIS2, hospital data, NCD registers</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Indicators for hypertension</strong></p>\n<p>Prevalence; <strong>awareness</strong>, <strong>treatment</strong> and <strong>control</strong> rates (&quot;rule of halves&quot;); risk-factor prevalence (salt, obesity, inactivity).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases; Principles of Epidemiology).</p>"},{"id":"DU.716","n":716,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["16Ja","13Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>State prevention and control measures for hypertension.</p>","a":"<p><strong>Prevention and control of hypertension</strong></p>\n<p><strong>A. Primary prevention</strong></p>\n<table>\n<thead>\n<tr>\n<th>Strategy</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Population strategy</strong></td>\n<td><strong>Salt</strong> &lt;5 g/day; more fruits and vegetables (potassium); less saturated fat; <strong>weight control</strong>; <strong>regular physical activity</strong> (≥150 min/week); <strong>no tobacco</strong>; limit <strong>alcohol</strong>; stress management; health education; food policies (salt reduction, labelling)</td>\n</tr>\n<tr>\n<td><strong>High-risk strategy</strong></td>\n<td>Identify people with prehypertension, obesity, diabetes, family history; intensive lifestyle counselling; regular BP checks</td>\n</tr>\n</tbody>\n</table>\n<p><strong>B. Secondary prevention</strong></p>\n<ol>\n<li><strong>Early detection</strong>: BP screening of all adults (opportunistic and community; NCD corners at UHCs and community clinics).</li>\n<li><strong>Treatment</strong>: lifestyle change + standard drug protocols (e.g., amlodipine, ACE inhibitor/ARB, thiazide); treat to target (&lt;140/90; &lt;130/80 for many high-risk patients).</li>\n<li><strong>Adherence</strong> and follow-up; free/low-cost drugs; patient registers.</li>\n<li>Control of other risk factors (diabetes, lipids).</li>\n</ol>\n<p><strong>C. Tertiary prevention</strong></p>\n<p>Manage complications (stroke, heart failure, kidney disease); rehabilitation.</p>\n<p><strong>D. Health system (WHO HEARTS package)</strong></p>\n<p>Simple treatment protocols, team-based care, reliable drug supply, information systems, community services.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.717","n":717,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["04S"],"colleges":"","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>Discuss the approach for prevention of hypertension.</p>","a":"<p><strong>Approach for prevention of hypertension (Park)</strong></p>\n<ol>\n<li><strong>Population (mass) strategy</strong>: shift the whole population's BP distribution downward by lifestyle and policy measures (salt reduction, healthy diet, physical activity, weight control, no tobacco, limit alcohol); small falls in average BP prevent many strokes and heart attacks.</li>\n<li><strong>High-risk strategy</strong>: find and manage individuals at high risk (raised BP, obesity, diabetes, family history) with counselling and drugs.</li>\n<li><strong>Secondary prevention</strong>: early detection by screening, regular treatment, follow-up, adherence.</li>\n<li><strong>Self-care</strong>: home BP monitoring, adherence.</li>\n<li><strong>Health education</strong>, community participation, intersectoral action.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.718","n":718,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":[],"colleges":"SSMC (2nd Term C3)","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>Write down the epidemiological features of hypertension.</p>","a":"<p><strong>Epidemiological features of hypertension</strong></p>\n<ol>\n<li><strong>Magnitude</strong>: very common; about <strong>1.3 billion adults (30–79 years)</strong> worldwide, about one in three (WHO, 2023); leading risk factor for death (stroke, CHD, kidney disease).</li>\n<li><strong>Iceberg disease</strong>: most cases asymptomatic and undiagnosed; <strong>rule of halves</strong>.</li>\n<li><strong>Age</strong>: BP rises with age.</li>\n<li><strong>Sex</strong>: more in men at younger ages; women after menopause.</li>\n<li><strong>Genetic factors</strong>: family history; tracking of BP from childhood.</li>\n<li><strong>Environmental and lifestyle factors</strong>: high salt, obesity, inactivity, alcohol, tobacco, stress, urbanisation.</li>\n<li><strong>Socio-economic</strong>: rising in low- and middle-income countries; rural–urban transition.</li>\n<li><strong>Ethnicity</strong>: higher in South Asians and Africans.</li>\n<li>Associated with diabetes, dyslipidaemia, CKD.</li>\n<li>Preventable and controllable.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases); WHO, Global report on hypertension, 2023.</p>"},{"id":"DU.719","n":719,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":[],"colleges":"DMC (2nd Assess D3); SSMC (2nd Term C3); MMC (2nd Term D1); MuMC (2nd Final A2)","asked":"","note":"","kind":"","sub":"Hypertension","q":"<p>Explain the &quot;Rule of Halves&quot; in hypertension. / Why is hypertension an iceberg disease in Bangladesh?</p>","a":"<p><strong>Rule of halves</strong></p>\n<p>In a community:</p>\n<ol>\n<li><strong>Half</strong> of all people with hypertension are <strong>not aware</strong> of it.</li>\n<li>Of those aware, <strong>half are not treated</strong>.</li>\n<li>Of those treated, <strong>half are not adequately controlled</strong>.</li>\n</ol>\n<p>→ Only about <strong>one in eight</strong> hypertensives has controlled BP.</p>\n<p><strong>Why hypertension is an iceberg disease in Bangladesh</strong></p>\n<ol>\n<li>Usually <strong>asymptomatic</strong> → people do not seek care.</li>\n<li><strong>Little routine screening</strong>; BP not checked at every contact.</li>\n<li><strong>Low awareness</strong> in rural and poor populations.</li>\n<li><strong>Poor adherence</strong>: drugs stopped when &quot;feeling well&quot;; cost.</li>\n<li><strong>Limited access</strong> to doctors and drugs in rural areas; reliance on informal providers.</li>\n<li>Health system focused on acute care.</li>\n<li>Rising risk factors: salt intake, obesity, inactivity, saline water in coastal areas.</li>\n</ol>\n<p>Hence the visible tip (diagnosed, controlled) is small; the submerged part (undiagnosed, untreated, uncontrolled) is large → need for screening and primary care management.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.720","n":720,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Write down the clinical manifestations of diabetes mellitus with complications and preventive measures.</p>","a":"<p><strong>Clinical manifestations of diabetes mellitus</strong></p>\n<ol>\n<li><strong>Polyuria, polydipsia, polyphagia</strong>.</li>\n<li><strong>Weight loss</strong> (especially type 1), fatigue, weakness.</li>\n<li><strong>Blurred vision</strong>.</li>\n<li><strong>Recurrent infections</strong>: skin, boils, UTI, vaginal candidiasis; slow wound healing.</li>\n<li>Tingling and numbness of feet.</li>\n<li>Many type 2 patients are <strong>asymptomatic</strong> (found on screening).</li>\n</ol>\n<p><strong>Diagnosis (WHO)</strong>: fasting plasma glucose ≥7.0 mmol/L (126 mg/dl), or 2-hour OGTT ≥11.1 mmol/L (200 mg/dl), or HbA1c ≥6.5%, or random ≥11.1 mmol/L with symptoms.</p>\n<p><strong>Complications</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Complications</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Acute</strong></td>\n<td>Diabetic ketoacidosis, hyperosmolar hyperglycaemic state, <strong>hypoglycaemia</strong>, infections</td>\n</tr>\n<tr>\n<td><strong>Microvascular</strong></td>\n<td><strong>Retinopathy</strong> (blindness), <strong>nephropathy</strong> (kidney failure), <strong>neuropathy</strong></td>\n</tr>\n<tr>\n<td><strong>Macrovascular</strong></td>\n<td><strong>CHD, stroke</strong>, peripheral arterial disease</td>\n</tr>\n<tr>\n<td><strong>Diabetic foot</strong></td>\n<td>Ulcers, infection, gangrene, <strong>amputation</strong></td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Cataract, periodontitis, erectile dysfunction, depression; pregnancy complications (macrosomia, congenital anomalies, stillbirth)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Preventive measures</strong></p>\n<ol>\n<li><strong>Primordial / primary</strong>: healthy diet, physical activity, weight control, no tobacco; school and community programmes; screening and lifestyle intervention for prediabetes.</li>\n<li><strong>Secondary</strong>: screening high-risk adults; early treatment; good control of glucose, BP and lipids.</li>\n<li><strong>Tertiary</strong>: regular eye, foot and kidney checks; foot care; rehabilitation; patient education and self-care.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.721","n":721,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":[],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Mention the preventive measures of diabetes.</p>","a":"<p><strong>Preventive measures of diabetes</strong></p>\n<ol>\n<li><strong>Healthy diet</strong>: less sugar and refined carbohydrates, more fibre, vegetables, whole grains; avoid sugary drinks.</li>\n<li><strong>Physical activity</strong>: ≥150 minutes/week.</li>\n<li><strong>Weight control</strong>; avoid central obesity.</li>\n<li><strong>No tobacco</strong>; limit alcohol.</li>\n<li><strong>Screening</strong> of high-risk groups; lifestyle intervention for prediabetes.</li>\n<li>Prevent <strong>LBW</strong> and promote <strong>breastfeeding</strong>.</li>\n<li>Screen and manage <strong>gestational diabetes</strong>.</li>\n<li><strong>Health education</strong>; school and workplace programmes.</li>\n<li><strong>Early treatment</strong> and control of glucose, BP, lipids to prevent complications.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.722","n":722,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["09Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Who are the risk groups of DM?</p>","a":"<p><strong>Risk groups for diabetes mellitus</strong></p>\n<ol>\n<li>Adults <strong>≥40 years</strong> (≥30 with other risk factors).</li>\n<li><strong>Overweight / obese</strong> (BMI ≥23 in South Asians), central obesity.</li>\n<li><strong>Family history</strong> of diabetes (first-degree relatives).</li>\n<li><strong>Physically inactive</strong> people.</li>\n<li>Women with previous <strong>gestational diabetes</strong> or a baby <strong>&gt;4 kg</strong>.</li>\n<li><strong>Prediabetes</strong> (IFG, IGT, HbA1c 5.7–6.4%).</li>\n<li><strong>Hypertension</strong>, dyslipidaemia, CVD.</li>\n<li><strong>Polycystic ovary syndrome</strong>.</li>\n<li>People on long-term steroids, antipsychotics.</li>\n<li>South Asian ethnicity; urban dwellers; smokers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.723","n":723,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["23Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Mention the risk factors of type-2 diabetes mellitus.</p>","a":"<p><strong>Risk factors of type 2 diabetes mellitus</strong></p>\n<p><strong>A. Non-modifiable</strong></p>\n<ol>\n<li><strong>Age</strong> (risk rises after 40).</li>\n<li><strong>Family history</strong> / genetic factors.</li>\n<li><strong>Ethnicity</strong> (South Asians develop diabetes at lower BMI and younger age).</li>\n<li>History of <strong>gestational diabetes</strong>.</li>\n<li><strong>Low birth weight</strong> and early-life undernutrition (fetal programming).</li>\n</ol>\n<p><strong>B. Modifiable</strong></p>\n<ol>\n<li><strong>Obesity</strong>, especially <strong>central (abdominal) obesity</strong>.</li>\n<li><strong>Physical inactivity</strong>; sedentary jobs; screen time.</li>\n<li><strong>Unhealthy diet</strong>: refined carbohydrates (white rice in large amounts), sugary drinks, fast food, low fibre.</li>\n<li><strong>Tobacco</strong> use; heavy alcohol.</li>\n<li><strong>Hypertension</strong>, dyslipidaemia.</li>\n<li><strong>Psychosocial stress</strong>, poor sleep.</li>\n<li>Drugs (steroids, thiazides, antipsychotics).</li>\n<li><strong>Urbanisation</strong> and lifestyle change.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.724","n":724,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>List the host factors of diabetes mellitus.</p>","a":"<p><strong>Host factors of diabetes mellitus (Park)</strong></p>\n<ol>\n<li><strong>Age</strong>: type 1 in young; type 2 rises with age.</li>\n<li><strong>Sex</strong>: varies by population.</li>\n<li><strong>Genetic factors</strong>: strong in type 2 (family clustering); type 1 linked to <strong>HLA</strong> genes (DR3, DR4).</li>\n<li><strong>Genetic markers</strong> and immune mechanisms (autoantibodies in type 1).</li>\n<li><strong>Obesity</strong>.</li>\n<li><strong>Maternal diabetes</strong> (offspring at higher risk).</li>\n<li><strong>Insulin resistance</strong> and insulin levels.</li>\n<li>Ethnicity.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.725","n":725,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["16Nov"],"colleges":"MMC (2nd Term D2)","asked":"mention the types and complications of DM","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>What are the complications of diabetes mellitus?</p>","a":"<p><strong>Complications of diabetes mellitus</strong></p>\n<p><strong>A. Acute</strong></p>\n<ol>\n<li><strong>Hypoglycaemia</strong> (insulin, sulphonylureas).</li>\n<li><strong>Diabetic ketoacidosis</strong> (type 1).</li>\n<li><strong>Hyperosmolar hyperglycaemic state</strong> (type 2, elderly).</li>\n<li><strong>Infections</strong>: skin, UTI, TB, mucormycosis.</li>\n</ol>\n<p><strong>B. Chronic</strong></p>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Complications</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Microvascular</strong></td>\n<td><strong>Retinopathy</strong> (leading cause of blindness in adults), <strong>nephropathy</strong> (CKD, dialysis), <strong>neuropathy</strong> (peripheral, autonomic)</td>\n</tr>\n<tr>\n<td><strong>Macrovascular</strong></td>\n<td><strong>Coronary heart disease</strong>, <strong>stroke</strong>, peripheral arterial disease</td>\n</tr>\n<tr>\n<td><strong>Diabetic foot</strong></td>\n<td>Neuropathic and ischaemic ulcers, infection, gangrene, <strong>amputation</strong></td>\n</tr>\n<tr>\n<td><strong>Eye (others)</strong></td>\n<td>Cataract, glaucoma</td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Periodontitis, erectile dysfunction, gastroparesis, fatty liver, depression, dementia</td>\n</tr>\n<tr>\n<td><strong>In pregnancy</strong></td>\n<td>Miscarriage, congenital anomalies, macrosomia, pre-eclampsia, stillbirth, neonatal hypoglycaemia</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.726","n":726,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["20Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>What do you mean by &quot;self care&quot; in patients with diabetes mellitus?</p>","a":"<p><strong>Self-care in diabetes</strong></p>\n<p>Activities that a person with diabetes (and family) does daily to control the disease and prevent complications, with support from health workers.</p>\n<p><strong>Main self-care behaviours</strong></p>\n<ol>\n<li><strong>Healthy eating</strong>: regular meals, portion control, less sugar and refined carbohydrates, more vegetables and fibre.</li>\n<li><strong>Being physically active</strong>: walking ≥30 minutes most days.</li>\n<li><strong>Monitoring</strong>: blood glucose (glucometer), BP, weight, feet; keep records (diabetic guide book).</li>\n<li><strong>Taking medicines</strong> correctly: tablets, <strong>insulin injection technique</strong>, storage, timing.</li>\n<li><strong>Problem solving</strong>: recognise and treat <strong>hypoglycaemia</strong> (take sugar); sick-day rules.</li>\n<li><strong>Healthy coping</strong>: stress management, family support.</li>\n<li><strong>Reducing risks</strong>: <strong>daily foot care</strong> (inspection, washing, proper footwear, nail care), stop smoking, annual eye and kidney checks, dental care, vaccinations.</li>\n<li><strong>Regular follow-up</strong> with health workers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.727","n":727,"part":11,"topic":"Non-Communicable Diseases","stars":2,"years":["11Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Discipline in life for management of NCDs, especially in DM – explain.</p>","a":"<p><strong>Discipline in life for managing NCDs, especially diabetes</strong></p>\n<p>The Diabetic Association of Bangladesh teaches the <strong>&quot;3 Ds&quot;: Diet, Discipline, Drugs</strong> (with education).</p>\n<p><strong>Discipline means a regular, controlled daily routine:</strong></p>\n<ol>\n<li><strong>Regular meal times</strong> and fixed portions; no skipping or overeating; avoid sweets.</li>\n<li><strong>Daily exercise</strong> at a fixed time.</li>\n<li><strong>Taking drugs/insulin regularly</strong> at the right time and dose.</li>\n<li><strong>Regular self-monitoring</strong> of glucose, BP and weight; records.</li>\n<li><strong>Regular sleep</strong>; stress control.</li>\n<li><strong>No smoking</strong>, no alcohol.</li>\n<li><strong>Foot care</strong> and hygiene every day.</li>\n<li><strong>Regular check-ups</strong> (eye, kidney, heart, feet).</li>\n</ol>\n<p><strong>Why</strong>: NCDs are lifelong; good control depends on steady habits more than on drugs alone; discipline prevents complications and improves quality of life.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.728","n":728,"part":11,"topic":"Non-Communicable Diseases","stars":2,"years":["18M"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Mention the procedure for conducting high-risk screening for diabetes mellitus in an Upazila. Write down the slogan of World Health Day 2018 and briefly explain it.</p>","a":"<p><strong>High-risk screening for diabetes in an upazila</strong></p>\n<ol>\n<li><strong>Planning</strong>: form a team (UH&amp;FPO, medical officers, nurses, CHCPs, HAs); decide target group, sites, schedule; arrange glucometers, strips, lancets, BP machines, weighing scales, registers.</li>\n<li><strong>Target group (high-risk)</strong>: adults ≥40 years, or ≥30 years with obesity, family history, hypertension, previous GDM, inactivity.</li>\n<li><strong>Community mobilisation</strong>: inform through CHCPs, HAs, imams, union parishad, miking.</li>\n<li><strong>Screening sites</strong>: NCD corner at UHC, community clinics, workplaces, camps.</li>\n<li><strong>Risk assessment</strong>: short questionnaire / risk score, BMI, waist, BP.</li>\n<li><strong>Blood glucose test</strong>: capillary fasting or random glucose.</li>\n<li><strong>Confirmation</strong> of positives at UHC: fasting plasma glucose, OGTT or HbA1c.</li>\n<li><strong>Counselling and management</strong>: lifestyle advice for all; treatment and enrolment of diabetics; prediabetes follow-up.</li>\n<li><strong>Records and referral</strong>: register, DHIS2 reporting; refer complicated cases.</li>\n<li><strong>Follow-up and evaluation</strong>: coverage, yield, linkage to care.</li>\n</ol>\n<p><strong>World Health Day 2018 slogan</strong></p>\n<p><strong>&quot;Universal health coverage: everyone, everywhere&quot;</strong> (WHO's 70th anniversary).</p>\n<p><strong>Explanation</strong></p>\n<p>UHC means <strong>all people and communities receive the quality health services they need</strong> (promotion, prevention, treatment, rehabilitation, palliative care) <strong>without suffering financial hardship</strong>. Three dimensions: <strong>who is covered</strong> (population), <strong>which services</strong> are covered, and <strong>how much of the cost</strong> is covered. It is SDG target <strong>3.8</strong>; achieved mainly through strong <strong>primary health care</strong>.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases); WHO, World Health Day 2018.</p>"},{"id":"DU.729","n":729,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["19M"],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p>Mention the primordial prevention of type II diabetes.</p>","a":"<p><strong>Primordial prevention of type 2 diabetes</strong></p>\n<p>Preventing the emergence of risk factors (obesity, inactivity, unhealthy diet) in the population, especially children.</p>\n<ol>\n<li><strong>Healthy school environment</strong>: daily physical education, playgrounds, healthy school meals; ban junk food and sugary drinks near schools.</li>\n<li><strong>Promote breastfeeding</strong> and proper complementary feeding; prevent childhood obesity.</li>\n<li><strong>Maternal nutrition</strong> to prevent LBW (fetal programming).</li>\n<li><strong>Food policies</strong>: sugar-sweetened beverage taxes, front-of-pack labelling, limits on marketing unhealthy food to children, reduce trans fats.</li>\n<li><strong>Urban planning</strong>: parks, walking and cycling paths, safe play spaces.</li>\n<li><strong>Tobacco control</strong> laws.</li>\n<li><strong>Health education</strong> through mass media, schools, families on traditional healthy diets and active living.</li>\n<li>Limit screen time; promote sports.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.730","n":730,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":[],"colleges":"","asked":"","note":"","kind":"","sub":"Diabetes Mellitus","q":"<p><em>(Activities of the Diabetic Association of Bangladesh: see &quot;National Health Situations &amp; Programmes&quot;, Part 6.)</em></p>","a":"<p><strong>Activities of the Diabetic Association of Bangladesh (BADAS)</strong></p>\n<ol>\n<li>Registration and lifelong care of diabetic patients at low cost; free for the poor.</li>\n<li><strong>BIRDEM</strong> (central institute, WHO Collaborating Centre) and affiliated centres in districts and upazilas.</li>\n<li><strong>Health education</strong> of patients and public (diet, discipline, drugs; foot care).</li>\n<li><strong>Prevention</strong>: screening, awareness campaigns, World Diabetes Day.</li>\n<li><strong>Specialist services</strong>: eye, foot, kidney, heart, maternal diabetes, childhood diabetes.</li>\n<li><strong>Rehabilitation</strong> of diabetic patients.</li>\n<li><strong>Training and education</strong>: medical college, university, nursing and allied institutes.</li>\n<li><strong>Research</strong> on diabetes and NCDs.</li>\n<li>Supply of insulin and drugs at fair prices; advocacy.</li>\n</ol>\n<p>(Detailed answer: see DU.305.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.731","n":731,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":[],"colleges":"ShSMC (2nd Term D5)","asked":"","note":"","kind":"Case-based","sub":"Diabetes Mellitus","q":"<p>A 45-year-old office worker with a BMI of 30 kg/m² has a strong family history of diabetes. During a workplace screening, his fasting plasma glucose is found to be 7.4 mmol/L. [2+2+3]</p>\n<ul>\n<li>a) What diagnosis should be suspected and how should it be confirmed? (2)</li>\n<li>b) Identify four risk factors for diabetes mellitus in this patient. (2)</li>\n<li>c) Describe three important community strategies for prevention of type 2 diabetes. (3)</li>\n</ul>","a":"<p><strong>a) Suspected diagnosis and confirmation (2)</strong></p>\n<p><strong>Type 2 diabetes mellitus</strong> (fasting plasma glucose 7.4 mmol/L ≥7.0).</p>\n<p><strong>Confirmation</strong> (asymptomatic person needs a second abnormal test):</p>\n<ol>\n<li>Repeat <strong>fasting plasma glucose</strong> on another day (≥7.0 mmol/L), or</li>\n<li><strong>OGTT</strong>: 2-hour glucose ≥11.1 mmol/L, or</li>\n<li><strong>HbA1c</strong> ≥6.5%.</li>\n</ol>\n<p><strong>b) Four risk factors in this patient (2)</strong></p>\n<ol>\n<li><strong>Obesity</strong> (BMI 30 kg/m²).</li>\n<li><strong>Strong family history</strong> of diabetes.</li>\n<li><strong>Age 45 years</strong>.</li>\n<li><strong>Sedentary office job</strong> (physical inactivity); likely unhealthy diet and stress.</li>\n</ol>\n<p><strong>c) Three community strategies to prevent type 2 diabetes (3)</strong></p>\n<ol>\n<li><strong>Health promotion / lifestyle change for the whole population</strong>: healthy diet, physical activity, weight control, no tobacco; mass media and school programmes; workplace wellness (healthy canteens, exercise breaks).</li>\n<li><strong>High-risk screening and early intervention</strong>: screen adults ≥40 or with risk factors at community clinics, workplaces, NCD corners; structured lifestyle programmes for prediabetes.</li>\n<li><strong>Supportive environment and policy</strong>: taxes on sugary drinks, food labelling, parks and walking paths, restricting junk food near schools; integration of NCD services into PHC.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.732","n":732,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["19Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"Rheumatic Fever","q":"<p>Mention the major criteria of rheumatic fever.</p>","a":"<p><strong>Major criteria of rheumatic fever (Jones)</strong></p>\n<ol>\n<li><strong>Carditis</strong> (clinical or subclinical on echocardiography).</li>\n<li><strong>Polyarthritis</strong> (migratory, large joints).</li>\n<li><strong>Sydenham's chorea</strong>.</li>\n<li><strong>Erythema marginatum</strong>.</li>\n<li><strong>Subcutaneous nodules</strong>.</li>\n</ol>\n<p>(In moderate/high-risk populations such as Bangladesh, <strong>monoarthritis</strong> or <strong>polyarthralgia</strong> also counts as a major manifestation: Revised Jones Criteria, 2015.)</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.733","n":733,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["23Nov","16Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Rheumatic Fever","q":"<p>What are the criteria which help in the diagnosis of rheumatic fever? / State the revised Jones' criteria.</p>","a":"<p><strong>Revised Jones criteria (American Heart Association, 2015)</strong></p>\n<p><strong>Essential</strong>: evidence of <strong>preceding group A streptococcal infection</strong>: raised or rising ASO / anti-DNase B titre, or positive throat culture / rapid antigen test.</p>\n<p><strong>Diagnosis</strong></p>\n<ul>\n<li><strong>Initial attack</strong>: <strong>2 major</strong>, or <strong>1 major + 2 minor</strong> manifestations.</li>\n<li><strong>Recurrent attack</strong>: 2 major, or 1 major + 2 minor, or <strong>3 minor</strong>.</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>Low-risk populations</th>\n<th><strong>Moderate/high-risk populations (e.g., Bangladesh)</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Major</strong></td>\n<td>Carditis (clinical/subclinical); <strong>polyarthritis</strong> only; chorea; erythema marginatum; subcutaneous nodules</td>\n<td>Carditis; <strong>monoarthritis or polyarthritis, or polyarthralgia</strong>; chorea; erythema marginatum; subcutaneous nodules</td>\n</tr>\n<tr>\n<td><strong>Minor</strong></td>\n<td>Polyarthralgia; fever ≥38.5 °C; ESR ≥60 mm/h and/or CRP ≥3 mg/dl; prolonged PR interval</td>\n<td><strong>Monoarthralgia</strong>; fever ≥38 °C; ESR ≥30 mm/h and/or CRP ≥3 mg/dl; prolonged PR interval</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Note</strong>: chorea alone or indolent carditis may be enough for diagnosis once other causes are excluded.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases); AHA Revised Jones Criteria, 2015.</p>"},{"id":"DU.734","n":734,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["08Ja","08Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Rheumatic Fever","q":"<p>How can you prevent rheumatic fever? State the prophylaxis for rheumatic fever.</p>","a":"<p><strong>Prevention of rheumatic fever</strong></p>\n<p><strong>A. Primordial</strong>: improve living conditions: less overcrowding, better housing, nutrition, access to care.</p>\n<p><strong>B. Primary prevention</strong>: prompt treatment of <strong>streptococcal sore throat</strong></p>\n<table>\n<thead>\n<tr>\n<th>Drug</th>\n<th>Dose</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Benzathine penicillin G</strong> IM, single dose</td>\n<td>1.2 million units (≥27 kg); 0.6 million units (&lt;27 kg)</td>\n</tr>\n<tr>\n<td>Oral penicillin V / amoxicillin</td>\n<td>10 days</td>\n</tr>\n<tr>\n<td>Erythromycin / azithromycin</td>\n<td>Penicillin allergy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Secondary prophylaxis</strong> (prevent recurrence in those who had RF)</p>\n<table>\n<thead>\n<tr>\n<th>Drug</th>\n<th>Dose / interval</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Benzathine penicillin G</strong></td>\n<td>1.2 million units IM every <strong>3–4 weeks</strong> (0.6 MU if &lt;27 kg)</td>\n</tr>\n<tr>\n<td>Oral penicillin V</td>\n<td>250 mg twice daily</td>\n</tr>\n<tr>\n<td>Erythromycin</td>\n<td>250 mg twice daily (allergy)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Duration</strong></p>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Duration</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>RF without carditis</td>\n<td>5 years after last attack or until age 21 (whichever longer)</td>\n</tr>\n<tr>\n<td>RF with carditis, no residual valve disease</td>\n<td>10 years or until age 21 (whichever longer)</td>\n</tr>\n<tr>\n<td>RF with residual rheumatic heart disease</td>\n<td>10 years or until age 40 (whichever longer); sometimes lifelong</td>\n</tr>\n</tbody>\n</table>\n<p><strong>D. Tertiary</strong>: manage RHD; endocarditis prevention; surgery.</p>\n<p><strong>E. Programme</strong>: school sore-throat clinics, RF/RHD registers, health education.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.735","n":735,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["14Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Rheumatic Fever","q":"<p>How can you provide secondary prophylaxis to a boy of 10 years suffering from rheumatic fever?</p>","a":"<p><strong>Secondary prophylaxis for a 10-year-old boy with rheumatic fever</strong></p>\n<ol>\n<li><strong>Drug</strong>: <strong>benzathine penicillin G 1.2 million units IM</strong> (0.6 MU if weight &lt;27 kg) <strong>every 3–4 weeks</strong> (3-weekly in high-risk settings).</li>\n<li>Check for <strong>penicillin allergy</strong>; keep adrenaline ready.</li>\n<li><strong>Alternative</strong>: oral penicillin V 250 mg twice daily; erythromycin 250 mg twice daily if allergic.</li>\n<li><strong>Duration</strong>:\n<ul>\n<li>No carditis: for 5 years or until age 21 (≥ age 21 here).</li>\n<li>With carditis, no residual disease: 10 years or until 21.</li>\n<li>With residual RHD: 10 years or until age 40, or longer.</li>\n</ul>\n</li>\n<li><strong>Adherence</strong>: card, register, reminders; involve family and school.</li>\n<li><strong>Regular follow-up</strong>: clinical exam, echocardiography.</li>\n<li>Dental hygiene; antibiotic prophylaxis for endocarditis when indicated.</li>\n<li>Health education about sore throat and prompt treatment.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.736","n":736,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["25Nov"],"colleges":"MMC (2nd Term D5)","asked":"","note":"","kind":"SEQ","sub":"","q":"<p>A 12-year-old girl presented with fever, joint pain and knee swelling. She reports migration of pain to the elbows; she suffered from a throat infection several weeks back. Her mother complains that she is breathing heavily and appears fatigued. On examination, she has tachycardia and a heart murmur. [7]</p>\n<ul>\n<li>a) What do you think about her diagnosis? (2)</li>\n<li>b) How can we diagnose the disease according to criteria? (3)</li>\n<li>c) State the preventive measures of the disease. (2)</li>\n</ul>","a":"<p><strong>a) Diagnosis (2)</strong></p>\n<p><strong>Acute rheumatic fever with carditis</strong> (fever, migratory polyarthritis of knees and elbows after a throat infection, tachycardia, new murmur, breathlessness, fatigue → possible heart failure).</p>\n<p><strong>b) Diagnosis by criteria (3): Revised Jones criteria, 2015</strong></p>\n<ol>\n<li><strong>Evidence of preceding group A streptococcal infection</strong>: raised ASO / anti-DNase B, or positive throat culture.</li>\n<li><strong>Major manifestations present</strong>: <strong>carditis</strong> (murmur, tachycardia; confirm by echocardiography) and <strong>migratory polyarthritis</strong>.</li>\n<li><strong>Minor manifestations</strong>: fever; raised ESR/CRP; prolonged PR interval on ECG.</li>\n<li><strong>2 major</strong> (carditis + polyarthritis) + evidence of strep infection → <strong>acute rheumatic fever</strong>.</li>\n</ol>\n<p>Investigations: ASO, throat swab, CBC, ESR, CRP, ECG, chest X-ray, <strong>echocardiography</strong>.</p>\n<p><strong>c) Preventive measures (2)</strong></p>\n<ol>\n<li><strong>Primary</strong>: early treatment of streptococcal sore throat (benzathine penicillin).</li>\n<li><strong>Secondary prophylaxis</strong>: benzathine penicillin every 3–4 weeks for at least 10 years / until age 21 (longer if residual RHD).</li>\n<li><strong>Primordial</strong>: better housing, less crowding, nutrition.</li>\n<li>Health education; school screening; RHD registers.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.737","n":737,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["25M","04S"],"colleges":"","asked":"","note":"","kind":"","sub":"Cancer","q":"<p>Define cancer.</p>","a":"<p><strong>Definition of cancer</strong></p>\n<p><strong>Park</strong>: a group of diseases characterised by:</p>\n<ol>\n<li><strong>Abnormal growth of cells</strong>,</li>\n<li>Ability to <strong>invade adjacent tissues</strong> and even <strong>distant organs</strong> (metastasis),</li>\n<li>Eventual <strong>death</strong> of the patient if the tumour has progressed beyond the stage when it can be successfully removed.</li>\n</ol>\n<p><strong>WHO</strong>: a large group of diseases in which abnormal cells grow beyond their usual boundaries, invade adjoining parts of the body and spread to other organs (metastasis).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.738","n":738,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["25M","19Nov","14Ja","07Ju"],"colleges":"MMC (2nd Term D2)","asked":"","note":"","kind":"","sub":"Cancer","q":"<p>Write down six warning signs of cancer / danger signals of cancer / early warning signs.</p>","a":"<p><strong>Warning signs (danger signals) of cancer (Park)</strong></p>\n<ol>\n<li>A <strong>lump or hard area in the breast</strong>.</li>\n<li>A <strong>change in a wart or mole</strong>.</li>\n<li>A <strong>persistent change in digestive or bowel habits</strong>.</li>\n<li>A <strong>persistent cough or hoarseness</strong>.</li>\n<li><strong>Excessive loss of blood at menstruation</strong> or bleeding outside the usual dates.</li>\n<li><strong>Blood loss from any natural orifice</strong>.</li>\n<li>A <strong>swelling or sore that does not heal</strong>.</li>\n<li><strong>Unexplained loss of weight</strong>.</li>\n</ol>\n<p><strong>Mnemonic (CAUTION)</strong>: Change in bowel/bladder habits; A sore that does not heal; Unusual bleeding or discharge; Thickening or lump; Indigestion or difficulty swallowing; Obvious change in wart or mole; Nagging cough or hoarseness.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.739","n":739,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["25M","14Ju","10Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Cancer","q":"<p>Enumerate four environmental factors of cancer / focus on environmental factors of cancer aetiology.</p>","a":"<p><strong>Environmental factors in cancer aetiology (Park)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Factor</th>\n<th>Cancers</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Tobacco</strong> (smoking, chewing, betel quid)</td>\n<td>Lung, oral, larynx, oesophagus, bladder, pancreas, cervix</td>\n</tr>\n<tr>\n<td><strong>2. Alcohol</strong></td>\n<td>Mouth, pharynx, oesophagus, liver, breast</td>\n</tr>\n<tr>\n<td><strong>3. Dietary factors</strong></td>\n<td>Smoked and salted foods, nitrosamines (stomach); aflatoxin (liver); low fibre, high fat, red/processed meat (colon)</td>\n</tr>\n<tr>\n<td><strong>4. Occupational exposures</strong></td>\n<td>Asbestos (mesothelioma, lung), aromatic amines (bladder), benzene (leukaemia), vinyl chloride (liver), arsenic, chromium, nickel</td>\n</tr>\n<tr>\n<td><strong>5. Viruses</strong></td>\n<td>HBV, HCV (liver), <strong>HPV</strong> (cervix, oral), EBV (nasopharynx, lymphoma), HTLV-1</td>\n</tr>\n<tr>\n<td><strong>6. Parasites and bacteria</strong></td>\n<td>Schistosoma (bladder), liver flukes (bile duct), <em>H. pylori</em> (stomach)</td>\n</tr>\n<tr>\n<td><strong>7. Radiation</strong></td>\n<td>Ionising (leukaemia, thyroid), UV (skin)</td>\n</tr>\n<tr>\n<td><strong>8. Customs and habits</strong></td>\n<td>Betel quid chewing, early marriage (cervix), reverse smoking</td>\n</tr>\n<tr>\n<td><strong>9. Others</strong></td>\n<td>Air pollution, <strong>arsenic in drinking water</strong> (skin, lung, bladder), medicinal drugs (hormones, immunosuppressants), sexual behaviour</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.740","n":740,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["17M","12Ju"],"colleges":"","asked":"","note":"","kind":"","sub":"Cancer","q":"<p>Explain lifestyle as a determinant of cancer.</p>","a":"<p><strong>Lifestyle as a determinant of cancer</strong></p>\n<p>About <strong>one-third of cancer deaths</strong> are due to tobacco use, high body mass index, alcohol, low fruit and vegetable intake and lack of physical activity (WHO).</p>\n<table>\n<thead>\n<tr>\n<th>Lifestyle factor</th>\n<th>Cancers</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Tobacco smoking</strong></td>\n<td>Lung (most), larynx, bladder, pancreas, kidney, cervix</td>\n</tr>\n<tr>\n<td><strong>Smokeless tobacco and betel quid</strong> (zarda, gul, shada pata)</td>\n<td><strong>Oral cancer</strong> (very common in Bangladesh), oesophagus</td>\n</tr>\n<tr>\n<td><strong>Alcohol</strong></td>\n<td>Mouth, throat, oesophagus, liver, breast</td>\n</tr>\n<tr>\n<td><strong>Unhealthy diet</strong></td>\n<td>Colorectal (red/processed meat, low fibre), stomach (salted, smoked foods), liver (aflatoxin)</td>\n</tr>\n<tr>\n<td><strong>Obesity and physical inactivity</strong></td>\n<td>Breast (post-menopausal), colon, endometrium, kidney, oesophagus</td>\n</tr>\n<tr>\n<td><strong>Sexual behaviour</strong></td>\n<td>Cervical, anal, oral (HPV); Kaposi's sarcoma (HIV)</td>\n</tr>\n<tr>\n<td><strong>Reproductive pattern</strong></td>\n<td>Breast (late first pregnancy, nulliparity, not breastfeeding); cervix (early marriage, many births)</td>\n</tr>\n<tr>\n<td><strong>Sun exposure</strong></td>\n<td>Skin cancers</td>\n</tr>\n<tr>\n<td><strong>Unsafe injections</strong></td>\n<td>Liver (HBV, HCV)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Implications</strong></p>\n<p>Most of these are <strong>modifiable</strong> → 30–50% of cancers are preventable by lifestyle change, vaccination (HBV, HPV) and policy (tobacco taxes, smoke-free laws).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases); WHO, Cancer fact sheet.</p>"},{"id":"DU.741","n":741,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["12Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"Cancer","q":"<p>How can you control cervical cancer in a rural setting?</p>","a":"<p><strong>Control of cervical cancer in a rural setting</strong></p>\n<p><strong>A. Primary prevention</strong></p>\n<ol>\n<li><strong>HPV vaccination</strong> of girls (Bangladesh introduced HPV vaccine for adolescent girls).</li>\n<li><strong>Health education</strong>: delay marriage and first pregnancy, safe sex, condoms, genital hygiene, stop tobacco.</li>\n<li>Treat STIs; prevent HIV.</li>\n</ol>\n<p><strong>B. Secondary prevention: screening and early treatment</strong></p>\n<ol>\n<li><strong>VIA (visual inspection with acetic acid)</strong> for women aged <strong>30–60</strong> at UHCs, union centres and camps (national screening programme); every 3–5 years.</li>\n<li><strong>HPV DNA testing</strong> where available (WHO preferred).</li>\n<li><strong>Screen-and-treat</strong>: thermal ablation or cryotherapy at the same visit for eligible lesions.</li>\n<li>Referral to colposcopy and LEEP for larger lesions.</li>\n<li>Mobilisation through CHCPs, FWAs.</li>\n</ol>\n<p><strong>C. Tertiary</strong></p>\n<p>Treatment (surgery, radiotherapy) at referral centres; <strong>palliative care</strong>.</p>\n<p><strong>WHO elimination targets (90-70-90 by 2030)</strong>: 90% of girls vaccinated by 15; 70% of women screened by 35 and 45 with a high-performance test; 90% of identified women treated.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases); WHO, Global strategy to eliminate cervical cancer, 2020.</p>"},{"id":"DU.742","n":742,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":[],"colleges":"DMC (2nd Assess D5)","asked":"","note":"","kind":"Case-based","sub":"","q":"<p>A 52-year-old woman from a lower socioeconomic background presents with irregular vaginal bleeding. She was married at an early age and had 4 children. [7]</p>\n<ul>\n<li>a) What was the probable diagnosis? (1)</li>\n<li>b) Mention risk factors relevant to the disease. (2)</li>\n<li>c) State the primary and secondary levels of preventive measures. (4)</li>\n</ul>","a":"<p><strong>a) Probable diagnosis (1)</strong></p>\n<p><strong>Carcinoma of the cervix</strong> (irregular vaginal bleeding in a 52-year-old woman with early marriage and high parity).</p>\n<p><strong>b) Risk factors (2)</strong></p>\n<ol>\n<li><strong>Persistent high-risk HPV infection</strong> (types 16, 18): the necessary cause.</li>\n<li><strong>Early marriage / early first intercourse</strong>.</li>\n<li><strong>High parity</strong> (4 children).</li>\n<li><strong>Low socio-economic status</strong>, poor genital hygiene.</li>\n<li><strong>Multiple sexual partners</strong> (of woman or husband); STIs; HIV.</li>\n<li><strong>Tobacco</strong> use (smoking, smokeless).</li>\n<li>Long-term oral contraceptive use.</li>\n<li><strong>No previous screening</strong>.</li>\n</ol>\n<p><strong>c) Primary and secondary prevention (4)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Measures</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primary</strong></td>\n<td><strong>HPV vaccination</strong> of girls (9–14 years) before sexual debut; <strong>delay marriage</strong> and first pregnancy; health education on safe sex, condoms, genital hygiene; stop tobacco; treat STIs and prevent HIV; family planning (fewer pregnancies)</td>\n</tr>\n<tr>\n<td><strong>Secondary</strong></td>\n<td><strong>Screening</strong> of women 30–60 years: <strong>VIA</strong>, <strong>HPV DNA test</strong>, Pap smear; <strong>screen-and-treat</strong> (thermal ablation, cryotherapy); colposcopy and LEEP for larger lesions; awareness of warning signs (post-coital, inter-menstrual or post-menopausal bleeding) and prompt referral for biopsy</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"},{"id":"DU.743","n":743,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["23Nov","22Nov","17Nov","17Ja","16Nov","16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Geriatric Health Problems","q":"<p>Identify the common health problems / issues of senior citizens (aged persons) of Bangladesh. / Enlist the common geriatric health problems.</p>","a":"<p><strong>Common health problems of the elderly (Bangladesh)</strong></p>\n<p><strong>A. Due to ageing process (Park)</strong></p>\n<p>Senile <strong>cataract</strong>, glaucoma; <strong>hearing loss</strong> (presbycusis); <strong>osteoporosis</strong>; emphysema; failure of special senses; changes in mental outlook.</p>\n<p><strong>B. Long-term (chronic) illness</strong></p>\n<ol>\n<li><strong>Cardiovascular</strong>: hypertension, CHD, <strong>stroke</strong>, heart failure.</li>\n<li><strong>Metabolic</strong>: <strong>diabetes</strong>, gout.</li>\n<li><strong>Joints</strong>: <strong>osteoarthritis</strong>, back pain.</li>\n<li><strong>Respiratory</strong>: COPD, TB.</li>\n<li><strong>Cancers</strong>.</li>\n<li><strong>Mental</strong>: <strong>dementia</strong>, <strong>depression</strong>, delirium.</li>\n<li><strong>Genito-urinary</strong>: prostate enlargement, incontinence, UTI.</li>\n<li><strong>Falls and fractures</strong> (hip).</li>\n<li><strong>Malnutrition</strong>, anaemia; oral problems (tooth loss).</li>\n<li><strong>Multimorbidity and polypharmacy</strong>.</li>\n</ol>\n<p><strong>C. Psychological</strong></p>\n<p>Loneliness, anxiety, depression, insecurity, loss of purpose.</p>\n<p><strong>D. Social and economic (Bangladesh)</strong></p>\n<ol>\n<li><strong>Breakdown of joint families</strong>; children migrate → <strong>neglect</strong>, lack of care.</li>\n<li><strong>Poverty</strong>, dependence; limited pension (only government retirees); old-age allowance is small.</li>\n<li><strong>Elder abuse</strong>.</li>\n<li>Few <strong>geriatric services</strong> and trained staff; long-term care facilities rare.</li>\n<li>Gender: widows most vulnerable.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.744","n":744,"part":11,"topic":"Non-Communicable Diseases","stars":3,"years":["16M"],"colleges":"","asked":"","note":"","kind":"","sub":"Geriatric Health Problems","q":"<p>Explain healthy aging through healthy life style.</p>","a":"<p><strong>Healthy ageing through a healthy lifestyle</strong></p>\n<p><strong>Healthy ageing (WHO)</strong>: the process of developing and maintaining the <strong>functional ability</strong> that enables well-being in older age.</p>\n<p><strong>Healthy lifestyle measures</strong></p>\n<ol>\n<li><strong>Balanced diet</strong>: adequate protein, calcium, vitamin D, fibre, fruits and vegetables; less salt, sugar and fat; adequate water.</li>\n<li><strong>Regular physical activity</strong>: ≥150 minutes/week of moderate activity + <strong>muscle-strengthening and balance</strong> exercises (prevents falls, keeps independence).</li>\n<li><strong>No tobacco</strong>; avoid alcohol.</li>\n<li><strong>Healthy weight</strong>.</li>\n<li><strong>Adequate sleep</strong>; stress management.</li>\n<li><strong>Mental activity</strong>: reading, learning, hobbies → delays cognitive decline.</li>\n<li><strong>Social engagement</strong>: family, friends, community and religious activities; volunteering.</li>\n<li><strong>Preventive check-ups</strong>: BP, glucose, lipids, eyes, hearing, teeth, cancer screening.</li>\n<li><strong>Vaccination</strong>: influenza, pneumococcal, Td, zoster where available.</li>\n<li><strong>Fall prevention</strong>: safe home, good lighting, proper footwear, vision correction.</li>\n<li><strong>Medicine review</strong>: avoid unnecessary drugs.</li>\n<li>Oral and foot care; good personal hygiene.</li>\n<li><strong>Financial and life planning</strong> for old age.</li>\n</ol>\n<p><strong>Life-course approach</strong>: healthy habits started early give the best ageing.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.745","n":745,"part":11,"topic":"Health Administration","stars":3,"years":["25Nov"],"colleges":"MMC (2nd Term B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Define management, administration and planning.</p>","a":"<p><strong>Definitions</strong></p>\n<table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Definition</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Management</strong></td>\n<td>The process of <strong>getting things done through people</strong> by <strong>planning, organising, staffing, directing and controlling</strong> resources (men, money, materials, time) to achieve stated objectives efficiently</td>\n</tr>\n<tr>\n<td><strong>Administration</strong></td>\n<td>The <strong>top-level</strong> function of determining <strong>policies, objectives</strong> and overall direction of an organisation, and coordinating its parts; concerned with &quot;what&quot; and &quot;why&quot;</td>\n</tr>\n<tr>\n<td><strong>Planning</strong></td>\n<td>The process of <strong>deciding in advance what to do, how, when and by whom</strong>: selecting objectives and the best course of action among alternatives, with available resources</td>\n</tr>\n<tr>\n<td><strong>Health planning</strong> (Park)</td>\n<td>Planning concerned with <strong>improving health</strong>: a process of defining community health problems, identifying needs and resources, setting priorities and goals, and designing, implementing and evaluating action to meet those needs</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.746","n":746,"part":11,"topic":"Health Administration","stars":3,"years":["22Nov","21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What are the types of administration? Categorize administration.</p>","a":"<p><strong>Types (categories) of administration</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Sector</strong></td>\n<td><strong>Public administration</strong> (government: MOHFW, DGHS) / <strong>Private administration</strong> (private hospitals, NGOs)</td>\n</tr>\n<tr>\n<td><strong>Level</strong></td>\n<td><strong>Top (policy)</strong>: ministry, directorate; <strong>Middle (executive)</strong>: division, district (civil surgeon); <strong>Lower (operational / supervisory)</strong>: upazila (UH&amp;FPO), union</td>\n</tr>\n<tr>\n<td><strong>Structure</strong></td>\n<td><strong>Centralised</strong> / <strong>Decentralised</strong></td>\n</tr>\n<tr>\n<td><strong>Organisational form</strong></td>\n<td><strong>Line</strong> (direct chain of command), <strong>Staff</strong> (advisory), <strong>Line and staff</strong>, Functional, Committee</td>\n</tr>\n<tr>\n<td><strong>Function</strong></td>\n<td>General, personnel, financial, material (logistics), health / hospital administration</td>\n</tr>\n<tr>\n<td><strong>Style</strong></td>\n<td>Autocratic, democratic, bureaucratic, laissez-faire</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.747","n":747,"part":11,"topic":"Health Administration","stars":3,"years":["22Nov"],"colleges":"DMC (2nd Assess C4)","asked":"five key functions of management according to Henry Fayol","note":"","kind":"","sub":"","q":"<p>Mention the functions of management.</p>","a":"<p><strong>Functions of management (POSDCORB, Gulick)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Function</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Planning</strong></td>\n<td>Setting objectives and deciding how to achieve them</td>\n</tr>\n<tr>\n<td><strong>Organising</strong></td>\n<td>Dividing work, setting structure, assigning authority and responsibility</td>\n</tr>\n<tr>\n<td><strong>Staffing</strong></td>\n<td>Recruiting, training, placing and retaining personnel</td>\n</tr>\n<tr>\n<td><strong>Directing</strong></td>\n<td>Leading, motivating, communicating, supervising</td>\n</tr>\n<tr>\n<td><strong>Coordinating</strong></td>\n<td>Linking activities of different people and units</td>\n</tr>\n<tr>\n<td><strong>Reporting</strong></td>\n<td>Keeping superiors and staff informed (records, MIS)</td>\n</tr>\n<tr>\n<td><strong>Budgeting</strong></td>\n<td>Financial planning, accounting, control</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Control / evaluation</strong>: monitoring performance against plans and correcting deviations (Fayol: plan, organise, command, coordinate, control).</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.748","n":748,"part":11,"topic":"Health Administration","stars":3,"years":["21M","19M"],"colleges":"ShSMC (2nd Term C4)","asked":"differentiate between leadership and management","note":"","kind":"","sub":"","q":"<p>Differentiate management from administration.</p>","a":"<p><strong>Management vs administration</strong></p>\n<table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Administration</th>\n<th>Management</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nature</td>\n<td><strong>Thinking</strong>, policy-making function</td>\n<td><strong>Doing</strong>, executive function</td>\n</tr>\n<tr>\n<td>Concerned with</td>\n<td><strong>Determining objectives, policies</strong></td>\n<td><strong>Implementing</strong> policies to achieve objectives</td>\n</tr>\n<tr>\n<td>Level</td>\n<td><strong>Top level</strong> (ministry, board)</td>\n<td>Middle and lower levels</td>\n</tr>\n<tr>\n<td>Decisions</td>\n<td>Broad, long-term</td>\n<td>Operational, day-to-day</td>\n</tr>\n<tr>\n<td>Key question</td>\n<td>&quot;What&quot; and &quot;why&quot;</td>\n<td>&quot;How&quot;, &quot;when&quot;, &quot;who&quot;</td>\n</tr>\n<tr>\n<td>Skills</td>\n<td>Conceptual, administrative</td>\n<td>Technical, human</td>\n</tr>\n<tr>\n<td>Influence</td>\n<td>Public opinion, government policy</td>\n<td>Administration's policies</td>\n</tr>\n<tr>\n<td>Usage</td>\n<td>Government, public offices</td>\n<td>Business, projects, hospitals</td>\n</tr>\n<tr>\n<td>Example</td>\n<td>MOHFW sets health policy</td>\n<td>UH&amp;FPO runs the UHC and programmes</td>\n</tr>\n</tbody>\n</table>\n<p>Both overlap in practice; in health systems the terms are often used together.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.749","n":749,"part":11,"topic":"Health Administration","stars":3,"years":["22Nov","21M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Define and categorize plan / mention the types of plan.</p>","a":"<p><strong>Plan</strong></p>\n<p>A <strong>predetermined course of action</strong> to achieve stated objectives, specifying what, how, when, by whom and with what resources.</p>\n<p><strong>Types of plans</strong></p>\n<table>\n<thead>\n<tr>\n<th>Basis</th>\n<th>Types</th>\n<th>Example (Bangladesh)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Time</strong></td>\n<td>Long-term (perspective, 15–20 years); medium-term (5 years); short-term (annual / operational)</td>\n<td>Perspective Plan 2021–2041; Five-Year Plans; Annual Operational Plans</td>\n</tr>\n<tr>\n<td><strong>Scope</strong></td>\n<td>Strategic, tactical, operational</td>\n<td>National health strategy vs upazila work plan</td>\n</tr>\n<tr>\n<td><strong>Level</strong></td>\n<td>National, divisional, district, upazila</td>\n<td>District health plan</td>\n</tr>\n<tr>\n<td><strong>Coverage</strong></td>\n<td>Comprehensive (multisectoral) / sectoral / programme or project</td>\n<td>Health, Population and Nutrition Sector Programme; EPI plan</td>\n</tr>\n<tr>\n<td><strong>Use</strong></td>\n<td><strong>Standing plans</strong> (policies, procedures, rules) / <strong>single-use plans</strong> (programmes, projects, budgets)</td>\n<td>Drug policy vs dengue campaign</td>\n</tr>\n<tr>\n<td><strong>Flexibility</strong></td>\n<td>Rigid / flexible</td>\n<td>—</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.750","n":750,"part":11,"topic":"Health Administration","stars":3,"years":["25Nov"],"colleges":"DMC (2nd Assess C4); SSMC (2nd Term C4)","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the components of the planning cycle / mention the steps in the planning process.</p>","a":"<p><strong>Planning cycle (steps in health planning, Park)</strong></p>\n<p>Analysis of situation → Objectives → Resources → Priorities → Write-up → Programming and implementation → Monitoring → Evaluation → (back to analysis)</p>\n<table>\n<thead>\n<tr>\n<th>Step</th>\n<th>Activities</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Analysis of the health situation</strong></td>\n<td>Collect data on population, health status, determinants, services; identify problems and needs</td>\n</tr>\n<tr>\n<td><strong>2. Establishment of objectives and goals</strong></td>\n<td>Clear, measurable, time-bound targets</td>\n</tr>\n<tr>\n<td><strong>3. Assessment of resources</strong></td>\n<td>Manpower, money, materials, facilities, time</td>\n</tr>\n<tr>\n<td><strong>4. Fixing priorities</strong></td>\n<td>By size, severity, feasibility, cost-effectiveness, community concern</td>\n</tr>\n<tr>\n<td><strong>5. Write-up of the formulated plan</strong></td>\n<td>Activities, responsibilities, timeline, budget</td>\n</tr>\n<tr>\n<td><strong>6. Programming and implementation</strong></td>\n<td>Organisation, staffing, training, logistics, execution</td>\n</tr>\n<tr>\n<td><strong>7. Monitoring</strong></td>\n<td>Day-to-day follow-up of activities against plan</td>\n</tr>\n<tr>\n<td><strong>8. Evaluation</strong></td>\n<td>Measure achievement of objectives, efficiency, impact → feedback for re-planning</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.751","n":751,"part":11,"topic":"Health Administration","stars":0,"years":[],"colleges":"MMC (2nd Term B2)","asked":"","note":"","kind":"","sub":"","q":"<p>Why is planning necessary?</p>","a":"<p><strong>Why planning is necessary</strong></p>\n<ol>\n<li><strong>Resources are limited</strong>; needs are many → best use of resources.</li>\n<li>Sets <strong>priorities</strong> among competing problems.</li>\n<li>Gives <strong>clear objectives and direction</strong>.</li>\n<li><strong>Efficiency</strong>: avoids waste and duplication.</li>\n<li><strong>Coordination</strong> among sectors and agencies.</li>\n<li>Prepares for the <strong>future</strong> (population growth, epidemics, disasters).</li>\n<li>Provides a <strong>basis for monitoring and evaluation</strong>.</li>\n<li><strong>Accountability</strong> and transparency.</li>\n<li>Helps <strong>mobilise resources</strong> (government, donors).</li>\n<li>Reduces uncertainty and crisis management.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Planning and Management).</p>"},{"id":"DU.752","n":752,"part":11,"topic":"Health Administration","stars":3,"years":["24Nov","22M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Illustrate the organogram of Upazila Health Complex (UHC).</p>","a":"<p><strong>Organogram of an Upazila Health Complex</strong></p>\n<pre><code>                     Upazila Health &amp; Family Planning Officer (UH&amp;FPO)\n                                (administrative head)\n        ┌───────────────────────────┼───────────────────────────┐\n  Clinical services           Public health / field          Administration\n        │                           │                           │\n Resident Medical Officer    Health Inspector (HI)        Head assistant, accountant,\n        │                           │                     storekeeper, statistician\n Junior consultants          Assistant Health              (MIS), drivers, support staff\n (medicine, surgery,          Inspectors (AHI)\n gynae-obs, paediatrics,            │\n anaesthesia, others)        Health Assistants (HA)\n        │                           │\n Medical officers,           Community Health Care\n dental surgeon                Providers (CHCPs) at\n        │                      community clinics\n Nursing supervisor → nurses, midwives\n SACMO, pharmacist, medical technologists\n (lab, radiology, dental), EPI technician\n\n Coordination: Upazila Family Planning Officer (UFPO) → FPI, FWV, FWA (DGFP)\n</code></pre>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.753","n":753,"part":11,"topic":"Health Administration","stars":3,"years":["18M","16Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Enlist the auxiliary workers working at UHC. Write down the functions of a grass-root level health worker.</p>","a":"<p><strong>Auxiliary health workers at UHC</strong></p>\n<p>SACMO (sub-assistant community medical officer); nurses and midwives; pharmacist; medical technologists (laboratory, radiography, dental, physiotherapy); EPI technician; Health Inspector, Assistant Health Inspectors, <strong>Health Assistants</strong>; <strong>CHCPs</strong>; (from family planning) FWV, FPI, <strong>FWA</strong>; ward attendants, ayas, cleaners.</p>\n<p><strong>Functions of grass-root health workers (HA, FWA, CHCP)</strong></p>\n<ol>\n<li><strong>Immunisation</strong> (EPI) and campaigns (vitamin A, deworming).</li>\n<li><strong>Family planning</strong>: counselling, pills, condoms, injectables; referral for LARC/permanent methods.</li>\n<li><strong>MCH</strong>: identify pregnant women, ANC and PNC advice, safe delivery, newborn care.</li>\n<li><strong>Health education</strong>: hygiene, nutrition, safe water, sanitation.</li>\n<li><strong>Treatment of minor ailments</strong>, first aid; ORS.</li>\n<li><strong>Surveillance</strong>: report births, deaths, notifiable diseases (AFP, measles).</li>\n<li><strong>TB, leprosy, malaria</strong> case finding and follow-up.</li>\n<li><strong>Registration</strong> and record keeping (households, eligible couples).</li>\n<li><strong>Referral</strong> to community clinic, union centre, UHC.</li>\n<li><strong>Community mobilisation</strong>; support community clinics.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.754","n":754,"part":11,"topic":"Health Administration","stars":3,"years":["19M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Mention the duties of the administrative head of UHC.</p>","a":"<p><strong>Duties of the administrative head of UHC (UH&amp;FPO)</strong></p>\n<ol>\n<li><strong>Overall administration</strong> of the UHC and upazila health services; staff management, discipline, leave, posting.</li>\n<li><strong>Planning and budgeting</strong>; annual work plans; financial management.</li>\n<li><strong>Supervision</strong> of clinical services (OPD, indoor, emergency, OT, labour room) and quality of care.</li>\n<li><strong>Implementation of national programmes</strong>: EPI, TB, leprosy, malaria, nutrition, NCD, MNCH.</li>\n<li><strong>Supervision of field staff</strong> and <strong>community clinics</strong>.</li>\n<li><strong>Surveillance</strong> and <strong>outbreak response</strong>; disaster management.</li>\n<li><strong>Logistics</strong>: drugs, equipment, supplies, stores, transport.</li>\n<li><strong>Health information</strong>: DHIS2 reporting, monthly reports to civil surgeon.</li>\n<li><strong>Coordination</strong>: upazila parishad, UNO, UFPO, DPHE, education, NGOs.</li>\n<li><strong>Training</strong> of staff; supervision of interns.</li>\n<li><strong>Medicolegal</strong> duties and certificates.</li>\n<li><strong>Community participation</strong>; health education; grievance handling.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community; Health Planning and Management).</p>"},{"id":"DU.755","n":755,"part":11,"topic":"Health Administration","stars":3,"years":["21M"],"colleges":"","asked":"","note":"Also listed in PHC, Part 1","kind":"","sub":"","q":"<p>Produce your idea about health care set-up from upazilla to grass-root level.</p>","a":"<p><strong>Health care set-up from upazila to grass-root level</strong></p>\n<table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Facility / workers</th>\n<th>Services</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Upazila</strong></td>\n<td><strong>Upazila Health Complex</strong> (31/50 beds); UH&amp;FPO; UFPO</td>\n<td>First-referral hospital: indoor, outdoor, emergency, EmOC, lab, X-ray; MCH-FP; national programmes; supervision</td>\n</tr>\n<tr>\n<td><strong>Union</strong></td>\n<td><strong>Union Health and Family Welfare Centre</strong> (FWV, SACMO); <strong>Union Sub-centre / Rural Dispensary</strong> (MO/SACMO)</td>\n<td>Outpatient care, ANC/PNC, normal delivery (selected), family planning, immunisation, referral</td>\n</tr>\n<tr>\n<td><strong>Ward</strong></td>\n<td><strong>Community clinic</strong> (CHCP), one per ~6,000 people</td>\n<td>One-stop primary care: MCH, FP, EPI, nutrition, minor treatment, NCD screening, health education, referral</td>\n</tr>\n<tr>\n<td><strong>Village / household</strong></td>\n<td><strong>Health Assistant</strong>, <strong>FWA</strong>, NGO volunteers</td>\n<td>Domiciliary services: EPI, FP supplies, health education, surveillance, registration</td>\n</tr>\n<tr>\n<td><strong>Outreach</strong></td>\n<td>EPI outreach sites, satellite clinics</td>\n<td>Immunisation, FP, ANC in hard-to-reach areas</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Flow (referral)</strong>: Household → Community clinic → Union centre → Upazila Health Complex → District hospital.</p>\n<p><strong>Ideas for strengthening</strong>: fill vacant posts, ensure drugs and equipment, functional referral and transport, community participation, digital records, quality improvement, urban PHC linkage.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.756","n":756,"part":11,"topic":"Health Administration","stars":3,"years":["22M"],"colleges":"","asked":"","note":"Also listed in PHC, Part 1","kind":"","sub":"","q":"<p>Enumerate responsibilities of UH&amp;FPO.</p>","a":"<p><strong>Responsibilities of UH&amp;FPO</strong></p>\n<ol>\n<li>Administrative head of <strong>UHC</strong> and upazila health system.</li>\n<li><strong>Planning, budgeting</strong> and logistics management.</li>\n<li>Ensuring quality <strong>clinical services</strong> (OPD, indoor, emergency, EmOC).</li>\n<li>Implementation and monitoring of <strong>national health programmes</strong>.</li>\n<li><strong>Supervision</strong> of medical officers, nurses, field staff and <strong>community clinics</strong>.</li>\n<li><strong>Disease surveillance</strong>, notification, outbreak and disaster response.</li>\n<li><strong>Health information</strong> management and reporting.</li>\n<li><strong>Coordination</strong> with upazila administration, family planning, other sectors and NGOs.</li>\n<li><strong>Training</strong> and capacity building of staff.</li>\n<li><strong>Medicolegal</strong> duties; certificates.</li>\n<li><strong>Health education</strong> and community participation.</li>\n<li>Ensuring <strong>equity</strong> and access for vulnerable groups.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Health Care of the Community).</p>"},{"id":"DU.757","n":757,"part":10,"topic":"Disasters","stars":0,"years":["25Nov"],"colleges":"MuMC (2nd Final A3)","asked":"","note":"Also listed in Disasters, Part 10","kind":"","sub":"","q":"<p>What do you mean by triage?</p>","a":"<p><strong>Triage</strong></p>\n<p>The <strong>rapid sorting of patients or casualties by severity and urgency of need</strong>, so that limited resources save the greatest number of lives; used in emergency departments and mass-casualty events.</p>\n<p><strong>Colour codes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Colour</th>\n<th>Priority</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Red</strong></td>\n<td>Immediate: life-threatening, treatable</td>\n</tr>\n<tr>\n<td><strong>Yellow</strong></td>\n<td>Delayed: serious but stable</td>\n</tr>\n<tr>\n<td><strong>Green</strong></td>\n<td>Minor (walking wounded)</td>\n</tr>\n<tr>\n<td><strong>Black</strong></td>\n<td>Dead or expectant</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Principles</strong>: quick, simple, repeated (re-triage), done by trained staff at the point of entry.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Disaster Management).</p>"},{"id":"DU.758","n":758,"part":1,"topic":"Introduction to Community Medicine","stars":0,"years":["25Nov"],"colleges":"MMC (2nd Term A5)","asked":"","note":"Also listed in Introduction, Part 1","kind":"","sub":"","q":"<p>Write the importance of integrity and accountability in medical practice.</p>","a":"<p><strong>Importance of integrity and accountability in medical practice</strong></p>\n<p><strong>Integrity</strong> (honesty, consistency with ethical principles)</p>\n<ol>\n<li>Builds <strong>patient trust</strong>, the basis of the doctor–patient relationship.</li>\n<li>Ensures <strong>honest diagnosis, documentation and certificates</strong>.</li>\n<li>Prevents <strong>exploitation</strong>: unnecessary tests, procedures, kickbacks, conflicts of interest.</li>\n<li>Supports <strong>evidence-based, rational</strong> prescribing.</li>\n<li>Protects <strong>research integrity</strong> (no fabrication or plagiarism).</li>\n<li>Upholds the <strong>reputation</strong> of the profession.</li>\n</ol>\n<p><strong>Accountability</strong> (answerability for decisions and outcomes)</p>\n<ol>\n<li><strong>Patient safety</strong>: errors are reported, learned from and corrected.</li>\n<li><strong>Quality of care</strong> through audit, peer review, clinical governance.</li>\n<li><strong>Legal and ethical compliance</strong> (BMDC code, laws).</li>\n<li><strong>Responsible use of public resources</strong>.</li>\n<li><strong>Public confidence</strong> in health services.</li>\n<li>Encourages <strong>continuous professional development</strong>.</li>\n</ol>\n<p>Together they promote <strong>ethical, safe, trusted</strong> health care.</p>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Man and Medicine).</p>"},{"id":"DU.759","n":759,"part":5,"topic":"Occupational Health","stars":0,"years":["22Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write about maternity benefits of a pregnant woman working in Upazila Health Complex.</p>","a":"<p><strong>Maternity benefits for a pregnant woman working at an Upazila Health Complex</strong></p>\n<p><strong>A. As a government employee</strong></p>\n<ol>\n<li><strong>Maternity leave of 6 months with full pay</strong> (for up to two occasions in service).</li>\n<li><strong>Protection from dismissal</strong> during pregnancy and maternity leave.</li>\n<li>Leave for <strong>antenatal check-ups</strong> as needed; light duties and avoiding hazardous work (heavy lifting, radiation, night duty where possible).</li>\n</ol>\n<p><strong>B. Health care benefits</strong></p>\n<p>Free <strong>ANC</strong>, delivery and PNC at government facilities; Td vaccination, IFA and calcium; screening for complications.</p>\n<p><strong>C. Workplace support</strong></p>\n<ol>\n<li><strong>Breastfeeding corner</strong> and breaks for breastfeeding after return.</li>\n<li><strong>Day-care / crèche</strong> facilities where available.</li>\n<li>Safe, clean toilets and rest area.</li>\n<li>Flexible duty roster during late pregnancy and early return.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Occupational Health; Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.760","n":760,"part":11,"topic":"Communicable Diseases","stars":0,"years":["17Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Write down the importance of period of communicability.</p>","a":"<p><strong>Period of communicability</strong></p>\n<p>The time during which an infectious agent may be transferred directly or indirectly from an infected person (or animal) to another person.</p>\n<p><strong>Importance</strong></p>\n<ol>\n<li>Decides the <strong>duration of isolation</strong> of cases.</li>\n<li>Decides <strong>exclusion</strong> from school, work, food handling.</li>\n<li>Defines the window for <strong>contact tracing</strong>.</li>\n<li>Guides <strong>concurrent disinfection</strong>.</li>\n<li><strong>Treatment shortens it</strong> (TB, syphilis, diphtheria) → early treatment is a control measure.</li>\n<li>Explains spread by <strong>carriers</strong> and pre-symptomatic cases.</li>\n<li>Helps plan <strong>outbreak control</strong> and health education.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Principles of Epidemiology).</p>"},{"id":"DU.761","n":761,"part":8,"topic":"Demography & Fertility","stars":0,"years":["22Nov","17Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>What do you mean by migration? Mention the common causes of migration.</p>","a":"<p><strong>Migration</strong></p>\n<p>The <strong>movement of people from one geographical area to another</strong>, involving a <strong>change of usual residence</strong> (permanent or semi-permanent).</p>\n<p><strong>Common causes</strong></p>\n<table>\n<thead>\n<tr>\n<th>Push factors (from origin)</th>\n<th>Pull factors (to destination)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Poverty, unemployment</strong>, landlessness</td>\n<td><strong>Jobs</strong> (garments, construction), higher wages</td>\n</tr>\n<tr>\n<td><strong>River erosion, floods, cyclones, salinity</strong> (climate change)</td>\n<td><strong>Education</strong> opportunities</td>\n</tr>\n<tr>\n<td>Conflict, persecution, insecurity</td>\n<td>Better <strong>health and urban services</strong></td>\n</tr>\n<tr>\n<td>Lack of services in rural areas</td>\n<td>Family reunion, <strong>marriage</strong></td>\n</tr>\n<tr>\n<td>Social discrimination</td>\n<td>Overseas work (Middle East, Malaysia)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Demography and Family Planning).</p>"},{"id":"DU.762","n":762,"part":8,"topic":"Maternal and Child Health","stars":0,"years":["17Nov"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>GOBI-FFF are the measures for child survival – discuss.</p>","a":"<p><strong>GOBI-FFF: measures for child survival (UNICEF &quot;child survival revolution&quot;, 1980s)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Letter</th>\n<th>Measure</th>\n<th>Contribution to child survival</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>G</strong></td>\n<td><strong>Growth monitoring</strong></td>\n<td>Early detection of growth faltering and malnutrition; guides feeding advice</td>\n</tr>\n<tr>\n<td><strong>O</strong></td>\n<td><strong>Oral rehydration therapy</strong></td>\n<td>Prevents deaths from diarrhoeal dehydration (simple, cheap)</td>\n</tr>\n<tr>\n<td><strong>B</strong></td>\n<td><strong>Breastfeeding</strong></td>\n<td>Nutrition and immunity; fewer infections and deaths</td>\n</tr>\n<tr>\n<td><strong>I</strong></td>\n<td><strong>Immunisation</strong></td>\n<td>Prevents measles, tetanus, pertussis, diphtheria, polio, TB deaths</td>\n</tr>\n<tr>\n<td><strong>F</strong></td>\n<td><strong>Female education</strong></td>\n<td>Better child care, hygiene, nutrition, use of services; lower IMR and fertility</td>\n</tr>\n<tr>\n<td><strong>F</strong></td>\n<td><strong>Family spacing</strong></td>\n<td>Fewer high-risk births; healthier mothers; more care per child</td>\n</tr>\n<tr>\n<td><strong>F</strong></td>\n<td><strong>Food supplementation</strong></td>\n<td>For pregnant women and young children; prevents LBW and PEM (vitamin A, iron)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Discussion</strong></p>\n<ol>\n<li>Simple, <strong>low-cost, high-impact</strong> interventions deliverable through PHC and CHWs.</li>\n<li>Target the main killers (diarrhoea, measles, malnutrition, neonatal causes).</li>\n<li>Address <strong>underlying social causes</strong> (FFF) as well as medical (GOBI).</li>\n<li>Bangladesh's large fall in under-5 deaths reflects ORS, EPI, breastfeeding, female education and family planning.</li>\n<li>Later expanded into IMCI and newborn care packages.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Preventive Medicine in Obstetrics, Paediatrics and Geriatrics).</p>"},{"id":"DU.763","n":763,"part":5,"topic":"Occupational Health","stars":0,"years":["26M","24M","17Ja"],"colleges":"MuMC (2nd Final C2)","asked":"","note":"Also listed in Environmental Health, Part 4","kind":"","sub":"","q":"<p>Define offensive trades with examples. Name / classify the different types of offensive trades.</p>","a":"<p><strong>Offensive trades</strong></p>\n<p>Trades or industries that are <strong>dangerous to health</strong> or create a <strong>nuisance</strong> (offensive smell, smoke, dust, noise, effluents, flies) for the neighbourhood, and therefore need licensing and control.</p>\n<p><strong>Examples</strong></p>\n<p>Slaughter houses; tanneries and leather dressing; bone boiling and crushing; blood drying; fat melting; glue making; soap boiling; tripe cleaning; fish drying; brick kilns; lime burning; manure, rag and bone stores; dairy and poultry farms.</p>\n<p><strong>Classification</strong></p>\n<table>\n<thead>\n<tr>\n<th>By nuisance</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Offensive smell</td>\n<td>Tanneries, slaughter houses, fish drying, bone mills</td>\n</tr>\n<tr>\n<td>Smoke and fumes</td>\n<td>Brick kilns, lime burning</td>\n</tr>\n<tr>\n<td>Dust</td>\n<td>Stone crushing, rice mills, cement works</td>\n</tr>\n<tr>\n<td>Noise</td>\n<td>Saw mills, metal workshops</td>\n</tr>\n<tr>\n<td>Water pollution</td>\n<td>Tannery and dyeing effluents</td>\n</tr>\n<tr>\n<td>Flies and rodents</td>\n<td>Manure stores, poultry farms, rag stores</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Environment and Health).</p>"},{"id":"DU.764","n":764,"part":1,"topic":"Disease Prevention, Control and Eradication","stars":0,"years":["17Ja"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Early diagnosis &amp; treatment is part of prevention – justify the statement.</p>","a":"<p><strong>Early diagnosis and treatment is part of prevention: justification</strong></p>\n<ol>\n<li>It is the <strong>secondary level of prevention</strong> (Leavell and Clark): intervention in the <strong>early pathogenesis</strong> phase.</li>\n<li><strong>Halts the disease process</strong> at an early stage → prevents progression to complications, disability and death.\n<ul>\n<li>Example: treating hypertension prevents <strong>stroke</strong>; treating cervical precancer prevents <strong>invasive cancer</strong>.</li>\n</ul>\n</li>\n<li><strong>Prevents spread</strong> in communicable diseases: treating TB, leprosy, STIs and malaria <strong>shortens the period of communicability</strong> → protects others (acts as <strong>primary prevention for the community</strong>).</li>\n<li><strong>Detects the hidden iceberg</strong> through <strong>screening</strong> (diabetes, cancers).</li>\n<li><strong>Cheaper</strong> than treating advanced disease.</li>\n<li>For diseases without primary prevention (many cancers, diabetes), it is the <strong>main preventive option</strong>.</li>\n<li>Basis of programmes: DOTS, IMCI, cancer screening, NCD corners.</li>\n</ol>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Concept of Health and Disease).</p>"},{"id":"DU.765","n":765,"part":11,"topic":"Non-Communicable Diseases","stars":0,"years":["26M"],"colleges":"","asked":"","note":"","kind":"","sub":"","q":"<p>Describe the natural history of stroke.</p>","a":"<p><strong>Natural history of stroke</strong></p>\n<p><strong>A. Pre-pathogenesis phase (risk factors)</strong></p>\n<p>Agent–host–environment interaction: <strong>hypertension</strong> (most important), diabetes, smoking, dyslipidaemia, obesity, physical inactivity, atrial fibrillation, heart disease, alcohol, age, male sex, family history, high salt intake, stress.</p>\n<p><strong>B. Pathogenesis phase</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Features</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Early (subclinical)</strong></td>\n<td>Atherosclerosis, small-vessel disease, arterial wall damage from hypertension; often silent</td>\n</tr>\n<tr>\n<td><strong>Warning</strong></td>\n<td><strong>Transient ischaemic attack (TIA)</strong>: deficits resolving within 24 hours; high short-term stroke risk</td>\n</tr>\n<tr>\n<td><strong>Onset (acute stroke)</strong></td>\n<td><strong>Ischaemic</strong> (~85%: thrombotic, embolic, lacunar) or <strong>haemorrhagic</strong> (~15%: intracerebral, subarachnoid); sudden weakness, facial droop, speech difficulty, vision loss</td>\n</tr>\n<tr>\n<td><strong>Acute phase</strong></td>\n<td>Brain oedema, raised intracranial pressure, complications (aspiration pneumonia, DVT, bedsores)</td>\n</tr>\n<tr>\n<td><strong>Recovery</strong></td>\n<td>Most recovery in first 3–6 months</td>\n</tr>\n</tbody>\n</table>\n<p><strong>C. Outcomes</strong></p>\n<p>Full recovery; <strong>residual disability</strong> (hemiplegia, aphasia, dysphagia); <strong>recurrent stroke</strong>; vascular dementia; depression; <strong>death</strong> (high case fatality in the first month).</p>\n<p><strong>D. Levels of prevention along the natural history</strong></p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Prevention</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Before risk factors</td>\n<td><strong>Primordial</strong>: healthy diet, activity, no tobacco</td>\n</tr>\n<tr>\n<td>Risk factors present</td>\n<td><strong>Primary</strong>: control BP, diabetes, lipids; stop smoking; anticoagulants for AF</td>\n</tr>\n<tr>\n<td>TIA / acute stroke</td>\n<td><strong>Secondary</strong>: urgent recognition (FAST), thrombolysis, stroke units, antiplatelets, statins</td>\n</tr>\n<tr>\n<td>After stroke</td>\n<td><strong>Tertiary</strong>: rehabilitation (physiotherapy, speech therapy), prevention of recurrence</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Ref:</strong> Park K. Park's Textbook of Preventive and Social Medicine, 28th ed. (Epidemiology of Chronic Non-communicable Diseases).</p>"}];
CM.subs={"5|Occupational Health":["Agricultural Workers","Prevention of Occupational Hazards"],"7|Arthropod Diseases and Control":["Mosquito","House Fly","Sand Fly & Louse Infestation","Fleas and Scabies"],"8|Maternal and Child Health":["High Risk Pregnancy","Pregnancy","Ante Natal Care (ANC)","Postnatal Care","Growth & Development","Breast Feeding and Weaning","MMR & IMR"],"9|Food & Nutrition":["Vitamins","Vitamin A","Vitamin D","Thiamine Deficiency","Mineral Deficiency (Iron + Iodine + Zinc)","Malnutrition & PEM","Lathyrism & Food Adulteration","Milk Borne Diseases","Food Poisoning"],"11|Communicable Diseases":["General","Chickenpox (Varicella-Zoster)","Measles & Mumps","Diphtheria & Pertussis","ARI / Pneumonia","Tuberculosis","Leprosy","Poliomyelitis","Hepatitis","Diarrhoeal Diseases","Helminthic Diseases","Enteric Fever (Typhoid)","Dengue Fever","Malaria & Filariasis","Kala-Azar","Tetanus & Anthrax","Plague","Rabies","Bird Flu","STIs, HIV & AIDS","COVID-19"],"11|Non-Communicable Diseases":["IHD & CHD","Hypertension","Diabetes Mellitus","Rheumatic Fever","Cancer","Geriatric Health Problems"]};
